INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9ef229e5183095770e361905e496a1f2f6c39490a728d735461c70ef97375404', 'AAP 1971-1999 Circ Policies Shapiro PedUrol 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9ef229e5183095770e361905e496a1f2f6c39490a728d735461c70ef97375404.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This article reviews two 1999 policy statements issued by the American Academy of Pediatrics (AAP) concerning pediatric urology. The first policy addresses neonatal circumcision, summarizing research on its medical benefits\u2014such as a reduced risk of urinary tract infections (UTIs) and squamous cell carcinoma\u2014versus potential complications and procedural pain. The AAP concluded that while circumcision offers potential medical benefits, the evidence is insufficient to recommend routine neonatal circumcision, emphasizing informed parental consent and mandatory local anesthesia when performed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ellen Shapiro", "Wiswell"], "organizations": ["American Academy of Pediatrics", "New York University School of Medicine"], "themes": ["Pediatric Urology", "Neonatal Circumcision", "Urinary Tract Infections", "Clinical Practice Guidelines"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a02d87d952e60ede97338cbf074dcc063439364bffcf607e037844de36dd0a98', 'AAP 1975 Circ Policy.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a02d87d952e60ede97338cbf074dcc063439364bffcf607e037844de36dd0a98.pdf', 'policy_guideline', 'ingested', '{"date": "1975", "description": "This text provides a copyright disclaimer and usage policy for the journal Pediatrics, owned by the American Academy of Pediatrics. It outlines the restrictions regarding the unauthorized redistribution, copying, or posting of journal content, while granting permission for individual users to print, download, or email articles for personal use.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["American Academy of Pediatrics"], "themes": ["Copyright and Terms of Use", "Intellectual Property", "Article Distribution Permissions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('49760469cf9b5417712c9f0e46e599d9a225ee129c830c7820c9d2f0d5a41d37', 'AAP 1988 Bioethics Religious Exemptions Child Abuse Statutes.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/49760469cf9b5417712c9f0e46e599d9a225ee129c830c7820c9d2f0d5a41d37.pdf', 'policy_guideline', 'ingested', '{"date": "1988", "description": "This policy statement by the American Academy of Pediatrics (AAP) Committee on Bioethics addresses cases where children suffer severe disability or death because parents withhold standard medical treatment due to religious beliefs. The document notes that widespread religious exemption clauses in state child abuse statutes prevent proper legal recourse and fail to protect vulnerable children from medical neglect.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Norman C. Fost", "William G. Bartholome", "William Reed Bell", "Alan R. Fleischman", "Arthur F. Kohrman", "William B. Weil, Jr.", "Kenneth J. Ryan", "Anthony Shaw"], "organizations": ["American Academy of Pediatrics", "Committee on Bioethics", "Council on Child and Adolescent Health"], "themes": ["Religious Exemptions", "Child Abuse and Medical Neglect", "Faith Healing", "Children''s Rights", "Bioethics", "Legal and Constitutional Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5c5475f87bd56ab7cfa6cd657dcd68b889cb138a44913807ec96bdc0cc09abce', 'AAP 1989 Circ Policy AAP News.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5c5475f87bd56ab7cfa6cd657dcd68b889cb138a44913807ec96bdc0cc09abce.pdf', 'policy_guideline', 'ingested', '{"date": "1989", "description": "This report from the American Academy of Pediatrics (AAP) Task Force on Circumcision reassesses the medical evidence surrounding neonatal circumcision, updating the AAP''s previous 1971 and 1975 stances that found no absolute medical indications for the routine procedure. Drawing on updated research, the Task Force identifies potential medical benefits, including the prevention of phimosis, paraphimosis, and balanoposthitis, a significant decrease in penile cancer incidence, and potential reductions in infant urinary tract infections, while finding evidence linking circumcision to sexually transmitted disease prevention inconclusive.\n\nThe report emphasizes that newborn circumcision is generally safe when performed by skilled operators on healthy, stable infants, though it carries minor risks such as local infection, bleeding, and transient procedural pain. It reviews pain management options like dorsal penile nerve blocks and outlines contraindications such as prematurity, systemic illness, or genital anomalies. The Task Force concludes that because the elective procedure carries both distinct benefits and potential risks, clinicians must provide comprehensive explanations to parents to ensure informed consent based on medical, religious, cultural, and personal considerations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Edgar J. Schoen", "Glen Anderson", "Constance Bohon", "Frank Hinman Jr.", "Ronald L. Poland", "E. Maurice Wakeman"], "organizations": ["American Academy of Pediatrics", "American College of Obstetrics and Gynecology"], "themes": ["Neonatal Circumcision", "Infant Health and Preventive Medicine", "Urinary Tract Infections", "Penile and Cervical Carcinoma", "Neonatal Pain and Anesthesia", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d0176d05e17749d9180f622fd2d00dea0ea135e52469f4cd311f7e92f25c1d7d', 'AAP 1989 Circ Policy.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d0176d05e17749d9180f622fd2d00dea0ea135e52469f4cd311f7e92f25c1d7d.pdf', 'policy_guideline', 'ingested', '{"date": "1989", "description": "This report by the American Academy of Pediatrics (AAP) Task Force on Circumcision reviews the medical evidence surrounding neonatal circumcision, modifying its previous 1975 stance that found no absolute medical indications for the routine procedure. The report outlines potential benefits, including the prevention of phimosis, paraphimosis, and balanoposthitis, alongside evidence indicating reduced risks of penile cancer and infant urinary tract infections. However, it also highlights potential surgical risks, the physiological pain experienced by neonates, and inconclusive evidence regarding sexually transmitted diseases.\n\nThe Task Force concludes that newborn circumcision is an elective surgical procedure carrying both potential advantages and risks. It evaluates surgical techniques, complications, and the use of dorsal penile nerve blocks for pain relief, recommending that parents receive comprehensive, unbiased information about the risks and benefits to provide fully informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Edgar J. Schoen", "Glen Anderson", "Constance Bohon", "Frank Hinman, Jr.", "Ronald L. Poland", "E. Maurice Wakeman"], "organizations": ["American Academy of Pediatrics", "American College of Obstetrics and Gynecology"], "themes": ["Neonatal Circumcision", "Pediatric Preventive Medicine", "Informed Consent", "Urinary Tract Infections", "Penile and Cervical Cancer", "Neonatal Pain and Anesthesia"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('00fcc8647fbc1fc35f5d1f9002786b0dcfcd51602bdce306c2651b7d728514b2', 'AAP 1995 Bioethics Proxy Consent.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/00fcc8647fbc1fc35f5d1f9002786b0dcfcd51602bdce306c2651b7d728514b2.pdf', 'policy_guideline', 'ingested', '{"date": "1995-02-01", "description": "This policy statement from the American Academy of Pediatrics (AAP) Committee on Bioethics addresses the ethical and legal limitations of traditional informed consent in pediatric medicine. It argues that because minor children lack formal legal empowerment and often full decisional capacity, the standard paradigm of adult informed consent is largely inapplicable. Instead, the Academy proposes a framework consisting of informed ''parental permission'' combined with the developmentally appropriate ''assent'' of the pediatric patient.\n\nThe statement highlights the necessity of shared decision-making among physicians, parents, and young patients, encouraging healthcare providers to actively involve children in discussions according to their cognitive maturity. It emphasizes honoring patient dissent when interventions are non-essential, outlines ethical conflict resolution mechanisms, and discusses special circumstances such as mature or emancipated minors who possess the legal capacity to give independent consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["William G. Bartholome", "Arthur Kohrman", "Ellen Wright Clayton", "Joel E. Frader", "Michael A. Grodin", "Kathryn L. Moseley", "Ian H. Porter", "Virginia M. Wagner", "Rebecca Dresser"], "organizations": ["American Academy of Pediatrics", "AAP Committee on Bioethics", "Council on Child and Adolescent Health", "American College of Obstetricians and Gynecologists", "Canadian Paediatric Society"], "themes": ["Informed Consent", "Parental Permission", "Pediatric Assent", "Bioethics", "Patient Autonomy", "Adolescent Healthcare Rights", "Shared Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f0584809525169418049633b1515cbe3eef712c50c7f3e3d7566f37c6fe3794', 'AAP 1999 Circ_Policy.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8f0584809525169418049633b1515cbe3eef712c50c7f3e3d7566f37c6fe3794.pdf', 'policy_guideline', 'ingested', '{"date": "1999", "description": "This policy statement from the American Academy of Pediatrics (AAP) Task Force on Circumcision assesses the medical, legal, and ethical evidence regarding routine neonatal male circumcision. The report finds that while circumcision offers potential medical benefits\u2014including a moderately reduced risk of urinary tract infections, penile cancer, and certain sexually transmitted infections\u2014the absolute risk of these conditions is low. The Task Force concluded that existing scientific data are insufficient to recommend routine circumcision for all newborn male infants.\n\nBecause circumcision is an elective surgical procedure carrying inherent risks and complications, the statement recommends that parents make the final decision in the best interest of their child after receiving accurate, unbiased information. Furthermore, because infants demonstrably experience significant physiologic pain and stress during the procedure, the AAP strongly recommends that safe and effective procedural analgesia\u2014such as a subcutaneous ring block, dorsal penile nerve block, or EMLA cream\u2014be administered whenever neonatal circumcision is performed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Carole M. Lannon", "Ann Geryl Doll Bailey", "Alan R. Fleischman", "George W. Kaplan", "Craig T. Shoemaker", "Jack T. Swanson", "Donald Coustan"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "National Center for Health Statistics", "Australian College of Paediatrics", "Canadian Paediatric Society"], "themes": ["Neonatal Circumcision", "Procedural Analgesia and Pain Management", "Informed Consent and Parental Autonomy", "Urinary Tract Infections", "Penile Cancer Prevention", "Preventive Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d485eb8373da7cb708c84db6a7c733194b5d9a2c88f393fb239321f63f682bbb', 'AAP 2010 FGM Policy Retired.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d485eb8373da7cb708c84db6a7c733194b5d9a2c88f393fb239321f63f682bbb.pdf', 'policy_guideline', 'ingested', '{"date": "2010", "description": "This policy statement from the American Academy of Pediatrics (AAP) addresses the practice of female genital cutting (FGC) or female genital mutilation among female infants, children, and adolescents. The AAP emphasizes that the procedure poses significant, potentially life-threatening physical and psychological risks to children and women, and it formally opposes all forms of the practice that risk harm.\n\nThe document counsels pediatricians and pediatric surgical specialists against performing these procedures and urges them to actively dissuade families from pursuing them. It advises healthcare providers to offer compassionate education regarding the harms associated with FGC while remaining sensitive to the cultural and religious motivations of immigrant families seeking the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["American Academy of Pediatrics", "Committee on Bioethics"], "themes": ["Female Genital Cutting (FGC)", "Child Health and Protection", "Medical Ethics", "Cultural Sensitivity in Healthcare", "Pediatric Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('58b82dfe54606b8333bd1b9944d64c97124c05c8bc76831345cfe979fcdc3939', 'AAP 2010 FGM Proposal _in NYT_.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/58b82dfe54606b8333bd1b9944d64c97124c05c8bc76831345cfe979fcdc3939.pdf', 'newspaper_clipping', 'ingested', '{"date": "2010-05-06", "description": "This document covers the controversy surrounding a 2010 policy statement by the American Academy of Pediatrics (AAP), which suggested permitting pediatricians to perform a ceremonial pinprick or ''ritual nick'' on girls'' genitalia as a harm-reduction compromise to deter families from sending girls overseas for severe female genital mutilation (FGM). The proposal faced intense condemnation from human rights groups like Equality Now, advocacy organizations such as Intact America, and lawmakers including Representative Joseph Crowley, who argued that any form of FGM violates bodily integrity, creates a dangerous slippery slope, and undermines global progress against gender-based violence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Pam Belluck", "Joseph Crowley", "Georganne Chapin", "Lainie Friedman Ross", "Mary Bono Mack", "Taina Bien-Aime", "Lakshmi Anantnarayan"], "organizations": ["The New York Times", "American Academy of Pediatrics", "Equality Now", "Intact America", "MacLean Center for Clinical Medical Ethics at the University of Chicago", "American Congress of Obstetricians and Gynecologists", "World Health Organization", "International Federation of Gynecology and Obstetrics", "U.S. Department of Health and Human Services"], "themes": ["Female Genital Mutilation (FGM)", "Medical Ethics and Harm Reduction", "Human Rights and Bodily Integrity", "Cultural Sensitivity vs. Universal Rights", "Health Law and Child Welfare Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('30d1c5941048dc14ad55a7ad988202ae0adac5c4d8a0ea08fec7995eaf3e82ec', 'AAP 2010 FGM Proposal.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/30d1c5941048dc14ad55a7ad988202ae0adac5c4d8a0ea08fec7995eaf3e82ec.pdf', 'policy_guideline', 'ingested', '{"date": "2010-04-26", "description": "This policy statement from the American Academy of Pediatrics (AAP) Committee on Bioethics addresses the practice of ritual genital cutting of female minors (female genital cutting/FGC). The AAP opposes all forms of FGC that risk physical or psychological harm, advising pediatricians to decline requests to perform them, counsel families about the health consequences, and actively seek to dissuade them from pursuing the practice. The statement details the four clinical classifications of FGC, outlines both acute and chronic medical complications, and examines the cultural and religious factors motivating families.\n\nWhile reiterating that nonmedical genital alterations on female minors are illegal under U.S. federal law and constitute child abuse, the policy discusses the ethical debate surrounding whether permitting a harmless ceremonial ''ritual nick'' could serve as a harm-reduction measure to prevent girls from undergoing severe procedures abroad. Ultimately, the AAP stresses the primacy of child protection and nonmaleficence, recommending compassionate, culturally sensitive education to eliminate the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Douglas S. Diekema", "Dena S. Davis", "Armand H. Matheny Antommaria", "Mary E. Fallat", "Ian R. Holzman", "Steven R. Leuthner", "Lainie F. Ross", "Sally Webb"], "organizations": ["American Academy of Pediatrics", "World Health Organization", "International Federation of Gynecology and Obstetrics", "American College of Obstetricians and Gynecologists", "American Medical Association"], "themes": ["Female Genital Cutting (FGC)", "Pediatric Bioethics", "Child Protection and Legal Constraints", "Cultural Relativism vs. Human Rights", "Harm Reduction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d6bf382c3e6a364989ad75141ee0d3200582e0c3fb0abf730e27fbfa5b20ed67', 'AAP 2010 ltr to IA re FGM Proposal.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d6bf382c3e6a364989ad75141ee0d3200582e0c3fb0abf730e27fbfa5b20ed67.pdf', 'letter', 'ingested', '{"date": "2010-06-02", "description": "This letter, dated June 2, 2010, from the American Academy of Pediatrics (AAP) to Intact America, announces the formal retraction and retirement of the AAP''s 2010 policy statement on female genital cutting (FGC). The AAP reaffirms its unequivocal opposition to all forms of FGC, warning of severe physical and psychological consequences and counseling pediatricians not to perform such procedures.\n\nThe letter explicitly clarifies that the AAP does not endorse the concept of a ''clitoral nick,'' emphasizing that the procedure is illegal under federal law. Statements from AAP President Judith S. Palfrey underscore the organization''s commitment to child protection and the global eradication of female genital mutilation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Georganne Chapin", "Judith S. Palfrey", "Errol R. Alden", "C. Marion Burton", "David T. Tayloe, Jr."], "organizations": ["American Academy of Pediatrics", "Intact America"], "themes": ["Female Genital Cutting", "Pediatric Health Policy", "Child Protection", "Medical Ethics", "Federal Law Compliance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1bc7cdc1f59a8a58e69c089e650c5e8ff64ba3fa66e541c5df821bf0de7c3559', 'AAP 2012 Analysis VanHowe.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1bc7cdc1f59a8a58e69c089e650c5e8ff64ba3fa66e541c5df821bf0de7c3559.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "In this extensive commentary, Dr. Robert S. Van Howe delivers a statement-by-statement critique of the 2012 American Academy of Pediatrics (AAP) Task Force Report on Circumcision. Van Howe argues that the Task Force operated with a predetermined agenda and substantial bias, employing a selective bibliography and improper evidence-evaluation methodology while neglecting the normal anatomy, histology, and sexual function of the foreskin. He asserts that the Task Force failed to adequately weigh complications, disregarded fundamental bioethical principles regarding infant bodily integrity, and inappropriately favored parental proxy decision-making for a non-therapeutic, elective cosmetic procedure driven by professional financial reimbursement.\n\nVan Howe challenges the AAP''s epidemiological and prophylactic claims regarding sexually transmitted infections (STIs), HIV, and urinary tract infections, arguing that the Task Force uncritically applied flawed African randomized controlled trial data that do not translate to North American populations. He emphasizes that alternative, non-surgical approaches such as education, condom use, and HPV vaccination are more effective and far less invasive, noting that international medical societies have consistently rejected the AAP''s conclusions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "Douglas Diekema"], "organizations": ["American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Central Michigan University College of Medicine", "American Academy of Family Physicians", "American College of Obstetricians and Gynecologists", "American Heart Association"], "themes": ["Neonatal Circumcision", "Medical Ethics and Informed Consent", "Critique of Clinical Practice Guidelines", "Foreskin Anatomy and Function", "Methodological Bias in Evidence-Based Medicine", "Healthcare Financing and Third-Party Reimbursement"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6cff6b3588a227c38a04acb856b8f73f7e8ce268129621e813bc7f58b557de86', 'AAP 2012 Circ Policy expired.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6cff6b3588a227c38a04acb856b8f73f7e8ce268129621e813bc7f58b557de86.pdf', 'policy_guideline', 'ingested', '{"date": "2012-09", "description": "This policy statement from the American Academy of Pediatrics (AAP) presents an updated evaluation of elective newborn male circumcision based on peer-reviewed literature from 1995 to 2010. The AAP concludes that the preventive health benefits\u2014including reduced risks of urinary tract infections, penile cancer, and transmission of certain sexually transmitted infections such as HIV\u2014outweigh the risks of the procedure when performed by trained professionals under sterile conditions with appropriate pain management.\n\nWhile the health benefits are significant enough to warrant third-party insurance coverage and justify access for families who choose it, they are not sufficient to recommend routine universal circumcision. The policy emphasizes that clinicians must inform parents of the risks and benefits in an unbiased manner, allowing parents to determine the best interests of their child within their cultural, ethical, and religious contexts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Susan Blank", "Michael Brady", "Ellen Buerk", "Waldemar Carlo", "Douglas Diekema", "Andrew Freedman", "Lynne Maxwell", "Steven Wegner", "Charles LeBaron", "Lesley Atwood", "Sabrina Craigo", "Susan K. Flinn", "Esther C. Janowsky", "Edward P. Zimmerman"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Centers for Disease Control and Prevention", "American Academy of Family Physicians"], "themes": ["Newborn Male Circumcision", "Preventive Health Benefits", "Informed Parental Consent and Decision-Making", "Sexually Transmitted Infection and HIV Prevention", "Medical Ethics and Health Care Financing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('51afc1854ca5ff86d8ff258e5c81d3f0805bf176584c95a0b83d7af39e08f77f', 'AAP 2012 Circ Tech Report expired.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/51afc1854ca5ff86d8ff258e5c81d3f0805bf176584c95a0b83d7af39e08f77f.pdf', 'policy_guideline', 'ingested', '{"date": "2012", "description": "This technical report by the American Academy of Pediatrics (AAP) Task Force on Circumcision provides an updated, evidence-based evaluation of newborn male circumcision. The Task Force concluded that the preventive and health benefits of newborn male circumcision outweigh the procedural risks, justifying access and third-party reimbursement for families who choose it. Demonstrated benefits include significant risk reduction for urinary tract infections, heterosexually acquired HIV, human papillomavirus (HPV), herpes simplex virus type 2 (HSV-2), and penile cancer, with no demonstrated adverse impact on sexual function or satisfaction.\n\nThe report emphasizes the central role of nonbiased, factually accurate clinician counseling provided early in pregnancy so parents can weigh clinical evidence alongside religious, cultural, and personal preferences. When performed, the elective procedure must be conducted by well-trained practitioners using sterile techniques and effective multimodal procedural analgesia, as untrained providers and inadequate pain management account for avoidable risks and complications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Susan Blank", "Michael Brady", "Ellen Buerk", "Waldemar Carlo", "Douglas Diekema", "Andrew Freedman", "Lynne Maxwell", "Steven Wegner", "Charles LeBaron", "Lesley Atwood", "Sabrina Craigo"], "organizations": ["American Academy of Pediatrics", "American Academy of Family Physicians", "American College of Obstetricians and Gynecologists", "Centers for Disease Control and Prevention", "American Heart Association", "American Society of Anesthesiologists", "American College of Nurse Midwives"], "themes": ["Male Circumcision", "Newborn and Infant Health", "Sexually Transmitted Infection Prevention", "Procedural Analgesia and Pain Management", "Parental Decision-Making and Informed Consent", "Healthcare Financing and Reimbursement"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('088ab7351f61bf1dae82c8eaa7ce50283c220aad18bc6ebab3213e6ac4b5411e', 'AAP 2012 Critique Frisch.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/088ab7351f61bf1dae82c8eaa7ce50283c220aad18bc6ebab3213e6ac4b5411e.pdf', 'medical_journal', 'ingested', '{"date": "2013-03-18", "description": "This commentary, authored by a coalition of European and international pediatric specialists, critiques the American Academy of Pediatrics'' (AAP) 2012 Technical Report and Policy Statement on infant male circumcision. The authors argue that the AAP''s assertion\u2014that the health benefits of neonatal circumcision outweigh the risks\u2014stems from cultural bias prevalent in the United States rather than robust scientific objectivity. They evaluate the AAP''s key clinical justifications (prevention of urinary tract infections, penile cancer, traditional sexually transmitted diseases, and HIV/AIDS) and conclude that these claims either lack relevance in Western contexts, are offset by less intrusive preventive methods, or fail to meet the ethical criteria required for nontherapeutic surgery on non-consenting minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Yves Aigrain", "Vidmantas Barauskas", "Ragnar Bjarnason", "Su-Anna Boddy", "Noni MacDonald"], "organizations": ["American Academy of Pediatrics", "Statens Serum Institut", "Aalborg University", "Royal College of Surgeons of England", "German Academy of Paediatrics and Adolescent Medicine", "World Health Organization"], "themes": ["Male Circumcision", "Medical Ethics and Bodily Integrity", "Cultural Bias in Clinical Policy", "Pediatric Preventive Medicine", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6802904b398ca424b7f7b12cbaf6c8a3f7eadf625de7a888188148731910b1db', 'AAP 2012 Freedman Fleshing Out Change On Circumcision JewishWeek.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6802904b398ca424b7f7b12cbaf6c8a3f7eadf625de7a888188148731910b1db.pdf', 'newspaper_clipping', 'ingested', '{"date": "2012-09-19", "description": "This article is an interview conducted by Ted Merwin with Dr. Andrew Freedman, a pediatric urologist and member of the American Academy of Pediatrics (AAP) task force on circumcision. Dr. Freedman explains the rationale behind the AAP''s updated policy statement, which shifted from neutrality to recognizing that the health benefits of circumcision, such as modest reductions in HIV transmission and penile cancer risk, outweigh the risks, warranting insurance coverage.\n\nDespite the qualified endorsement, Dr. Freedman emphasizes that the AAP does not universally advocate circumcision, affirming that decisions should ultimately respect family values, religious beliefs, and cultural traditions. He also notes broader cultural shifts, ethical debates surrounding bodily integrity, declining circumcision rates in the United States, and the task force''s decision not to formally address the practice of metzitzah b''peh.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Ted Merwin", "Dr. Andrew Freedman"], "organizations": ["The Jewish Week", "American Academy of Pediatrics", "Cedars-Sinai Medical Center"], "themes": ["Circumcision", "Pediatric Medicine", "Public Health Policy", "Medical Ethics", "Religious Traditions", "Health Insurance Coverage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a17fc87b2bdbfc26c2ee70fb3871da3316e5a9189d3650c9740ade70b2126c20', 'AAP 2012 Reply to Critique Frisch.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a17fc87b2bdbfc26c2ee70fb3871da3316e5a9189d3650c9740ade70b2126c20.pdf', 'medical_journal', 'ingested', '{"date": "2013-03-18", "description": "This article is a formal response from the American Academy of Pediatrics (AAP) Task Force on Circumcision to critiques raised by Frisch et al. regarding the AAP''s 2012 policy on male circumcision. The Task Force refutes accusations of cultural bias, arguing that its evaluation of evidence was systematic, objective, and transparent, whereas European critics demonstrate their own normative biases against the procedure. The authors address specific criticisms regarding evidence of urinary tract infection prevention, HIV risk reduction, and anatomical or sexual complications, pointing out methodology flaws in studies that claim circumcision impairs sexual function or sensation.\n\nAdditionally, the Task Force defends the timing of neonatal circumcision, emphasizing epidemiological data that show significant risks of sexually transmitted infections and HIV transmission among adolescents before legal age of consent. Addressing ethical dilemmas of bodily integrity versus parental rights, the authors argue that when clear preventive medical benefits exist, inaction can also cause harm. Consequently, the decision is ethically and appropriately left to informed parents rather than restricted entirely.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Susan Blank", "Douglas S. Diekema", "Michael Brady", "Ellen Buerk", "Waldemar Carlo", "Andrew Freedman", "Lynne Maxwell", "Steven Wegner", "Morten Frisch"], "organizations": ["American Academy of Pediatrics", "AAP Task Force on Circumcision", "World Health Organization", "Centers for Disease Control and Prevention", "American Academy of Family Physicians", "American College of Obstetricians and Gynecologists"], "themes": ["Male Circumcision", "Cultural Bias in Clinical Guidelines", "HIV and STI Prevention", "Medical Ethics and Bodily Integrity", "Parental Decision-Making", "Sexual Function and Sensitivity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b1e1c263b226c098e361476a89db126461c5161c2a84c43c652ab687b24dbcda', 'AAP 2022 Ped Pt Educ Circ.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b1e1c263b226c098e361476a89db126461c5161c2a84c43c652ab687b24dbcda.pdf', 'policy_guideline', 'ingested', '{"date": "2022", "description": "This patient education document from the American Academy of Pediatrics outlines essential information for parents considering newborn male circumcision. It details the surgical procedure, safety requirements, and postoperative care, noting that pain management should be provided. Furthermore, it discusses the reasons parents choose or decline the procedure, highlighting that scientific evidence shows health benefits\u2014such as reduced risks of UTIs, penile cancer, and sexually transmitted infections including HIV\u2014outweigh risks, while also addressing cultural, religious, and personal viewpoints.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["American Academy of Pediatrics"], "themes": ["Newborn Circumcision", "Pediatric Health", "Informed Consent", "Infection Prevention", "Parental Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f5111c9a5e3e3efe6f3a9ac07dd948305489e0ab9c1fc56ccf13ef5fb5ebe9f5', 'Aaron New Legal Standard for Medical Malpractice JAMA 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f5111c9a5e3e3efe6f3a9ac07dd948305489e0ab9c1fc56ccf13ef5fb5ebe9f5.pdf', 'medical_journal', 'ingested', '{"date": "2025-02-26", "description": "This article discusses the American Law Institute''s (ALI) approval of its first-ever restatement of the law of medical malpractice, the Restatement (Third) of Torts: Medical Malpractice, approved in May 2024. The new legal framework marks a significant shift from the traditional reliance on customary professional practice toward a modern, patient-centered standard of ''reasonable medical care'' defined by competence under comparable circumstances. This standard empowers courts and juries to consider contemporary scientific evidence and clinical practice guidelines rather than outdated local customs.\n\nThe authors analyze the implications of the restatement across clinical care, informed consent, candid physician-patient communication after adverse events, and healthcare organizational liability. By allowing adherence to authoritative guidelines to serve as evidence against negligence and modernizing rules surrounding communication and informed consent, the restatement aims to align tort law with modern medical ethics, mitigate unproductive defensive medicine, and encourage healthcare systems to prioritize patient safety over courtroom defense.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Daniel G. Aaron", "Christopher T. Robertson", "Louise P. King", "William M. Sage", "Learned Hand"], "organizations": ["American Law Institute", "American Medical Association", "World Medical Association", "Boston University", "Harvard Medical School", "University of Utah", "Texas A&M University", "University of Michigan"], "themes": ["Medical Malpractice", "Standard of Care", "Evidence-Based Medicine", "Tort Reform", "Defensive Medicine", "Informed Consent", "Patient Safety"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ff48ebbb28bcb4c6021f59d4819fc7ca0c2ba9b35753b3366dc2467dcd8a6b50', 'Abara Prepuce health Canada Can Urol Assoc 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ff48ebbb28bcb4c6021f59d4819fc7ca0c2ba9b35753b3366dc2467dcd8a6b50.pdf', 'medical_journal', 'ingested', '{"date": "2017-01", "description": "This academic review examines the anatomical development, health, and care of the prepuce (foreskin) alongside the practice of neonatal and childhood circumcision within Canada. Following the delisting of routine circumcision from provincial health insurance plans, prevalence rates have declined, meaning the majority of Canadian males live with an intact prepuce. The article details conservative management options for common conditions such as physiological and pathological phimosis, balanitis, and balanitis xerotica obliterans (BXO), emphasizing basic penile hygiene and topical steroid treatments before surgical intervention is considered.\n\nThe author reviews the indications, contraindications, techniques, anesthesia methods, and complication rates of childhood circumcision, noting that neonatal procedures carry lower costs and risks compared to surgeries performed later in life. Emphasizing the importance of informed parental consent and culturally sensitive dialogue, the report calls for structured provider training, standardized reporting of adverse events, and comprehensive parental education to optimize preputial care and ensure safety when circumcision is chosen.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Emmanuel O. Abara", "Douglas Gairdner"], "organizations": ["Canadian Urological Association", "Northern Ontario Medical School", "Canadian Paediatric Society", "American Academy of Pediatrics", "World Health Organization", "UNAIDS", "Richmond Hill Urology Practice and Prostate Institute"], "themes": ["Neonatal and Childhood Circumcision", "Prepuce Health and Anatomy", "Phimosis and Balanitis Xerotica Obliterans", "Informed Consent and Parental Education", "Canadian Healthcare Policy and Circumcision Prevalence", "Surgical Complications and Provider Training"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1b3e964faebbfce7f24dab25dd85c331746bf3712d1935e92ad8a387f6e68bb0', 'Abd el Salam Importance GenMutil Power Al Raida 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1b3e964faebbfce7f24dab25dd85c331746bf3712d1935e92ad8a387f6e68bb0.pdf', 'other', 'ingested', '{"date": "2002", "description": "This article examines male genital mutilation (MGM) and female genital mutilation (FGM) through the lens of patriarchal gender power politics, rather than merely viewing them as cultural rites of passage or purification. Based on a qualitative study conducted between 1999 and 2000 involving 23 Egyptian intellectuals who opposed FGM but remained tolerant toward MGM, the author argues that MGM remains a muted yet critical gender issue.\n\nThe text outlines the anatomical and physiological consequences of both procedures, noting that both involve removing sensitive, functional genital tissues and carry severe physical and psychological risks. Furthermore, it explores the cultural and social origins of these practices, linking FGM to patriarchal desires to police female chastity and patrilineal inheritance, while analyzing theories that attribute MGM to gender hierarchy, male rivalry, and symbolic identification with female fertility.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Seham Abd El Salam", "Nahid Toubia", "Marie Assaad", "Efua Dorkenoo"], "organizations": ["NOHARMM"], "themes": ["Male Genital Mutilation", "Female Genital Mutilation", "Gender Power Politics", "Patriarchy", "Circumcision", "Human Rights and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eeaffc9f150d3851eba002d5a501e0c45276a421260d06df214931ccb81d49de', 'Aboneka Boy Circumcision Uganda Monitor 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eeaffc9f150d3851eba002d5a501e0c45276a421260d06df214931ccb81d49de.pdf', 'newspaper_clipping', 'ingested', '{"date": "2024-05-08", "description": "This commentary piece by Michael Aboneka argues that the practice of forceful and harmful circumcision constitutes a severe violation of the fundamental human rights of young boys. Published as an op-ed, the article advocates for the protection of the boy child against non-consensual and dangerous traditional or forced circumcision practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Michael Aboneka"], "organizations": ["Daily Monitor"], "themes": ["Child Rights", "Circumcision", "Human Rights Violations", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9c6aaaea1d8954f5c859b5a6f55047e7160e920213106cbd775a4729e4a12e14', 'Acimi Prevalence Meatal Stenosis JPedUrol 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9c6aaaea1d8954f5c859b5a6f55047e7160e920213106cbd775a4729e4a12e14.pdf', 'medical_journal', 'ingested', '{"date": "2021-10-11", "description": "This prospective cross-sectional study investigates the prevalence and etiologic factors of meatal stenosis in 1,031 circumcised schoolboys aged 5 to 8 years in Algeria. The screening identified meatal stenosis in 185 boys, establishing an overall prevalence of 17.9%, with the majority exhibiting membrane stenosis obstructing the lower urethral meatus.\n\nMultivariate statistical analysis revealed significant risk factors associated with meatal stenosis, including circumcision performed during the first week of life, forceful prepuce retraction in cases of complete foreskin adhesion to the glans, and the postoperative use of specific healing products (such as Beta-sitosterol and Centella Asiatica). The authors conclude that meatal stenosis is a frequent post-circumcision complication and emphasize cautious surgical technique and post-procedure care.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Smail Acimi", "Naima Abderrahmane", "Lamia Debbous", "Nacim Bouziani", "Juba Mohammed Mansouri", "Mohammed Ali Acimi", "Youcef Boukhari", "Naziha Hadjeb", "Aboubakr Essedik Yazi"], "organizations": ["Journal of Pediatric Urology", "Elsevier", "Children''s Hospital Canastel", "University of Oran", "EHU of Oran", "CHU of Sidi Bel Abbes", "University of Sidi Bel Abbes", "American Academy of Pediatrics"], "themes": ["Pediatric Urology", "Circumcision Complications", "Meatal Stenosis", "Postoperative Risk Factors", "Surgical Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('415710d22210538f132720faeb2e83300949781aa6fffb06f1692df9b2410159', 'Adler Circumcision Fraud CornellLaw&PubPolicy 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/415710d22210538f132720faeb2e83300949781aa6fffb06f1692df9b2410159.pdf', 'legal_document', 'ingested', '{"date": "2020", "description": "This article argues that non-therapeutic male circumcision, or male genital cutting (MGC), performed on healthy infant boys is not only unlawful under U.S. law but also constitutes a multi-billion-dollar constructive and intentional fraud. The authors argue that the practice amounts to battery, criminal child abuse, and a breach of physicians'' fiduciary duties, violating children''s fundamental common law and constitutional rights to bodily integrity and self-determination. They contend that parents lack the legal authority to consent to medically unnecessary genital amputation on behalf of their children, drawing parallels to adult cases of unnecessary surgery and prohibitions against female genital cutting.\n\nFurthermore, the authors accuse the American Academy of Pediatrics (AAP) and medical practitioners of perpetuating intentional fraud and Medicaid fraud. They allege that medical authorities have historically fabricated and exaggerated medical justifications while omitting substantial risks, functions of the prepuce, and ethical controversies to preserve industry revenues and secure third-party Medicaid reimbursement for unnecessary procedures. Consequently, the article asserts that circumcised males, parents, and state governments have viable causes of action that expose practitioners, hospitals, and medical trade associations to significant liability.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Peter W. Adler", "Robert Van Howe", "Travis Wisdom", "Felix Daase", "Douglas Gairdner", "Matthew Giannetti", "Michael Brady"], "organizations": ["American Academy of Pediatrics", "American Medical Association", "American College of Obstetricians and Gynecologists", "Medicaid", "Cornell Journal of Law and Public Policy"], "themes": ["Non-Therapeutic Male Circumcision", "Medical Malpractice and Unnecessary Surgery", "Constructive and Intentional Fraud", "Medicaid Fraud", "Bodily Integrity and Human Rights", "Informed Consent and Pediatric Ethics", "Child Abuse and Battery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5bbe55f1e76da350889f776d687003eb56f6c859fab2813d8f68044e2a1cf856', 'Adler Lawful-medicaid-circumcision JLM 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5bbe55f1e76da350889f776d687003eb56f6c859fab2813d8f68044e2a1cf856.pdf', 'legal_document', 'ingested', '{"date": "2011", "description": "This article examines whether it is lawful under United States federal and state law for Medicaid to fund routine, non-therapeutic infant circumcision. The author argues that Medicaid coverage of the procedure is not a discretionary policy choice but a violation of governing law, because Medicaid statutes explicitly mandate that funding be restricted solely to medically necessary treatments for diagnosed conditions. Since major medical associations concede that infant circumcision is elective, non-therapeutic, and performed primarily for cultural, social, or religious reasons on healthy anatomy, it does not meet statutory definitions of medical necessity.\n\nAdditionally, the article asserts that performing and billing routine circumcision under Medicaid misallocates billions of taxpayer dollars and subjects physicians and hospitals to severe liability under federal and state False Claims Acts. The author calls on the federal government and remaining states that cover the procedure to immediately enforce statutory requirements, eliminate Medicaid funding for routine neonatal circumcision, and recoup improper payments.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Peter W Adler", "Petrina Fadel", "Robert S. Van Howe", "Dan Bollinger"], "organizations": ["Medicaid", "Attorneys for the Rights of the Child", "American Academy of Pediatrics", "American Medical Association", "Canadian Paediatric Society", "Doctors Opposing Circumcision"], "themes": ["Medicaid Law and Compliance", "Infant Circumcision", "Medical Necessity Standards", "False Claims Act and Healthcare Fraud", "Elective and Cosmetic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('be2bd5570f67870b56390838dafe6bd7050fde3437bc87c6be8dffe439e0139f', 'Adler-CDC-2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/be2bd5570f67870b56390838dafe6bd7050fde3437bc87c6be8dffe439e0139f.pdf', 'other', 'ingested', '{"date": "2016", "description": "In this article, author Peter W. Adler critically examines the draft circumcision recommendations issued by the Centers for Disease Control and Prevention (CDC) in December 2014. Adler argues that the CDC''s proposed recommendations\u2014which encourage clinicians to advise parents and sexually active males that the medical benefits of non-therapeutic male circumcision outweigh its risks and that Medicaid should cover the procedure\u2014are scientifically untenable, ethically flawed, legally impermissible, and procedurally invalid. The article contends that the CDC dramatically overstates benefits, underreports potential surgical and psychological harms, ignores the physiological importance of the foreskin, and relies on biased evidence from African HIV trials inapplicable to the United States.\n\nFurthermore, Adler asserts that routine infant circumcision violates fundamental human rights, constitutional protections regarding bodily integrity and equal protection, and established medical ethics requiring patient autonomy and non-maleficence. He highlights that funding elective, non-therapeutic surgeries through Medicaid violates federal and state laws governing medical necessity, thereby exposing medical providers to liability for fraud and malpractice. The article concludes that the CDC failed to meet federal standards for Highly Influential Scientific Assessments regarding public commentary and peer review, and calls upon the agency to withdraw the recommendations and advise that physicians not operate on healthy minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Peter W. Adler", "Robert S. Van Howe", "J. Steven Svoboda", "Morten Frisch", "Brian Earp"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Attorneys for the Rights of the Child", "Royal Dutch Medical Association", "Doctors Opposing Circumcision", "American Medical Association", "U.S. Department of Health and Human Services", "Office of Management and Budget"], "themes": ["Male Circumcision", "Children''s Rights and Bodily Integrity", "Medical Ethics and Informed Consent", "Public Health Guidelines", "Medicaid and Healthcare Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('42b14cf26069afdcd83b4f135c4685e290a49e0f476393990677b71911591739', 'Adler-is-circumcision-legal Richmond 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/42b14cf26069afdcd83b4f135c4685e290a49e0f476393990677b71911591739.pdf', 'legal_document', 'ingested', '{"date": "2013", "description": "In this law review article, author Peter W. Adler examines the legal, ethical, and medical dimensions of non-therapeutic neonatal male circumcision, arguing that the procedure is unlawful under American and international law. Adler contends that healthy boys have fundamental constitutional and common law rights to bodily integrity, personal security, equal protection, and religious freedom, which supersede parental preferences and religious claims. Because non-therapeutic circumcision involves the irreversible excision of healthy, functional tissue without medical necessity, Adler argues it meets statutory criteria for child abuse, criminal assault, battery, and tortious injury.\n\nThe article further asserts that physicians violate medical ethics and professional duties by operating on healthy children and failing to obtain genuine informed consent. Adler criticizes medical associations like the American Academy of Pediatrics for overstating preventative health benefits and downplaying surgical risks, complications, and long-term functional and sexual harms. Additionally, the author addresses ancillary issues, arguing that public Medicaid funding for routine circumcision violates statutory mandates against reimbursing elective, medically unnecessary procedures, and questions the commercial sale of foreskin tissue.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Peter W. Adler", "William Blackstone", "Margaret Somerville", "Shea Lita Bond", "William Brigman", "Dan Bollinger"], "organizations": ["Richmond Journal of Law and the Public Interest", "Attorneys for the Rights of the Child", "American Academy of Pediatrics", "American Medical Association", "Royal Dutch Medical Association", "British Medical Association"], "themes": ["Male Circumcision Legality", "Bodily and Genital Integrity", "Equal Protection and Gender Disparity", "Parental Rights vs. Children''s Rights", "Child Abuse and Criminal Assault", "Medical Ethics and Informed Consent", "Medicaid Funding Legality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7cf4a932d49732e43fbcc6af43218e8d029d2e05204ea4b764d7fe154d2cba7', 'Agarwal cut_below Ganaga Ram J 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7cf4a932d49732e43fbcc6af43218e8d029d2e05204ea4b764d7fe154d2cba7.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This review article critically evaluates the medicalization and widespread advocacy of non-cultural, non-therapeutic neonatal circumcision (NNC). The authors challenge the scientific and prophylactic claims often used to justify routine circumcision, such as the prevention of urinary tract infections, sexually transmitted infections, HIV transmission, and penile cancer. They argue that the evidence supporting these benefits is geographically inconsistent, statistically overstated, and ethically questionable, while simultaneously ignoring the anatomical significance, protective immunological role, and sensory value of the prepuce.\n\nIn addition to questioning epidemiological justifications, the paper underscores the ethical dilemmas and bodily integrity violations associated with performing irreversible surgery on non-consenting minors. The authors present findings regarding reduced sexual satisfaction, increased risk of surgical complications, and altered sexual mechanics for both partners post-circumcision. Drawing parallels to debates surrounding female genital mutilation, the article advocates for a gender-neutral standard of bodily autonomy and urges the medical community to adhere to the core tenet of ''primum non nocere'' by ceasing the routine promotion of NNC.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brij B. Agarwal", "Sneh Agarwal", "Amarjit Singh", "Manish Gupta", "Satish Saluja", "Waris Dirie"], "organizations": ["Sir Ganga Ram Hospital", "Lady Hardinge Medical College", "American Academy of Pediatrics", "World Health Organization", "British Medical Association", "General Medical Council", "Royal Dutch Medical Association"], "themes": ["Non-therapeutic Neonatal Circumcision", "Medical Ethics and Bodily Integrity", "HIV and STI Prevention", "Functional Anatomy and Innervation of the Prepuce", "Sexual Function and Quality of Life", "Surgical Complications and Demedicalization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('67ae718195e3d2251846b6e3e61d7aa52cc7e10ae909383e50c8395e983ec9b4', 'Agarwal Preputial Retraction in Children JIAPS 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/67ae718195e3d2251846b6e3e61d7aa52cc7e10ae909383e50c8395e983ec9b4.pdf', 'medical_journal', 'ingested', '{"date": "2005", "description": "This excerpt from an academic medical study investigates the developmental patterns of preputial (foreskin) retraction across different pediatric age groups, from infants aged 0\u20136 months up to children aged 10\u201312 years. The data highlights a clear progression from minimal retractability (Type I) predominantly seen in infants to complete or near-complete retractability (Types IV and V) that becomes common as children reach older age cohorts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Agarwal A"], "organizations": ["Indian Association of Pediatric Surgeons"], "themes": ["Pediatric Surgery", "Preputial Retraction", "Child Development", "Urology", "Phimosis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2da7df390edeabe3b9f48e382e1844edb8cb475d4919a8cb7bb5f735278811ff', 'Agarwal preputioplasty Internet J Surg 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2da7df390edeabe3b9f48e382e1844edb8cb475d4919a8cb7bb5f735278811ff.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This prospective comparative clinical study evaluates the efficacy and outcomes of bilateral lateral slit preputial plasty compared to traditional circumcision in 120 pediatric patients aged 1.5 to 14 years presenting with symptomatic phimosis. Fifty patients with secondary preputial scarring underwent circumcision, while 70 boys with primary symptomatic phimosis were treated with bilateral lateral slit preputial plasty under local anesthesia.\n\nThe findings indicate that bilateral lateral slit preputial plasty offers superior cosmetic and functional results while avoiding common complications associated with circumcision, such as bleeding, infection, and urinary retention. Patients undergoing preputial plasty recovered faster, resuming normal clothing wear earlier, leading the authors to recommend the technique as an easy, safe, foreskin-preserving day-care alternative for primary symptomatic phimosis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Pawan Agarwal", "James D''Silva", "D. Sharma", "V. K. Raina"], "organizations": ["NSCB Govt. Medical College Jabalpur", "Internet Scientific Publications"], "themes": ["Pediatric Urology", "Preputial Plasty", "Circumcision Alternatives", "Primary Phimosis", "Foreskin Preservation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0791ab12257f0b7883c46d7b8cd1ef5e6c0d0afe09dcf2e75f9042a4f7d5d37d', 'Ahmadu Disputing myth sex dysf FGM Anthr 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0791ab12257f0b7883c46d7b8cd1ef5e6c0d0afe09dcf2e75f9042a4f7d5d37d.pdf', 'other', 'ingested', '{"date": "2009", "description": "This document features an interview conducted by anthropologist Richard A. Shweder with Fuambai S. Ahmadu, followed by a reflective commentary by Carlos D. Londo\u00f1o Sulkin, published in Anthropology Today. Ahmadu disputes widespread Western representations of female genital cutting/excision as inherently traumatizing, medically disastrous, or sexually debilitating. Drawing on her personal initiation into the Sierra Leonean Kono bondo society and reviewing clinical and anthropological literature, Ahmadu argues that the practice carries cultural and symbolic meaning tied to female empowerment, aesthetic preferences, and gender complementarity, while demonstrating that empirical evidence does not support claims of inevitable sexual dysfunction.\n\nIn the accompanying reflection, Londo\u00f1o Sulkin examines how Western anti-FGM advocacy and zero-tolerance approaches often reflect parochial, ethnocentric assumptions regarding bodily integrity and beauty. He cautions that aggressive eradication campaigns risk enacting their own cruelties\u2014such as stigmatizing circumcised women, impeding their access to healthcare, and creating self-fulfilling beliefs about psychosexual damage\u2014and calls for more nuanced, culturally informed liberal perspectives.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Fuambai S. Ahmadu", "Richard A. Shweder", "Carlos D. Londo\u00f1o Sulkin", "Sunju Ahmadu", "Carla Obermeyer", "Linda Morison", "Lucrezia Catania", "Michelle Goldberg"], "organizations": ["National Institutes of Health", "University of Chicago", "London School of Economics", "University of Regina", "World Health Organization", "Sauti Yetu"], "themes": ["Female Genital Cutting / Circumcision", "Cultural Relativism and Liberalism", "Female Sexuality and Sexual Function", "Medical Anthropology and Ethnography", "Western Advocacy vs. Local Perspectives", "Kono Bondo Initiation Rites"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cf60623fa34cb28052c164e51208b19a615a3ab01bc8876208d1c79f3dd1cb9f', 'Ahmadu Equality_Not_Special_Protection_2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cf60623fa34cb28052c164e51208b19a615a3ab01bc8876208d1c79f3dd1cb9f.pdf', 'other', 'ingested', '{"date": "2017", "description": "This document features front matter, acknowledgments, and Chapter Twelve from the edited volume ''Universalism without Uniformity: Explorations in Mind and Culture'', compiled in honor of cultural psychologist Richard A. Shweder. The featured chapter, written by anthropologist Fuambai Ahmadu, critically responds to Susan Okin''s essay ''Is Multiculturalism Bad for Women?'' by examining female circumcision within the cultural context of the Kono people of Sierra Leone and Western liberal democracies.\n\nAhmadu argues against Western feminist and legal anti-FGM narratives that depict all female genital modifications in non-Western cultures as inherently patriarchal and oppressive. Drawing on her own voluntary initiation into the Sierra Leonean Bondo society alongside ethnographic research on Mande cosmological dual-sex models, she highlights that these rituals celebrate female sexuality and social power. She asserts that Western liberal states enact hypocritical double standards by legally permitting expensive female genital cosmetic surgeries while criminalizing traditional circumcisions, calling instead for equal rights, cultural pluralism, and bodily autonomy over paternalistic state intervention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Fuambai Ahmadu", "Julia L. Cassaniti", "Usha Menon", "Richard A. Shweder", "Susan Moller Okin", "Roy D''Andrade"], "organizations": ["The University of Chicago Press", "American Anthropological Association", "UNICEF"], "themes": ["Cultural Psychology", "Female Circumcision and Genital Modification", "Multiculturalism vs. Feminism", "Autonomy and Agency", "Mande Cosmology and Rituals", "Relativism vs. Universalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('24205569dc495a6bc9118183294225fb4dc51e9516f5e5ebd2785ff008d7282a', 'Ahmadu Harms anti-FGM Campaign JME 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/24205569dc495a6bc9118183294225fb4dc51e9516f5e5ebd2785ff008d7282a.pdf', 'medical_journal', 'ingested', '{"date": "2025-07-06", "description": "This academic extended essay presents a multidisciplinary critique of the global campaign and discourse surrounding ''female genital mutilation'' (FGM). The authors argue that the dominant anti-FGM narrative\u2014originating from Western advocacy and international health organizations\u2014relies on an ethnocentric, sensationalized ''standard tale'' that homogenizes diverse cultural practices, suppresses dissenting voices from affected communities, and perpetuates racialized stereotypes. They contend that this framework generates substantial unintended harms, such as eroding trust in healthcare settings, prompting intrusive state surveillance and racial profiling of immigrant families, and causing psychological distress or lower self-esteem by pathologizing women''s bodies.\n\nAdditionally, the paper highlights systemic double standards, pointing out that Western bioethics and law routinely permit female genital cosmetic surgery, routine male circumcision, and intersex normalizing surgeries, while strictly criminalizing non-Western female genital practices of comparable or lesser physical severity. Calling for a shift away from the stigmatizing label ''mutilation'' toward more neutral, evidence-based terminology and equitable bioethical assessments, the authors urge policymakers, media, and medical professionals to re-evaluate current advocacy strategies so they do not perpetuate the very injustices they seek to eliminate.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Fuambai Sia Nyoko Ahmadu", "Sara Johnsdotter", "Brian D Earp", "Ellen Gruenbaum", "Juliet Rogers", "Richard A Shweder", "Fran P Hosken", "Ban Ki-moon"], "organizations": ["Journal of Medical Ethics", "BMJ Group", "World Health Organization", "Forte"], "themes": ["Anti-FGM Discourse and Policy", "Ethnocentrism and Double Standards", "Surveillance and Racial Profiling of Migrant Communities", "Medical Ethics and Clinical Mistrust", "Trauma and Cross-Cultural Conceptions of Bodily Modification"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('edc128b8c393d7b68bc47a9beabcab7cf7836730378060cb0994d980e8a54829', 'Ahmady Blade of Tradition 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/edc128b8c393d7b68bc47a9beabcab7cf7836730378060cb0994d980e8a54829.pdf', 'other', 'ingested', '{"date": "2023", "description": "This document presents a comprehensive phenomenological and empirical investigation into male circumcision in Iran, contextualized within global historical, religious, and medical frameworks. Authored by Kameel Ahmady and colleagues, the research critically evaluates the cultural, social, and religious pressures sustaining the near-universal practice of male circumcision (99.7% prevalence in Iran), while exposing the medical, psychological, and sexual complications often neglected by official discourse and commercial medical practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kameel Ahmady", "Hilary Burrage", "Sepehr Estiri", "Fatemeh (Sayeh) Rahimi", "Dr Fateme Mousavi Mirak", "Dr Alireza Kermani", "Mullah Jamaluddin Vazhi", "Dr. Mahnaz Alizadeh"], "organizations": ["Avaye Buf", "UNICEF", "UNFPA", "World Health Organization", "UNAIDS", "Society for the Protection of Children\u2019s Rights in Tehran"], "themes": ["Male Circumcision", "Female Genital Mutilation (FGM/C)", "Children''s Rights and Bodily Autonomy", "Religious Tradition and Cultural Norms", "Medical Pathology and Health Complications", "Medicalization and Commercialization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4af3c3d3a6ab76be5d18631bb983292558cb6d685687520bfc3aab4cc5af7988', 'Ahmady Med Econ Male Circ Iran WJPSR 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4af3c3d3a6ab76be5d18631bb983292558cb6d685687520bfc3aab4cc5af7988.pdf', 'medical_journal', 'ingested', '{"date": "2024-02-24", "description": "This article examines the medical, socioeconomic, and cultural dimensions of male circumcision in Iran, contrasting official health discourses with the lived experiences of circumcised individuals. While medical arguments frequently cite benefits such as reduced risks of HIV, penile cancer, and urinary tract infections, the author critiques how commercialized medical interests, advertising, and religious conservatism collaborate to sustain the practice for financial profit and ideological conformity. \n\nDrawing on qualitative interviews and interdisciplinary literature, the study emphasizes the overlooked negative repercussions of childhood circumcision, including severe physical pain, long-term psychological trauma, and potential impairments to sexual well-being. Ahmady argues that the routine procedure fundamentally violates children''s bodily integrity and calls for legal reforms, critical medical education, and open public discourse to protect children''s fundamental rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kameel Ahmady", "Abdurrahman Mohammad Rasouli", "Sigmund Freud"], "organizations": ["University of Kent", "World Health Organization", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "Children''s Rights and Bodily Integrity", "Commercialization of Healthcare", "Psychological Trauma", "Public Health and Religious Discourse"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9acdd9e33c21f751f031ddae5fe07cf5975db3d286b93e3b2b62ef7d364d3e81', 'Aktor Whose_Rights Danish Debate 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9acdd9e33c21f751f031ddae5fe07cf5975db3d286b93e3b2b62ef7d364d3e81.pdf', 'other', 'ingested', '{"date": "2016", "description": "This academic chapter examines the debate surrounding ritual infant male circumcision (RIMC) in Denmark and across Europe, approaching the controversy from a human rights and child welfare perspective. The author argues that individual rights to bodily integrity, physical autonomy, and future sexual health must override parental authority and religious or cultural minority exemptions. Drawing on the UN Convention on the Rights of the Child and Council of Europe resolutions, the text challenges the legal inconsistency between bans on female genital modification and the continued accommodation of non-therapeutic male circumcision.\n\nAddressing both legal frameworks and medical findings, the document contends that current Danish health regulations operate on ambiguous ''soft law'' exceptions to bodily injury statutes rather than clear legislative justification. The author predicts that increasing international emphasis on children''s absolute rights to protection from non-consensual bodily modifications will ultimately necessitate introducing an age of consent for male circumcision, ensuring such decisions are made autonomously by the individual.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Mikael Aktor", "Shimon Peres", "Thorbj\u00f8rn Jagland", "Marta Santos Pais", "Bryan Turner", "Peter Garde", "Jonas Christoffersen"], "organizations": ["Parliamentary Assembly of the Council of Europe", "Council of Europe", "United Nations", "UN Committee on the Rights of the Child", "International NGO Council on Violence against Children", "Danish Health and Medicines Authority", "Danish Institute for Human Rights", "World Health Organization"], "themes": ["Ritual Infant Male Circumcision", "Children''s Rights", "Bodily Integrity and Autonomy", "Religious Freedom vs. Individual Rights", "Minority Rights", "Human Rights Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e9ffc902cd4881f3ad26bb9f8651c835b2d83fa7c29740a9c1b883cc32e890c9', 'Akturk comp-politics-of-circ-bans-west-europe 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e9ffc902cd4881f3ad26bb9f8651c835b2d83fa7c29740a9c1b883cc32e890c9.pdf', 'other', 'ingested', '{"date": "2019-11-07", "description": "This academic paper examines the wave of political, medical, and legal initiatives aimed at criminalizing and banning infant male circumcision across Western and Northern European countries between 2012 and 2018, focusing primarily on Germany, Austria, Switzerland, Denmark, Sweden, Norway, and Iceland. The author develops a six-stage causal narrative explaining how these initiatives unfolded: medical or legal professionals first triggered national debate, followed by politicization from far-right or secular-left parties, broad public opinion support, legislative deliberation, pushback from international Jewish and Muslim organizations, and finally executive intervention by heads of state or party leaders to halt the bans.\n\nThe paper highlights that while proponents framed bans around children''s physical integrity and medical ethics, the bans disproportionately impacted Jewish and Muslim minority religious practices. Ultimately, national political leadership blocked these bans due to international diplomatic pressure, historical sensitivities, and concerns over religious freedom, demonstrating that political interventions rather than medical or legal consensus determined the final policy outcomes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["\u015eener Akt\u00fcrk", "Angela Merkel", "Markus Wallner", "Beatrix Karl", "Frederik Malmberg", "Silja D\u00f6gg Gunnarsd\u00f3ttir", "Jonathan Greenblatt", "Pinchas Goldschmidt", "David Goldberg"], "organizations": ["Ko\u00e7 University", "American Political Science Association", "District Court of Cologne", "German Bundestag", "Parliamentary Assembly of the Council of Europe", "American Academy of Pediatrics", "British Medical Association", "Anti-Defamation League", "European Jewish Congress", "Conference of European Rabbis", "Sweden Democrats", "Progress Party (Norway)", "Intact Denmark"], "themes": ["Male Circumcision Bans", "Religious Liberty and Minority Rights", "Comparative Politics", "Children''s Rights vs. Parental Authority", "Medical Ethics and Bodily Integrity", "Far-Right Politics and Islamophobia", "Judicial Activism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5133c4d95e0bf7e502833a68269f7966c1ebff8a1166adb0816161754d8a0a33', 'Alahmad Bodily Integrity Circ Islam JIMA 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5133c4d95e0bf7e502833a68269f7966c1ebff8a1166adb0816161754d8a0a33.pdf', 'medical_journal', 'ingested', '{"date": "2012-03-20", "description": "This academic paper examines the concept of bodily integrity within Islamic bioethics and jurisprudence, using male circumcision as a focal case study. The authors analyze how Islamic tradition honors and protects the human body\u2014viewing it as a divine trust (\u1e25urmat al-jasad) that must not be altered, mutilated, or defaced without legal or medical necessity\u2014while simultaneously mandating or recommending male circumcision as a religious commandment originating with Prophet Ibrahim and reinforced by the sunnah of Prophet Muhammad. \n\nThe study compares Islamic perspectives with Western bioethical frameworks across three dimensions of bodily integrity: biological wholeness, subjective wholeness, and normative wholeness. The authors conclude that unlike recent Western bioethical arguments that frame circumcision as a violation of bodily integrity, Islamic ethics views the practice as an act of purification, obedience, and perfection of the body, meaning that anti-circumcision movements are unlikely to find traction within Muslim societies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ghiath Alahmad", "Wim Dekkers", "Imam Ahmad", "al-Shafi`i", "Imam Abu Hanifa", "Imam Malik", "Sami Awad Aldeeb Abu-Sahlieh", "Immanuel Kant", "Thomas Aquinas"], "organizations": ["King Abdullah International Medical Research Center", "King Saud bin Abdulaziz University for Health Sciences", "Radboud University Nijmegen Medical Center", "Islamic Fiqh Council", "Committee of Senior Scholars in Saudi Arabia", "Journal of the Islamic Medical Association of North America"], "themes": ["Islamic Bioethics", "Bodily Integrity", "Male Circumcision", "Comparative Bioethics", "Islamic Jurisprudence (Shariah)", "Human Dignity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bfed96b7894ac8b84efdbb1ec11d8b5bde9bd162b1818d7908f698efa0950774', 'Albero Circ & Clearance HPV BMC InfDis 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bfed96b7894ac8b84efdbb1ec11d8b5bde9bd162b1818d7908f698efa0950774.pdf', 'medical_journal', 'ingested', '{"date": "2014-02-10", "description": "This prospective cohort study from the HPV Infection in Men (HIM) study evaluates the association between male circumcision and the incidence and clearance of genital human papillomavirus (HPV) infections. Analyzing 4,033 healthy men from Brazil, Mexico, and the United States followed every six months for a median of 17.5 months, researchers tested combined cell samples from the coronal sulcus, glans, penile shaft, and scrotum for 37 HPV types.\n\nThe study found no overall association between male circumcision and the incidence or clearance of genital HPV infections, including oncogenic and non-oncogenic categories. However, circumcision was linked to significant differences in acquisition and clearance for specific individual HPV genotypes. The authors conclude that the lack of observed overall effect was likely due to combining swabs from multiple penile and scrotal subsites into a single sample, which may have masked site-specific protective effects at the distal penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ginesa Albero", "Xavier Castellsagu\u00e9", "Hui-Yi Lin", "William Fulp", "Luisa L Villa", "Eduardo Lazcano-Ponce", "Mary Papenfuss", "Martha Abrahamsen", "Jorge Salmer\u00f3n", "Manuel Quiterio", "Alan G Nyitray", "Beibei Lu", "F Xavier Bosch", "Anna R Giuliano"], "organizations": ["H. Lee Moffitt Cancer Center and Research Institute", "Catalan Institute of Oncology", "IDIBELL", "CIBER en Epidemiolog\u00eda y Salud P\u00fablica", "Universitat Autonoma de Barcelona", "University of S\u00e3o Paulo", "Instituto Nacional de Salud Publica", "Instituto Mexicano del Seguro Social", "The University of Texas School of Public Health", "BioMed Central Ltd"], "themes": ["Human Papillomavirus (HPV)", "Male Circumcision", "Genital HPV Incidence and Clearance", "Sexually Transmitted Infections", "Cancer Prevention", "Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5969d795089f60df345c05b474b775ed3cbb61c102c63a4490f71bfd494e36d0', 'Albero Circ & HPV MultiNational BMC InfDis 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5969d795089f60df345c05b474b775ed3cbb61c102c63a4490f71bfd494e36d0.pdf', 'medical_journal', 'ingested', '{"date": "2013-01-17", "description": "This multinational study investigated the association between male circumcision (MC) and genital human papillomavirus (HPV) infection among 4,072 healthy men aged 18\u201370 across Brazil, Mexico, and the United States as part of the HPV in Men (HIM) Study. Exfoliated cell samples pooled from the coronal sulcus, glans penis, shaft, and scrotum were analyzed for HPV DNA detection and specific genotyping.\n\nThe findings demonstrated no significant overall association between circumcision and the general prevalence of any HPV, oncogenic HPV types, or unclassified HPV infections. However, circumcision was inversely associated with non-oncogenic HPV infections, particularly types 11, 40, 61, 71, and 81, and this effect was most pronounced among men reporting 1 to 4 lifetime female sexual partners. The authors suggest that the lack of observed overall protection may stem from the pooling of multiple anatomical sampling sites, which could dilute site-specific protective effects localized primarily to the glans penis and coronal sulcus.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ginesa Albero", "Anna R. Giuliano", "Luisa L. Villa", "Eduardo Lazcano-Ponce", "Xavier Castellsagu\u00e9", "F. Xavier Bosch", "Jorge Salmer\u00f3n"], "organizations": ["H. Lee Moffitt Cancer Center and Research Institute", "Catalan Institute of Oncology", "Ludwig Institute for Cancer Research", "Instituto Nacional de Salud P\u00fablica", "University of South Florida", "National Cancer Institute"], "themes": ["Human Papillomavirus (HPV)", "Male Circumcision", "Sexually Transmitted Infections", "Epidemiology", "Cancer Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9c1ed571f0d31039c6842b749af1eba3a9b93c7cec6c7439c67d904289ddb3b0', 'Aldeeb Islamic_Law_and_Male_Female 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9c1ed571f0d31039c6842b749af1eba3a9b93c7cec6c7439c67d904289ddb3b0.pdf', 'legal_document', 'ingested', '{"date": "1995-01-04", "description": "This article examines the religious, legal, and medical debates surrounding male and female circumcision in Islamic law and international discourse. Author Sami A. Aldeeb Abu-Sahlieh argues that the common distinction drawn between male circumcision (routinely accepted or considered hygienic) and female circumcision (condemned as genital mutilation) is legally, ethically, and medically unsound. Emphasizing that both practices compromise the physical integrity of healthy children without explicit Quranic mandates, the author contends that arguments defending circumcision rely on weak religious traditions, social customs, and flawed medical justifications.\n\nThe document reviews classical and contemporary Islamic legal rulings, varying regional practices across Africa and the Middle East, and the physiological and psychological damages caused by genital cutting. It also critiques the reluctance of international bodies, Western nations, and Islamic scholars to condemn male circumcision alongside female genital cutting, concluding that both forms should be prohibited on human rights grounds, permitting surgical intervention only for rare, verified individual medical necessities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Sami A. Aldeeb Abu-Sahlieh", "Gad-al-Haq Ali Gad-al-Haq", "Nawal El-Saadawi", "Mahmud Shaltut", "Mustafa Kamal Al-Mahdawi", "Muhammad Al-Tantawi", "G\u00e9rard Zwang"], "organizations": ["Swiss Institute of Comparative Law", "Valparaiso University Law School", "Al-Azhar University", "United Nations", "World Health Organization", "UNICEF", "Inter-African Committee"], "themes": ["Islamic Law and Jurisprudence", "Male and Female Circumcision", "Children''s Rights and Bodily Integrity", "Human Rights vs. Cultural Tradition", "Medical and Psychological Consequences of Genital Cutting", "Legal and Policy Regulation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d24255c0d8938cc8828fb2004549444ce0a3a3ae92af1acf9ccf7a7f134dba10', 'Aldeeb Male Female Circ Law (book) 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d24255c0d8938cc8828fb2004549444ce0a3a3ae92af1acf9ccf7a7f134dba10.pdf', 'other', 'ingested', '{"date": "2012", "description": "This text comprises the preliminary matter, introduction, and initial chapters of a comprehensive treatise by legal scholar Sami A. Aldeeb Abu-Sahlieh examining male and female circumcision through religious, medical, social, and legal perspectives. The author traces the historical origins of genital cutting from ancient Middle Eastern cultures through the scriptural frameworks of Judaism, Christianity, and Islam, analyzing biblical commands, covenants, and the rigorous theological requirements that render circumcision a marker of identity, purity, and community membership.\n\nThe author critiques the contemporary international discourse for disproportionately condemning female genital mutilation while ignoring routine male circumcision, arguing that both procedures alter healthy genital organs without patient consent and constitute fundamental violations of physical integrity and human rights. Supported by historical and sociological data, the text explores the clinical typologies, religious justifications, and political taboos surrounding genital cutting, while challenging the medical dogma and legal hesitancy that perpetuate these practices globally.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sami A. Aldeeb Abu-Sahlieh", "Marilyn Fayre Milos", "Abu-Yusuf", "Jad-al-Haq", "Muhammad Sayyid Tantawi", "Al-Zahrawi", "Moses Maimonides", "Baruch Spinoza"], "organizations": ["Centre of Arab and Islamic Law", "National Organization of Circumcision Information Resource Centers", "World Health Organization", "UNICEF", "United Nations Population Fund", "Swiss Institute of Comparative Law"], "themes": ["Male Circumcision", "Female Genital Mutilation", "Bodily Integrity and Human Rights", "Religious Law and Covenants", "Comparative Religion and Theology", "Medical and Surgical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7c7f79555dd62ad8f9a1e37eafcddf35dff5376fb9d37c255ab9ba2f96ad08ab', 'Aldeeb To Mutilate Jehovah CIRP 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7c7f79555dd62ad8f9a1e37eafcddf35dff5376fb9d37c255ab9ba2f96ad08ab.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This article examines the religious, cultural, medical, and legal justifications surrounding male and female circumcision, primarily focusing on Islamic jurisprudence and Arab society, alongside Jewish and Western medical practices. The author argues that neither the Koran nor medical necessity justifies ritual genital cutting of healthy minors, critiquing both traditions for rationalizing bodily mutilation and violating children''s fundamental right to physical integrity. Furthermore, the paper critiques the inconsistency of international human rights organizations and Western legal systems that actively condemn female genital mutilation while ignoring or normalizing non-therapeutic male circumcision.\n\nDrawing upon historical texts, contemporary fatwas, medical literature, and events from the Third International Symposium on Circumcision, the author highlights the physical, psychological, and psychosexual harm inflicted by these practices. He concludes that distinctions between male and female circumcision are legally and ethically untenable, calling for legal prohibitions against all non-consensual infant genital cutting until individuals reach the age of majority and can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sami Awad Aldeeb Abu-Sahlieh", "Frederick M. Hodges", "G\u00e9rard Zwang", "Nawal El-Saadawi", "Mahmud Shaltut", "Mustafa Kamal Al-Mahdawi", "Jim Bigelow", "Neal Barnard"], "organizations": ["World Health Organization", "UNICEF", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "Inter-African Committee on Traditional Practices", "Al-Azhar University", "Physicians Committee for Responsible Medicine"], "themes": ["Male and female circumcision", "Physical integrity and children''s rights", "Islamic law and jurisprudence", "Medical ethics and bodily autonomy", "Religious justification of genital cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9c55b20a5fc544c1779944308baf0d06c32db494764a267ec2c8cac5601e1624', 'Aldeeb To Mutilate Jehovah MedLaw 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9c55b20a5fc544c1779944308baf0d06c32db494764a267ec2c8cac5601e1624.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This article examines the religious, legal, and medical justifications surrounding male and female circumcision within Islamic law, Judaism, and Western medical practice. The author argues that both practices constitute the mutilation of healthy organs and infringe upon the physical integrity and human rights of children, rejecting the legal and cultural double standard that condemns female genital mutilation while accepting male circumcision. Analyzing scriptural sources, including the Koran and Hadith, the article asserts that religious texts do not mandate bodily mutilation and that such customs have instead been legitimized through tradition, flawed reasoning, and patriarchal authority.\n\nThe document also reviews the physical, psychosexual, and legal repercussions of circumcision, tracking evolving international perspectives, medical declarations, and legal prohibitions. Additionally, the author reports on the Third International Symposium on Circumcision held in 1994, highlighting growing opposition to routine neonatal male circumcision in the United States, testimonies of dissenting health professionals, methods of foreskin restoration, and ongoing activist efforts to secure universal legal protections for all children regardless of sex or religion.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sami A. Aldeeb Abu-Sahlieh", "Nawal El-Saadawi", "Mahmud Shaltut", "G\u00e9rard Zwang", "Mustafa Kamal Al-Mahdawi", "Jim Bigelow", "Gad-al-Haq ''Ali Gad-al-Haq", "Neal Barnard"], "organizations": ["World Health Organization", "UNICEF", "Al-Azhar University", "Inter-African Committee on Traditional Practices Affecting Women''s and Children''s Health", "National Organization of Circumcision Information Resource Centers", "Swiss Institute of Comparative Law", "Swiss Academy of Medical Sciences", "Physicians Committee for Responsible Medicine", "National Organization to Halt the Abuse and Routine Mutilation of Males"], "themes": ["Male and Female Circumcision", "Children''s Rights and Bodily Integrity", "Islamic Jurisprudence and Religious Law", "Medical Ethics and Health Complications", "Legal Prohibition and Human Rights", "Foreskin Restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e9cc7b222aeb652340f404c28b9eec7331964f415593a199bf3b814d8e464d86', 'Alguacil Terminal Innervation Clin Anat 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e9cc7b222aeb652340f404c28b9eec7331964f415593a199bf3b814d8e464d86.pdf', 'medical_journal', 'ingested', '{"date": "2014-12-05", "description": "This study investigates the terminal neuroanatomy and cutaneous sensory receptors of the human male foreskin using histological and immunohistochemical analyses. By examining tissue samples from ten circumcised boys aged 1 to 9 years using markers for PGP 9.5 and neuron-specific enolase (NSE), along with modified Bielschowsky silver staining, the researchers sought to characterize the sensory innervation of the prepuce.\n\nThe findings confirmed the presence of three distinct types of cutaneous sensory receptors: free nerve endings (FNE) primarily located in the papillary dermis and epidermal strata, non-capsulated Meissner-like corpuscles scattered in the dermal papillae, and capsulated Pacinian-like corpuscles located in the deeper dermis. PGP 9.5 proved to be the most sensitive neural marker, clearly delineating nerve structures and corpuscles. The authors conclude that the presence of these specialized mechanoreceptors provides neuroanatomical evidence of the foreskin''s complex sensory capability, which may inform future discussions on circumcision, surgical decisions, and therapeutic approaches to sexual dysfunction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Nieves Mart\u00edn-Alguacil", "R. Scott Cooper", "Nathan Aardsma", "Lazarus Mayoglou", "Donald Pfaff", "Justine Schober"], "organizations": ["Rockefeller University", "Universidad Complutense de Madrid", "UPMC Hamot", "Lake Erie College of Osteopathic Medicine", "Wiley Periodicals, Inc."], "themes": ["Neuroanatomy", "Male Genitalia Innervation", "Foreskin Histology", "Cutaneous Sensory Receptors", "Circumcision", "Immunohistochemistry"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5ff70dd3600f9b4f49445c17a06cff33aae0b873f791af699d15465f31857f69', 'Ali FGC-FGM Mutilating_Facts 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5ff70dd3600f9b4f49445c17a06cff33aae0b873f791af699d15465f31857f69.pdf', 'other', 'ingested', '{"date": "2012", "description": "This paper argues against the conflation of female circumcision with female genital mutilation (FGM), asserting that Islamic law categorically prohibits FGM\u2014including clitoridectomy, excision, and infibulation\u2014as a punishable crime of bodily harm. The author contends that Islamic tradition strictly distinguishes between harmful mutilation and a limited, non-damaging procedure akin to modern clitoral hoodectomy or labiaplasty, intended exclusively to address anatomical impediments such as clitoral phimosis.\n\nFurthermore, the text argues that authentic Islamic jurisprudence reserves any such permissible procedure strictly for consenting adult women to enhance marital well-being and sexual function, rejecting its application to infants and prepubescent children. Ali strongly criticizes Western academics, misinformed religious practitioners, and media narratives for perpetuating factual errors, calling instead for objective legal clarity, ethical medical standards, and the protection of women''s rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Afroz Ali", "Imam Malik", "Imam Nawawi", "Ibn Hajar al-Asqalani", "Umm ''Attiyah", "Nuh Keller", "Sayyid Sabiq", "Imam Shawkani"], "organizations": ["World Health Organisation", "Muslim Womens League", "American Society of Plastic Surgeons", "United Nations"], "themes": ["Islamic Jurisprudence", "Female Genital Mutilation Prohibition", "Female Circumcision vs. FGM", "Women''s Bodily Autonomy and Sexual Health", "Labiaplasty and Clitoral Hoodectomy", "Critique of Western Academic Discourse"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cc2c7dea995b69564fbdcbcb9dc31c60a7e701095b7a01f86b407d781c59a58f', 'Ali Manager Atitudes Botswana 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cc2c7dea995b69564fbdcbcb9dc31c60a7e701095b7a01f86b407d781c59a58f.pdf', 'other', 'ingested', '{"date": "2013", "description": "This study evaluates the attitudes of Safe Male Circumcision (SMC) program managers toward the rollout and scale-up of SMC as an HIV prevention strategy in Botswana. Despite substantial capacity-building and resource allocation by the Ministry of Health since 2009, circumcision numbers continually lagged behind national targets. Through a qualitative research design involving semi-structured interviews with 24 program managers across national and district levels, the study investigated whether managerial attitudes contributed to this program underperformance.\n\nThe findings indicate that managers largely exhibited positive attitudes aligning with the Ministry of Health''s values, viewing the benefits of SMC\u2014specifically HIV prevention and penile hygiene\u2014as significantly outweighing the surgical risks. The study concluded that lagging uptake was not caused by poor managerial attitudes, but rather by external barriers such as public fear of pain, hesitation around HIV testing, difficulty observing post-operative sexual abstinence, high staff turnover, and health facility capacity constraints.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Ali Salim Ali", "Dr Thozamile Qubuda", "Kgosi Linchwe II"], "organizations": ["Stellenbosch University", "Ministry of Health Botswana", "I-TECH Botswana", "ACHAP", "World Health Organization", "UNAIDS", "CDC", "Jhpiego"], "themes": ["Safe Male Circumcision (SMC)", "HIV/AIDS Prevention", "Public Health Scale-Up", "Healthcare Program Management", "Health Personnel Attitudes and Turnover"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3d13da87b1b934aa2e335906f6209923ad273d05cfcb65112d788080749f91c7', 'Alkhenizan Nonthera Inf Circ SaudiMedJ 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3d13da87b1b934aa2e335906f6209923ad273d05cfcb65112d788080749f91c7.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This systematic review examines the clinical evidence, ethical dimensions, and international legal perspectives surrounding non-therapeutic infant male circumcision. Synthesizing data from numerous systematic reviews and meta-analyses, the authors demonstrate that the procedure confers substantial long-term health benefits, including marked reductions in the risks of urinary tract infections, HIV transmission, human papillomavirus (HPV), penile cancer, and cervical cancer in female partners, while demonstrating high cost-effectiveness and a very low rate of serious complications when performed under sterile conditions with proper anesthesia.\n\nFrom ethical and legal viewpoints, the review argues that infant male circumcision aligns with the principles of beneficence and non-maleficence, serving the child''s overall best interests across physical, mental, and cultural dimensions. The authors assert that parental consent is legally and internationally grounded under frameworks such as the UK Children Act, the European Convention on Human Rights, and UN conventions, concluding that banning the practice would violate parental and religious rights and risk severe public health consequences by driving the procedure underground.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Abdullah Alkhenizan", "Kossay Elabd", "Angela Merkel", "Gerard Porter"], "organizations": ["King Faisal Specialist Hospital and Research Center", "American Academy of Pediatrics", "World Health Organization", "UNAIDS", "British Medical Association", "National Health Service"], "themes": ["Infant Male Circumcision", "Preventive Medicine and Public Health", "Medical Ethics and Beneficence", "Parental Rights and Bodily Integrity", "International Human Rights Law", "Cost-Effectiveness Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2ac36139aeed12019942129dc311fb8e6a61ae2906cb1f4a708229b0d91435ac', 'Allan Circ in Sexology J Men Stud 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2ac36139aeed12019942129dc311fb8e6a61ae2906cb1f4a708229b0d91435ac.pdf', 'other', 'ingested', '{"date": "2021", "description": "This academic article analyzes the evolving discourse on male circumcision in ''Sexology: Sex Science Magazine'' between 1934 and 1975. The author, Jonathan A. Allan, examines how the publication captured the shifting perceptions surrounding routine neonatal circumcision, charting its progression from early medical and hygienic endorsements toward increasing skepticism and anti-circumcision perspectives by the 1970s.\n\nAllan argues that despite ''Sexology'' frequently relying on sensationalist framing and popular science journalism for lay audiences, it reflected broader historical and medical trends including the medicalization, demedicalization, and remedicalization of the foreskin. The magazine served as an accessible public forum for bodily and clinical concerns that foreshadowed modern intactivist debates.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jonathan A. Allan", "Hugo Gernsback", "Craig Yoe", "Laura M. Carpenter", "W. J. Fox", "George Ryley Scott", "Winfield Scott Pugh"], "organizations": ["Brandon University", "SAGE Publications"], "themes": ["Circumcision", "Medicalization and Demedicalization", "Popular Science and Sex Education", "Men''s Health and Sexuality", "Intactivism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a8173a6c18ddc7ebd2dbf6f759d0c9e3de8ce2e62e6537fc2ca3f25b4d4544c8', 'Allan First Rip Off 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a8173a6c18ddc7ebd2dbf6f759d0c9e3de8ce2e62e6537fc2ca3f25b4d4544c8.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This academic paper examines the historical emergence of ''intactivism''\u2014the anti-circumcision social movement\u2014within men''s adult magazines during the 1970s, focusing primarily on Hustler. While existing scholarship predominantly analyzes intactivism through mainstream news media, online platforms, and academic discourse, the author demonstrates that sexually explicit magazines served as early, influential venues for questioning routine neonatal circumcision. By analyzing major Hustler articles such as ''A Foreskin is Missing'' (1975) and ''The First Rip-Off'' (1979), alongside reader correspondence, the study highlights how these publications addressed the medical, financial, and sexual dimensions of circumcision.\n\nThe article argues that pornographic magazines provided an unconventional yet impactful platform to challenge prevailing medical and cultural orthodoxies regarding circumcision. These magazines directly engaged with taboo subjects, framing the foreskin in terms of erotic function, penile sensitivity, bodily autonomy, and aesthetic value. Reader responses illustrated deeply polarized perspectives, demonstrating that popular men''s publications significantly contributed to public debate and shaped early intactivist rhetoric well before the movement became widely established online.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jonathan A. Allan", "Larry Flynt", "Leo Rosenhouse", "Tom Conaway", "Thomas J. Ritter", "Robert J. Valentine", "William Masters", "Virginia Johnson", "Amanda Kennedy", "Lauren M. Sardi"], "organizations": ["Brandon University", "American Academy of Pediatrics", "Hustler"], "themes": ["Intactivism and Anti-Circumcision Activism", "Pornography and Men''s Magazines", "Genital Autonomy and Bodily Integrity", "Male Sexuality and Penile Sensitivity", "Medicalization and Commercialization of Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('30fb10047fba9dc42fb4c92e017516148bec1d7be85c4885b48cd74c556f7cc1', 'Allan Foreskin Graveyard Raw 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/30fb10047fba9dc42fb4c92e017516148bec1d7be85c4885b48cd74c556f7cc1.pdf', 'other', 'ingested', '{"date": "2019", "description": "This document comprises the front matter, table of contents, and Chapter 1 from the edited volume ''RAW: PrEP, Pedagogy, and the Politics of Barebacking,'' edited by Ricky Varghese. In the opening chapter, ''Is the Foreskin a Grave?'', author Jonathan A. Allan examines the biopolitical, cultural, and medical discourses surrounding the foreskin and male circumcision, drawing heavily on Leo Bersani''s seminal essay ''Is the Rectum a Grave?''. Allan analyzes how biomedical literature frequently pathologizes the foreskin as a primitive, disease-ridden vector or ''magnet for HIV'' while framing circumcision as a prophylactic ''natural condom'' tied to American exceptionalism, hygiene, and national security.\n\nAllan argues that global and American public health campaigns advocating circumcision primarily prioritize protecting heterosexual men and reproductive bodies, thereby exposing deep-seated ''heterosexual anxiety'' and marginalizing queer, bisexual, and immigrant bodies. By deconstructing the cultural stigmatization of intact penises and the racialized, colonial undertones of circumcision initiatives, the chapter invites queer theory to engage more critically with the bodily politics of the foreskin, sexual desire, and HIV risk.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Ricky Varghese", "Jonathan A. Allan", "Tim Dean", "Leo Bersani", "Brian J. Morris", "Robert Darby", "D.W. Winnicott"], "organizations": ["University of Regina Press", "Zed Books Ltd", "World Health Organization", "UNAIDS", "United Nations"], "themes": ["Queer Theory", "Biopolitics", "HIV/AIDS Prevention", "Male Circumcision", "Heterosexual Anxiety", "Barebacking", "Bodily Integrity and Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('17c6f5f5f4a1e225e4606b24b9aa99636cbd48e237bf92839e172f4cc4dc29fc', 'Allan Lost inches 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/17c6f5f5f4a1e225e4606b24b9aa99636cbd48e237bf92839e172f4cc4dc29fc.pdf', 'other', 'ingested', '{"date": "2019", "description": "This academic article by Jonathan A. Allan explores the debates surrounding male circumcision and foreskin restoration as presented in gay men''s pornographic magazines from the 1980s into the early 2000s. Analyzing publications such as Stallion, Honcho, Machismo, and Unzipped Monthly, Allan examines how these erotic periodicals served as accessible forums for gay men to negotiate bodily aesthetics, sexual pleasure, and bodily autonomy away from mainstream reticence.\n\nThe analysis tracks how discussions shifted across decades alongside changing pediatric guidelines from the American Academy of Pediatrics and the emergence of the HIV/AIDS epidemic. During the height of the crisis, media rhetoric framed the uncircumcised penis as a biomolecular health risk, while later coverage shifted toward anti-circumcision activism (''intactivism'') and techniques for non-surgical foreskin restoration, highlighting evolving cultural anxieties surrounding masculinity and genital integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jonathan A. Allan", "Bob Ward", "Chuck Thompson", "Mitchell Anderson", "Tim Evans", "Marilyn Milos", "Jim Bigelow"], "organizations": ["Brandon University", "American Academy of Pediatrics", "National Organization of Circumcision Information Resource Centers", "National Organization of Restoring Men", "Brothers United for Future Foreskins"], "themes": ["Circumcision Debates", "Gay Men''s Print Culture", "HIV/AIDS and Biopolitics of Risk", "Foreskin Restoration", "Intactivism", "Male Embodiment and Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f66d3a8dabc4f267d578774b6f277b670e631ee38025ca24b2fbcf97856394da', 'Allen Human Tissue Ownership ClinChem 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f66d3a8dabc4f267d578774b6f277b670e631ee38025ca24b2fbcf97856394da.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This review examines the legal, regulatory, and ethical frameworks governing the collection, ownership, and use of human tissue specimens in biomedical research. While federal regulations such as the Common Rule establish clear rules for human participant protections and informed consent, they leave the question of specimen ownership unaddressed. Through analysis of landmark legal cases\u2014including Moore v. Regents of the University of California, Greenberg v. Miami Children''s Hospital, and Washington University v. Catalona\u2014the authors demonstrate that courts have consistently rejected donor property claims over excised tissue to avoid burdening medical progress, treating voluntary donations as gifts rather than bailments.\n\nThe article also reviews legal standards governing postmortem tissues and reproductive specimens, highlighting recent controversies\u2014such as the Texas newborn screening blood spot litigation and the Havasupai Tribe lawsuit\u2014that culminated in settlements requiring the destruction or return of valuable samples due to lack of donor consent. The authors advise laboratorians and researchers to prioritize transparency, secure detailed informed consent covering potential secondary research, ensure institutional review board oversight, and rigorously adhere to specimen de-identification standards.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Monica J. Allen", "Michelle L.E. Powers", "K. Scott Gronowski", "Ann M. Gronowski", "William Catalona", "Reuben Matalon", "John Moore"], "organizations": ["American Association for Clinical Chemistry", "Washington University School of Medicine", "BJC HealthCare", "Department of Health and Human Services", "Food and Drug Administration", "Office of Human Research Protection", "Texas Department of State Health Services", "Arizona State University", "Miami Children''s Hospital Research Institute", "Havasupai Tribe"], "themes": ["Human Tissue Ownership", "Informed Consent", "Biomedical Research Ethics", "Common Rule and Federal Regulations", "Property Rights vs. Public Good", "Biospecimen Repositories"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7e29283876330135f4145e8f633d3081d1de7e1a2da7817e57584f15cb191670', 'AMA Circ Policy 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7e29283876330135f4145e8f633d3081d1de7e1a2da7817e57584f15cb191670.pdf', 'policy_guideline', 'ingested', '{"date": "2023", "description": "This document outlines the American Medical Association''s (AMA) official policy (H-60.945) on neonatal male circumcision, as modified in 2023. The policy states that current medical evidence demonstrates the health benefits of newborn male circumcision\u2014including the prevention of urinary tract infections, penile cancer, and certain sexually transmitted infections such as HIV\u2014outweigh the risks, thereby justifying access for families who choose it.\n\nAdditionally, the AMA emphasizes the necessity of physician training in local pain control techniques and advocates for thorough informed consent discussions regarding pain management options with parents. To ensure equitable access, the policy explicitly encourages state Medicaid reimbursement for the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["American Medical Association", "Council on Science and Public Health", "Medicaid"], "themes": ["Neonatal Circumcision", "Pediatric Health", "Pain Management", "Informed Consent", "Health Insurance and Medicaid", "Preventative Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4419769362a03e259048482e84bb6fdfa519b74a0799d87d0d93e455e4ed2651', 'AmCollSurgeons Definition Surgery 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4419769362a03e259048482e84bb6fdfa519b74a0799d87d0d93e455e4ed2651.pdf', 'policy_guideline', 'ingested', '{"date": "2007", "description": "The American College of Surgeons (ACS) Definition of Surgery Legislative Toolkit is an advocacy guide designed to help surgeons and state chapters lobby state legislatures to codify a formal legal definition of surgery. The document argues that defining surgery in state law protects patient safety and ensures quality outcomes by maintaining high standards for the education, training, and licensure required to perform invasive procedures that irreversibly transform human tissue.\n\nTo assist state-level advocacy, the toolkit provides background on existing statutory definitions, talking points addressing counterarguments regarding scope of practice, model legislative text, sample legislative letters, action alerts, and excerpts of enacted definitions from states such as Virginia, Florida, and New Hampshire.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Christopher Johnson"], "organizations": ["American College of Surgeons", "American Medical Association", "Connecticut Chapter of the American College of Surgeons"], "themes": ["Definition of Surgery", "Patient Safety", "Scope of Practice", "Legislative Advocacy", "Medical Licensure and Qualifications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('708e72407873e66bd292a7bf2fff92db4acd4e6c0c61e6093ed2b65362831c89', 'Amesbury Is_Body_Secular J Br Assoc Religion 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/708e72407873e66bd292a7bf2fff92db4acd4e6c0c61e6093ed2b65362831c89.pdf', 'other', 'ingested', '{"date": "2016", "description": "This article examines the public and legal controversies in Germany regarding non-therapeutic male circumcision following a 2012 Cologne court ruling. The debate was largely framed as a clash between a child''s fundamental right to bodily integrity and parents'' religious freedom. The author argues that this framing relies on problematic modern liberal assumptions that treat the body as a natural, pre-cultural baseline and religion as an elective, privatized individual choice.\n\nDrawing on critical and cultural theorists including Michel Foucault, Judith Butler, Mary Douglas, and Talal Asad, the author contends that the body is not prediscursive or external to law, but rather culturally and legally constructed. Under modern secular law, the normative, intact uncircumcised body serves as a synecdoche for secular universalism while concealing its own particular cultural and historically Christian lineage, ultimately circumscribing religious minority practices like circumcision under the guise of state neutrality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Richard Amesbury", "Judith Butler", "Michel Foucault", "Talal Asad", "Martha Nussbaum", "Mary Douglas"], "organizations": ["British Association for the Study of Religions", "University of Zurich", "Landgericht K\u00f6ln", "Bundestag", "Yale Law School"], "themes": ["Circumcision", "Bodily Integrity", "Religious Freedom", "Secularism", "Multiculturalism", "Legal and Cultural Construction of the Body"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5fa411ab4017952be9a6d5cb0071322b920ab6f8ddf364ecea164bff8e96aa51', 'AmnestyIntl Intersex DoNoHarmReport 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5fa411ab4017952be9a6d5cb0071322b920ab6f8ddf364ecea164bff8e96aa51.pdf', 'policy_guideline', 'ingested', '{"date": "2017", "description": "This Amnesty International report investigates the human rights violations experienced by children and adults born with variations of sex characteristics (intersex individuals) in Denmark and Germany. It highlights how infants and children are frequently subjected to non-emergency, invasive, and irreversible medical interventions\u2014such as clitoral reductions, vaginoplasties, hypospadias repairs, and gonadectomies\u2014primarily aimed at conforming atypical genitalia to binary male or female social norms. The report argues that such cosmetic procedures are often performed without the informed consent of the individual, driven by entrenched gender stereotypes and medical pathologization.\n\nThe findings emphasize the resulting physical and psychological harm suffered by individuals, including chronic pain, loss of sensation, and psychological trauma, exacerbated by a lack of access to medical records and comprehensive psychosocial support. Amnesty International calls on authorities in Denmark and Germany to adopt human rights-based healthcare protocols that safeguard bodily integrity and self-determination, postpone non-urgent surgical and hormonal interventions until children can participate in informed decision-making, and provide legal redress and psychological assistance to those impacted.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Alex J\u00fcrgen", "Anne Fausto-Sterling", "John Money", "Karina Lins", "Mika Venhola", "Lucie Veith", "Claus Gravholt", "Katharina Main", "Ditte Trolle", "J\u00f6rg Woweries", "Gerda Janssen-Schmidchen"], "organizations": ["Amnesty International", "United Nations Committee on Economic, Social and Cultural Rights", "Rigshospitalet", "Arhus University Hospital", "Odense University Hospital", "Intersexuelle Menschen e.V.", "Organisation Intersex International (OII) Europe", "Intersex Denmark", "European Society for Paediatric Endocrinology", "Lawson Wilkins Endocrine Society"], "themes": ["Intersex Rights", "Bodily Integrity and Autonomy", "Informed Consent in Pediatric Medicine", "Non-consensual ''Normalizing'' Surgeries", "Gender Binary Stereotypes", "Psychosocial Support in Healthcare", "Medical Ethics and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2c80d71e370a804da295ff7afc31c04c263f8a466570d96e64a9c5523ea14ea4', 'AmSocPainMgmtNursing Circ 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2c80d71e370a804da295ff7afc31c04c263f8a466570d96e64a9c5523ea14ea4.pdf', 'policy_guideline', 'ingested', '{"date": "2011", "description": "This position statement from the American Society for Pain Management Nursing (ASPMN) asserts that healthcare professionals have an ethical and clinical obligation to provide optimal pain management before, during, and after male infant circumcision. Emphasizing that unmanaged pain leads to immediate physiological distress and long-term altered pain responses, the statement details multi-modal pain strategies integrating pharmacologic interventions, local anesthesia, and non-pharmacologic comfort techniques.\n\nThe document provides concrete practice recommendations for nursing staff, prescribers, and healthcare institutions. Recommended protocols include the pre-emptive use of oral acetaminophen and topical anesthetic creams, local anesthetic blocks (such as dorsal penile nerve block or subcutaneous ring block), intraoperative comfort measures like oral sucrose or breast milk, and continued post-procedural pain management alongside comprehensive parental education.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Susan O\u2019Conner-Von", "Helen Turner", "Renee Manworren", "Sarah Leahy"], "organizations": ["American Society for Pain Management Nursing", "American Academy of Pediatrics", "American Pain Society"], "themes": ["Neonatal Pain Management", "Infant Circumcision", "Procedural Analgesia", "Pediatric Nursing Guidelines", "Medical Ethics and Beneficence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4c4d0066a97d143be9251369a08750ac96941a86dc33b6a094ed9120b174f1c0', 'ANA Position Nurse Ethics 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4c4d0066a97d143be9251369a08750ac96941a86dc33b6a094ed9120b174f1c0.pdf', 'policy_guideline', 'ingested', '{"date": "2016", "description": "This position statement from the American Nurses Association (ANA) defines the ethical obligation of nurses to uphold, protect, and promote the inherent dignity, worth, and human rights of all individuals across every practice setting. Drawing upon the Universal Declaration of Human Rights and the ANA Code of Ethics, the document outlines concrete recommendations for clinical nurses, educators, researchers, and administrators to challenge discriminatory practices, ensure informed consent, and eliminate health disparities.\n\nThe statement emphasizes that ethical nursing practice requires continuous advocacy, particularly for vulnerable populations with diminished capacity to self-advocate, such as pediatric, incarcerated, and critically ill patients. It underscores that human rights protections extend beyond the patient to encompass nurses and healthcare environments, asserting that safe, just, and non-discriminatory workplace cultures are essential to delivering quality care.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["S. R. Benatar", "M. Ssenyonjo", "J. Hendrick"], "organizations": ["American Nurses Association", "ANA Center for Ethics and Human Rights", "International Council of Nurses", "United Nations", "Amnesty International", "The Carter Center", "Human Rights Watch", "Physicians for Human Rights", "U.S. Department of Health & Human Services"], "themes": ["Nursing Ethics", "Human Rights Advocacy", "Social Justice", "Health Equity", "Patient Rights and Dignity", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('006bf5d61fbd278d77ab28235d3c212c4364588b379858fa94715e9fe3dfc485', 'Anand Pain in Infants NEJM1987.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/006bf5d61fbd278d77ab28235d3c212c4364588b379858fa94715e9fe3dfc485.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "The provided text contains only repeated digital watermarks and copyright notices from the New England Journal of Medicine archive, noting that the document was accessed via Cambridge University Library. There is no substantive article text, study findings, or editorial content present in the excerpt.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["The New England Journal of Medicine", "Cambridge University Library", "Massachusetts Medical Society"], "themes": ["Academic Publishing", "Copyright and Archiving"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5d2cfa2ec263d0d006b2c97c0ddd348911b54d75152aabb12b7b6b5737bd8603', 'Anderson-Giberson Circumcision+disability CritDisabDisc 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5d2cfa2ec263d0d006b2c97c0ddd348911b54d75152aabb12b7b6b5737bd8603.pdf', 'other', 'ingested', '{"date": "2025", "description": "This article analyzes routine neonatal male circumcision (RNC) in Canadian and Western contexts through the framework of critical disability studies (CDS). The author argues that RNC constitutes the non-consensual amputation of healthy, erogenous tissue, resulting in both sexual impairment and psychological distress that meet formal and socio-political definitions of disability, such as criteria under the Accessibility for Ontarians with Disabilities Act (AODA).\n\nDrawing upon core principles of CDS outlined by Geoffrey Reaume, the paper investigates the lived experiences of circumcised men, challenges conventional medicalized discourse that minimizes the function of the foreskin, and examines community responses including intactivism and foreskin restoration. The author calls for formal institutional recognition of circumcision-induced disability, the provision of targeted accommodations and affirming psychotherapy, and policy interventions to protect children from non-therapeutic genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dale Andersen-Giberson", "Geoffrey Reaume", "Brian D. Earp", "Brian J. Morris"], "organizations": ["Canadian Paediatric Society", "American Academy of Pediatrics", "Intact America", "National Organization of Circumcision Information Resource Centers (NOCIRC)"], "themes": ["Critical Disability Studies", "Routine Neonatal Circumcision", "Genital Autonomy and Consent", "Foreskin Restoration", "Sexual Dysfunction and Impairment", "Medicalization and Structural Violence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('865c02b5873ca79b2d979e73859006e22842983562e06b15aa1d78693240cfb5', 'Aniaka Best Interest Canada 2013 (paper).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/865c02b5873ca79b2d979e73859006e22842983562e06b15aa1d78693240cfb5.pdf', 'legal_document', 'ingested', '{"date": "2012", "description": "This legal research paper examines whether infant male circumcision should be exempted on religious grounds from legal prohibitions against assault and child abuse, specifically within the context of Canadian law and the Canadian Charter of Rights and Freedoms. Tracing the religious and historical roots of circumcision, the author argues that the procedure lacks medical necessity, permanently deprives the child of healthy penile tissue, and amounts to non-consensual wounding and aggravated assault. Furthermore, the paper asserts that religious freedom under Section 2(a) of the Charter cannot justify violating a child''s bodily integrity or preempting their future autonomy to choose their own religious beliefs.\n\nDespite concluding that infant male circumcision is legally and ethically impermissible without the child''s informed consent, the author acknowledges the practical and emotional difficulties of criminally prosecuting parents under the ''best interests of the child'' standard. Consequently, the paper advocates for non-confrontational remedies over direct criminalization\u2014including public education, physician accountability via civil actions for battery and medical malpractice, and collaborative dialogue with religious communities to promote non-cutting alternative rituals such as Brit Shalom.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Oluchi Aniaka", "Margaret A. Somerville", "David L. Gollaher", "Leonard B. Glick", "William E. Brigman", "Dena S. Davis"], "organizations": ["Canadian Institutes of Health Research", "Canadian Paediatric Society", "American Academy of Pediatrics", "Supreme Court of Canada", "Canadian Children''s Rights Council"], "themes": ["Infant Male Circumcision", "Best Interests of the Child", "Freedom of Religion", "Bodily Integrity and Autonomy", "Aggravated Assault and Child Abuse", "Canadian Charter of Rights and Freedoms", "Informed Consent and Medical Malpractice"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fe185b4e4e471c7431f43404b5ba30cacc573e39cc55c0670e93083b4e228a6d', 'Anonymous Circ Oppress Med Colonizer CSW 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fe185b4e4e471c7431f43404b5ba30cacc573e39cc55c0670e93083b4e228a6d.pdf', 'other', 'ingested', '{"date": "2018", "description": "This article presents a critical reflection and deconstruction of routine neonatal male circumcision, framing the procedure as an unacknowledged form of medical colonization and oppression enacted upon a vulnerable population. Using an autoethnographic narrative of personal trauma resulting from an infant circumcision and subsequent corrective surgery, the author analyzes how the practice inflicts personal, cultural, and structural oppression by permanently altering infants'' bodies without informed consent, adequate pain management, or sound medical necessity.\n\nThe author critiques prevailing medical arguments regarding disease and HIV prevention, contrasting them with the physiological and psychological risks of the procedure and drawing parallels between male circumcision and female genital mutilation. Concluding that the biopsychosocial risks heavily outweigh potential benefits, the paper issues a call to action for social workers to combat routine infant circumcision through narrative therapy, hospital-based advocacy, parenting education, and policy reform.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Stephen Moses", "Robert Bailey", "Bob Mullaly"], "organizations": ["University of Windsor", "American Academy of Pediatrics", "Canadian Paediatric Society", "Australian Association of Paediatric Surgeons", "World Health Organization"], "themes": ["Male Circumcision", "Medical Colonization", "Oppression and Vulnerability", "Bodily Autonomy and Consent", "Hegemonic Masculinity", "Social Work Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5fdea00e23b5f44e0de679696ec4b9689b563c601fcb79e15de95e4dfa9a5158', 'Antonazzo Problems Criminalizing FGM PeaceReview 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5fdea00e23b5f44e0de679696ec4b9689b563c601fcb79e15de95e4dfa9a5158.pdf', 'other', 'ingested', '{"date": "2003", "description": "This article examines the unintended and counterproductive consequences of enacting nationwide bans to criminalize female genital cutting (FGC) in African nations. The author argues that top-down criminalization, heavily influenced by Western anti-FGC campaigns and international pressure, fails to address the underlying cultural, social, and economic reasons women perpetuate the tradition. Rather than ending the practice, legislative bans often drive FGC underground, cause girls to be cut at younger ages under more dangerous conditions, prevent victims from seeking medical aid, and provoke nationalist resistance against perceived cultural imperialism.\n\nInstead of coercive legal prohibitions, the author advocates for community-led, culturally nuanced strategies initiated by African women. Effective alternative models include collective community pledges (such as the convention model implemented by Tostan in Senegal), the creation of alternative coming-of-age ceremonies without cutting, and addressing broader structural issues such as women''s access to education, healthcare, and economic independence. The article concludes that external aid should support these locally driven educational and empowerment efforts rather than forcing unenforceable criminal statutes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Monica Antonazzo", "Hillary Rodham Clinton", "Fuambai Ahmadu", "Gerry Mackie", "David M\u2019Naikiuru"], "organizations": ["United Nations", "World Health Organization", "United Nations Children''s Fund", "United Nations Population Fund", "U.S. Department of State", "Tostan", "American College of Obstetricians and Gynecologists", "International Federation of Gynecology and Obstetrics", "American Medical Association"], "themes": ["Female Genital Cutting", "Criminalization and Legal Deterrence", "Cultural Imperialism vs. Cultural Relativism", "Community-Based Intervention", "Women''s Rights and Autonomy", "Public Health and Medicalization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('726b25d660a989ec3a79c12102d08fcb56a9451a74e7c9a413c111d6f0578419', 'Auchter Forced Male Circ Kenya Gender based violence  2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/726b25d660a989ec3a79c12102d08fcb56a9451a74e7c9a413c111d6f0578419.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic article examines forced adult male circumcision and genital mutilation as forms of gender-based sexual violence, focusing on the post-election violence in Kenya in 2007\u20132008. The author argues that prevailing international legal frameworks and human rights norms rely on essentialist views of gender that equate sexual violence exclusively with female victims, thereby treating men as inviolable aggressors rather than potential victims. As a result, forced circumcisions perpetrated by Kikuyu militias against Luo men were classified by the International Criminal Court (ICC) as ''other inhumane acts'' rather than sexual violence, undermining accountability and healthcare redress for male victims.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jessica Auchter", "Walter Odondi", "Raila Odinga", "Mwai Kibaki", "Uhuru Kenyatta", "Luis Moreno-Ocampo", "Charli Carpenter", "Dustin Lewis", "Anjali Manivannan", "Wanjiru Kamau-Rutenberg", "Judith Okal"], "organizations": ["International Criminal Court", "Oxford University Press", "The Royal Institute of International Affairs", "United Nations", "Mungiki", "Coalition on Violence Against Women in Kenya", "Kenyans for Peace through Truth and Justice"], "themes": ["Gender-Based Violence", "Forced Circumcision", "International Humanitarian Law", "Post-Election Violence in Kenya", "Masculinity and Gender Essentialism", "Human Rights and International Criminal Prosecution"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('62b207cbb72188d185139d5072ee5ed091215fdce535a4ffece078e97a994dc5', 'Aydur Childhood Circ Adult Sexual Function IJIR 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/62b207cbb72188d185139d5072ee5ed091215fdce535a4ffece078e97a994dc5.pdf', 'other', 'ingested', '{"date": "2007-06-05", "description": "This document is an interlibrary loan request cover sheet from the Johns Hopkins University Welch Medical Library. The request was submitted on behalf of patron Gillian Longley at the University of Colorado Denver Auraria Library for an academic article titled ''Effects of childhood circumcision age on adult male sexual functions'' by E. Aydur and colleagues, published in the International Journal of Impotence Research in February 2007.\n\nThe sheet contains transaction and routing metadata, including lending strings, document tracking identifiers, transmission IP addresses, and delivery specifications for fulfilling the requested journal article between academic libraries.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Gillian Longley", "E Aydur", "S Gungor", "S T Ceyhan", "L Taiimaz", "I Baser"], "organizations": ["Welch Medical Library", "Johns Hopkins University", "International Society for Impotence Research", "University of Colorado Denver", "Auraria Library"], "themes": ["Interlibrary Loan", "Male Sexual Function", "Circumcision", "Academic Publishing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('510743c75b742401c0720499eda311c32cc50a71c462fb7e278107b10361f6b3', 'Backes Bailey Moses Circ HPV Int J Cancer 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/510743c75b742401c0720499eda311c32cc50a71c462fb7e278107b10361f6b3.pdf', 'medical_journal', 'ingested', '{"date": "2012-04-15", "description": "This study evaluated the association between male circumcision and human papillomavirus (HPV)-associated penile lesions among 275 Kenyan men enrolled in a randomized controlled trial in Kisumu, Kenya. Penile examinations via colposcopy after 3% acetic acid application and HPV DNA testing demonstrated that circumcised men had a significantly lower prevalence of flat penile lesions (0.7%) compared to uncircumcised men (26.0%).\n\nFlat penile lesions were strongly associated with HPV DNA positivity, high-risk HPV types (particularly HPV 56 and 16), and high HPV 16/18/31 viral loads, especially on the glans. The findings indicate that male circumcision substantially reduces the prevalence of flat penile lesions, providing a viable strategy to potentially decrease male-to-female HPV transmission and reduce the burden of cervical cancer in high-incidence regions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Danielle M. Backes", "Maaike C.G. Bleeker", "Chris J.L.M. Meijer", "Michael G. Hudgens", "Kawango Agot", "Robert C. Bailey", "J.O. Ndinya-Achola", "Juma Hayombe", "Cornelis J.A. Hogewoning", "Stephen Moses", "Peter J.F. Snijders", "Jennifer S. Smith"], "organizations": ["University of North Carolina, Chapel Hill", "VU University Medical Center", "Impact Research and Development Organization", "University of Illinois at Chicago", "University of Nairobi", "Nyanza Reproductive Health Society", "Albert Schweitzer Hospital", "University of Manitoba", "National Cancer Institute", "National Institutes of Health", "Canadian Institutes of Health Research"], "themes": ["Male Circumcision", "Human Papillomavirus (HPV)", "Flat Penile Lesions", "Cervical Cancer Prevention", "Sexually Transmitted Infections", "HPV Viral Load"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('84dc308e9ab25db837aa788b48bbcdccb3e5d8844f81a20f3a3a29759f0eec0f', 'Baker Rock Circumstraint Mother Underground 1990.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/84dc308e9ab25db837aa788b48bbcdccb3e5d8844f81a20f3a3a29759f0eec0f.pdf', 'other', 'ingested', '{"date": "1990", "description": "This document excerpt from Issue 15 of ''Mother''s Underground'' features a prominent quote by author and activist Audre Lorde. The quote reflects on internal anger, describing it as an innate and deeply familiar emotional response that often serves as an easier defense mechanism than enduring pain.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Audre Lorde"], "organizations": ["Mother''s Underground"], "themes": ["Anger", "Emotional Pain", "Psychological Reflection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c08bcdccdb27e3f755cc01e5c9a93eb356b617b099021ce3e32b267864f257bf', 'Baker Should cosmetic circ be criminalized NewCrimLawRev 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c08bcdccdb27e3f755cc01e5c9a93eb356b617b099021ce3e32b267864f257bf.pdf', 'legal_document', 'ingested', '{"date": "2014", "description": "In this article, Dennis J. Baker argues that unnecessary, nontherapeutic cosmetic surgery carrying a high risk of serious bodily harm constitutes wrongful physical harm rather than genuine medicine, and therefore should be criminalized. Drawing on the harm principle and common law precedents\u2014notably the English House of Lords decision in R. v. Brown\u2014Baker posits that patient consent cannot legally or morally justify the infliction of actual or grievous bodily harm for purely aesthetic or commercially driven ends.\n\nThe author places particular emphasis on minors, advocating for a blanket statutory prohibition against performing nontherapeutic cosmetic surgery on individuals under the age of 18. Baker contends that minors possess diminished capacity and heightened vulnerability to social and commercial pressures, arguing that parental consent or the ''mature minor'' doctrine should not permit procedures with significant long-term risks, such as labiaplasty or breast augmentations, which should instead be addressed through psychological counseling.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Dennis J. Baker", "Lord Mustill", "Lord Jauncey", "Andrew Horne"], "organizations": ["King''s College London", "University of California Press", "House of Lords", "National Health Service", "American Society of Plastic Surgeons", "Law Commission for England and Wales"], "themes": ["Criminal Law and Criminalization", "Harm Principle", "Limits of Consent", "Protection of Minors", "Nontherapeutic Cosmetic Surgery", "Medical Ethics and Necessity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('240b55cd08a1a28c8834ef12f532fa26822d2cea4a1916b121d83d205c917280', 'Banasik Polish Law ProgHlthSci 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/240b55cd08a1a28c8834ef12f532fa26822d2cea4a1916b121d83d205c917280.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This academic paper examines the legality of non-therapeutic male infant circumcision under Polish criminal law, specifically focusing on ritual Jewish neonatal circumcision performed by a mohel. The author concludes that while the surgical removal of the foreskin technically fulfills the statutory elements of a criminal offence involving medium bodily injury under the Polish Penal Code, the act is not legally punishable.\n\nThe author argues that the unlawfulness of the act is precluded by an uncodified customary justification (kontratyp). By balancing competing legal interests\u2014the child''s physical integrity and future self-determination versus parental religious rights and communal religious tradition\u2014the customary justification confers ''secondary legality'' upon the procedure, rendering the mohel''s conduct lawful under current Polish law.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Banasik K."], "organizations": ["Andrzej Frycz Modrzewski Krakow University", "Medical University of Bia\u0142ystok", "Landgericht K\u00f6ln"], "themes": ["Male Circumcision", "Polish Criminal Law", "Religious Freedom vs. Bodily Integrity", "Customary Justifications (Kontratypy)", "Bodily Injury and Penal Liability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fb2d824f9906e4db39ecc08e8fbc111fd4440544f1a85ec74386fc65d6efdc7f', 'Bankirer Jewish feminist opposition to circumcision.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fb2d824f9906e4db39ecc08e8fbc111fd4440544f1a85ec74386fc65d6efdc7f.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This study examines the growing opposition to the traditional Jewish rite of circumcision among secular mothers in Israeli society. Utilizing qualitative constructivist research through in-depth interviews and a literature review, the authors investigate the socio-demographic and ideological traits of mothers who decided against circumcising their sons.\n\nThe findings reveal that decisions were predominantly emotional and mother-initiated, typically by older, highly educated, and atheist women who prioritized child-rearing over career expectations. The researchers conclude that rejecting circumcision serves as an assertion of feminine values, motherhood, and the protective mother-child bond over traditional, militaristic, and ritualistic cultural norms, reflecting broader individualistic shifts within modern Israeli society.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Y. Bankirer", "Y. Abramovich", "S. Gooldin", "M. Kotler"], "organizations": ["Ness-Ziona Mental Health Center", "Tel Aviv University", "Beer Yaacov Mental Health Center", "The Hebrew University of Jerusalem"], "themes": ["Jewish Circumcision", "Motherhood", "Feminism", "Secularization", "Israeli Society", "Individualism", "Parent-Child Dyad"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('286f20852c4801db547ca501403776c7ff32bd65e72da475f55f9db34b6b5bc3', 'Barker Benfield Sex Surg Late 19th Cent IntJHealthSvcs 1975.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/286f20852c4801db547ca501403776c7ff32bd65e72da475f55f9db34b6b5bc3.pdf', 'medical_journal', 'ingested', '{"date": "1975", "description": "This article examines the rise of gynecology and sexual surgery in late nineteenth-century America, arguing that the medical profession''s aggressive surgical interventions on women\u2014specifically clitoridectomy and female castration (oophorectomy)\u2014were direct reactions to male anxiety surrounding female emancipation, shifting sex roles, and post-Civil War social instability. Medical theory embraced ''somaticism'' and mechanical materialism, positing that a woman''s mind, character, and alleged moral or mental disorders were governed entirely by her reproductive organs, thus justifying invasive surgery to enforce traditional submission and domestic roles.\n\nThe author further details how the gynecological specialty developed through drastic experimentation, often beginning with marginalized patients such as enslaved women and poor immigrants before expanding to affluent middle- and upper-class women. The paper highlights the complex symbiotic dynamic between authoritative male physicians and disordered patients, the suppression of female sexuality and reproductive autonomy, and how the subsequent iatrogenic physical and psychological harm eventually compelled early shifts toward psychosomatic medicine and conservative surgical practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ben Barker-Benfield", "Charles Meigs", "Isaac Ray", "Augustus Kinsley Gardner", "Alfred Still\u00e9", "J. Marion Sims", "Robert Battey", "Isaac Baker Brown", "S. Weir Mitchell", "Ely Van de Warker"], "organizations": ["American Medical Association", "American Gynecological Society", "American Historical Association", "Woman''s Hospital"], "themes": ["History of Gynecology", "Female Emancipation and Anti-Feminism", "Somaticism and Medical Materialism", "Female Castration and Clitoridectomy", "Victorian Gender Norms", "Medicalization of Female Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('db2aa5e0288453c0339dd8972aefd8c6fcc9cf5839a845e74eee3d326f211cba', 'Barrett CLR JAMA Peds Circ Page Correction Analysis 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/db2aa5e0288453c0339dd8972aefd8c6fcc9cf5839a845e74eee3d326f211cba.pdf', 'other', 'ingested', '{"date": "2025-12-24", "description": "This report evaluates the impact of an ethics and advocacy intervention concerning a JAMA Pediatrics Patient Page titled ''What Parents Should Understand About Infant Male Circumcision.'' Following a formal complaint submitted on November 18, 2025, by Kevin Barrett to the AMA Editorial Governance Committee and the Committee on Publication Ethics (COPE), JAMA Pediatrics issued a substantial correction on December 19, 2025. The revisions removed reliance on an expired 2012 American Academy of Pediatrics policy, qualified overstated health claims, eliminated unsupported numerical comparisons, and expanded conflict of interest disclosures.\n\nThe analysis demonstrates a direct causal link between the formal governance-level complaint and the journal''s corrective actions. Key modifications include replacing non-neutral terminology with terms like ''intact penis,'' recognizing ethical debates surrounding bodily autonomy and informed consent, acknowledging the foreskin as specialized tissue, and tempering claims regarding sexual function and immediate medical benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kevin Barrett", "Thompson", "Van Howe", "Bryan Garner"], "organizations": ["Circumcision Law Reform", "JAMA Pediatrics", "American Academy of Pediatrics", "American Medical Association", "Committee on Publication Ethics"], "themes": ["Infant Male Circumcision", "Medical Ethics and Bodily Autonomy", "Editorial Integrity and Publication Ethics", "Informed Consent", "Conflict of Interest Disclosure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8ddbd0b7f6ed015192d190f663ac9b2c0e4cb1229fffa23ca411e7b660180e8a', 'Bashi Parental regret JPedUrol 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8ddbd0b7f6ed015192d190f663ac9b2c0e4cb1229fffa23ca411e7b660180e8a.pdf', 'medical_journal', 'ingested', '{"date": "2024-10-02", "description": "This study evaluates the rate and predictors of parental decisional regret following elective post-neonatal circumcision under general anesthesia. Analyzing 130 pediatric patients whose parents completed the Decision Regret Scale (DRS) questionnaire, the authors found that 13.8% of parents experienced regret (11.5% mild, 2.3% moderate-to-strong), which is lower than regret rates previously observed for other pediatric urologic procedures such as hypospadias repair.\n\nParental regret did not significantly vary based on clinical factors, age, or whether the procedure was performed for medical or cultural/religious reasons. The only statistically significant predictor of regret was the time elapsed since the procedure, with an interval longer than 33.4 months predicting an absence of regret, indicating that parental negative attitudes diminish over time.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tomer Bashi", "Hadas Rorman", "Ziv Savin", "Noam Bar-Yaakov", "Snir Dekalo", "Jacob Ben-Chaim", "Yuval Bar-Yosef"], "organizations": ["Dana-Dwek Children\u2019s Hospital", "Tel-Aviv Medical Center", "Tel-Aviv University", "American Academy of Pediatrics", "Journal of Pediatric Urology Company", "Elsevier Ltd."], "themes": ["Pediatric Urology", "Post-neonatal Circumcision", "Parental Decisional Regret", "Decision Regret Scale (DRS)", "Surgical Outcomes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f0521e6d8bbb0ed34d7d9a51e1b54f1fac5b76f920aa8d128174493ea992cd93', 'Baumgarten Marked_and_Unmarked_Flesh 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f0521e6d8bbb0ed34d7d9a51e1b54f1fac5b76f920aa8d128174493ea992cd93.pdf', 'other', 'ingested', '{"date": "2008", "description": "This article is an academic review essay by Elisheva Baumgarten evaluating two 2005 books concerning the history, theology, and cultural practice of circumcision. The first, Shaye J. D. Cohen''s ''Why Aren\u2019t Jewish Women Circumcised? Gender and Covenant in Judaism'', analyzes rabbinic and medieval textual traditions regarding gender, female inclusion in the covenant, and Jewish identity amidst Christian polemics. The second, Leonard B. Glick''s ''Marked in Your Flesh: Circumcision from Ancient Judea to Modern America'', takes an anthropological approach tracing circumcision from an ancient Jewish rite to its widespread medicalization and adoption as routine neonatal surgery in modern America.\n\nBaumgarten compares the methodologies and persuasiveness of both scholars, noting that Cohen provides a rigorous, objective textual examination of ancient and medieval Jewish thought. Conversely, she notes that Glick writes from an openly critical perspective advocating for the abandonment of the practice, which at times affects the fairness of his historical presentation. Ultimately, Baumgarten recommends both works for their valuable contributions to the study of a central, ancient ritual.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Elisheva Baumgarten", "Shaye J. D. Cohen", "Leonard B. Glick", "Moses Maimonides", "Jacob Anatoli", "Joseph Bekhor Shor", "Philo of Alexandria"], "organizations": ["Bar Ilan University", "Purdue University Press", "University of California Press", "Oxford University Press", "University of Pennsylvania", "Society for Humanistic Judaism"], "themes": ["Circumcision", "Jewish Identity and Covenant", "Gender and Rabbinic Judaism", "Medicalization of Ritual", "Christian-Jewish Polemics", "History of Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dfc031c4073a097fa62a51f5b4cee938306e42b2fcffdc9ff2e67d02c21d6346', 'Bañuelos Marco Blessing or Curse IJIR 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dfc031c4073a097fa62a51f5b4cee938306e42b2fcffdc9ff2e67d02c21d6346.pdf', 'medical_journal', 'ingested', '{"date": "2020-09-29", "description": "This narrative review investigates the impact of childhood and neonatal male circumcision on adult male sexual function, psychological well-being, and overall health. Analyzing literature published between 1986 and 2020, the authors find insufficient histological, anatomical, or clinical evidence to support claims that circumcision leads to sexual dysfunctions such as premature ejaculation or diminished penile sensitivity. Instead, sexual satisfaction appears heavily influenced by psychological factors, body image perception, and the sociocultural environment in which an individual matures.\n\nWhile circumcision offers clear prophylactic benefits\u2014notably reducing rates of urinary tract infections, sexually transmitted infections including HIV and HPV, and penile inflammatory conditions\u2014the controversy surrounding routine neonatal circumcision persists. The authors conclude that rather than characterizing circumcision as inherently a blessing or a curse, clinical counseling should focus on objective medical facts and cultural context so parents can make informed decisions, mitigating potential negative psychological impacts on developing children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Beatriz Ba\u00f1uelos Marco", "Jessica Leigh Garc\u00eda Heil"], "organizations": ["Charite Universit\u00e4tsmedizin Berlin", "London School of Hygiene and Tropical Medicine", "American Academy of Pediatrics", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "Sexual Dysfunction", "Premature Ejaculation", "Psychosexual Development", "Preventive Health and STIs"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a8f5aacbc8e134cbc1094aea8214b58fe5fd15970d289e8ea353c6217c53ef03', 'BC College of Physicians Circ Policy 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a8f5aacbc8e134cbc1094aea8214b58fe5fd15970d289e8ea353c6217c53ef03.pdf', 'policy_guideline', 'ingested', '{"date": "2009", "description": "This policy guideline issued by the College of Physicians and Surgeons of British Columbia addresses routine infant male circumcision in light of modern evidence-based medicine, ethics, human rights, and law. The College highlights that routine circumcision of healthy male infants is a non-therapeutic and medically unnecessary cosmetic procedure whose potential risks outweigh any documented prophylactic health benefits. While acknowledging the procedure''s deep significance within Jewish and Islamic traditions, the document questions the ethics of parental proxy consent for an irreversible, non-essential surgery on an individual unable to provide consent.\n\nThe guideline advises physicians to inform parents of the current medical consensus and the ethical dimensions regarding an infant''s right to bodily integrity. Physicians are not obligated to perform routine circumcisions, though those who choose to do so for cultural or religious reasons must ensure they possess the necessary surgical competence, obtain valid signed consent from both parents, and provide appropriate analgesia and aftercare.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["M. Somerville", "T. Szaz", "J. Goodman", "D. Richards"], "organizations": ["College of Physicians and Surgeons of British Columbia", "Canadian Paediatric Society", "American Academy of Pediatrics", "American Urological Society", "Canadian Medical Association", "British Medical Association"], "themes": ["Infant Male Circumcision", "Bioethics and Medical Ethics", "Informed and Proxy Consent", "Bodily Integrity and Human Rights", "Evidence-Based Medicine", "Religious and Cultural Traditions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e31351e5ac663be4ce98b4ed8ddfc79072e2c8a203d5dfbda56e955805c5056a', 'Begley Willingness_of_circ in MSM PloSOne 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e31351e5ac663be4ce98b4ed8ddfc79072e2c8a203d5dfbda56e955805c5056a.pdf', 'medical_journal', 'ingested', '{"date": "2008-07-16", "description": "This study evaluates the acceptability and willingness of adult men who have sex with men (MSM) in the United States to undergo circumcision as an HIV prevention strategy, should it be proven effective for this population. Surveying 780 presumed HIV-negative MSM attending gay pride events in 2006, researchers identified 133 uncircumcised individuals, of whom 53% expressed willingness to undergo adult circumcision. Willingness was significantly higher among Black MSM, individuals who reported non-injection drug use, and those who perceived circumcision as offering protection against penile cancer, while primary concerns centered on postoperative pain and wound infection.\n\nThe authors conclude that adult circumcision demonstrates substantial acceptability among uncircumcised U.S. MSM, particularly among Black MSM who bear a disproportionate burden of HIV diagnoses. However, because circumcision offers only partial protection and may be misunderstood as eliminating the need for condoms, the authors emphasize that any future clinical recommendations must integrate educational outreach addressing perceived risks, surgical benefits, and the continued necessity of comprehensive safer-sex practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Elin B. Begley", "Krishna Jafa", "Andrew C. Voetsch", "James D. Heffelfinger", "Craig B. Borkowf", "Patrick S. Sullivan", "Landon Myer"], "organizations": ["Centers for Disease Control and Prevention", "National Center for HIV/AIDS, Viral Hepatitis, STD, and TB Prevention", "World Health Organization"], "themes": ["HIV/AIDS Prevention", "Adult Male Circumcision", "Men Who Have Sex with Men (MSM)", "Racial Health Disparities", "Sexual Health and Risk Behaviors"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('81662b2b221fa571d952c12c762b2ea4ecdfa1b96d04fe813378c54e68d5c1e1', 'Behrens-Traditional-male-circumcision SouthAfrMedJ 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/81662b2b221fa571d952c12c762b2ea4ecdfa1b96d04fe813378c54e68d5c1e1.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This article examines the ethical and legal conflict between protecting cultural rights and preventing severe, avoidable harm related to traditional male circumcision in South Africa. Highlighting alarming statistics of hospitalizations, penile amputations, and deaths among initiates, the author argues that while cultural traditions are vital for identity and restorative justice, the constitutional right to culture is limited and must not supersede the fundamental rights to life, bodily integrity, and health.\n\nRather than calling for the abolition of traditional male circumcision, the paper asserts that the government and traditional leadership have an urgent moral and constitutional obligation to regulate the practice effectively. By improving oversight, training, postoperative care, and cooperation between health authorities and traditional leaders, the rite can be preserved while eliminating preventable medical tragedies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["K G Behrens", "Steve Biko", "Charles Taylor", "Will Kymlicka", "Thembela Kepe"], "organizations": ["University of the Witwatersrand", "Steve Biko Centre for Bioethics", "South African Medical Journal", "Congress of Traditional Leaders of South Africa", "National Department of Health"], "themes": ["Traditional male circumcision", "Bioethics", "Cultural rights", "Harm prevention", "Public health regulation", "Human rights and constitutional law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('01373a229a392a8707a7be0fee53fde6b12007b9af7fcbdd09ed066e3cb43114', 'Behrns To Cut or Not to Cut Jewish WMBRJ 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/01373a229a392a8707a7be0fee53fde6b12007b9af7fcbdd09ed066e3cb43114.pdf', 'legal_document', 'ingested', '{"date": "2013", "description": "This article examines proposed bans on male infant circumcision, particularly highlighting the 2011 San Francisco ballot initiative, and assesses whether such prohibitions can withstand legal scrutiny concerning Jewish and Muslim families. The author analyzes the issue through two distinct legal frameworks: a parental rights theory and a child-centered best-interests standard. Under the parental rights model, combining Fourteenth Amendment parental rights with First Amendment Free Exercise claims triggers strict scrutiny under the constitutional ''hybrid-rights'' doctrine. Because circumcision is a safe procedure with minimal health risks and does not threaten life or cause grievous injury, the state lacks a compelling interest to override parental choice, meaning total bans fail strict scrutiny.\n\nUnder the child-centered best-interests framework, the author concludes that male infant circumcision serves the child''s medical and psychosocial interests. Drawing upon empirical medical research and policy statements from the American Academy of Pediatrics, the article highlights significant preventive health benefits, including reduced transmission rates of UTIs and STIs. Furthermore, the author emphasizes the psychological and sociological advantages of religious solidarity and integration within Jewish and Muslim communities, noting that preventing circumcision risks alienating the child and causing social ostracism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Andrew E. Behrns", "Jerry Brown", "Aaron A. R. Tobian", "Ronald H. Gray"], "organizations": ["William & Mary Law School", "American Academy of Pediatrics", "American Medical Association", "Centers for Disease Control and Prevention", "Jewish Community Relations Council of San Francisco"], "themes": ["Male Infant Circumcision", "Parental Rights", "Free Exercise of Religion", "Hybrid-Rights Doctrine", "Best Interests of the Child", "Parens Patriae", "Jewish and Islamic Traditions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('852d70e879f9318f2a2001391155f2c515265ce8dfd5e6428fe3fdd8adc5a1e4', 'Belgian Bioethics Stmt 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/852d70e879f9318f2a2001391155f2c515265ce8dfd5e6428fe3fdd8adc5a1e4.pdf', 'policy_guideline', 'ingested', '{"date": "2017-05-08", "description": "This document, Opinion no. 70 issued by the Belgian Advisory Committee on Bioethics, examines the ethical, legal, medical, and anthropological dimensions of nonmedical male circumcision, particularly when performed on minors. The inquiry was initiated by Dr. Georges Bauherz of the IRIS South Hospitals ethics committee, focusing on whether nontherapeutic circumcision should be permitted, performed by hospital doctors, financed by public health insurance, and distinguished from female genital mutilation. Committee members presented divided viewpoints: some argued that religious freedom and parental rights justify the practice provided safeguards and pain management are observed, while others maintained that it violates a child''s bodily integrity and right to future informed consent, urging postponement until adulthood. Ultimately, the Committee unanimously recommended that nonmedical circumcisions should not be financed by social security and suggested shifting toward symbolic rituals that avoid bodily cutting, while advising against immediate legislative prohibition.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Georges Bauherz", "B\u00e9atrice Toussaint", "Robert Rubens", "Jules Messinne", "Julien Libbrecht", "Cathy Herbrand", "Marie-Genevi\u00e8ve Pinsart", "Jacqueline Herremans", "Richard Rega", "Francine Malotaux", "T. Gergely", "P. Hoebeke", "X. Luffin", "R. Darby", "Bruno Bettelheim"], "organizations": ["Belgian Advisory Committee on Bioethics", "IRIS South Hospitals", "INAMI/RIZIV", "American Academy of Pediatrics", "Royal Dutch Medical Association", "World Health Organization", "UNAIDS", "Council of Europe", "Universit\u00e9 Libre de Bruxelles", "University Hospital Gent"], "themes": ["Nonmedical Male Circumcision", "Bioethics and Bodily Integrity", "Children''s Rights and Informed Consent", "Religious Freedom vs. Child Welfare", "Healthcare Financing and Social Security", "Comparison with Female Genital Mutilation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7a432b066eb8b87491907130fd4146a893f7313b33041936429b7ba5300fa595', 'Bell West Discourse MedAnthrQtr 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7a432b066eb8b87491907130fd4146a893f7313b33041936429b7ba5300fa595.pdf', 'medical_journal', 'ingested', '{"date": "2005", "description": "This article examines the disparate Western perceptions and dominant discourses surrounding male and female genital cutting. While female genital cutting has been widely condemned as a human rights violation and severe sexual mutilation, male circumcision in Western contexts remains largely normalized, defended, or met with public indifference. The author argues that this asymmetry cannot be explained solely by physiological differences or health outcomes, but rather reflects historically and culturally specific constructions of gender, sexuality, and bodily integrity in the West, which view male sexuality as resilient and drive-oriented while conceptualizing female sexuality as fragile, passive, and anatomically phallicized through direct comparisons between the clitoris and penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kirsten Bell", "Fran Hosken", "Carla Makhlouf Obermeyer", "Martha Nussbaum", "David Gollaher", "Anne Koedt", "Sigmund Freud"], "organizations": ["American Anthropological Association", "World Health Organization", "American Academy of Pediatrics", "Macquarie University"], "themes": ["Genital Cutting", "Male and Female Circumcision", "Western Discourses on Sexuality", "Medicalization and Culture", "Bodily Integrity and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('128d6d8f2029041c1e386c01153e9e9f57343d1ef8fc7e110bf9c1161a9b2c05', 'Bellieni Infant Pain IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/128d6d8f2029041c1e386c01153e9e9f57343d1ef8fc7e110bf9c1161a9b2c05.pdf', 'medical_journal', 'ingested', '{"date": "2022-04", "description": "This review evaluates clinical trials published over the past 20 years to determine the effectiveness of analgesic methods in mitigating pain during newborn male circumcision. By analyzing studies that used the modified Neonatal Infant Pain Scale (mNIPS), the author found that none of the evaluated analgesic interventions\u2014including EMLA cream, dorsal penile nerve block (DPNB), and ring block (RB)\u2014completely eliminated pain, with most assessments showing scores indicating clinically significant pain.\n\nThe document highlights that despite slight variations in pain scores across different surgical and anesthetic techniques, circumcision remains inherently painful for neonates. The author underscores the documented short- and long-term adverse neurological and developmental consequences of early-life pain, concluding that existing analgesia is insufficient to provide a painless procedure, which feeds into broader ethical questions regarding non-therapeutic infant circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Carlo Valerio Bellieni"], "organizations": ["Universit\u00e0 degli Studi di Siena", "Springer Nature Limited"], "themes": ["Neonatal Circumcision", "Pain Assessment and Management", "Neonatal Infant Pain Scale (NIPS)", "Pediatric Analgesia and Anesthesia", "Medical Ethics and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4ba5a5bc26835e6419c41103e29d32ee2484c1562258a0805161e3b0ca0680e5', 'Ben Smit Search of Real Circumcison  JStudNewTest 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4ba5a5bc26835e6419c41103e29d32ee2484c1562258a0805161e3b0ca0680e5.pdf', 'other', 'ingested', '{"date": "2017", "description": "This article examines the Apostle Paul''s treatment of circumcision across Galatians, Philippians, and Romans through the framework of ''ritual failure'' and ''ritual negotiation,'' drawing from ritual criticism theories developed by scholars such as Ronald Grimes and Ute H\u00fcsken. The author argues that Paul did not aim to abolish circumcision, but rather reevaluated physical circumcision as an ineffectual, misframed, or defeated ritual when relied upon as a requirement for justification and inclusion among Gentile converts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Peter-Ben Smit", "Paul the Apostle", "Ronald Grimes", "Ute H\u00fcsken"], "organizations": ["Vrije Universiteit Amsterdam", "Utrecht University", "University of Pretoria"], "themes": ["Ritual Failure", "Circumcision", "Pauline Epistles", "Ritual Criticism", "Early Christian Identity", "Intra-Jewish Debate"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('da85a1e63a38069c99853bcfe391429be1f4e1be22b01cbdaf5360616ef7fded', 'Ben-Yami Commentary JMedEth 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/da85a1e63a38069c99853bcfe391429be1f4e1be22b01cbdaf5360616ef7fded.pdf', 'medical_journal', 'ingested', '{"date": "2013-03-05", "description": "In this article, Hanoch Ben-Yami examines the ethical, religious, and legal controversies surrounding non-therapeutic infant male circumcision, particularly in Judaism and Islam. He argues that framing the issue as a collision between an individual''s right to bodily integrity and a community''s religious freedom fails to offer practical policy solutions. Moreover, an outright legal ban on circumcision would provoke intense social friction, evoke histories of religious persecution, and likely fail to stop the practice.\n\nInstead of prohibition, Ben-Yami advocates for moderate, harm-reducing regulatory reforms that do not fundamentally violate religious doctrines. He proposes three central measures: mandating local anesthesia administered by qualified medical professionals in certified clinics, banning oral suction (metzitzah b''peh), and establishing an upper age limit of around six months for non-therapeutic circumcisions of minors to minimize psychological trauma. He posits that these incremental legal and cultural steps would directly reduce harm while gradually encouraging communities to reinterpret traditions and decrease the frequency of the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hanoch Ben-Yami"], "organizations": ["Central European University", "Journal of Medical Ethics"], "themes": ["Male Circumcision", "Bioethics and Medical Law", "Bodily Integrity", "Freedom of Religion", "Metzitzah B''peh", "Harm Reduction", "Pediatric Pain Management"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('15d34f2cd32eb69d1563fde7927ed71af9991d12652144827f0f6d831199ca2c', 'Benyamini Circ_as_Regressive Conv 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/15d34f2cd32eb69d1563fde7927ed71af9991d12652144827f0f6d831199ca2c.pdf', 'other', 'ingested', '{"date": "2012", "description": "This academic text examines the Apostle Paul''s theological stance on circumcision and conversion, primarily analyzing the Epistle to the Galatians through anthropological and psychoanalytic frameworks. The author, Itzhak Benyamini, argues that Paul considered circumcision a ''regressive conversion'' back into the flesh and the Mosaic Law, which stood in direct contradiction to true spiritual conversion achieved purely through divine grace. Paul sought to eliminate bodily signs of distinction to foster a universal spiritual community founded on faith in Christ rather than external works.\n\nApplying theories from Sigmund Freud and Jacques Lacan, the analysis frames circumcision as a symbolic substitute for sacrifice and castration bound to the patriarchal Symbolic order and the Law of the Father. Benyamini contends that Paul attempted to replace this symbolic castration and desire with an Imaginary identification with the suffering Son (Christ), while demonstrating how historical anxieties surrounding circumcision as bodily mutilation intersected with castration anxiety, xenophobia, and early Christian anti-Semitism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Itzhak Benyamini", "Paul the Apostle", "Sigmund Freud", "Jacques Lacan", "Slavoj \u017di\u017eek", "Mark Goodacre"], "organizations": ["T&T Clark International", "Continuum", "British Library"], "themes": ["Pauline Theology", "Psychoanalytic Biblical Interpretation", "Circumcision and Conversion", "Symbolic Castration", "Castration Anxiety and Anti-Semitism", "Law versus Grace"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('285ff48fc6f45aebbbf53ce4d2183ce2c0cc04a5bac0fbe63f717f0b6c096673', 'Berry Acucullophilia Warbleton 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/285ff48fc6f45aebbbf53ce4d2183ce2c0cc04a5bac0fbe63f717f0b6c096673.pdf', 'other', 'ingested', '{"date": "2023-07-07", "description": "This document examines acucullophilia, an atypical sexual preference or paraphilia characterized by sexual attraction and arousal specifically toward a circumcised penis. It discusses potential psychological etiologies\u2014such as childhood experiences, personality dynamics, and substitution mechanisms\u2014and notes that the condition is primarily considered a disorder only when it impairs personal, social, or occupational functioning. While cognitive-behavioral therapy and psychotherapy are mentioned as treatment modalities, the text emphasizes that clinical research on non-criminal paraphilias remains limited and inconclusive.\n\nThe text also addresses the medical indications and controversies surrounding male circumcision. In an included commentary, Tim Hammond of the Genital Autonomy Legal Defense and Education Fund raises ethical and legal concerns, arguing that parents who project a circumcision fetish onto their sons by subjecting them to non-therapeutic circumcision may be committing child abuse and battery, violating a child''s fundamental human right to bodily integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Peter Berry", "Tim Hammond"], "organizations": ["Farlex, Inc.", "Warbleton Council", "Genital Autonomy Legal Defense and Education Fund"], "themes": ["Paraphilias and Fetishism", "Acucullophilia", "Male Circumcision", "Children''s Rights and Bodily Integrity", "Psychological Disorders and Treatment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7869303e31fa911ac917d3a1adde8e3d959b0701c08f1e11a08d8f17d607d820', 'Bhimji Infant Male Circumcision 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7869303e31fa911ac917d3a1adde8e3d959b0701c08f1e11a08d8f17d607d820.pdf', 'legal_document', 'ingested', '{"date": "2000-01-01", "description": "This document presents a legal, medical, and ethical analysis arguing that non-therapeutic infant male circumcision violates the Canadian Charter of Rights and Freedoms, Canadian criminal law, and international human rights conventions. The author contends that routine neonatal circumcision lacks proven medical benefit, entails surgical risks, and removes healthy, specialized erogenous tissue without the individual''s consent. Drawing parallels with female genital mutilation (FGM), the paper argues that Canadian law\u2014specifically Section 268 of the Criminal Code\u2014discriminates on the basis of sex by expressly criminalizing non-therapeutic genital cutting for females while failing to extend identical legal protections to males.\n\nFurthermore, the paper examines jurisprudence regarding parental proxy consent, religious freedom, and child welfare, maintaining that the child''s right to bodily integrity and security of the person under Section 7 of the Charter supersedes parental religious or cultural preferences. Relying on medical policy statements, Canadian court precedents (such as Re ''Eve''), and international treaties including the UN Convention on the Rights of the Child, the author concludes that infant male circumcision constitutes an unjustified form of assault that should be legally prohibited until the person is old enough to make an autonomous decision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Arif Bhimji", "Margaret Somerville", "Eike-Henner Kluge", "Christopher Price", "Thomas Szasz"], "organizations": ["Canadian Paediatric Society", "American Academy of Pediatrics", "British Medical Association", "Australasian Association of Paediatric Surgeons", "Ontario Human Rights Commission", "United Nations", "Supreme Court of Canada"], "themes": ["Infant Male Circumcision", "Canadian Charter of Rights and Freedoms", "Bodily Integrity", "Proxy and Informed Consent", "Gender Discrimination and Equal Protection", "Medical Ethics", "Human Rights Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('78161f5cdc482c5c647ec7438af0a1d058af92ba9e8856933063781bb5d4f51c', 'Bingawaho Circ Rwanda PLoS 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/78161f5cdc482c5c647ec7438af0a1d058af92ba9e8856933063781bb5d4f51c.pdf', 'medical_journal', 'ingested', '{"date": "2010-01-19", "description": "This study evaluates the cost-effectiveness of male circumcision (MC) across three hypothetical cohorts in Rwanda\u2014newborns, adolescents, and adults\u2014to guide national HIV prevention policy in a country where adult HIV prevalence is approximately 3%. By modelling direct intervention costs against projected lifetime savings from averted HIV care and treatment, the researchers determined that neonatal MC costs approximately US$15 per procedure and is net cost-saving over an individual''s lifetime. In contrast, adolescent and adult circumcisions cost approximately US$59 per procedure, yielding net costs per HIV infection averted of US$3,932 and US$4,949, respectively.\n\nThe authors conclude that Rwanda should implement a comprehensive strategy that prioritizes routine infant circumcision integrated into existing neonatal and vaccination services. While adolescent MC was found to be highly cost-effective and adult MC potentially cost-effective under WHO criteria, they recommend treating adolescent and adult MC as temporary ''catch-up'' campaigns that will eventually become redundant as routinely circumcised infant cohorts mature, providing a sustainable long-term public health approach to reducing HIV incidence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Agnes Binagwaho", "Elisabetta Pegurri", "Jane Muita", "Stefano Bertozzi", "Seth C. Kalichman"], "organizations": ["Ministry of Health, Kigali, Rwanda", "UNAIDS", "UNICEF", "National AIDS Control Commission of Rwanda (CNLS)", "Instituto Nacional de Salud P\u00fablica", "World Health Organization", "Rwanda National Institute of Statistics", "CAMERWA"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Cost-Effectiveness Analysis", "Public Health Policy", "Neonatal Healthcare", "Resource Allocation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('944cd78659353c3775d83efd47b4c90bfc97e63ff1e21a1004fcb64a7509e9db', 'Bock Tolerance-ritual-male-infant-circumcision AmJBio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/944cd78659353c3775d83efd47b4c90bfc97e63ff1e21a1004fcb64a7509e9db.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-12", "description": "In this commentary published in The American Journal of Bioethics, Gregory L. Bock responds to an article by Allan J. Jacobs and Kavita S. Arora concerning the ethical and legal status of ritual male infant circumcision. While Bock agrees with Jacobs and Arora that male infant circumcision does not violate basic human rights, he critiques their suggestion that states may justly ban the practice if it conflicts with local norms under a framework resembling John Locke''s principle of neutrality. Bock argues that laws of general applicability often reflect majority prejudices and can unjustly burden religious minorities, particularly Jewish communities for whom circumcision is an essential religious covenant.\n\nDrawing on the philosophical framework of Martha Nussbaum, Bock contends that the principle of religious accommodation is superior to Lockean neutrality for resolving these conflicts. Because male infant circumcision does not significantly compromise bodily integrity, adult sexual functioning, or central human capabilities, the state lacks a compelling interest to restrict it. Bock concludes that a truly just society should accommodate and tolerate ritual male infant circumcision regardless of local prevailing norms.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory L. Bock", "Allan J. Jacobs", "Kavita S. Arora", "John Locke", "Martha Nussbaum", "Baruch Spinoza"], "organizations": ["Walters State Community College", "Routledge", "Taylor & Francis", "Supreme Court of the United States"], "themes": ["Male Infant Circumcision", "Bioethics", "Religious Liberty", "Principle of Accommodation", "Lockean Neutrality", "Minority Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4e7324d489ce8c47c0b85893f0b59b53255d689fb4d52c030c255f5474c45b43', 'Bogacki-Rychlik NeurophysioMaleOrgasm Frontiers 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4e7324d489ce8c47c0b85893f0b59b53255d689fb4d52c030c255f5474c45b43.pdf', 'medical_journal', 'ingested', '{"date": "2024-01-24", "description": "This review paper analyzes the neurophysiology of male sexual arousal from a behavioral and physiological perspective, primarily utilizing rodent models to inform human sexuality. The authors propose a clear conceptual and operational distinction between sexual arousal, defined as an autonomic nervous system response culminating in penile erection triggered by specific sexual cues, and sexual motivation, which comprises actions that increase the likelihood of sexual interactions. By distinguishing these mechanisms alongside general arousal, the authors seek to improve translational transparency across basic, preclinical, and clinical research.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wiktor Bogacki-Rychlik", "Katarzyna Gaw\u0119da", "Michal Bialy", "Fabrizio Sanna", "Gabriela Rodriguez-Manzo", "Pekka Santtila", "Wendy Portillo", "Frank Beach", "Benjamin D. Sachs"], "organizations": ["Medical University of Warsaw", "Frontiers Media SA", "University of Cagliari", "National Polytechnic Institute of Mexico", "New York University Shanghai", "National Autonomous University of Mexico", "European Union"], "themes": ["Neurophysiology of Sexual Arousal", "Distinction Between Sexual Arousal and Sexual Motivation", "Autonomic Nervous System and Penile Erection", "Non-contact Erection (NCE) Test", "Central and Spinal Neural Circuits", "Preclinical Animal Models"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('89ee81464aea5eb118b098ec00d596107a8538075e648f775d07597ffc2fa352', 'Boldt v Boldt (Davis) JClinEthics 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/89ee81464aea5eb118b098ec00d596107a8538075e648f775d07597ffc2fa352.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This article analyzes the Oregon Supreme Court case Boldt v. Boldt, which centered on a custody dispute where a father who converted to Judaism wanted to circumcise his 12-year-old son, Misha, against the mother''s objections. Although the court recognized a custodial parent''s general legal authority over routine medical and religious choices, it remanded the case to ascertain the boy''s personal desires, as forcing the procedure could damage the parent-child relationship. Ultimately, the boy firmly opposed both conversion and circumcision, leading to the procedure being denied.\n\nAuthor Dena S. Davis explores the tension between parental legal custody, religious freedom, and medical ethics. She argues that while infant circumcision is typically deferred to parental discretion, an adolescent possesses sufficient developmental capacity to warrant autonomous decision-making and assent. Drawing parallels to Wisconsin v. Yoder, Davis emphasizes that physicians have an ethical duty under principles of bodily integrity and ''do no harm'' to respect a child''s dissent regarding elective, permanent procedures, irrespective of pure custody law.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dena S. Davis", "Doug Diekema", "Janet Dolgin", "Ron Brauner", "Jon Katz", "Noam Zohar", "John V. Geisheker"], "organizations": ["The Journal of Clinical Ethics", "Cleveland State University", "American Society for Bioethics and Humanities", "Supreme Court of Oregon", "Doctors Opposed to Circumcision", "American Jewish Congress", "Russian Orthodox Church"], "themes": ["Child Autonomy and Assent", "Male Circumcision", "Parental Rights vs. Children''s Rights", "Medical Ethics", "Religious Freedom", "Child Custody Disputes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('171e76324f7fe8d7fc764227d53aad4cda11638f8057576ee03ab61932825f17', 'Boldt v Boldt (Zohar) Circ Conversion JClinEthics 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/171e76324f7fe8d7fc764227d53aad4cda11638f8057576ee03ab61932825f17.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This article examines the ethical and legal questions surrounding the circumcision and conversion of a minor to Judaism through the lens of halakhah (Jewish normative law). The author evaluates whether circumcision is inherently beneficial or if its value exists primarily as a communal and covenantal marker rather than a universal bodily good. Drawing on rabbinic debate and medieval philosophy, particularly Maimonides, the text highlights the historical tension between natural bodily integrity and religious bodily alteration.\n\nThe author further explores the talmudic mechanism of converting a minor, noting that such conversions are traditionally conducted on behalf of the future adult under the presumption of benefit, but remain tentative and subject to annulment when the child reaches the age of majority. In contemporary contexts, however, a disparity exists between the traditional age of religious competence (thirteen) and modern secular legal majority (eighteen). The author warns that delaying circumcision and conversion until age eighteen could cause significant identity and social harm by excluding a desiring adolescent from communal participation during critical developmental years.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Noam Zohar", "Maimonides", "Rabbi Akiva", "Tinnieus Rufus", "Rav Yosef"], "organizations": ["The Journal of Clinical Ethics", "Bar-Ilan University"], "themes": ["Circumcision", "Conversion to Judaism", "Halakhah (Jewish Law)", "Pediatric Bioethics", "Best Interests of the Child", "Covenantal Identity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ad414c787af2de10cd34af08939706faa9d92341299f8493793df42e952e20a4', 'Boldt v Boldt Oregon 2004-2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ad414c787af2de10cd34af08939706faa9d92341299f8493793df42e952e20a4.pdf', 'other', 'ingested', '{"date": "2022-08-25", "description": "This document chronicles the legal proceedings and commentary surrounding the Oregon child-custody case Boldt v. Boldt. Originating in 2004, the dispute centered on a custodial father''s intention to have his nine-year-old son circumcised for religious conversion to Judaism, despite objections from both the boy and his mother. After decisions in lower courts, the Oregon Supreme Court ruled in 2008 that the child''s perspective and bodily integrity were critical factors warranting judicial evaluation to determine whether custody should be reconsidered.\n\nFollowing a denial of certiorari by the U.S. Supreme Court and an in-chambers hearing where the boy formally testified against the procedure, the circuit court prohibited the circumcision. By late 2009, the father voluntarily agreed to transfer primary physical custody to the mother. Legal and bioethical scholars view the case as a major legal precedent establishing the rights of minors to bodily integrity and judicial protection against non-therapeutic, elective surgical interventions driven solely by parental religious preferences.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Mikhail James Boldt", "Lia Nikolaevna Boldt", "James Harlan Boldt", "Clayton C. Patrick", "Lisa Greif", "John Geisheker", "Sherry F. Colb", "Douglas Diekema", "J. Steven Svoboda", "Marie Fox", "Michael Thompson"], "organizations": ["Jackson County Circuit Court", "Oregon Court of Appeals", "Oregon Supreme Court", "Supreme Court of the United States", "Doctors Opposing Circumcision (D.O.C.)", "American Jewish Congress", "American Jewish Committee", "Anti-Defamation League", "Union of Orthodox Jewish Congregations of America", "National Organization of Circumcision Information Resource Centers (NOCIRC)"], "themes": ["Genital Integrity", "Male Circumcision", "Child Custody", "Children''s Rights", "Religious Freedom vs. Minor Welfare", "Informed Consent and Bodily Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a8f45558d61f3ce3c670a4b94ea2174068ab2afd2caa8788b20953c342981297', 'Boldt v. Boldt (Diekema) JClinEthics 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a8f45558d61f3ce3c670a4b94ea2174068ab2afd2caa8788b20953c342981297.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This article analyzes the legal and bioethical dilemmas presented in the case of Boldt v. Boldt, which centers on a parental dispute over whether a 12-year-old boy, Jimmy Boldt, should undergo non-therapeutic circumcision following his custodial father''s conversion to Judaism, despite objections from his mother. The author examines the procedural aspects, modest medical benefits, and rare complications of circumcision in older children, arguing that parental decision-making authority must be balanced against principles of beneficence, non-maleficence, and respect for persons.\n\nThe author contends that while parents generally hold wide discretion to weigh cultural, social, and medical factors for their children, elective and irreversible procedures performed on older minors require special ethical constraints. Ultimately, the article concludes that elective circumcisions for older children or adolescents should not proceed without the unambiguous assent of the minor and the mutual consent of both parents, asserting that physicians should ethically decline to perform the procedure when these conditions are unmet.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Douglas S. Diekema", "Jimmy Boldt", "Thomas Szasz"], "organizations": ["The Journal of Clinical Ethics", "University of Washington School of Medicine", "Treuman Katz Center for Pediatric Bioethics", "Seattle Children\u2019s Hospital", "American Academy of Pediatrics", "Russian Orthodox Church"], "themes": ["Pediatric Bioethics", "Parental Decision-Making Authority", "Male Circumcision", "Adolescent Assent and Autonomy", "Religious and Cultural Identity", "Custody Disputes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a19634e5bb1f31fa46696b6a036416a947541e04fb542d5d3bf3ff274ff690d1', 'Bollinger Chapin CGC as ACE 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a19634e5bb1f31fa46696b6a036416a947541e04fb542d5d3bf3ff274ff690d1.pdf', 'policy_guideline', 'ingested', '{"date": "2019-08-01", "description": "This white paper argues that child genital cutting (CGC)\u2014encompassing involuntary genital procedures on male, female, and intersex infants and children\u2014constitutes an early physical and psychological trauma that meets the criteria of an Adverse Childhood Experience (ACE). Despite its high prevalence and documented associations with neurodevelopmental harm, toxic stress, alexithymia, and sexual dysfunction, CGC is omitted from standard ACE screening tools. The authors assert that this omission skews demographic risk profiles and conceals widespread childhood trauma, particularly among men in the United States.\n\nTo address this gap, the authors propose modifying the existing sexual abuse question in the standard 10-item ACE questionnaire to explicitly include non-consensual surgical alteration of the genitals. Adopting this modification would allow public health authorities and researchers to better capture early adversity, appropriately assess lifelong health risks, and facilitate trauma prevention and treatment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Dan Bollinger", "Georganne Chapin", "Caitlyn Rhorer", "Nadine Burke Harris", "Douglas Gairdner"], "organizations": ["Intact America", "Hudson Center for Health Equity & Quality", "Centers for Disease Control and Prevention", "Kaiser Permanente"], "themes": ["Child Genital Cutting", "Adverse Childhood Experiences (ACE)", "Male Circumcision", "Toxic Stress", "Childhood Trauma", "Screening Tools and Diagnostics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b64f5906709d17c8a8bfc3bbd6170ba5ade8c31d6164f2618ccb8912183bc5ce', 'Bollinger Circumcision_and_its_Opposition 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b64f5906709d17c8a8bfc3bbd6170ba5ade8c31d6164f2618ccb8912183bc5ce.pdf', 'other', 'ingested', '{"date": "2007", "description": "This text, an encyclopedia entry by Dan Bollinger, explores the historical, religious, medical, and ethical conflicts surrounding male circumcision, characterizing the issue as a struggle between ''evangelism'' and ''preservationism.'' Bollinger critiques the widespread acceptance of infant circumcision in religious contexts and Western medicine, arguing that medical rationales have continuously shifted to justify genital alteration without solid evidence. He points out a perceived double standard where female genital cutting is recognized internationally as a human rights violation, yet non-therapeutic male circumcision remains largely unchallenged by secularists, ethicists, and legal systems.\n\nBollinger details the growing momentum of the genital integrity movement since the late 20th century, which frames non-consensual genital alteration of minors as a violation of bodily integrity. The text outlines historical renunciation within Judaism and Christianity, modern government defunding of routine circumcision in Western healthcare systems, and grassroots efforts by secular and faith-based groups advocating for legal protections, bodily autonomy, and gender-neutral laws safeguarding all children from non-therapeutic genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger", "Tom Flynn", "Richard Dawkins", "Maimonides"], "organizations": ["Prometheus Books", "American Academy of Pediatrics", "American Medical Association", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "Jews Against Circumcision", "Catholics Against Circumcision", "International Coalition for Genital Integrity"], "themes": ["Genital Integrity", "Male Circumcision", "Children''s Rights", "Bodily Autonomy", "Medicalization", "Religious Rituals and Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0b13a46f6c139a0179e7af9838c79f439884e5e3b6abc2ea3c1ef2a7a6eb9100', 'Bollinger HighCostofCircumcision-ResGate2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0b13a46f6c139a0179e7af9838c79f439884e5e3b6abc2ea3c1ef2a7a6eb9100.pdf', 'other', 'ingested', '{"date": "2022-01-20", "description": "This preprint argues that neonatal male circumcision in the United States incurs a substantial annual financial burden totaling approximately $5.7 billion. Author Dan Bollinger breaks this estimate down into procedure costs and extended hospital stays ($1.4 billion), treatments for medical complications and surgical revisions ($743 million), and long-term costs attributed to circumcision-related erectile dysfunction and personal lubricants ($3.65 billion).\n\nBollinger contends that financial incentives heavily influence medical practice, asserting that major professional organizations\u2014such as the American Academy of Pediatrics and the American Medical Association\u2014fail to condemn circumcision because the procedure and its complications generate significant revenue for hospitals and individual practitioners.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger"], "organizations": ["Intact America", "American Academy of Pediatrics", "American Medical Association", "American Academy of Family Physicians", "American College of Obstetricians and Gynecologists", "ResearchGate"], "themes": ["Circumcision Economics", "Healthcare Costs", "Medical Complications", "Erectile Dysfunction", "Physician Financial Incentives", "Infant Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ea58b8abf1d6ca053e363f778d94298b666a7c2e2c2cbc0f2800a4f55533dc6d', 'Bollinger Intactivist Origins_Masculine Fdtn 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ea58b8abf1d6ca053e363f778d94298b666a7c2e2c2cbc0f2800a4f55533dc6d.pdf', 'other', 'ingested', '{"date": "2017-11-11", "description": "In this historical overview, author Dan Bollinger charts the origins of the intactivist movement from the late 19th century through the late 20th century, highlighting the early individuals who voiced opposition to neonatal male circumcision prior to the emergence of formal advocacy organizations in the mid-1980s. Bollinger argues that early resistance was largely pioneered by men and physicians who recognized circumcision as an unnecessary, traumatic, and medically ungrounded form of bodily mutilation with lifelong physical and psychological consequences.\n\nThe document chronologically compiles medical literature, psychological critiques, legal analyses, and activist milestones\u2014spanning early medical dissenters like Herbert Snow and Douglas Gairdner to foundational figures like Jeffrey Wood and Marilyn Milos. Bollinger frames the historical struggle against routine circumcision as a significant men''s issue centered on bodily integrity, child welfare, and resistance to entrenched cultural and medical dogma.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger", "Herbert Snow", "Douglas Gairdner", "Jeffrey Wood", "Marilyn Milos", "Bruno Bettelheim", "William Brigman", "Desmond Morris"], "organizations": ["INTACT Educational Foundation", "NOCIRC", "Intact America", "American Academy of Pediatrics", "American Medical Association", "Attorneys for the Rights of the Child"], "themes": ["Intactivism", "Male Circumcision", "Bodily Integrity", "Medical History", "Psychological Trauma", "Men''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bb399b7785b4e31352788af991a388af9368962fa7cb5e4364786f96fcbcf6be', 'Bollinger Intactivist Revolutionaries_Rebels 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bb399b7785b4e31352788af991a388af9368962fa7cb5e4364786f96fcbcf6be.pdf', 'other', 'ingested', '{"date": "2014-12-08", "description": "Dan Bollinger evaluates the internal dynamics and tactics of the intactivist (anti-circumcision) movement, utilizing social movement theorist Bill Moyer''s Movement Action Plan (MAP) framework. He addresses the phenomenon of ''loose cannons''\u2014activists whose aggressive, dogmatic, or confrontational actions threaten to alienate moderate fence-sitters and undermine the campaign during its critical ''Ripening Conditions'' stage.\n\nBollinger argues that successful activism requires discipline, nonviolent persuasion, and strategic awareness rather than uncontrolled anger or disruptive extremism. He outlines the differences between effective and ineffective rebels, urging intactivist organizations to implement strict rules of engagement, undergo nonviolence training, and hold participants accountable to ensure public credibility and long-term legislative success.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger", "Bill Moyer", "Abraham Maslow", "Martin Luther King, Jr.", "Rosa Parks"], "organizations": ["American College of Obstetricians and Gynecologists (ACOG)", "Training for Change", "Sea Shepherd", "DC Metro Police"], "themes": ["Intactivism", "Social Movement Strategy", "Nonviolent Protest", "Movement Action Plan (MAP)", "Activist Roles and Discipline", "Circumcision Opposition"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('297b1dcdd4cb69231ceaddb86ce8e0a30641e359c11b612c4580a49dd74754b0', 'Bollinger Lost Boys Thymos 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/297b1dcdd4cb69231ceaddb86ce8e0a30641e359c11b612c4580a49dd74754b0.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This article investigates neonatal circumcision-related mortality in the United States, estimating that approximately 117 infant boys die each year from circumcision-related complications\u2014predominantly hemorrhage and bacterial sepsis. The author argues that because infant circumcision is an elective, non-therapeutic procedure, every one of these deaths is entirely preventable.\n\nThe paper critiques the medical establishment, regulatory bodies, and parenting literature for failing to inform parents of mortality risks and for obscuring the true causes of death on official certificates. Bollinger identifies institutional conflicts of interest, physician financial incentives, and fears of malpractice liability as primary drivers of underreporting, and advocates for the elimination of non-therapeutic infant circumcision and the establishment of rigorous mortality reporting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dan Bollinger", "Douglas Gairdner", "H. Patel", "Dustin Evans, Jr.", "Ryleigh McWillis", "Eric Keefe"], "organizations": ["Boy''s Health Advisory", "American Academy of Pediatrics", "American Medical Association", "American College of Obstetricians and Gynecologists", "American Academy of Family Physicians", "Centers for Disease Control and Prevention"], "themes": ["Neonatal Circumcision", "Infant Mortality", "Surgical Complications", "Medical Ethics", "Informed Consent", "Healthcare Accountability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7f49108401aa73a4e766a4b4bc66eb782acd57e13f3db10f93729c25f8fe40b1', 'Bollinger Normal-Circ Ratio 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7f49108401aa73a4e766a4b4bc66eb782acd57e13f3db10f93729c25f8fe40b1.pdf', 'other', 'ingested', '{"date": "2000", "description": "This white paper by Dan Bollinger examines trends in neonatal male circumcision rates across the United States throughout the 1990s, aiming to supply reliable and updated statistics on genital integrity. It highlights that the circumcision rate dropped to 57.2% by 1998, corresponding to an intact rate of 42.8%\u2014a nearly threefold increase in intact boys compared to the low point of 15% in 1979.\n\nBollinger notes that despite medical statements from bodies like the American Academy of Pediatrics indicating no absolute medical necessity for routine newborn circumcision, circumcisions remain common and costly in the U.S. Total charges reached approximately $2.1 billion in 1999, predominantly covered by commercial insurance and Medicaid, in contrast to much lower rates in other countries such as the United Kingdom.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger", "Edward Wallerstein", "David Gollaher"], "organizations": ["American Academy of Pediatrics", "British Department of Health and Social Security", "Medicaid"], "themes": ["Neonatal Circumcision Rates", "Genital Integrity", "Infant Health Statistics", "Medical Costs and Insurance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0d44e483854fc727755a5cbe2d2c4095b1a3635385427f82d47f9ab4272cd523', 'Bollinger Normal_vs_Cut Psychol 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0d44e483854fc727755a5cbe2d2c4095b1a3635385427f82d47f9ab4272cd523.pdf', 'other', 'ingested', '{"date": "2014", "description": "In this literature review, Dan Bollinger investigates the psychological consequences of male circumcision, asserting that there is a stark lack of scientific evidence supporting any psychological benefit to the procedure. Following a comprehensive search across major medical and psychological indexes, the author identifies more than one hundred peer-reviewed studies documenting pain, trauma, alexithymia, and other long-term psychological harms associated with circumcision, compared to zero studies demonstrating psychological benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Bollinger", "Robert Van Howe", "Gocke Cansever", "Bertil Jacobson", "Marc Bygdeman", "Herman Nunberg", "John Rhinehart"], "organizations": ["American Academy of Pediatrics", "American Pain Society"], "themes": ["Male Circumcision", "Psychological Trauma", "Neonatal Pain Management", "Alexithymia", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a03edf9b265c1973e170b42ccf780f09279492d50d77e2604603c2dd099cfb88', 'Bollinger Solicit Circ Violates Anti Kickback 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a03edf9b265c1973e170b42ccf780f09279492d50d77e2604603c2dd099cfb88.pdf', 'policy_guideline', 'ingested', '{"date": "2025-07-27", "description": "This policy paper argues that routine institutional solicitation of newborn male circumcision constitutes a violation of the Federal Anti-Kickback Statute (AKS). Because neonatal circumcision is an elective, non-therapeutic procedure that is not medically indicated or recommended by major medical associations, the author contends that promoting and billing it under federal programs like Medicaid, CHIP, and TRICARE is primarily driven by financial incentives rather than clinical necessity.\n\nThe paper highlights survey findings showing that frequent solicitations significantly drive procedure rates, disproportionately pressuring vulnerable demographics and persons of color while undermining informed consent. To curb these abuses, the author outlines policy recommendations, including federal audits and investigations by the HHS Office of Inspector General (OIG), regulatory guidance clarifying billing prohibitions, and strict bans on provider solicitation for elective procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Dan Bollinger"], "organizations": ["American Academy of Pediatrics", "U.S. Department of Health and Human Services", "Office of Inspector General", "Centers for Medicare & Medicaid Services", "Florida Board of Medicine", "College of Physicians and Surgeons of British Columbia", "Royal Dutch Medical Association", "Finnish Central Union for Child Welfare", "Royal Australasian College of Physicians"], "themes": ["Anti-Kickback Statute", "Neonatal Circumcision", "Healthcare Fraud and Compliance", "Informed Consent", "Medicaid Reimbursement", "Racial Disparities in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('30f0849b93a6bef08efbab3f8e9b68f2103eb49a2463f6403f4b09ff26559ca1', 'Bollinger Super-absorbent_Diapers_and_Circ (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/30f0849b93a6bef08efbab3f8e9b68f2103eb49a2463f6403f4b09ff26559ca1.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This study investigates how modern super-absorbent disposable diapers may mask life-threatening hemorrhage following neonatal circumcision. Due to the high wicking efficiency of sodium polyacrylate cores, disposable diapers absorb substantial volumes of blood without displaying obvious surface staining, requiring up to 45.8 ml of fluid to generate a ''quarter-sized'' spot\u2014dangerously close to the 54 ml threshold capable of inducing hypovolemic shock in newborns.\n\nIn contrast, traditional cotton cloth diapers require only 0.5 ml of fluid to produce an equivalent spot and readily bleed through to provide an immediate visual warning. The author concludes that common clinical indicators such as a ''quarter-sized spot'' are unsafe when using disposable diapers, recommending that parents and healthcare providers switch to cloth diapers during post-operative recovery and that diaper manufacturers include explicit warning labels.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dan Bollinger"], "organizations": ["Procter & Gamble", "Kimberly-Clark", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Circumcision Complications", "Neonatal Hemorrhage Detection", "Hypovolemic Shock", "Super-absorbent Diapers", "Post-operative Infant Care"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1789fd6dec77e3b5dafdf80a53741163f78033764465a501b3a82b1339d727c9', 'Bollinger_Penis_Care_Info_Gap_Thymos 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1789fd6dec77e3b5dafdf80a53741163f78033764465a501b3a82b1339d727c9.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This article highlights a widespread ''penis-care information gap'' among healthcare providers and parents in North America regarding how to properly care for intact (uncircumcised) boys. Decades of routine infant circumcision have eroded baseline medical knowledge and parenting practices, leading to frequent misinformation, unwarranted parental anxiety, and iatrogenic harm. Notably, normal developmental non-retractability is routinely misdiagnosed as pathological phimosis, and caregivers or physicians often engage in premature forced foreskin retraction (PFFR), causing pain, scarring, and avoidable ''corrective'' circumcisions.\n\nThe author argues that normal penile anatomy requires minimal intervention (''uncare'') and that natural separation of the foreskin often continues into puberty. To rectify this issue, the paper advocates for structured educational programs for both parents and physicians, providing clear guidance on natural penile development, conservative alternatives for rare preputial conditions, and strict avoidance of forced retraction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dan Bollinger", "L. M. Osborn", "T. J. Metcalf"], "organizations": ["Boy''s Health Advisory", "Men''s Studies Press, LLC", "American Academy of Pediatrics", "International Coalition for Genital Integrity", "Mothers Against Circumcision", "National Organization to Halt the Abuse and Routine Mutilation of Males"], "themes": ["Infant and Childhood Genital Care", "Circumcision Practices and Trends", "Premature Forced Foreskin Retraction (PFFR)", "Physician and Parental Misinformation", "Diagnosis of Pathological vs. Physiological Phimosis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('731d3a2e7a5c5969cbf6d67fb4a9ea6a93dcf13b947a279ae947955f2d434aed', 'Bond State Laws Female Circumcision_ Violate Equal UIC Rev 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/731d3a2e7a5c5969cbf6d67fb4a9ea6a93dcf13b947a279ae947955f2d434aed.pdf', 'legal_document', 'ingested', '{"date": "1999", "description": "This article argues that state laws criminalizing female circumcision violate the Equal Protection Clause of the Fourteenth Amendment by failing to provide equal legal protections to male minors subjected to circumcision. While acknowledging the physical and psychological harms of female circumcision and the state''s interest in protecting child welfare, the author asserts that male circumcision is similarly painful, medically unnecessary, and far more prevalent in the United States. To rectify this unconstitutional gender discrimination, the comment proposes replacing gender-specific statutes with gender-neutral legislation that protects all children from non-therapeutic genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Shea Lita Bond"], "organizations": ["UIC Law Review", "The John Marshall Law Review"], "themes": ["Equal Protection Clause", "Fourteenth Amendment", "Female Genital Mutilation", "Male Circumcision", "Child Welfare", "Gender Discrimination", "Constitutional Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('aa84427390c012d38a36440a31a5e1aa4f25a2f2dd116a8f13c88465d1771449', 'Bonner Legal Constit TruthSeeker 1989.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/aa84427390c012d38a36440a31a5e1aa4f25a2f2dd116a8f13c88465d1771449.pdf', 'legal_document', 'ingested', '{"date": "1989", "description": "This article examines the constitutional, civil, and criminal legal questions surrounding routine neonatal circumcision in the United States. The authors argue that because infant circumcision lacks clear medical necessity, parental consent cannot legally justify the procedure, drawing parallels to legal precedents that restrict third-party consent for the sterilization of mentally incompetent individuals. They maintain that routine circumcision infringes upon an infant''s fundamental constitutional rights to bodily integrity, liberty, privacy, due process, and equal protection.\n\nThe authors further contend that performing non-therapeutic circumcision without valid informed consent exposes physicians and medical institutions to civil liability for battery and false imprisonment. While acknowledging the current cultural barriers to pursuing criminal child abuse charges, they propose civil rights class-action lawsuits against hospitals and surgeons as an effective legal mechanism to challenge routine, non-medically indicated circumcisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Charles A. Bonner", "Michael J. Kinane", "Karen Ericksen Paige", "Jeffery M. Paige"], "organizations": ["American Academy of Pediatrics", "Hastings School of Law", "The Truth Seeker", "University of California Press"], "themes": ["Neonatal Circumcision", "Parental Consent", "Constitutional Rights", "Bodily Integrity", "Medical Malpractice and Battery", "Child Welfare and Due Process"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1fa2116e055ef2102e22653275f853cfebc0bfbef0e6c90152bfc71c45ff8dae', 'Bonner Male Circ not Natural Condom 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1fa2116e055ef2102e22653275f853cfebc0bfbef0e6c90152bfc71c45ff8dae.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This article examines the viability and implications of promoting male circumcision as a public health intervention to control HIV transmission, particularly in high-risk areas of sub-Saharan Africa. While acknowledging epidemiological evidence indicating that circumcision correlates with a reduced risk of female-to-male HIV acquisition, the author challenges the notion that circumcision acts as a ''natural condom.'' Crucially, studies show that circumcision does not reduce the risk of transmission from HIV-positive men to female partners, and the protective effect appears to diminish when circumcision is performed post-puberty or in adulthood.\n\nThe author underscores significant ethical, medical, and cultural challenges associated with implementing mass circumcision programs, particularly in resource-limited settings where traditional procedures without sterile techniques pose substantial risks of severe complications or death. Additionally, there is concern that a perceived sense of immunity could encourage risky sexual behaviors. The article concludes that before widespread surgical interventions are promoted, further research is required to substantiate biological mechanisms and generalizability, emphasizing that established prevention strategies of proven efficacy, such as consistent condom use, should remain the primary focus.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kate Bonner", "Kitty Bloemenkamp", "Inon Schenker", "Tim Farley"], "organizations": ["Reproductive Health Matters", "Elsevier", "World Health Organization", "St George''s Hospital Medical School", "JSTOR"], "themes": ["Male circumcision", "HIV/AIDS prevention", "Sexually transmitted infections", "Public health policy", "Surgical complications and ethics", "Sub-Saharan Africa"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dda4847ce29b7cb0d3c7c37ed3b1bb195b763afb4f48ff2d60c7c109c0c80b6d', 'Bonyai Why Bioethics Matters BioethicsToday 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dda4847ce29b7cb0d3c7c37ed3b1bb195b763afb4f48ff2d60c7c109c0c80b6d.pdf', 'other', 'ingested', '{"date": "2026-04-05", "description": "This document examines routine infant circumcision through the framework of the four foundational principles of bioethics: autonomy, non-maleficence, beneficence, and justice. The author argues that performing an irreversible, non-therapeutic surgical procedure on healthy infants violates the limits of parental proxy consent and undermines personal autonomy. Furthermore, the practice exposes non-consenting individuals to surgical harm without immediate medical necessity, while claimed benefits can often be achieved through less invasive alternatives.\n\nHighlighting international medical stances that counsel against the procedure on healthy minors, the author calls for consistency in ethical standards concerning bodily integrity and child protection. Rather than dismissing cultural or religious traditions, the piece proposes deferring the decision until the individual is mature enough to weigh the risks, benefits, and personal implications to provide their own informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Justin Bonyai"], "organizations": ["Intact Global", "Bioethics Today"], "themes": ["Infant Circumcision", "Bioethics", "Bodily Autonomy", "Proxy Consent", "Non-Maleficence", "Children''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e2c3e8e77ba073faa9466f714c5afa990571e68c894a31983c1f2d05501b29c0', 'Bossio Attitudes Circ Status ArchSexBeh 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e2c3e8e77ba073faa9466f714c5afa990571e68c894a31983c1f2d05501b29c0.pdf', 'medical_journal', 'ingested', '{"date": "2017-08-18", "description": "This study examines the relationship between men''s attitudes toward their circumcision status, the timing of their circumcision, and their subsequent body image and sexual functioning. Surveying 811 men (including neonatally circumcised, childhood circumcised, adult circumcised, and intact individuals), the researchers found that satisfaction with one''s circumcision status\u2014rather than actual circumcision status itself\u2014was significantly associated with higher genital self-image, better overall body image, and superior sexual functioning.\n\nMen circumcised in adulthood and intact men reported the highest satisfaction with their circumcision status, whereas a distressed subgroup primarily comprised men circumcised as neonates or in childhood who lacked choice in the procedure. The authors conclude that psychological appraisal and satisfaction with circumcision status are critical variables that researchers and clinicians must consider when evaluating male sexual dysfunction and genital perception.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Sean Dougherty"], "organizations": ["Queen''s University", "Springer Science+Business Media", "Social Sciences and Humanities Research Council", "Pfizer-Canadian Male Sexual Health Council"], "themes": ["Male Circumcision", "Body Image", "Genital Self-Image", "Sexual Functioning", "Men''s Sexual Health", "Informed Consent and Bodily Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d326ccc2e022c8d36121ed28c7db9722362247dab40591acac9b904fa03d7984', 'Bossio Examining penile sensitivity J Urol 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d326ccc2e022c8d36121ed28c7db9722362247dab40591acac9b904fa03d7984.pdf', 'medical_journal', 'ingested', '{"date": "2016-06", "description": "This study evaluated penile sensitivity among 62 adult men (30 neonatally circumcised and 32 intact) using quantitative sensory testing (QST) to measure touch, pain, warmth detection, and heat pain thresholds across several penile sites and a control site on the forearm. The researchers found no statistically significant differences in penile sensitivity or sexual functioning (assessed via the IIEF) between circumcised and intact men across any stimulus modality or penile site.\n\nWhile the foreskin in intact men exhibited greater sensitivity to fine tactile stimulation compared to other genital areas, it showed comparable thresholds for punctate pain, warmth, and heat pain. These findings challenge traditional assumptions that neonatal circumcision decreases penile sensitivity due to glans keratinization or the removal of sensitive prepuce tissue, indicating that surgical excision of the foreskin during infancy has minimal long-term effects on adult penile sensitivity thresholds.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Stephen S. Steele", "Ranjiv Mathews"], "organizations": ["Queen\u2019s University", "American Urological Association Education and Research, Inc.", "Southern Illinois University School of Medicine", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Penile Sensitivity", "Quantitative Sensory Testing (QST)", "Sexual Functioning", "Urology and Somatosensation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d707d3a2d3f24aab06e30142c1e5f3a20428d4ee10367fea59b6768f06a5b2a8', 'Bossio Examining sexual correlates (thesis) 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d707d3a2d3f24aab06e30142c1e5f3a20428d4ee10367fea59b6768f06a5b2a8.pdf', 'other', 'ingested', '{"date": "2015", "description": "This doctoral dissertation investigates the sexual and sensory correlates of neonatal male circumcision in adult men to address a significant gap in North American medical policy, which has traditionally focused on STI/HIV prevention rather than sexual outcomes. Through a comprehensive literature review, quantitative sensory testing, psychophysiological arousal measurements, and self-report surveys, the research evaluates physiological sensitivity, sexual response, body image, and partner satisfaction across circumcised and intact men.\n\nThe findings reveal minimal objective physiological differences between neonatally circumcised and intact men regarding penile tactile sensitivity, thermal thresholds, and erectile or sexual arousal responses. However, psychological and attitudinal factors proved influential: negative attitudes or dissatisfaction with one''s circumcision status\u2014rather than circumcision status alone\u2014were strongly associated with poorer body image and decreased sexual functioning. The author argues that future public health policies and guidelines must integrate these subjective and psychosocial factors alongside health data.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Stephen Steele", "Katie Bartley", "Ron Holden", "Dean Tripp"], "organizations": ["Queen\u2019s University", "American Academy of Pediatrics", "World Health Organization", "Canadian Paediatric Society", "Centers for Disease Control and Prevention"], "themes": ["Neonatal Male Circumcision", "Penile Sensitivity and Somatosensory Testing", "Male Sexual Functioning and Genital Response", "Genital Body Image and Psychological Distress", "Public Health Policy and Infant Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('18ef0baa4e93b4665650e7fa98cf3e859da3611715af431580ab6045e06eeddb', 'Bossio reply to Morris JSM 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/18ef0baa4e93b4665650e7fa98cf3e859da3611715af431580ab6045e06eeddb.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "In this response to a Letter to the Editor published in The Journal of Sexual Medicine, the authors defend their review on male circumcision literature against criticisms concerning health outcomes and methodology. They clarify that their primary objective was to highlight critical gaps in research regarding the sexual and psychological correlates of neonatal circumcision, rather than conducting a broad risk-benefit analysis of protective health effects.\n\nThe authors emphasize that randomized controlled trials demonstrating HIV risk reduction among adult men circumcised in African countries cannot be uncritically generalized to neonatal circumcision performed in North America. They address methodological disputes over study inclusion and quality assessments\u2014specifically critiquing the evaluation criteria used in Morris and Krieger''s competing review\u2014and conclude by advocating for cautious, unbiased, and evidence-based parental education regarding neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Stephen Steele", "Robert S. Van Howe", "Brian J. Morris", "John N. Krieger"], "organizations": ["Queen''s University", "Scottish Intercollegiate Guidelines Network"], "themes": ["Neonatal Circumcision", "Male Sexual Functioning", "HIV Prevention", "Research Methodology and Study Quality", "Evidence-Based Healthcare Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e92758817a839b201e4f1af7cbad911aba856f38ef0d39308bd00fd3669f46c7', 'Bossio Review of the Current Evidence JSM 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e92758817a839b201e4f1af7cbad911aba856f38ef0d39308bd00fd3669f46c7.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This review evaluates the empirical literature surrounding male circumcision, critically addressing recent policy developments such as the American Academy of Pediatrics'' stance that the health benefits of neonatal circumcision outweigh the risks. The authors argue that much of the existing research\u2014particularly large trials demonstrating reduced HIV transmission conducted among adult men in sub-Saharan Africa\u2014lacks direct generalizability to North American populations, where circumcision is typically performed on neonates and transmission dynamics differ considerably.\n\nFurthermore, the review identifies critical gaps in the literature regarding sexual health correlates, including penile sensitivity, male and partner sexual functioning, body image, and the psychosocial drivers behind parental decision-making. The authors advocate for methodologically rigorous, objective research that specifically examines the long-term physiological and psychological outcomes of neonatal circumcision before North American medical guidelines and public policies are modified.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Stephen Steele"], "organizations": ["Queen''s University", "American Academy of Pediatrics", "International Society for Sexual Medicine"], "themes": ["Male Circumcision", "Neonatal Health", "Sexual Functioning", "Penile Sensitivity", "HIV and STI Transmission", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e1212fc51718e426f7b0f77f19e7012d9601a835375ca285c8c9da8864a21ef0', 'Bossio You either have it or you don''t_ Can J Hum Sex 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e1212fc51718e426f7b0f77f19e7012d9601a835375ca285c8c9da8864a21ef0.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This empirical study investigates the impact of male circumcision status on the sexual functioning, sexual satisfaction, preferences, and beliefs of their sexual partners. Surveying 196 participants (168 women and 28 men) currently in a sexual relationship with a man, the researchers found that male circumcision status had no significant impact on the sexual functioning of either female or male partners when evaluated with standardized measures (FSFI and IIEF-MSM). However, women with intact partners reported significantly higher overall sexual satisfaction than those with circumcised partners, while no such satisfaction difference emerged among male participants.\n\nThe findings also revealed distinct gender divergences regarding preferences and attitudes. Female participants expressed slight preferences for circumcised penises during vaginal intercourse and fellatio and held more positive general beliefs about circumcised anatomy. In contrast, men who have sex with men demonstrated strong preferences and more positive beliefs toward intact penises across all examined sexual activities. Despite these preferences, overall satisfaction with a partner''s genital status was consistently high across all participants, indicating that circumcision status ultimately exerts minimal disruption on relationship quality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jennifer A. Bossio", "Caroline F. Pukall", "Katie Bartley"], "organizations": ["Queen''s University", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "Sexual Functioning", "Sexual Satisfaction", "Partner Preferences", "Human Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2b72375d94e8d14b7e2dd53a72c171120727f6ff77b7dd5828b7f227264b2bb3', 'Bouclin LegEth Canada IJMH 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2b72375d94e8d14b7e2dd53a72c171120727f6ff77b7dd5828b7f227264b2bb3.pdf', 'medical_journal', 'ingested', '{"date": "2005", "description": "This article examines the legal, ethical, and medical dilemmas surrounding elective, nontherapeutic neonatal male circumcision within the Canadian context. The author argues that despite shifting medical guidelines cautioning against the procedure, infant circumcision remains normalized even though it lacks clear therapeutic necessity, presents documented risks of physical and psychological harm, and permanently excises healthy erogenous tissue.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Suzanne Bouclin", "Ryleigh McWillis", "Bora Laskin", "G\u00e9rard La Forest", "Margaret Somerville"], "organizations": ["University of Ottawa", "Men\u2019s Studies Press, LLC", "Canadian Paediatric Society", "Canadian Medical Protective Association", "College of Physicians and Surgeons of British Columbia", "College of Physicians and Surgeons of Saskatchewan", "College of Physicians and Surgeons of Manitoba", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Informed Consent", "Parental Proxy Consent", "Bodily Integrity and Autonomy", "Pediatric Medical Ethics", "Canadian Health Law and Charter Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('667ed94ac8b32867f624f50b7add0d29d37695ceac5817d6e7813c7cc0d495f3', 'Boyle Bensley Adverse sex psych effects 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/667ed94ac8b32867f624f50b7add0d29d37695ceac5817d6e7813c7cc0d495f3.pdf', 'medical_journal', 'ingested', '{"date": "2001-07-11", "description": "This study examines the adverse sexual and psychological effects of involuntary male infant circumcision using survey data collected from intact and circumcised men, as well as female and gay male sexual partners with experience with both. The findings indicate that circumcised men experienced significant progressive declines in penile glans sensitivity, greater dissatisfaction with orgasms, different masturbation techniques, and a range of long-term negative emotional consequences regarding their circumcision status compared to genitally intact men.\n\nAdditionally, sexual partners reported greater general discontent among circumcised men, along with a higher likelihood of engaging in unsafe sexual practices such as reluctance to use condoms. The authors conclude that infant circumcision negatively impacts sexual function, bodily integrity, and psychological well-being, arguing that these adverse outcomes must be addressed when considering informed consent for non-therapeutic genital surgery imposed on male minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "Gillian A. Bensley"], "organizations": ["Bond University"], "themes": ["Male Infant Circumcision", "Sexual Sensation and Dysfunction", "Psychological Trauma and Body Image", "Bodily Integrity", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0f7fc63c73a91e27507e23077637c5094a5a3c85d9f63433503820cd70f6741a', 'Boyle Critique of African RCTs Book Chapter 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0f7fc63c73a91e27507e23077637c5094a5a3c85d9f63433503820cd70f6741a.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This document presents a comprehensive critique of three sub-Saharan African randomized clinical trials (RCTs) conducted in South Africa, Kenya, and Uganda that led the WHO and UNAIDS to recommend mass male circumcision (MC) for HIV prevention in 2007. The author argues that the trials suffered from severe methodological flaws, including researcher expectation bias, lack of clinical equipoise, inadequate blinding, non-representative sampling, excessive attrition, and premature termination that artificially exaggerated treatment efficacy. When adjusting for lead-time and procedural biases, the reported 60% relative risk reduction translates to an absolute risk reduction of merely 1.3% (or less), which lacks clinical significance.\n\nFurthermore, the critique raises severe ethical and public health concerns, citing a parallel Ugandan trial where circumcised HIV-positive men exhibited a 61% increase in transmitting HIV to their female partners, some of whom were never informed of their partners'' infection status. The author contends that mass circumcision diverts vital public health funding away from proven prevention methods such as condoms and antiretroviral therapy, exposes men and women to surgical risks and non-sexual HIV transmission, fosters behavioral risk compensation, and violates the foundational medical ethic of ''primum non nocere'' (first do no harm).", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "George Hill", "B. Auvert", "R. C. Bailey", "R. H. Gray", "M. J. Wawer", "R. S. Van Howe"], "organizations": ["World Health Organization (WHO)", "UNAIDS", "Bond University", "Centers for Disease Control and Prevention (CDC)", "Doctors Opposing Circumcision", "Springer Science+Business Media"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Randomized Clinical Trials (RCTs)", "Methodological Bias and Validity", "Medical Ethics and Informed Consent", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('28657cf356b47b89c8a10ca4bbdb8cb12d5c041e2eb91a6dd2dabc9526a24322', 'Boyle Ending_Forced_Cutting (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/28657cf356b47b89c8a10ca4bbdb8cb12d5c041e2eb91a6dd2dabc9526a24322.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This article argues that non-therapeutic neonatal male circumcision and involuntary genital surgeries on minors lack medical justification and violate a child''s fundamental human right to bodily integrity. The author contends that such procedures inflict significant and permanent physical, sexual, and psychological trauma\u2014often leading to reduced sexual sensitivity, erectile dysfunction, and long-term conditions like Post-Traumatic Stress Disorder (PTSD).\n\nFrom legal and ethical standpoints, the paper asserts that parents cannot legally provide proxy consent for non-therapeutic, irreversible surgical amputations on healthy children, effectively categorizing such interventions as criminal assault. Furthermore, it criticizes medical associations, such as the American Academy of Pediatrics, for policies permitting routine circumcision and argues that laws exclusively banning female genital mutilation are discriminatory, demanding equal legal protection under international human rights law for all children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "Margaret Somerville", "Tim Hammond", "Maimonides", "Anna Freud"], "organizations": ["American Academy of Pediatrics", "American Medical Association", "United Nations", "Queensland Law Reform Commission", "Australasian Association of Paediatric Surgeons", "Intersex Society of North America", "General Medical Council"], "themes": ["Neonatal Circumcision", "Children''s Rights and Bodily Integrity", "Medical Ethics", "Informed Consent", "Psychological Trauma and PTSD", "Equal Legal Protection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0d6c3abc7158a02482ff28eec56734ac2bf4b48afa23f40cb7888174eedbcf51', 'Boyle Gemmel Neonatal_Circ_Long_Term_Harm 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0d6c3abc7158a02482ff28eec56734ac2bf4b48afa23f40cb7888174eedbcf51.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This study examines the long-term physical, sexual, and psychological consequences of neonatal male circumcision through a survey comparing circumcised and intact men in Queensland, Australia. The findings indicate that circumcised men report significantly less penile sensation during sexual activity, experience a greater progressive decline in sensitivity with age, and express lower overall satisfaction with their sex lives compared to intact men. Additionally, circumcised men exhibited higher rates of negative emotional outcomes, frequently reporting feelings of anger, sadness, incompleteness, and having been cheated.\n\nThe authors conclude that routine neonatal circumcision is an unnecessary and destructive surgical procedure that removes specialized erogenous and protective tissue without valid medical necessity. They advocate for public education and awareness campaigns to demystify the anatomical function of the foreskin, dispel cultural and aesthetic rationales, and inform prospective parents about the long-term adverse effects of infant circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tracey Gemmell", "Gregory J. Boyle", "G. A. Bensley", "George C. Denniston", "Frederick Mansfield Hodges", "Marilyn Fayre Milos", "Robert S. Van Howe"], "organizations": ["Kluwer Academic/Plenum Publishers", "World Health Organization", "Australian Institute of Health and Welfare", "Bond University"], "themes": ["Neonatal Circumcision", "Penile Sensation and Sensitivity", "Sexual Dysfunction", "Psychological and Emotional Well-being", "Foreskin Anatomy and Function", "Medical Ethics and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d2bdb66ae9c41d4bf9549592ecbae060db6cbfaf9e51ada7b88fdc8747b3e3db', 'Boyle Hill Circ Emotions Bias BJUI 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d2bdb66ae9c41d4bf9549592ecbae060db6cbfaf9e51ada7b88fdc8747b3e3db.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This letter to the editor criticizes an article by Tobian and Gray published in JAMA that advocated for male circumcision. The authors, Gregory J. Boyle and George Hill, argue that Tobian and Gray relied on methodologically flawed African randomized controlled trials, neglected evidence indicating increased male-to-female HIV transmission following circumcision, and ignored policy statements from both the Royal Dutch Medical Association and the Royal Australasian College of Physicians that advise against routine non-therapeutic male circumcision.\n\nFurthermore, the authors contend that pro-circumcision medical literature is fundamentally biased by the circumcised status and cultural background of its proponents. They characterize defenses of male circumcision as psychological rationalizations of trauma, emphasizing the physiological, sexual, and ethical harms of removing healthy foreskin, and call for the legal prohibition of non-therapeutic circumcision on minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "George Hill", "Aaron A. R. Tobian", "Ronald H. Gray"], "organizations": ["Bond University", "Doctors Opposing Circumcision", "Royal Dutch Medical Association", "Royal Australasian College of Physicians", "American Medical Association"], "themes": ["Male Circumcision", "Medical Ethics and Human Rights", "Observer and Cultural Bias in Medicine", "HIV Transmission", "Bodily Integrity and Non-therapeutic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('58f3007d729e5b4482aeb2cb58ede618ec9955a21748416ccf5cec589e502c96', 'Boyle Hill SubSaharan RCT JLM 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/58f3007d729e5b4482aeb2cb58ede618ec9955a21748416ccf5cec589e502c96.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This article critically examines the randomised clinical trials (RCTs) conducted in South Africa, Kenya, and Uganda that led the WHO and UNAIDS to endorse male circumcision as an HIV prevention intervention. The authors contend that these trials were fundamentally compromised by severe methodological flaws, including selection bias, investigator expectation bias, lack of true blinding and placebo control, problematic attrition, and early termination that artificially inflated treatment effects. They highlight that while relative risk reduction was reported at around 60%, the absolute risk reduction was merely 1.3%, which diminished further when adjusting for lead-time bias.\n\nBeyond methodological issues, the paper details substantial ethical and legal concerns surrounding mass circumcision programs. It emphasizes findings from a Ugandan trial indicating an increased risk of HIV transmission to female partners of HIV-positive circumcised men, alongside issues of inadequate informed consent, financial inducements among vulnerable populations, risk compensation, and surgical transmission risks. The authors conclude that mass adult circumcision in sub-Saharan Africa diverts vital resources away from proven preventive measures like condoms and antiretroviral treatments, arguing that widespread rollout is scientifically, ethically, and legally unjustified.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J Boyle", "George Hill", "Bertran Auvert", "Robert C. Bailey", "Ronald H. Gray", "Maria J. Wawer", "Yoweri Museveni"], "organizations": ["World Health Organization", "UNAIDS", "Doctors Opposing Circumcision", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Clinical Trial Methodology and Bias", "Medical Ethics and Informed Consent", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7a786c04d302ee52d6837259e3c4f01feb3fa58732e2939038a0abab3241e177', 'Boyle Issues_with_Intro Circ STI 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7a786c04d302ee52d6837259e3c4f01feb3fa58732e2939038a0abab3241e177.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This document comprises the ''PostScript'' correspondence and reviews section from a 2003 issue of the journal Sexually Transmitted Infections. It compiles clinical letters, mini-studies, and commentaries on various issues in venereology and sexual health. Major contributions include a case report on a pediatric perianal epidermal naevus mimicking genital warts, methodological critiques regarding the diagnostic criteria and role of Mycoplasma genitalium in pelvic inflammatory disease (PID), and a large epidemiological study in Pune, India finding no evidence for efficient sexual transmission of hepatitis C virus (HCV).\n\nAdditional pieces examine the persistent contamination and cleaning efficacy against human papillomavirus (HPV) DNA in outpatient clinics, a population-based dynamic cost-effectiveness analysis of Chlamydia trachomatis screening in the Netherlands, and an ethical, medical, and legal critique opposing the proposed introduction of infant male circumcision as an HIV prevention strategy in Botswana. The issue concludes with book reviews of STI atlases and meeting abstract corrections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["D Bandyopadhyay", "D Taylor-Robinson", "A Risbud", "G J Boyle", "S Strauss", "R Welte", "M Talbot"], "organizations": ["National AIDS Research Institute", "Imperial College London", "Health Protection Agency", "Bond University", "RG Kar Medical College", "University of Groningen"], "themes": ["Sexually Transmitted Infections", "Hepatitis C Virus Transmission", "HPV Environmental Contamination", "Chlamydia trachomatis Screening", "Pelvic Inflammatory Disease Aetiology", "Male Circumcision and HIV Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3093b28826c7547cdec50fac7daca79262e49f93604a3b99b149a1db3c0d235f', 'Boyle Male Circ Trauma J Health Psychol 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3093b28826c7547cdec50fac7daca79262e49f93604a3b99b149a1db3c0d235f.pdf', 'medical_journal', 'ingested', '{"date": "2002", "description": "This academic paper reviews the physiological, psychological, and psychosexual consequences of involuntary infant and childhood male circumcision. The authors argue that circumcision causes severe acute pain and trauma in newborns, potentially leading to lasting neurobiological alterations and conditions such as post-traumatic stress disorder (PTSD). Additionally, the study evaluates the long-term sexual sequelae, asserting that the removal of specialized erogenous tissue leads to reduced penile sensitivity, functional sexual difficulties, and significant emotional distress in affected men, prompting a call for health and legal professionals to reconsider the practice on unconsenting minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "Ronald Goldman", "J. Steven Svoboda", "Ephrem Fernandez", "Moses Maimonides", "George Hill"], "organizations": ["Bond University", "Circumcision Resource Center", "Attorneys for the Rights of the Child", "Southern Methodist University", "American Academy of Pediatrics", "American Medical Association", "Doctors Opposing Circumcision"], "themes": ["Male Circumcision", "Infant Pain and Trauma", "Post-Traumatic Stress Disorder (PTSD)", "Psychosexual Sequelae", "Medical Ethics and Human Rights", "Sexual Dysfunction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6e24dac2d9e80d3594295b0dd00a113e7409404942b62b3385752862f8eae96c', 'Boyle on Morris and Krieger ASM 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6e24dac2d9e80d3594295b0dd00a113e7409404942b62b3385752862f8eae96c.pdf', 'medical_journal', 'ingested', '{"date": "2015-03-31", "description": "This academic commentary by Gregory J. Boyle critically evaluates a 2013 systematic review by Brian J. Morris and John N. Krieger, which asserted that male circumcision has no adverse impacts on sexual function, sensitivity, or satisfaction. Boyle contends that Morris and Krieger''s conclusions are untenable, arguing that they relied on selective citations of non-peer-reviewed letters, ignored published rebuttals, and misclassified the quality of studies to favor their predetermined stance. He also critiques their heavy reliance on adult circumcision trials in Africa that reported unrealistically low rates of sexual dysfunction.\n\nBoyle emphasizes anatomical and physiological evidence demonstrating that the human foreskin is a specialized, richly innervated erogenous tissue essential to fine-touch sensitivity and mechanical sexual function. Reviewing multiple empirical studies, Boyle presents findings linking circumcision to decreased penile sensation, impairment of the penilo-cavernosus reflex, and heightened risks of erectile dysfunction and premature ejaculation. He concludes that neonatal male circumcision is an inherently harmful and non-consensual procedure, while also drawing attention to undisclosed pro-circumcision advocacy conflicts of interest.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "Brian J. Morris", "John N. Krieger", "Robert S. Van Howe", "Morten Frisch", "C. Terry Russell"], "organizations": ["Australian Institute of Psychology", "Scientific Research Publishing Inc.", "Circumcision Academy of Australia", "The Gilgal Society"], "themes": ["Male Circumcision", "Sexual Dysfunction", "Penile Sensitivity", "Erectile Dysfunction and Premature Ejaculation", "Bioethics and Bodily Integrity", "Methodological Bias in Research"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f2bd94465c9e0797b8539c978543cef93e6b84bad5af8f7243f5d6259bb3d4af', 'Boyle Proving a Negative in Ullman 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f2bd94465c9e0797b8539c978543cef93e6b84bad5af8f7243f5d6259bb3d4af.pdf', 'medical_journal', 'ingested', '{"date": "2018-03-25", "description": "This critique by Gregory J. Boyle examines a 2017 study by Ullmann et al. published in Translational Psychiatry, which claimed to refute long-term psychological and endocrine trauma (PTSD) resulting from male circumcision based on non-significant differences in hair cortisol/cortisone and self-report psychological measures. Boyle argues that Ullmann et al. committed a fundamental scientific error by asserting they had ''proven'' the null hypothesis, particularly given that their study was severely underpowered with a tiny convenience sample (only 20 participants total, including 9 circumcised and 11 intact men). Furthermore, Boyle demonstrates through traditional Cohen and Trafimow power analyses that the required sample sizes would need to be substantially larger to detect meaningful effects, points out significant psychometric weaknesses and lack of validity in the self-report scales utilized, identifies serious confounders such as the inclusion of subjects circumcised with analgesia, and notes that Ullmann et al. misrepresented major pediatric policy statements regarding routine circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "E. Ullmann", "David Trafimow", "Brian D. Earp", "Robert S. Van Howe"], "organizations": ["University of Melbourne", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "Post-Traumatic Stress Disorder (PTSD)", "Null Hypothesis Significance Testing (NHST)", "Statistical Power and Sample Size", "Psychometrics and Measurement Validity", "Hair Cortisol and Cortisone Biomarkers"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('903e0bce3f06fd746efeeaf1d53e14e7513d1c2df76bc7d385b5af3f7c6f3e52', 'Boyle Short-term trauma long-term Adv Sex Med 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/903e0bce3f06fd746efeeaf1d53e14e7513d1c2df76bc7d385b5af3f7c6f3e52.pdf', 'medical_journal', 'ingested', '{"date": "2015-04-16", "description": "This article reviews the evidence surrounding non-therapeutic infant and childhood male circumcision, arguing that the practice inflicts substantial physical, sexual, and psychological harms that are more prevalent and severe than widely recognized. The author highlights acute surgical complications\u2014including infection, meatal stenosis, penile loss, and death\u2014as well as the permanent loss of highly sensitive, functional erotogenic tissue, which is associated with long-term sexual dysfunctions such as premature ejaculation, erectile dysfunction, and reduced pleasure for both men and their partners.\n\nAdditionally, the paper evaluates the psychological impact of neonatal circumcision, emphasizing that severe early procedural pain\u2014frequently performed without effective anesthesia\u2014can disrupt early neurodevelopment and trigger lasting trauma akin to post-traumatic stress disorder (PTSD), alexithymia, and heightened negative emotionality. Boyle argues that routine infant circumcision violates medical ethics and human rights, and suggests that its continued promotion in cultures like the United States is largely driven by psychological defense mechanisms, including denial and rationalization, among circumcised practitioners and parents.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "David Reimer", "Dan Bollinger", "Robert S. Van Howe", "Alice Dreger", "Brian J. Morris"], "organizations": ["Australian Institute of Psychology", "Scientific Research Publishing Inc.", "American Psychiatric Association"], "themes": ["Infant Male Circumcision", "Psychosexual Harm and Sexual Dysfunction", "Post-Traumatic Stress Disorder (PTSD)", "Neonatal Pain and Trauma", "Medical Ethics and Informed Consent", "Defense Mechanisms and Harm Denial"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ee8aa6c5b4297c1a5d4868287eb272f39ffc8f0e1e4a6fde0ecdc7b5fd0f1602', 'Boyle Svoboda Circ Criminal Assualt JLM 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ee8aa6c5b4297c1a5d4868287eb272f39ffc8f0e1e4a6fde0ecdc7b5fd0f1602.pdf', 'medical_journal', 'ingested', '{"date": "2000", "description": "This article argues that non-therapeutic neonatal and infant male circumcision should be recognized as a criminal assault causing grievous bodily harm under common law and international human rights law. The authors examine legal precedents, such as Australia''s Marion''s Case, asserting that parents lack the legal authority to provide proxy consent for invasive, irreversible, and medically unnecessary surgery on healthy minors.\n\nThe paper contends that routine circumcision causes substantial lifelong physical, sexual, and psychological trauma while lacking credible medical indications or endorsements from major international medical bodies. Furthermore, the authors highlight a legal double standard, arguing that banning female genital mutilation while failing to protect male infants violates international human rights conventions and constitutional guarantees of equal protection under the law.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "J. Steven Svoboda", "Christopher P. Price", "J. Neville Turner", "Margaret Somerville", "Tim Hammond"], "organizations": ["Bond University", "Attorneys for the Rights of the Child", "Australasian Association of Paediatric Surgeons", "American Academy of Pediatrics", "Queensland Law Reform Commission", "United Nations", "Australian College of Paediatrics"], "themes": ["Male Circumcision", "Bodily Integrity", "Criminal Assault", "Informed Consent", "Human Rights", "Equal Protection", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3243b62baa2f144dc9b9e63388b5cc82f67c1c50b748f99d14ec148d19965505', 'Boyle Tuli PTSD Anl Med Surg 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3243b62baa2f144dc9b9e63388b5cc82f67c1c50b748f99d14ec148d19965505.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This retrospective cohort study investigates the prevalence of post-traumatic stress disorder (PTSD) among Filipino boys subjected to non-therapeutic ritual genital cutting (Tuli) compared to those undergoing medical circumcision. Assessing 1,577 boys aged 11\u201316 in the Batangas Province using DSM-IV criteria, the study found that 69% of boys undergoing ritual cutting and 51% undergoing medical procedures met the criteria for a PTSD diagnosis, demonstrating significantly elevated psychological trauma associated with both methods.\n\nThe authors argue that intense societal, cultural, and peer pressures force boys into undergoing these destructive, non-therapeutic procedures, despite opposition from medical ethics and international human rights standards. They conclude that non-therapeutic genital cutting constitutes a harmful violation of children''s bodily autonomy and integrity, resulting in severe psychological distress, trauma, and long-term psychosexual impairment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gregory J. Boyle", "Samuel Ramos"], "organizations": ["University of Melbourne", "Bond University", "Philippines Department of Health", "Elsevier"], "themes": ["Post-Traumatic Stress Disorder (PTSD)", "Ritual Genital Cutting (Tuli)", "Medical Circumcision", "Children''s Rights and Bodily Integrity", "Psychosexual Harm"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eb449446ba10377be929b99de1409b0a9223a6be2c94d0e6c81904eba1717900', 'Brady-Fryer, Lander Pain relief for neoonatal circ Cochrane 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eb449446ba10377be929b99de1409b0a9223a6be2c94d0e6c81904eba1717900.pdf', 'medical_journal', 'ingested', '{"date": "2004", "description": "This systematic review evaluated the efficacy and safety of various interventions used to manage pain during neonatal circumcision across 35 randomized controlled trials comprising 1,997 neonates. Interventions assessed included dorsal penile nerve block (DPNB), ring block, topical anesthetic creams (such as EMLA and 30% lidocaine), oral sucrose solutions, oral acetaminophen, and environmental adjustments like soothing music.\n\nThe review concluded that DPNB was the most effective intervention, significantly reducing physiological and behavioral pain markers like heart rate and cry duration, though it did not completely eliminate procedural pain. EMLA and topical lidocaine also significantly reduced pain compared to placebos, though EMLA was less effective than DPNB in direct comparisons. Oral sucrose, acetaminophen, and environmental modifications showed inconsistent or non-significant efficacy. Reported adverse effects for active treatments, such as minor localized bruising or erythema, were mild and transient.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Barbara Brady-Fryer", "Natasha Wiebe", "Janice A Lander"], "organizations": ["Cochrane Collaboration", "University of Alberta", "Capital Health", "American Academy of Pediatrics", "Canadian Paediatric Society"], "themes": ["Neonatal Circumcision", "Pediatric Pain Management", "Dorsal Penile Nerve Block (DPNB)", "Topical Anesthesia", "EMLA Cream", "Systematic Review and Meta-Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bb0489a80d8e4417496c12712ca881b5ce82debb0d5f4d9f54e526fabf5b731f', 'Braver Moss Jewish Inquiry Midstream 1992.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bb0489a80d8e4417496c12712ca881b5ce82debb0d5f4d9f54e526fabf5b731f.pdf', 'other', 'ingested', '{"date": "1992", "description": "In this essay, Lisa Braver Moss critically examines the traditional Jewish practice of Brit Milah (ritual circumcision) in light of modern scientific understanding and Jewish ethical principles. While acknowledging the deep historical and covenantal significance of circumcision in Judaism, Moss argues that contemporary concerns regarding infant pain, bodily integrity, and medical risks directly resonate with core Jewish teachings, including the prohibition against causing suffering to living creatures and the Golden Rule of Hillel. She challenges common rationalizations that downplay infant pain, citing pediatric findings that infants experience acute surgical trauma.\n\nDrawing on her personal experiences as a mother who harbored profound doubts when circumcising her own sons, Moss observes that the ritual has often shifted from a meaningful spiritual dedication to a perfunctory act of social or familial conformity. She notes the prevailing silence and discouragement of open debate within the Jewish community, advocating instead for an honest and thoughtful inquiry into the ethics, necessity, and modern significance of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lisa Braver Moss", "Hillel"], "organizations": ["American Academy of Pediatrics"], "themes": ["Brit Milah", "Infant Pain", "Halacha and Jewish Ethics", "Parental Conflict and Tradition", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ce46ca394513a9397806c5d92ea513ad1ff2f3472fcf79a3f828d2119ff968c1', 'Bridgewater NTMC Tackling JSexMed 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ce46ca394513a9397806c5d92ea513ad1ff2f3472fcf79a3f828d2119ff968c1.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This review examines the complex religious, cultural, social, and prophylactic incentives surrounding nontherapeutic male circumcision (NTMC), alongside the associated clinical risks and ethical dilemmas. The authors highlight that while circumcision alters bodily integrity and poses potential complications such as surgical risk, psychosocial harm, and questions regarding infant consent, prophylactic justifications (such as preventing UTIs, penile cancer, or HIV acquisition in specific populations) lack global consensus for widespread routine adoption.\n\nNevertheless, the authors conclude that clinicians must carefully evaluate an individual patient''s cultural and religious context before deciding to deny or perform NTMC. Refusing the procedure to males from communities where circumcision is a mandatory cultural rite of passage or religious requirement can result in severe social ostracism, loss of cultural heritage, discrimination, or lead individuals to seek dangerous circumcision procedures from untrained practitioners under unhygienic conditions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Caryn L. Perera", "Franklin H.G. Bridgewater", "Prema Thavaneswaran", "Guy J. Maddern"], "organizations": ["Royal Australasian College of Surgeons", "The Queen Elizabeth Hospital", "The University of Adelaide", "ASERNIP-S", "International Society for Sexual Medicine", "Royal Australasian College of Physicians", "American Academy of Pediatrics", "World Health Organization", "Australian Government Department of Health and Ageing"], "themes": ["Nontherapeutic Male Circumcision", "Medical Ethics and Informed Consent", "Bodily Integrity", "Religious and Cultural Traditions", "HIV/AIDS Prevention", "Psychosexual Outcomes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c01d915215ba2ccb77c9726b7449c69104fd23e11dc08a1a6f5af7fadce73fc1', 'Bridgewater Safety_Efficacy_NTMC AnnFamMed 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c01d915215ba2ccb77c9726b7449c69104fd23e11dc08a1a6f5af7fadce73fc1.pdf', 'medical_journal', 'ingested', '{"date": "2010-01", "description": "This systematic review evaluates the safety and efficacy of nontherapeutic male circumcision based on eight randomized controlled trials published between 1997 and 2008. The authors found that adult male circumcision was associated with a statistically significant reduction in the acquisition of HIV/AIDS among men in sub-Saharan Africa (OR = 0.44) and reduced the prevalence of self-reported genital ulcers, without adversely affecting overall sexual satisfaction or function. Severe complications were rare across operative settings, though adequate analgesia is strongly recommended for neonatal procedures to prevent pain distress and altered subsequent pain responses.\n\nDespite the significant protective effect against HIV in sub-Saharan African populations, the authors caution that findings remain uncertain for men in other global contexts with lower baseline HIV prevalence and better access to barrier methods. Additionally, evidence linking nontherapeutic male circumcision to the prevention of other sexually transmitted infections, urinary tract infections, and penile cancer remains inconclusive. Consequently, the review concludes that current clinical trial evidence does not justify recommending routine or widespread neonatal circumcision for prophylactic purposes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Caryn L. Perera", "Franklin H. G. Bridgewater", "Prema Thavaneswaran", "Guy J. Maddern"], "organizations": ["Royal Australasian College of Surgeons", "The Queen Elizabeth Hospital", "The University of Adelaide", "Australian Government Department of Health and Aging", "South Australian Department of Health", "Canadian Paediatric Society", "National Health and Medical Research Council"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Pediatric and Neonatal Health", "Pain Management and Analgesia", "Sexually Transmitted Infections", "Surgical Safety and Complications", "Sexual Health and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('387e8bf39247eaed31c609045173ea963a861195adc423f689e34dc191cc21d8', 'Brigman Circ as Child Abuse JFamLaw 1984.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/387e8bf39247eaed31c609045173ea963a861195adc423f689e34dc191cc21d8.pdf', 'legal_document', 'ingested', '{"date": "1984", "description": "This law review article examines routine neonatal male circumcision through the lens of child abuse, arguing that the procedure is medically unwarranted, physically painful, potentially dangerous, and constitutes nonaccidental disfigurement. The author details the medical and psychological consensus opposing routine circumcision, noting significant complication risks and an absence of documented physiological benefits, and contends that societal acceptance obscures its nature as child abuse.\n\nFrom a constitutional and legal perspective, the author analyzes whether parental autonomy, religious freedom under the First Amendment, or constitutional privacy rights protect the practice. The article concludes that parental custody rights and religious protections (such as those established in Wisconsin v. Yoder) do not extend to irreversible physical injury or health risks to children. Finally, the author proposes potential legal remedies to curb routine circumcision, emphasizing civil class-action lawsuits against hospitals over criminal prosecution or individualized malpractice claims.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["William E. Brigman", "Douglas Gairdner", "Robert L. Baker", "William H. Masters", "Virginia E. Johnson", "John Foley"], "organizations": ["University of Louisville School of Law", "University of Houston-Downtown", "American Academy of Pediatrics", "Mayo Clinic", "George Washington University Medical Center"], "themes": ["Neonatal Circumcision", "Child Abuse and Child Welfare Law", "Parental Rights and Family Autonomy", "Freedom of Religion and First Amendment Jurisprudence", "Bodily Integrity and Informed Consent", "Constitutional Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8a53cdd1d6275187252e9be59a85ed3b6a1f1b80a420994579ba054813fe3efa', 'Brito Bailey Sexual Pleasure VMMC satisfaction JSexMed 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8a53cdd1d6275187252e9be59a85ed3b6a1f1b80a420994579ba054813fe3efa.pdf', 'medical_journal', 'ingested', '{"date": "2017-01-27", "description": "This cohort study evaluates long-term satisfaction, sexual pleasure and function, coital trauma, and risk compensation among 362 men in the Dominican Republic who underwent voluntary medical male circumcision (VMMC) for HIV prevention, assessed 6 to 24 months post-procedure. The vast majority of participants reported high satisfaction with the procedure (98%) and perceived partner satisfaction (95%), citing improved hygiene and enhanced sexual pleasure as key factors. Furthermore, men experienced significant improvements in sexual function, erectile potency, and a substantial reduction in coital injuries such as penile swelling, abrasions, and bleeding.\n\nWhile the study observed an increase in the proportion of participants reporting two or more sexual partners in the preceding 30 days, evidence for risk compensation was mixed, as rates of casual sex decreased significantly and condom use remained stable. The authors conclude that VMMC can be safely and acceptably implemented as an effective biomedical HIV prevention strategy outside of Africa without compromising sexual function or pleasure, though programs must continue monitoring for potential risk compensation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maximo O. Brito", "Shaveta Khosla", "Sheewin Pananookooln", "Paul J. Fleming", "Leonel Lerebours", "Yeycy Donastorg", "Robert C. Bailey"], "organizations": ["University of Illinois at Chicago", "University of Michigan", "Clinica de Familia", "Instituto Dermatol\u00f3gico y Cirug\u00eda De Piel", "International Society for Sexual Medicine", "National Institutes of Health"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV and STD Prevention", "Sexual Pleasure and Function", "Coital Trauma and Injuries", "Risk Compensation and Sexual Risk Behaviors"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cba9b3c218b63a95ff12265c03ed5cd71224435a9ea5ea471100d90a049913fa', 'Brodbar-Nemzer AmericanCircumcision SSR 1987.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cba9b3c218b63a95ff12265c03ed5cd71224435a9ea5ea471100d90a049913fa.pdf', 'other', 'ingested', '{"date": "1987", "description": "This study examines the persistence of routine neonatal circumcision in the United States despite official medical statements from organizations like the American Academy of Pediatrics asserting that the procedure is not medically necessary. Investigating a cohort of 133 families who participated in natural childbirth education through the Boston Association of Childbirth Education (BACE)\u2014a group predisposed toward low medical intervention\u2014the authors found that 62% still chose to circumcise their newborn sons.\n\nThe findings reveal that circumcision decisions are overwhelmingly driven by social rather than medical reasons, specifically the desire for sons to resemble fathers and peers or adhere to religious traditions. While non-circumcising parents cited medical non-necessity and expressed firm confidence in their decisions, circumcising parents exhibited considerable cultural ambivalence and doubt, suggesting that the social reality and peer conformity surrounding male circumcision continue to override evolving medical guidelines.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jay Brodbar-Nemzer", "Peter Conrad", "Shelly Tenenbaum"], "organizations": ["Boston Association of Childbirth Education", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Brandeis University", "Clark University", "Jerusalem Fellows"], "themes": ["Neonatal Circumcision", "Social Norms vs. Medical Advice", "Parental Decision-Making", "Natural Childbirth", "Peer Conformity", "Cultural Ambivalence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1da85f28b8cd274bde67ddf04ef74f21bb229d548c7ff78d1912f7c8409049aa', 'Bronselaer Circ PenileSens BJUI 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1da85f28b8cd274bde67ddf04ef74f21bb229d548c7ff78d1912f7c8409049aa.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This study assesses the effects of male circumcision on penile sensitivity and sexual satisfaction using an online self-assessment questionnaire (SAGASF-M) administered to a large cohort of 1,059 uncircumcised and 310 circumcised men. The findings indicate that circumcised men reported significantly decreased sexual pleasure and lower orgasm intensity at the glans penis, required greater effort to achieve orgasm, and experienced higher rates of numbness, pain, and unusual sensations on both the glans and penile shaft compared to their uncircumcised counterparts.\n\nFurthermore, participants circumcised during adolescence or adulthood reported greater reductions in glans sensitivity and increased shaft discomfort compared to those circumcised in infancy or childhood. The authors conclude that the foreskin plays a crucial role in overall penile sensitivity and sexual functioning, recommending that adult men and parents considering elective, non-medical circumcision be fully counseled regarding potential permanent loss of genital sensitivity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Guy A. Bronselaer", "Justine M. Schober", "Heino F.L. Meyer-Bahlburg", "Guy T''Sjoen", "Robert Vlietinck", "Piet B. Hoebeke"], "organizations": ["Ghent University Hospital", "Hamot Medical Center", "Rockefeller University", "Columbia University", "NYS Psychiatric Institute", "University of Leuven", "BJU International"], "themes": ["Male Circumcision", "Penile Sensitivity", "Sexual Function", "Foreskin Anatomy", "Erogenous Sensation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('de5e36b9e8338da80b319123eb30690aa787a65cc7188c8587c0228fe7008571', 'Brown Circ Social Concerns Peds 1987.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/de5e36b9e8338da80b319123eb30690aa787a65cc7188c8587c0228fe7008571.pdf', 'medical_journal', 'ingested', '{"date": "1987", "description": "This study examines why routine newborn circumcision remains widespread in the United States despite official policy recommendations against it by the American Academy of Pediatrics and the American College of Obstetrics and Gynecology. Surveying parents of 124 newborn boys at Children''s Hospital at St. Luke''s Hospital, the authors found that parental decisions are overwhelmingly driven by social rather than medical factors. The strongest predictor was whether the newborn''s father was circumcised, followed by concerns about peer perception and the child''s future self-concept.\n\nThe authors conclude that infant circumcision in the United States functions primarily as a cultural ritual rather than a health-related decision. As a result, educational programs focusing solely on the lack of medical indications are largely ineffective, and healthcare providers must address parental social concerns if circumcision practices are to change significantly.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mark S. Brown", "Cheryl A. Brown"], "organizations": ["American Academy of Pediatrics", "American College of Obstetrics and Gynecology", "Children\u2019s Hospital at St Luke''s Hospital"], "themes": ["Newborn Circumcision", "Parental Decision-Making", "Cultural and Social Norms", "Pediatric Health Policy", "Medical Counseling"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('015a754d2f420586dc86a9a138834114719cde8f22a2146fe7890a4903774b6a', 'Brown FGC-MGC in Family Law OJLR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/015a754d2f420586dc86a9a138834114719cde8f22a2146fe7890a4903774b6a.pdf', 'other', 'ingested', '{"date": "2023-10-13", "description": "This article examines why family law in England and Wales draws a sharp distinction between female genital mutilation (FGM), which is treated as an intolerable criminal abuse crossing the threshold of reasonable parenting, and male circumcision, which is legally recognized as reasonable and within parental discretion. The author argues that the standard judicial justifications distinguishing the two practices\u2014namely precedent, cultural/religious distinctions, and medical or health rationales\u2014are flawed and fail upon close analytical scrutiny, particularly because both practices involve non-consensual, permanent modifications to children''s bodies that cause significant harm.\n\nInstead, the author contends that the differential treatment is justifiable through the pragmatic realities and underlying institutional features of family law. Grounded in community standards, limits of state intervention, parental autonomy, and societal context, the law reflects distinct historical and social developments: FGM was criminalized as an imported practice amid an international movement against violence toward women and girls, whereas male circumcision has deep, accepted roots in Judaeo-Christian and minority religious traditions (notably Judaism and Islam). Declaring male circumcision per se unreasonable would trigger radical and practically unmanageable state intervention, including widespread child removals, which society and the family justice system cannot sustain.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Nick Brown", "James Munby", "Oliver Wendell Holmes Jr.", "Jonathan Sacks", "Lady Hale", "Richard A. Posner"], "organizations": ["Oxford University Press", "St Philips Chambers", "British Medical Association", "American Academy of Pediatrics", "UNICEF", "World Health Organization"], "themes": ["Family Law and Child Protection", "Female Genital Mutilation (FGM)", "Male Circumcision", "Parental Autonomy and State Intervention", "Religious and Cultural Rights", "Judicial Pragmatism and Statutory Thresholds"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('43bc3930bc9e48817bcc2051eec753e7b5682e16902906c3fbf6b37504c748ed', 'Brussels Genital Modifications in Prepubescent Minors AJOB 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/43bc3930bc9e48817bcc2051eec753e7b5682e16902906c3fbf6b37504c748ed.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This article argues that clinicians should not perform any nonvoluntary genital cutting or surgery on prepubescent minors, regardless of their sex characteristics or assigned gender, unless urgently necessary to protect their physical health. The authors assert that the established bioethical consensus prohibiting medically unnecessary genital procedures in non-intersex females should be consistently extended to intersex children and endosex males, prioritizing bodily integrity, future autonomy, and personal boundaries over speculative psychosocial or aesthetic benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Pidgeon Pagonis", "Sean Saifa Wall", "Dominic Wilkinson", "Talia Mae Bettcher"], "organizations": ["The Brussels Collaboration on Bodily Integrity", "Lurie Children''s Hospital", "Boston Children''s Hospital", "New York City Health & Hospitals", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists"], "themes": ["Genital Autonomy", "Bodily Integrity", "Intersex Rights", "Pediatric Ethics", "Medical Necessity", "Parental Discretion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ab4b11f46be2d96fe5f0a94f2fcf5b456ab05570dd36c438f970daf55c3ce03c', 'Brussels Medically_unnecessary_genital_cutting_AmJBio 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ab4b11f46be2d96fe5f0a94f2fcf5b456ab05570dd36c438f970daf55c3ce03c.pdf', 'medical_journal', 'ingested', '{"date": "2019-09-26", "description": "This article by The Brussels Collaboration on Bodily Integrity evaluates the ethics and legality of medically unnecessary childhood genital cutting. Prompted by a U.S. federal court case addressing ritual female genital cutting within the Dawoodi Bohra community, the authors argue that subjecting any child to nonconsensual, nontherapeutic genital alteration constitutes a severe violation of bodily integrity. They establish that while competent adults may elect to undergo genital alterations based on personal or cultural preferences, nonautonomous children must be protected from irreversible, non-medically necessary procedures until they possess the capacity to provide informed consent.\n\nCritiquing prevailing Western medicolegal frameworks, the authors highlight troubling double standards that strictly criminalize even minor female genital modifications while continuing to permit routine infant male circumcision and medically unnecessary cosmetic surgeries on intersex infants. They contend that all forms of nonconsensual, nontherapeutic genital cutting\u2014regardless of sex or gender\u2014should be addressed coherently under human rights and autonomy principles, advocating for professional medical ethics statements, educational campaigns, and dialogue rather than selectively enforced criminal sanctions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Bernard A. Friedman", "Dena S. Davis", "Jasmine Abdulcadir", "Peter W. Adler"], "organizations": ["The Brussels Collaboration on Bodily Integrity", "World Health Organization", "Yale University", "The Hastings Center"], "themes": ["Bodily Integrity", "Informed Consent", "Children''s Rights", "Female Genital Mutilation (FGM)", "Male Circumcision", "Intersex Surgery", "Bioethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('71478c4d8b95b98946ef2b27abbcb85256cbc69c89a317043830bd3bca566cb1', 'Brutus Parent decisional regret JPedUrol 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/71478c4d8b95b98946ef2b27abbcb85256cbc69c89a317043830bd3bca566cb1.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This document consists of the header and URL references for a study titled ''Parent decisional regret regarding neonatal circumcision in an American...'' hosted on ScienceDirect. The study investigates parental decision-making and subsequent regret concerning neonatal circumcision in the United States, though specific findings and empirical data are omitted in the provided text excerpt.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["ScienceDirect"], "themes": ["Neonatal Circumcision", "Parental Decision-Making", "Decisional Regret", "Pediatrics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ef12b8487cfc27b82705b80fa8a30cd0281440cacd3c358aefabededc64d3396', 'Brutus Parental regret JPedUrol 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ef12b8487cfc27b82705b80fa8a30cd0281440cacd3c358aefabededc64d3396.pdf', 'medical_journal', 'ingested', '{"date": "2024-07-23", "description": "This study investigates parental decisional regret regarding neonatal male circumcision among families visiting an American outpatient pediatric urology clinic. Using the validated Decisional Regret Scale (DRS), the authors evaluated parents of both circumcised and uncircumcised boys to identify factors influencing levels of regret concerning their initial choices.\n\nThe findings show that while 55% of parents reported no regret, approximately 21% experienced moderate to strong regret, with no significant difference observed between parents of circumcised versus uncircumcised children. Higher regret was significantly linked to presentation for penile-related complaints, dissatisfaction with appearance, and feeling uninformed, whereas lower regret was strongly associated with physician counseling and informed decision-making. The authors conclude that comprehensive parental counseling prior to elective neonatal circumcision is essential to minimize future regret.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Nicholas N. Brutus", "Adam S. Howe", "Alexandra Rehfuss", "Karla Giramonti", "Paul J. Feustel", "Barry A. Kogan"], "organizations": ["Yale University School of Medicine", "Albany Medical Center", "Albany Medical College", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Decisional Regret", "Pediatric Urology", "Informed Consent", "Shared Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('14407c2c7f906140295db530f391f0290312fdd178d197f9d8f6027930952e82', 'Buckler Controversies rethink JME 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/14407c2c7f906140295db530f391f0290312fdd178d197f9d8f6027930952e82.pdf', 'medical_journal', 'ingested', '{"date": "2025-11-09", "description": "This article examines the growing controversies surrounding non-therapeutic childhood circumcision and critiques the intersection of medical advice, law, and cultural/religious practices. Focusing primarily on the influential 2012 American Academy of Pediatrics (AAP) policy statement\u2014which asserted that the health benefits of newborn male circumcision outweigh the risks\u2014the author draws on new interviews with AAP task force members Dr. Douglas Diekema and Dr. Andrew Freedman. These interviews reveal that the policy''s phrasing was not a purely evidence-based medical conclusion, but rather a compromise intended to act as a legal and cultural ''permission slip'' to accommodate parental discretion and religious traditions without endorsing an outright ban.\n\nThe author argues that conflating extra-medical values with objective clinical evidence has caused widespread misunderstanding, leading both the public and institutions like the CDC and BMA to erroneously interpret circumcision as medically recommended or preferable. With global controversies mounting and trust in public health institutions under strain, the article concludes that guiding medical authorities in the US, UK, and internationally must urgently rethink their policies and clearly articulate the boundary between medical necessity and non-medical practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Buckler", "Douglas Diekema", "Andrew Freedman", "Susan Blank", "Michael Brady", "Robert F. Kennedy, Jr.", "Clare Chambers"], "organizations": ["American Academy of Pediatrics", "British Medical Association", "Centers for Disease Control and Prevention", "American Medical Association", "Canadian Paediatric Society", "General Medical Council", "BMJ Group", "Johns Hopkins Medicine"], "themes": ["Non-therapeutic childhood circumcision", "Medical ethics and clinical guidance", "Separation of medical and cultural/religious practices", "Bodily integrity and parental autonomy", "Public trust in scientific and health policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e314b8d82a8ce23788efb75851af18990d81ba25c82bf5967819552fa5d27c13', 'Buckler Earp Critical_test_religious ethics Dorff 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e314b8d82a8ce23788efb75851af18990d81ba25c82bf5967819552fa5d27c13.pdf', 'other', 'ingested', '{"date": "2024", "description": "This academic chapter critically examines the role of religion in bioethics by using non-therapeutic childhood circumcision as a primary test case, focusing on the work of prominent Jewish bioethicist Rabbi Elliot N. Dorff. The authors evaluate Dorff''s foundational theological precept that ''God owns the body'' (GOTB), which generally proscribes non-therapeutic and non-voluntary bodily alterations, yet carves out a distinct exception for male infant circumcision based on religious covenant and parental duty.\n\nThe authors highlight the philosophical tensions this exception creates regarding bodily autonomy and the child''s right to bodily integrity (RBI). They argue that Dorff faces a difficult dilemma when evaluating comparable practices in other religious traditions, such as ritual pricking of the vulva among Dawoodi Bohra Muslims: either Dorff must oppose these practices on the grounds of preventing bodily harm and boundary violation (thereby undermining civic pluralism and equal treatment), or condone them under religious freedom (which conflicts with his own strictures on bodily modification and sexual inviolability). The authors conclude by inviting Dorff and other religious bioethicists to engage more deeply and consistently with child genital cutting within secular public discourse.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Max Buckler", "Brian D. Earp", "Elliot N. Dorff", "Louis E. Newman", "Jonathan K. Crane"], "organizations": ["University of Oxford", "National University of Singapore", "American Academy of Pediatrics", "World Health Organization", "Springer Nature"], "themes": ["Religious Bioethics", "Male Circumcision", "Right to Bodily Integrity", "Female Genital Cutting", "Autonomy and Consent", "Jewish Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('72a78ed184fd9cb9528061589c47a8779a1479be4573118587908794ecf25e92', 'Buckler Earp Unconsented procedures Sex Boundaries CurrSexHlth 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/72a78ed184fd9cb9528061589c47a8779a1479be4573118587908794ecf25e92.pdf', 'medical_journal', 'ingested', '{"date": "2023-12-01", "description": "This review article synthesizes scholarship from obstetric violence and children''s rights to examine nonconsensual medicalized genital procedures, including unconsented educational pelvic exams on anesthetized patients, episiotomies during labor, infant intersex surgeries, ritual vulvar nicking, and neonatal penile circumcision. The authors argue that such interventions constitute sexual boundary violations and can be experienced as medical sexual assault, irrespective of practitioner intent or estimated risk-benefit profiles, because they infringe upon an individual''s fundamental rights to bodily integrity and sexual autonomy.\n\nThe authors conclude that personal, explicit consent must serve as the primary ethical standard for any non-emergency intervention involving intimate sexual anatomy. Consequently, presumed, implied, or parental proxy consent is deemed insufficient for medically unnecessary procedures, meaning clinicians are ethically obligated to delay nontherapeutic genital examinations or surgeries until the patient possesses the capacity to provide or withhold their own informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Buckler", "Lori Bruce", "Brian D. Earp", "Dena Davis", "Larry Nassar", "Talia Mae Bettcher"], "organizations": ["University of Oxford", "Yale University", "Yale Interdisciplinary Center for Bioethics", "Uehiro Centre for Practical Ethics", "Springer Nature"], "themes": ["Informed Consent", "Obstetric Violence", "Sexual Boundary Violations", "Bodily Integrity", "Child Genital Cutting", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fc6235fd2993d5891adc5a0983742da0157b23b71dc45436d95d27956a3a8262', 'Buckler Smallest cut KennedyIEJ 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fc6235fd2993d5891adc5a0983742da0157b23b71dc45436d95d27956a3a8262.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This academic preprint examines the ethics of non-voluntary child genital cutting through the lens of hatafat dam brit (HDB), a Jewish ritual involving a superficial pinprick to draw a drop of covenantal blood from the penis. The author contrasts two prominent philosophical stances: Richard Shweder''s liberal pluralist view, which tolerates minor cutting practices provided there is no lasting physical harm or dysfunction (''no harm, no foul''), and Brian Earp''s zero-tolerance stance, which treats any medically unnecessary, nonconsensual genital intervention as a rights violation.\n\nBecause HDB leaves no scar and alters no tissue, it represents an essentialized, non-modifying form of genital cutting that cannot be justified or critiqued via standard arguments about physical damage, intactness, or medical benefit. Drawing on accounts from adult converts, parents, and Jewish religious authorities who express discomfort or recommend age limits regarding HDB, the author argues that ethical evaluations of involuntary child genital rituals should not focus primarily on body modification or measurable physical harm. Instead, the debate must center on the ethics of power-asymmetric, nonconsensual touching and boundary-based violations of a child''s sexual embodiment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Buckler", "Richard Shweder", "Brian D. Earp", "Jumana Nagarwala", "Samuel A. Kunin", "Kevin Bernstein", "Elliot N. Dorff", "David Archard"], "organizations": ["Kennedy Institute of Ethics Journal", "World Health Organization", "Central Conference of American Rabbis", "Reconstructionist Rabbinical Association", "Committee on Jewish Law and Standards", "American Academy of Pediatrics"], "themes": ["Hatafat Dam Brit", "Child Genital Cutting Ethics", "Bodily and Genital Autonomy", "Liberal Pluralism vs. Harm Principles", "Sexual Embodiment and Boundaries", "Medicalization of Religious Rituals"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bbec0f1978605f2ce1fa542b3d092f3ffe7ae44c36281cfde50c933020d3e384', 'Burgess Cutting both ways Ethics & GM AmJBio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bbec0f1978605f2ce1fa542b3d092f3ffe7ae44c36281cfde50c933020d3e384.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-12", "description": "In this commentary, Sarah Burgess and Stuart J. Murray critically respond to Allan J. Jacobs and Kavita Shah Arora''s defense of ritual male infant circumcision. The authors argue that Jacobs and Arora conflate universal human rights with localized cultural rites and parental prerogatives, using biomedical justifications to circumvent fundamental rights such as bodily integrity and autonomy. By restricting human rights only to uncontroversial or universally appreciated claims, Jacobs and Arora''s logic undermines the ethical authorization of human rights altogether.\n\nBurgess and Murray contend that human rights are fundamentally constituted through political, ideological, and institutional struggles rather than passive consensus. They caution that displacing human rights discourses in favor of historical observation and biomedical authority leaves non-consenting infants without legal or ethical protection, raising serious concerns regarding the inability to ethically oppose other non-consensual procedures, such as female genital mutilation or infant sex assignment surgery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sarah Burgess", "Stuart J. Murray", "Allan J. Jacobs", "Kavita Shah Arora", "Costas Douzinas", "Brian D. Earp", "Jacques Derrida", "Hannah Arendt"], "organizations": ["University of San Francisco", "Carleton University"], "themes": ["Bioethics", "Male Infant Circumcision", "Human Rights vs. Cultural Rites", "Bodily Integrity and Autonomy", "Biomedical Discourse", "Parental Prerogative"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8a4787b78a4b73dc5825c3a25db479f3d4538cf622bd7169838a2c122148d69d', 'Calderone Fetal Erection SIECUS Report 1983.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8a4787b78a4b73dc5825c3a25db479f3d4538cf622bd7169838a2c122148d69d.pdf', 'medical_journal', 'ingested', '{"date": "1983-05-25", "description": "In this article, Dr. Mary S. Calderone reflects on sonographic evidence of penile erection in a 29-week-old fetus, arguing that the human sexual response system is active and cyclical throughout the entire lifespan rather than initiating solely at puberty. She asserts that intrauterine erections and infancy-stage self-exploration are natural, harmless physiological reflexes akin to early digestive, circulatory, and motor functions.\n\nCalderone criticizes prevailing social taboos and parental anxieties that seek to suppress infant and childhood sexual curiosity, such as masturbation. She urges parents and medical professionals to guide children through constructive socialization\u2014focusing on privacy, place, and appropriateness\u2014rather than transmitting damaging negative conditioning across generations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mary S. Calderone", "Deborah Alley", "James W. Ramey", "Eric W. Johnson", "T. Berry Brazelton", "Thore Langfeldt"], "organizations": ["SIECUS", "New York University", "Norfolk General Hospital", "World Congress of Sexology"], "themes": ["Fetal and Infant Sexuality", "Sexual Response System", "Childhood Development", "Parental Guidance and Socialization", "Sex Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9fddf62e71eca1558d76dd1492aec2cf40486f77fff50b28402c73a1d9599124', 'Camargo, Giami Circ and HIV-facts and values GPH 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9fddf62e71eca1558d76dd1492aec2cf40486f77fff50b28402c73a1d9599124.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-08", "description": "This academic paper presents a controversy study examining the scientific and social debates surrounding male circumcision (MC) as an HIV prevention strategy from 1986 to 2013. Focusing on three key randomized controlled trials in South Africa, Uganda, and Kenya, the authors analyze the rhetoric and evidentiary claims used by proponents who argue that circumcision reduces female-to-male HIV transmission risk by up to 60%, leading major global health organizations to promote it as public policy.\n\nThe authors contrast these prevailing biomedical arguments with counter-perspectives that criticize the trials'' external validity, ethical implications, neglect of behavioral and sociocultural factors, and the marginalization of women''s health. Ultimately, the study suggests that public health policy has prioritized biomedical interventions over holistic social strategies, arguing that valid dissenting viewpoints urging caution have not been adequately considered.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kenneth Rochel de Camargo, Jr.", "Andr\u00e9 Luiz de Oliveira Mendon\u00e7a", "Christophe Perrey", "Alain Giami", "Peter Aggleton", "Marge Berer", "Robert S. Van Howe"], "organizations": ["Universidade do Estado do Rio de Janeiro", "INSERM", "Center for Research in Epidemiology and Population Health (CESP)", "World Health Organization", "UNAIDS", "World Bank", "Bill & Melinda Gates Foundation"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Science and Technology Studies", "Public Health Policy", "Medical Controversy and Ethics", "Biomedicine vs. Social Factors"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dd6a52348719e08b2c0e9ed11623617207821260ff01ebd8f88dced74409dc92', 'CanPaedSoc Neonatal circumcision revisited 1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dd6a52348719e08b2c0e9ed11623617207821260ff01ebd8f88dced74409dc92.pdf', 'policy_guideline', 'ingested', '{"date": "1996", "description": "This position statement from the Canadian Paediatric Society''s Fetus and Newborn Committee evaluates the medical evidence, risks, benefits, and costs surrounding routine neonatal circumcision. After reviewing extensive literature on urinary tract infections, sexually transmitted infections, penile cancer, cervical cancer in partners, procedural complications, and pain management, the committee concluded that routine neonatal circumcision is not medically indicated.\n\nWhile circumcision demonstrates a reduction in the incidence of infant urinary tract infections and provides some protection against penile cancer and HIV transmission, the overall low incidence of these conditions and the potential procedural risks and complications result in an evenly balanced risk-to-benefit ratio. Consequently, the society maintains its previous recommendation against routine neonatal circumcision, advising instead that parents receive balanced medical information while emphasizing the critical necessity of adequate pain control when the procedure is performed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Eugene Outerbridge", "Douglas McMillan", "Wayne Andrews", "Arne Ohlsson", "Th\u00e9r\u00e8se Perreault", "Michael Vincer", "C Robin Walker", "John Watts", "Alexander Allen", "Saroj Saigal", "T. E. Wiswell"], "organizations": ["Canadian Paediatric Society", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Society of Obstetricians and Gynaecologists of Canada"], "themes": ["Neonatal Circumcision", "Pediatric Health Guidelines", "Urinary Tract Infections", "Pain Management and Analgesia", "Cost-Benefit Analysis in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fd6238e5b9cee555c5a553129f5f6ae5491b7f856f4356ecb7c7ef9a5b3320fc', 'Cansever Psychological effects BritJMedPsych 1965.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fd6238e5b9cee555c5a553129f5f6ae5491b7f856f4356ecb7c7ef9a5b3320fc.pdf', 'medical_journal', 'ingested', '{"date": "1965", "description": "This study evaluates the psychological consequences of circumcision performed on twelve Turkish boys between the ages of 4 and 7, during the psychoanalytic phallic stage of development. Utilizing psychological assessments including the Goodenough Draw-a-Man test, Children''s Apperception Test (CAT), Rorschach protocols, and projective stories administered before and after the operation, the author finds that circumcision is perceived by young boys as an act of severe aggression and castration.\n\nThe findings indicate significant ego weakening, regression toward more primitive instinctual drives, and psychological constriction as defensive withdrawal mechanisms after surgery. Contrary to standard Freudian expectations regarding fear of retaliation from father figures, aggressive impulses were predominantly directed toward female figures (such as mothers), likely due to cultural family dynamics and the child''s association of the procedure with the female researcher and caregiver.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["G\u00f6k\u00e7e Cansever", "Sigmund Freud", "Anna Freud", "Herman Nunberg", "Fred Pine"], "organizations": ["Human Ecology Fund", "Bakirkoy Mental Hospital", "Robert College"], "themes": ["Circumcision", "Castration Anxiety", "Child Psychology", "Psychoanalytic Theory", "Ego Defense Mechanisms", "Sexual Identification"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a06925aced570261873898f062e2338f13834d9c0f065f0b85090d4e05815ced', 'Carlisle Restore Case JPsychChristy 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a06925aced570261873898f062e2338f13834d9c0f065f0b85090d4e05815ced.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This academic case study examines the psychological, spiritual, and relational journey of ''John,'' a conservative Christian man in his fifties who underwent non-surgical foreskin restoration. The author contextualizes the case within broader historical and contemporary debates surrounding neonatal circumcision, male genital self-image, and sexual functioning, countering previous clinical characterizations of restoration as a neurotic or fetishistic pursuit. \n\nJohn''s narrative illustrates how he sought divine reassurance through prayer, overcame marital hesitation, and channeled feelings of grief and anger over his non-consensual circumcision into personal restoration. The study highlights significant reported outcomes, including heightened sexual sensitivity, a transition to an internal locus of sexual arousal, enhanced marital intimacy, and a renewed sense of bodily integrity and emotional healing. The author concludes by urging healthcare providers, therapists, and spiritual directors to approach foreskin restoration with informed understanding rather than dismissal.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["G. Corey Carlisle", "John", "Jane"], "organizations": ["Christian Association for Psychological Studies", "Building Intimate Marriages", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Foreskin Restoration", "Male Circumcision", "Genital Self-Image", "Christianity and Sexuality", "Sexual Function and Intimacy", "Grief and Psychological Healing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d2f5e4d563bf867385c397cd9b38e4cad9df7b277e4e9269386736ec52aa2b0b', 'Carmack Milos Cath without retraction CanFamPhys 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d2f5e4d563bf867385c397cd9b38e4cad9df7b277e4e9269386736ec52aa2b0b.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This clinical article outlines a technique for urethral catheterization in intact prepubescent boys without forcibly retracting the foreskin. Due to historical circumcision trends in North America, many healthcare providers lack familiarity with intact penile anatomy and erroneously practice premature foreskin retraction, which risks tissue tearing, scarring, infection, and iatrogenic pathologic phimosis or paraphimosis.\n\nThe authors explain that physiologic phimosis is normal in young boys and resolves naturally over time. They describe a procedure to gently insert and guide a lubricated catheter into the urethral meatus by feel while occluding the preputial space, noting that initial urine should be discarded to avoid preputial flora contamination when culturing.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Adrienne Carmack", "Marilyn Fayre Milos"], "organizations": ["Genital Autonomy America", "Canadian Family Physician"], "themes": ["Urinary Catheterization", "Pediatric Urology", "Physiologic Phimosis", "Foreskin Care", "Iatrogenic Injury Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('558174136da88e6440277af0bad9315e97a7ffc0bea5c7b9d261cf6c1ebb0616', 'Carnes Improper Care Risk J Onc Res 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/558174136da88e6440277af0bad9315e97a7ffc0bea5c7b9d261cf6c1ebb0616.pdf', 'medical_journal', 'ingested', '{"date": "2016-05-06", "description": "This article examines the recognized risk factors for penile cancer\u2014such as phimosis, penile trauma, chronic irritation, and poor hygiene\u2014and questions the common assumption in American medicine that having an intact foreskin inherently increases cancer risk. The author argues that improper care practices common in the United States, particularly premature forced retraction and washing under the foreskin with harsh soaps, frequently cause the micro-tears, scarring, infections, and secondary phimosis that subsequently heighten cancer risk.\n\nTo test this hypothesis, the author proposes a retrospective cohort study administering questionnaires to 200 penile cancer patients across the American Midwest to assess correlations between historical genital care practices and cancer diagnosis. The document concludes that establishing improper care rather than the presence of foreskin as the underlying driver of risk factors could reduce unnecessary circumcisions, improve medical training, and foster evidence-based education regarding intact penile hygiene.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Samuel M Carnes"], "organizations": ["The University of Toledo", "Gavin Publishers", "ECPI University"], "themes": ["Penile Cancer", "Circumcision", "Foreskin Care and Hygiene", "Phimosis and Penile Trauma", "Medical Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('42db9084d95b3675144a21014a5dc192fc7bbd96dadf5c7fbcaa6a3cddd73e3a', 'Carpenter (Im)perishable Pleasure JSexRes 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/42db9084d95b3675144a21014a5dc192fc7bbd96dadf5c7fbcaa6a3cddd73e3a.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study analyzes how sexual pleasure, desire, and sexual health are framed in print news coverage of female genital cutting (FGC) and male circumcision (MC). Examining 1,902 news articles published between 1985 and 2009 across 13 U.S. and 8 English publications, the authors apply an embodied ethnosexuality framework to explore how gender, racial, and national norms influence media discourse. The findings reveal that sexual themes were present in only a minority of coverage and were treated unevenly depending on the practice and country.\n\nCoverage in both nations depicted FGC as severely reducing or eliminating female sexual pleasure and desire, reinforcing heterosexist assumptions of passive female sexuality and framing cut women through an ethnosexual lens of victimization. In contrast, depictions of MC reflected differing national embodiment norms: English media frequently presented MC as diminishing male sensation and pleasure, whereas U.S. media framed it as neutral or enhancing male sexuality. The authors conclude that news coverage shies away from nuanced discussions of sexual pleasure, instead reinscribing dominant cultural assumptions about gender, sexuality, and bodily normalcy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Laura M. Carpenter", "Heather Hensman Kettrey", "Alice Walker", "Edward Laumann", "Awa Thiam"], "organizations": ["Vanderbilt University", "Society for the Scientific Study of Sexuality", "World Health Organization", "American Academy of Pediatrics", "British Medical Association", "National Science Foundation"], "themes": ["Female Genital Cutting", "Male Circumcision", "Sexual Pleasure and Desire", "Media Framing and Journalism", "Gender and Heteronormativity", "Ethnosexuality and Embodiment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('20649593ec7de229e1a49336bf1c811876abd4c389a87c4296243fd3afd9d81b', 'Carpenter Casper Tale HIV-HPV GenderSoc 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/20649593ec7de229e1a49336bf1c811876abd4c389a87c4296243fd3afd9d81b.pdf', 'other', 'ingested', '{"date": "2009", "description": "This article examines the divergent public and political reactions to two prophylactic sexual health containment technologies: the human papillomavirus (HPV) vaccine and male circumcision for HIV prevention. Applying feminist science and technology studies (STS) and an intersectional sociological framework of containment, the authors explore why HPV vaccination mandates for adolescent girls provoked moral panic over female ''promiscuity,'' while promoting circumcision among males elicited minimal anxiety regarding boys'' sexuality in the United States.\n\nThe authors argue that these differing reactions both rely on and reproduce deeply entrenched sexual double standards structured by gender, age, race, and nationality. While female bodies are disciplined and surveilled under fears of adolescent sexual activity, male circumcision is framed largely as a neutral surgical safeguard, despite conferring only partial protection against HIV. Ultimately, the paper demonstrates how public health technologies reflect and sustain societal hierarchies and cultural ideologies regarding contagion, hygiene, and bodily control.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Laura M. Carpenter", "Monica J. Casper", "Thomas Frieden", "Anthony Fauci", "Peter Piot", "Richard Feachem"], "organizations": ["Vanderbilt University", "Arizona State University", "Centers for Disease Control and Prevention", "Food and Drug Administration", "American Academy of Pediatrics", "World Health Organization", "UNAIDS", "Merck & Co.", "GlaxoSmithKline", "Bill and Melinda Gates Foundation", "National Organization of Circumcision Information and Resource Centers"], "themes": ["HPV Vaccination", "Male Circumcision", "Sexual Health", "Gender and Sexuality", "Sexual Double Standard", "HIV/AIDS Prevention", "Hygienic Containment and Biopolitics", "Intersectionality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('018275e7e0baee9168919f0f14ee3e24dbd971bfba301bddf586a960e951789e', 'Carpenter If you prick us Gender&Hist 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/018275e7e0baee9168919f0f14ee3e24dbd971bfba301bddf586a960e951789e.pdf', 'other', 'ingested', '{"date": "2020", "description": "This article examines how shifting cultural definitions of masculinity and evolving biomedical science transformed medical and social approaches to male circumcision pain in the United States and Canada between 1960 and 2000. Historically underpinned by beliefs that infants did not experience physical pain and that manhood required stoic endurance, routine infant circumcision went largely unquestioned without anesthesia through the mid-twentieth century.\n\nFrom the 1960s onward, emerging pediatric pain research, changing masculine norms influenced by feminism and the men''s movement, and grassroots activism pushed the medical establishment to recognize neonatal pain. By the late 1990s, major pediatric organizations in both countries formally recommended pain relief during the procedure, though debates persisted regarding psychological trauma, bodily integrity, and emotional harm associated with non-conformity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Laura M. Carpenter", "Benjamin Spock", "Marilyn Milos", "Anna Taddio", "David A. Grimes", "E. Noel Preston", "John S. MacKay"], "organizations": ["American Academy of Pediatrics", "Canadian Paediatric Society", "National Organization of Circumcision Information Centers", "National Organization to Halt the Abuse and Routine Mutilation of Males", "Association for Genital Integrity", "National Organization for Restoring Men"], "themes": ["Masculinity and Gender Constructs", "Pediatric Pain Management", "Routine Male Circumcision", "Medicalization and Bioethics", "Health Social Movements and Activism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('695a9e8ab5cad17fde084cf0404134818b65436eb1d48e058f99835efa1faaef', 'Carpenter Newman Embodiment without Bodies SocHlthIllness 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/695a9e8ab5cad17fde084cf0404134818b65436eb1d48e058f99835efa1faaef.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This article examines the concept of embodiment within embodied health movements (EHMs) through the lens of US-based pro-breastfeeding and anti-male circumcision activism. While traditional EHMs rely on activists drawing from their own direct physical and bodily experiences, the authors demonstrate that these two movements frequently utilize ''embodiment by proxy,'' wherein activists base their advocacy on the imagined sensations, health risks, and bodily autonomy of others, such as infants and children. Consequently, the authors argue that sociological theories of health social movements must be expanded to account for embodiment by proxy and its impact on activist strategies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Harmony D. Newman", "Laura M. Carpenter"], "organizations": ["University of Northern Colorado", "Vanderbilt University", "Foundation for the Sociology of Health & Illness", "John Wiley & Sons Ltd."], "themes": ["Embodied Health Movements", "Embodiment by Proxy", "Breastfeeding Advocacy", "Anti-Circumcision Activism", "Health Social Movements", "Bodily Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b3efb7fa7decaa74f22e3eb2b4c7125ee6dbb53bfa51ee440e07e0f5d129eeb6', 'Castro Acceptability Hispanics .pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b3efb7fa7decaa74f22e3eb2b4c7125ee6dbb53bfa51ee440e07e0f5d129eeb6.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This original research article investigates the acceptability of neonatal male circumcision among Hispanic expectant and new parents in South Florida. Despite historically low circumcision rates among Hispanic populations in the United States, the authors found a surprisingly high willingness (85%) among participants to circumcise their sons if the procedure were performed safely in a hospital and provided free of charge.\n\nThe authors argue that neonatal circumcision offers a significant, cost-effective opportunity to reduce long-term ethnic disparities in HIV and STD incidence. They conclude that barriers such as procedure costs, Medicaid coverage limits, and a lack of informed guidance from healthcare providers impede adoption, indicating a need for targeted public health education and physician engagement within Hispanic communities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J G Castro", "D L Jones", "M R L\u00f3pez", "K Deeb", "I Barradas", "S M Weiss"], "organizations": ["University of Miami, Miller School of Medicine", "Florida Department of Health", "National Institutes of Health", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "HIV Prevention", "Hispanic Health Disparities", "Public Health and Preventative Medicine", "Cultural Acceptability and Acculturation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8c0c4abc82a53c1dd4627236b52ea9a9a858d6856442c7ba55e10bbd3084dd88', 'Catania FGM Pleasure JSexMed 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8c0c4abc82a53c1dd4627236b52ea9a9a858d6856442c7ba55e10bbd3084dd88.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This academic paper investigates sexual functioning, pleasure, and the capacity for orgasm among women who have undergone female genital mutilation/cutting (FGM/C). Analyzing data across four study groups\u2014including adult immigrants, young women living in Western countries, infibulated women, and women post-defibulation\u2014the authors find that a high percentage of cut women are capable of experiencing sexual pleasure and orgasm. The authors emphasize that internal female erectile structures critical for sexual response frequently remain intact following FGM/C procedures.\n\nThe findings challenge the widespread assumption among Western clinicians that FGM/C completely eliminates sexual function, while highlighting the complex interplay of anatomy, physiology, and sociocultural conditioning. The study notes that while intact erectile anatomy allows for orgasmic capability, social stigmatization and cultural conflict in Western contexts can lead to psychological distress and iatrogenic sexual dysfunction, demonstrating the need for culturally competent clinical care, defibulation, and sex therapy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lucrezia Catania", "Omar Abdulcadir", "Vincenzo Puppo", "Jole Baldaro Verde", "Jasmine Abdulcadir", "Dalmar Abdulcadir"], "organizations": ["Research Center for Preventing and Curing Complications of FGM/C", "Italian Centre for Sexology", "Centre for Interdisciplinary Research in Sexology", "World Health Organization", "International Society for Sexual Medicine"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Female Sexuality and Orgasm", "Infibulation and Defibulation", "Female Erectile Anatomy", "Psychosexual Well-being and Cultural Acculturation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ff5f1a4c6501786fc9b8830b8200058a3ffb2b35ab02d7799480915a9e6c4020', 'CDC Background to Inform Providers 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ff5f1a4c6501786fc9b8830b8200058a3ffb2b35ab02d7799480915a9e6c4020.pdf', 'policy_guideline', 'ingested', '{"date": "2018", "description": "This document synthesizes scientific evidence compiled by the Centers for Disease Control and Prevention (CDC) to inform clinical guidance for healthcare providers counseling male patients and parents on male circumcision. Evaluating data from randomized controlled trials, observational studies, and meta-analyses, the report demonstrates that male circumcision significantly reduces female-to-male transmission of HIV by 50% to 60%, while also lowering the incidence and prevalence of other sexually transmitted infections, such as high-risk HPV, HSV-2, genital ulcer disease, and trichomoniasis. Furthermore, circumcision is associated with decreased risks of infant urinary tract infections, penile cancer, and cervical cancer in female partners.\n\nThe report also evaluates the safety profile, potential adverse events, and impacts on sexual function, concluding that serious complications are rare\u2014particularly when performed during the neonatal period\u2014and that circumcision does not compromise sexual sensation or performance. Translating these findings to the United States, the synthesis discusses the domestic HIV epidemiology, the varying rates of circumcision across racial and ethnic populations, parental and adult acceptability, economic cost-effectiveness, and Medicaid reimbursement policies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["Centers for Disease Control and Prevention", "Division of HIV/AIDS Prevention", "National Center for HIV/AIDS, Viral Hepatitis, STD, and TB Prevention", "U.S. Department of Health and Human Services", "World Health Organization", "Joint United Nations Programme on HIV/AIDS", "American Academy of Pediatrics", "Public Health Ethics Committee"], "themes": ["Male Circumcision", "HIV Prevention and Transmission", "Sexually Transmitted Infections", "Neonatal and Infant Health", "Penile and Cervical Cancer", "Healthcare Provider Guidance and Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f342b8bb63bfa3b14a614b0b6afd022ae64ab4ac7276c4d8918648ce475f4f9b', 'Cepeda Immunohistol prepuce IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f342b8bb63bfa3b14a614b0b6afd022ae64ab4ac7276c4d8918648ce475f4f9b.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This immunohistological study analyzes the density and distribution of neural tissue across the longitudinal and transverse axes of human fetal, adult preputial, and cadaveric penile specimens. The researchers propose an innervation gradient hypothesis, demonstrating that cutaneous and subcutaneous nerve bundles and sensory corpuscles are most densely concentrated in the prepuce\u2014particularly in the distal third of the ventral aspect\u2014and decline proximally and dorsally. The study also identifies dual autonomic innervation (sympathetic noradrenergic and parasympathetic nitrergic) in the preputial dartos and neurovascular structures, as well as early fetal development of intraepithelial nerve fibers.\n\nThe authors conclude that the rich innervation concentrated in the ventral prepuce forms an essential neuroanatomical substrate for sexual sensation and reflexogenic pathways. Consequently, deep incisions, excessive tissue resection, or aggressive cauterization during circumcision may disrupt these superficial and ventrally biased neural networks, providing an organic anatomical mechanism for reported post-circumcision sensory loss and sexual dysfunction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alfonso Cepeda-Emiliani", "Marina G\u00e1ndara-Cort\u00e9s", "Mar\u00eda Otero-Al\u00e9n", "Heidy Garc\u00eda", "Juan Su\u00e1rez-Quintanilla", "Tom\u00e1s Garc\u00eda-Caballero", "Rosal\u00eda Gallego", "Luc\u00eda Garc\u00eda-Caballero"], "organizations": ["University of Santiago de Compostela", "University Clinical Hospital, Santiago de Compostela", "Health Research Institute of Santiago (IDIS)", "National Institute of Legal Medicine and Forensic Sciences of Colombia", "Springer Nature"], "themes": ["Penile Neuroanatomy", "Preputial Innervation and Histology", "Circumcision and Sexual Sensation", "Immunohistochemistry", "Neural Gradient Hypothesis", "Peripheral Somatosensory Receptors"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c75640de2abad40c40345d557f60c6d66b410f20cc053b23ebca55a29e0c515c', 'Cepeda-Emiliani Immunohistological WAS Abstract 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c75640de2abad40c40345d557f60c6d66b410f20cc053b23ebca55a29e0c515c.pdf', 'medical_journal', 'ingested', '{"date": "2023-11-02", "description": "This abstract presents an immunohistological and neurodevelopmental study examining the peripheral neural substrates responsible for penile sexual sensation, specifically tracking fetal and postnatal development. Using fetal, adult cadaveric, and post-circumcision specimens, the authors mapped nerve extension, receptor densities, and neurovascular innervation in the glans, urethra, and prepuce from early gestation into adulthood. The findings emphasize that the external genitalia comprise highly specialized sensory tissues, advising that surgical excision of genital tissue should be strictly limited to essential medical needs to preserve anatomical and sexual function.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alfonso Cepeda-emiliani", "Luc\u00eda Garc\u00eda-caballero", "Marina G\u00e1ndara-cort\u00e9s", "Tom\u00e1s Garc\u00eda-caballero", "Rosal\u00eda Gallego", "Cold", "Taylor"], "organizations": ["World Association for Sexual Health", "University of Santiago de Compostela"], "themes": ["Neurodevelopmental Biology", "Penile Innervation", "Immunohistology", "Penile Surgery", "Circumcision", "Sexual Sensation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('747e68b05ccedd7313e731d18a969c2f79198e9548b3b689e0bb09bb4e7e618d', 'Cepeda‐Emiliani - The sensory penis Andrology 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/747e68b05ccedd7313e731d18a969c2f79198e9548b3b689e0bb09bb4e7e618d.pdf', 'medical_journal', 'ingested', '{"date": "2025-08-30", "description": "This study provides a comprehensive immunohistological and ontogenetic investigation into human penile innervation using 30 fetal and 14 adult cadaveric penile specimens. The researchers identified two distinct stages of fetal penile neurodevelopment: an early pre-corpuscular/hyperinnervation phase (8\u201316 weeks) defined by robust axonal outgrowth and intraepithelial nerve proliferation concentrated ventrally, followed by a corpuscular/neural pruning stage (17\u201324 weeks) marked by selective axon retraction and the emergence of developing Pacinian corpuscles. \n\nIn adult specimens, neuroanatomical mapping demonstrated a persistent concentration of nerve bundles and diverse mechanoreceptors within the frenular delta and ventral glans, alongside autonomic innervation of the preputial dartos and vasculature. Additionally, the study confirmed the presence of a distinct fibroelastic glans tunica albuginea enveloping the corpus spongiosum and identified intracorporeal Pacinian corpuscles in the glans and penile bulb. These findings provide an anatomical framework that informs surgical interventions, such as circumcision and selective penile neurotomy, while elucidating the neural mechanisms underlying penile sexual sensation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alfonso Cepeda-Emiliani", "Mar\u00eda Otero-Al\u00e9n", "Juan Su\u00e1rez-Quintanilla", "Marina G\u00e1ndara-Cort\u00e9s", "Tom\u00e1s Garc\u00eda-Caballero", "Rosal\u00eda Gallego", "Luc\u00eda Garc\u00eda-Caballero"], "organizations": ["University of Santiago de Compostela", "Health Research Institute of Santiago (IDIS)", "University Clinical Hospital, Santiago de Compostela", "Complutense University of Madrid", "American Society of Andrology", "European Academy of Andrology", "John Wiley & Sons Ltd"], "themes": ["Penile Neurodevelopment and Ontogeny", "Sensory Innervation and Mechanoreceptors", "Frenular Delta and Sexual Sensation", "Immunohistochemistry and Molecular Profiling", "Glans Tunica Albuginea", "Preputial Dartos Innervation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9e60fc33b3b0488f35e99071efc5e91de56bb1f579f12b78cc111f7dbedf806b', 'Chamberlain Babies Dont Feel Pain JOPPPAH 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9e60fc33b3b0488f35e99071efc5e91de56bb1f579f12b78cc111f7dbedf806b.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This academic paper examines the medical establishment''s century-long denial of infant pain during the 20th century, which arose from flawed assumptions regarding neurological immaturity and ingrained guild traditions. Author David B. Chamberlain details how medical professionals routinely carried out invasive obstetric routines, neonatal intensive care procedures, major surgeries, and circumcisions without anesthesia, treating infant responses as mere non-conscious reflexes.\n\nChamberlain presents substantial empirical evidence proving that neonates and fetuses actively feel and remember pain, citing distinct crying acoustics, facial grimacing, motor defenses, and profound hormonal and vital sign disturbances. Pointing to pivotal research by Kanwal Anand demonstrating the severe metabolic and shock risks of unanesthetized surgery, as well as rising pushback from activist parent groups, legal human rights frameworks, and medical professionals, Chamberlain argues that medicine''s era of denial is concluding and urges the standard adoption of comprehensive pain management for infants.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David B. Chamberlain", "Kanwal J. S. Anand", "Jill Lawson", "Myrtle McGraw", "Mary Blanton", "Edgar J. Schoen", "Lloyd DeMause"], "organizations": ["American Academy of Pediatrics", "American Medical Association", "Johns Hopkins University", "Columbia University", "Northwestern University", "Doctors Opposed to Circumcision (D.O.C.)", "NOCIRC", "United Nations"], "themes": ["Infant Pain Perception", "Neonatal Surgery without Anesthesia", "Routine Circumcision", "Medical Dogma and Guild Tradition", "Trauma and Neurobiological Sequelae", "Medical Ethics in Neonatology and Obstetrics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b3c41e6f7a467798f4d95226bac6e1b74f17c94accc88b486f7d09d99a6b12be', 'Chapin Don’t Ask, Don’t Sell  IntAmerBlog 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b3c41e6f7a467798f4d95226bac6e1b74f17c94accc88b486f7d09d99a6b12be.pdf', 'other', 'ingested', '{"date": "2013-03-27", "description": "In this blog post, Intact America executive director Georganne Chapin argues that developing better informed consent forms is an ineffective method to reduce infant circumcision, asserting that parental consent cannot validate a medically unnecessary surgical procedure. Instead, Chapin proposes a harm reduction policy termed ''don''t ask, don''t sell''\u2014modeled after public health restrictions on tobacco display\u2014where healthcare providers and hospital staff would be barred from proactively soliciting, offering, or bringing up circumcision to new parents unless specifically initiated by the parents.\n\nChapin contends that demand for neonatal circumcision in the United States is primarily driven by financially motivated sales tactics within hospitals rather than genuine parental desire, citing ethical guidelines against providing unnecessary care. The post concludes with a community discussion featuring commentary on historical policy parallels (such as in New Zealand), medical-legal liabilities, and the role of organizations like the American Academy of Pediatrics.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Georganne Chapin", "Thomas Farley", "John V. Geisheker", "Dan Bollinger"], "organizations": ["Intact America", "American Medical Association", "American Academy of Pediatrics", "Doctors Opposing Circumcision", "The Whole Network", "National Public Radio"], "themes": ["Infant Circumcision", "Informed Consent", "Medical Ethics", "Harm Reduction", "Commercialization of Healthcare", "Children''s Rights and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3db32e22862ed63713b59d8a070d7e2f503efb3955dafa20ec58e222d19589da', 'Chen Circ Satisfaction Taiwan SciReports 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3db32e22862ed63713b59d8a070d7e2f503efb3955dafa20ec58e222d19589da.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This cross-sectional study investigated factors influencing patient satisfaction with male circumcision among 376 men aged 20 to 40 in Taiwan using an online questionnaire. Approximately 66.2% of participants reported satisfaction with the surgical outcome. Univariate analysis revealed that satisfaction was significantly higher among men who underwent circumcision during adulthood, had higher education levels, and had the procedure to treat pathological conditions such as phimosis or balanitis, whereas involuntary circumcision directed by parents was associated with dissatisfaction.\n\nMultivariate logistic regression demonstrated that undergoing circumcision during adulthood and the absence of long-term postoperative complaints\u2014specifically skin colour mismatch, hypertrophic scarring, and excessive shortening of the prepuce\u2014were independent predictors of satisfaction. Subjective perception of increased penile length was associated with satisfaction, while changes in ejaculatory latency time had no significant effect. The authors conclude that honoring patient autonomy, ensuring proper preoperative patient selection, and minimizing aesthetic and functional complications are crucial to improving satisfaction rates.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Chia Hung Chen", "Wei-Ming Cheng", "Yu-Hua Fan", "Tung-Ping Chang"], "organizations": ["Taipei City Hospital", "National Yang Ming Chiao Tung University", "Taipei Veterans General Hospital", "Springer Nature"], "themes": ["Male Circumcision", "Patient Satisfaction", "Urology", "Postoperative Complications", "Sexual Health", "Patient Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('33a63989d5f8a78169f6c9974aa619c4e79fa43126be21a170408f71368e4181', 'Chessler Justifying Unjustifiable Rite v. Wrong BuffLawRev 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/33a63989d5f8a78169f6c9974aa619c4e79fa43126be21a170408f71368e4181.pdf', 'other', 'ingested', '{"date": "1997-04-01", "description": "This academic comment argues against the widespread Western practice of routine infant male circumcision by drawing direct parallels to female genital mutilation (female circumcision). The author critiques the global and Western legal communities for condemning female circumcision as a severe human rights violation while continuing to tolerate and routinely perform male circumcision. It asserts that both procedures involve non-consensual bodily alteration, cause acute pain and potential long-term psychological and physical trauma, and are maintained by cultural conformism, flawed medical arguments, and religious traditions.\n\nThe article examines international human rights instruments (such as the Convention on the Rights of the Child and the Universal Declaration of Human Rights) alongside domestic legal avenues\u2014including child abuse statutes, civil suits under the informed consent doctrine, and constitutional analyses regarding parental rights and religious freedom. It concludes that male circumcision violates an infant''s fundamental right to bodily integrity and calls for legal reforms, clinical accountability, and public education campaigns to end the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Abbie J. Chessler", "David Filvaroff", "Isabel Marcus", "Nahid Toubia", "Harry Reid", "Patricia Schroeder", "Bill Clinton", "Edgar J. Schoen", "Edward O. Laumann"], "organizations": ["University at Buffalo School of Law", "American Academy of Pediatrics", "American College of Obstetrics and Gynecology", "United Nations", "National Organization to Halt the Abuse and Mutilation of Males (NOHARMM)", "Inter-African Committee on Traditional Practices Affecting the Health of Women and Children"], "themes": ["Male and Female Circumcision", "Human Rights", "Child Abuse and Bodily Integrity", "Informed Consent and Medical Ethics", "Parental Rights vs. State Interest", "Freedom of Religion and Constitutional Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1aa7e5a85870eac0eacf31f0d32a4ff455e30681c9e13f9077a0e92624add0d', 'Chikutsa Circ Risky Behavior 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1aa7e5a85870eac0eacf31f0d32a4ff455e30681c9e13f9077a0e92624add0d.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study analyzes data from 7,480 men aged 15\u201345 surveyed in the 2010\u201311 Zimbabwe Demographic and Health Survey to assess whether the desire for voluntary medical male circumcision (VMMC) correlates with risky sexual behaviour. Grounded in Cognitive Dissonance Theory, the authors hypothesize that men engaging in high-risk sexual practices seek circumcision as a protective measure to alleviate risk anxiety. The findings confirmed a significant association: men wanting circumcision were significantly more likely to report multiple sexual partners, having paid for sex, and having had risky non-marital sex, while being less likely to have used a condom during their last risky encounter.\n\nDemographic analysis revealed that willingness to get circumcised was higher among men aged 25\u201334, those in the highest wealth tercile, married or formerly married men, and residents of Matabeleland, Midlands, and Bulawayo. Conversely, older men, rural residents, and Christian men exhibited lower demand. The authors conclude that while targeting men who engage in high-risk behaviour for VMMC is beneficial, public health messaging must continue prioritizing conventional prevention strategies\u2014such as consistent condom use and partner reduction\u2014to prevent risk compensation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antony Chikutsa", "Alfred C Ncube", "Shepard Mutsau"], "organizations": ["Zimbabwe Open University", "BioMed Central", "ICF International", "USAID"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV Prevention", "Risky Sexual Behaviour", "Cognitive Dissonance", "Public Health Demographics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e37afb32d5fc11b7f2e38b5f8ce11c88b326873174f63efc9541640d2b1e4ed5', 'Chikutsa Social_representations Zimbabwe BMC 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e37afb32d5fc11b7f2e38b5f8ce11c88b326873174f63efc9541640d2b1e4ed5.pdf', 'medical_journal', 'ingested', '{"date": "2015-06-25", "description": "This qualitative study investigates the social representations and cultural perceptions influencing the uptake of voluntary medical male circumcision (VMMC) as an HIV prevention measure in Harare, Zimbabwe. Despite evidence supporting the clinical efficacy and widespread knowledge of VMMC, actual uptake has remained lower than targeted. Drawing on focus group discussions with men and women alongside key informant interviews, the researchers examine the socially constructed meanings and barriers surrounding the procedure.\n\nThe findings reveal that circumcision is frequently perceived as an alien cultural practice or inappropriate for adult married men, with persistent rumors associating it with satanic rituals, foreskin trafficking, or physical disability. The study also documented substantial confusion regarding post-circumcision sexual health, notably beliefs that circumcised men no longer require condoms and anxieties that the procedure could incite sexual promiscuity or marital discord. The authors conclude that public health initiatives must move beyond general awareness and actively tailor communication strategies to dismantle local myths, clarify the continued necessity of condom use, and sensitively engage female partners.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antony Chikutsa", "Pranitha Maharaj"], "organizations": ["World Health Organisation", "University of KwaZulu Natal", "Zimbabwe Open University", "Ministry of Health and Child Care", "Zimbabwe National AIDS Council", "Zimbabwe National Family Planning Council", "Zimbabwe Council of Churches", "Evangelical Fellowship of Zimbabwe"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV/AIDS Prevention", "Social Representations", "Cultural Barriers and Stigma", "Condom Use and Risk Compensation", "Sexual Health and Gender Dynamics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('67e4e3287fcdc936609798f6b0db150170ed81dd2bf03cabbb0976f9c2f51c3b', 'Chikutsa Support_VMMC Zimbabwe 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/67e4e3287fcdc936609798f6b0db150170ed81dd2bf03cabbb0976f9c2f51c3b.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study examines the levels of knowledge, acceptability, and willingness regarding voluntary medical male circumcision (VMMC) for HIV prevention among 681 men and women in Harare, Zimbabwe. Utilizing the Health Belief Model, the researchers assessed demographic factors, risk perceptions, and awareness to determine what drives circumcision uptake in an effort to reach national targets for HIV risk reduction.\n\nWhile the findings demonstrate high overall awareness (over 96%) and strong general support for VMMC promotion, a significant gap was identified between acceptability and personal uptake. Less than half (43.3%) of uncircumcised male participants expressed willingness to undergo the procedure, with many citing barriers such as the inability to take time away from work and employer constraints. The authors highlight the need for tailored interventions, improved female engagement, and broader contextual support to effectively translate awareness into actual surgical uptake.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antony Chikutsa", "Pranitha Maharaj"], "organizations": ["University of KwaZulu-Natal", "Ministry of Health and Child Care", "World Health Organization", "UNAIDS", "USAID", "Zimbabwe National Statistics Agency"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV Prevention", "Health Belief Model", "Reproductive Health", "Public Health Promotion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('db2a967ba09aaecb06fe8614a3df8914ac94d4ec190401b0c7ea9575b297ed5c', 'Christensen-Szalanski Parents-Is More Info Better MedCare 1987.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/db2a967ba09aaecb06fe8614a3df8914ac94d4ec190401b0c7ea9575b297ed5c.pdf', 'medical_journal', 'ingested', '{"date": "1987", "description": "This study evaluates whether comprehensive disclosure of medical risks alters parental decision-making regarding elective neonatal circumcision, comparing standard partial physician disclosure against detailed written and verbal disclosures of potential complications. The authors observed that physicians typically inform parents of only a small fraction of risks based on subjective assessments of ''expected seriousness,'' which systematically underestimate complication severity relative to maternal perceptions and misestimate actual frequencies.\n\nDespite these biases, providing mothers with comprehensive, objective risk information did not change their ultimate decisions to proceed with or decline circumcision, as these choices were overwhelmingly guided by social, cultural, and religious factors rather than medical data. Instead, full disclosure decreased maternal confidence in their choices, induced feelings of guilt and resentment toward healthcare providers, and increased physician burden. Consequently, the authors conclude that more information is not inherently better and advocate for a flexible, tailored approach to informed consent rather than rigid mandates for total disclosure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jay J. J. Christensen-Szalanski", "W. Thomas Boyce", "Harriet Harrell", "Mary M. Gardner"], "organizations": ["University of Iowa", "University of Arizona", "University of California, San Francisco", "American Academy of Pediatrics", "Society for Medical Decision Making"], "themes": ["Informed Consent", "Neonatal Circumcision", "Physician-Patient Communication", "Medical Decision Making", "Risk Perception and Disclosure", "Patient Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ee2eeac8973313058ae0a9b73cebe78b972be0ba131aa57d40b553e9a1808a48', 'Chung Novoglan trial TAU 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ee2eeac8973313058ae0a9b73cebe78b972be0ba131aa57d40b553e9a1808a48.pdf', 'medical_journal', 'ingested', '{"date": "2023-07-25", "description": "This article presents the findings of the Novoglan-01 open-label clinical trial, which investigated the safety, efficacy, and tolerability of the Novoglan medical device as a conservative, non-surgical alternative to circumcision for adult phimosis. The device utilizes a custom-moulded, user-controlled balloon inserted under the foreskin twice daily over 4 to 8 weeks to stimulate gradual tissue expansion and prepuce dilation.\n\nConducted on 20 adult male participants across two Australian hospitals, the trial demonstrated high efficacy, with 90% showing improved foreskin retraction and 100% achieving complete retraction (Grade 5 or 6) at the final assessment. Additionally, participants reported marked reductions in anxiety and sexual discomfort, 95% expressed satisfaction, and no adverse events occurred, confirming the device''s potential as an effective first-line conservative therapy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eric Chung", "Dmitry Polikarpov", "Hubert Mazure", "Andrew James", "Hassan Doosti", "Douglas Campbell", "David Gillatt"], "organizations": ["Princess Alexandra Hospital", "Royal Prince Alfred Hospital", "HGM Consultants", "Platigo Solutions Pty Ltd.", "Macquarie University", "Macquarie University Hospital", "Minomic International Ltd.", "Therapeutic Goods Administration"], "themes": ["Adult Male Phimosis", "Circumcision Alternatives", "Balloon Tissue Expansion", "Urological Medical Devices", "Conservative Clinical Interventions", "Quality of Life and Patient Tolerability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0ac04d23c83aa7ff430b4b786a6f84a762a7a3766bade6bc9259a033037618ed', 'Circ Fees & Practices OBG Mgmt 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0ac04d23c83aa7ff430b4b786a6f84a762a7a3766bade6bc9259a033037618ed.pdf', 'medical_journal', 'ingested', '{"date": "1994-10", "description": "A survey conducted by OBG Management among more than 200 obstetrician-gynecologists reveals national trends in neonatal circumcision fees, prevalence, and anesthesia practices. Nationwide, fees averaged $137, ranging widely by region\u2014with the highest fees in the Mid-Atlantic states (averaging $204 to $237.50 in New Jersey) and the lowest in the West, Midwest, and South ($50 to $98). Age also influenced practice patterns: younger physicians (aged 34 and younger) charged the highest fees and were the most likely to perform the procedure, but were the least likely to use anesthetic, with only 4% reporting its use.\n\nOverall, 74% of surveyed Ob/Gyns perform circumcisions, with non-performers citing dropping obstetrics or deferring the procedure to pediatricians. Despite public controversy surrounding infant circumcision, respondents reported that approximately 85% to 90% or more of male infants delivered are circumcised within their first month of life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tom Garry"], "organizations": ["OBG Management", "American College of Obstetricians and Gynecologists (ACOG)", "Syntex Puerto Rico, Inc."], "themes": ["Neonatal Circumcision", "Medical Fees and Healthcare Economics", "Anesthesia and Pain Management in Infants", "Obstetric and Gynecologic Practice Trends"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0fbfd08a14b95be1aa4262a649270c09fd5e99ee704b43cf217c708411c972cd', 'Circ How to get reimbursed OBG Mgmt1993.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0fbfd08a14b95be1aa4262a649270c09fd5e99ee704b43cf217c708411c972cd.pdf', 'medical_journal', 'ingested', '{"date": "1993", "description": "This Reimbursement Adviser column provides practical guidance for obstetrics and gynecology practitioners on navigating medical coding and insurance reimbursement. It covers appropriate diagnostic and procedural coding for routine newborn circumcision, fractional dilation and curettage (D&C), endometrial ablation, and multiple antepartum visits. Key advice includes using proper ICD-9 and CPT codes, avoiding inappropriate double-coding, and billing circumcisions under the infant''s ID rather than the mother''s to prevent automated claim rejections caused by payer sex edits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Frank W. Ling", "Mark Dowden", "Carroll V. Dowden", "Robert J. Osborn", "Gloria A. Bachmann", "Jeffrey P. Phelan"], "organizations": ["Dowden Publishing Company", "St. Anthony Publishing", "Medicaid", "American College of Obstetricians and Gynecologists"], "themes": ["Medical Billing and Coding", "Obstetrics and Gynecology", "Insurance Reimbursement", "CPT and ICD-9 Coding Guidelines"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dc40eb4893dce20608cfecddb9d8468ce9005c58de85d435f6372c15ff1becf0', 'Circ Phallic Period Armagan Andrologia 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dc40eb4893dce20608cfecddb9d8468ce9005c58de85d435f6372c15ff1becf0.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This cross-sectional study investigates whether male circumcision performed during the phallic stage of psychosexual development (ages 3 to 6) leads to adverse psychosexual and psychological outcomes in adult life. Evaluating 302 healthy, sexually active men aged 30 to 40 in Turkey, the researchers assessed outcomes using validated clinical questionnaires, including the International Index of Erectile Function (IIEF), the Premature Ejaculation Diagnostic Tool (PEDT), and the Beck Depression Inventory (BDI).\n\nThe findings revealed no statistically significant differences between men circumcised during the phallic period and those circumcised during nonphallic periods regarding total erectile function, orgasmic function, sexual desire, intercourse satisfaction, overall satisfaction, premature ejaculation rates, or depression scores. The authors conclude that undergoing circumcision during the phallic period does not negatively impact psychosexual health or psychological well-being in adulthood.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Abdullah Armagan", "M. S. Silay", "T. Karatag", "T. Akman", "A. Tepeler", "C. Ersoz", "M. Akcay"], "organizations": ["Bezmialem Vakif University", "Karapinar State Hospital", "Blackwell Verlag GmbH"], "themes": ["Male Circumcision", "Psychosexual Development", "Erectile Dysfunction", "Premature Ejaculation", "Adult Mental Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('94d9a6c95891fcc3d9a86f8bc0fdc23ffd473d3e35cc3647f633d801fa7daa04', 'Circ Unethical Unlawful JLME 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/94d9a6c95891fcc3d9a86f8bc0fdc23ffd473d3e35cc3647f633d801fa7daa04.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article presents a comprehensive critique of non-therapeutic neonatal male circumcision, arguing that the practice lacks valid medical justification, breaches fundamental tenets of medical ethics, and violates statutory, constitutional, and international human rights law. The authors directly challenge the American Academy of Pediatrics'' (AAP) 2012 policy and CDC guidelines, asserting that alleged benefits\u2014such as reductions in urinary tract infections, penile cancer, and heterosexual HIV transmission\u2014are scientifically overstated, methodologically flawed, or achievable through non-invasive means. In contrast, they emphasize the documented risks and harms, including acute surgical trauma, lifelong loss of functional and sensitive specialized tissue, sexual dysfunction, and potential psychological trauma.\n\nFrom ethical and legal perspectives, the authors argue that infant circumcision violates the cardinal ethical principles of autonomy, non-maleficence, beneficence, and justice, as well as specific medical rules against unnecessary surgery. They assert that parental proxy consent for non-essential, irreversible surgery on healthy children is legally invalid, as parents do not possess a legal or religious right to violate a child''s bodily integrity. Consequently, the authors conclude that performing or facilitating non-therapeutic circumcision exposes physicians to potential legal liability and renders elective Medicaid reimbursement unlawful.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. Steven Svoboda", "Peter W. Adler", "Robert S. Van Howe", "Michael Brady", "Douglas Diekema"], "organizations": ["Attorneys for the Rights of the Child", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Royal Dutch Medical Association", "American Medical Association", "Canadian Paediatric Society", "Intact America"], "themes": ["Male Circumcision", "Medical Ethics", "Bodily Integrity", "Children''s Human Rights", "Informed and Proxy Consent", "Physician Liability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b2afd03eb27fe6d4c672db6172f6bbd867abc37087c897f636b5ddbccdb67d2b', 'Cirilli Phimostop TAU 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b2afd03eb27fe6d4c672db6172f6bbd867abc37087c897f636b5ddbccdb67d2b.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This prospective clinical trial evaluates the efficacy and durability of PhimoStop\u2122, a minimally invasive device utilizing progressive silicone tuboids to treat adult male phimosis without surgery. The study enrolled 85 adult males with mild-to-moderate phimosis (Kikiros grade \u22642) scheduled for circumcision, achieving a median treatment duration of 60 days. Circumsion was successfully avoided in 52.1% of patients who completed the protocol and 43.5% across the entire enrolled cohort, surpassing the primary endpoint threshold of 33%.\n\nPatients experienced a statistically significant reduction in phimosis severity as well as an improvement in erectile function according to IIEF-5 scores. Long-term telephone follow-up at a median of 24 months revealed that 81% of patients who initially succeeded sustained their results and avoided surgery. The authors conclude that PhimoStop\u2122 is a safe, durable, and effective alternative to circumcision for select adult phimosis cases, though randomized trials are recommended.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Marco Carilli", "Anastasios D. Asimakopoulos", "Serena Pastore", "Stefano Germani", "Luca Orecchia", "Enrico Finazzi Agr\u00f2", "Roberto Miano"], "organizations": ["Fondazione PTV Policlinico Tor Vergata", "University of Rome Tor Vergata", "Phimomed S.r.l.", "Italian Ministry of Health"], "themes": ["Urology", "Adult Phimosis", "Circumcision", "Non-surgical Treatment", "Preputial Dilation", "Erectile Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('18ec0a538b4d645a55b51dc9fca4e8619253364401319f66c2cc92ff605de0eb', 'Claeys Self‐assessment genital anatomy Androl 2022 .pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/18ec0a538b4d645a55b51dc9fca4e8619253364401319f66c2cc92ff605de0eb.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This study validates the Dutch translation of the Self-Assessment of Genital Anatomy and Sexual Function in Male (SAGASF-M) questionnaire among 808 sexually active, cisgender Belgian men without a history of reconstructive genital surgery. The tool evaluates patient perceptions of genital anatomy, sexual pleasure, orgasm intensity and effort, and discomfort across 11 specific anatomical areas, with clinical evaluations conducted on a subset to confirm the validity of self-reported scores.\n\nThe results demonstrated significant discrimination between anatomical zones, identifying the frenular area and glans as the greatest contributors to sexual pleasure and orgasmic intensity, whereas the anal region was rated lowest. While circumcised and uncircumcised men showed no significant difference in overall genital sensitivity, partner stimulation consistently yielded higher pleasure and intensity than self-stimulation. The authors conclude that the translated SAGASF-M is a reliable instrument for mapping site-specific sensation and evaluating outcomes in reconstructive urological surgery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wietse Claeys", "Guy Bronselaer", "Nicolaas Lumen", "Piet Hoebeke", "Anne-Fran\u00e7oise Spinoit"], "organizations": ["University Hospital Ghent", "Ghent University", "American Society of Andrology", "European Academy of Andrology"], "themes": ["Reconstructive Urology", "Genital Sensation and Anatomy", "Sexual Function and Orgasm", "Questionnaire Validation", "Circumcision Outcomes", "Patient-Reported Outcome Measures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('963b1a8c9fd4b446d374b8670623b5d80598b7de246980b20652a57017f6d927', 'CMAJ-Collier Circumcision indecision  2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/963b1a8c9fd4b446d374b8670623b5d80598b7de246980b20652a57017f6d927.pdf', 'medical_journal', 'ingested', '{"date": "2011-11-22", "description": "This article examines the enduring medical, cultural, and ethical controversies surrounding male circumcision, which remains the most commonly performed surgical procedure in human history despite a lack of global consensus on its benefits. While circumcision has historically been driven by religious traditions and 19th-century medical rationalizations, nonreligious circumcision has steadily declined across most Western nations, including the United States. Concurrently, recent African clinical trials demonstrating up to a 60% reduction in heterosexual HIV transmission have sparked renewed global health debates.\n\nServing as the introduction to a multipart investigative series by the Canadian Medical Association Journal (CMAJ), the piece outlines the polarized perspectives between advocates who view the procedure as an effective preventive measure against disease and opponents who emphasize bodily integrity, ethics, and sexual function. The upcoming series is set to explore anatomical significance, foreskin restoration, adult circumcision trends, the anti-circumcision movement, and the validity of international circumcision research.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Roger Collier", "David Gollaher", "Robert Darby", "Lewis Sayre", "David Cooper", "Ronald Makwankwa"], "organizations": ["Canadian Medical Association", "World Health Organization", "Centers for Disease Control and Prevention", "American Medical Association"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Medical Ethics and Human Rights", "History of Medicine", "Pediatric Surgery", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e1fb338985e777cb6931195dff85b23ec9ef2cc322461b4bc7805387f3896c9d', 'CMAJ-Collier Foreskin Vital or vestigal 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e1fb338985e777cb6931195dff85b23ec9ef2cc322461b4bc7805387f3896c9d.pdf', 'medical_journal', 'ingested', '{"date": "2011-11-22", "description": "This document features two news reports published by the Canadian Medical Association Journal (CMAJ). The first article examines the medical and cultural debate surrounding male circumcision and the function of the foreskin, contrasting arguments regarding sexual sensitivity and anatomical protection against evidence showing circumcision reduces HIV transmission and urinary tract infections. The second article covers proposed United States regulations by the Department of Health and Human Services to grant patients direct access to clinical lab results, discussing the balance between patient empowerment through electronic health records and physician concerns over patient anxiety, misinterpretation, and the absence of clinical guidance.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["George Denniston", "Douglas Gairdner", "Minh Dinh", "Roger Collier", "Kathleen Sebelius", "Mary M. Newman", "Deborah Peel", "Neil Desai", "Nancy Benac"], "organizations": ["Canadian Medical Association", "Doctors Opposing Circumcision", "Northwestern University", "US Department of Health and Human Services", "American Medical Association", "Patient Privacy Rights Foundation", "Quest Diagnostics"], "themes": ["Male Circumcision Debate", "HIV Prevention and Transmission", "Patient Access to Medical Records", "Health Policy and Regulation", "Doctor-Patient Communication"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('537fe8fda34e7fa2dab5294dd2315104cdaa80d36c61833ab8b417c992aa9189', 'CMAJ-Collier Late cuts 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/537fe8fda34e7fa2dab5294dd2315104cdaa80d36c61833ab8b417c992aa9189.pdf', 'medical_journal', 'ingested', '{"date": "2012-01-10", "description": "This article examines global trends, medical debates, and varying motivations behind adult male circumcision. In African nations with high HIV rates, clinical trials demonstrating reduced heterosexual virus transmission have driven large-scale public health campaigns endorsed by the World Health Organization. In other regions, adult circumcision is sought for diverse reasons, including cosmetic preferences, resolving medical conditions like phimosis, religious conversion, and cultural norms, such as those established in South Korea following the Korean War.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian Morris", "David Cornell", "John Aquino", "Robert Francoeur", "Roger Collier"], "organizations": ["Canadian Medical Association", "University of Sydney", "World Health Organization", "UNAIDS", "The Circumcision Center", "Ontario Men''s Health"], "themes": ["Adult Circumcision", "HIV/AIDS Prevention", "Public Health Initiatives", "Sexual Health and Function", "Cultural and Cosmetic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a9566760bc39caf475cfc1c64a8d720800a2d99fd899f425818343b6bad8a7f2', 'CMAJ-Collier Studies launched 1000 snips 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a9566760bc39caf475cfc1c64a8d720800a2d99fd899f425818343b6bad8a7f2.pdf', 'medical_journal', 'ingested', '{"date": "2012-01-10", "description": "This article examines the controversy surrounding landmark clinical trials conducted in South Africa, Uganda, and Kenya that found male circumcision could reduce female-to-male HIV transmission by 50% to 60%. These findings prompted substantial international funding and mass circumcision initiatives in Africa, backed by figures like Bill Clinton and the Bill & Melinda Gates Foundation, as well as pro-circumcision researchers who argue the health benefits far outweigh the risks.\n\nConversely, critics and groups such as Doctors Opposing Circumcision contend that these trials were fundamentally flawed and influenced by various methodological biases, including attrition bias, lead-time bias, and unverified infection pathways. Opponents also argue that mass campaigns fail to account for local social dynamics, potentially increasing risky sexual behaviors and reflecting a misguided colonial approach to public health.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["George Denniston", "Bill Clinton", "Bill Gates", "Minh Dinh", "Brian Morris", "John Travis", "John Geisheker", "Roger Collier"], "organizations": ["Canadian Medical Association", "Doctors Opposing Circumcision", "Bill & Melinda Gates Foundation", "Northwestern University", "University of Sydney", "Alliance for Transforming the Lives of Children"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Clinical Trial Methodology and Bias", "Global Health Interventions", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4259b0ee9adab73d385dfd8f57a74630472306fd327e49935fc7e2aab29e836c', 'CMAJ-Collier Ugly, messy, nasty circ debate 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4259b0ee9adab73d385dfd8f57a74630472306fd327e49935fc7e2aab29e836c.pdf', 'medical_journal', 'ingested', '{"date": "2012-01-10", "description": "This article examines the contentious and polarizing public debate surrounding male infant circumcision, centered primarily in the United States. Proponents argue that the procedure provides substantial public health benefits, supported by modern clinical research showing reductions in HIV transmission and penile cancer. In contrast, opponents\u2014often identifying as ''intactivists''\u2014condemn the practice as an unnecessary violation of bodily integrity, human rights, and the medical oath to ''do no harm.''\n\nThe text details how anti-circumcision organizations are actively lobbying for legal bans, questioning the scientific validity of pro-circumcision research, and advocating for foreskin restoration. The debate is further complicated by historical context, deeply rooted cultural norms, and religious traditions in Judaism and Islam, creating an aggressive discourse where scientific evidence frequently clashes with moral, bodily consent, and human rights arguments.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Roger Collier", "George Denniston", "Brian Morris", "Wayne Griffiths", "Jack Lapides", "Geoff Hinchley", "Russell Crowe"], "organizations": ["Canadian Medical Association", "Doctors Opposing Circumcision", "University of Sydney", "National Organization to Halt the Abuse and Routine Mutilation of Males", "National Organization of Circumcision Information Resources Centers", "Intact America", "Stop Infant Circumcision Society", "National Organization of Restoring Men"], "themes": ["Male circumcision debate", "Intactivism and bodily integrity", "Medical ethics and consent", "HIV prevention and public health", "Religious freedom versus legal bans"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cd095bc8ced70fd946cce782eda8d607236cec5d3ef447c82a57b0cc60dc52bd', 'CMAJ-Collier Whole Again FSRest 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cd095bc8ced70fd946cce782eda8d607236cec5d3ef447c82a57b0cc60dc52bd.pdf', 'medical_journal', 'ingested', '{"date": "2011-12-13", "description": "This article explores the practice and history of foreskin restoration (uncircumcision) among circumcised men, focusing on physical techniques, psychological motivations, and medical perspectives. It highlights the efforts of Wayne Griffiths, founder of the National Organization of Restoring Men (NORM), who popularized nonsurgical skin-stretching devices like ''Foreballs'' to improve sexual sensitivity and resolve emotional distress stemming from infant circumcision.\n\nThe piece also examines the medical community''s hesitant relationship with foreskin restoration. While historical motives for uncircumcision were often driven by the evasion of religious persecution, contemporary approaches mainly rely on slow tissue expansion rather than surgery. Modern surgeons rarely perform reconstructive surgery due to poor cosmetic results and complexity, making gradual, weight-assisted skin expansion the predominant method advocated by restoration groups.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wayne Griffiths", "Dirk Schultheiss", "Aulus Cornelius Celsus", "Johann Friedrich Dieffenbach", "Stephen Giunta", "Robert Stubbs", "Roger Collier"], "organizations": ["National Organization of Restoring Men", "Canadian Medical Association"], "themes": ["Foreskin Restoration", "Circumcision and Uncircumcision", "Men''s Health and Sexual Well-being", "Genital Cosmetic and Reconstructive Surgery", "Tissue Expansion and Stretching Techniques"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('52c742cc881547359bd317b4d4ff0d5d5c0c86ac5ce8f08f220e7fe36dc4a3ab', 'Coates Can Babies Remember Trauma (paper) 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/52c742cc881547359bd317b4d4ff0d5d5c0c86ac5ce8f08f220e7fe36dc4a3ab.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article examines whether infants and preverbal toddlers can experience, symbolically encode, and remember traumatic events. Challenging historical medical assumptions that neonates do not feel pain or retain memories of suffering, the author synthesizes findings from developmental cognitive science, pediatrics, and clinical psychoanalysis to demonstrate that primitive episodic and somatic memory systems operate from early infancy.\n\nThrough detailed clinical cases\u2014notably that of an infant named Betsy who survived a stabbing assault at ten months old\u2014the paper illustrates how preverbal trauma is stored somatically and reexperienced through play, behavioral reenactments, and sensory triggers. The study highlights the vital role of the caregiver attachment system and parental verbal scaffolding, demonstrating that a secure attachment relationship can contain severe trauma, facilitate narrative integration, and promote long-term psychological resilience.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Susan W. Coates", "Sigmund Freud", "S\u00e1ndor Ferenczi", "David Levy", "Theodore Gaensbauer", "Andrew N. Meltzoff", "K. J. Anand"], "organizations": ["Columbia University", "College of Physicians and Surgeons", "Columbia University Center for Psychoanalytic Training and Research", "Hospital for Sick Children at the University of Toronto"], "themes": ["Infant Trauma", "Somatic Memory", "Attachment Theory", "Preverbal Symbolic Representation", "Pediatric Post-Traumatic Stress Disorder (PTSD)", "Autobiographical Memory Development"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f1aef427a778e4d8ac0e7f7a5f36ee7c66989e354393843d22a63655a39243c6', 'Coene Gender Culture Circ ClinEthics 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f1aef427a778e4d8ac0e7f7a5f36ee7c66989e354393843d22a63655a39243c6.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This article critically analyzes the divergent attitudes of European medical professionals toward two medically nonindicated procedures: hymen (re)construction and nontherapeutic male circumcision. Utilizing a standard biomedical ethics framework based on autonomy, beneficence, nonmaleficence, and justice, the authors argue that infant male circumcision presents greater ethical challenges because it involves irreversible bodily alteration without the patient''s consent. Conversely, hymenoplasty\u2014typically requested by competent adult women and carrying minimal physical risk\u2014faces intense professional resistance and moral scrutiny.\n\nThe authors contend that these contrasting medical responses are heavily driven by gendered and sociocultural biases rather than consistent ethical reasoning. While male circumcision is largely normalized in Western discourse and viewed as a gender-neutral or minor health practice, hymen reconstruction is frequently framed as patriarchal subjugation among minority or immigrant communities. This leads to medical paternalism and onerous counseling requirements that undermine female autonomy, illustrating how cultural assumptions shape clinical decision-making.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gily Coene", "Sawitri Saharso"], "organizations": ["Vrije Universiteit Brussel", "Universiteit voor Humanistiek", "Dutch Society of Obstetrics and Gynecology", "American Academy of Pediatrics", "World Health Organization", "Council of Europe"], "themes": ["Bioethics and Medical Ethics", "Nontherapeutic Male Circumcision", "Hymen (Re)construction", "Patient Autonomy and Informed Consent", "Gender and Cultural Norms", "Medical Paternalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1499df157e0c239e662c3e3e865ded056402d716a6d5477636f80dbfe0012fc', 'Cohen Circ and Medicalization of Sex Genspect 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1499df157e0c239e662c3e3e865ded056402d716a6d5477636f80dbfe0012fc.pdf', 'other', 'ingested', '{"date": "2024-04-16", "description": "The provided text consists of page headers and URLs from an online article titled ''Circumcision and the Medicalization of Sex,'' published or hosted by the organization Genspect. The main body text of the article is absent from the excerpt, leaving only pagination markers and timestamps from April 16, 2024.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Genspect"], "themes": ["Circumcision", "Medicalization of Sex", "Healthcare Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('90769f14b4465a384135aefabaaf00a217dd17e9a591fb09f33d48d891e327ac', 'Cohen Preventing FGM U.S AJPH 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/90769f14b4465a384135aefabaaf00a217dd17e9a591fb09f33d48d891e327ac.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article examines the legal fallout following the 2018 federal court decision in United States v. Nagarwala, which struck down the 1996 US federal ban on female genital mutilation (FGM) on constitutional and federalism grounds. Presided over by Judge Bernard A. Friedman, the district court ruled that Congress exceeded its enumerated powers under both the Treaty Power and the Commerce Clause, declaring FGM to be a matter of local criminal activity for state regulation.\n\nThe authors criticize the court''s legal reasoning, contending that the court misconstrued the International Covenant on Civil and Political Rights (ICCPR) and improperly characterized FGM as purely noncommercial assault rather than a paid-for service in the healthcare market. To rectify this legal barrier and uphold protections against FGM, the authors argue that Congress should enact revised legislation with explicit connections to interstate commerce or that states must continue to enact and strengthen their own comprehensive bans.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jumana Nagarwala", "Bernard A. Friedman", "I. Glenn Cohen", "Nikolas Bowie", "Megan Jones", "Eli Y. Adashi"], "organizations": ["American Journal of Public Health", "World Health Organization", "United Nations Children''s Fund", "US District Court for the Eastern District of Michigan", "US Department of Justice", "US Sixth Circuit Court of Appeals", "US House of Representatives", "Harvard Law School", "Brown University"], "themes": ["Female Genital Mutilation", "Constitutional Law", "Commerce Clause", "Federalism", "Human Rights", "Public Health Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7b4a84ae4d8e1f404e348bec17297160447e751f3ccc94c7f13c8f58f790b9e6', 'Cold Taylor Prepuce BJU 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7b4a84ae4d8e1f404e348bec17297160447e751f3ccc94c7f13c8f58f790b9e6.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This academic paper reviews the evolutionary history, embryology, normal anatomy, and physiological functions of the prepuce in both male and female external genitalia. The authors argue that the prepuce is a normal, ancient, and specialized mucocutaneous tissue that provides protective coverage and erogenous function, challenging cultural and medical justifications that view it as unhealthy or redundant and lead to routine circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["C.J. Cold", "J.R. Taylor", "R. Brinsko", "G. Craigmyles"], "organizations": ["British Journal of Urology", "Marshfield Clinic", "University of Manitoba", "BJU International"], "themes": ["Prepuce Anatomy", "Embryology", "Circumcision", "Genital Physiology", "Evolutionary Biology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('678d154aafc8c3bb7be1a442ee009b69444141e505bf59c59b20b1205c907869', 'Cook Ethical Concerns FGC 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/678d154aafc8c3bb7be1a442ee009b69444141e505bf59c59b20b1205c907869.pdf', 'medical_journal', 'ingested', '{"date": "2008-04", "description": "This commentary examines the bioethical, cultural, and medical dimensions of female genital cutting (FGC). The author argues that using the term ''female genital cutting'' rather than ''female genital mutilation'' is more ethically appropriate as it avoids stigmatizing parents who subject their daughters to the practice out of social necessity, such as ensuring marriageability and purity. The article outlines the four WHO-defined types of FGC and reviews the severe health consequences, including infection, hemorrhage, obstetric fistula, and maternal and neonatal mortality.\n\nAdditionally, the paper explores the socio-cultural motivations behind FGC, framing it within a broader historical context of patriarchal control over female sexuality. It addresses the ethical dilemma confronting healthcare professionals regarding the ''medicalization'' of FGC, ultimately concluding that physicians must strictly adhere to the principle of non-maleficence by refusing to perform these procedures while playing an active role in educating communities and advocating for the elimination of harmful traditional practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Rebecca J. Cook"], "organizations": ["World Health Organization", "International Federation of Gynecology and Obstetrics", "United Nations"], "themes": ["Female Genital Cutting (FGC)", "Bioethics and Non-maleficence", "Medicalization of FGC", "Reproductive Health Complications", "Children''s Rights and Bodily Integrity", "Social and Cultural Control of Female Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5efaa4bf207119808d9342b17bfba8d1bfc7d9c2586a446383562739f6d9d2b4', 'Council of Europe CircRes#1952 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5efaa4bf207119808d9342b17bfba8d1bfc7d9c2586a446383562739f6d9d2b4.pdf', 'policy_guideline', 'ingested', '{"date": "2013-10-01", "description": "Resolution 1952 (2013) of the Parliamentary Assembly of the Council of Europe addresses non-medically justified violations of children''s physical integrity that are frequently defended as beneficial despite contrary evidence. The resolution focuses on practices such as female genital mutilation, religious circumcision of young boys, early cosmetic or non-vital medical interventions on intersex children, and coercive body modifications like tattoos and piercings.\n\nInvoking the UN Convention on the Rights of the Child and the Council of Europe''s child protection initiatives, the Assembly calls on member states to define specific policy measures, raise public awareness, and introduce professional training. Member states are urged to legally ban female genital mutilation, regulate sanitary and medical standards for non-medical circumcisions, guarantee bodily autonomy and postpone non-vital surgeries for intersex children until they can be consulted, and ensure the best interests of the child guide all related medical and legal decisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Ms Rupprecht"], "organizations": ["Parliamentary Assembly of the Council of Europe", "Council of Europe", "United Nations", "Committee on Social Affairs, Health and Sustainable Development"], "themes": ["Children''s Rights", "Physical Integrity", "Female Genital Mutilation", "Religious Circumcision", "Intersex Bodily Autonomy", "Child Protection and Welfare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6dc83afe8406a18d6d2306163b969c738c6d44a674111b4c7b99720d10c28b86', 'Cox Foreskin Functions MedHypoth 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6dc83afe8406a18d6d2306163b969c738c6d44a674111b4c7b99720d10c28b86.pdf', 'medical_journal', 'ingested', '{"date": "1995-12", "description": "This academic paper proposes an evolutionary hypothesis regarding the function of the human male foreskin, specifically addressing why conditions like phimosis and preputial adhesions are prevalent despite their apparent disadvantages. The author postulates that these physical traits confer an evolutionary and reproductive advantage by delaying the age of first coitus and childbirth until young parents are better established to provide for offspring, drawing an analogy to female virginity markers and contextualizing the cultural practice of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Guy Cox", "Wiswell"], "organizations": ["University of Sydney", "Electron Microscope Unit", "Pearson Professional Ltd"], "themes": ["Human Evolution", "Reproductive Biology", "Circumcision", "Phimosis", "Evolutionary Advantage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c52482be213af9b1b655c0f33f8a2bbbae5729428dd6723103810f47bdca81cb', 'CPT Code 54163 Excision Procedures on the Penis.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c52482be213af9b1b655c0f33f8a2bbbae5729428dd6723103810f47bdca81cb.pdf', 'other', 'ingested', '{"date": "2024-12-17", "description": "This document serves as a web reference listing for Current Procedural Terminology (CPT) Code 54163, published via AAPC''s Codify platform. The code corresponds to surgical excision procedures performed on the penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["AAPC"], "themes": ["Medical Coding", "CPT Codes", "Surgical Excision", "Urology Procedures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('47cec36f31f1b4d2d1d3c9d7ab8e6e405edebddd430fcba3ce621ca09583e105', 'Craig Medicaid NCarol Kluwer 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/47cec36f31f1b4d2d1d3c9d7ab8e6e405edebddd430fcba3ce621ca09583e105.pdf', 'other', 'ingested', '{"date": "2004", "description": "This document examines the political and fiscal battle over North Carolina Medicaid''s coverage of routine, elective infant male circumcisions between 2001 and 2003. Although North Carolina Medicaid initially eliminated funding for non-therapeutic circumcisions in November 2001 citing medical consensus from organizations like the AAP, intense lobbying by state physicians and intervention by Governor Michael Easley led to a temporary legislative reinstatement of funding during late-night budget maneuvers. The author highlights the substantial financial burden and medical conflicts of interest associated with the procedure, contrasting the state''s funding of elective surgeries with concurrent cuts to basic healthcare services like pediatric dental care and in-home elderly assistance.\n\nFollowing continued grassroots activism, media engagement, and severe state budget deficits, the North Carolina legislature ultimately defunded routine circumcision permanently in late 2002. The chapter places North Carolina''s experience within a broader national trend, noting that numerous other states likewise eliminated Medicaid reimbursements for non-therapeutic circumcisions in the early 2000s.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Amber Craig", "Valerie Parisi", "William Hubbard", "Kenneth Baker", "Christopher J. Mansfield", "Ruth Sheehan", "David Redwine", "Michael Easley", "Franklin Freeman", "Marc Basnight", "Donna Larkin"], "organizations": ["National Organization of Circumcision Information Resource Centers of North Carolina", "North Carolina Medicaid", "American Academy of Pediatrics", "American Medical Association", "American College of Obstetrics and Gynecology", "North Carolina General Assembly", "North Carolina Pediatric Society", "University of North Carolina Hospital", "East Carolina University School of Medicine"], "themes": ["Medicaid Funding", "Routine Infant Circumcision", "Healthcare Economics and Budget Cuts", "Medical Necessity vs. Elective Procedures", "Legislative Lobbying and Grassroots Activism", "Media Coverage and Public Opinion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('020375a2cabe65005ba4e9a39dcc92084516a3ed4d2acbea79f46dc327282188', 'CRIN Childrens Health (Stmt, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/020375a2cabe65005ba4e9a39dcc92084516a3ed4d2acbea79f46dc327282188.pdf', 'policy_guideline', 'ingested', '{"date": "2012", "description": "This submission by the Child Rights International Network (CRIN) to the OHCHR Study on Children''s Right to Health outlines how children''s health rights under Article 24 of the Convention on the Rights of the Child (CRC) are inextricably linked with broader civil and political rights. It argues that health policies must uphold the best interests of the child, non-discrimination, the right to privacy and confidentiality, and the right to be heard based on evolving maturity rather than rigid age limits. CRIN emphasizes the necessity of informed consent, warning against untested drug testing and the routine over-prescription of psychiatric medications like Ritalin.\n\nThe submission also addresses several critical systemic challenges, including discriminatory laws restricting LGBT health education, the persistence of harmful traditional practices such as forced male circumcision and faith-healing medical neglect, and the exclusion of adolescents from harm reduction and drug dependence treatments. Additionally, it calls for alternatives to incarceration for youth with substance use issues and insists on comprehensive, community-equivalent health and psychological services for children deprived of their liberty.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Fred Baughman", "Adam Fletcher"], "organizations": ["Child Rights International Network", "Office of the United Nations High Commissioner for Human Rights", "UN Committee on the Rights of the Child", "World Health Organization", "UNODC", "UNAIDS", "UNICEF", "Pfizer", "Canadian Medical Association", "Eurasian Harm Reduction Network"], "themes": ["Children''s Rights", "Right to Health", "Medical Confidentiality and Informed Consent", "Harm Reduction and Substance Abuse", "Harmful Traditional Practices", "LGBT Rights and Sexual Health Education", "Juvenile Justice and Detention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d64cdcd8ccd40b0d76daff6ca74de92a3ba5e71897b6f5a673497a61b55d79b9', 'CRIN Childrens Religious Freedom (Stmt) 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d64cdcd8ccd40b0d76daff6ca74de92a3ba5e71897b6f5a673497a61b55d79b9.pdf', 'policy_guideline', 'ingested', '{"date": "2015-11", "description": "This policy position document by the Child Rights International Network (CRIN) responds to an October 2015 report presented to the UN General Assembly by the UN Special Rapporteur on freedom of religion or belief. While welcoming the Rapporteur''s recognition that children hold an independent right to freedom of religion and belief, CRIN argues that the report overly ties children''s rights to parental authority rather than treating children as independent rights-holders under the UN Convention on the Rights of the Child (CRC).\n\nCRIN urges greater protections for children''s religious self-determination, including mandatory pluralistic education about diverse faiths and non-theistic beliefs to counteract prejudice and radicalization. It calls for the explicit protection of children with atheistic convictions and those who commit apostasy, while strongly criticizing the Rapporteur for condoning non-consensual, non-therapeutic male circumcision and other irreversible physical practices in the name of parental religious freedom.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["Child Rights International Network (CRIN)", "United Nations General Assembly", "Office of the United Nations High Commissioner for Human Rights (OHCHR)", "UN Committee on the Rights of the Child", "Pew Research Center"], "themes": ["Children''s Rights", "Freedom of Religion or Belief", "Religious Education and Pluralism", "Apostasy and Blasphemy", "Bodily Integrity and Male Circumcision", "Parental Rights vs. Child Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('44628b5af50d1f5b73e7a8de19429f6136ecc07092bb48d3148c5d94bc961077', 'Crosby Condom Use Perceptions IntJ-STD-AIDS 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/44628b5af50d1f5b73e7a8de19429f6136ecc07092bb48d3148c5d94bc961077.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This study compares condom use perceptions, confidence, and behaviors between 316 circumcised and intact men attending sexually transmitted infection (STI) clinics in Kentucky and Ohio. Contrary to expectations that uncircumcised men might encounter greater mechanical or sensation-related difficulties with condoms, findings indicated that intact men were significantly less likely to report unprotected vaginal sex and infrequent condom use, and they reported greater confidence in their ability to use condoms compared to circumcised men.\n\nMultivariate logistic regression demonstrated that men lacking complete confidence had more than double the odds of engaging in unprotected vaginal sex and infrequent condom use. Furthermore, circumcision status significantly increased the likelihood of infrequent condom use primarily among younger men under age 25. The authors conclude that public health interventions and STI clinic counseling should prioritize strengthening men''s self-efficacy and confidence in condom use, while particularly focusing prevention messaging on young circumcised men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R Crosby", "R J Charnigo"], "organizations": ["University of Kentucky", "Indiana University", "The Kinsey Institute for Research in Sex, Gender and Reproduction", "National Institutes of Health", "National Institute of Allergy and Infectious Diseases"], "themes": ["Condom Use", "Male Circumcision", "Sexually Transmitted Infections (STIs)", "HIV Prevention", "Self-Efficacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6994cbef436b88dac7c330a16b67283e95d9b4a5082a0c98bab0eb9cc988f204', 'Crosby Condoms & Circumcision AIDS Behav 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6994cbef436b88dac7c330a16b67283e95d9b4a5082a0c98bab0eb9cc988f204.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study examines whether circumcision status influences condom use behaviors, sexual pleasure perceptions, and STI/HIV prevalence among young Black men who have sex with men (YBMSM). Analyzing baseline data from a sample of YBMSM recruited at a clinic in the southern United States, researchers evaluated self-reported circumcision status against condom-related issues and laboratory diagnoses of HIV, urethral Chlamydia, and urethral gonorrhea.\n\nThe findings revealed no statistically significant associations between circumcision status and condom-use errors, problems, or perceptions of pleasure, nor were there significant differences in STI or HIV prevalence between intact and circumcised men. Consequently, the authors conclude that circumcision does not appear to confer protective benefits against HIV or STIs in this demographic, suggesting adult circumcision is not an effective preventive intervention for young Black MSM.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Richard A. Crosby", "Cynthia A. Graham", "Leandro Mena", "William L. Yarber", "Stephanie A. Sanders", "Robin R. Milhausen", "Angelica Geter"], "organizations": ["University of Kentucky", "The Kinsey Institute for Research in Sex, Gender, and Reproduction", "University of Southampton", "University of Mississippi Medical Center", "Indiana University", "University of Guelph", "National Institute of Mental Health", "Springer Science+Business Media"], "themes": ["Circumcision", "Condom Use and Compliance", "HIV/AIDS Prevention", "Sexually Transmitted Infections", "Young Black MSM Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('459ae3c4688bd075012a949d09136a17008ac327d3bd245ccca4cf0ac782a31c', 'Cunha Develop of Prepuce & Innerv Differentiation 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/459ae3c4688bd075012a949d09136a17008ac327d3bd245ccca4cf0ac782a31c.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This study examines the morphogenesis and innervation of the human prepuce across 9 to 17 weeks of gestation using scanning electron microscopy, histology, and immunohistochemistry. The authors identify a novel morphogenetic mechanism in which the thickened epidermis of the glans splits into the preputial lamina and outer epidermis via the intrusion of a vascularized, blood-vessel-rich mesenchyme. This process begins at 10 to 11 weeks proximally/dorsally and extends distally, driven largely by androgen signaling in the surrounding mesenchyme, with potential regulatory contributions from estrogen receptors (ESR1 and ESR2).\n\nAdditionally, the study traces the ontogeny of penile innervation via S100 immunostaining, showing that the dorsal nerve of the penis is recognizable as early as 9 weeks of gestation. Nerve fibers progressively advance in a proximal-to-distal direction to reach the distal glans, prepuce, and frenulum by 14 to 16 weeks. The findings provide critical insights into human genital embryology and the developmental etiology of congenital penile anomalies such as hypospadias and epispadias.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gerald R. Cunha", "Adrian Sinclair", "Mei Cao", "Laurence S. Baskin"], "organizations": ["University of California, San Francisco", "National Institutes of Health"], "themes": ["Preputial Morphogenesis", "Penile and Preputial Innervation", "Androgen and Estrogen Receptor Signaling", "Congenital Genitourinary Anomalies and Hypospadias", "Human Fetal Development"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a249338eb6b0855adaaf02ccecb6bd98e507c961fe0dc2863c316da36ab41ff6', 'Darby Cox Objections sentimental_character Foreskin loss 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a249338eb6b0855adaaf02ccecb6bd98e507c961fe0dc2863c316da36ab41ff6.pdf', 'other', 'ingested', '{"date": "2008", "description": "This academic essay examines the subjective, physical, and psychological repercussions of non-therapeutic male circumcision performed in infancy and childhood. Challenging historical assertions by figures like William Acton and contemporary claims by advocates like Brian Morris that circumcision has negligible impact and provokes few complaints, the authors demonstrate that a significant number of men experience lasting dissatisfaction, reduced sexual sensation, physical discomfort, and psychological distress from bodily alteration without consent.\n\nDrawing on survey data from the United Kingdom, the United States, and Laurence Cox''s Australian study on men seeking foreskin restoration, the authors document severe emotional grievances, including feelings of bodily violation, mutilated self-image, and resentment toward parents and medical practitioners. They argue that routine circumcision lacks clear medical necessity, violates children''s bodily autonomy and human rights, and should not be performed on minors who cannot provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Darby", "Laurence Cox", "Chantal Zabus", "William Acton", "Brian J. Morris", "Jonathan Hutchinson", "George Williams"], "organizations": ["Australasian Association of Paediatric Surgeons", "Royal Australasian College of Physicians", "NOCIRC Australia", "NOHARMM", "Editions Rodopi"], "themes": ["Male Circumcision", "Bodily Autonomy and Consent", "Medical Ethics", "Psychosexual Sequelae", "Foreskin Restoration", "Children''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3136f457ad5f3fd93e78e780eb0dcb2d46c7767811093a23c8f6b7f5d60dbd3a', 'Darby genital-cutting-male Intl Encycl Hum Sex 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3136f457ad5f3fd93e78e780eb0dcb2d46c7767811093a23c8f6b7f5d60dbd3a.pdf', 'other', 'ingested', '{"date": "2015", "description": "This encyclopedia entry by Robert Darby examines the history, cultural functions, and global prevalence of male genital cutting, particularly circumcision and related practices such as subincision and infibulation. It explores how traditional tribal societies utilized circumcision as a rite of passage, a tool for gender differentiation, and a means of social control, while contrasting this with the institutionalized infant circumcision in Judaism and customary practices in Islam. The text highlights how rationales for the procedure have evolved across eras\u2014from fertility and patriarchal identity to Victorian moral policing of sexuality and contemporary medical justifications such as HIV prevention.\n\nDarby also addresses the broader debates surrounding circumcision, including its documented risks, physical pain, and impact on sexual function, emphasizing that historical arguments framing it as an ancient hygienic measure are largely speculative. The entry concludes that despite shifting rationales and the growing medicalization of the procedure in clinical settings, circumcision remains deeply entrenched and historically difficult to eradicate once integrated into a culture''s identity and social norms.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Darby", "Patricia Whelehan", "Anne Bolin", "Wilfred Thesiger", "Leonard Glick"], "organizations": ["John Wiley & Sons, Inc.", "Wellcome Library"], "themes": ["Male Circumcision", "Body Modification", "Rites of Passage", "Religious Rituals", "Medicalization", "Cultural Anthropology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('332a598a4565a57505c3d658aaa9e3c341377600ee021e620080351668a72f6a', 'Darby Masturbation_Taboo JSocHist 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/332a598a4565a57505c3d658aaa9e3c341377600ee021e620080351668a72f6a.pdf', 'other', 'ingested', '{"date": "2003", "description": "This historiographical review by Robert Darby examines the medical and cultural origins of routine infant male circumcision in the English-speaking world during the nineteenth and twentieth centuries. Darby refutes modern assertions that the procedure was introduced purely for organic hygiene or disease prevention, demonstrating that medical historians have consistently traced routine circumcision back to the widespread Victorian obsession with curbing masturbation. Influenced by moral theology dressed in medical rhetoric, nineteenth-century physicians pathologized masturbation as a primary cause of physical, mental, and nervous disorders, using surgical removal of the foreskin to dampen sexual sensitivity and enforce sexual quiescence.\n\nDarby synthesizes decades of scholarship\u2014including works by Ren\u00e9 Spitz, Thomas Szasz, Ronald Hamowy, and David Gollaher\u2014to show how the transition from home births to hospital-managed deliveries institutionalized neonatal circumcision. The paper also highlights an enduring cultural double standard in Western medicine: while female clitoridectomy was rapidly denounced and abandoned as genital mutilation in the late nineteenth century, involuntary male circumcision was rationalized as preventive medicine, persisting through shifting medical justifications well into the twentieth century.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Darby", "David Gollaher", "Brian Morris", "Jonathan Hutchinson", "Lewis Sayre", "Thomas Szasz", "Ren\u00e9 Spitz", "William Acton", "Frederick Hodges"], "organizations": ["Royal College of Surgeons", "Obstetrical Society", "Nocirc"], "themes": ["Historiography of male circumcision", "Masturbation taboo and moral panic", "Victorian medical ethics and sexual morality", "Medicalization of religious sin", "Genital modification and cultural double standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('103b78adc7fea54ec130d2049417d9581bee5403da9dcff92978e8e1c5c438b5', 'Darby Medicare 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/103b78adc7fea54ec130d2049417d9581bee5403da9dcff92978e8e1c5c438b5.pdf', 'policy_guideline', 'ingested', '{"date": "2015", "description": "This document is a submission by Dr. Robert Darby to the Australian Medical Benefits Schedule (MBS) Review, arguing that Medicare should terminate rebates for non-therapeutic male circumcision. Darby asserts that routine infant and child circumcision is not clinically necessary, serves no compelling prophylactic purpose in developed nations, and violates Medicare''s own statutory regulations against funding elective cosmetic surgeries. He highlights that major Australian and international medical associations do not recommend routine circumcision, and emphasizes that performing irreversible, non-therapeutic surgery on minors infringes on fundamental bioethical principles, including physical integrity and autonomy.\n\nDarby also frames the continued subsidization of circumcision as an issue of economic waste, legal liability, and gender discrimination under the Sex Discrimination Act, given that female circumcision is prohibited and completely excluded from Medicare. He proposes that Medicare add the requirement ''where medically indicated'' to all existing circumcision item codes, which would end taxpayer subsidies for discretionary operations and align Australia with international practices without prohibiting families from privately pursuing cultural or religious procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Robert Darby", "Tony Webber"], "organizations": ["Medicare", "Medical Benefits Schedule Review", "National Health and Medical Research Council", "Royal Australasian College of Physicians", "Royal Australasian College of Surgeons", "Tasmania Law Reform Institute", "Department of Health and Ageing"], "themes": ["Non-therapeutic Circumcision", "Medicare Reform and Public Expenditure", "Bioethics and Autonomy", "Children''s Rights", "Gender Equity in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8e41bd95bcd3e542019f2314ec1525ecf9937df5a2e470a45dc08c5714c7d7dc', 'Darby Moral Hypocrisy KIJE 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8e41bd95bcd3e542019f2314ec1525ecf9937df5a2e470a45dc08c5714c7d7dc.pdf', 'medical_journal', 'ingested', '{"date": "2016-06", "description": "In this article, Robert Darby examines the ethical double standard and historical context surrounding male genital cutting (MGC) and female genital cutting (FGC). Building on work by Brian D. Earp, Darby argues that major health organizations and legal frameworks commit intellectual inconsistency by universally condemning all forms of FGC while tolerating or endorsing nontherapeutic circumcision of male minors. Tracing this dichotomy back to 19th-century British medical debates over clitoridectomy, Darby asserts that principles of bodily integrity, autonomy, and human rights should be applied universally regardless of sex or gender.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Brian D. Earp", "Nahid Toubia", "Edgar Schoen", "Isaac Baker Brown", "Jonathan Hutchinson", "Paul Fleiss", "Stephen James"], "organizations": ["United Nations", "World Health Organization", "Johns Hopkins University Press", "Kennedy Institute of Ethics", "Obstetrical Society"], "themes": ["Male Genital Cutting (Circumcision)", "Female Genital Cutting (FGC/FGM)", "Bioethics and Human Rights", "Bodily Integrity and Consent", "Medical History and Gender Bias"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e50e67f2731bf70b4852322ed806d414cf468f4ed20c74cad28362a5ab462fa7', 'Darby Not Surg Vaccine ANZJPH 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e50e67f2731bf70b4852322ed806d414cf468f4ed20c74cad28362a5ab462fa7.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This academic article critically evaluates proposals to boost routine infant male circumcision in Australia as a public health measure against heterosexually transmitted HIV. The authors argue against adopting such policies, contending that the evidence from African randomized controlled trials is methodologically flawed, has poor external validity, and does not apply to Australia''s low-prevalence, concentrated HIV epidemiology where heterosexual transmission remains rare.\n\nFurthermore, the authors state that the proposal violates principles of evidence-based medicine by targeting non-consenting infants for potential adult risks, while severely understating surgical complications, pain, and long-term consequences. They assert that non-therapeutic neonatal circumcision infringes on biomedical ethics and human rights, concluding that characterizing the procedure as a ''surgical vaccine'' is unscientific rhetoric that should be rejected in public health policy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Robert Van Howe", "Brian Morris", "David A. Cooper", "Alex D. Wodak"], "organizations": ["Australian and New Zealand Journal of Public Health", "Public Health Association of Australia", "Royal Australasian College of Physicians", "World Health Organization", "Australian Paediatric Association", "Royal Dutch Medical Association"], "themes": ["Infant Male Circumcision", "HIV/AIDS Transmission and Prevention", "Evidence-Based Medicine", "Medical Ethics and Human Rights", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1957c1c29425584fb12019f00d1e8e23de56ed31d591f339cb038e8ef9cc5f9a', 'Darby Risks, Benefits, Harms KIEJ 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1957c1c29425584fb12019f00d1e8e23de56ed31d591f339cb038e8ef9cc5f9a.pdf', 'medical_journal', 'ingested', '{"date": "2015-03", "description": "This article critically examines the prevailing risk-versus-benefit paradigm used in debates surrounding non-therapeutic neonatal male circumcision, focusing specifically on the American Academy of Pediatrics'' (AAP) 2012 policy statement. The author argues that the AAP''s conclusion\u2014that the health benefits outweigh the risks\u2014is both empirically unsupportable due to incomplete complication data and conceptually flawed because it narrows ''risk'' solely to immediate surgical complications. By doing so, it fails to account for the intrinsic anatomical, erotic, and psychological value of the foreskin, as well as the ethical harms of non-consensual bodily alteration.\n\nThe paper contends that the debate should instead be structured as ''risk of harm versus prospect of benefit,'' comparing circumcision to other non-therapeutic or prophylactic amputations. Because infants cannot provide informed consent and are not at imminent risk of the conditions circumcision purportedly prevents, parental proxy consent is ethically untenable. The author concludes that non-therapeutic circumcision should be classified as a special medical procedure, with the decision deferred until the individual reaches maturity to exercise bodily autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Brian Morris", "Michael Benatar", "David Benatar", "Tom Beauchamp", "James Childress", "J. Steven Svoboda", "Robert Van Howe", "Michael Brady"], "organizations": ["American Academy of Pediatrics", "Johns Hopkins University Press", "Kennedy Institute of Ethics", "University of Victoria", "Royal Australasian College of Physicians", "British Medical Association", "Royal Dutch Medical Association", "World Health Organization"], "themes": ["Bioethics and Medical Ethics", "Non-Therapeutic Male Circumcision", "Bodily Integrity and Autonomy", "Risk vs Harm Assessment in Medicine", "Pediatric Consent and Parental Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('70cca6a37aa109eb490d4d1a315d689d1fde520a36ce8cc9406631cdfcc49da5', 'Darby Sorcerers Apprentice Contexts 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/70cca6a37aa109eb490d4d1a315d689d1fde520a36ce8cc9406631cdfcc49da5.pdf', 'other', 'ingested', '{"date": "2005", "description": "In this article, historian Robert Darby examines why routine neonatal male circumcision persists widely in the United States while having largely disappeared from other Anglophone countries like Great Britain, Australia, Canada, and New Zealand. Originating in the late nineteenth century amid Victorian anxieties over masturbation and preemptive surgical disease prevention, the procedure became deeply institutionalized in American medicine. Despite ambiguous guidance from the American Academy of Pediatrics and epidemiological data showing no clear superior health outcomes compared to non-circumcising nations, the majority of American boys continue to be circumcised.\n\nDarby argues that the continuation of routine circumcision in the U.S. is driven by sociological, financial, and cultural factors rather than clinical necessity. These include financial incentives provided by insurance and Medicaid, commercial uses of foreskin tissue, a medical culture reluctant to admit past errors, and deeply rooted social norms surrounding parental conformity and locker-room stigma. The author concludes that routine circumcision is the last remnant of Victorian preventive amputation and suggests that its decline will only occur when shifting cultural norms reach a tipping point that restores the natural foreskin as the accepted norm.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Darby", "Edward Wallerstein", "Edward Laumann", "Robert Van Howe", "Lawrence Dritsas", "Geoffrey Miller", "Sarah Waldeck"], "organizations": ["American Sociological Association", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "University of California Press", "Medicaid"], "themes": ["Neonatal Male Circumcision", "American Medical Exceptionalism", "Social Norms and Conformity", "Medical Ethics and Informed Consent", "History of Preventive Surgery", "Financial Incentives in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('13ae6fcbe7746b5402f40efbaa83833b5a44cb04a8253828a1b71dce82fddbd5', 'Darby Svoboda Rose Other Name MedAnthrQtrly 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/13ae6fcbe7746b5402f40efbaa83833b5a44cb04a8253828a1b71dce82fddbd5.pdf', 'medical_journal', 'ingested', '{"date": "2007-09", "description": "Robert Darby and J. Steven Svoboda critically examine the prevailing Western tendency to compartmentalize discussions of genital modifications into acceptable male circumcision versus abhorrent female genital mutilation (FGM). They argue that this definitional double standard obscures objective analysis of the physical, psychological, and sexual harms caused to minors. Emphasizing that both practices involve the nonconsensual excision of healthy, sexually functional tissue from children, the authors propose a standardized five-point scale of anatomical damage for male circumcision to parallel the World Health Organization''s categorization of female genital alterations.\n\nTracing the historical, legal, and cultural roots of this dichotomy, the authors illustrate how Victorian-era medical attitudes and cultural familiarity normalized male circumcision in Anglophone societies while framing female procedures as barbaric. They critique international bodies and professional medical organizations like the American Academy of Pediatrics for maintaining conflicting stances that permit or medically rationalize infant male cutting. Concluding from an ethical and human rights perspective, the authors advocate for gender equity and consistency, calling for bodily integrity protections to be applied equally to male and female children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "J. Steven Svoboda", "Margaret Somerville", "Kirsten Bell", "Sirkuu Hellsten", "Marie Fox", "Michael Thomson", "Sami Aldeeb Abu-Sahlieh", "Ruth Macklin", "Carole Lannon", "Edgar Schoen"], "organizations": ["American Anthropological Association", "World Health Organization", "Attorneys for the Rights of the Child", "American Academy of Pediatrics", "British Medical Association", "Canadian Pediatric Society", "Royal Australasian College of Physicians"], "themes": ["Male Circumcision", "Female Genital Mutilation", "Medical Ethics", "Children''s Rights and Bodily Integrity", "Gender Double Standards", "Cultural Relativism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('17a577a1028c27ad5a28392e11607a175dee1a4d3eadc5d9c84d85c8f86a076f', 'Darby Syphilis_HIV-AIDS Anatomy Gl Pub Hlth 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/17a577a1028c27ad5a28392e11607a175dee1a4d3eadc5d9c84d85c8f86a076f.pdf', 'medical_journal', 'ingested', '{"date": "2014-09-30", "description": "This article draws historical parallels between the medical promotion of male circumcision to combat syphilis in 19th-century Britain and contemporary mass circumcision initiatives aimed at curbing HIV/AIDS in sub-Saharan Africa. In both cases, health crises involving incurable, sexually transmitted infections evoked moralism, stigmatization, and a therapeutic impasse, leading researchers and health authorities to target human anatomy\u2014specifically the foreskin\u2014as the cause of disease rather than focusing on broader behavioral, socio-demographic, and healthcare failures.\n\nThe author argues that the empirical claims supporting circumcision as a prophylactic were methodologically flawed and inconclusive in both eras, noting that circumcision played no discernible role in the eventual control of syphilis. Furthermore, the paper highlights ethical concerns, risks of iatrogenic infection transmission through unsterile surgical practices, and violations of bodily autonomy, warning modern global health authorities against repeating the ethical transgressions and therapeutic dead-ends of the Victorian era.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Jonathan Hutchinson", "E. Harding Freeland", "Abraham Wolbarst", "Herbert Snow", "Arthur Powell"], "organizations": ["UNAIDS", "World Health Organization", "American Academy of Pediatrics", "Royal Commission on Venereal Diseases", "Taylor & Francis"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Syphilis and Venereal Disease History", "Public Health Ethics and Human Rights", "Medical Moralism", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ee16e38a3aa04291f06604ddff1df14e52b4383cc1260c117bfd060617dab69', 'Darby Targeting Patients SageOpen 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ee16e38a3aa04291f06604ddff1df14e52b4383cc1260c117bfd060617dab69.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article critically examines the medical, logical, and ethical justifications for routine non-therapeutic infant circumcision (NTC), particularly in Anglophone countries like the United States. The author argues that the asserted medical benefits\u2014such as reductions in sexually transmitted infections, urinary tract infections, and penile cancer\u2014either fail to demonstrate significant net benefit in developed countries or accrue primarily in adulthood, making prophylactic surgery on healthy, non-consenting minors ethically impermissible. Furthermore, the paper contends that the persistence of infant circumcision stems historically from 19th-century Victorian anti-masturbation crusades and institutional hospital convenience rather than rigorous evidence-based medicine.\n\nEvaluating the practice under core bioethical standards and human rights principles, including bodily integrity, the best interests standard, and the child''s right to an open future, the paper concludes that non-therapeutic circumcision should not be performed on infants who cannot object. Instead, such procedures should be delayed until an individual reaches maturity and can exercise voluntary, informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "David Gollaher", "Richard Miller", "Donald Snyder", "Hiram Yellen", "Brian J. Morris", "Tom L. Beauchamp", "James F. Childress"], "organizations": ["American Academy of Pediatrics", "Royal Australasian College of Physicians", "Canadian Paediatric Society", "World Health Organisation", "Centers for Disease Control", "British Medical Association", "Royal Dutch Medical Association"], "themes": ["Non-Therapeutic Infant Circumcision", "Bioethics and Informed Consent", "Children''s Rights and Bodily Integrity", "Medical History and Professional Practice", "Risk-Benefit Analysis in Pediatric Surgery", "Sexually Transmitted Infections and Prophylaxis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('57a25307bdbbbc9b332617690ddd6ab5bce1fe3aa7876dee6a3c4eea62d41954', 'Darby Where_doctors_differ JSoctySocHistMed 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/57a25307bdbbbc9b332617690ddd6ab5bce1fe3aa7876dee6a3c4eea62d41954.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This article examines the medical debate between 1855 and 1914 regarding the purported protective effect of male circumcision against syphilis. Sparked by flawed statistical claims published by British surgeon Jonathan Hutchinson in 1855, medical advocates increasingly promoted routine infant circumcision as a prophylactic measure against venereal disease, while frequently driven by underlying Victorian moral panics surrounding masturbation, sexual continence, and aesthetic preferences. Sceptics and critics repeatedly questioned these statistical conclusions, pointing out that any perceived lower disease incidence among Jewish populations was largely attributable to behavioral, marital, and cultural factors rather than anatomical differences.\n\nThe author further demonstrates that while circumcision played no actual role in the prevention or microbiological control of syphilis, the surgical procedure itself was a direct vector of infection and mortality for infants prior to aseptic standardization. Complications including hemorrhage, sepsis, and direct transmission of syphilis and tuberculosis\u2014often via traditional practices such as metsitsah or unsterilized surgical tools\u2014posed significant health risks, revealing that the historical justification of circumcision as disease prophylaxis was medically unfounded.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Jonathan Hutchinson", "Peter Charles Remondino", "E. Harding Freeland", "Abraham Wolbarst", "William Acton", "Herbert Snow", "Julius Preuss", "Eugen Levit", "J. Cooper Forster"], "organizations": ["Society for the Social History of Medicine", "Metropolitan Free Hospital", "London Pathological Society", "New York Board of Health", "Viennese Medical Society"], "themes": ["Circumcision", "Syphilis and Venereal Disease", "History of Medicine", "Victorian Morality and Masturbation Panics", "Public Health and Sanitation", "Medical Scepticism and Surgical Risks"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c8ec301fc1e08039888b9dd5fe887b2a2cc52b14f9de0797173f76668f779883', 'Darby-BeenThereDoneThat Austral Qrly 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c8ec301fc1e08039888b9dd5fe887b2a2cc52b14f9de0797173f76668f779883.pdf', 'other', 'ingested', '{"date": "2002-09", "description": "In this commentary, medical historian Robert Darby critically evaluates the argument that male circumcision serves as an effective preventive measure against HIV/AIDS. Comparing international epidemiological data, Darby demonstrates that national rates of circumcision and HIV infection do not correlate consistently across developed or developing nations, arguing that HIV transmission is primarily driven by social, cultural, and behavioral factors rather than genital anatomy.\n\nDarby draws extensive historical parallels to 19th-century physicians who incorrectly promoted circumcision as a panacea against syphilis based on flawed statistical interpretations. He cautions against adopting surgical solutions over proven public health strategies, warning that mass infant or adult circumcision in developing regions raises significant ethical and human rights concerns while diverting vital resources from comprehensive safe sex education and condom distribution programs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Darby", "Roger Short", "Robert Szabo", "Jonathan Hutchinson", "Kevin Dowling"], "organizations": ["UNAIDS", "Royal Australasian College of Physicians", "Catholic Church"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Public Health Policy", "Medical History and Syphilis", "Medical Ethics and Human Rights", "Safe Sex Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('09ff910f14e5f55694578cebbb3005f53173ef2120d8efb262555849bf578d87', 'Darby-mysterious-disappearance-object-inquiry-AmJBio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/09ff910f14e5f55694578cebbb3005f53173ef2120d8efb262555849bf578d87.pdf', 'medical_journal', 'ingested', '{"date": "2015-05-13", "description": "This article is a critical response to Jacobs and Arora''s defense of ritual male infant circumcision. The author, Robert Darby, argues that Jacobs and Arora''s attempt to delineate the acceptable conditions for circumcision is logically incoherent because their strict conditions (performed on infants, in a hygienic clinical setting with adequate analgesia, and as a religious ritual) effectively exclude virtually all real-world forms of cultural, religious, and prophylactic circumcision.\n\nFurthermore, Darby criticizes the authors for conflating legal permissibility with ethical acceptability and human rights principles. He contends that Jacobs and Arora''s framework ultimately elevates parental power over the bodily autonomy and rights of vulnerable infants, warning that their broad defense sets a concerning precedent where children are left unprotected from nontherapeutic interventions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Allan J. Jacobs", "Kavita Shah Arora", "Michael Ignatieff"], "organizations": ["Routledge", "Taylor & Francis Group"], "themes": ["Male Infant Circumcision", "Bioethics", "Human Rights vs. Parental Power", "Medical Ethics and Law", "Bodily Autonomy and Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('72dbd0662b7108867e365b5416406cd81bf0577470055befca4cb141effc0ca0', 'Darby_forgotten_critics_Jewish_arguments (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/72dbd0662b7108867e365b5416406cd81bf0577470055befca4cb141effc0ca0.pdf', 'other', 'ingested', '{"date": "2013", "description": "This historical essay explores the long-standing internal Jewish debate over infant male circumcision, demonstrating that ethical and medical objections to the practice have persisted since antiquity rather than originating from modern anti-Semitism. Tracking the controversy from Hellenistic foreskin restoration and early modern apostate accounts to the 19th-century German-Jewish Enlightenment and Reform movement, the text outlines how Jewish reformers and physicians raised concerns regarding physical harm, infant consent, and religious coercion.\n\nThe document highlights how defenders of the rite increasingly countered these ethical and bodily integrity critiques by medicalizing circumcision in the late 19th and early 20th centuries, attempting to universalize it as a prophylactic health measure. Concluding with reflections on contemporary legal, human rights, and bodily integrity debates in Europe and the United States, the author argues that modern opposition within the Jewish community continues a historical tradition of advocating for children''s rights and parental choice over dogma.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Abraham Glassberg", "Philo of Alexandria", "Samuel Holdheim", "Eugen Levit", "Abraham Wolbarst", "Leonard Glick", "L. Emmett Holt", "Brendan O\u2019Neill"], "organizations": ["Council of Europe", "Society of the Friends of Reform", "Frankfurt Health Department", "New York Board of Health", "Tasmania Law Reform Institute", "Beyond the Bris"], "themes": ["Circumcision debate", "Jewish history and identity", "Bodily integrity and children''s rights", "Medicalization of ritual", "Reform Judaism vs. Orthodox tradition", "Medical ethics and infant harm"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('21499265f0dfb729a47a5b7cf80ee1c5c9928a25856edbcdb322adbd61d02bfe', 'Darby_riddle_of_sands_NZ Med J 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/21499265f0dfb729a47a5b7cf80ee1c5c9928a25856edbcdb322adbd61d02bfe.pdf', 'medical_journal', 'ingested', '{"date": "2005-07-15", "description": "This article challenges and refutes two persistent medical urban myths regarding male circumcision: the notion that ancient religious and ritual circumcision originated as a public health measure to prevent sand-induced balanitis, and the belief that Allied soldiers serving in North Africa and the Middle East during the World Wars required mass circumcisions due to epidemics of sand irritation. Author Robert Darby argues that historical and anthropological evidence shows traditional circumcision practices originated from religious cosmology, tribal rites, and social customs rather than utilitarian health objectives.\n\nFurthermore, Darby examines official British, Australian, and New Zealand military medical histories from World War II, showing that surgical resources were limited and that terms such as ''balanitis,'' ''foreskin,'' or ''circumcision'' do not appear as significant combat-zone medical issues. He concludes that the protective benefits of the foreskin against dust contradict the myth, and urges the medical establishment to abandon unsubstantiated historical claims connecting circumcision to desert sand.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Darby", "Douglas Gairdner", "J.M. Hutson", "Spencer Beasley", "Manfred Rommel", "Aaron Fink"], "organizations": ["New Zealand Medical Association", "Royal Australasian College of Physicians", "Australian National University"], "themes": ["Circumcision", "Medical Urban Myths", "Military Medicine", "Anthropology of Rituals", "History of Medicine", "Hygiene and Sanitation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('643893ac12a85fba2f18a35754976cd4aaf73125ae040ecb03bfc2535e976d5c', 'Davis Childs Right Open Future CapitalUnivLawRev 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/643893ac12a85fba2f18a35754976cd4aaf73125ae040ecb03bfc2535e976d5c.pdf', 'legal_document', 'ingested', '{"date": "1997", "description": "This law review article examines the tension between parental authority, cultural preservation, and a child''s autonomy, framed around Joel Feinberg''s concept of ''the child''s right to an open future.'' Analyzing the landmark U.S. Supreme Court case Wisconsin v. Yoder, author Dena S. Davis critiques the legal deference granted to Amish parents who curtailed their children''s formal schooling after eighth grade to preserve their religious culture. Davis argues that prioritizing cultural continuity over individual development significantly restricts a child''s potential to choose their own path in adulthood.\n\nTo challenge the uncritical acceptance of cultural preservation claims, Davis compares Yoder to two contemporary issues: female genital mutilation (FGM) among immigrant communities and the debate within the Deaf community opposing cochlear implants for deaf children. While the Amish case is often viewed benignly due to societal familiarity, Davis illustrates how similar arguments prioritizing cultural survival over bodily integrity or future autonomy produce profoundly troubling legal and ethical consequences when applied in other cultural contexts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Dena S. Davis", "Joel Feinberg", "Harlan Lane", "Michael Grodin", "Pat Schroeder"], "organizations": ["Cleveland State University", "Capital University Law Review", "World Health Organization", "U.S. Food and Drug Administration", "Gallaudet University"], "themes": ["Child''s Right to an Open Future", "Parental Rights vs. State Intervention", "Religious and Cultural Preservation", "Wisconsin v. Yoder", "Female Genital Mutilation", "Cochlear Implants and Deaf Culture"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ba6cba186cd85d52254c3c83d1f1904fdbdbfc04687d65f41887236d611697c2', 'Davis Collision Course with Law HlthMatrix 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ba6cba186cd85d52254c3c83d1f1904fdbdbfc04687d65f41887236d611697c2.pdf', 'legal_document', 'ingested', '{"date": "2001", "description": "In this article, legal scholar Dena S. Davis analyzes the legal, ethical, and cultural inconsistencies surrounding male and female genital alteration in the United States. While federal and state laws strictly criminalize all forms of female genital alteration (FGA) on minors\u2014including medically supervised, minimal symbolic incisions intended as harm-reduction compromises for immigrant communities\u2014routine neonatal male genital alteration (MGA) remains legally unregulated and culturally normative. Davis points out that the medical justifications often used to defend male circumcision are increasingly contested, with professional organizations like the American Academy of Pediatrics withdrawing routine recommendation, while the risks, pain, and lack of consent mirror many ethical concerns raised against female alteration.\n\nDavis argues that the stark disparity between total criminalization of female genital procedures and a laissez-faire approach to male circumcision lacks a legally defensible foundation. Consequently, this legal divergence implicates constitutional concerns, particularly under the First Amendment''s Free Exercise Clause and the Equal Protection Clause, by affording legal protection against culturally or religiously motivated bodily modification exclusively to female minors while leaving male infants unprotected.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Dena S. Davis", "Pat Schroeder", "Leslie R. Miller", "Doriane Lambelet Coleman", "Ellen Gruenbaum", "David L. Gollaher"], "organizations": ["American Academy of Pediatrics", "Harborview Medical Center", "World Health Organization", "Cleveland-Marshall College of Law", "Case Western Reserve University School of Law", "British Medical Association", "Canadian Paediatric Society"], "themes": ["Female Genital Alteration (FGA)", "Male Genital Alteration (MGA)", "Constitutional Law", "Free Exercise Clause", "Equal Protection", "Cultural Relativism vs. Universal Human Rights", "Bioethics and Neonatal Pain"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ce9929a0efc6ac2dd4a366cc8f9b91a0d2feb947792a2f6776d558bb8ebfea46', 'Davis Cultural Bias MITPress 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ce9929a0efc6ac2dd4a366cc8f9b91a0d2feb947792a2f6776d558bb8ebfea46.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "In this commentary, Dena S. Davis argues that cultural bias shapes the disparate legal and medical treatment of male and female genital surgeries in the United States. While minor forms of female genital alteration are strictly criminalized without exception for religious or cultural beliefs, newborn male circumcision remains virtually unregulated, frequently performed without pain control or formal oversight. Davis contends that this disparity raises serious Constitutional issues regarding equal protection and First Amendment religious freedoms.\n\nTo reconcile this divide and reduce religious and cultural intolerance, Davis proposes policy compromises. Specifically, she recommends that laws be amended to permit medically supervised, painless, and hygienic ''nicks'' for female minors as a harm-reduction measure, while simultaneously instituting regulatory oversight, mandatory licensing of nonphysician practitioners, data tracking, and required analgesia for newborn male circumcisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dena S. Davis", "Michael Benatar", "David Benatar", "Pat Schroeder"], "organizations": ["Cleveland-Marshall College of Law", "American Academy of Pediatrics", "The MIT Press", "University of Victoria"], "themes": ["Bioethics", "Cultural Bias", "Male Circumcision", "Female Genital Alteration", "Equal Protection", "Health Law and Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('94296eb4186dd22aa61edc68e690ee18e0280aafb92e26d9ea28d74b26537be6', 'de Witt Langerin Natural Barrier HIV-1 Langerhans Nature Med 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/94296eb4186dd22aa61edc68e690ee18e0280aafb92e26d9ea28d74b26537be6.pdf', 'medical_journal', 'ingested', '{"date": "2007-03-04", "description": "This academic study investigates the role of Langerin, a C-type lectin expressed on epithelial Langerhans cells (LCs), during human immunodeficiency virus-1 (HIV-1) transmission. Contrary to DC-SIGN on subepithelial dendritic cells which facilitates HIV-1 transfer to T cells, Langerin acts as a natural protective barrier by capturing HIV-1, internalizing it into Birbeck granules, and promoting viral degradation and clearance.\n\nThe authors demonstrate that immature LCs do not efficiently transmit HIV-1 to T cells unless Langerin is inhibited (e.g., by mannan or blocking antibodies) or saturated by exceptionally high viral loads. These findings highlight that anti-HIV microbicide development must avoid blocking Langerin function, as preserving its clearance activity is vital to mucosal defense against HIV-1 infection.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lot de Witte", "Alexey Nabatov", "Marjorie Pion", "Donna Fluitsma", "Marein A W P de Jong", "Tanja de Gruijl", "Vincent Piguet", "Yvette van Kooyk", "Teunis B H Geijtenbeek"], "organizations": ["VU University Medical Center", "University Hospital of Geneva", "University Medical Center Utrecht", "Kazan State Medical University", "Instituto de Investigaci\u00f3n Sanitaria Gregorio Mara\u00f1\u00f3n", "Amsterdam University Medical Center"], "themes": ["HIV-1 Transmission", "Langerhans Cells", "Langerin Function", "DC-SIGN", "Mucosal Immunity", "Microbicides"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('97756858b579e2c181529f2ae000fbaee571937143d23ed1d29428f7d02a3d7e', 'Dekel Circumcising_the_body_Natl Ident 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/97756858b579e2c181529f2ae000fbaee571937143d23ed1d29428f7d02a3d7e.pdf', 'other', 'ingested', '{"date": "2019-05-03", "description": "This academic study examines the intense public and political debate surrounding male ritual circumcision in Germany in 2012, triggered by a Cologne regional court ruling that classified the non-medical circumcision of a young boy as bodily injury. Analyzing media coverage across Germany, Israel, and Turkey, the authors explore how the debate served as a symbolic battleground over national identity, minority inclusion, and bodily integrity.\n\nEmploying concepts such as Michel Foucault''s ''clinical gaze'' and Mary Douglas''s ''ring composition,'' the paper demonstrates how the German secular-liberal majority positioned state-regulated medical authority above religious tradition, framing Jewish and Muslim rituals as archaic or harmful. At the same time, the debate spurred transnational solidarity between Jewish and Muslim communities defending their constitutional rights, while revealing underlying tensions and persistent modes of exclusion within modern liberal nation-states.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Irit Dekel", "Bernhard Forchtner", "Ibrahim Efe", "Angela Merkel", "Charlotte Knobloch", "Holm Putzke", "J\u00fcrgen Habermas"], "organizations": ["German Bundestag", "Landgericht K\u00f6ln", "Central Council of Jews in Germany", "Giordano Bruno Foundation", "J\u00fcdisches Museum Berlin", "Friedrich Schiller University Jena", "University of Leicester"], "themes": ["Ritual Circumcision Debate", "Bodily Integrity vs. Religious Freedom", "Minority Rights and Integration", "Clinical Gaze and Biopolitics", "Secularism and National Identity", "Jewish-Muslim Alliances"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3f5f2943b5abfd8a509790eb6dee48aa63578b17f7e1e2bc1d80dce40448b985', 'Devecioglu Challenging God  JPedUrol 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3f5f2943b5abfd8a509790eb6dee48aa63578b17f7e1e2bc1d80dce40448b985.pdf', 'letter', 'ingested', '{"date": "2023-08-21", "description": "This document is a letter to the editor responding to a study by Villanueva et al., which evaluated expanding the inclusion criteria for in-office Gomco clamp circumcisions in infants older than three months or heavier than 5.5 kg. The authors strongly argue against routine infant circumcision, characterizing it as an unnecessary, painful, and historically rooted mutilation that pediatric surgeons should avoid rather than facilitate through broadened clinical criteria.\n\nThe authors highlight the natural embryological development of the prepuce, noting that physiological non-retractability is standard in infants and young children. They critically question the practice of administering multiple local anesthetic injections into an awake infant''s penis, identify multiple confounding variables regarding bleeding complications and hemostatic materials in the original study, and assert that the foreskin serves vital anatomical functions that warrant preservation rather than surgical removal.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["De\u011fer Devecio\u011flu", "H\u00fcseyin \u00d6zbey", "C. A. Villanueva", "D. Salevitz", "D. M. Gairdner"], "organizations": ["Journal of Pediatric Urology", "Medi-Life Beylikd\u00fcz\u00fc Hospital", "Sechenov First Moscow State Medical University", "Elsevier Ltd."], "themes": ["Infant Circumcision", "Pediatric Surgery Ethics", "Gomco Clamp Procedures", "Prepuce Anatomy and Development", "Surgical Complications and Hemostasis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4a0cfde2d748ec2330822ac04fa0e9fe93fc23bec3ca28e4112e3105355defcd', 'Dias_Adult Circ-Andrologia 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4a0cfde2d748ec2330822ac04fa0e9fe93fc23bec3ca28e4112e3105355defcd.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This retrospective study evaluates the impact of adult male circumcision on sexual function among 62 adult men operated on in 2011, predominantly for phimosis. Through telephone surveys using validated sexual health scales and matched-pairs analysis, the authors assessed changes in erectile dysfunction, delayed orgasm, premature ejaculation, and pain with intercourse. The findings showed a significant increase in post-operative erectile dysfunction (rising from 9.7% to 25.8%) and delayed orgasm (rising from 11.3% to 48.4%), alongside a marked relief in pain during intercourse (decreasing from 50.0% to 6.5%), while premature ejaculation rates remained largely unchanged.\n\nMultivariate regression identified diabetes mellitus and reduced sexual desire as independent predictors for the onset of de novo erectile dysfunction, whereas having fewer than three lifetime sexual partners and low sexual desire predicted de novo delayed orgasm. The authors conclude that circumcision in adult men carries risks of non-trivial sexual dysfunctions, underscoring the importance of thorough pre-operative patient counseling regarding these sexual health implications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jorge Dias", "R. Freitas", "R. Amorim", "P. Espiridi\u00e3o", "L. Xambre", "L. Ferraz"], "organizations": ["Centro Hospitalar Vila Nova de Gaia/Espinho", "Instituto Portugu\u00eas de Oncologia do Porto \u2013 Francisco Gentil"], "themes": ["Adult Circumcision", "Male Sexual Health", "Erectile Dysfunction", "Delayed Orgasm", "Dyspareunia"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e25e2d5b497d959ef2cc9460350c05c902d3d415cbf7787d3d1d1bfc5c8a18e4', 'Dibieamaka FGM Implications WomenStudIntForum 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e25e2d5b497d959ef2cc9460350c05c902d3d415cbf7787d3d1d1bfc5c8a18e4.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This study investigates the effects of female genital mutilation (FGM) on female sexuality among 400 undergraduate students at Delta State University, Abraka, Nigeria. Evaluating factors such as sexual initiation, erogenous sensitivity, frequency of sexual intercourse, and attitudes toward the practice, the researchers found that 70% of respondents were uncircumcised. The study demonstrated that circumcised women were more supportive of continuing the practice and having their daughters circumcised compared to uncircumcised women.\n\nFurthermore, the findings debunk the cultural belief that circumcision curbs promiscuity or prevents early sexual debut; circumcised students had a slightly younger mean age of first intercourse (18.4 years) than uncircumcised students (19.8 years). The authors also noted that circumcision altered erogenous sensitivity, with circumcised women displaying a shift in sensitivity away from the clitoris, and recommended that anti-FGM educational campaigns be directed toward circumcised women and those with lower education levels.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Samuel Dibieamaka Nwajei", "Andrew Iwesim Otiono"], "organizations": ["Delta State University, Abraka", "Elsevier Ltd", "World Health Organization", "Inter-African Committee"], "themes": ["Female Genital Mutilation (FGM)", "Female Sexuality", "Sexual Health", "Cultural and Traditional Practices", "Erogenous Sensitivity", "Women''s Rights and Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8e443a9112857116aa58c4b18c320c4a8714cdd4477cfb2b7082f8c4c1c90203', 'Diekema Critical Eval of Adler CDC_2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8e443a9112857116aa58c4b18c320c4a8714cdd4477cfb2b7082f8c4c1c90203.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article critically evaluates and refutes a challenge by legal advisor Peter Adler against the Centers for Disease Control and Prevention (CDC) draft recommendations supporting elective infant male circumcision in the United States. The authors argue that Adler''s opposition relies on speculative claims, flawed methodologies, and activist rhetoric that mischaracterize scientific consensus. They demonstrate that empirical evidence strongly supports infant circumcision as an effective preventive health measure that significantly reduces lifetime risks of urinary tract infections, sexually transmitted infections including HIV, and penile and cervical cancers, with minimal and rare complications when performed in infancy.\n\nAdditionally, the authors defend the legal, procedural, and ethical justifications of the CDC guidelines. They refute arguments that circumcision violates bodily integrity, constitutional protections, or international human rights conventions such as the UN Convention on the Rights of the Child (CRC). Instead, they affirm that infant male circumcision aligns with the best interests of the child and falls squarely within recognized parental rights to make proactive medical and preventive health decisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Beth E. Rivin", "Douglas S. Diekema", "Anna C. Mastroianni", "John N. Krieger", "Jeffrey D. Klausner", "Brian J. Morris", "Peter W. Adler", "Robert S. Van Howe", "Morten Frisch"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Attorneys for the Rights of the Child", "University of Washington", "University of Sydney", "World Health Organization", "United Nations"], "themes": ["Infant Male Circumcision", "Public Health and Disease Prevention", "Bioethics and Children''s Rights", "Parental Consent and Autonomy", "Health Policy and Regulation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('13c45702d9e1f96a8368497df63ccf45dfff5a3fef74c750ae81b0425d6defa4', 'DiPietro,Gonzalez PrevNewbornCirc CuadernosBio 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/13c45702d9e1f96a8368497df63ccf45dfff5a3fef74c750ae81b0425d6defa4.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article evaluates the ethical, clinical, and bioethical controversies surrounding preventive newborn male circumcision. While proponents argue that neonatal circumcision reduces the incidence of urinary tract infections (UTIs), penile cancer, and sexually transmitted diseases (including HIV/AIDS), the authors demonstrate that the prophylactic benefits are either marginal, treatable through less invasive measures, or inappropriately extrapolated from adult randomized trials conducted in high-prevalence settings. Furthermore, the procedure carries potential acute and long-term complications, including pain, hemorrhage, infection, and meatal stenosis.\n\nFrom a bioethical standpoint, the authors argue that preventive surgical intervention on healthy tissue violates the principle of totality, the child''s right to bodily integrity, and the child''s right to an open future. Because the potential health risks circumcised tissue is thought to mitigate occur primarily in adulthood or can be managed with standard hygiene and medical treatments, preventive neonatal circumcision fails to meet the legal and ethical standard of the ''child''s best interest.'' The authors conclude that non-therapeutic bodily alterations should be delayed until the individual is mature enough to grant informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maria Luisa Di Pietro", "Adele A. Teleman", "Andrea Poscia", "Ferm\u00edn J. Gonz\u00e1lez-Melado", "Nicola Panocchia"], "organizations": ["Catholic University of Sacred Heart", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "British Medical Association", "British Association of Paediatric Surgeons", "Royal Dutch Medical Association", "High Center for Theological Studies - Badajoz"], "themes": ["Male Circumcision", "Neonatal Healthcare", "Preventive Medicine", "Child''s Best Interest Standard", "Bodily Integrity", "Bioethics and Human Rights", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a76505f8cc4af7a7d1b73b6e5ee1bec60a149147327e8b4abe9fa078222eec67', 'Dogra Circumcision or preputioplasty MedJPatilUniv 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a76505f8cc4af7a7d1b73b6e5ee1bec60a149147327e8b4abe9fa078222eec67.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This medical commentary examines the overuse of circumcision for non-retractile foreskins in boys, emphasizing that developmental physiological narrowness is frequently misdiagnosed as pathological phimosis. It highlights that natural retractability typically develops spontaneously through puberty and that normal transient issues like preputial ballooning during voiding do not warrant surgical excision.\n\nThe author advocates for conservative alternatives when surgical intervention is required, specifically recommending standard and lateral preputioplasty techniques. These prepuce-preserving procedures relieve constriction while retaining the anatomical, sensory, and functional advantages of the foreskin, reserving full circumcision strictly for true pathological scarring conditions such as balanitis xerotica obliterans.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Bharat Bhushan Dogra", "K. Pal"], "organizations": ["Padmashree Dr D Y Patil Medical College, Hospital and Research Centre", "Dr D Y Patil Vidyapeeth"], "themes": ["Phimosis Diagnosis and Treatment", "Preputioplasty", "Circumcision Indications", "Foreskin Preservation", "Pediatric Urology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2276e17c5bf096d743c91ea196d8f801defe391b8b8ab1fbb2841c5514d10277', 'Dowsett Enough right kind of evidence ReproHlthMatt 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2276e17c5bf096d743c91ea196d8f801defe391b8b8ab1fbb2841c5514d10277.pdf', 'medical_journal', 'ingested', '{"date": "2007-05", "description": "This article critically examines the rapid policy push by international agencies to adopt male circumcision as a primary biomedical HIV prevention technology following randomised clinical trials in South Africa, Kenya, and Uganda. The authors argue that the enthusiasm emerging from the 2006 Toronto AIDS Conference and subsequent WHO/UNAIDS policy statements relies on a narrow definition of scientific evidence that conflates clinical trial efficacy with real-world effectiveness.\n\nDowsett and Couch contend that evidence-based policymaking requires a generative model of causation that accounts for broader social, cultural, and behavioural contexts rather than trial efficacy figures alone. They highlight critical unaddressed issues, including behavioural disinhibition and risk compensation, adverse surgical outcomes, ethical implications regarding neonatal consent and human rights, the safety and meaning of traditional circumcision practices, and the neglect of diverse populations such as men who have sex with men (MSM) and women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gary W. Dowsett", "Murray Couch", "Ray Pawson", "Anthony S. Fauci", "Bill Clinton", "Stephen Lewis"], "organizations": ["Reproductive Health Matters", "Elsevier", "La Trobe University", "World Health Organization", "UNAIDS", "National Institute of Allergy and Infectious Diseases"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Evidence-Based Policy", "Randomised Clinical Trials", "Public Health and Ethics", "Sexual and Reproductive Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('99720672f2a998097a598c706715f6541a7dd51df33b86cc687799876b5f3eb3', 'Drash Psychological Distress in Anglophone Population 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/99720672f2a998097a598c706715f6541a7dd51df33b86cc687799876b5f3eb3.pdf', 'unknown', 'ingested', '{"date": "2024", "description": "", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "error": "Failed to generate"}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bb823467bef29ad9408859747a023b6ce8868fd0937e818f99dc4d8a676e333e', 'Dresser Best Interests v Harm Prev AmJBio 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bb823467bef29ad9408859747a023b6ce8868fd0937e818f99dc4d8a676e333e.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "In this commentary, Rebecca Dresser argues that the traditional ''best interests'' standard governing surrogate healthcare choices should be replaced with a ''harm prevention'' framework that grants families greater discretion. Drawing from Michael and David Benatar''s analysis of parental choice regarding neonatal male circumcision, Dresser contends that clinicians and legal authorities should apply a similar model to end-of-life decisions for decisionally incapacitated adults. Under this proposed standard, a family''s decision to forgo or withdraw life-sustaining treatment would be ethically and legally permissible so long as it does not impose clear harm on the patient.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Rebecca Dresser", "Michael Benatar", "David Benatar", "William G. Stowell"], "organizations": ["The American Journal of Bioethics", "Washington University in St. Louis", "Medicaid", "United Nations"], "themes": ["Bioethics", "Surrogate Decision-Making", "Best Interests Standard", "Harm Prevention", "End-of-Life Care", "Parental Discretion", "Incapacitated Patients"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ecbd8b7d4e32c46f8d8a87a6507b07bffd19a4c1962f700ed0cb3422c42bba95', 'Dritsas Below_belt_Doctors_debate SciTechSoc 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ecbd8b7d4e32c46f8d8a87a6507b07bffd19a4c1962f700ed0cb3422c42bba95.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This article provides a critical examination of the ongoing controversy and history surrounding routine neonatal male circumcision in the United States. While the practice was historically adopted based on late-19th-century theories of reflex neurosis and hygiene, other developed nations have largely abandoned it. The author analyzes the evolution of medical policy statements, particularly those from the American Academy of Pediatrics in 1989 and 1999, which moved from identifying no valid medical indications to acknowledging marginal prophylactic benefits (such as decreased risk of urinary tract infections and penile cancer) without firmly endorsing routine surgery.\n\nThe author explores the ethical contradictions inherent in current medical guidelines, highlighting issues of proxy parental consent, the lack of therapeutic necessity for healthy tissue removal, and the stark double standard applied when comparing male circumcision to the universal medical opposition toward female genital cutting. The article concludes that continuing routine circumcision in the U.S. relies heavily on entrenched medical culture and professional habit rather than modern evidence-based necessity, recommending that the practice be suspended until a clear consensus emerges.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lawrence S. Dritsas", "Lewis A. Sayre", "Peter Remondino", "Douglas Gairdner", "Thomas Wiswell", "Edgar J. Schoen", "David L. Gollaher"], "organizations": ["American Academy of Pediatrics", "Virginia Polytechnic Institute and State University", "American Medical Association", "British Medical Association", "Canadian Paediatric Society", "National Health Service"], "themes": ["Routine Neonatal Male Circumcision", "Medical History and Medicalization", "Bioethics and Informed Proxy Consent", "Preventative Surgery vs. Therapeutic Necessity", "Comparative International Healthcare Practices", "Discourse on Male vs. Female Genital Modification"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('41867add225190a7f64f53d8f6c0dd0c0d577597489589bef9ad81789ec36d72', 'Duivenbode Criminalizing medically unnecessary child genital IJIR 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/41867add225190a7f64f53d8f6c0dd0c0d577597489589bef9ad81789ec36d72.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This perspective article examines the ongoing ethical and legal debates surrounding the proposed criminalization of medically unnecessary, non-therapeutic child genital cutting\u2014specifically ritual male circumcision\u2014in Western liberal societies. The author categorizes the debate into several distinct viewpoints, contrasting children''s rights activists advocating for prohibition grounded in individual bodily autonomy with arguments from public health proponents, religious freedom defenders, harm-reduction strategists, and value pluralists.\n\nThe author focuses on two primary arguments against criminalization: an expanded harm-reduction strategy, which warns that prohibitions may cause greater harm by driving procedures underground or stigmatizing minorities, and a value pluralism framework based on Isaiah Berlin''s concept of incommensurable goods. Ultimately, the paper argues that Western liberal states should exercise caution and avoid criminalization, as ritual prepuce-cutting falls within the realm of legitimate cultural and religious difference, suggesting that medical regulation rather than prohibition is the most sound approach.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R. Duivenbode", "Richard A. Shweder", "Isaiah Berlin", "Allan J. Jacobs", "Kavita Shah Arora"], "organizations": ["University of Chicago Divinity School", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Royal Dutch Medical Association", "Danish Medical Association", "Brussels Collaboration on Bodily Integrity"], "themes": ["Male Circumcision", "Female Genital Cutting", "Criminalization and Law", "Value Pluralism", "Harm Reduction", "Children''s Rights and Bodily Integrity", "Religious Freedom and Multiculturalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('88ee23624cc80fb4b29e6c4417fd1b1a7a52c4554314ca826b42f333bccda178', 'Dupret-El Bernoussi Circumcision OxfordIslamicStud 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/88ee23624cc80fb4b29e6c4417fd1b1a7a52c4554314ca826b42f333bccda178.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic text examines the practices of male circumcision (khitan) and female circumcision (khifad/FGM) across historical, cultural, bioethical, and Islamic jurisprudential contexts. It outlines the surgical procedures, cultural rituals, and theological debates surrounding both practices, noting that male circumcision is nearly universal in the Muslim world and framed around purification and hygiene, whereas female circumcision is geographically concentrated, heavily contested, and increasingly condemned as a human rights violation.\n\nThe authors further trace historical precedents from pre-Islamic and Abrahamic traditions into pre-modern and modern Islamic legal thought. While traditional jurists debated the obligatoriness of the procedures based on hadith rather than the Quran, modern debates encompass medical bioethics, feminist critiques, and legal confrontations in countries like Egypt and Indonesia over bodily integrity and religious authority.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Zaynab El Bernoussi", "Baudouin Dupret", "Al-Ja\u1e25i\u1e93", "Abu Hayyan al-Tawhidi", "Nawal El Saadawi", "Yusuf Al-Qaradawi", "Mustafa Kamal al-Mahdawi", "Arif Bhimji"], "organizations": ["Oxford Islamic Studies Online", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "World Health Organization", "United Nations", "Majelis Ulama Indonesia", "Egyptian Supreme Administrative Court"], "themes": ["Male and Female Circumcision", "Islamic Jurisprudence and Sharia", "Bioethics and Pediatric Health", "Bodily Integrity and Human Rights", "Cultural and Religious Rites of Passage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('41086109d47d3a02337bce15525ea886ee58e0df7f514c8a445fcc5409dd28a2', 'Earp AAP 2012_report_bad_science PractEth 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/41086109d47d3a02337bce15525ea886ee58e0df7f514c8a445fcc5409dd28a2.pdf', 'other', 'ingested', '{"date": "2013-05-27", "description": "This commentary critically examines the American Academy of Pediatrics'' (AAP) 2012 policy statement endorsing infant male circumcision, arguing that the policy is built on flawed scientific reasoning and questionable biomedical ethics. The author contends that the AAP relies inappropriately on African adult heterosexual HIV studies that are not generalizable to infant populations in developed countries, while ignoring less invasive, more effective alternatives such as condoms, vaccines, and hygiene. \n\nFurthermore, the author argues that non-therapeutic circumcision violates a child''s right to bodily integrity and exceeds the ethical limits of parental proxy consent. Aligning with broad international medical opposition, particularly from European and Canadian health authorities, the document concludes that the AAP''s stance reflects an entrenched American cultural bias and conflicts of interest among task force members rather than evidence-based medical consensus.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Robert Van Howe", "Noni MacDonald", "Susan Blank", "Andrew Freedman", "Douglas Diekema"], "organizations": ["American Academy of Pediatrics", "University of Oxford", "Doctors Opposing Circumcision", "Royal Dutch Medical Association"], "themes": ["Infant Male Circumcision", "Medical Ethics", "Bodily Integrity", "Parental Consent", "Cultural Bias in Medicine", "Preventive Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('860139fb84f29a2a2ad566d286994fbcb7b5c533fa67e41310676b5e98dd23cc', 'Earp Abdulcadir Child_genital_cutting_Pt1 IJIR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/860139fb84f29a2a2ad566d286994fbcb7b5c533fa67e41310676b5e98dd23cc.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This journal editorial introduces a two-part special collection evaluating child genital cutting and surgery practices across cultures, sex, and gender boundaries. The authors argue for an urgent, unified ethical and legal framework to evaluate all non-therapeutic genital modifications performed on pre-autonomous minors. They highlight notable legal and ethical contradictions in Western societies, where all forms of female genital cutting are strictly criminalized regardless of severity or parental intent, whereas medically unnecessary surgeries on intersex infants and routine male infant circumcision remain widely permitted.\n\nAdditionally, the authors examine the contested concepts of ''medical necessity'' and informed consent in pediatric care, debating whether parents should have proxy decision-making authority over permanent modifications to a child''s sexual anatomy. The editorial contrasts involuntary infant or childhood procedures with the distinct, emerging debates surrounding gender-affirming surgeries in trans adolescents, ultimately calling for an end to arbitrary sex- and culture-based double standards in protecting minors'' rights to bodily integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Jasmine Abdulcadir", "Lih-Mei Liao"], "organizations": ["World Health Organization", "World Professional Association for Transgender Health"], "themes": ["Child Genital Cutting and Surgery", "Intersex Rights and Normalizing Surgeries", "Informed Consent and Bodily Integrity", "Medical Necessity vs. Cosmetic Surgery", "Bioethics and Law", "Gender and Sex Norms"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('481d389e2f2190163487f44ca97de8b963439f9868d223e2ca64de1ae2a1506f', 'Earp Abdulcadir Child_genital_cutting_Pt2 IJIR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/481d389e2f2190163487f44ca97de8b963439f9868d223e2ca64de1ae2a1506f.pdf', 'medical_journal', 'ingested', '{"date": "2023-04-21", "description": "This editorial introduces Part 2 of a special issue exploring child and adolescent genital cutting and surgery across cultures, sexes, and genders, focusing specifically on individuals born with ''endosex'' traits. The authors examine the ethical, legal, and clinical frameworks governing ''gendered genital modifications'' (GGMs), evaluating how cultural standards and power-asymmetric relationships influence decisions surrounding non-voluntary and medically unnecessary procedures such as newborn penile circumcision, adolescent labiaplasty, and ritual genital modifications.\n\nThe authors highlight persistent cultural and legal double standards in Western healthcare systems. While traditional or ritual female genital modifications are strictly criminalized as female genital mutilation (FGM) regardless of consent or minimal invasiveness, anatomically comparable or more invasive procedures\u2014such as cosmetic labiaplasty or infant male circumcision\u2014are often permitted or justified under broad interpretations of cosmetic relief or health benefits. The editorial argues against using weak notions of ''medical reasons'' to rationalize non-consensual modifications, proposing instead a strict standard of medical necessity and advocating that decisions regarding bodily alteration be deferred until the affected individual can provide fully informed, voluntary consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Jasmine Abdulcadir", "Lih-Mei Liao"], "organizations": ["University of Oxford", "University Hospitals of Geneva", "University of Geneva", "World Health Organization", "American Academy of Pediatrics", "Springer Nature"], "themes": ["Gendered Genital Modifications", "Informed Consent and Autonomy", "Medical Necessity vs. Cosmetic Surgery", "Female Genital Mutilation/Cutting (FGM/C)", "Penile Circumcision", "Bioethics and Pediatric Ethics", "Cultural Relativism and Legal Inconsistencies"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d65791e6cd7e7f48b287add3d67c455d8168f26c3b0ed6d94efbc441b37c9283', 'Earp Abdulcadir What_counts_as_mutilation CultHlthSex 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d65791e6cd7e7f48b287add3d67c455d8168f26c3b0ed6d94efbc441b37c9283.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This article serves as the editorial introduction to a Special Collection in Culture, Health & Sexuality, examining female, male, and intersex genital cutting and modification practices across global contexts. The authors challenge prevailing Western double standards and dominant discourses that categorize non-Western female genital cutting strictly as ''mutilation'' requiring criminal eradication, while simultaneously normalizing or medicalizing infant male circumcision, intersex ''normalization'' surgeries, and female genital cosmetic procedures in the Global North.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Jasmine Abdulcadir", "Arianne Shahvisi", "Ellen Gruenbaum", "Jo Boyden", "Claudia Merli", "Annette Smith", "Peter Hegarty"], "organizations": ["World Health Organization", "National University of Singapore", "University of Oxford", "Geneva University Hospitals", "University of Geneva", "Brighton and Sussex Medical School", "United States Agency for International Development"], "themes": ["Genital cutting and modification", "Female Genital Mutilation/Cutting (FGM/C)", "Male circumcision", "Intersex genital normalization", "Cultural imperialism and bioethics", "Medicalization of cultural practices", "Consent and bodily autonomy", "Hegemonic masculinity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1992c184994e9ab823c304ea5eb23cd78802fcede428d43fb0b4812c60b57b5', 'Earp Abolishing Gender FutureMorality 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1992c184994e9ab823c304ea5eb23cd78802fcede428d43fb0b4812c60b57b5.pdf', 'other', 'ingested', '{"date": "2021", "description": "This academic chapter examines the philosophical debate surrounding gender abolition versus reform. Abolitionists argue that the Dominant Gender Ideology (DGI) upholds patriarchy and systematically oppresses women, concluding that socially enforced gender roles must be eliminated entirely. Conversely, progressive critics like Matthew J. Cull contend that abolishing gender would conceptually or socially erase transgender individuals whose self-conception and flourishing depend on the intelligibility of gender categories.\n\nUsing an analogy to the abolition of the samurai class in 19th-century Japan, author Brian D. Earp explores how the dismantling of social categories impacts personal identity. Concluding with insights from philosopher Sally Haslanger, Earp suggests that full abolition may be biologically and socially unrealistic. Instead, he advocates reforming gender scripts to dismantle oppressive power dynamics and eliminating punitive social sanctions against those who deviate from traditional gender roles.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Matthew J. Cull", "Sally Haslanger", "David Edmonds", "Robin Dembroff"], "organizations": ["Yale University", "University of Oxford", "Oxford University Press", "The Hastings Center"], "themes": ["Gender Abolition", "Dominant Gender Ideology", "Transgender Identity", "Feminist Philosophy", "Social Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0c488a28b2735208449fb2c4e5b81bcb20987b0885164aa4db793af4d2e8dcea', 'Earp Against legalising FGC Global 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0c488a28b2735208449fb2c4e5b81bcb20987b0885164aa4db793af4d2e8dcea.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This academic commentary by Brian D. Earp responds to Richard Shweder''s argument advocating for the legal accommodation of minor, non-consensual female genital cutting (FGC)\u2014specifically the practice of khafz among the Dawoodi Bohra community\u2014to rectify the sex-based double standard between male and female circumcision under Western law. While agreeing that Western legal frameworks display profound moral and legal inconsistencies by permitting non-consensual male circumcision while criminalizing comparable female practices, Earp argues against resolving this disparity through the legalization of female circumcision.\n\nEarp contends that bodily and genital integrity should be protected for all children regardless of sex characteristics or religious background, asserting that no medically unnecessary genital cutting should occur without the affected individual''s own informed consent. He suggests that instead of legalizing childhood FGC to match current practices around male circumcision, both procedures should be recognized as non-consensual physical battery and unlawful under secular legal principles, while advocating for harm reduction and non-carceral dissuasion over immediate criminal penalties to avoid disproportionately penalizing minority communities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Richard Shweder", "Jumana Nagarwala", "Bernard Friedman"], "organizations": ["University of Oxford", "Bristol University Press", "World Health Organization", "American Academy of Pediatrics", "Sahiyo"], "themes": ["Female Genital Cutting", "Male Circumcision", "Bodily Integrity", "Children''s Rights", "Informed Consent", "Medical Ethics", "Legal and Sex-Based Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8ebe1ebee95da580d8534c7077f8a4d48ada0de052479f3a6b1acbf573c45cc2', 'Earp Autonomy based ethical framework MedLegBio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8ebe1ebee95da580d8534c7077f8a4d48ada0de052479f3a6b1acbf573c45cc2.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This review paper by Brian D. Earp challenges the prevailing Western double standard that treats non-therapeutic female genital alteration (conventionally termed female genital mutilation or FGM) as categorically impermissible while viewing male circumcision as benign or beneficial. Earp argues that the conventional harm-based and symbolic arguments used to justify this distinction are empirically and philosophically untenable, as both practices span overlapping continuums of severity, potential complications, and cultural meanings.\n\nRather than maintaining separate, gender-based ethical and legal discourses, Earp proposes an autonomy-based ethical framework centered on bodily integrity and informed consent. Under this proposed framework, non-therapeutic, irreversible surgical alterations to healthy genital tissue should not be performed on minors of any sex or gender without medical necessity, preserving the individual''s right to make choices regarding their own body upon reaching the age of consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D Earp", "Joseph Mazor", "Kirsten Bell", "Nahid Toubia", "Anika Rahman"], "organizations": ["Dove Medical Press", "University of Cambridge", "World Health Organization", "United Nations", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Female Genital Mutilation (FGM)", "Male Circumcision", "Bodily Autonomy and Integrity", "Informed Consent", "Bioethics", "Gender and Cultural Norms"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fc28ab6ba4b707e3958d670a057c3d3db5f8659cbac5907a9ad101d3d9041227', 'Earp Between Moral Relativism KennIJE 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fc28ab6ba4b707e3958d670a057c3d3db5f8659cbac5907a9ad101d3d9041227.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article critiques the orthodox international consensus against female genital mutilation (FGM), led by bodies such as the World Health Organization (WHO) and the United Nations (UN). Author Brian D. Earp argues that while the WHO/UN condemn all forms of FGM under absolute human rights and anti-harm frameworks, their stance exhibits cultural bias and moral hypocrisy. Specifically, Western discourse fails to apply these same moral standards to culturally familiar yet functionally analogous practices, such as routine nontherapeutic infant male circumcision and Western female genital cosmetic surgeries.\n\nTo move beyond the dichotomy of cultural relativism and moral double standards, Earp introduces an ethical framework derived from the biomedical ''enhancement'' literature. This framework posits that any nontherapeutic, irreversible alteration of healthy genital tissue\u2014regardless of gender or cultural background\u2014involves permanent trade-offs and should be delayed until the individual reaches the maturity and capacity to provide personal informed consent, rather than having such interventions imposed during childhood.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Fuambai Ahmadu", "Richard Shweder", "Lori Leonard", "Carla Obermeyer", "Nelson Mandela", "Nahid Toubia", "Debra DeLaet", "Martha Nussbaum"], "organizations": ["World Health Organization", "United Nations", "Kennedy Institute of Ethics", "Johns Hopkins University Press", "Harborview Medical Center", "Public Policy Advisory Network on Female Genital Surgeries in Africa"], "themes": ["Female Genital Mutilation (FGM)", "Moral Relativism and Moral Hypocrisy", "Male Circumcision", "Bioethics and Bodily Integrity", "Cultural Imperialism and Double Standards", "Informed Consent and Children''s Rights", "Biomedical Enhancement"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eeeb288ebb312153d77530ebac1da362679b2ba301e57def62810a1a8b5c715e', 'Earp Boys_and_girls_alike Aeon 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eeeb288ebb312153d77530ebac1da362679b2ba301e57def62810a1a8b5c715e.pdf', 'other', 'ingested', '{"date": "2015-01-13", "description": "In this essay, Brian D. Earp argues that non-therapeutic genital cutting performed on healthy, non-consenting children is ethically problematic regardless of the child''s sex or gender. He challenges the prevailing Western double standard that universally condemns female genital mutilation (FGM) as criminal torture while routinely defending or medicalizing male infant circumcision. By examining the spectrum of severity, cultural rationales, and health arguments for both practices, Earp demonstrates that common distinctions\u2014such as motivations of hygiene, aesthetics, or sexual control\u2014often overlap significantly.\n\nUltimately, Earp maintains that parental intentions and cultural justifications should not override a child''s fundamental right to bodily integrity. Because individuals experience the functional, aesthetic, and psychological impacts of genital alterations differently, he concludes that any irreversible, medically unnecessary genital surgeries should be deferred until the individual is mature enough to provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Margaret Somerville", "Kirsten Bell", "Dena Davis", "Tanya Gold", "Lisa Wade", "Hanny Lightfoot-Klein", "Sara Johnsdotter"], "organizations": ["University of Oxford", "World Health Organization", "Centers for Disease Control and Prevention", "Aeon Magazine"], "themes": ["Male Circumcision", "Female Genital Mutilation (FGM)", "Medical Ethics", "Bodily Autonomy", "Informed Consent", "Children''s Rights", "Cultural Relativism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0365b874744a2f88d16e76a146abd12e4eb109e8cf872409be1620cc1873dc8f', 'Earp Boys_and_girls_alike Women Healthcare 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0365b874744a2f88d16e76a146abd12e4eb109e8cf872409be1620cc1873dc8f.pdf', 'other', 'ingested', '{"date": "2016", "description": "This document contains a formal academic citation for a book chapter authored by B. D. Earp titled ''Boys and girls alike: The ethics of male and female circumcision.'' The chapter appears in the edited collection ''Women, Health, & Healthcare: Readings on Social, Structural, & Systemic Issues,'' edited by E. C. H. Gathman and published in 2016.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["B. D. Earp", "E. C. H. Gathman"], "organizations": ["Kendall Hunt Publishing Company"], "themes": ["Bioethics", "Male Circumcision", "Female Circumcision", "Healthcare Ethics", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5bedfa3e7a7ae8e211e938c13ec3591b47576a970645cfa8f763a492c929b576', 'Earp Bruce Medical necessity and consent JME 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5bedfa3e7a7ae8e211e938c13ec3591b47576a970645cfa8f763a492c929b576.pdf', 'medical_journal', 'ingested', '{"date": "2023-08-30", "description": "This editorial examines the bioethical requirements surrounding healthcare provider interventions involving a patient''s genitalia, spanning surgical procedures such as episiotomies, infant circumcision, and intersex normalisation surgeries, as well as unconsented intimate examinations conducted for educational purposes. Drawing on Talia Mae Bettcher''s philosophical concept of ''intimate agency,'' the authors argue that the moral status of genitalia as intimate anatomy is not erased in medical settings, making non-consensual contact a profound violation of bodily and personal boundaries rather than a mere assessment of physical invasiveness or harm.\n\nThe authors contend that outside rare, genuine medical emergencies involving an incapacitated patient where intervention cannot be safely delayed, ''presumed consent'' is fundamentally illegitimate. They advocate for strict respect for patient consent and genital autonomy across medical practice, calling for systemic reforms across professional guidelines, hospital policies, and medical training.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D Earp", "Lori Bruce", "Talia Mae Bettcher", "Marit van der Pijl"], "organizations": ["University of Oxford", "Yale University", "American Academy of Pediatrics", "BMJ"], "themes": ["Medical Ethics", "Informed Consent", "Intimate Agency", "Bodily Integrity and Genital Autonomy", "Obstetric Interventions", "Unconsented Medical Examinations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bfc4fa833cf79f95b23fffc85e0b0348e6079a8810982a6baffc992a69f94264', 'Earp Childs Right to BodInt-Ethics Contemp World 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bfc4fa833cf79f95b23fffc85e0b0348e6079a8810982a6baffc992a69f94264.pdf', 'other', 'ingested', '{"date": "2019-06", "description": "This academic book chapter examines the ethical foundations of the right to bodily integrity (BI) with a specific focus on pre-autonomous children. The author defines a violation of bodily integrity as any non-consensual physical intrusion, breaking of the skin, or bodily alteration that wrongs an individual. Because children are temporarily non-autonomous and lack the capacity to provide informed consent, bodily interventions must generally be postponed until they mature and can make their own autonomous decisions.\n\nThe author argues that non-consensual infringements on a child''s bodily integrity are morally permissible only when they meet or approach the threshold of ''medical necessity''\u2014interventions required to avert immediate, serious threats to life or well-being where delayed action would cause greater harm. Consequently, irreversible cultural or non-therapeutic modifications (such as infant male circumcision, female genital cutting, and ritual dental or skin alterations) fail this ethical standard because their perceived benefits depend on contestable cultural norms rather than universal health necessities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "David Edmonds"], "organizations": ["University of Oxford", "Routledge", "ResearchGate"], "themes": ["Bodily Integrity", "Child Autonomy and Consent", "Bioethics", "Non-Therapeutic Body Modifications", "Medical Necessity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('71ffeb8b7a7c1700c8743afcc5078a5059aa4d92f9f1fb89dc0413c2e2abde64', 'Earp circumcision_reduce_penis_sensitivity HuffPo 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/71ffeb8b7a7c1700c8743afcc5078a5059aa4d92f9f1fb89dc0413c2e2abde64.pdf', 'newspaper_clipping', 'ingested', '{"date": "2016-04-21", "description": "In this article, ethicist and researcher Brian D. Earp critiques sensationalized and uncritical media coverage surrounding a study by Jennifer Bossio and colleagues regarding male circumcision and penile sensitivity. Earp argues that media headlines claiming circumcision does not reduce sensitivity mischaracterize the study''s actual findings, which demonstrated that the foreskin is significantly more sensitive to fine touch and warmth than other genital sites.\n\nEarp highlights several methodological limitations in the study, including a small, statistically underpowered sample size, the exclusion of older men and those with sexual dysfunction, and the failure to test the highly innervated inner foreskin. Emphasizing anatomical reality and bioethics, Earp contends that removing sensitive genital tissue inherently alters sensory experience and advocates for bodily autonomy, arguing that decisions regarding non-therapeutic circumcision should be deferred until the individual can make an informed choice for himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Brian D. Earp", "Jennifer Bossio", "Nicholas Bakalar"], "organizations": ["The Huffington Post", "Queen''s University", "The New York Times", "The Hastings Center"], "themes": ["Male Circumcision", "Penile Sensitivity", "Science Journalism", "Bioethics and Bodily Autonomy", "Sexual Health and Anatomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('daf2409ece246dc369e1e062a069213a10a7a063b34e53a51e7020744b7b6c61', 'Earp cut_by_any_other_name_Pt1 EC 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/daf2409ece246dc369e1e062a069213a10a7a063b34e53a51e7020744b7b6c61.pdf', 'other', 'ingested', '{"date": "2020-05", "description": "This document appears to be the table of contents and publication masthead for the May 2020 issue of a periodical published by the Out Alliance, an organization advocating for LGBTQ+ life and culture based in Rochester, New York. The issue features articles on LGBTQ+ businesses, Trans Day of Visibility, a comparison of the AIDS crisis and the COVID-19 pandemic, as well as recurring sections including community news, health matters, creative writing, and history.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Out Alliance", "United Way"], "themes": ["LGBTQ+ Community", "COVID-19", "AIDS Crisis", "Transgender Visibility", "Community Health and Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('59e47afc6b254e514f147ef6abd671fce71bbdbeea074bac06285639262b63b6', 'Earp cut_by_any_other_name_Pt2 EC 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/59e47afc6b254e514f147ef6abd671fce71bbdbeea074bac06285639262b63b6.pdf', 'other', 'ingested', '{"date": "2020-06", "description": "This document contains the table of contents and organizational masthead for the June 2020 issue of a publication by The Out Alliance, an LGBTQ+ advocacy group based in Rochester, New York. The issue focuses on community reflections regarding the importance of Pride, a commemorative feature remembering the Pulse nightclub shooting, and regular sections covering local history, creative writing, health, and community news.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Anthony Manley", "Sam Cicero", "Sara Hickman Himes", "Jenny Pugos", "Stacie Houghtaling", "Heather Meu", "Dante Fraguada", "Monica Lynne Blodgett"], "organizations": ["The Out Alliance", "United Way"], "themes": ["LGBTQ+ Pride", "Pulse Nightclub Memorial", "Community Support and Acceptance", "Rochester LGBTQ+ History"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('66aa660d1174d0a20e7068f47e5c2cd33acf52fe7afea68cc0bcc97f510dab57', 'Earp Darby (McMath) Circ, Autonomy Pub Health PubHealthEth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/66aa660d1174d0a20e7068f47e5c2cd33acf52fe7afea68cc0bcc97f510dab57.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article examines the ethical and empirical arguments surrounding the use of nontherapeutic infant male circumcision as a public health initiative, specifically responding to claims that randomized controlled trial (RCT) data from Sub-Saharan Africa regarding adult HIV reduction justify infant circumcision in developed countries. Evaluating counter-arguments and bioethical frameworks\u2014notably those presented by Azim McMath\u2014the authors argue that generalizing adult RCT results to infants in completely different epidemiological environments lacks translational evidence, overlooks socio-behavioral risk factors, and improperly characterizes healthy bodily tissue as an inherent disease risk.\n\nThe authors further contend that paternalistic appeals to public health fail to justify overriding a child''s fundamental interest in bodily integrity and future autonomy. Unlike temporary measures such as quarantine or non-ablative interventions such as vaccinations, infant circumcision permanently and irreversibly removes sensitive, functional erogenous tissue without the individual''s consent. Consequently, they conclude that nontherapeutic circumcision of minors cannot be justified on public health or harm-prevention grounds and that decisions regarding elective genital surgery should be deferred until the child reaches the age of competent consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Robert Darby", "Azim McMath", "Aaron T. Norton", "Nancy Cartwright"], "organizations": ["Yale University", "The Hastings Center", "Oxford University Press", "Bill & Melinda Gates Foundation", "Centers for Disease Control and Prevention", "American Academy of Pediatrics"], "themes": ["Male Circumcision", "Public Health Ethics", "Bodily Integrity", "Pediatric Autonomy", "HIV/AIDS Prevention", "Medical Paternalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('329ede7afcd8aba01ef1b1234a032431fc775acde427da04fd65bc2533b779d3', 'Earp Darby Circ SexExperience Harm UPennJIntLaw 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/329ede7afcd8aba01ef1b1234a032431fc775acde427da04fd65bc2533b779d3.pdf', 'legal_document', 'ingested', '{"date": "2017-04-03", "description": "This article by Brian D. Earp and Robert Darby examines the moral, legal, and psychosexual dimensions of nontherapeutic male circumcision (NTC) in minors, responding to Stephen R. Munzer''s commentary on the 2012 Cologne court decision. The authors argue that empirical medical evidence alone cannot resolve the debate over whether circumcision is beneficial or harmful, as harm is an open-textured, subjective concept heavily influenced by personal values, cultural context, and individual assessments of risk.\n\nThe authors highlight the anatomical significance and erogenous sensitivity of the foreskin, detailing how its non-consensual excision can be legitimately experienced as an intrinsic harm and impairment of sexual function. Given the profound individual variability in outcomes, anatomical differences, and psychosexual preferences, the authors conclude that nontherapeutic genital modifications should generally be deferred until an individual reaches an age of consent, while also pointing out the legal inconsistencies between male and female genital cutting protections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Brian D. Earp", "Robert Darby", "Stephen R. Munzer", "Bijan Fateh-Moghadam", "Joel Feinberg", "Andrew L. Freedman"], "organizations": ["University of Pennsylvania Journal of International Law", "American Academy of Pediatrics", "The Hastings Center", "Yale University", "Landgericht K\u00f6ln"], "themes": ["Nontherapeutic Male Circumcision", "Bodily Integrity and Consent", "Subjective Definition of Harm", "Psychosexual and Sensory Impact", "Legal and Gender Disparities in Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('915da870589335d94f5920336e3ac867829acbe24d4dab35e23e007e15a47b6c', 'Earp Darby Circ_autonomy_PubHlthEth 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/915da870589335d94f5920336e3ac867829acbe24d4dab35e23e007e15a47b6c.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article examines the ethical tensions between public health initiatives and individual autonomy regarding non-therapeutic infant male circumcision, using a paper by Azim McMath as a primary case study. The authors, B. D. Earp and R. Darby, challenge the claim that prospective public health benefits\u2014primarily HIV risk reduction\u2014justify overriding an infant''s future autonomy and right to bodily integrity. They argue that evidence from adult randomized controlled trials in high-prevalence heterosexual transmission areas in Sub-Saharan Africa cannot be unproblematically extrapolated to neonates or different epidemiological settings, such as developed nations.\n\nFurthermore, the authors reject analogies comparing circumcision to vaccination or temporary quarantine, emphasizing that circumcision entails the permanent, irreversible excision of functional, erogenous tissue that individuals may reasonably view as a harm. They critique the conceptual shift that treats a healthy foreskin as an inherent pathology or vector of risk to others. Concluding that the human rights and autonomy costs to the individual far outweigh the asserted societal health benefits, the authors maintain that elective genital alteration should be postponed until the individual reaches an age of competence to give informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["B. D. Earp", "R. Darby", "Azim McMath", "Aaron T. Norton", "Nancy Cartwright"], "organizations": ["Public Health Ethics", "Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Bill & Melinda Gates Foundation"], "themes": ["Male Circumcision", "Bodily Integrity", "Patient Autonomy", "Public Health Ethics", "HIV Prevention", "Paternalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a6ba495e2535f12b272921a20648210188d15883319755cfabe113c839bc2707', 'Earp Darby Does_science_support Skeptic 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a6ba495e2535f12b272921a20648210188d15883319755cfabe113c839bc2707.pdf', 'other', 'ingested', '{"date": "2015", "description": "In this article, Brian D. Earp and Robert Darby present a detailed rebuttal to Brian Morris''s assertion that science unequivocally supports routine infant male circumcision. The authors argue that science alone cannot resolve normative ethical questions and that Morris relies on biased, exaggerated, and contested data to justify non-therapeutic genital surgery. They contend that the conditions circumcision purportedly prevents\u2014such as urinary tract infections and sexually transmitted infections\u2014are either rare, treatable by non-surgical methods, or irrelevant in infancy.\n\nEarp and Darby emphasize the ethical implications of removing functional, healthy tissue from non-consenting minors, contrasting the procedure with vaccination. Drawing on statements from international pediatric associations, bioethicists, and legal rulings, they conclude that routine infant circumcision exposes children to unnecessary surgical harms and violates bodily autonomy and physical integrity, arguing that such permanent bodily decisions should be deferred until the individual can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Robert Darby", "Brian Morris", "Basil Donovan", "Andrew Freedman", "Russell Saunders", "Kevin Pringle", "Margaret Somerville"], "organizations": ["American Academy of Pediatrics", "Royal Dutch Medical Association", "Royal Australasian College of Physicians", "Circumcision Foundation of Australia", "The Gilgal Society", "World Health Organization"], "themes": ["Infant Male Circumcision", "Bioethics and Bodily Integrity", "Informed Consent", "Pediatric Medicine", "Scientific Methodology and Bias"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5bf0998fa2f562c98fda6847464088866c39138ce13ca44eaced3ae25201454c', 'Earp Defense of GA for children JME 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5bf0998fa2f562c98fda6847464088866c39138ce13ca44eaced3ae25201454c.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "In this bioethics commentary, Brian D. Earp responds to a proposal by Kavita Shah Arora and Allan J. Jacobs, who argue that because Western liberal societies tolerate non-therapeutic infant male circumcision, they should also tolerate or encourage ''de minimis'' forms of female genital alteration (FGA). Earp argues that such a compromise solution would cause severe legal, regulatory, medical, psychosexual, and cultural problems, effectively functioning as a reductio ad absurdum.\n\nRather than lowering the standard of protection for female minors to create parity with male circumcision, Earp argues that liberal societies should adopt an autonomy-based ethical framework that discourages or regulates non-therapeutic genital cutting on children of any sex or gender. He concludes that healthy sexual organs should remain intact until an individual reaches the developmental maturity and competence necessary to provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Kavita Shah Arora", "Allan J. Jacobs", "Ayaan Hirsi Ali", "Soraya Mire", "Robert S. Van Howe", "Sara Johnsdotter"], "organizations": ["The Hastings Center Bioethics Research Institute", "World Health Organization", "American Academy of Pediatrics", "American Congress of Obstetricians and Gynecologists", "Canadian Paediatric Society", "Equality Now"], "themes": ["Genital autonomy", "Pediatric ethics", "Bodily integrity", "Female genital alteration (FGA)", "Non-therapeutic infant male circumcision", "Informed consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5d1ee8a7249edfd81d1e09dd25288d608368b2bc1e869ba666094ae68a1f5bc7', 'Earp DeLaet Which Children Have Rights AmicusCuriae 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5d1ee8a7249edfd81d1e09dd25288d608368b2bc1e869ba666094ae68a1f5bc7.pdf', 'legal_document', 'ingested', '{"date": "2024-07-04", "description": "This article examines the significant legal and normative gaps in protecting the rights of children with intersex traits against medically unnecessary, non-voluntary medicalized interventions. Although various United Nations bodies, treaty-monitoring committees, and human rights frameworks (such as the Yogyakarta Principles plus 10) increasingly affirm that intersex minors have rights to bodily integrity and future autonomy, these global norms remain largely uncodified in binding international treaties.\n\nAt the national level, approximately 94 percent of UN member states lack adequate legal measures to protect intersex children, with only a handful of countries\u2014such as Greece, Malta, Germany, Iceland, Portugal, and Spain\u2014passing explicit prohibitions or regulatory frameworks. The authors argue that this widespread failure of legal protection and enforcement stems from deeply entrenched sociopolitical and medical adherence to the binary gender model, parental and clinical deference, and broad resistance to SOGIESC rights, highlighting the urgent need for multifaceted legislative, educational, and cultural reforms.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Debra L. DeLaet", "Brian D. Earp", "Elizabeth Mills", "Juan E. M\u00e9ndez", "Tlaleng Mofokeng", "Dainius P\u016bras", "Anand Grover"], "organizations": ["Drake University", "University of Oxford", "University of Sussex", "United Nations", "ILGA World", "Human Rights Council", "Office of the High Commissioner for Human Rights", "World Health Organization", "Committee on the Rights of the Child", "Committee on the Elimination of Discrimination Against Women", "Committee on the Rights of Persons with Disabilities"], "themes": ["Intersex Rights", "Bodily Integrity", "Children''s Rights", "Non-voluntary Medical Interventions", "International Human Rights Law", "Gender Binary", "SOGIESC Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8549a2b3b8b9f12bb6a888a3c4f12fb575dbcdcd5ff34c220555e6f3bd4d7da5', 'Earp Do_benefits_outweigh risks CDC FrontPeds 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8549a2b3b8b9f12bb6a888a3c4f12fb575dbcdcd5ff34c220555e6f3bd4d7da5.pdf', 'medical_journal', 'ingested', '{"date": "2015-03-18", "description": "In this perspective article, Brian D. Earp critically examines proposed guidelines from the Centers for Disease Control and Prevention (CDC) asserting that the health benefits of male circumcision outweigh its risks. Earp argues that the CDC''s recommendations rely heavily on clinical trials from sub-Saharan Africa that cannot be validly translated to North American populations or infant circumcisions, given differences in epidemiological environments and HIV transmission dynamics. Furthermore, he contends that the CDC applies an inadequate conception of risk by narrowly focusing on immediate surgical complications while failing to account for the inherent harm of losing functional, erogenous penile tissue and disregarding potential long-term adverse sexual and physical outcomes.\n\nEarp also critiques the CDC for presenting benefits in terms of relative risk reductions alongside harms described as absolute risks, a disparity that inflates perceived benefits and undermines informed consent. Emphasizing bioethical principles of bodily integrity, autonomy, and proportionality\u2014drawing comparisons to ethical and legal stances against non-therapeutic female genital modification\u2014he concludes that prophylactic infant circumcision is not an ethically sound health-promotion strategy and that the decision should be deferred until the individual can provide consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Frederick Robert Carrick", "Marie Fox", "Eike-Henner Kluge", "Sandra Hassink", "Brian J. Morris"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "University of Oxford", "Frontiers in Pediatrics"], "themes": ["Male Circumcision", "Bioethics and Bodily Integrity", "Informed Consent", "Benefit vs. Risk Analysis", "Public Health Policy", "HIV and STI Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1b847231bf1462660e313d82de313078e20348ef49a04a8cd35c4e31df3de562', 'Earp Early Circ Deaths ClinPeds 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1b847231bf1462660e313d82de313078e20348ef49a04a8cd35c4e31df3de562.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This study analyzes the frequency of early, in-hospital deaths associated with neonatal male circumcision in the United States between 2001 and 2010 using the Nationwide Inpatient Sample (NIS). Examining 9,833,110 newborn males circumcised during their index hospitalization, the researchers identified 200 in-hospital deaths, equivalent to approximately 1 death per 49,166 circumcisions (10.2 deaths per 500,000). The authors emphasize that this correlation does not prove direct causation, as the dataset excludes outpatient/post-discharge deaths while potentially including deaths driven by unrelated underlying fatal conditions.\n\nThe findings reveal that infants who died following circumcision had substantially higher odds of comorbid conditions, including cardiovascular disease, coagulopathies, fluid and electrolyte disorders, and pulmonary circulatory disorders. Given these severe correlations and because circumcision is typically a non-therapeutic procedure on healthy newborns, the authors suggest that such comorbidities should be considered potential contraindications and recommend careful evaluation before performing neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Veerajalandhar Allareddy", "Veerasathpurush Allareddy", "Alexandre T. Rotta"], "organizations": ["Yale University", "The Hastings Center", "Stead Family Children\u2019s Hospital", "University of Iowa", "University of Illinois at Chicago", "UH Rainbow Babies & Children\u2019s Hospital", "Case Western Reserve University", "Agency for Healthcare Research and Quality", "American Academy of Pediatrics"], "themes": ["Neonatal Male Circumcision", "Infant Mortality and Complications", "Comorbid Conditions and Contraindications", "Healthcare Disparities and Inpatient Hospitalization Data", "Pediatric Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7f74945619c79c08a457f26643a8daefe5d42fb4d73afeb16b1dd4e279e4181e', 'Earp Ethics of Infant Male Circ JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7f74945619c79c08a457f26643a8daefe5d42fb4d73afeb16b1dd4e279e4181e.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This editorial addresses the ethical, legal, and cultural controversies surrounding non-therapeutic infant male circumcision, prompted by the American Academy of Pediatrics'' (AAP) 2012 policy statement asserting that the health benefits of the procedure outweigh its risks. The author highlights significant international medical and ethical pushback against the AAP''s findings, shifting the central inquiry toward the fundamental tension between ancient cultural/religious traditions and modern secular ethics grounded in bodily integrity, autonomy, and a child''s right to an open future.\n\nWhile recognizing that an immediate total prohibition could lead to adverse outcomes like unregulated black-market procedures, the author criticizes the cultural double standard that completely outlaws female genital cutting while leaving male circumcision largely unregulated. The piece argues that growing skepticism within both legal scholarship and religious communities\u2014evidenced by emerging symbolic alternatives such as the Jewish ''brit shalom'' ceremony\u2014signals a shifting moral landscape that warrants continued dialogue, harm reduction, and incremental reform.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D Earp", "J Steven Svoboda", "Robert Van Howe", "Hanoch Ben Yami", "Anders Sandberg", "Julian Savulescu", "Joseph Mazor", "Dena Davis", "Matthew Johnson"], "organizations": ["American Academy of Pediatrics", "Oxford Uehiro Centre for Practical Ethics", "Jews Against Circumcision"], "themes": ["Infant Male Circumcision", "Medical Ethics", "Bodily Integrity and Autonomy", "Children''s Rights", "Religious Freedom vs. Child Protection", "Harm Reduction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('62bd09bf64fe6f9bb310a8a5a60b003c10a03daed294efb2ddeed75feb21b49b', 'Earp ethics_of_circumcision RowmanHandbk2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/62bd09bf64fe6f9bb310a8a5a60b003c10a03daed294efb2ddeed75feb21b49b.pdf', 'other', 'ingested', '{"date": "2022", "description": "In this bioethics book chapter, Brian D. Earp argues against the practice of medically unnecessary, non-consensual genital cutting performed on children, including penile circumcision, female genital alterations, and intersex genital normalization surgeries. Examining three dominant global patterns of child genital cutting, Earp advocates for the standard prevailing across Europe, wherein children''s genitals are left physically intact until they reach an age where they can provide their own informed consent. He critiques the prevailing utilitarian calculus of ''weighing harms and benefits'' and appeals to parental discretion, asserting that subjective values, future identity changes, and non-surgical alternatives render such proxy justifications morally invalid.\n\nEarp establishes that the only ethical exception to non-consensual interventions into a child''s sexual anatomy is strict medical necessity\u2014defined as an immediate, time-sensitive somatic threat where non-intervention would result in death or severe disability. Surgeries that are merely ''medically beneficial,'' cosmetic, or culturally and religiously motivated fail this high threshold. Ultimately, Earp frames non-therapeutic infant circumcision as an ethically indefensible violation of bodily integrity and sexual autonomy, calling for children of all sexes and gender identities to be granted equal moral protection from non-consensual genital modifications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Ezio Di Nucci", "Ji-Young Lee", "Isaac Wagner"], "organizations": ["University of Oxford", "Rowman & Littlefield", "American Academy of Pediatrics", "Canadian Paediatric Society", "Danish Medical Association", "Centers for Disease Control and Prevention", "World Health Organization"], "themes": ["Ethics of circumcision", "Bodily integrity and sexual autonomy", "Informed and proxy consent", "Medical necessity vs. medical benefit", "Intersex surgery and gender equality", "Bioethics and cultural relativism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1473f1ba658c42f28e0567a4dcd2ac44efa98ab2053e41ca179ae63ba10ea05a', 'Earp Female_male_separate discourse PractEth 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1473f1ba658c42f28e0567a4dcd2ac44efa98ab2053e41ca179ae63ba10ea05a.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This academic bioethics article challenges the conventional separation of ethical discourses concerning female genital mutilation (FGM) and male circumcision. The author argues that popular distinctions\u2014framing FGM as exclusively catastrophic and male circumcision as benign, medically beneficial, or culturally inconsequential\u2014rely on empirical inaccuracies, cultural familiarity, and ethnocentric double standards. In reality, both female and male genital cutting span a wide spectrum of anatomical severity, procedural risks, and cultural justifications.\n\nThe author asserts that evaluating genital cutting based on claimed health benefits or cultural intentions is morally inadequate. Instead, ethical considerations should center on bodily integrity, individual autonomy, and informed consent. Consequently, non-therapeutic, non-consensual genital modifications on all children\u2014regardless of whether they are female, male, or intersex\u2014should be deemed ethically impermissible until the individual can decide for themselves.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Margaret Somerville", "Kirsten Bell", "Tanya Gold", "Zachary Androus", "Nancy Ehrenreich", "Dustin Wax", "Nelson Mandela", "Sara Johnsdotter", "Rebecca Steinfeld", "Andrew DeLaney", "Hanny Lightfoot-Klein"], "organizations": ["University of Oxford", "World Health Organization", "Hastings Center"], "themes": ["Bioethics", "Male Circumcision", "Female Genital Cutting (FGC)", "Bodily Integrity", "Informed Consent", "Children''s Rights", "Ethnocentrism and Cultural Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d224206b9ad0a12d8baa2e6d43fbf33078509b80e5f16a59525119009e1dab05', 'Earp FGM_health benefits Pract Eth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d224206b9ad0a12d8baa2e6d43fbf33078509b80e5f16a59525119009e1dab05.pdf', 'other', 'ingested', '{"date": "2017", "description": "In this essay, Brian D. Earp examines the indictment of Detroit members of the Dawoodi Bohra Muslim sect for performing a ''ritual nick'' on young girls, using the landmark case to critique the ethical and legal double standards surrounding childhood genital cutting. Earp argues that contemporary public health discourse, particularly from organizations like the World Health Organization, improperly reduces fundamental moral questions to health benefit-risk calculations. This medicalization creates an inconsistent paradigm where male circumcision is promoted or legally permitted based on contested health benefits, while female procedures\u2014even minor and less invasive ones\u2014are categorically criminalized without consistent moral justification.\n\nEarp cautions that relying on the presence or absence of health benefits to condemn or permit genital modifications incentivizes proponents of female genital cutting to search for medical justifications. Ultimately, he argues that the moral debate must shift away from false dichotomies of gender, religion versus culture, and health metrics, focusing instead on bodily integrity, children''s rights, and informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Julian Savulescu", "Dena Davis", "Andrew Freedman", "Robert Darby", "Kirsten Bell", "Fuambai Ahmadu"], "organizations": ["Yale University", "University of Oxford", "World Health Organization", "American Academy of Pediatrics", "Dawoodi Bohra"], "themes": ["Female Genital Mutilation (FGM)", "Male Circumcision", "Bodily Autonomy and Consent", "Medicalization of Morality", "Religious Freedom and Children''s Rights", "Bioethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d2fad50fac66c73368c8afcf28bb66f96d6177037bad2465f1fb90412ccbc46c', 'Earp Frisch VanHowe AnesthCircADHD Anesth Analg 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d2fad50fac66c73368c8afcf28bb66f96d6177037bad2465f1fb90412ccbc46c.pdf', 'medical_journal', 'ingested', '{"date": "2020-10-27", "description": "This commentary responds to research by Ing et al. investigating the association between early-life surgery under general anesthesia and the subsequent risk of attention deficit hyperactivity disorder (ADHD) in young children. While acknowledging the value of the original studies, the authors point out a key methodological concern: neonatally circumcised boys were categorized as ''unexposed'' controls, which may have biased hazard ratios downward for males due to the trauma of neonatal surgery without general anesthesia.\n\nThe authors recommend re-running the analyses with neonatally circumcised boys excluded from the unexposed reference group. Furthermore, they propose a comparative analysis between boys who underwent postneonatal circumcision (typically under general anesthesia) and those circumcised during the neonatal period (typically without general anesthesia) to better determine whether the heightened ADHD risk is driven by surgical trauma, anesthesia exposure, or a combination of both.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Brian D. Earp", "Robert S. Van Howe", "C. Ing"], "organizations": ["Statens Serum Institut", "Aalborg University", "Yale University", "The Hastings Center", "University of Oxford", "Michigan State University", "Central Michigan University"], "themes": ["Early-Life Surgery", "General Anesthesia", "Attention Deficit Hyperactivity Disorder (ADHD)", "Neonatal Circumcision", "Epidemiological Methodology", "Pediatric Neurodevelopment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3b76ddabede91f7141ace05ca43f1509981684463a93f6d142b24f64b71e6c72', 'Earp Genital_cutting_gender_oppress WHO_FrontHumDyn 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3b76ddabede91f7141ace05ca43f1509981684463a93f6d142b24f64b71e6c72.pdf', 'medical_journal', 'ingested', '{"date": "2022-06-10", "description": "This article critiques the World Health Organization''s (WHO) categorical condemnation of non-Western female genital cutting (FGC) alongside its tolerance or promotion of male genital cutting (MGC) and silence on intersex genital cutting (IGC) and Western cosmetic genital surgeries. Author Brian D. Earp argues that appeals to differing health outcomes or surgical harms fail to justify this asymmetry, noting that traditional male circumcision carries severe health risks and high complication rates, while certain forms of female cutting are less invasive than standard penile circumcision.\n\nFurthermore, the paper refutes the justification that FGC uniquely upholds patriarchal oppression and sex-based discrimination. Earp demonstrates that ritual MGC plays an integral role in socializing boys into hegemonic, female-subordinating masculinity and enforcing strict gender hierarchies. Because child genital modification rites are interdependent and mutually reinforcing, the author concludes that eradicating gender oppression and protecting children''s right to bodily integrity requires a principled, gender-neutral approach that opposes all medically unnecessary, non-consensual genital cutting of minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Nahid Toubia", "Efua Dorkenoo", "Seham Abd el Salam", "Tatu Kamau", "Camilla Power"], "organizations": ["World Health Organization", "University of Oxford", "Yale University", "The Hastings Center"], "themes": ["Female Genital Cutting (FGC)", "Male Genital Cutting (MGC)", "Intersex Genital Cutting (IGC)", "Bodily Integrity", "Children''s Rights", "Patriarchy and Gender Oppression", "Medicalization", "Cultural Imperialism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8d6cddfca013e92314ad99fbcc78da23235bb037a2056c14c9bb5fdf7e57a2a5', 'Earp Johnsdotter Current_critiques_of_WHO_FGM IJIR 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8d6cddfca013e92314ad99fbcc78da23235bb037a2056c14c9bb5fdf7e57a2a5.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This review article by Brian D. Earp and Sara Johnsdotter critically evaluates the World Health Organization''s (WHO) policy and dominant Western discourse regarding female genital mutilation (FGM), also referred to as female genital cutting (FGC). The authors argue that the WHO''s zero-tolerance stance\u2014which categorically bans all non-Western female genital cutting regardless of severity, consent, or context\u2014is ethically incoherent, empirically unsupportable, and legally unsustainable. They demonstrate that the monolithic label of ''mutilation'' conflates diverse practices, misrepresents parental motivations, relies on inaccurate anatomical and medical assumptions, and often causes psychological stigmatization and harm to affected women.\n\nFurthermore, the paper highlights how existing anti-FGM frameworks exhibit cultural and gender bias by selectively condemning non-Western female practices while tolerating or endorsing medically unnecessary procedures on males, intersex individuals, and Western women seeking cosmetic genital surgeries. Challenging the premise that FGC is solely an instrument of patriarchal oppression, the authors show that such practices often parallel male rites of passage and carry complex cultural meanings. They advocate for a consistent, non-discriminatory ethicolegal framework centered on individual informed consent and bodily integrity across all sexes and genders.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Sara Johnsdotter"], "organizations": ["World Health Organization", "Yale University", "The Hastings Center", "Malm\u00f6 University", "Brussels Collaboration on Bodily Integrity", "Springer Nature"], "themes": ["Female Genital Mutilation (FGM)", "Female Genital Cutting (FGC)", "Male Circumcision", "Bodily Integrity and Autonomy", "Bioethics and Health Policy", "Cultural Imperialism vs. Human Rights", "Gender Discrimination and Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('adcc2a71d8a5c4d300eaf5002ba81a9e31e4009dbd8106d9d18823d9d2b1e529', 'Earp Medicalised_Global-North-and-South-BMJ-2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/adcc2a71d8a5c4d300eaf5002ba81a9e31e4009dbd8106d9d18823d9d2b1e529.pdf', 'letter', 'ingested', '{"date": "2023-02-14", "description": "In this response to Kimani et al., Brian D. Earp argues that selective Western opposition to female genital cutting (FGC) in the Global South creates an inconsistent double standard, given the widespread medicalisation of non-therapeutic genital procedures in the Global North\u2014including cosmetic labiaplasty, intersex ''normalisation,'' and routine infant male circumcision. Earp asserts that framing only Southern practices on females as human rights violations invites accusations of cultural imperialism and weakens global human rights advocacy.\n\nEarp further contends that because male and female genital modifications frequently co-evolve as culturally paired rites of passage, Western-backed campaigns that promote medicalised male circumcision (such as for HIV prevention) inadvertently drive demand for the medicalisation of FGC. Parents observing harm-reduction measures for boys naturally seek similar surgical protections against infection and hemorrhage for their daughters. To resolve these contradictions, Earp proposes a unified ethical framework that opposes all medically unnecessary, non-voluntary genital cutting of minors regardless of sex or geography.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Brian D. Earp", "Tatu Kamau", "S. Kimani"], "organizations": ["University of Oxford", "Uehiro Centre for Practical Ethics", "World Health Organization", "BMJ"], "themes": ["Medicalisation of Genital Cutting", "Female Genital Mutilation/Cutting (FGM/C)", "Male Circumcision", "Bioethics and Human Rights", "Cultural Imperialism and Moral Consistency", "Bodily Integrity and Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('12ec9dfaa485187cf5e5be1a8b6b141bc6cd3a24bda33365c30766e5ad82a9fb', 'Earp MGC-FGC ''Health Benefits'' Irrelevant JME 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/12ec9dfaa485187cf5e5be1a8b6b141bc6cd3a24bda33365c30766e5ad82a9fb.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "In this extended essay, Brian D. Earp argues that appeals to potential ''health benefits'' cannot morally justify the disparate treatment between male and female child genital cutting practices. While Western medical authorities such as the World Health Organization (WHO) and the American Academy of Pediatrics (AAP) strictly condemn all medically unnecessary female genital cutting as an inviolable human rights violation, they frequently permit or endorse male circumcision by appealing to modest or statistical health advantages, such as reduced risk of urinary tract infections.\n\nEarp contends that this stance represents an indefensible double standard and that potential or non-urgent health benefits fail to satisfy the criterion of ''medical necessity'' required to override a non-consenting minor''s bodily integrity. He concludes that children of all sexes and genders possess an equal right to future bodily autonomy, meaning non-therapeutic, permanent alterations to healthy genital tissue should be deferred until the individual reaches sufficient maturity to provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D Earp", "Melinda Jones", "Debra DeLaet", "Sara Johnsdotter", "Kai M\u00f6ller", "Andrew Freedman", "Robert Darby", "Eike-Henner Kluge", "Dan Kahan"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "The Hastings Center", "Yale University", "The Brussels Collaboration on Bodily Integrity", "BMJ"], "themes": ["Bodily Integrity", "Male Circumcision", "Female Genital Cutting", "Medical Ethics", "Children''s Rights", "Informed Consent", "Gender and Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5cb461ea95ccb21bb42fa6a763fb7c1375abf969c972cffe80f46c6e9595683c', 'Earp Mohamed Clitoral_reconstr JSexMed 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5cb461ea95ccb21bb42fa6a763fb7c1375abf969c972cffe80f46c6e9595683c.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This academic paper presents a comprehensive review of surgical techniques and an initial ethical analysis of clitoral reconstruction (CR) following female genital mutilation/cutting (FGM/C). While CR is increasingly sought to reduce pain, improve sexual function, and restore genital appearance, the authors emphasize that high-quality clinical evidence supporting these outcomes is largely lacking, and the surgery carries notable risks including wound complications, dyspareunia, and worsened pain. Furthermore, the paper highlights widespread anatomical misconceptions, noting that FGM/C typically affects only the external glans and prepuce rather than removing the entire clitoris, meaning CR exposes existing buried tissue rather than restoring an entirely missing organ.\n\nThe authors conclude that CR is medically indicated primarily for treating localized pain and neuromas when conservative therapies have failed. In non-pain cases, CR functions largely as a psychosocial intervention where informed consent must be critically evaluated. Clinicians must educate patients on clitoral anatomy, address underlying trauma and psychosexual factors, avoid reinforcing stigmatizing narratives that equate FGM/C with total sexual dysfunction, and prioritize non-surgical psychosexual therapies before considering invasive procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Fatima Sharif Mohamed", "Verina Wild", "Brian D. Earp", "Crista Johnson-Agbakwu", "Jasmine Abdulcadir", "Pierre Fold\u00e8s"], "organizations": ["World Health Organization", "UNICEF", "Royal College of Obstetricians and Gynecologists", "Geneva University Hospitals", "University of Geneva", "Ludwig-Maximilians-University Munich", "Yale University", "The Hastings Center", "Arizona State University", "Maricopa Integrated Health System", "Clitoraid"], "themes": ["Clitoral Reconstruction", "Female Genital Mutilation/Cutting (FGM/C)", "Bioethics and Informed Consent", "Psychosexual Therapy", "Patient Autonomy and Stigma", "Surgical Outcomes and Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7215a0594a861a29c40e8dc46e9f9c3d2ef4f5a08e68c31befb5ae576cb2af7a', 'Earp Morris ''rigged'' systematic reviews 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7215a0594a861a29c40e8dc46e9f9c3d2ef4f5a08e68c31befb5ae576cb2af7a.pdf', 'other', 'ingested', '{"date": "2018", "description": "This document consists of 17 largely blank pages containing only page numbering and a header reference to an archived web thread hosted on Thread Reader App dating from 2018. Due to the lack of body text, no substantive content or arguments are present.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Thread Reader App"], "themes": ["Archived Web Content", "Social Media"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('838c1ec65ddb1d0c3193b0f8a15bf9ba6bcf4ab9a809a358c0b8a0036c9cd057', 'Earp Mutilated vs Enhancement PractEthics 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/838c1ec65ddb1d0c3193b0f8a15bf9ba6bcf4ab9a809a358c0b8a0036c9cd057.pdf', 'other', 'ingested', '{"date": "2019-12-24", "description": "In this article, bioethicist Brian D. Earp argues against the categorical use of the term ''mutilation'' (as in female genital mutilation, or FGM) to describe all forms of non-therapeutic genital alterations. Drawing on personal testimonies, anthropological literature, and ethical principles, Earp asserts that the term is inherently evaluative, paternalistic, and stigmatizing, often inflicting psychological harm and shame on the very individuals intended to be protected. He contends that many affected individuals view their bodies through cultural, aesthetic, or religious lenses rather than as disfigured, and that individuals should retain the autonomy to interpret their own bodies without externally imposed labels.\n\nEarp further argues that ethical opposition to medically unnecessary genital alterations should not hinge on contestable empirical claims regarding physical harm or disfigurement, but rather on a fundamental rights-based framework centered on bodily autonomy and informed consent. By distinguishing moral wrongfulness from harmfulness, he maintains that non-consensual genital cutting performed on children\u2014regardless of sex or gender, whether female, male, or intersex\u2014is intrinsically wrong because it violates bodily integrity without medical necessity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "David Archard", "Kai M\u00f6ller"], "organizations": ["University of Oxford", "World Health Organization", "Inter-African Committee on Traditional Practices Affecting the Health of Women and Children", "Brussels Collaboration on Bodily Integrity"], "themes": ["Genital Autonomy and Bodily Integrity", "Bioethics and Medical Necessity", "Language, Stigma, and Labeling Theory", "Informed Consent and Children''s Rights", "Female Genital Cutting (FGC)", "Paternalism and Cultural Relativism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('27ec72170eb285ff5ca12856b294be311e00ae0eb70f92ed7c03bf6fe196c652', 'Earp Need Unified Ethical Stance NursEthics 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/27ec72170eb285ff5ca12856b294be311e00ae0eb70f92ed7c03bf6fe196c652.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This paper argues that Western healthcare organizations and international bodies like the World Health Organization (WHO) maintain inconsistent, culturally biased double standards regarding medically unnecessary child genital cutting. While non-Western female genital cutting is categorically condemned as a human rights violation regardless of invasiveness or perceived cultural value, Western practices such as infant male circumcision and intersex ''normalization'' surgeries are routinely tolerated or justified through appeals to contested physical or psychosocial health benefits.\n\nThe authors demonstrate that appeals to ''health benefits'' create ethical loopholes and misapply the definition of health, as similar psychosocial arguments could theoretically be applied to normative female cutting traditions. Emphasizing a rights-based framework, the authors conclude that Western medical institutions and nursing professionals must adopt a unified ethical standard grounded in bodily integrity, which holds that all medically unnecessary, non-consensual genital modifications performed on minors are morally impermissible.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D Earp", "Arianne Shahvisi", "Samuel Reis-Dennis", "Elizabeth Reis", "Nancy Ehrenreich", "Mark Barr", "Kai M\u00f6ller"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "American College of Nurse-Midwives", "American Society for Pain Management Nursing", "Yale University", "The Hastings Center", "Brighton and Sussex Medical School", "Albany Medical College", "The City University of New York"], "themes": ["Child Genital Cutting", "Bodily Integrity and Autonomy", "Pediatric Informed Consent", "Intersex Genital Surgeries", "Female Genital Mutilation/Cutting (FGM/FGC)", "Male Circumcision", "Bioethics and Cultural Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ab7ce340e7136991efb1ebe7980cf0a84aecc32f2eb2d3bd49322a0940229df', 'Earp need_control_for_socially_desirable PloSONE 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ab7ce340e7136991efb1ebe7980cf0a84aecc32f2eb2d3bd49322a0940229df.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This commentary by Brian D. Earp critiques a study by Feldblum et al. (2015) concerning the longer-term outcomes of voluntary medical male circumcision (VMMC) in Kenya using the ShangRing device. Earp argues that the reported positive outcomes\u2014such as enhanced sexual pleasure, absence of complications, and high cosmetic satisfaction\u2014are likely confounded by methodological flaws, including selection bias, the use of leading questions, reliance on non-independent interviewers, and a lack of control for socially desirable responding (SDR) and experimenter demand effects.\n\nFurthermore, Earp highlights evidence within the study indicating behavioral risk compensation among participants, characterized by decreased condom use and an increase in sexual partners, which the original authors failed to properly emphasize. He outlines six recommendations for future research, including the use of validated quantitative measurement scales, independent ethnographic researchers, objective physiological assessments, and rigorous long-term follow-ups to accurately gauge the sexual and behavioral consequences of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "P. J. Feldblum", "B. J. Morris", "J. N. Krieger", "M. Frisch"], "organizations": ["University of Oxford", "Bill and Melinda Gates Foundation"], "themes": ["Male Circumcision", "Socially Desirable Responding", "Sexual Function and Sensation", "Risk Compensation", "HIV Prevention", "Research Methodology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ba6710b02303831eaeeb3d5a14fed500b8a379a636fbc01b29781ceb11d55f2d', 'Earp Penile Sensitivity TrendsUrolMensHlth 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ba6710b02303831eaeeb3d5a14fed500b8a379a636fbc01b29781ceb11d55f2d.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "In this commentary, Brian D. Earp critiques a 2016 study by Bossio et al. and its subsequent widespread media coverage, which claimed that neonatal male circumcision has minimal long-term implications for adult penile sensitivity. Earp argues that this conclusion contradicts the study''s own empirical data, which demonstrated that the foreskin is significantly more sensitive to touch and warmth than other areas of the penis. Because circumcision excises this sensitive and mobile tissue, Earp asserts that the procedure inherently reduces overall penile sensitivity.\n\nEarp identifies several critical methodological flaws in the study, including a small sample size, the exclusion of older men and those with sexual dysfunction, and the reliance on static sensory tests on flaccid tissue, which fail to reflect dynamic real-world sexual intercourse. He further argues that quantitative sensory testing overlooks subjective psychological frameworks and individual variations in sexual satisfaction. Concluding from an ethical standpoint, Earp advocates for a precautionary approach that avoids non-therapeutic infant circumcision, deferring the choice until an individual can make an informed decision for himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Jennifer A. Bossio", "Caroline F. Pukall", "Stephen Steele", "M. L. Sorrells", "Sara Johnsdotter"], "organizations": ["The Hastings Center Bioethics Research Institute", "Queen''s University"], "themes": ["Male Circumcision", "Penile Sensitivity", "Sexual Health and Dysfunction", "Medical Ethics and Genital Autonomy", "Scientific Methodology and Media Misrepresentation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('67fa84df2c8e0ed78f01d56db167a7f04f925a54b70a8df11bec5be41016cc12', 'Earp Policing_gender IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/67fa84df2c8e0ed78f01d56db167a7f04f925a54b70a8df11bec5be41016cc12.pdf', 'other', 'ingested', '{"date": "2022-09-20", "description": "In this bioethics commentary, Brian D. Earp examines the inconsistency between legislative bans on gender-affirming healthcare for transgender youth\u2014such as Ohio''s SAFE Act and Alabama''s statutes\u2014and the widespread legal acceptance of medically unnecessary, non-consensual genital modifications on infants and minors. Earp points out that while conservative lawmakers claim to protect children by banning puberty blockers and hormone treatments, they simultaneously permit irreversible, non-voluntary surgeries on infants with intersex traits, hypospadias repairs, adolescent cosmetic labiaplasties, and routine infant male circumcisions.\n\nEarp argues that these double standards reflect an effort to police and preserve rigid sex and gender binaries rather than a consistent ethical commitment to bodily integrity. He proposes that all genital and gender-related interventions should be evaluated under a unified moral and legal framework centered on physical medical necessity and valid, informed consent\u2014protecting non-consenting minors from elective alterations while respecting the developing autonomy of mature adolescents.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Melinda Jones", "Jumana Nagarwala", "Donald Trump"], "organizations": ["University of Oxford", "Yale University", "The Hastings Center", "World Health Organization", "American Medical Association", "American Academy of Pediatrics", "American Psychiatric Association", "World Professional Association for Transgender Health"], "themes": ["Gender-Affirming Healthcare", "Bodily Integrity and Genital Autonomy", "Bioethics", "Informed Consent", "Intersex Rights", "Female Genital Mutilation (FGM)", "Male Circumcision", "Transgender Rights and Legislation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ce325b6a2be8a3dc753005d799c99debbaee9a90e93ebbda47fdf2a1382ce8d4', 'Earp Protecting_children_without stigma ArchSexBeh 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ce325b6a2be8a3dc753005d799c99debbaee9a90e93ebbda47fdf2a1382ce8d4.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This paper examines how prevailing Western academic, activist, and policy discourses surrounding female genital cutting (FGC) risk stigmatizing affected women''s bodies and inadvertently compounding psychosexual harms. Integrating the fear-avoidance model and biopsychosocial frameworks of pain, the author illustrates that pain and sexual functioning are mediated by threat interpretation, culturally learned sensation schemas, and social emotions such as shame. Consequently, dogmatic claims that all forms of FGC inherently destroy sexual function can worsen sexual pain and distress through maladaptive expectancy effects and healthcare provider biases.\n\nTo address this dilemma, the author proposes shifting the moral and legal argument against medically unnecessary genital cutting from an empirical harm-based approach to a rights-based framework centered on bodily integrity and informed consent. Grounding opposition in the intrinsic wrongfulness of non-consensual bodily modification protects all children from unnecessary genital alterations while validating diverse lived experiences, supporting psychosexual resilience, and avoiding the stigmatization of individuals who have already undergone cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Sara Johnsdotter", "J. J. Connor"], "organizations": ["Yale University", "World Health Organization", "Brussels Collaboration on Bodily Integrity"], "themes": ["Female Genital Cutting (FGC)", "Bodily Integrity", "Sexual Pain and Pleasure", "Stigmatization", "Children''s Rights", "Biopsychosocial Model of Pain", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('93192dcf8d411aff8a28a1a1910d49def242a15a93bcc66931d8b11293c3cc89', 'Earp Psychosocial_genital_surgeries_in_minor Alden 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/93192dcf8d411aff8a28a1a1910d49def242a15a93bcc66931d8b11293c3cc89.pdf', 'other', 'ingested', '{"date": "2013-03-26", "description": "This document is a transcript of an academic lecture delivered by Brian D. Earp examining the ethical and evidentiary dimensions of performing ''psychosocial'' genital surgeries on minors, such as male circumcision, female genital cutting, and intersex normalizing procedures. Earp distinguishes these interventions from uncontroversial surgeries that are either voluntarily consented to by competent adults or strictly necessary to avert imminent physical death or severe disability. He argues that performing irreversible surgeries on non-consenting children to satisfy cultural aesthetics or prevent hypothetical social stigma carries significant ethical asymmetry, as children harmed or dissatisfied by such interventions cannot restore their bodies in adulthood.\n\nFurthermore, the lecture underscores a critical deficit in empirical evidence supporting early surgical intervention over psychosocial support or deferred surgery. Earp challenges the medical and bioethical community to interrogate prevailing assumptions of benefit, highlighting the risks of nerve damage, loss of sexual sensation, and violations of autonomy, while advocating for non-surgical psychosocial alternatives and robust follow-up methodologies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "J. Abdulcadir", "L-M. Liao"], "organizations": ["University of Oxford", "Alden March Bioethics Institute", "Albany Medical College"], "themes": ["Bioethics", "Pediatric Genital Modification", "Informed Consent", "Medical Necessity", "Bodily Autonomy", "Intersex Rights", "Evidence-Based Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cbd9500330739a9d41b4528e7a5b6947951350e4f8ba81b0a6c372d9dd6decd8', 'Earp Rotta_circumcision_techniques AmFamPhys 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cbd9500330739a9d41b4528e7a5b6947951350e4f8ba81b0a6c372d9dd6decd8.pdf', 'letter', 'ingested', '{"date": "2020", "description": "This letter to the editor responds to an article by Omole and colleagues on newborn penile circumcision techniques. While acknowledging the technical accuracy of the original article, the authors argue that the purported health benefits\u2014such as reductions in UTIs, penile cancer, phimosis, and HIV transmission\u2014are overstated, contextually misapplied, or address conditions that can be treated with less invasive means.\n\nFrom an ethical and legal standpoint, the authors contend that routine neonatal circumcision removes healthy, functional, and erogenous tissue without urgent medical necessity or the patient''s informed consent. Drawing analogies to female genital procedures and highlighting evolving legal and bioethical standards, they conclude that non-therapeutic genital cutting on non-autonomous minors violates the right to bodily integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Brian D. Earp", "Ranit Mishori", "Alexandre T. Rotta", "F. Omole"], "organizations": ["Yale University", "The Hastings Center", "Georgetown University School of Medicine", "Duke University School of Medicine", "Brussels Collaboration on Bodily Integrity"], "themes": ["Neonatal Circumcision", "Medical Ethics", "Bodily Integrity", "Informed Consent", "Anatomy of the Prepuce", "Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('02433852772fb248982bb4352c48375c42cf572ec9e3c9843c41ad723db17537', 'Earp Sardi FalseBeliefs CultHlthSex 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/02433852772fb248982bb4352c48375c42cf572ec9e3c9843c41ad723db17537.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This empirical study investigates the relationship between anatomical/procedural misconceptions and satisfaction with circumcision status among adult men in the United States. Drawing a comparison to rationalizations observed among women in societies that practice female genital cutting (FGC), the authors hypothesized that circumcised men resolve potential cognitive dissonance and justify neonatal genital alteration by endorsing false beliefs about the foreskin and circumcision.\n\nAnalyzing survey data from 902 eligible US men recruited via Amazon Mechanical Turk, the researchers found that circumcised men who endorsed a higher proportion of false beliefs regarding penile anatomy and circumcision reported significantly greater satisfaction with being circumcised. Conversely, among genitally intact men, higher endorsement of false beliefs trended toward lower satisfaction with being intact. The authors conclude that reported feelings of lack-of-harm among many circumcised men may be facilitated by misinformation and motivated reasoning rather than informed subjective preference.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Lauren M. Sardi", "William A. Jellison", "Ronald Goldman"], "organizations": ["Yale University", "Quinnipiac University", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Male Circumcision", "Female Genital Cutting (FGC)", "Penile Anatomy", "Cognitive Dissonance", "Bodily Integrity", "Sexual Satisfaction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9c4b8df0769626f2c07e19c907d662a20e3e2b0cc958d9de8d8627c589c7708d', 'Earp Sex and Circ Am J Bio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9c4b8df0769626f2c07e19c907d662a20e3e2b0cc958d9de8d8627c589c7708d.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-12", "description": "In this commentary, Brian D. Earp critiques arguments advanced by Jacobs and Arora regarding ritual infant male circumcision, specifically challenging their claim that circumcision has little to no impact on sexual function and experience. Earp argues that relying on adult randomized trials to evaluate infant procedures is flawed due to physiological and developmental differences, unvalidated survey measures, and the direct anatomical loss of densely innervated, erogenous tissue. Furthermore, Earp contextualizes male circumcision within a broader gender and bodily autonomy framework, contending that medically unnecessary modifications to the healthy genitalia of any minor\u2014male, female, or intersex\u2014should be deferred until the individual can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "A. J. Jacobs", "K. S. Arora", "Morten Frisch"], "organizations": ["University of Oxford", "Taylor & Francis", "Routledge", "World Health Organization"], "themes": ["Infant Male Circumcision", "Bioethics and Bodily Autonomy", "Sexual Function and Sensation", "Informed Consent", "Genital Cutting and Gender"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('86fc11c11dd0c7c7b715a8a437cb13533ce06c47deffe969735cea5bcdeb77ac', 'Earp Shavisi Problems defining_medicalised_FGM Lancet 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/86fc11c11dd0c7c7b715a8a437cb13533ce06c47deffe969735cea5bcdeb77ac.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This correspondence critiques the World Health Organization''s (WHO) definition of ''medicalised female genital mutilation'' (FGM), arguing that it creates cultural double standards between non-Western genital cutting practices and Western female genital cosmetic surgeries (FGCS), such as labiaplasty. The authors note that the current definition fails to incorporate crucial criteria regarding age and informed consent, improperly conflating voluntary adult choices with non-consensual procedures on children while also overlooking surgeries performed on minors and intersex infants in the Global North.\n\nTo resolve these inconsistencies and prevent discrimination based on geography, sex, or gender, the authors propose replacing ambiguous terms with a unified standard termed ''Unethical Genital Modification.'' Under this framework, any medically unnecessary genital procedure performed without the informed consent of the individual is classified as unethical, establishing consistent ethical criteria for bodily integrity across all cultural contexts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Arianne Shahvisi", "Jasmine Abdulcadir", "Mireia Garc\u00e9s de Marcilla", "Tammary Chepkoech Rotich", "Brian D. Earp"], "organizations": ["World Health Organization", "The Lancet", "Brighton and Sussex Medical School", "Geneva University Hospitals", "University of Exeter", "Amref International University", "National University of Singapore", "University of Oxford", "Brussels Collaboration on Bodily Integrity"], "themes": ["Female Genital Mutilation (FGM)", "Female Genital Cosmetic Surgery (FGCS)", "Medical Ethics", "Informed Consent", "Bodily Integrity", "Intersex Rights", "Cultural Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8b6d08afa9c4846148dd8d2ef0cd969a198135cd5f75905d085b414ec37b62b1', 'Earp Shaw American Cult Bias J Ped Ethics 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8b6d08afa9c4846148dd8d2ef0cd969a198135cd5f75905d085b414ec37b62b1.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article analyzes the controversy surrounding the American Academy of Pediatrics'' (AAP) 2012 policy statement, which concluded that the health benefits of newborn male circumcision outweigh the risks. Authors Brian D. Earp and David M. Shaw examine international criticism\u2014particularly from European medical associations\u2014that the AAP''s stance reflects cultural bias rather than objective scientific analysis. The authors evaluate the methodology of benefit-risk assessments, arguing that subjective values, cultural norms, and motivated reasoning heavily skew perceptions of harm and benefit. They note that the purported benefits are marginal or achievable through less invasive measures, while the permanent removal of healthy, sensitive prepuce tissue carries under-researched risks and subjective harms.\n\nCritiquing the AAP Task Force''s counterarguments, Earp and Shaw challenge the claims that a 50% circumcision prevalence reflects cultural neutrality and that parental discretion should permit nontherapeutic genital cutting. Drawing parallels to prohibitions against female genital alteration, they argue that nontherapeutic infant circumcision encroaches on a child''s fundamental right to bodily integrity and autonomy. The paper concludes that medical task forces should include diverse viewpoints, transparently acknowledge non-financial biases (such as personal or religious backgrounds), and adhere to standard medical norms where irreversible, elective surgeries are deferred until individuals can consent for themselves.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "David M. Shaw", "Andrew Freedman", "Douglas Diekema", "Dan Kahan", "J. Steven Svoboda", "Robert S. Van Howe"], "organizations": ["American Academy of Pediatrics", "Canadian Paediatric Society", "Royal Australasian College of Physicians", "Danish Medical Association", "British Medical Association", "World Health Organization"], "themes": ["Infant male circumcision", "Cultural bias in medicine", "Bioethics and bodily integrity", "Risk-benefit analysis", "Parental rights vs. child autonomy", "Motivated reasoning and cognitive dissonance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('06e30e938a4fcb60b101b3775a0caea51ddbab7d29b43683747a4765c455c0b1', 'Earp Sidler Targeting Mothers SAfrMedJ 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/06e30e938a4fcb60b101b3775a0caea51ddbab7d29b43683747a4765c455c0b1.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This correspondence piece critiques a proposal by Millard et al. that advocated for targeting mothers and generating artificial demand to promote medical male circumcision (MC) among adolescent boys in South Africa for HIV prevention. The authors argue that comparing circumcision to routine childhood immunisation is deeply flawed, as MC involves the irreversible surgical excision of healthy genital tissue rather than a minimally invasive intervention for an immediate childhood threat. They contend that marketing the procedure to mothers undermines parental autonomy and violates ethical informed consent standards, while also potentially breaching South Africa''s Children''s Act, which generally restricts circumcision for boys under 16 without their independent consent and counseling.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["D Sidler", "Brian D. Earp", "A A van Niekerk", "K Moodley", "S Kling", "P Millard", "N Goldstuck"], "organizations": ["South African Medical Journal", "Stellenbosch University", "Tygerberg Children''s Hospital", "University of Oxford", "Yale University", "Bill and Melinda Gates Foundation", "Clearinghouse on Male Circumcision", "World Health Organization"], "themes": ["Medical Male Circumcision", "Medical Ethics and Informed Consent", "HIV Prevention", "Children''s Rights and Healthcare Law", "Parental Autonomy", "Public Health Marketing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ee02a03cc8526e500f9ed659d22a5b1145944706484a94c01fd699f085b7208a', 'Earp Steinfeld Expand FGC Efforts MGC ReproHlth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ee02a03cc8526e500f9ed659d22a5b1145944706484a94c01fd699f085b7208a.pdf', 'medical_journal', 'ingested', '{"date": "2017-09-15", "description": "This document compiles peer-reviewed meeting abstracts focused on the prevention, eradication, and clinical management of Female Genital Mutilation/Cutting (FGM/C). Key presentations address the critical need for comprehensive training and clinical guidelines for healthcare professionals, highlighting challenges surrounding the medicalization of FGM/C in countries such as Sudan and Egypt, where procedures are increasingly performed by midwives and clinicians. \n\nAdditional contributions evaluate surgical, psychological, and community-level interventions across high-, middle-, and low-income countries. Researchers report on the outcomes, ethics, and diagnostic challenges of clitoral reconstruction and defibulation, the effectiveness of legal frameworks and criminalization, and strategies for culturally competent, community-led prevention campaigns to support survivors and end the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Fabienne Richard", "Wisal Ahmed", "Angela Dawson", "Nesrin Varol", "Birgitta Ess\u00e9n", "Sara Johnsdotter", "Bettina Shell-Duncan", "Crista E. Johnson-Agbakwu", "Edna Adan Ismail", "Lale Say", "Jasmine Abdulcadir", "Pierre Fold\u00e8s"], "organizations": ["World Health Organization", "GAMS", "CeMAViE", "Geneva University Hospitals", "Edna Adan University Hospital", "Georgetown University", "University of Sydney"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "FGM Medicalization and De-medicalization", "Healthcare Provider Training and Education", "Clitoral Reconstruction and Psychosexual Care", "Legal and Policy Interventions", "Community-Based Participatory Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b8dc2dcc5d7c50d8c62e244ea30e2a818d8cee451b78aaca21248bc053f69f89', 'Earp Steinfeld Gen Autonomy Sexual Well-being CurrSexHlthRept 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b8dc2dcc5d7c50d8c62e244ea30e2a818d8cee451b78aaca21248bc053f69f89.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This review surveys ethical, medical, and legal arguments regarding the preservation of children''s genital autonomy across female, male, and intersex demographics. The authors argue that nontherapeutic genital modifications carried out before an individual can provide informed consent infringe upon bodily integrity and potentially impair long-term sexual well-being. Furthermore, the paper highlights inconsistencies in Western legal frameworks, which strictly ban all forms of nontherapeutic female genital cutting while continuing to permit routine infant male circumcision and cosmetic ''normalizing'' surgeries on intersex children.\n\nThe authors examine the physical, psychosexual, and symbolic overlaps between these cutting practices, challenging the reliance on adult elective surgery satisfaction data to justify childhood interventions. Concluding that the harms, risks, and subjective significance of genital alteration transcend phenotypic sex categories, the authors propose a unified ethical and legal approach that protects all children from medically unnecessary genital modifications until they reach an age of informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Rebecca Steinfeld", "J Abdulcadir", "C Johnson-Agbakwu", "Robert Van Howe", "Elizabeth Reis"], "organizations": ["Yale University", "The Hastings Center", "Goldsmiths, University of London", "Springer Nature", "American Academy of Pediatrics", "Canadian Paediatric Society"], "themes": ["Genital Autonomy", "Bodily Integrity", "Childhood Circumcision", "Female Genital Cutting (FGC)", "Intersex Rights and DSD Surgeries", "Bioethics and Medical Law", "Sexual Health and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a8bd31f2374c81827373bd60727bec90a7c89c725adcb085fc66c2a642099324', 'Earp Steinfeld Gender_genital_cutting new_paradigm Euromind 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a8bd31f2374c81827373bd60727bec90a7c89c725adcb085fc66c2a642099324.pdf', 'other', 'ingested', '{"date": "2017", "description": "This article proposes a sex- and gender-neutral ethical paradigm regarding non-therapeutic genital cutting (NGC) of minors, arguing that all children\u2014female, male, and intersex\u2014deserve equal protection of their bodily integrity and genital autonomy. The authors critique the Western tendency to treat female genital cutting, male circumcision, and intersex ''normalizing'' surgeries under separate moral and legal frameworks, demonstrating that these procedures significantly overlap in both physical invasiveness and symbolic or cultural motivations.\n\nThe authors contend that the moral permissibility of genital modification should be determined by medical necessity and informed consent rather than the sex of the child. Because preemptive childhood alterations are irreversible and often lead to adult resentment without recourse, whereas unaltered individuals can always choose to undergo procedures upon reaching maturity and Gillick competence, the authors conclude that elective genital cutting should be delayed until the individual can provide valid consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brian D. Earp", "Rebecca Steinfeld", "Teresa Gim\u00e9nez Barbat", "Eduardo Zugasti", "Robert Darby", "Elizabeth Reis", "J. Steven Svoboda"], "organizations": ["Yale-Hastings Program in Ethics & Health Policy", "Goldsmiths, University of London", "ALDE Group-EU Parliament", "World Health Organization", "American Academy of Pediatrics", "Council of Europe"], "themes": ["Genital Autonomy", "Bodily Integrity", "Non-Therapeutic Genital Cutting (NGC)", "Informed Consent and Gillick Competence", "Bioethics and Human Rights", "Intersex Normalization Surgery", "Cultural and Gender Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('65d0f9be5df4b2115f118a36228613aa6bb9aca595e14119126b5d125d2f5dd3', 'Earp Steinfeld How_different_The Conversation 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/65d0f9be5df4b2115f118a36228613aa6bb9aca595e14119126b5d125d2f5dd3.pdf', 'newspaper_clipping', 'ingested', '{"date": "2017-05-15", "description": "This article examines the ethical, cultural, and physical overlaps among female genital cutting, male circumcision, and intersex ''normalisation'' surgeries. The authors argue that traditional categorical distinctions based strictly on sex or gender are increasingly difficult to justify, as many procedures share parallel cultural motivations, varying physical impacts, and a lack of medical necessity. Rather than treating these practices under divergent legal and moral standards, the authors propose a gender-neutral framework centered on bodily integrity, medical necessity, and informed consent. They suggest that such an approach reduces accusations of sexism and cultural double standards, while cautioning that effective change requires stepwise regulation and community education rather than counterproductive, abrupt criminal bans.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["R. Steinfeld", "B. D. Earp", "Hanne Gaby Odiele"], "organizations": ["The Conversation", "Dawoodi Bohra", "European Parliament"], "themes": ["Genital Cutting", "Bodily Integrity", "Informed Consent", "Intersex Rights", "Male Circumcision", "Female Genital Mutilation", "Bioethics and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('76c7bd6aa395921e1c3575e120be89629a48f9c1baf83acb9463263b0c7fa5ca', 'Earp Strengths_weaknesses_CPS PaedChHlth 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/76c7bd6aa395921e1c3575e120be89629a48f9c1baf83acb9463263b0c7fa5ca.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This commentary analyzes the 2015 Canadian Paediatric Society (CPS) position statement on newborn male circumcision, which concluded that the benefits of the procedure do not outweigh the associated risks and harms. The author highlights several strengths in the CPS statement, including the acknowledgment that the foreskin serves functional sensory roles, the recognition that absolute risks for UTIs and HIV transmission in developed nations are low, and the affirmation that circumcision is a painful, non-medically necessary procedure performed on infants unable to provide consent.\n\nConversely, the author identifies significant weaknesses in the CPS policy. These include a failure to adequately address literature regarding the adverse long-term sexual effects of circumcision, an uncritical conflation of adult and neonatal circumcision data, reliance on a pro-circumcision advocacy brochure rather than official medical guidance from Australia, and an omission of ethical comparisons to legal prohibitions against non-therapeutic female genital procedures in Canada.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp"], "organizations": ["Canadian Paediatric Society", "American Academy of Pediatrics", "University of Oxford", "Royal Australasian College of Physicians"], "themes": ["Newborn Male Circumcision", "Pediatric Ethics and Consent", "Medical Policy Analysis", "Harm vs. Benefit Assessment", "Sexual Health and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('424a2a61eeea5bfb1174b4e97425122d7a81eecbce53825023a3aa4400795e44', 'Earp Systems thinking Gender Med JME 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/424a2a61eeea5bfb1174b4e97425122d7a81eecbce53825023a3aa4400795e44.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article highlights the necessity of systems thinking in medical ethics, focusing primarily on systemic gender bias within the surgical profession. Drawing on empirical research by Hutchison detailing the mistreatment of women surgeons in Australia, the author outlines four reinforcing harms: structural workplace bias, epistemic injustice, stereotyped carework expectations, and objectification. Rather than relying on classical binary views of patriarchy, the author applies Dembroff''s intersectional ''Real Men'' framework to illustrate how surgical culture subordinates anyone who does not conform to prototypical masculine ideals.\n\nThe piece also examines moral responsibility for systemic reform, addressing the interplay between institutional accountability and individual behavior. While systemic and institutional overhauls are necessary to correct deep-seated inequalities without wrongful finger-pointing, individuals\u2014especially those holding structural authority\u2014bear an active responsibility to champion institutional change and evaluate their own conduct.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Hutchison", "RA Dembroff", "Brennan", "Scully"], "organizations": ["Journal of Medical Ethics", "University of Oxford"], "themes": ["Systems Thinking", "Gender Bias in Medicine", "Surgical Culture", "Intersectionality", "Institutional Reform", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c0fc542fd62c3ae94daa563425ddfb82aee99ff9842de95076d94ce11122d04d', 'Earp Thomson Reason and Paradox MedLawRev 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c0fc542fd62c3ae94daa563425ddfb82aee99ff9842de95076d94ce11122d04d.pdf', 'medical_journal', 'ingested', '{"date": "2017-05-24", "description": "This academic article critically analyzes the legal and ethical distinctions drawn between male and female genital cutting in medical and family law, focusing on the 2015 English High Court decision in Re B and G. In that case, Sir James Munby acknowledged that non-therapeutic cutting of both male and female genitals causes ''significant harm,'' yet concluded that the law continues to tolerate male circumcision under the scope of ''reasonable parenting'' while strictly forbidding all forms of female genital cutting. The authors argue that the dichotomies relied upon to justify this differential treatment\u2014chiefly the distinctions between religion and culture, and between therapeutic and non-therapeutic interventions\u2014are conceptually flawed, empirically untenable, and culturally biased.\n\nApplying a systems theoretical approach to legal change, the authors frame these inconsistencies as ''local paradoxes'' managed by unstable distinctions and displacements into medicine and religion. They contend that neither scriptural authority nor evidence of prophylactic health benefits provides a principled basis for categorically distinguishing male from female childhood genital cutting. Consequently, the authors advocate for a coherent, sex-neutral legal framework centered on children''s rights to bodily integrity and self-determination, which would also provide greater scrutiny to other contested childhood body-shaping interventions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Jennifer Hendry", "Michael Thomson", "Sir James Munby", "Baroness Brenda Hale"], "organizations": ["Yale University", "University of Leeds", "Oxford University Press", "World Health Organization", "High Court of Justice Family Division"], "themes": ["Genital Cutting", "Children''s Rights", "Bodily Integrity", "Systems Theory", "Medical and Family Law", "Religion vs Culture"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3bfbe4ca63e30adfba29d2bbbc9d05b52469cb8f3f4397cb0d31c8ad0d654632', 'Earp Unconst_US_anti-FGM_law_hypocrisy Converstn 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3bfbe4ca63e30adfba29d2bbbc9d05b52469cb8f3f4397cb0d31c8ad0d654632.pdf', 'newspaper_clipping', 'ingested', '{"date": "2019-01-11", "description": "This article examines the legal and ethical ramifications of a US federal judge ruling that the 1996 federal law against female genital mutilation (FGM) was unconstitutional. The author argues that sex-specific legislation exposes significant legal hypocrisy and potential equal protection violations, as federal and state legal frameworks strictly prohibit any non-consensual genital cutting on girls while continuing to permit medically unnecessary genital surgeries on boys and intersex children.\n\nThe author contends that the fundamental issue across all non-therapeutic genital cutting is the violation of a child''s right to bodily integrity without informed consent. Rather than permitting minor forms of female cutting or continuing double standards based on sex, religious tradition, or cultural habits, the author advocates for consistent legal protections that safeguard the bodily autonomy of all children until they reach an age of understanding.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Brian D Earp", "Hanne Gaby Odiele", "Dena Davis"], "organizations": ["University of Oxford", "Uehiro Centre for Practical Ethics", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Canadian Pediatric Society", "Royal Australasian College of Physicians", "World Health Organization", "Dawoodi Bohra"], "themes": ["Female Genital Mutilation (FGM)", "Male Circumcision", "Bodily Integrity and Child Rights", "Equal Protection and Constitutional Law", "Intersex Genital Surgery", "Medical Ethics and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5350718cd6e3b871cf1865d59b732d412060dbecf811aa7832d1e5257ecc6d93', 'Earp Walden Labiaplasty_in_minors 2024 ArchSexBeh.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5350718cd6e3b871cf1865d59b732d412060dbecf811aa7832d1e5257ecc6d93.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This article examines the sharp rise of labiaplasty procedures performed on minors and critically assesses the clinical, ethical, and legal justifications used to classify them as ''medically necessary.'' The authors argue that ''labial hypertrophy'' lacks objective diagnostic criteria and that normal anatomical variation is frequently pathologized. Without a rigorous standard of medical necessity, performing labial reductions on minors for aesthetic or poorly defined functional reasons risks meeting the definitions of medicalized female genital mutilation (FGM) under World Health Organization guidelines and federal laws, such as the US STOP FGM Act.\n\nAdditionally, the authors highlight substantial methodological shortcomings in existing literature on pediatric labiaplasty, including small sample sizes, short follow-up periods, biased satisfaction metrics, and failure to account for psychosocial counseling or conservative alternatives. They emphasize that minor patients may lack the developmental maturity to provide valid consent for irreversible surgery and conclude that objective eligibility criteria, standardized complication reporting, and longitudinal studies are urgently required before labiaplasty in adolescents can be considered ethically or medically supported.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Rachel L. Walden", "Jasmine Abdulcadir", "Brian D. Earp", "Alla Vash-Margita", "Dominic Wilkinson"], "organizations": ["The Johns Hopkins School of Medicine", "University Hospitals of Geneva", "University of Geneva", "University of Oxford", "National University of Singapore", "World Health Organization", "American College of Obstetricians and Gynecologists", "The Aesthetic Society"], "themes": ["Adolescent Labiaplasty", "Female Genital Mutilation (FGM)", "Medical Necessity vs. Cosmetic Surgery", "Pathologization of Anatomical Diversity", "Bioethics and Pediatric Consent", "Methodological Shortcomings in Surgical Research"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('97efe939d01c77e2e2ff0416e6c95c7ecbd4e51f03041611670f52fa9573f3a9', 'Earp Who_should_decide Peds 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/97efe939d01c77e2e2ff0416e6c95c7ecbd4e51f03041611670f52fa9573f3a9.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "In this commentary responding to an editorial by Dr. Andrew L. Freedman, Brian D. Earp argues that the decision to perform male circumcision for nonmedical reasons should belong to the individual affected rather than the parents. Addressing arguments about cultural, religious, and aesthetic preferences, Earp contends that because values differ and an individual child may not share his parents'' values later in life, ethical considerations require deferring the procedure until the child can provide informed consent.\n\nEarp also critiques the argument that infant circumcision carries significantly lower medical risk than adult circumcision, noting that comparative risk studies often fail to adequately control for confounding surgical variables. He asserts that because the absolute risk of severe surgical complications remains low across all ages, relative risk differences are morally insufficient to justify violating an individual''s bodily integrity and autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Andrew L. Freedman", "Akim McMath"], "organizations": ["University of Oxford", "The Hastings Center Bioethics Research Institute", "American Academy of Pediatrics", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "Bioethics", "Bodily Autonomy", "Informed Consent", "Parental Rights vs. Child Autonomy", "Pediatric Surgical Risk"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bd1c2fd5381f7457de58f4326813ec86d9c7f4263a263a5db9ec66cfccc9cee3', 'Earp Why_U_S_FGM ban_Unconstit MedPubHlth 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bd1c2fd5381f7457de58f4326813ec86d9c7f4263a263a5db9ec66cfccc9cee3.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article analyzes the constitutional and ethical implications of the 2018 federal court ruling that struck down the 1996 U.S. ban on female genital mutilation (FGM) on federalism grounds. Author Brian D. Earp argues that the legal and ethical frameworks separating female genital cutting (FGC) from medically unnecessary male and intersex genital cutting are increasingly untenable. While minor forms of ritual FGC are criminalized regardless of medical necessity or harm, substantially more invasive male procedures\u2014such as infant male circumcision and ritual practices like metzizah b''peh\u2014remain widely permitted and normalized in the United States, raising serious concerns regarding sex-based equal protection under the law.\n\nEarp critiques attempts to justify this asymmetry through alleged health benefits or cultural and religious distinctions, demonstrating how prominent defenders of male circumcision have begun arguing for the toleration of minor ritual FGC as a defense against encroaching restrictions on male cutting. Rather than lowering standards of protection for girls, the paper concludes that legal and ethical protections against non-consensual, non-therapeutic genital cutting must be applied equally across all sexes and genders, rooted in an overarching human right to bodily integrity and personal consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Bernard Friedman", "Alan Dershowitz", "Andrew Freedman", "Shea Lita Bond", "Kavita Shah Arora", "Allan J. Jacobs", "Richard Shweder"], "organizations": ["Yale University", "American Academy of Pediatrics", "World Health Organization", "Centers for Disease Control and Prevention", "Dawoodi Bohra", "National Secular Society", "Canadian Paediatric Society", "Royal Australasian College of Physicians"], "themes": ["Female Genital Mutilation (FGM)", "Male Circumcision", "Intersex Genital Cutting", "Bodily Integrity", "Children''s Rights", "Equal Protection and Sex Discrimination", "Constitutional Law", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a4a34ad7d5f0d2d08bb551a7b399c64f1c4e806cb10fefb4331e93192e4f2cf3', 'Earp Yuter Is_circumcision_wrong Letter 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a4a34ad7d5f0d2d08bb551a7b399c64f1c4e806cb10fefb4331e93192e4f2cf3.pdf', 'letter', 'ingested', '{"date": "2019-12-29", "description": "This document consists of an eight-part epistolary exchange between bioethicist Brian Earp and Rabbi Josh Yuter exploring the moral status of non-therapeutic infant male circumcision. Earp argues that permanently removing healthy, sexually sensitive genital tissue from a child without their consent violates fundamental bodily autonomy and constitutes a serious moral wrong, asserting that only urgent medical necessity justifies non-consensual bodily interference. He compares the practice to female genital cutting, arguing that moral consistency requires granting boys the same protections currently afforded to girls and intersex children.\n\nIn response, Yuter questions whether secular frameworks of bodily autonomy and consent hold universal authority over religious and communal traditions, referencing Jewish law and moral psychology. He argues that moral judgments often stem from subjective intuitions and shifting cultural consensus rather than objective moral facts. The exchange examines broader questions of meta-ethics, paternalism, and moral epistemology, ultimately concluding with mutual respect but an unresolved disagreement regarding the reconciliation of traditional religious obligations with contemporary secular ethics.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Brian Earp", "Josh Yuter"], "organizations": ["Letter.wiki", "World Health Organization"], "themes": ["Male Circumcision", "Bodily Autonomy", "Informed Consent", "Moral Epistemology", "Religious Ethics vs. Secular Ethics", "Female Genital Mutilation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d8734ebcc674e755dbf55275ec6ff75c37888f8df05535f84053748e8637e18b', 'Earp Zero Tolerance for GM CurrSexHlth 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d8734ebcc674e755dbf55275ec6ff75c37888f8df05535f84053748e8637e18b.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This academic review critically examines the moral justifications behind zero-tolerance policies and legislation regarding medically unnecessary female genital cutting (FGC). The author argues that typical arguments against FGC create an ethical dilemma: either they imply that common Western practices like infant male circumcision, intersex ''normalization'' surgeries, and female genital cosmetic surgery are also morally impermissible, or they reveal biased, culturally discriminatory double standards that violate principles of equal protection before the law.\n\nTo resolve this dilemma ethically and maintain policy parity, the paper argues that the only coherent, non-discriminatory justification for prohibiting non-consensual genital procedures is a foundational right to bodily integrity and genital autonomy. Under this framework, all non-consenting individuals\u2014regardless of sex, gender, religion, or race\u2014must be protected from medically unnecessary or deferrable alterations to their intimate anatomy, regardless of the procedure''s perceived severity or cultural rationale.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Juliet Rogers", "Nancy Ehrenreich", "Mark Barr", "Fuambai Ahmadu", "Ingvild Bergom Lunde", "Kai M\u00f6ller"], "organizations": ["Yale University", "World Health Organization", "United Nations", "Brussels Collaboration on Bodily Integrity", "High Court of Australia"], "themes": ["Female Genital Cutting (FGC)", "Male Circumcision", "Intersex Normalization Surgery", "Bodily Integrity and Genital Autonomy", "Children''s Rights and Consent", "Bioethics and Policy Parity", "Cultural Bias and Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('612071fd0ed4b0fb8f00fb4bc6d8f94379ba1c0b412d476b59a1ff5b8df940a6', 'Einstein From_Body_to_Brain Pers Bio Med 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/612071fd0ed4b0fb8f00fb4bc6d8f94379ba1c0b412d476b59a1ff5b8df940a6.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This academic paper proposes a neurobiological framework for understanding female genital cutting (FGC), arguing that biomedical research has excessively focused on reproductive and local genital outcomes while overlooking the central nervous system (CNS). Because the vulva is densely innervated by the pudendal, pelvic, hypogastric, and vagus nerves, cutting these tissues likely prompts retrograde degeneration and neural rewiring in the spinal cord and brain. Such reorganization in structures like Onuf''s nucleus and the somatosensory cortex could explain reported adverse effects, such as micturition issues and chronic neuropathic pain, as well as shifts in erogenous zones, phantom sensations, and preserved capacity for orgasm.\n\nIntegrating first-person accounts of women who have undergone FGC with neuroanatomical principles, the author emphasizes that cultural practices physically inscribe meaning onto neural architecture, impacting sensory experience and the lived body. Moving beyond a narrow reproductive focus allows researchers to reconcile the wide diversity of personal experiences with biological mechanisms, viewing FGC as a practice with systemic, body-wide neurobiological consequences.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gillian Einstein", "Wilder Penfield", "V. S. Ramachandran"], "organizations": ["University of Toronto", "Johns Hopkins University Press", "World Health Organization", "Women''s College Hospital"], "themes": ["Female Genital Cutting (FGC)", "Neurobiology and Neural Plasticity", "Central Nervous System Reorganization", "Somatosensory Cortex", "Women''s Health and Sexuality", "Cultural Practices and Embodiment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ac0da48e9f0e7d4afaf6063279eaf5f9e21a07b49a520f146d5becd33a71a8da', 'Ejiogu ConObj Intersex Justice IARS 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ac0da48e9f0e7d4afaf6063279eaf5f9e21a07b49a520f146d5becd33a71a8da.pdf', 'medical_journal', 'ingested', '{"date": "2020-11-01", "description": "In this commentary, anesthesiology resident Dr. Nwadiogo Ijeoma Ejiogu examines the ethical responsibility of anesthesia clinicians regarding medically unnecessary, nonconsensual genital-normalizing surgeries performed on intersex infants and children. Prompted by protests organized by the Intersex Justice Project and personal reflections on systemic medical harm against marginalized communities, Ejiogu outlines the lack of evidence supporting these procedures and the significant physical and psychological trauma reported by intersex individuals.\n\nEjiogu details the process of formally utilizing institutional conscientious objection policies during pediatric training to opt out of participating in these surgeries. The piece concludes with a call for perioperative justice, urging anesthesiologists to embrace professional accountability and actively advocate for vulnerable patients who cannot consent, thereby fostering a more ethical and humanistic medical practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Nwadiogo Ijeoma Ejiogu", "Edward C. Nemergut"], "organizations": ["International Anesthesia Research Society", "McGaw Medical Center of Northwestern University", "Intersex Justice Project", "National Institutes of Health", "Accreditation Council for Graduate Medical Education", "Transgender Gender-Variant & Intersex Justice Project"], "themes": ["Intersex Rights", "Conscientious Objection", "Pediatric Anesthesia", "Medical Ethics", "Perioperative Justice", "Patient Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('20eb33db3e880b45e0c3b6814a88f2b1a37457fea427e913248270ebfcdfb552', 'El Bcheraoui Circ Adverse Events JAMA Ped 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/20eb33db3e880b45e0c3b6814a88f2b1a37457fea427e913248270ebfcdfb552.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This retrospective cohort study evaluates the incidence of adverse events (AEs) associated with male circumcision performed in U.S. inpatient and outpatient medical settings between 2001 and 2010. Utilizing administrative claims data from SDIhealth encompassing over 1.4 million circumcised males, the researchers identified 41 possible AEs across pre-defined risk windows, determining that 16 were probably related to circumcision.\n\nThe overall incidence of probable adverse events was relatively low among infants, occurring in less than 0.5% of cases (around 0.23% to 0.40%), with the most frequent complications involving bleeding and minor correctional procedures, while serious complications were exceedingly rare. Notably, the risk of adverse events rose dramatically when the procedure was delayed beyond infancy, exhibiting an approximate 20-fold increase in children aged 1 to 9 years and a 10-fold increase in males aged 10 years and older compared to infants circumcised within their first year of life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Charbel El Bcheraoui", "Xinjian Zhang", "Christopher S. Cooper", "Charles E. Rose", "Peter H. Kilmarx", "Robert T. Chen"], "organizations": ["Centers for Disease Control and Prevention", "University of Washington", "University of Iowa", "American Academy of Pediatrics", "SDI Health"], "themes": ["Male Circumcision", "Adverse Events", "Pediatric Health", "Surgical Complications", "Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9ac551813bff047c7d38c1c4c9a9a31d7f3afa37141bb2dc93ca04aa5472e008', 'El-Koutby Webbed penis J IndAssPedSurg 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9ac551813bff047c7d38c1c4c9a9a31d7f3afa37141bb2dc93ca04aa5472e008.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This medical study proposes a novel classification system and surgical correction technique for congenital webbed penis in infants. Based on prospective clinical evaluations across two pediatric surgical units in Egypt and the UAE, the authors categorize the anomaly into primary (further divided into simple grades and compound variations) and secondary forms. The article outlines detailed surgical steps tailored to the severity of the webbing to restore normal penoscrotal anatomy with reproducible cosmetic and functional outcomes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maizels M."], "organizations": ["Mafraq Hospital", "Ain Shams Children''s Hospital", "Ain Shams University"], "themes": ["Pediatric Urology", "Congenital Anomalies", "Webbed Penis Classification", "Surgical Techniques", "Penoscrotal Reconstruction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('43b6d2aa2c47735d817028ac8168b5735b20ff184466f54106b495e47977c198', 'Elhaik crib death bioRxiv 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/43b6d2aa2c47735d817028ac8168b5735b20ff184466f54106b495e47977c198.pdf', 'medical_journal', 'ingested', '{"date": "2018-06-07", "description": "This ecological study evaluates the allostatic load hypothesis for Sudden Infant Death Syndrome (SIDS), which posits that cumulative perinatal painful, stressful, or traumatic exposures overwhelm neonatal regulatory systems. Analyzing data across 15 countries and over 40 US states from 1999 to 2016, the study investigates the association between SIDS rates and two specific early-life stressors: male neonatal circumcision (MNC) and prematurity.\n\nThe results demonstrate that SIDS prevalence is significantly and positively correlated with both MNC and premature birth rates, with the combination of both stressors showing an additive effect. Furthermore, MNC accounted for 14.2% of the variability in the male gender bias observed in US SIDS deaths. The author concludes that reducing or postponing non-medical neonatal circumcisions and improving neonatal pain management could potentially mitigate infant mortality risks, while emphasizing the need for future cohort studies to establish causality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eran Elhaik"], "organizations": ["University of Sheffield", "Insigneo Institute for in silico medicine", "Centers for Disease Control and Prevention", "March of Dimes Foundation", "bioRxiv"], "themes": ["Sudden Infant Death Syndrome (SIDS)", "Male Neonatal Circumcision", "Premature Birth", "Allostatic Load Hypothesis", "Neonatal Stress and Pain", "Infant Mortality Disparities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('10807966f6f00fbe36c4fb166b256f1be266ee4be171d4d0c9c409b0f04fd7c8', 'Elhaik Neonatal circumcision and SIDS J Clin ransl Res 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/10807966f6f00fbe36c4fb166b256f1be266ee4be171d4d0c9c409b0f04fd7c8.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This academic paper investigates the relationship between sudden infant death syndrome (SIDS) and two common phenotypes: male neonatal circumcision (MNC) and premature birth. Grounded in the allostatic load hypothesis, which posits that cumulative perinatal stress and painful trauma overwhelm infant regulatory systems, the study analyzes longitudinal and cross-sectional data from various nations and U.S. states. The findings reveal a statistically significant positive correlation between SIDS mortality and both neonatal circumcision and prematurity, with the combination of both phenotypes showing an additive effect on early unexplained infant death.\n\nThe author argues that differences in neonatal circumcision rates can help explain significant epidemiological patterns in SIDS, specifically the consistent male predominance and the notably lower mortality rates among Hispanic populations. While acknowledging the limitations inherent in epidemiological correlation, the paper suggests that surgical trauma, blood loss, and physiological stress from non-therapeutic circumcisions may substantially tax vulnerable male infants, highlighting the need for cautious policy revisions and rigorous prospective cohort studies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eran Elhaik"], "organizations": ["University of Sheffield", "Centers for Disease Control and Prevention", "March of Dimes Foundation", "Medicaid", "American Academy of Pediatrics"], "themes": ["Sudden Infant Death Syndrome (SIDS)", "Male Neonatal Circumcision", "Prematurity", "Allostatic Load Hypothesis", "Infant Mortality", "Pediatric Pain and Trauma"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fbe03725ba113c96496cd5cd1c363f9ec4d924f287543927695fde47f2b9f86e', 'Erickson Ltr - Perfect Crime 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fbe03725ba113c96496cd5cd1c363f9ec4d924f287543927695fde47f2b9f86e.pdf', 'letter', 'ingested', '{"date": "1995", "description": "This document features an excerpt from a letter written by an Arizona man to John Erickson detailing the severe psychological trauma, rage, and suicidal ideation he experiences as a result of being circumcised as an infant. The author characterizes infant circumcision as a ''perfect crime'' carried out by medical practitioners who abuse their authority under the cover of parental and societal ignorance, arguing that the psychological motivations of circumcisers need serious scrutiny.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["John A. Erickson", "Wiswell", "Fink", "Gelbaum"], "organizations": [], "themes": ["Infant circumcision", "Psychological trauma", "Medical ethics", "Bodily integrity", "Medical malpractice"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d93cdf8c7c364fb8ab145ce705227f448700038f0059be4dda4849f65221bcc2', 'Euro Multisectoral_Training Guide FGM 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d93cdf8c7c364fb8ab145ce705227f448700038f0059be4dda4849f65221bcc2.pdf', 'policy_guideline', 'ingested', '{"date": "2017", "description": "This document is an academic training guide produced by the MAP-FGM Project (co-funded by the European Commission) to incorporate education on female genital mutilation/cutting (FGM/C) into university curricula across disciplines such as medicine, law, social work, and anthropology. It establishes a multidisciplinary and culturally contextualized framework addressing the health, social, and legal dimensions of FGM/C, emphasizing that the practice violates women''s and children''s fundamental human rights while cautioning against Eurocentric alarmism and stigmatization of practicing communities.\n\nThe guide outlines clinical management guidelines, obstetric and psychosexual consequences, and surgical procedures such as deinfibulation, alongside preventive and child-protection strategies for healthcare workers. Additionally, it analyzes legal frameworks across Europe and international law, evaluating the dissuasive role and unintended consequences of criminalization, as well as the intersection of FGM/C with migration policy and asylum claims based on gender-specific persecution.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Laura Nu\u00f1o G\u00f3mez", "Adriana Kaplan", "Magaly Thill", "Nora Salas Seoane", "Els Leye", "Ricardo Falc\u00e3o", "Francesco Pompeo", "Julia Ropero Carrasco", "Michela Fusaschi"], "organizations": ["European Commission", "Rey Juan Carlos University", "Autonomous University of Barcelona", "Wassu-UAB Foundation", "Vrije Universiteit Brussel", "University Institute of Lisbon", "Rome Tre University", "Fondazione Angelo Celli", "World Health Organization", "UNICEF"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Gender-Based Violence", "Human Rights", "Clinical Management and Women''s Health", "Cultural Relativism and Anthropology", "Migration and Asylum Law", "Child Protection and Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5de477caa797771a981f5968e8003070977cdd9d9c01a712e6aaa3b9fdbbdbec', 'Evans Counseling Couples Circ Jew JPPPH 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5de477caa797771a981f5968e8003070977cdd9d9c01a712e6aaa3b9fdbbdbec.pdf', 'medical_journal', 'ingested', '{"date": "2002", "description": "This article addresses the emotional and cultural complexities faced by expectant couples\u2014specifically Jewish parents\u2014who find themselves in disagreement regarding neonatal male circumcision. Author Laurie Evans explores how cultural taboos, inadequate medical training, and religious expectations prevent parents from making fully informed choices or recognizing the pain and potential trauma of the procedure. She outlines the intense dilemmas parents face, including fears of social ostracization and marital strain, while highlighting the lack of neutral counseling and information available to them.\n\nEvans provides practical guidance and conflict-resolution strategies for counselors assisting ambivalent or conflicted couples. She directs parents toward supportive resources, advocacy organizations, and non-cutting alternatives such as the Bris Shalom (Covenant of Peace). By encouraging open dialogue, empathy, and recognition of an infant''s right to bodily integrity, the article advocates for evolving traditions that prioritize family closeness and the well-being of newborns.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Laurie Evans", "Ronald Goldman", "P. Fleiss"], "organizations": ["National Organization of Circumcision Information Resource Centers", "Doctors Opposing Circumcision", "Nurses for the Rights of the Child", "Attorneys for the Rights of the Child", "International Coalition for Genital Integrity", "Jewish Associates of the Circumcision Resource Center", "Health Care Investment Analysts"], "themes": ["Neonatal Circumcision", "Jewish Tradition and Rituals", "Bris Shalom", "Bodily Integrity and Human Rights", "Parental Conflict Resolution", "Psychological Trauma and Pain in Infants"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('20042299a40f0e2c4b51f3ef9c280e08969cf4377934397bf0d822bcf18b55a4', 'Evans, Tim Restoration Hardware Unzipped July 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/20042299a40f0e2c4b51f3ef9c280e08969cf4377934397bf0d822bcf18b55a4.pdf', 'other', 'ingested', '{"date": "2001", "description": "This document appears to be the cover text of an adult or LGBTQ+ men''s lifestyle magazine. Featured stories cover topics surrounding male sexuality, anatomy, relationship advice, and dating, including articles on foreskin restoration, non-monogamy, and tips for finding a partner, alongside features on Dan Savage and model Travis Wade.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dan Savage", "Travis Wade"], "organizations": [], "themes": ["Men''s Sexuality", "Non-Monogamy", "Dating and Relationships", "Foreskin Restoration", "LGBTQ+ Culture"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2565005b7e0e922b89081d9b369806985b5dfb04f1c02153d3379b076e6eaecf', 'Ezzell Clitoral Phimosis SciAmer 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2565005b7e0e922b89081d9b369806985b5dfb04f1c02153d3379b076e6eaecf.pdf', 'newspaper_clipping', 'ingested', '{"date": "2017-12-05", "description": "Researchers at Boston University School of Medicine, led by Dr. Irwin Goldstein, reported that approximately one-quarter of women evaluated for sexual dysfunction suffered from clitoral phimosis, an anatomical condition where the clitoral hood is overly tight or restricts glans exposure. The study of roughly 200 women found a strong correlation between the severity of phimosis and difficulty reaching orgasm, drawing a parallel to male foreskin tightness.\n\nGoldstein suggests that the condition is frequently overlooked because clinicians typically avoid examining the clitoris during standard pelvic exams. The article emphasizes the need for further research to assess the true prevalence of clitoral phimosis and its contribution to the widespread issue of female sexual dysfunction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Irwin Goldstein"], "organizations": ["Boston University School of Medicine", "Woman''s Sexual Health Clinic", "Female Sexual Function Forum", "Scientific American", "American Medical Association"], "themes": ["Female Sexual Dysfunction", "Clitoral Phimosis", "Anatomy and Sexuality", "Women''s Health", "Gynecological Examination"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2952fa571a8afb971727f7c3e434b9e382ad55bd2ed46ad60340d978f5210f80', 'Fahmy ComplicMaleCirc (ch 10, 11, 15 title, TofC).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2952fa571a8afb971727f7c3e434b9e382ad55bd2ed46ad60340d978f5210f80.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This text comprises excerpted front matter, indices, and chapters from the medical textbook ''Complications in Male Circumcision'', edited by Mohamed A. Baky Fahmy. The selections detail the various clinical, aesthetic, and functional complications associated with male circumcision, including untidy scarring, skin bridges, penile adhesions, phimosis, paraphimosis, keloids, suture marks, smegma collections, concealed penis, and penile lymphoedema. It explores both surgical techniques and humanistic perspectives regarding penile aesthetics and self-esteem, alongside restorative and reconstructive surgical interventions such as preputioplasty, tissue expansion, and repair of congenital and iatrogenic penile anomalies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A Baky Fahmy", "Jonathan A. Allan", "Ahmad R. Abdel-Aal", "Anthony Emmanuel", "Nick Watkin", "Atieno Kili K''Odhiambo"], "organizations": ["Elsevier Inc.", "Al Azher University", "Brandon University", "Solihull Hospital", "University of Nairobi", "St George\u2019s University Hospitals", "Assuit University", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "National Organization of Restoring Men"], "themes": ["Male Circumcision Complications", "Pediatric Urology and Surgery", "Genital Reconstruction and Restoration", "Penile Aesthetics and Body Image", "Surgical Scarring and Wound Healing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6aa65f9e9126e5bc0000968e2061a6a65b21af4b98886d64f7dc8305daad3277', 'Fahmy ComplicMaleCirc (ch 15 reconstruction).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6aa65f9e9126e5bc0000968e2061a6a65b21af4b98886d64f7dc8305daad3277.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This medical text details reconstructive principles and surgical techniques for addressing complications resulting from male circumcision, which frequently arise when underlying congenital penile anomalies are unrecognized. The author emphasizes tailored, case-by-case surgical planning\u2014often deferred until adulthood\u2014to restore aesthetic normal anthropometry and functional integrity while avoiding premature revision surgeries.\n\nThe text systematically examines preputial reconstruction modalities, including surgical flaps, skin grafts, emerging tissue-engineering approaches, and nonsurgical skin expansion devices used for foreskin restoration. Furthermore, it covers surgical alternatives to circumcision such as preputioplasty for phimosis, preputial reconstruction in hypospadias repairs, and corrective strategies for conditions like penile torsion and concealed or trapped penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A Baky Fahmy", "Aulus Cornelius Celsus", "Galen", "Maurice Maizels"], "organizations": ["National Organization of Restoring Men (NORM)"], "themes": ["Reconstructive Urology", "Circumcision Complications", "Foreskin Restoration", "Preputioplasty", "Penile Torsion", "Concealed Penis", "Tissue Engineering and Regenerative Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7c1ee4c6e4850be7faa203624dc83c6eb4745aff880d49842663f20549f56934', 'Fahmy ComplicMaleCirc (contributors) 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7c1ee4c6e4850be7faa203624dc83c6eb4745aff880d49842663f20549f56934.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This document is a list of contributors for an academic or medical publication, detailing each author''s academic degrees, professional titles, institutional affiliations, and locations. The contributors represent diverse disciplines, ranging from pediatric surgery, urology, and hyperbaric oxygen therapy to queer theory and educational foundations across global institutions in Egypt, Canada, the United Kingdom, and Kenya.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ahmad R. Abdel-Aal", "Jonathan A. Allan", "Anthony Emmanuel", "Mohamed A Baky Fahmy", "Atieno Kili K\u2019Odhiambo", "Nick Watkin"], "organizations": ["Assuit University", "Brandon University", "Solihull Hospital", "Al Azher University", "University of Nairobi", "St George\u2019s University Hospitals"], "themes": ["Academic Publishing", "Pediatric Surgery", "Urology", "Hyperbaric Oxygen Therapy", "Higher Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1679eb107eff12995448111d70a0890f158e371621b17882667ec81b6f422e5', 'Fahmy ComplicMaleCirc Title page.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1679eb107eff12995448111d70a0890f158e371621b17882667ec81b6f422e5.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This text represents the title page or front matter for a medical work titled ''Complications in Male Circumcision.'' It identifies Mohamed A. Baky Fahmy, a Professor of Pediatric Surgery at Al Azher University in Cairo, Egypt, as the editor.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A. Baky Fahmy"], "organizations": ["Al Azher University"], "themes": ["Male Circumcision", "Surgical Complications", "Pediatric Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('931d48f8850f26afa0e5e9d0b17f03acb1f797dd8e4640eca908b7409210bae6', 'Fahmy Management ischemia post-circ BMJ Urol 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/931d48f8850f26afa0e5e9d0b17f03acb1f797dd8e4640eca908b7409210bae6.pdf', 'medical_journal', 'ingested', '{"date": "2023-06-28", "description": "This prospective cohort study evaluates a multimodal treatment protocol consisting of intravenous pentoxifylline infusion, hyperbaric oxygen therapy (HBOT), and topical nitroglycerin ointment for the management of post-circumcision penile ischemia in pediatric patients. Analyzing 23 boys presenting with penile ischemia between 2017 and 2021, the authors identified the use of monopolar diathermy (74%), compressive wound dressings (52.2%), post-operative infection (43.5%), and circumcisions performed by inexperienced or non-specialist practitioners (73.9%) as the predominant causative factors.\n\nThe findings indicate that timing and depth of ischemia are crucial determinants of patient outcomes; children admitted and treated within the first 24 hours had significantly better rates of spontaneous recovery without tissue loss compared to those with delayed presentation. While deep necrosis often resulted in partial or complete tissue loss necessitating staged reconstructive surgeries, the combination of HBOT and pentoxifylline proved effective at enhancing tissue revascularization and limiting tissue loss, prompting the authors to recommend early referral and advocate for a strict ban on monopolar diathermy during circumcision procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A Baky Fahmy", "Tarek Abdelazeem Sabra", "Sarah Magdy Abdelmohsen"], "organizations": ["Al-Azhar University", "Assiut University", "Aswan University", "BMC Urology", "Science, Technology & Innovation Funding Authority", "Egyptian Knowledge Bank"], "themes": ["Pediatric Surgery", "Post-circumcision Complications", "Penile Ischemia and Necrosis", "Hyperbaric Oxygen Therapy", "Pentoxifylline Infusion", "Surgical Safety and Electrocautery Hazards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8c0b4f0b57edf756c890447583c29e7bce09ecfdd4eb21c1cbe972f2afc36f2e', 'Fahmy Normal&Abnormal Prepuce (advertisement) 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8c0b4f0b57edf756c890447583c29e7bce09ecfdd4eb21c1cbe972f2afc36f2e.pdf', 'other', 'ingested', '{"date": "2020", "description": "This text serves as an introduction to a clinical reference book detailing the anatomy, embryology, functions, and pathology of the human prepuce in both males and females. Drawing on four decades of surgical practice, the author argues that the prepuce is a specialized, functional, and highly vascularized organ whose medical significance has historically been neglected due to routine circumcision practices and limited medical education.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": [], "themes": ["Preputial Anatomy and Function", "Pediatric Surgery", "Phimosis and Misdiagnosis", "Circumcision and Genital Autonomy", "Congenital and Rare Anomalies"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('518e03d5a73adc94ea23585f11848e4cfcd3450d9ef150f4de1be8d2714b9e59', 'Fahmy Normal&Abnormal Prepuce (complete book) 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/518e03d5a73adc94ea23585f11848e4cfcd3450d9ef150f4de1be8d2714b9e59.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This document comprises the front matter, table of contents, and initial chapters of the medical textbook ''Normal and Abnormal Prepuce'' by pediatric surgeon Mohamed A. Baky Fahmy. The text provides a comprehensive overview of the male and female prepuce, addressing its historical cultural contexts, comparative mammalian anatomy, embryological development, histological structures, and physiological functions. The author argues that the prepuce is not merely a superfluous skin fold to be excised during circumcision, but a specialized, innervated, and functional organ requiring dedicated medical study and understanding.\n\nIn addition to detailing normal anatomy and embryological processes, the work reviews the vast spectrum of congenital anomalies (such as aposthia, macroposthia, and hooded prepuce) and acquired pathologies (including phimosis, paraphimosis, lichen sclerosus, infections, and malignancies). It also highlights the surgical, immunological, and reconstructive significance of preputial tissue, emphasizing the necessity of preserving or properly managing the prepuce across diverse clinical disciplines.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A. Baky Fahmy", "Ahmed Medhat Zaki", "Douglas Gairdner", "Laurence S. Baskin"], "organizations": ["Springer Nature Switzerland AG", "Al Azher University", "Ain Shams University", "University of California, San Francisco"], "themes": ["Preputial Anatomy and Embryology", "History and Cultural Perspectives of Circumcision", "Comparative Animal Anatomy", "Congenital and Acquired Penile Pathologies", "Pediatric and Reconstructive Urologic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d6384b5cb55452afa98e17178111b9e5072323ea0e90a3a3486438953e594a08', 'Fahmy Normal&Abnormal Prepuce (phimosis chapter) 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d6384b5cb55452afa98e17178111b9e5072323ea0e90a3a3486438953e594a08.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This medical text provides a comprehensive clinical overview of phimosis, distinguishing between normal physiological non-retractability (preputial synechiae) and true pathological phimosis. It addresses historical misconceptions and modern clinical definitions, noting that developmental foreskin adherence is common in infancy and childhood and typically resolves spontaneously with age without requiring surgical intervention.\n\nThe author categorizes phimosis into congenital, acquired (often driven by conditions such as balanitis xerotica obliterans, diabetes, or recurrent infections), and post-circumcision cicatricial types. In addressing management, the text highlights a shift away from routine traditional circumcision toward conservative options, demonstrating high success rates with topical corticosteroid therapy and advocating for foreskin-sparing procedures, such as preputioplasty or gentle dilation, when surgery is indicated.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["M. A. B. Fahmy", "A. M. K. Rickwood", "Douglas Gairdner", "Jakob Oster", "Aulus Celsus"], "organizations": ["Springer Nature", "Alder Hey Children''s Hospital"], "themes": ["Phimosis and Preputial Development", "Balanitis Xerotica Obliterans (BXO)", "Pediatric Urology and Diagnostics", "Topical Corticosteroid Therapy", "Surgical Alternatives to Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8337d42a44b99c0d88999ad6d15fd3af94ea096aa51ce8255220757617861b97', 'Fahmy Phlebectasia Non-MedCirc PedSurgTrop 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8337d42a44b99c0d88999ad6d15fd3af94ea096aa51ce8255220757617861b97.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This prospective comparative cohort study evaluated 830 pediatric patients (420 circumcised and 410 intact) to determine the correlation between non-medical male circumcision and penile venous anomalies such as phlebectasia and phlebothrombosis. The study found a statistically significant increase in abnormal penile venous dilation (5.5% vs. 0.5%) and lateral penile deviation/chordee in circumcised boys compared to the uncircumcised control group, with abnormalities predominantly affecting the dorsal penile vein.\n\nThe authors conclude that circumcision wounds, subsequent scar formation, and aggressive hemostatic techniques (such as electro-coagulation) can distort Buck''s fascia and the surrounding vascular structures, leading to acquired phlebectasia and penile curvature. They advise careful surgical techniques, favoring compression or fine sutures over electro-coagulation to mitigate these complications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed Abdel Baky Fahmy", "Noor A. Nour", "Hasan A Matar", "Akhmad Asaad Matar", "Asaad A Matar", "Valentin N Pavlov"], "organizations": ["Al-Azhar University", "Bashkir State Medical University", "Russian Medical Academy of Postgraduate Education", "International Medical Academy of Urology"], "themes": ["Male Circumcision Complications", "Penile Phlebectasia", "Phlebothrombosis", "Penile Chordee and Deviation", "Pediatric Urology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('aad2277f54e72a0e327bcfcb986d691fbc74853d1bf4c6632c8b91a68dff117e', 'Fahmy Spectrum of adhesions BMCUrol 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/aad2277f54e72a0e327bcfcb986d691fbc74853d1bf4c6632c8b91a68dff117e.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This retrospective study examines 95 pediatric cases of glanular-preputial adhesions (GPA) following ritual non-medical male circumcision in Egypt between 2019 and 2023. Patients were categorized into two primary cohorts based on presentation severity: Group A comprised 55 infants and children with early, simple fibrinous adhesions successfully resolved via conservative medical management using topical corticosteroids and retractile hygiene, while Group B included 40 patients exhibiting fibrous, well-formed skin bridges or cicatricial phimosis requiring surgical adhesiolysis.\n\nThe findings demonstrate a significant correlation between adhesion development and the use of the guillotine circumcision technique, as well as procedures executed by non-medical or general practitioner personnel. The authors emphasize that post-circumcision adhesions represent a manageable yet significant complication, where early fibrinous presentations resolve well with topical steroids, but mature skin bridges demand operative repair to prevent long-term functional and cosmetic sequelae.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohamed A. Baky Fahmy", "Amr Hussein Elsayed Mohamed", "Mohamed Fawzy ElSayed Ali AbdAlla", "Nour A. Nour"], "organizations": ["Al-Azhar University", "National Institute of Urology", "BMC Urology", "Springer Nature"], "themes": ["Pediatric Urology", "Male Circumcision Complications", "Glanular-Preputial Adhesions", "Surgical Adhesiolysis", "Postoperative Wound Care", "Penile Skin Bridges"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e93608cad142a2e6a00bcd3a530a234345e68960d2fe2e930e66ec6609b74b00', 'Fendereski Compare Penile Problems Circ-Uncirc JPedSurg 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e93608cad142a2e6a00bcd3a530a234345e68960d2fe2e930e66ec6609b74b00.pdf', 'medical_journal', 'ingested', '{"date": "2024-07-05", "description": "This study analyzes commercial claims data from the MarketScan database (2011\u20132020) to compare the incidence of penile problems in approximately 850,000 circumcised boys versus 850,000 matched uncircumcised controls, while also evaluating provider type differences. The authors found that while overall penile complications within the first five years of life remain infrequent, circumcised boys faced a 2.9-fold higher risk of penile problems compared to uncircumcised boys (1.7% vs. 0.5%). Additionally, patients circumcised by surgeons demonstrated a 2.1-fold higher rate of post-procedure penile problems compared to those treated by pediatricians.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kiarad Fendereski", "Joshua John Horns", "Nathan Driggs", "Glen Lau", "Anthony J Schaeffer"], "organizations": ["Journal of Pediatric Surgery", "MarketScan"], "themes": ["Circumcision", "Pediatric Surgery", "Urology", "Postoperative Complications", "Provider Comparison"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('652d4c92665430f6aae2ddf87d70dbce39ae7914a4b2aa6818d66e5f18f92c58', 'Fihman JSM-reply by Kevin Barrett 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/652d4c92665430f6aae2ddf87d70dbce39ae7914a4b2aa6818d66e5f18f92c58.pdf', 'letter', 'ingested', '{"date": "2026", "description": "This document is a formal letter from Kevin Barrett, an ethics researcher and public health advocate, to the editorial leadership of The Journal of Sexual Medicine and Oxford University Press, requesting an editorial review and correction of a published study by Fihman et al. (2026) concerning elective adult circumcision. Barrett outlines nine key methodological and ethical deficiencies, including the lack of a defined postoperative follow-up timeline, retrospective self-reporting biases, failure to disclose that an American Academy of Pediatrics policy cited had expired in 2017, omission of contemporary relevant literature, and insufficient reporting of statistical domain scores and effect sizes.\n\nAdditionally, the letter notes critical limitations involving a small sample size with potential non-response bias, unwarranted generalisation of adult findings to neonatal circumcision, failure to analyse differences between surgical techniques, and the absence of a required Data Availability Statement. Referencing Committee on Publication Ethics (COPE) standards, Barrett urges the editorial team to issue appropriate corrections or clarifications to protect scientific rigor and transparency.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Kevin Barrett", "Fihman"], "organizations": ["The Journal of Sexual Medicine", "Oxford University Press", "Committee on Publication Ethics", "American Academy of Pediatrics"], "themes": ["Publication Ethics", "Research Integrity", "Circumcision", "Methodological Rigor", "Post-Publication Review"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ffca59badc5f524f8b552b8a0d3fff94787c93a990139d897980318475c3f80', 'Fihman-Impact elective adult circ JSM 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ffca59badc5f524f8b552b8a0d3fff94787c93a990139d897980318475c3f80.pdf', 'medical_journal', 'ingested', '{"date": "2026", "description": "This pilot study investigates the impact of elective adult male circumcision performed for religious reasons on sexual function and overall satisfaction. Evaluating 32 adult patients who underwent circumcision between 2020 and 2024 at Shaare Zedek Medical Center, the researchers compared pre- and post-operative outcomes using validated tools, specifically the International Index of Erectile Function (IIEF) and the Premature Ejaculation Diagnostic Tool (PEDT).\n\nThe findings revealed no significant differences in erectile function, sexual desire, orgasm, or ejaculatory control before and after the procedure. Additionally, the vast majority of participants reported no harm to their quality of life and expressed no regret about undergoing the procedure, suggesting that elective adult circumcision does not adversely affect sexual function or satisfaction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["May Fihman", "Boris Chertin", "Dolev Peretz", "Mahmood Abbas", "Yehuda Noyman", "Binyamin B. Neeman"], "organizations": ["The International Society for Sexual Medicine", "Oxford University Press", "Hebrew University", "Shaare Zedek Medical Center", "American Academy of Pediatrics", "American Urological Association"], "themes": ["Male Circumcision", "Sexual Function", "Men''s Health", "Erectile Dysfunction", "Premature Ejaculation", "Quality of Life"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5bdaae0664be2eb289a43511b64b8b098b62764b980264259214ea8aa8cd6717', 'Fish childrens-sexual-development-privacy ClinPeds 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5bdaae0664be2eb289a43511b64b8b098b62764b980264259214ea8aa8cd6717.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This commentary argues that medical interventions involving children''s genitalia require rigorous justification and must be strictly evidence-based, especially given the potential for psychological distress and the necessity of respecting developing sexual boundaries and privacy. The authors argue that routine clinical examinations of healthy minors'' genitalia often prioritize medical convention over empirical support, pointing out that routine screening does not meet standard evidence-based criteria established by preventive health authorities.\n\nThe authors critically evaluate three policies endorsed by the American Academy of Pediatrics (AAP): routine sexual maturity screening using the Tanner scale, routine preventive gynecological exams for adolescent girls, and nontherapeutic infant male circumcision. They contend that these practices lack high-quality evidence of benefit, diverge significantly from international guidelines, and may cause harm or lead to unnecessary invasive procedures. Consequently, they urge professional pediatric organizations to revise these policies, restrict intimate examinations to medically indicated and symptomatic cases, and ensure fully informed consent that transparently communicates clinical uncertainties.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Fish", "Margaret M. McCartney", "Brian D. Earp", "Al Aynsley-Green", "Andrew Freedman"], "organizations": ["American Academy of Pediatrics", "US Preventive Services Taskforce", "National Health Service", "Child Rights International Network", "UNICEF", "University of Oxford", "Yale University", "University of St. Andrews"], "themes": ["Evidence-Based Medicine", "Pediatric Ethics", "Genital Examination and Screening", "Patient Privacy and Autonomy", "Informed Consent", "Male Infant Circumcision", "Sexual Maturity Assessment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cfb3b10d92f9331b1f16e0759c4a07a16f8aa01ffa942cb8a57ba72cbf7b9633', 'Fish Earp New Tuskegee Dev World Bioeth 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cfb3b10d92f9331b1f16e0759c4a07a16f8aa01ffa942cb8a57ba72cbf7b9633.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article critically evaluates the mass voluntary medical male circumcision (VMMC) campaigns promoted by the World Health Organization (WHO), UNAIDS, and Western agencies across sub-Saharan Africa to reduce HIV transmission. Drawing parallels to historically unethical medical experiments such as the Tuskegee Syphilis Study, the authors argue that VMMC policy is rooted in racial stereotypes regarding African sexuality, neglects complex socioeconomic determinants of health, and imposes Western bodily norms through cultural imperialism.\n\nThe authors further highlight serious ethical, methodological, and human rights issues within VMMC trials and roll-out programs, including coercive incentives, unconsented circumcisions of minors, and a trial that observed increased HIV transmission to female partners. Emphasizing the emergence of newer, more effective biomedical interventions such as PrEP and TasP, the paper contends that public health authorities must dismantle paternalistic neocolonial frameworks and ensure African communities possess meaningful representation and autonomy over their own healthcare policies and bodies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Fish", "Arianne Shahvisi", "Tatenda Gwaambuka", "Godfrey B. Tangwa", "Daniel Ncayiyana", "Brian D. Earp"], "organizations": ["World Health Organization", "UNAIDS", "Johns Hopkins University", "United States Agency for International Development", "Centers for Disease Control and Prevention", "President''s Emergency Plan for AIDS Relief", "The VMMC Experience Project"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "Bioethics and Medical Exploitation", "Neocolonialism and Cultural Imperialism", "HIV/AIDS Prevention", "Medical Racism", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2244dd9d509707ead9dcefbc4902483bddd50fa3febc6d02be5f871e2531f4c4', 'Fish Earp VMMC MorrisReply ClinInfDisease 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2244dd9d509707ead9dcefbc4902483bddd50fa3febc6d02be5f871e2531f4c4.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "In this response published in Clinical Infectious Diseases, Max Fish, Brian D. Earp, and their co-authors refute criticisms made by Brian Morris regarding their earlier work on voluntary medical male circumcision (VMMC) and neocolonialism in African HIV prevention initiatives. The authors address and correct several factual inaccuracies propagated by Morris concerning lead author Max Fish''s credentials and organization, while strongly rejecting his characterization of their team as solely ''white westerners,'' which erases the perspectives and contributions of the African scholars on the paper.\n\nAdditionally, the authors dispute Morris''s assertion that VMMC is universally accepted without controversy in the medical-scientific community, citing ongoing bioethical debates, high adverse event rates in infant trials, and Morris\u2019s heavy reliance on self-citation. They argue that global health campaigns led by Western institutions cannot substitute genuine grassroots African community representation with high-ranking international elites, maintaining that affected local populations must have an active voice in public health policy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Max Fish", "Brian Morris", "Arianne Shahvisi", "Godfrey B. Tangwa", "Daniel Ncayiyana", "Brian D. Earp", "Tedros Ghebreyesus"], "organizations": ["VMMC Experience Project", "South African Medical Association", "World Health Organization", "University of Oxford", "Brighton and Sussex Medical School", "University of Yaounde I"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV Prevention", "Neocolonialism in Global Health", "Bioethics", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('496649d51c8f69fa5cfac68d8af818c3c9ad458dc790ce0a0d898eb092c3c142', 'Flawed HIV RCTs IntactAmerica (no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/496649d51c8f69fa5cfac68d8af818c3c9ad458dc790ce0a0d898eb092c3c142.pdf', 'policy_guideline', 'ingested', '{"date": "2009", "description": "This policy brief critiques three randomized clinical trials conducted in sub-Saharan Africa that promoted male circumcision as an effective measure to curb HIV/AIDS transmission. The document argues that these trials had significant methodological flaws\u2014including early termination, substantial loss of participants to follow-up, researcher bias, and a lack of protective benefits for women and men who have sex with men\u2014while pointing out that condom use and education are far more effective and cost-efficient.\n\nFurthermore, the paper asserts that these African studies cannot ethically or scientifically justify recommending infant or adult circumcision in the United States. It highlights vast differences in epidemiology, healthcare access, and transmission vectors between the regions, concluding that routine neonatal circumcision violates bioethical standards regarding proxy consent and the unnecessary removal of healthy tissue.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["Intact America", "Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Cochrane Collaboration"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Infant and Neonatal Health", "Medical Ethics and Informed Consent", "Randomized Clinical Trials"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf082aa73a7f240ba1c93f4f7496af6749d20ba058271ebe5b4d1e8bd2a7bb96', 'Fleiss Hodges VanHowe Immunol SexTransInf 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf082aa73a7f240ba1c93f4f7496af6749d20ba058271ebe5b4d1e8bd2a7bb96.pdf', 'medical_journal', 'ingested', '{"date": "1998", "description": "This debate article argues against routine male neonatal circumcision, asserting that historical and modern justifications\u2014ranging from masturbation deterrence to sexually transmitted disease (STD) prevention\u2014are scientifically unfounded. The authors review histological and physiological evidence demonstrating that the prepuce (foreskin) is a functional, highly vascularized, and innervated specialized tissue that provides essential mechanical protection, lubrication, and local immunological defenses via antibacterial enzymes, lysozymes, and immunoglobulins.\n\nCritically reviewing epidemiological studies, the authors contest assertions that circumcision protects against HIV and other STDs, highlighting significant methodological flaws, population biases, and confounding socio-cultural factors in existing African and global studies. They conclude that prophylactic preputial amputation compromises penile immunity, sensitivity, and structural integrity, and that performing non-therapeutic, involuntary genital surgery on unconsenting neonates constitutes a serious violation of medical ethics and bodily integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["P M Fleiss", "F M Hodges", "R S Van Howe"], "organizations": ["University of Southern California Medical Center", "University of Oxford", "Medical College of Wisconsin"], "themes": ["Immunological functions of the foreskin", "Routine neonatal male circumcision", "HIV and STD transmission risks", "Medical ethics and patient consent", "Penile anatomy and sexual physiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7af02beb82c651e4f44def3ab28f7262850177feca92ee4f968250222141117', 'Fletcher Circ in America Physician Attitudes Plenum 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7af02beb82c651e4f44def3ab28f7262850177feca92ee4f968250222141117.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This document presents the findings of a 1998 study examining the attitudes, beliefs, informed consent practices, and financial incentives surrounding neonatal male circumcision among American physicians, conducted primarily through the Ambulatory Sentinel Primary Care Network (ASPN). The author argues that routine infant circumcision is a medically unnecessary, non-consensual surgical procedure sustained by debunked medical arguments, professional habit, parental cultural expectations, and substantial financial reimbursement. Despite growing medical literature refuting the procedural benefits regarding phimosis, UTIs, and STIs, a significant portion of physicians continue to promote these justifications to parents.\n\nSurvey results from 213 physicians revealed critical gaps in practice and ethics: although a majority (53%) believed circumcision causes more harm than benefit, 71% continued to perform it, with over a third operating despite personal moral opposition. Furthermore, physicians rarely provided comprehensive informed consent, overwhelmingly omitting severe risks such as penile amputation, catastrophic hemorrhage, or death. Fletcher concludes that because organized medical associations have failed to eliminate routine non-therapeutic circumcisions, legal, constitutional, and human rights interventions may be necessary to halt the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Christopher R. Fletcher", "Robert S. Van Howe", "Marilyn Fayre Milos", "George C. Denniston"], "organizations": ["Ambulatory Sentinel Primary Care Network (ASPN)", "Marshfield Clinic", "American Academy of Pediatrics (AAP)", "American College of Obstetricians and Gynecologists (ACOG)", "American Academy of Family Physicians (AAFP)", "American Medical Association (AMA)"], "themes": ["Neonatal Circumcision", "Medical Ethics and Human Rights", "Informed Consent", "Physician Attitudes and Practices", "Evidence-Based Medicine", "Financial Incentives in Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c4e09b4fa3ed526864be33ae7e2d68e8be43a67b5e7b689dad2d96c46bc62443', 'Ford Why Pleasure Matters IJSH 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c4e09b4fa3ed526864be33ae7e2d68e8be43a67b5e7b689dad2d96c46bc62443.pdf', 'medical_journal', 'ingested', '{"date": "2019-08-30", "description": "This academic commentary argues that global sexual and reproductive health initiatives have disproportionately focused on negative outcomes, such as sexually transmitted infections, HIV, unintended pregnancy, and violence, while neglecting the positive role of sexual pleasure. The authors contend that sexual pleasure is a primary motivator of human sexual behavior and a critical component of overall health, wellbeing, and human rights. Incorporating sexual pleasure into public health policies, sexuality education, and clinical practice is demonstrated to improve safer sex behaviors, condom use, and health literacy, ultimately contributing toward global development benchmarks such as the Sustainable Development Goals.\n\nThe authors address major socio-cultural and political barriers, including gender inequality, pervasive sexual double standards, systemic oppression, and the risks of excessive medicalization. They provide a framework linking sexual pleasure to sexual rights\u2014emphasizing autonomy, consent, equality, and diversity\u2014and advocate for accountability mechanisms, pleasure audits, and policy reorientations across transnational, national, and local healthcare structures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jessie V. Ford", "Esther Corona Vargas", "Itor Finotelli Jr.", "J. Dennis Fortenberry", "Eszter Kism\u00f6di", "Anne Philpott", "Eusebio Rubio-Aurioles", "Eli Coleman"], "organizations": ["International Journal of Sexual Health", "World Association for Sexual Health", "Global Advisory Board for Sexual Health and Wellbeing", "World Health Organization", "Columbia University Mailman School of Public Health", "University of Minnesota Medical School", "Indiana University School of Medicine", "The Pleasure Project", "Guttmacher Institute"], "themes": ["Sexual Health", "Sexual Pleasure", "Sexual Rights and Human Rights", "Public Health Policy", "Sexuality Education", "Sustainable Development Goals (SDGs)", "Gender Equality and Wellbeing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('effa3d1a31c927cdbfb13db5566ba0d0af961bea4294abc8ff0959532be0ff5a', 'Foregen - Purpura SAGE 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/effa3d1a31c927cdbfb13db5566ba0d0af961bea4294abc8ff0959532be0ff5a.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This study details the development and evaluation of an extracellular matrix (ECM)-based biomaterial scaffold derived from decellularized human foreskin dermis, intended to aid in anatomical foreskin reconstruction for circumcised men. Addressing the physiological and psychosexual complications linked to male circumcision and the shortcomings of conventional restorative procedures, the authors applied a chemicophysical decellularization process to foreskin tissue procured from consenting adult donors.\n\nEvaluation of the resulting foreskin dermal matrices (FDMs) confirmed complete cell removal without compromising the distinctive butterfly-shaped geometry, structural integrity, collagen and elastic fiber density, or tensile mechanical properties. Additionally, the decellularized matrices demonstrated a twofold increase in basic fibroblast growth factor (FGFb) content, suggesting enhanced bioactivity and strong potential as a functional scaffold for regenerative tissue engineering.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Valeria Purpura", "Elena Bondioli", "Eric J Cunningham", "Giovanni De Luca", "Daniela Capirossi", "Evandro Nigrisoli", "Tyler Drozd", "Matthew Serody", "Vincenzo Aiello", "Carlo A Cirioni", "Davide Melandri"], "organizations": ["Emilia Romagna Regional Skin Bank and Burn Centre", "Bufalini Hospital", "AUSL Romagna", "Illinois Institute of Technology", "Foregen Onlus Association"], "themes": ["Tissue Engineering", "Regenerative Medicine", "Decellularization", "Extracellular Matrix Scaffolds", "Foreskin Reconstruction", "Male Circumcision Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('79733932d1adfef2f40089982d5be32a01227f68ee98ee16c3e6c4722a873511', 'Foregen White Paper 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/79733932d1adfef2f40089982d5be32a01227f68ee98ee16c3e6c4722a873511.pdf', 'other', 'ingested', '{"date": "2025-08-08", "description": "This white paper published by Foregen details the scientific, ethical, and clinical framework for developing a regenerative medicine solution to reverse male circumcision. It argues that circumcision\u2014particularly when performed on infants without consent\u2014results in the permanent loss of specialized erogenous tissue, fine-touch sensory innervation, and natural penile mechanics, causing enduring physical and psychological distress for many men.\n\nTo address this unmet need, Foregen presents a five-phase roadmap centered on tissue engineering. The methodology involves preparing decellularized extracellular matrix (ECM) scaffolds from donor tissue, recellularizing them with patient stem or autologous cells in a bioreactor, and surgically grafting the construct with a strong emphasis on restoring vascularization and peripheral nerve reinnervation. The document grounds its mission in ethical principles of bodily autonomy, the right to an open future, and restorative justice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Foregen"], "themes": ["Regenerative Medicine", "Tissue Engineering", "Male Circumcision", "Foreskin Restoration", "Bodily Integrity", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('475bddd612b167267292bf41b3b66c5b1f2425c93aeb4c3f9d513458d61d78fd', 'Foregen_Foreskin_Anatomy (model, add text, flat).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/475bddd612b167267292bf41b3b66c5b1f2425c93aeb4c3f9d513458d61d78fd.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This text discusses the anatomical dimensions of the adult foreskin and the impact of neonatal circumcision. It highlights that the adult foreskin surface area ranges widely from 18 to 90 cm\u00b2 and notes that standard neonatal circumcisions typically excise approximately 50% of the mean penile shaft skin length projected into adulthood.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul M.N. Werker", "Alex S.C. Terng", "Moshe Kon", "J.R. Taylor", "A.P. Lockwood", "A.J. Taylor"], "organizations": ["Plastic and Reconstructive Surgery", "British Journal of Urology"], "themes": ["Circumcision", "Penile Anatomy", "Urology", "Plastic and Reconstructive Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7200fff9468958dd49a7bd0376c5c99aec616caf71f64d9d61e2eea715f83773', 'Fox Foreskin Feminist Austral Fem 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7200fff9468958dd49a7bd0376c5c99aec616caf71f64d9d61e2eea715f83773.pdf', 'other', 'ingested', '{"date": "2009-05-12", "description": "This article examines the ethics and socio-cultural dimensions of non-therapeutic infant male circumcision, arguing that the practice should be analyzed through the lens of feminist theory and embodiment rather than restricted to conventional bioethical risk-benefit assessments. The authors critique mainstream feminist scholarship for largely overlooking male circumcision or rigidly separating it from female genital cutting, contending that this binary treats comparable bodily modifications as conceptually distinct and inadvertently signals that certain bodies matter more than others.\n\nFocusing historically and comparatively on Australia, New Zealand, and the United Kingdom, the paper traces how routine neonatal circumcision emerged and persisted as a gendering technology deeply rooted in ideologies of masculinity. The authors demonstrate that the surgery was historically promoted to regulate male sexuality\u2014specifically to deter masturbation and enforce sexual restraint\u2014and to align the male body with aesthetic and hygienic ideals of phallic closure by pathologizing and feminizing the foreskin as redundant, polluted tissue.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Marie Fox", "Michael Thomson", "Margaret Somerville", "Martha Nussbaum", "Carolyn Pedwell", "Janice Boddy", "Robert Darby", "Douglas Gairdner"], "organizations": ["Australian Paediatric Association", "Australasian Association of Paediatric Surgeons", "National Health Service", "British Medical Association", "World Health Organization", "Royal Australasian College of Physicians", "Keele University"], "themes": ["Infant Male Circumcision", "Feminist Theory", "Female Genital Cutting", "Masculinity and Gender Norms", "Bioethics and Bodily Integrity", "History of Medicine", "Regulation of Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5b83694214aca8d7ec951d896974ddd8403ac4139788471efd53ca534e5e2818', 'Fox New Politics of Male Circ LegalStudies 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5b83694214aca8d7ec951d896974ddd8403ac4139788471efd53ca534e5e2818.pdf', 'legal_document', 'ingested', '{"date": "2012", "description": "This article examines the shifting global politics of male circumcision, critically assessing its promotion as a biomedical intervention to reduce heterosexual HIV transmission in sub-Saharan Africa and its subsequent influence on revitalizing neonatal circumcision advocacy in Western nations like the United States. Authors Marie Fox and Michael Thomson argue that clinical trial findings have been oversimplified, external validity remains questionable, and mass circumcision campaigns risk diverting resources from more effective prevention methods while fostering dangerous risk-compensation behaviors.\n\nThe authors call for re-framing the legal and ethical analysis of circumcision away from traditional medical law''s narrow emphasis on doctor-patient consent and private parental choice toward a comprehensive social justice and human rights framework. Such a framework exposes the structural, racial, and socioeconomic dimensions of the HIV/AIDS epidemic, addresses critical violations of bodily integrity in infants, and illuminates how male-targeted circumcision policies often overlook and potentially endanger the health and autonomy of women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Marie Fox", "Michael Thomson", "Jacob Zuma", "Thokozani Khupe", "Susan Blank", "Peter Piot", "Michel Sidib\u00e9"], "organizations": ["University of Birmingham", "Keele University", "World Health Organization", "Joint United Nations Programme on HIV/AIDS", "Bill & Melinda Gates Foundation", "American Academy of Pediatrics", "Royal Dutch Medical Association", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Health Law and Bioethics", "Social Justice", "Human Rights", "Informed Consent and Autonomy", "Gender Equity in Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7622bfc4a2b95ec3c7b942211aef6938618b845ff2305faa3103b6a411217903', 'Fox Short Changed Law Eth IJCR 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7622bfc4a2b95ec3c7b942211aef6938618b845ff2305faa3103b6a411217903.pdf', 'other', 'ingested', '{"date": "2005", "description": "This article examines the legal, ethical, and medical discourses surrounding routine neonatal male circumcision, arguing that the practice has historically escaped serious medico-legal scrutiny in Anglo-American contexts. Authors Marie Fox and Michael Thomson critique the persistent tendency in legal commentary and professional guidance\u2014including publications from the British Medical Association and the English Law Commission\u2014to minimize documented risks, infant pain, and complications while privileging parental discretion, cultural deference, and unsubstantiated or marginal health benefits.\n\nBy tracing the medical history of routine circumcision back to Victorian-era anxieties concerning masturbation, insanity, and class distinction, the authors demonstrate how the male infant foreskin was historically pathologized without rigorous clinical justification. They argue that contemporary law continues to construct male bodies as invulnerable and fails to recognize children as holders of present bodily integrity. Fox and Thomson conclude that the law should re-evaluate permissive standards, acknowledge circumcision as an infliction of unnecessary physical harm, and protect children''s bodily autonomy until they can make informed decisions for themselves.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Marie Fox", "Michael Thomson", "John Lewis A. Sayre", "Peter Charles Remondino", "Caroline Bridge", "David Benatar", "Michael Benatar"], "organizations": ["Keele University", "British Medical Association", "American Academy of Pediatrics", "Law Commission", "National Health Service"], "themes": ["Male Circumcision", "Children''s Rights", "Bodily Integrity", "Parental Autonomy", "Medical Ethics", "Legal Construction of Harm"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('872c18bbec5c8b49247ceb8dce0f80bf127a0e21f2989834c0f57ebd5c4e2942', 'Fox_Thomson_Bodily_Integrity_JLawSoc 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/872c18bbec5c8b49247ceb8dce0f80bf127a0e21f2989834c0f57ebd5c4e2942.pdf', 'legal_document', 'ingested', '{"date": "2017", "description": "This article proposes a legal and conceptual model called ''embodied integrity'' to restrict the extensive authority parents hold when making irreversible, non-therapeutic bodily decisions for young children. Focusing on the legal disparity between the strict prohibition of female genital cutting and the ongoing legal tolerance of male circumcision, the authors critique conventional, property-based notions of bodily integrity that reinforce mind/body dualisms and punitive frameworks. Drawing on the philosophical theories of Drucilla Cornell and Joel Feinberg, the authors argue that embodied integrity should take priority in legal ''best interests'' assessments to safeguard a child''s future self-determination and legal subjectivity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Marie Fox", "Michael Thomson", "Drucilla Cornell", "Joel Feinberg", "Margaret Brazier", "James Munby"], "organizations": ["University of Liverpool", "University of Leeds", "World Health Organization", "Royal Dutch Medical Association", "Council of Europe", "European Court of Human Rights"], "themes": ["Bodily Integrity", "Embodiment", "Parental Responsibility", "Children''s Rights", "Male and Female Genital Cutting", "Best Interests Standard", "Right to an Open Future"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('75beab5497e7581c769ecbf8b6200ee9211df596f0b6ddbdcce881837bb2bda6', 'Franz Studie zu Spätfolgen der Beschneidung HPD 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/75beab5497e7581c769ecbf8b6200ee9211df596f0b6ddbdcce881837bb2bda6.pdf', 'newspaper_clipping', 'ingested', '{"date": "2023-07-18", "description": "This document is a webpage printout from the Humanistischer Pressedienst (hpd) featuring a call for study participants regarding the long-term effects and consequences of male circumcision (''Studie zu Sp\u00e4tfolgen der Beschneidung''). The text also includes navigation elements and links to related articles covering topics such as COVID-19 vaccination perceptions, mental health impacts, and the relationship between religion and conspiracy beliefs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": [], "organizations": ["hpd", "Humanistischer Pressedienst"], "themes": ["Circumcision", "Medical Research", "Public Health", "COVID-19", "Religion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0042bd9420ae1c2770603ff33aed18bb4dac9f0a37570a8e34da43ac34b1bef1', 'Franz Study Late Effects Circumcision HPD 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0042bd9420ae1c2770603ff33aed18bb4dac9f0a37570a8e34da43ac34b1bef1.pdf', 'newspaper_clipping', 'ingested', '{"date": "2019-10-24", "description": "A research group at the University Hospital D\u00fcsseldorf, led by Prof. Dr. Matthias Franz and Peter Richter, is conducting the PRECK study (''Psychovegetative Reactivity of Adults after Circumcision in Childhood'') to examine the potential psychological and physical long-term consequences of medically unindicated boy circumcision. The study investigates physiological signals, such as ECG, through superficial skin measurements in a non-invasive experiment lasting 90 to 120 minutes.\n\nThe researchers are recruiting male participants aged 18 to 45 who were circumcised between the ages of 0 and 12, especially those who currently experience or suffer from late consequences related to the procedure. Participants are offered an expense allowance, with strict adherence to ethical and data privacy standards.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Matthias Franz", "Peter Richter"], "organizations": ["University of D\u00fcsseldorf", "University Hospital D\u00fcsseldorf", "Clinical Institute for Psychosomatic Medicine and Psychotherapy"], "themes": ["Male Circumcision", "Psychological Late Effects", "Clinical Research Recruitment", "Psychovegetative Reactivity", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0a7acea83fec40363362feacacebb60969c3e158e4614da8abf3afd951532c49', 'Freedman Beyond Benefits and Risks Peds 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0a7acea83fec40363362feacacebb60969c3e158e4614da8abf3afd951532c49.pdf', 'medical_journal', 'ingested', '{"date": "2016-04-06", "description": "In this commentary, Andrew L. Freedman reflects on the controversy surrounding the American Academy of Pediatrics'' (AAP) 2012 policy statement regarding newborn male circumcision. While the AAP concluded that the procedure''s health benefits outweigh its risks, Freedman notes that this was meant to justify parental access rather than recommend routine universal circumcision. He highlights that parental decisions are rarely purely clinical; instead, they are heavily driven by religious, cultural, familial, and aesthetic considerations where physicians lack exclusive moral authority.\n\nFreedman argues that no single scientific study will ever definitively settle the debate or override deeply held personal beliefs. Consequently, well-informed parents remain the best proxy decision-makers for their children. He urges medical professionals to focus on objective patient education and encourages anticircumcision advocates to engage in cultural persuasion rather than pursuing legal bans, ultimately advocating for a pluralistic society where diverse practices can coexist.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Andrew L. Freedman", "I. Sneppen", "J. Thorup"], "organizations": ["American Academy of Pediatrics", "Cedars Sinai Medical Center"], "themes": ["Newborn Male Circumcision", "Medical Ethics and Parental Autonomy", "Risk-Benefit Analysis in Medicine", "Cultural and Religious Traditions", "Pediatric Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b78d172f573116fb344c9c32ac7a0b39f63912956ebc7b3c550959aed72bca7d', 'Freeman Child''s right to circumcision BJUI 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b78d172f573116fb344c9c32ac7a0b39f63912956ebc7b3c550959aed72bca7d.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This academic article examines the legality and ethics of ritual male circumcision under English law and international human rights instruments, focusing on Jewish and Muslim traditions. The author argues that ritual male circumcision is lawful, distinct from female genital mutilation, and does not constitute child abuse or criminal assault. Applying the concept of ''future-oriented consent'' and provisions from the United Nations Convention on the Rights of the Child, the author contends that ritual circumcision upholds a child''s fundamental right to religious and cultural identity, concluding that the practice aligns with the child''s long-term best interests.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["M.D.A. Freeman", "Lord Templeman", "Lord Scarman"], "organizations": ["University College London", "United Nations", "House of Lords", "British Medical Association", "Australian College of Paediatrics"], "themes": ["Ritual Circumcision", "Children''s Rights", "Parental Consent", "Cultural and Religious Identity", "Best Interests Principle", "Medical Law and Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d3eeac0ff8249dced606a792c1cf9e7e72939dc216c7f829320b4fc8170e40ae', 'Frisch Earp Circumcision CDC GlobPubHlth 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d3eeac0ff8249dced606a792c1cf9e7e72939dc216c7f829320b4fc8170e40ae.pdf', 'medical_journal', 'ingested', '{"date": "2016-04-23", "description": "This article critically assesses the 2014 draft recommendations issued by the U.S. Centers for Disease Control and Prevention (CDC), which asserted that the preventive health benefits of non-therapeutic male infant circumcision outweigh its risks. Authors Morten Frisch and Brian D. Earp challenge this position, arguing that current empirical and scientific evidence does not justify circumcision as a routine public health measure in developed countries like the United States.\n\nThe authors identify several major flaws in the CDC and American Academy of Pediatrics (AAP) stances, including an over-reliance on adult trials conducted in sub-Saharan Africa, undue weight given to heavily biased literature, the omission of the anatomical and sexual functions of the prepuce, and a disregard for infant pain. Furthermore, they demonstrate that complication rates\u2014specifically meatal stenosis\u2014are severely underestimated by relying on short-term register data rather than clinical follow-up, concluding that any elective circumcision should be deferred until a child can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Brian D. Earp", "Brian J. Morris", "Andrew L. Freedman", "Kevin Pringle"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Canadian Paediatric Society", "Royal Australasian College of Physicians", "Statens Serum Institut", "The Hastings Center Bioethics Research Institute", "Circumcision Academy of Australia"], "themes": ["Male Circumcision", "Public Health Policy", "Risk-Benefit Assessment", "Surgical Complications", "Infant Pain and Ethics", "HIV and STI Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7170992d568ba276b6649c2d51df7104a98afc860eeed5bc35afe6d60f61e38e', 'Frisch High Freq Black Circ AIDSBehav 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7170992d568ba276b6649c2d51df7104a98afc860eeed5bc35afe6d60f61e38e.pdf', 'medical_journal', 'ingested', '{"date": "2015-11-25", "description": "This academic commentary discusses findings by Crosby et al. regarding HIV prevalence and sexual behavior among circumcised versus intact young Black men who have sex with men (MSM). The author highlights that circumcised men engaged in unprotected insertive anal sex at approximately twice the rate of intact men, an important finding that received little focus in the original study.\n\nThe author argues that this increased risk behavior has a plausible anatomical and sensory basis: circumcision removes sensitive erogenous tissue, and men experiencing diminished penile sensitivity may avoid condoms to prevent further desensitization. The commentary concludes that these findings add to growing evidence that male circumcision is unlikely to be an effective public health intervention for HIV prevention among MSM.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "R. A. Crosby"], "organizations": ["Statens Serum Institut", "Aalborg University", "Springer Science+Business Media"], "themes": ["Male Circumcision", "HIV Prevention", "Men Who Have Sex with Men (MSM)", "Penile Sensitivity", "Condom Use"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a1da2d5640aed85fb31a5498063aeedd2e9dae39ff8c64b2dc9c9197aa0e23f6', 'Frisch Lindholm male circumcision & function JIntEpidAdv 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a1da2d5640aed85fb31a5498063aeedd2e9dae39ff8c64b2dc9c9197aa0e23f6.pdf', 'medical_journal', 'ingested', '{"date": "2011-06-14", "description": "This cross-sectional, population-based study investigates the associations between male circumcision and sexual function among men and women in Denmark using national health survey data. While circumcised and uncircumcised individuals exhibited similar levels of sexual desire and overall sexual activity, circumcised men were three times more likely to experience frequent orgasm difficulties after adjusting for confounding factors.\n\nAmong women, having a circumcised spouse was significantly associated with higher rates of frequent sexual function difficulties, notably dyspareunia, orgasm difficulties, and incomplete fulfillment of sexual needs. The authors hypothesize that reduced penile sensitivity due to foreskin removal may contribute to these difficulties and suggest careful ethical consideration and further rigorous study regarding international male circumcision promotion programs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Morten Lindholm", "Morten Gr\u00f8nb\u00e6k", "Christian Graugaard"], "organizations": ["Statens Serum Institut", "National Institute of Public Health", "International Epidemiological Association", "Oxford University Press", "World Health Organization"], "themes": ["Male Circumcision", "Sexual Dysfunction", "Epidemiology", "Orgasm Difficulties", "Dyspareunia", "Public Health Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9e9d2b08814b63fc2b5b3ad461cf661c4ee27e69dad8fe9f5564615ff8662f81', 'Frisch PenileCancer Epid&Prevention 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9e9d2b08814b63fc2b5b3ad461cf661c4ee27e69dad8fe9f5564615ff8662f81.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This academic chapter provides an extensive epidemiological review of penile cancer, a rare malignancy that predominantly manifests as squamous cell carcinoma (SCC) on the glans or foreskin. Penile SCC largely arises through two distinct etiologic pathways: one associated with high-risk human papillomavirus (HPV) infection (chiefly HPV 16, present in approximately half of invasive cases) and an HPV-independent pathway frequently associated with chronic inflammation, lichen sclerosus, and pathological phimosis. While incidence has historically remained stable or slightly declined in developed nations, prognosis varies by subsite and clinical stage, with foreskin cancers demonstrating more favorable survival outcomes.\n\nThe author emphasizes primary prevention opportunities centered on modifiable risk factors rather than routine neonatal surgery. Strategies include implementing gender-neutral preadolescent HPV vaccination programs, promoting safe-sex practices to curb viral transmission, and mitigating pathological phimosis via non-traumatic foreskin management. Epidemiological analyses suggest that the apparent protective effect of childhood circumcision against penile cancer is primarily mediated through the avoidance of pathological phimosis rather than a reduced susceptibility to HPV acquisition.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "M J Thun", "M S Linet", "J S Cerhan", "D Schottenfeld"], "organizations": ["Oxford University Press", "National Cancer Institute", "Surveillance, Epidemiology, and End Results (SEER) Program", "Centers for Disease Control and Prevention (CDC)"], "themes": ["Penile Cancer Epidemiology", "Squamous Cell Carcinoma", "Human Papillomavirus (HPV)", "Pathological Phimosis", "Male Circumcision", "HPV Vaccination", "Cancer Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9c8456b39bb35519ec67189011e47c6414ea75e57ee8bc42939f8d90c94f0ac6', 'Frisch Ritual Circ Autism RoyalSocMed 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9c8456b39bb35519ec67189011e47c6414ea75e57ee8bc42939f8d90c94f0ac6.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This Danish national cohort study investigated the potential association between ritual male circumcision and the subsequent risk of autism spectrum disorder (ASD), hyperkinetic disorder, and asthma in boys aged 0 to 9 years. Analyzing register data for over 340,000 boys born between 1994 and 2003, the researchers found that circumcised boys had a 46% higher overall risk of developing ASD before age 10 compared to intact boys, with the risk being particularly pronounced for infantile autism before age five (HR = 2.06). \n\nAdditionally, circumcised boys in non-Muslim families showed an elevated risk of hyperkinetic disorder, while foreskin status showed no association with asthma. The authors hypothesize that early-life surgical trauma and severe pain from circumcision, which may alter stress response and sensory perception, could contribute to neurodevelopmental vulnerabilities, highlighting the need for further confirmatory studies given the global prevalence of non-therapeutic circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Jacob Simonsen"], "organizations": ["Statens Serum Institut", "Aalborg University", "The Royal Society of Medicine"], "themes": ["Ritual Circumcision", "Autism Spectrum Disorder", "Neonatal Pain and Trauma", "Pediatric Neurodevelopment", "Epidemiological Cohort Study"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('42632a3cfdf1be27d1fa72c0b23ff6d02db1fa20ef82465c389e50230623e792', 'Frisch Simonsen Circ HIV Denmark EurJEpid 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/42632a3cfdf1be27d1fa72c0b23ff6d02db1fa20ef82465c389e50230623e792.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This nationwide population-based cohort study examines whether non-therapeutic male circumcision performed in infancy or childhood provides long-term protection against HIV and other sexually transmitted infections (STIs) in adulthood. Analyzing health register records of 810,719 Danish-born non-Muslim males followed across up to 36 years (1977\u20132013), researchers compared STI and HIV incidence rates between circumcised and genitally intact males.\n\nThe findings revealed no statistically significant protective effect of early male circumcision against HIV or any specific STI. Instead, circumcised males demonstrated a 53% higher overall rate of hospital-diagnosed STIs, with statistically significant elevated risks specifically observed for anogenital warts and syphilis. The authors conclude that infant or childhood non-therapeutic circumcision does not offer protection against adult STIs or HIV, questioning the rationale of expanding voluntary medical circumcision programs to young male children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Jacob Simonsen"], "organizations": ["Statens Serum Institut", "Aalborg University", "World Health Organization", "President''s Emergency Plan For AIDS Relief"], "themes": ["Male Circumcision", "Sexually Transmitted Infections", "HIV Prevention", "Epidemiology", "Pediatric Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4bb5f4d40bf8c2d8fff36fa4f1145c6b46f9d43a8360e1ca983ceb5260923f6b', 'Frisch Simonsen meatal stenosis 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4bb5f4d40bf8c2d8fff36fa4f1145c6b46f9d43a8360e1ca983ceb5260923f6b.pdf', 'medical_journal', 'ingested', '{"date": "2016-11-30", "description": "This nationwide register-based cohort study conducted in Denmark from 1977 to 2013 investigates the association between non-therapeutic male circumcision, cultural background, and the risk of developing meatal stenosis and other urethral stricture diseases (USDs). The authors evaluated data across two cohorts: 4.0 million males of all ages categorized by cultural background (Muslim vs. ethnic Danish) and over 810,000 non-Muslim males aged 0\u201336 years classified by foreskin status.\n\nThe findings show that circumcised males and boys from culturally circumcising (Muslim) backgrounds faced significantly elevated risks of meatal stenosis and other USDs, with hazard ratios particularly high in boys under 10 years of age (HR exceeding 16 to 26 in various models for meatal stenosis). Population attributable fraction estimates suggest that in countries with high circumcision rates, such as the United States and Israel, approximately 80% to 94% of pediatric meatal stenosis cases may be attributable to circumcision. The authors conclude that circumcision removes natural penile protections provided by the foreskin, highlighting a substantial long-term surgical complication burden.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Jacob Simonsen"], "organizations": ["Statens Serum Institut", "Aalborg University", "Royal College of Surgeons of Edinburgh", "Royal College of Surgeons in Ireland"], "themes": ["Non-therapeutic Male Circumcision", "Meatal Stenosis", "Urethral Stricture Disease", "Pediatric Surgical Complications", "Epidemiology and Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('27e6187f552b503386a5a6a250667cb16a97752d5ce9941717f6d030d8ebd92d', 'Fusaschi Gendered Gen Mutilations IJIR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/27e6187f552b503386a5a6a250667cb16a97752d5ce9941717f6d030d8ebd92d.pdf', 'medical_journal', 'ingested', '{"date": "2022-03-04", "description": "This article conducts a genealogic deconstruction of the international discourse surrounding Female Genital Mutilation or Cutting (FGM/C), contrasting critical anthropological perspectives with the human rights framework popularized by organizations like the World Health Organization (WHO). The author argues that international policy has historically isolated non-Western female genital cutting from its broader cultural contexts and complementary male rites, categorizing it exclusively as violence against women and girls while ignoring parallel issues in Western biomedical practices. This selective production of knowledge has created an ideological divide between traditional practices labeled as barbaric and Western interventions framed as modern and empowering.\n\nTo bridge this analytical gap, the author proposes the unifying concept of ''Gendered Genital Modifications'' (GGMo), which includes FGM/C alongside male circumcision, intersex genital surgeries, gender reassignment surgeries, and genital cosmetic surgery. The paper emphasizes the need for an interdisciplinary and gendered ethnographic approach that interrogates power, consent, bodily integrity, and personal autonomy across all forms of genital modification, moving beyond essentialist binaries toward a deeper understanding of agency and subjectivity within the sex/gender system.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michela Fusaschi", "Michel Foucault", "Gayle Rubin", "Franziska Porges Hosken", "Rose Hayes", "Kathryn Morgan", "Eugenia Kaw", "Veena Das"], "organizations": ["World Health Organization", "United Nations", "UNICEF", "American Anthropological Association", "University of Rome 3", "European Institute for Gender Equality"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Gendered Genital Modifications (GGMo)", "Critical Anthropology", "Biomedicalization", "Human Rights vs. Cultural Relativism", "Bodily Integrity and Consent", "Male Circumcision", "Cosmetic Genital Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cd2bd88b97f0791d28331c0e1ed7e5d26c46efd7cbd81304b9ccf4cf51de2e41', 'Gairdner Fate of Foreskin BMJ 1949.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cd2bd88b97f0791d28331c0e1ed7e5d26c46efd7cbd81304b9ccf4cf51de2e41.pdf', 'medical_journal', 'ingested', '{"date": "1949-12-24", "description": "In this landmark medical paper, Douglas Gairdner examines the anatomy, development, and widespread practice of routine infant circumcision. He argues that the operation is frequently performed without critical medical justification or an understanding of normal penile embryology and anatomy. Presenting developmental and clinical observational data, Gairdner demonstrates that a non-retractable foreskin is a normal developmental stage in newborns and toddlers rather than an abnormal pathology requiring surgical intervention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Douglas Gairdner", "Grafton Elliot Smith", "R. H. Hunter", "G. A. Deibert"], "organizations": ["British Medical Journal", "United Cambridge Hospitals"], "themes": ["Circumcision", "Paediatric Surgery", "Penile Anatomy and Development", "Cultural and Historical Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a2a078924d3744d222bbdc2d135a1e567402fb8c5670892db4ecd2dd6519697d', 'Gaither Genital dissatisfaction circ men ArchSexBehav 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a2a078924d3744d222bbdc2d135a1e567402fb8c5670892db4ecd2dd6519697d.pdf', 'medical_journal', 'ingested', '{"date": "2016-09-13", "description": "This study characterizes male genital self-image and dissatisfaction across a nationally representative sample of 4,198 U.S. men using the 14-item Index of Male Genital Image (IMGI). The authors found that while a majority of men (85.9%) were satisfied with their genitals\u2014reporting highest satisfaction with the shape of the glans and lowest with flaccid penis length\u2014approximately 14.1% reported low genital satisfaction across all demographics.\n\nDemographic factors such as age, race, sexual orientation, income, and education were not significantly linked to genital dissatisfaction. However, men with low genital satisfaction were significantly less likely to be sexually active, had lower frequencies of intercourse, and reported significantly less penetrative vaginal intercourse and receptive oral sex, suggesting important clinical implications for male psychosocial and sexual health.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Thomas W. Gaither", "Isabel E. Allen", "E. Charles Osterberg", "Amjad Alwal", "Catherine R. Harris", "Benjamin N. Breyer"], "organizations": ["University of California, San Francisco", "GfK Group", "Springer Science+Business Media"], "themes": ["Genital Satisfaction", "Male Body Image", "Sexual Behavior", "Urology", "Psychosocial Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf5f79f71e0187ad4e9eb325e14eee78effc8685a770c8121850dd13783e7696', 'Gallagher Jew''s Penis MedHum 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf5f79f71e0187ad4e9eb325e14eee78effc8685a770c8121850dd13783e7696.pdf', 'medical_journal', 'ingested', '{"date": "2022-12-30", "description": "This article explores the contradictory and prejudicial representations of circumcision and Jewish male sexuality in eighteenth-century English print culture and medical discourse. The author argues that alongside enduring stereotypes of lechery and effeminacy, eighteenth-century culture fostered a specific obsession with sexual pathology linked to growing anxieties over venereal disease. Consequently, Jewish men were simultaneously depicted as predatory lechers and derided for penile deformities, diminutive size, and impotence. Circumcision was paradoxically viewed both as a cause of sexual dysfunction and as a prophylactic against infection.\n\nAnalyzing visual and literary works\u2014such as William Hogarth''s ''A Harlot''s Progress'', Alexander Pope''s anti-Curll satire, and the anti-Semitic propaganda surrounding the Jewish Naturalisation Act of 1753\u2014the study illustrates how circumcision functioned as a pseudo-scientific and ideological metonym. These representations pathologized the Jewish male body and reflected broader societal anxieties regarding Christian virility, demographic competition, and bodily corruption well before the emergence of nineteenth-century scientific racism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Noelle Gallagher", "William Hogarth", "Sander Gilman", "Herman Boerhaave", "Alexander Pope", "Edmund Curll", "John Marten", "Daniel Turner", "Robert Darby", "Dana Rabin"], "organizations": ["University of Manchester", "BMJ Publishing Group Limited", "British Museum", "Lewis Walpole Library, Yale University"], "themes": ["Anti-Semitism", "Circumcision", "Venereal Disease", "Eighteenth-Century Print Culture", "Masculinity and Impotence", "Sexual Pathology", "Jewish Naturalisation Act of 1753"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('920c1dd95de790277f1d9faf2ec70bd99374b5f752815c2afc0dafb5ddfa6035', 'Gallo Excess prepuce, prem ejac and circumcision ArabJUrol 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/920c1dd95de790277f1d9faf2ec70bd99374b5f752815c2afc0dafb5ddfa6035.pdf', 'medical_journal', 'ingested', '{"date": "2017-04-07", "description": "This study investigates the prevalence of an excessive prepuce among men with lifelong premature ejaculation (PE) and evaluates the therapeutic efficacy of distal circumcision as a definitive treatment. Among 352 patients diagnosed with lifelong PE, 59.1% presented with an excessive prepuce, suggesting that anatomical redundancy of the foreskin\u2014a highly innervated and sensitive tissue\u2014serves as an organic risk factor for PE via penile hypersensitivity.\n\nWhile only 13% of eligible patients consented to surgery, those who underwent distal circumcision (often combined with frenulectomy) experienced significant clinical improvements at 6 months post-operation. The mean intravaginal ejaculatory latency time (IELT) increased from 40.4 to 254 seconds, and mean Premature Ejaculation Diagnostic Tool (PEDT) scores decreased from 17 to 6.6. The author concludes that distal circumcision is an effective surgical intervention for carefully selected patients with lifelong PE and excessive prepuce, although caution is advised due to potential irreversible effects on penile sensitivity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Luigi Gallo"], "organizations": ["Arab Association of Urology", "Gallo Uro-Andrology Centre", "Elsevier"], "themes": ["Premature Ejaculation", "Excessive Prepuce", "Distal Circumcision", "Penile Hypersensitivity", "Andrology and Sexual Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('29f18c30a3b8d4c44f724a41095df25656c874d94b5fd7a81bd6dbedef0501ab', 'Ganczak Attitudes Circ Promotn Poland IntJEnviroResPubHlth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/29f18c30a3b8d4c44f724a41095df25656c874d94b5fd7a81bd6dbedef0501ab.pdf', 'medical_journal', 'ingested', '{"date": "2017-09-21", "description": "This study assesses the attitudes, beliefs, and willingness of final-year medical students in Szczecin, Poland, to promote male circumcision (MC) to adult men at risk for HIV. Conducted between 2013 and 2016 among 539 Polish and international students, the survey found that while overall HIV/AIDS knowledge was high, only 34.2% of respondents recognized that MC reduces HIV infection risk, and 54.8% declared they would recommend MC to adult patients at risk.\n\nStatistical analysis indicated that willingness to recommend the procedure was primarily predicted by the personal belief that circumcised men experience greater sexual pleasure (OR = 3.35) and the factual understanding that MC reduces HIV risk (OR = 2.13). The authors conclude that educational interventions are needed within medical curricula in traditionally non-circumcising regions to bridge knowledge gaps and replace personal biases with evidence-based information.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maria Ganczak", "Marcin Korze\u0144", "Maciej Olszewski"], "organizations": ["Pomeranian Medical University", "West Pomeranian University of Technology", "World Health Organization", "Joint United Nations Programme on HIV and AIDS", "American Academy of Pediatrics", "American Congress of Obstetricians and Gynecologists", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Medical Education", "Public Health Beliefs and Attitudes", "Healthcare Provider Recommendations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d6bf182f83a02084c592bae10d8b50c8adbff29969afc6e59744251f38e401e5', 'Ganiats Cost Utility MedDecMaking 1991.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d6bf182f83a02084c592bae10d8b50c8adbff29969afc6e59744251f38e401e5.pdf', 'medical_journal', 'ingested', '{"date": "1991", "description": "This study conducts a cost-utility analysis to assess the relative clinical and financial elements of routine neonatal circumcision. Using the General Health Policy Model and the Quality of Well-being (QWB) scale, the researchers evaluate several factors, including the cost and pain of the procedure alongside the long-term risks of urinary tract infections and penile cancer. The analysis calculated a net discounted lifetime dollar cost of $102 per individual and a net discounted lifetime health cost of 14 hours of healthy life.\n\nUltimately, the authors conclude that the economic and medical advantages and disadvantages of routine neonatal circumcision essentially cancel each other out. Because the quantifiable costs and benefits offset one another, clinical and parental decisions regarding the procedure must rely on factors beyond medical outcomes and cost-effectiveness.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Theodore G. Ganiats", "Jonathan B. C. Humphrey", "Howard L. Taras", "Robert M. Kaplan", "Gairdner", "Wiswell"], "organizations": ["University of California, San Diego School of Medicine", "American Academy of Pediatrics", "American College of Obstetrics and Gynecology", "Society of Teachers of Family Medicine", "Public Health Service"], "themes": ["Neonatal Circumcision", "Cost-Utility Analysis", "Healthcare Economics", "Quality of Well-being Scale", "Pediatric Health Policy", "Urinary Tract Infections"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d4082d64a71d91202fea6607a969c7aeb3a3c379cc9fbba6db0d3432ab443e2a', 'Garber Circular_Cut (thesis) 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d4082d64a71d91202fea6607a969c7aeb3a3c379cc9fbba6db0d3432ab443e2a.pdf', 'other', 'ingested', '{"date": "2013", "description": "This academic honors thesis critically evaluates the persistence and defense of routine neonatal male circumcision, particularly in the United States and within Jewish tradition. The author argues that the medical benefits attributed to the practice\u2014such as reduced risks of urinary tract infections, penile cancer, and HIV transmission\u2014are weak, non-generalizable, or insufficient to justify the irreversible amputation of healthy, functional tissue that causes acute pain and potential long-term sensory loss. The thesis posits that the medical community continually generates retroactive justifications to rationalize an ingrained cultural custom rather than basing the procedure on objective health needs.\n\nAdditionally, the document explores the historical and symbolic evolution of circumcision in Judaism, tracing its role from an ancient priestly fertility and lineage marker to an enduring symbol of identity reinforced by centuries of external Christian persecution and modern Zionist revival. Examining medicalization in the Anglophone world and recent European legal challenges, the author highlights double standards in how Western institutions condemn female genital cutting while defending male circumcision, concluding that dismantling routine neonatal circumcision will require financial defunding, reforming institutional medical guidelines, and shifting cultural perceptions of bodily normalcy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Shemuel Toviah Garber", "Ethan Kleinberg", "Douglas Gairdner", "Lewis Sayre", "John Harvey Kellogg", "James Beaney", "Howard Eilberg-Schwartz", "Leonard Glick", "Charlotte Knobloch"], "organizations": ["Wesleyan University", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "National Health Service", "Royal Dutch Medical Association", "Doctors Opposing Circumcision", "Central Conference of American Rabbis"], "themes": ["Neonatal Circumcision", "Medical Ethics and Bodily Integrity", "Jewish Ritual and Tradition", "Cultural Normalization", "Preventative Medicine Debate", "Female vs. Male Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('92619d142b5e40d80b7381d3c7d76afbc9761a52ffd12ac282cc7c27393a4784', 'Garcia-Mesa Sensory innervation AnatSocty 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/92619d142b5e40d80b7381d3c7d76afbc9761a52ffd12ac282cc7c27393a4784.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This study analyzes the sensory innervation and mechanoreceptor profile of the human male prepuce using tissue samples from 32 males aged 5 to 23 years. Utilizing immunohistochemistry and double immunofluorescence, the researchers identified that Meissner''s corpuscles are the predominant sensory corpuscles in the prepuce, exhibiting a marked increase in density and maturity from pre-puberty through puberty and post-puberty.\n\nNotably, the study demonstrates for the first time the presence of the mechanosensitive ion channel protein PIEZO2 within the axons of preputial Meissner''s corpuscles, genital end bulbs, and scattered Merkel cells. The preputial corpuscles share the structural and immunohistochemical profile of digital Meissner''s corpuscles\u2014including an endoneurial CD34-positive capsule and absence of a perineurial capsule\u2014suggesting that their mechanotransductive function and anatomical organization are conserved across different body sites.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Yolanda Garc\u00eda-Mesa", "Jorge Garc\u00eda-Piqueras", "Ram\u00f3n Cobo", "Jos\u00e9 Mart\u00edn-Cruces", "Iv\u00e1n Suazo", "Olivia Garc\u00eda-Su\u00e1rez", "Jorge Feito", "Jos\u00e9 A. Vega"], "organizations": ["Universidad de Oviedo", "Universidad Aut\u00f3noma de Chile", "Complejo Hospitalario Universitario de Salamanca", "Universidad de Salamanca", "Anatomical Society", "John Wiley & Sons Ltd"], "themes": ["Cutaneous Sensory Innervation", "Meissner''s Corpuscles", "PIEZO2 Mechanoreceptors", "Human Male Prepuce Anatomy", "Mechanotransduction and Somatosensation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a13fdb06bbed177ef3c05c8c6b7c5fd865dc68d1866892f95d3b338c0eaf38c8', 'Garenne Circumcision & HIV in Africa RevueInfir-FR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a13fdb06bbed177ef3c05c8c6b7c5fd865dc68d1866892f95d3b338c0eaf38c8.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This article critically evaluates the World Health Organization''s (WHO) 2007 recommendation endorsing voluntary medical male circumcision to curb HIV transmission in Southern Africa. While initial randomized clinical trials indicated that medical circumcision reduced short-term HIV incidence by approximately 50% over 18 to 24 months, extensive population-based demographic surveys (PHIA, DHS, and HSRC) indicate that long-term HIV prevalence among men aged 40\u201359 is virtually identical regardless of circumcision status or whether the procedure was performed medically or traditionally.\n\nThe authors conclude that short-term reductions observed in clinical trials fail to translate into general population efficacy over time due to repeated exposure and behavioral heterogeneity. Consequently, they question the medical, financial, and ethical justifications for dedicating extensive public health resources to mass circumcision campaigns within already strained African healthcare systems.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michel Garenne", "Nancy Stiegler", "Jean-Pierre Bouchard"], "organizations": ["World Health Organization", "Elsevier Masson SAS", "University of Western Cape", "University of the Witwatersrand", "Institut de recherche pour le d\u00e9veloppement", "Human Sciences Research Council", "Centre hospitalier de Cadillac"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Public Health Policy", "Demographic Surveys", "Epidemiology", "Global Health Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1142f0016215f6ccc5bd734cefb8608dbbd9e02cefb255265b1507d80d8f4a30', 'Garenne Circumcision & HIV in Africa RevueInfirm-EN 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1142f0016215f6ccc5bd734cefb8608dbbd9e02cefb255265b1507d80d8f4a30.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This article analyzes large-scale demographic survey data (DHS, PHIA, and HSRC) from eight southern African countries to examine the long-term relationship between male circumcision and HIV prevalence. While randomized controlled trials led the World Health Organization (WHO) to recommend voluntary medical male circumcision based on short-term incidence reductions, this study finds that among men aged 40\u201359, HIV seroprevalence is virtually identical regardless of circumcision status (circumcised vs. intact) or circumcision type (medical vs. traditional).\n\nThe authors argue that short-term trial efficacy does not translate into long-term population-level effectiveness, primarily because repeatedly exposed men eventually contract HIV regardless of circumcision status. Consequently, the paper challenges WHO recommendations and questions the ethical and practical justification of allocating scarce healthcare resources to mass circumcision campaigns in Africa.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michel Garenne", "Nancy Stiegler", "Jean-Pierre Bouchard"], "organizations": ["World Health Organization", "UNAIDS", "University of Western Cape", "University of the Witwatersrand", "Institut de Recherche pour le D\u00e9veloppement", "FERDI", "Universit\u00e9 d\u2019Auvergne", "Institut Psycho-Judiciaire et de Psychopathologie", "Centre hospitalier de Cadillac", "Human Sciences Research Council"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Public Health Policy", "Demographic Studies", "Healthcare Resource Allocation", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4c9d2ecdd7eb197eb2b393c434399ca92e87434e7ce064d7d0ecb4906cbed6d5', 'Garenne HIV-intact-&-circumcised-southern-africa JBiosocSci 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4c9d2ecdd7eb197eb2b393c434399ca92e87434e7ce064d7d0ecb4906cbed6d5.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This study analyzes the statistical relationship between male circumcision and HIV prevalence and incidence using Population-based HIV Impact Assessment (PHIA) survey data (2015\u20132017) across six Southern African countries: Eswatini, Lesotho, Malawi, Namibia, Zambia, and Zimbabwe. Evaluating men aged 20\u201359, the findings reveal that while circumcised men show lower relative risks of HIV infection at younger ages, this advantage disappears with age; by ages 50\u201359, relative risk does not significantly differ from 1.0 (RR = 0.923), and HIV prevalence is nearly identical across intact, medically circumcised, and traditionally circumcised men.\n\nThe author attributes the lower prevalence observed among younger medically circumcised men to demographic and socio-economic selection biases, noting that participants in Voluntary Medical Male Circumcision (VMMC) campaigns were disproportionately younger, wealthier, more educated, and urbanized. Concluding that circumcision shows no long-term demographic protective effect against HIV compared to consistent condom use, the study calls into question the scientific efficacy, cost-effectiveness, and ethical justification of mass VMMC public health campaigns.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michel Garenne"], "organizations": ["University of the Witwatersrand", "University of the Western Cape", "FERDI", "Universit\u00e9 d\u2019Auvergne", "Institut de Recherche pour le D\u00e9veloppement", "Cambridge University Press", "World Health Organization", "UNAIDS", "Columbia University"], "themes": ["HIV/AIDS Prevention", "Voluntary Medical Male Circumcision (VMMC)", "Epidemiology", "Public Health Policy", "Bioethics and Human Rights", "PHIA Surveys"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('daf30fbe96e06a87be2e0c79cd51aff7295891b6a4fd33292fce7365b72c5777', 'Geishecker Completely Unregul MaleCirc NewMale Studies 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/daf30fbe96e06a87be2e0c79cd51aff7295891b6a4fd33292fce7365b72c5777.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This article examines the lack of safety standards, clinical oversight, and legal regulation surrounding non-therapeutic infant male circumcision in both clinical and ritual settings. The author argues that despite posing significant risks of surgical morbidity, lifelong trauma, and loss of functional tissue, circumcision is increasingly protected or ''enshrined'' in law under the guise of religious freedom and parental authority, contrasting sharply with universal legal prohibitions against female genital cutting.\n\nThe author critiques the permissive medical milieu in the United States and abroad, highlighting issues such as inadequately trained practitioners, minimal use of effective anesthesia, unmonitored complication rates, and short statutes of limitations that bar victims from seeking civil remedies. The paper contends that genuine bioethical review and assessment of long-term surgical harm must ethically precede blanket legal protections for non-consensual genital cutting of minors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["John V. Geisheker", "Angela Merkel", "M. David Gibbons"], "organizations": ["Australian Institute of Male Health and Studies", "Doctors Opposing Circumcision (DOC)", "American Academy of Pediatrics", "Royal Dutch Medical Association (KNMG)", "Tasmania Law Reform Institute", "German Bundestag"], "themes": ["Male Circumcision", "Human Rights and Bodily Integrity", "Medical Regulation and Morbidity", "Bioethics and Proxy Consent", "Religious Freedom versus Child Protection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('33e611c5f7c53106866fbbd34f74fcb7e58f5f874cd4dfbea1c21e591b0cd77e', 'Geisheker GREATEST DANGER PsychToday 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/33e611c5f7c53106866fbbd34f74fcb7e58f5f874cd4dfbea1c21e591b0cd77e.pdf', 'other', 'ingested', '{"date": "2011-10-23", "description": "This article highlights the dangers of Premature Forcible Foreskin Retraction (PFFR), identifying it as one of the most common and harmful medical interventions inflicted on intact young boys during routine well-baby examinations. The authors explain that at birth, the foreskin and glans are naturally fused by the balano-preputial lamina, which typically separates gradually on its own over the course of childhood and often into adolescence. Forcibly pulling the foreskin back causes severe pain, bleeding, lacerations, infection, and subsequent scarring, which frequently leads to acquired secondary phimosis.\n\nThe document traces the persistence of this harmful practice to 19th-century Victorian medical myths, particularly the debunked theory of ''reflex neurosis,'' which encouraged aggressive genital hygiene to prevent disease and discourage masturbation. Despite clear warnings from organizations like the American Academy of Pediatrics and modern evidence-based research establishing non-retraction as normal anatomy, many healthcare providers continue to erroneously advise or perform forcible retraction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Darcia Narvaez", "John V. Geisheker", "George C. Denniston", "Mark D. Reiss", "Morris R. Sorrels", "Robert S. Van Howe"], "organizations": ["Doctors Opposing Circumcision", "American Academy of Pediatrics", "Psychology Today"], "themes": ["Premature Forcible Foreskin Retraction (PFFR)", "Pediatric Genital Anatomy and Development", "Medical Malpractice and Ignorance", "Phimosis and Scarring", "History of Medicine and Reflex Neurosis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('de1e9d45efb66518de031127693649e5606b32e72a7df4edc51b59163e04656b', 'Geisheker WHY CONTINUE HARM PsychToday 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/de1e9d45efb66518de031127693649e5606b32e72a7df4edc51b59163e04656b.pdf', 'other', 'ingested', '{"date": "2011-10-30", "description": "This article criticizes the widespread ignorance among U.S. medical providers regarding natural male infant anatomy and the harmful practice of forcibly retracting the foreskin. The authors argue that American medical training relies on obsolete Victorian myths and fails to teach normal preputial development, frequently misidentifying natural developmental fusion as phimosis and using unfounded hygiene concerns to promote circumcision. They assert that forced retraction causes scarring and introduces infections that are falsely attributed to keeping boys intact.\n\nTo prevent injury and unnecessary surgical intervention, the authors advocate an evolutionary perspective of ''benign neglect'' under the guideline ''Only Clean What is Seen.'' They advise parents to actively protect their intact sons from medical tampering, insist on a strict hands-off policy during examinations, and allow the foreskin to separate naturally without forced intervention until the child is old enough to retract it himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Darcia Narvaez", "John V. Geisheker", "George C. Denniston", "Mark D. Reiss", "Morris R. Sorrels", "Robert S. Van Howe", "Robert Darby"], "organizations": ["Psychology Today", "Doctors Opposing Circumcision"], "themes": ["Infant Male Anatomy", "Forced Foreskin Retraction", "Circumcision Critique", "Medical Education Deficiencies", "Pediatric Hygiene", "Patient Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ebf1776577eb42d123ea0ce9f1a8bbb16009413d979c0964b7b94b57af6fbb4b', 'Giami Hybrid forum GlobPubHlth 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ebf1776577eb42d123ea0ce9f1a8bbb16009413d979c0964b7b94b57af6fbb4b.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This article analyzes the social and political processes leading up to the 2007 WHO and UNAIDS technical consultation in Montreux, Switzerland, which officially recommended male circumcision as an HIV prevention intervention across 16 hyperendemic African countries. Applying theoretical frameworks from Science and Technology Studies (STS), particularly Callon''s concept of a ''hybrid forum'' versus Riles''s concept of a ''network'', the authors investigate whether the consultation constituted a genuinely open, participatory deliberative arena or merely an instrument to legitimize a predetermined policy.\n\nThe authors conclude that the Montreux consultation failed to meet the criteria of a hybrid forum due to limited openness, the exclusion or marginalization of opposing scientific viewpoints and social scientists, and an absence of genuine debate regarding the efficacy and broader cultural consequences of the intervention. Instead, the consultation operated through a well-established, informal network of epidemiologists, biomedical researchers, and international agency bureaucrats who orchestrated the trials, set the agenda, and utilized the meeting primarily to ratify and strategize the implementation of evidence-based public health policy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alain Giami", "Christophe Perrey", "Andr\u00e9 Luiz de Oliveira Mendon\u00e7a", "Kenneth Rochel de Camargo", "Robert C. Bailey", "Daniel T. Halperin", "Bertran Auvert", "Ronald H. Gray", "Catherine Hankins", "Gary Dowsett", "Kevin De Cock", "Jean-Fran\u00e7ois Delfraissy"], "organizations": ["World Health Organization", "UNAIDS", "Inserm", "Rio de Janeiro State University", "United States Agency for International Development", "Agence Nationale de Recherche sur le SIDA", "Bill and Melinda Gates Foundation", "World Bank", "UNICEF"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Science and Technology Studies", "Evidence-Based Public Health Policy", "Hybrid Forums vs. Networks", "Randomized Controlled Trials"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e09af4c10bcf9b00376ca30ce8e3cf802e93e94bc83f00c1ad8e48b027a82fb5', 'Giami Sexual_Justice_Future_of_Sexual Rights IJSexHealth 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e09af4c10bcf9b00376ca30ce8e3cf802e93e94bc83f00c1ad8e48b027a82fb5.pdf', 'medical_journal', 'ingested', '{"date": "2026-04-19", "description": "This position paper introduces sexual justice as a transformative framework designed to address systemic inequalities, structural violence, and moralistic or colonial oppression that shape global experiences of sexuality, health, and rights. Grounded in declarations by the World Association for Sexual Health (WAS) and genealogies of feminist, LGBTIQ+, HIV, sex worker, and Indigenous movements, the authors argue that conventional liberal rights frameworks are insufficient because they often emphasize individual protections without rectifying root structural inequities.\n\nThe document articulates a call to action anchored in transformative, distributive, and reparative justice, emphasizing intersectionality, bodily autonomy, dignity, and sexual pleasure. It outlines concrete recommendations across policy, healthcare, education, and international funding\u2014advocating for legal decriminalization, equitable resource redistribution, non-pathologizing and community-led care, and institutional accountability to realize sexual health and rights as lived realities for marginalized populations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alain Giami", "Esther Corona", "Lisa Welsh", "Ricardo Hernandez Forcada", "Zahra Stardust", "Md. Sharful Islam Khan", "Magaly Pirotte", "Richard G. Parker", "Shereen El Feki", "Amaranta G\u00f3mez Regalado", "Denise Medico", "Agata Loewe Kurilla", "Luis Perelman", "Ren\u00e9 de Klerk", "Erick Janssen", "Pedro Nobre", "Elna Rudolph"], "organizations": ["World Association for Sexual Health", "Institut National de la Sant\u00e9 et de la Recherche M\u00e9dicale", "World Health Organization", "United Nations Population Fund", "International Planned Parenthood Federation", "UNESCO", "UNAIDS"], "themes": ["Sexual Justice", "Sexual and Reproductive Health and Rights (SRHR)", "Intersectionality", "Bodily Autonomy and Pleasure", "Transformative and Reparative Justice", "Decriminalization and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5320403038c48e94f7e87c3b7c070314296bde6ff6719f2f425b8026fdfb5f80', 'Gianetti AAP Misconduct Trade Assn Iowa Law Rev 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5320403038c48e94f7e87c3b7c070314296bde6ff6719f2f425b8026fdfb5f80.pdf', 'legal_document', 'ingested', '{"date": "2000", "description": "This legal note critically examines the American Academy of Pediatrics'' (AAP) policy statements on routine neonatal male circumcision, specifically focusing on the 1989 and 1999 task force reports. The author argues that the AAP failed to adhere to sound scientific methodology by relying on flawed studies to assert questionable medical benefits\u2014such as reductions in urinary tract infections, sexually transmitted diseases, and penile cancer\u2014while systematically ignoring or downplaying surgical risks, complication rates, infant trauma, and the physiological functions of the foreskin.\n\nDrawing upon tort principles under Section 324A of the Restatement (Second) of Torts and the legal precedent of Snyder v. American Ass''n of Blood Banks, the author argues that medical trade associations should be held legally liable for the negligent promulgation of clinical practice guidelines. Because physicians and parents rely on AAP standards to make medical decisions, the author contends that imposing liability would enforce scientific accountability and protect infants from foreseeable surgical harms.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Matthew R. Giannetti", "Dustin Evans, Jr.", "Douglas Gairdner", "Thomas E. Wiswell", "Edward Wallerstein", "William Snyder", "Troyen A. Brennan", "Arnold J. Rosoff"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "American Association of Blood Banks", "Canadian Paediatric Society", "American Cancer Society", "University of Iowa College of Law"], "themes": ["Neonatal Circumcision", "Trade Association Liability", "Medical Malpractice and Tort Law", "Scientific Misconduct and Research Methodology", "Informed Consent", "Standard of Care and Practice Guidelines"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('37d83a80a28b5969212fcaeb11c0b965c2fbce19fead91593f6e73bc5eeaa9f0', 'Glass Forced_circumcision_of_men JME_2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/37d83a80a28b5969212fcaeb11c0b965c2fbce19fead91593f6e73bc5eeaa9f0.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This article examines the forced circumcision of men as an overlooked and severe human rights violation occurring across various global contexts, including ethnic conflict, war, forced religious conversion, and traditional tribal initiation rituals. Drawing on documented accounts from countries such as Kenya, South Africa, Indonesia, Iraq, Uganda, and others, the author details the physical, psychological, and communal trauma inflicted on non-consenting adult males and youth.\n\nThe author argues that forced circumcision and forcibly stripping individuals to examine their genital status are inherently violent and indecent, contending they should be legally classified and prosecuted as sexual assault or sexual violence rather than minimized as mere ''inhumane acts.'' Furthermore, when committed in armed conflict or civil unrest, such practices should be recognized as sexual terrorism and war crimes. The paper emphasizes the absolute necessity of genuine consent, warning against coercion in voluntary public health male circumcision campaigns and arguing that cultural or religious traditions cannot justify non-consensual bodily violations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michael Glass", "Julian Savulescu", "Brian Earp", "Daniel Sidler", "Margaret Somerville", "Luis Moreno-Ocampo", "Brigid Inder", "Judith Okal", "Agnes Leina", "Mwelo Nonkonyana", "Bonani Yamani", "Peter Jacob", "Masenyani Mandhalele"], "organizations": ["Journal of Medical Ethics", "UNAIDS", "International Criminal Court", "Women''s Initiatives for Gender Justice", "Federation of Women Lawyers in Kenya", "Center on Violence Against Women in Kenya", "Kenyan Human Rights Commission", "Congress of National Traditional Leaders of South Africa", "Vishwa Hindu Parishad", "United States Commission on International Religious Freedom", "Ugandan Foundation for Human Rights Initiative"], "themes": ["Forced Circumcision", "Human Rights Violations", "Sexual Assault and Gender-Based Violence", "War Crimes and Sexual Terrorism", "Bodily Integrity and Informed Consent", "Ethnic and Religious Conflict", "Traditional Initiation Rites"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('27f6571b6ce2d1fe200b5e255754f7569383ec06b590df57a655cfcec78e4f47', 'Godwin-Earp Paradox-of-medical-necessity ClinEth 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/27f6571b6ce2d1fe200b5e255754f7569383ec06b590df57a655cfcec78e4f47.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This editorial introduces a special issue of Clinical Ethics examining the concept of ''medical necessity,'' a term frequently invoked to justify clinical decisions, healthcare coverage, and legal exceptions. Authors Samantha Godwin and Brian D. Earp argue that despite its widespread use and perceived normative force, ''medical necessity'' lacks a clear, non-circular, and conceptually sound definition. It frequently suffers from either recursive definition (referencing terms like ''normal functioning'' or ''disease'') or overbreadth (equating to general human welfare), often acting as a rhetorical intensifier in bioethical and policy debates concerning topics such as abortion and aging.\n\nTo move forward, the authors outline a framework centered on three core questions: clarifying what constitutes medical necessity conceptually, understanding what rhetorical and practical functions the term serves in various settings, and determining what normative implications should properly follow when an intervention is deemed medically necessary.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Samantha Godwin", "Brian D Earp", "Ben Davies", "Emma Prendergast", "John Ioannidis"], "organizations": ["Yale Law School", "University of Oxford", "Uehiro Centre for Practical Ethics", "National Health Service"], "themes": ["Medical Necessity", "Bioethics", "Healthcare Resource Allocation", "Conceptual Analysis", "Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dc7853f67a4f43fe98f5af163e4aae5411f20c26c6d00026469716818dd4662b', 'Goksan fMRI reveals neural activity eLife 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dc7853f67a4f43fe98f5af163e4aae5411f20c26c6d00026469716818dd4662b.pdf', 'medical_journal', 'ingested', '{"date": "2015-04-21", "description": "This study uses functional magnetic resonance imaging (fMRI) to map neural responses to acute noxious stimulation in healthy newborn infants and compare them directly to adult pain processing. Historically, infant pain has been undertreated due to the belief that neonates lack the cortical mechanisms necessary to experience the affective and sensory dimensions of pain. The researchers applied pinprick stimulation to the foot and discovered that 18 of the 20 brain regions activated in adults\u2014including areas encoding sensory and affective components like the anterior cingulate cortex and thalamus\u2014were also significantly active in neonates.\n\nWhile infants did not display activation in the amygdala or orbitofrontal cortex, suggesting an absence of complex emotional evaluation or anticipation of pain, their overall activation patterns closely mirrored those of adults. Furthermore, infants exhibited widespread nociceptive brain activity at much lower stimulus thresholds than adults, demonstrating heightened sensitivity. These findings indicate that newborn infants possess the neural capacity to experience pain in a manner remarkably similar to adults, underscoring the vital need for adequate clinical analgesia and effective pain management in neonatal care.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sezgi Goksan", "Rebeccah Slater", "Caroline Hartley", "Irene Tracey", "Mark Jenkinson", "Stuart Clare", "Eleri Adams"], "organizations": ["University of Oxford", "Oxford Centre for Functional Magnetic Resonance Imaging of the Brain (FMRIB)", "John Radcliffe Hospital", "Wellcome Trust", "Medical Research Council (MRC)", "National Health Service (NHS)"], "themes": ["Infant Pain Perception", "Functional Magnetic Resonance Imaging (fMRI)", "Nociceptive Processing", "Neonatal Pain Management", "Neurodevelopment and Cortical Organization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('38fd93aa9bba15e23caf582036c885d606175d03618f784abfffd91e362e0709', 'Goldman CircPolicy PaedChildHelath 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/38fd93aa9bba15e23caf582036c885d606175d03618f784abfffd91e362e0709.pdf', 'medical_journal', 'ingested', '{"date": "2004", "description": "This article examines how nontherapeutic neonatal circumcision policies in English-speaking countries, particularly within the American Academy of Pediatrics (AAP), are influenced by psychosocial, cultural, and religious factors rather than purely objective evidence. The author argues that personal physician biases\u2014such as gender, personal circumcision status, cognitive dissonance from performing the procedure, and fear of being labeled religiously intolerant\u2014have hindered evidence-based assessments and led to compromise-driven policy statements that tolerate the practice despite a lack of established safety and therapeutic necessity.\n\nTo improve the objectivity and ethical standing of future medical guidelines, the author recommends openly acknowledging these implicit psychosocial dynamics. Proposed measures include treating circumcision status and clinical practice history as potential conflicts of interest requiring disclosure, broadening committee composition to include more women and specialists in ethics and the social sciences, and considering legal liabilities regarding medically negligent recommendations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ronald Goldman"], "organizations": ["Circumcision Resource Center", "American Academy of Pediatrics", "Canadian Paediatric Society", "American Medical Association", "Royal Australasian College of Physicians", "British Medical Association", "United States Department of Health and Human Services"], "themes": ["Neonatal Circumcision", "Health Policy and Ethics", "Psychosocial Bias in Medicine", "Evidence-Based Medicine", "Conflict of Interest Disclosure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d91e914e7d6dec145f83e5b372ebbe98f9cb751fae7d947f1fec0141a8fa1861', 'Goldman Growing Jewish Circ Debate Kluwer 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d91e914e7d6dec145f83e5b372ebbe98f9cb751fae7d947f1fec0141a8fa1861.pdf', 'other', 'ingested', '{"date": "2004", "description": "This chapter examines the emerging debate over infant male circumcision within the Jewish community, offering a psychosocial analysis of the arguments between critics and traditional advocates. The author highlights medical, psychological, and ethical evidence concerning neonatal pain, trauma, and bodily autonomy, while analyzing how defenders of circumcision rely heavily on divine commandment, cultural identity, and rationalized health benefits to justify the practice.\n\nApplying psychological concepts such as cognitive dissonance, closed belief systems, and denial, Goldman argues that advocates often dismiss empirical evidence and reinterpret infant suffering to preserve core religious and cultural cognitions. He also refutes accusations that Jewish circumcision critics are motivated by anti-Semitism or self-hatred, emphasizes the growing role of mothers in challenging the procedure, and critiques how religious sensitivities unduly influence broader medical policies in the United States and other Western nations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Ronald Goldman", "Jon Levenson", "Daniel Gordis", "Rivy Kletenick", "Lisa Braver Moss", "Esther Raul-Friedman", "Donald Tam", "Lawrence Hoffman"], "organizations": ["Circumcision Resource Center", "Council of Jewish Federations", "American Academy of Pediatrics", "General Medical Council"], "themes": ["Jewish Circumcision Debate", "Psychosocial Critique", "Cognitive Dissonance and Denial", "Infant Pain and Trauma", "Religious Tradition vs. Bodily Autonomy", "Cultural and Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e4e8542daa6aab5fea0604e5140d8859da355b3cd78d49f6bac46305200ff7f6', 'Goldman Psych Impact BJUI 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e4e8542daa6aab5fea0604e5140d8859da355b3cd78d49f6bac46305200ff7f6.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This academic article examines the psychological motivation for and consequences of non-religious neonatal male circumcision, focusing predominantly on practices in the United States. It refutes historical medical beliefs that newborns do not experience significant pain, presenting empirical evidence that the procedure induces severe pain, substantial physiological stress, and behavioral disruptions that can impair early parent-infant bonding.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R. Goldman"], "organizations": ["Circumcision Resource Center", "American Academy of Pediatrics", "BJU International"], "themes": ["Male circumcision", "Neonatal pain response", "Pediatric anesthesia", "Psychological impact", "Parent-infant bonding"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c7ff77aab6700fc39583618bd3e5191b63cdea5901e3855ef36258c89f7119de', 'Gollaher Ritual to Science JSocHist 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c7ff77aab6700fc39583618bd3e5191b63cdea5901e3855ef36258c89f7119de.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This document citation represents an academic article titled ''From ritual to science: The medical transformation of circumcision in America'' by David L. Gollaher, published in the Journal of Social History in 1994. The work examines the historical transition and medicalization of circumcision in the United States, tracing how a traditional religious and cultural ritual evolved into a standard medical and scientific procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David L. Gollaher"], "organizations": ["Journal of Social History", "ProQuest"], "themes": ["Circumcision", "Medicalization", "History of Medicine", "Ritual to Science"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3a01f6ede3bb47542bd6f74ac829950bf63ba7ba0d11e589b5e6d4ad54c1679d', 'Gomez Rights_of_Children_Pragmatics (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3a01f6ede3bb47542bd6f74ac829950bf63ba7ba0d11e589b5e6d4ad54c1679d.pdf', 'other', 'ingested', '{"date": null, "description": "This paper analyzes the bioethical and legal tensions surrounding non-therapeutic infant male circumcision (IMC), evaluating whether parental proxy consent violates a child''s rights under frameworks like the United Nations Convention on the Rights of the Child (UNCRC). The author defends the ''open-future'' argument, maintaining that unnecessary, irreversible bodily modifications should be delayed until a child reaches ''religious maturity''\u2014defined as possessing the rational capacity to consciously practice, rather than merely belong to or profess, a religion.\n\nWhile concluding that a ban on infant male circumcision is ethically justified in principle, the author warns against heavy-handed blanket prohibitions due to pragmatic realities. Drawing parallels to female genital mutilation as a collective action problem, the paper argues that an immediate total ban risks pushing the practice underground and ostracizing children. Instead, the author advocates for pragmatic, localized municipal regulation that strictly enforces anesthesia, bans high-risk practices like Metzitzah B''Peh, and cautiously evaluates communal tolerance to protect overall child welfare.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Joseph Mazor", "Robert Darby", "Allan J. Jacobs", "Kavita Shah Arora", "Eliyahu Unger-Sargon", "Eldar Sarajlic", "Hanoch Ben-Yami", "Rabbi David Niederman"], "organizations": ["Cologne District Court", "United Nations"], "themes": ["Infant Male Circumcision", "Children''s Rights", "Bodily Integrity", "Right to an Open Future", "Religious Freedom vs. Autonomy", "Medical Ethics and Proxy Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bba6751e8be36c721363c05ecfad7d7c0e8f7536da96e7a162bdfa630cf37b32', 'Goodman Jewish Perspective BJUI 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bba6751e8be36c721363c05ecfad7d7c0e8f7536da96e7a162bdfa630cf37b32.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This article presents a medical, ethical, and psychosocial critique of neonatal Jewish ritual circumcision (Brit Milah). Presenting physiological evidence, the author highlights that circumcision inflicts acute pain and neurodevelopmental trauma on neonates, carries documented surgical risks, and lacks substantiated preventive medical necessity. The paper also examines the psychological distress experienced by mothers and the historical conflation of the practice with communal belonging and survival.\n\nDrawing upon Jewish texts and legal principles such as Pikuach Nefesh (the imperative to preserve human life) and Tsa''ar ba''alei chayyim (compassion for living beings), the author argues that Jewish ethics inherently support re-evaluating the tradition. Goodman concludes that cultural customs evolve and suggests transitioning toward non-violent, symbolic welcoming ceremonies that protect infant bodily integrity while preserving Jewish identity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. Goodman", "Paul Fleiss", "Maimonides", "Jonathan Sacks"], "organizations": ["BJU International", "University College London", "British Broadcasting Corporation (BBC)"], "themes": ["Ritual Circumcision", "Infant Pain and Trauma", "Jewish Law and Ethics", "Cultural Evolution", "Pediatric Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('48f0e9132c3e8c2284102587001a7961ae053527861ed361597a06f7dcbd50b5', 'Gordon Reconcile FGC with HR DevWorldBioeth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/48f0e9132c3e8c2284102587001a7961ae053527861ed361597a06f7dcbd50b5.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article examines the ethical and cultural conflict surrounding female genital circumcision (FGC) and proposes a mediating framework to reconcile a limited form of the practice with universal human rights. Grounding the analysis in a ''moderate human rights'' approach and cultural sensitivity, the author argues that human rights need not be seen as absolutist, nor cultural sensitivity as extreme relativism. While recognizing that most current forms of FGC cause severe harm and violate rights to bodily integrity and autonomy, the author contends that the least invasive procedure\u2014specifically the removal of the clitoral foreskin\u2014can be ethically permissible under strictly defined limiting conditions.\n\nThese essential limiting conditions require that the procedure be medicalized (performed by licensed medical professionals using sterile instruments and proper anesthesia) and strictly voluntary. The author emphasizes that autonomous individual informed consent is paramount, proposing a minimum maturity age of 16, and insists that communities eliminate social coercion, pressure, and socio-political disadvantages against girls and women who choose not to undergo the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["John-Stewart Gordon", "Jerome Bickenbach", "Ruth Macklin", "B\u00e9n\u00e9zet Bujo", "Kavita Shah Arora", "Allan J. Jacobs"], "organizations": ["Vytautas Magnus University", "United Nations General Assembly", "United Nations Population Fund", "World Health Organization", "John Wiley & Sons Ltd"], "themes": ["Female Genital Circumcision", "Universal Human Rights", "Cross-Cultural Bioethics", "Cultural Sensitivity", "Individual Informed Consent", "Bodily Integrity and Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d4530708c9ddfca1696ee995c5785fbca09811fd4965a564db8c97d9155b314c', 'Gore Analysis_Western_Discourses_on_GC (paper) 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d4530708c9ddfca1696ee995c5785fbca09811fd4965a564db8c97d9155b314c.pdf', 'other', 'ingested', '{"date": "2010-12-24", "description": "This academic paper critiques Western discourses surrounding female genital cutting (FGC) and male genital cutting (MGC), arguing that condemnation of FGC and acceptance of MGC are shaped by cultural bias rather than objective scientific fact. The author contends that biomedical discourse frames MGC in terms of medical benefits while pathologizing FGC as traditional and oppressive, despite both practices sharing variable severities and similar cultural justifications.\n\nFurthermore, the paper examines how Western medicine functions as a cultural system that permits female genital modifications when they conform to Western norms\u2014such as infant genital normalizing surgeries on intersex children\u2014while condemning similar non-Western practices. The author asserts that this double standard reflects a colonial dichotomy between ''civilized science'' and ''uncivilized tradition,'' calling for anthropologists and researchers to examine Western cultural ethnocentrism when analyzing genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Toni Gore", "Colleen McVeigh", "Ellen Gruenbaum", "Carla Obermeyer", "Janice Boddy", "Fuambai Ahmadu", "Robert Darby", "J. Steven Svoboda", "David L. Gollaher", "Cheryl Chase", "Kirsten Bell"], "organizations": ["World Health Organization", "UNAIDS", "UNDP", "UNESCO", "UNFPA", "UNHCR", "UNICEF", "Films for the Humanities and Social Sciences"], "themes": ["Female Genital Cutting (FGC)", "Male Genital Cutting (MGC)", "Cultural Relativism and Ethnocentrism", "Medicalization and Colonialism", "Intersex Genital Normalizing Surgery", "Anthropology of the Body and Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d8db5ab04bf76e80cf032fd8dbdbde2efac76bd7484820f513689234d97321cf', 'Grande Hegemonic_Human_Rights Arc Ant Med 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d8db5ab04bf76e80cf032fd8dbdbde2efac76bd7484820f513689234d97321cf.pdf', 'other', 'ingested', '{"date": "2009", "description": "This academic paper examines the double standards underlying the Western-dominated international human rights discourse regarding bodily modifications. Author Elisabetta Grande critiques the selective framing of female circumcision (FC) as an intolerable human rights violation and patriarchal crime, while male circumcision (MC) and female breast augmentation (BA) are normalized, institutionalized, and legally protected in countries like the United States and Italy. By analyzing health risks, anatomical effects on sexual satisfaction, and notions of consent, Grande demonstrates that non-infibulating forms of FC carry health and sensory risks comparable to routine male circumcision and cosmetic breast surgery.\n\nGrande argues that Western critiques rely on Orientalist narratives and ''positional superiority,'' creating a false dichotomy between ''savage'' non-Western practices and ''civilized'' Western choices. Instead of attributing FC solely to patriarchal oppression and the denial of female sexuality, she highlights its anthropological function in group identity, social solidarity, and gender construction\u2014dynamics equally present in Western cosmetic surgeries driven by societal beauty standards and economic interests. Advocating for an ''integrative comparison'' informed by comparative law and anthropological immersion, the author calls for the elimination of ethnocentric double standards and a genuine commitment to multiculturalism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Elisabetta Grande", "Edward Said", "Laura Nader", "Richard A. Shweder", "Nahid Toubia", "Anika Rahman", "Carla M. Obermeyer", "Jomo Kenyatta"], "organizations": ["World Health Organization", "United Nations", "Food and Drug Administration"], "themes": ["Female Circumcision", "Human Rights Discourse", "Comparative Law", "Multiculturalism", "Gender Identity Construction", "Western Hegemony and Ethnocentrism", "Male Circumcision", "Cosmetic Breast Augmentation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ed6292d3087ace5ccc5617c4bcac8866f9c70feaa1e3ec16803bd03b7ee65d1a', 'Green Circ HIV Prev Insufficient AmJPrevMed 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ed6292d3087ace5ccc5617c4bcac8866f9c70feaa1e3ec16803bd03b7ee65d1a.pdf', 'medical_journal', 'ingested', '{"date": "2010-11-01", "description": "This article critically examines recommendations to rapidly scale up mass male circumcision as an HIV prevention strategy in sub-Saharan Africa following three randomized controlled clinical trials. The authors argue that while the trials demonstrated short-term efficacy, their external validity is severely compromised in real-world settings due to factors such as ungeneralizable trial conditions, lack of direct protection for women, and surgical complication risks that could strain local healthcare infrastructures.\n\nFurthermore, the review emphasizes that mathematical modeling shows condom promotion and antiretroviral therapy (ART) are significantly more cost-effective and impactful than circumcision. The authors also outline substantial bioethical concerns, including the risk of ''condom migration'' driven by a false sense of immunity, lack of fully informed consent, and ethical issues surrounding pain and complications in infant circumcisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lawrence W. Green", "John W. Travis", "Ryan G. McAllister", "Kent W. Peterson", "Astrik N. Vardanyan", "Amber Craig"], "organizations": ["University of California at San Francisco", "RMIT University", "Georgetown University", "American College of Occupational and Environmental Medicine", "Armenian Association of Pediatricians and Pediatric Surgeons", "World Health Organization"], "themes": ["HIV Prevention", "Male Circumcision", "External Validity", "Public Health Policy", "Cost-Effectiveness", "Bioethics and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('943abfc07303358d119018a9ff83dafa5af5840570e708259fb4793d2fd330a6', 'Green McAllister Circumcision not HIV Vaccine FutMed 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/943abfc07303358d119018a9ff83dafa5af5840570e708259fb4793d2fd330a6.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This editorial argues against the implementation of mass male circumcision campaigns as a primary HIV prevention tool in developing nations, challenging claims that the procedure acts as an HIV ''vaccine.'' The authors criticize the methodology of the randomized clinical trials used to justify these programs, citing early study termination, high rates of participant loss to follow-up, and neglect of nonsexual transmission and real-world conditions.\n\nThe authors contend that mass surgical interventions carry substantial risks of complications, divert critical funding away from proven behavioral interventions like condom promotion, and foster a false sense of security that may exacerbate risky behaviors. They also raise significant ethical concerns regarding the proposed mass circumcision of infants and argue that established safe-sex educational programs offer far safer, cheaper, and more effective long-term results.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lawrence W Green", "Ryan G McAllister", "Kent W Peterson", "John W Travis", "Robert Bailey"], "organizations": ["Future Medicine Ltd", "Future Science Group", "Wellness Associates", "University of California at San Francisco", "Georgetown University", "Occupational Health Strategies, Inc.", "Conseil National du SIDA", "World Health Organization", "UNAIDS"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Public Health Policy", "Clinical Trial Methodology", "Risk Compensation", "Medical Ethics and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('09d5029ce9518973087a63f9f7ad2a2e7bc1ed1a236f134bde0879fc2cde971b', 'Green McAllister Medicaid Spreads Harm AJPH 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/09d5029ce9518973087a63f9f7ad2a2e7bc1ed1a236f134bde0879fc2cde971b.pdf', 'letter', 'ingested', '{"date": "2009", "description": "In this letter to the American Journal of Public Health, the authors dispute findings by Leibowitz et al. that framed declining circumcision rates among Medicaid recipients as a negative outcome. Instead, they argue that neonatal circumcision exposes male infants to avoidable risks\u2014including complications, MRSA, and death\u2014without conferring clear health benefits compared to populations in Europe where circumcision is rare.\n\nHighlighting a substantial increase in healthcare expenditures associated with circumcision complications, the authors assert that the procedure is not a cost-effective or justifiable public health intervention. They conclude that taxpayer funds via Medicaid should not finance an elective, potentially harmful procedure when tens of millions of Americans lack basic health coverage, praising the states that have dropped Medicaid coverage for neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Lawrence W. Green", "Ryan G. McAllister", "Kent W. Peterson", "John W. Travis", "A. A. Leibowitz"], "organizations": ["American Journal of Public Health", "Medicaid", "University of California, San Francisco", "Georgetown University", "Alliance for Transforming the Lives of Children", "Royal Melbourne Institute of Technology University"], "themes": ["Neonatal Circumcision", "Medicaid Policy and Funding", "Public Health and Preventive Medicine", "Healthcare Costs and Cost-Utility Analysis", "Medical Ethics and Child Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d796f1a447a32637ec9e8adc4bfe61605d6d3de2f384bad8aecb877665b3ab66', 'Griffiths Current Practices Foreskin Restoration Springer 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d796f1a447a32637ec9e8adc4bfe61605d6d3de2f384bad8aecb877665b3ab66.pdf', 'other', 'ingested', '{"date": "1999", "description": "This text provides an overview of the origins and objectives of the National Organization of Restoring Men (NORM), established in San Francisco in 1989 by R. Wayne Griffiths and Tim Hammond. Founded as the first known support group of its kind, NORM arose in response to significant public interest following advertisements about non-surgical foreskin restoration techniques.\n\nThe primary goals of the organization include offering a safe, confidential forum for circumcised men to discuss restoration methods and outcomes without fear of ridicule. Additionally, NORM serves to help men regain physical and emotional self-determination and address personal desires to feel intact.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["R. Wayne Griffiths", "Tim Hammond", "Denniston"], "organizations": ["The National Organization of Restoring Men", "Kluwer Academic / Plenum Publishers"], "themes": ["Foreskin Restoration", "Circumcision", "Men''s Health and Support Groups", "Bodily Autonomy and Self-Determination"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('80e7dff7c06846f75817bb6f53b5619c3a2012179ded8801206d4fd61249af0f', 'Griffiths Foreskin Restoration 1980-2008 Springer 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/80e7dff7c06846f75817bb6f53b5619c3a2012179ded8801206d4fd61249af0f.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This document introduces an analysis of foreskin restoration methods between 1980 and 2008, addressing the anatomical goals and expectations of men undergoing the process. It notes that while both surgical and non-surgical approaches exist to cover the glans, surgical results have often been disappointing, directing focus toward non-surgical tissue expansion techniques and devices. The authors emphasize that understanding the complex physiological structure of penile shaft tissue is critical to achieving successful and realistic outcomes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R. Wayne Griffiths", "J. David Bigelow", "James Loewen", "G. C. Denniston"], "organizations": ["National Organization of Restoring Men (NORM)", "Springer Science+Business Media"], "themes": ["Foreskin restoration", "Tissue expansion", "Penile anatomy", "Surgical vs non-surgical reconstruction", "Patient expectations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eb361431f651f744713293ad49df96e2e6d868035d254642437941c1d18c6793', 'Grimes RIC Reappraisal AmJObGyn1978.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eb361431f651f744713293ad49df96e2e6d868035d254642437941c1d18c6793.pdf', 'medical_journal', 'ingested', '{"date": "1978-01-15", "description": "In this clinical opinion article, Dr. David A. Grimes critically evaluates the practice of routine newborn circumcision and concludes that it lacks adequate medical justification. While acknowledging that circumcision can facilitate distal penile hygiene and may decrease the risk of penile cancer, the author demonstrates that the operation often relies on flawed patient selection, widespread failure to obtain genuine informed consent, omission of anesthesia based on the misconception that neonates do not feel pain, and substantial rates of immediate and delayed complications. Additionally, the paper argues that allocating an estimated 51 million dollars annually to an elective procedure of unproven prophylactic value squanders finite healthcare resources that would be more effectively invested in proven public health measures such as childhood vaccinations and newborn metabolic screening.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David A. Grimes", "Frederick P. Zuspan", "George J. Annas", "Howard H. Hiatt", "Erik Erikson"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Center for Disease Control", "United States Department of Health, Education, and Welfare", "American Board of Obstetrics and Gynecology", "Australian Paediatric Society"], "themes": ["Routine Neonatal Circumcision", "Medical Necessity and Prophylactic Surgery", "Informed Consent in Pediatrics", "Infant Pain Perception and Anesthesia Management", "Healthcare Resource Allocation and Cost-Effectiveness"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('84bd828ec41a2efe6ab20563b15eb1c6988d86aa86216a1d3d97e3dd28ff8631', 'Gruenbaum Earp Reconsidering_patriarchy IJIR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/84bd828ec41a2efe6ab20563b15eb1c6988d86aa86216a1d3d97e3dd28ff8631.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This review article critically examines the widely held ''patriarchy hypothesis''\u2014endorsed by organizations such as the World Health Organization (WHO)\u2014which asserts that customary female genital modifications are inherently driven by male dominance, female subordination, and the policing of female sexuality. The authors argue that this characterization relies on misleading generalizations and ignores cross-cultural complexities, notably that almost all societies practicing ritual female genital modification also practice male genital modification, frequently for comparable developmental and social reasons with women managing the female rites.\n\nAnalyzing ethnographic data from pre-industrial societies alongside contemporary global prevalence patterns, the authors demonstrate that female initiation rites do not correlate with gendered double standards regarding premarital sex, nor are female genital modifications uniquely present in the most patriarchal societies. Furthermore, they highlight that female initiation ceremonies often function to build female solidarity and communal power, meaning that selective external campaigns against female rites alone may inadvertently dismantle female support networks while leaving male rites intact. The authors call on international health organizations, researchers, and policymakers to adopt nuanced, culturally accurate frameworks rather than broad, unsupported assumptions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ellen Gruenbaum", "Brian D. Earp", "Richard A. Shweder", "Martin King Whyte", "Sara Johnsdotter"], "organizations": ["World Health Organization", "Purdue University", "University of Oxford", "University of Chicago", "UNICEF", "Human Relations Area Files"], "themes": ["Female Genital Modification", "Male Circumcision", "Patriarchy Hypothesis", "Anthropological Analysis", "Gender Roles and Inequality", "Premarital Sexual Norms", "Cross-Cultural Rites of Passage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('da81f9f506c4bfd582ea68783d1803dd724d9974b18efbaaa14cbfde8d169d56', 'Grund Male Circ Women''s Biomed  LancetGlobHlth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/da81f9f506c4bfd582ea68783d1803dd724d9974b18efbaaa14cbfde8d169d56.pdf', 'medical_journal', 'ingested', '{"date": "2017-11-08", "description": "This systematic review investigates the association between voluntary medical male circumcision (VMMC) and biomedical health outcomes among female partners, evaluating 60 publications covering global populations with particular relevance to sub-Saharan Africa. The authors identified high-consistency evidence indicating that male circumcision provides protective associations for women against cervical cancer, cervical dysplasia, herpes simplex virus type 2 (HSV-2), chlamydia, and syphilis. Medium-consistency evidence supported protection against general and low-risk human papillomavirus (HPV) infections.\n\nEvidence for protection against HIV was categorized as low consistency due to heterogeneity, largely driven by an increased transmission risk observed when sex resumed before wound healing among partners of HIV-infected men; however, observational data broadly favored protection. The findings suggest that the large-scale rollout of VMMC provides substantial secondary public health benefits to women, warranting stronger programmatic linkages between male circumcision and women''s reproductive health initiatives.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jonathan M Grund", "Tyler S Bryant", "Inimfon Jackson", "Kelly Curran", "Naomi Bock", "Carlos Toledo", "Joanna Taliano", "Sheng Zhou", "Jorge Martin del Campo", "Ling Yang", "Apollo Kivumbi", "Peizi Li", "Sherri Pals", "Stephanie M Davis"], "organizations": ["US Centers for Disease Control and Prevention", "Johns Hopkins Bloomberg School of Public Health", "Jhpiego", "LAC Group", "World Health Organization", "UNAIDS", "President''s Emergency Plan for AIDS Relief"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "Women''s Biomedical Health Outcomes", "Sexually Transmitted Infections (STIs)", "HIV Prevention", "Cervical Cancer and HPV", "Global Health and Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('524e3787d3e6154de5c0230845252636048a0f63b2dfc35dfd225058416036b9', 'Guevara Factors Parental Decision Cureus 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/524e3787d3e6154de5c0230845252636048a0f63b2dfc35dfd225058416036b9.pdf', 'medical_journal', 'ingested', '{"date": "2021-11-09", "description": "This prospective study investigated the primary factors influencing parental decision-making regarding elective newborn male circumcision and evaluated the utility of American Academy of Pediatrics (AAP) guidelines as an educational resource. Surveying 265 parents at a pediatric urology clinic, researchers found that the future health of the child (63.4%) and the circumcision status of the father (34%) were the most significant considerations guiding guardians'' decisions.\n\nAdditionally, 85.3% of participating parents found the AAP policy statement helpful as an educational supplement, with younger mothers finding it significantly more useful. The authors conclude that while clinical guidelines do not necessarily alter parental choice, providing objective educational resources effectively enhances provider-parent discussions regarding the risks and health benefits of neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Christian G. Guevara", "Justin K. Achua", "Ruben Blachman-Braun", "Isabella Cabrera-Valencia", "George A. Ransford", "Rafael Gosalbez", "Andrew S. Labbie", "Miguel A. Castellan", "Alireza Alam"], "organizations": ["Nicklaus Children''s Hospital", "University of Miami Miller School of Medicine", "Jackson Memorial Hospital", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists"], "themes": ["Neonatal Circumcision", "Parental Decision-Making", "Pediatric Urology", "Patient Education", "Preventive Health Benefits"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f61acc47d27b933eed4586c3fa9f3556b5ee0c8c9b1e0ae49064012a27526412', 'Gupta prepuce reconstruction IndianJPlasSurg 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f61acc47d27b933eed4586c3fa9f3556b5ee0c8c9b1e0ae49064012a27526412.pdf', 'medical_journal', 'ingested', '{"date": "2021-07-05", "description": "This article outlines a novel surgical technique for prepuce (foreskin) reconstruction developed for men who require complete and continuous glans penis coverage without visible scarring, specifically addressing religious and cultural requirements of certain ascetic groups. The procedure utilizes penile shaft skin degloving, glans de-epithelization to create adherence, and strategic suturing to establish a stable, non-retracting neoprepuce.\n\nA retrospective review of 46 patients treated between 2010 and 2019 showed successful complete coverage across all cases, with no significant complications such as balanitis, infection, or interference with erections over a mean follow-up period of 23.24 months.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Richie Gupta", "Sandeep Mehta", "Rajat Gupta"], "organizations": ["Fortis Hospital Shalimar Bagh", "Association of Plastic Surgeons of India", "Thieme Medical and Scientific Publishers Pvt. Ltd."], "themes": ["Prepuce Reconstruction", "Plastic and Reconstructive Surgery", "Circumcision Reversal", "Religious Anatomy Requirements", "Urological Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3de7653ab243d8a95f34ce21d9f9f8d4f98f48979639f79f3749359bf5a07ff7', 'Gyan Determinants morbidity Ghana TropMedIntHealth 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3de7653ab243d8a95f34ce21d9f9f8d4f98f48979639f79f3749359bf5a07ff7.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This population-based, cross-sectional study investigates the determinants and burden of morbidity associated with infant male circumcision across rural Ghana. Examining 2,850 circumcised male infants under 12 weeks of age, the authors identified an overall morbidity rate of 8.1% along with two procedure-related fatalities. The findings revealed that morbidity risk did not significantly differ between circumcisions performed by formal healthcare providers and traditional informal providers (such as Wanzams).\n\nInstead, the primary driver of complications was poor hygiene practices, including failing to wash hands, using uncleaned surgical instruments, and failing to clean the infant''s penile area beforehand. Significant risk was also observed in infants circumcised at or after 20 days of life and those born to mothers with lower educational attainment. Consequently, the study emphasizes the critical need for governmental and non-governmental health agencies to improve hygiene and surgical safety training for both formal and informal circumcision providers throughout sub-Saharan Africa.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Thomas Gyan", "Kimberley McAuley", "Natalie A. Strobel", "Caitlin Shannon", "Sam Newton", "Charlotte Tawiah-Agyemang", "Seeba Amenga-Etego", "Seth Owusu-Agyei", "Betty Kirkwood", "Karen M. Edmond"], "organizations": ["University of Western Australia", "Kintampo Health Research Centre", "Ghana Health Service", "Engender Health", "Kwame Nkrumah University of Science and Technology", "London School of Hygiene and Tropical Medicine", "World Health Organization"], "themes": ["Infant Male Circumcision", "Post-surgical Morbidity and Complications", "Hygiene and Sanitation Practices", "Traditional vs. Formal Healthcare Providers", "Neonatal and Infant Health in Rural Africa"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f56d79a17d0ea41c771a5b15055989555fe38c66cfc7d29cd5746b9d2ebf1471', 'Hainz Enhancement Circ Bioethics 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f56d79a17d0ea41c771a5b15055989555fe38c66cfc7d29cd5746b9d2ebf1471.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This article examines the ethical tension and potential double standard in bioethical discourse and legal policy regarding the enhancement of children versus non-therapeutic infant male circumcision. The author demonstrates that three central bioethical arguments commonly deployed against pediatric enhancement\u2014namely, the argument from insecurity and irreversibility, the child''s right to an open future, and the preservation of human nature and dignity\u2014apply with comparable force to circumcision. Consequently, institutions and ethicists who prohibit or condemn pediatric enhancement while permitting circumcision risk harboring mutually inconsistent moral standards.\n\nTo resolve this inconsistency, the article explores three potential approaches: the fundamental differences strategy, the total prohibition strategy, and the subsumption strategy. The author rejects the first two strategies due to flaws in differentiating the interventions and the dangerous side effects of absolute bans, such as the emergence of unregulated black markets. Instead, he advocates for the subsumption strategy, which categorizes circumcision as a form of human enhancement. Under this framework, current non-therapeutic circumcision is subject to strict harm-reduction regulations rather than prohibition, but could ethically become obsolete and unjustified as safer biomedical alternatives are developed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tobias Hainz", "Francis Fukuyama", "Joel Feinberg", "Robert J. L. Darby", "Dena S. Davis", "Jonathan Glover", "Julian Savulescu"], "organizations": ["Hannover Medical School", "President''s Council on Bioethics", "World Health Organization", "John Wiley & Sons Ltd"], "themes": ["Human Enhancement", "Infant Male Circumcision", "Bioethics", "Right to an Open Future", "Human Dignity and Human Nature", "Bodily Integrity", "Moral Consistency and Regulation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c458fd1653023ca50591e18403c5a442589420b9aca4e341ea8de6e3425a787b', 'Halata Neuroanatomical Basis Glans Brain Res1986.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c458fd1653023ca50591e18403c5a442589420b9aca4e341ea8de6e3425a787b.pdf', 'medical_journal', 'ingested', '{"date": "1986", "description": "This neuroanatomical study investigates the sensory innervation of the human glans penis using light and electron microscopy across seven anatomical specimens. The authors find that free nerve endings (FNEs) constitute the overwhelming majority of nerve terminals, outnumbering corpuscular receptors by roughly 10:1 and populating nearly every dermal papilla. The unique corpuscular receptors characteristic of the glans\u2014genital end bulbs\u2014fundamentally consist of tangled skeins of axon terminals that share identical ultrastructural features with FNEs. Typical low-threshold mechanoreceptors common in digital glabrous skin, such as innervated epidermal Merkel cells and Meissner corpuscles, are entirely absent, while simple, Pacinian, and Ruffini corpuscles appear only occasionally.\n\nThese findings provide a neuroanatomical explanation for the known psychophysical and physiological phenomenon of dissociated sensibility in the glans penis, wherein tactile thresholds are unusually high and approach the threshold for pain (protopathic sensibility). The dominance of high-threshold nociceptive free nerve endings and the lack of classic low-threshold mechanoreceptors correlate with the embryologic derivation of the glans and preputial plate, demonstrating that its sensory function differs fundamentally from ordinary cutaneous skin.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Zdenek Halata", "Bryce L. Munger", "Max von Frey", "Henry Head"], "organizations": ["Universit\u00e4t Hamburg", "The Pennsylvania State University", "The Milton S. Hershey Medical Center", "Elsevier Science Publishers B.V."], "themes": ["Neuroanatomy", "Sensory Innervation", "Protopathic Sensibility", "Genital End Bulbs", "Free Nerve Endings", "Mechanoreceptors", "Pain Thresholds"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ac5db624232f0b321f5f989f1f5f5238adb0a1420a9706ed2b981d1da9d8979b', 'Hammond Circ Scar Review JPPPH 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ac5db624232f0b321f5f989f1f5f5238adb0a1420a9706ed2b981d1da9d8979b.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This document is a book review by genital autonomy advocate Tim Hammond, published in the Journal of Prenatal and Perinatal Psychology and Health, evaluating Jay J. Jackson''s 2020 book Circumcision Scar. Hammond analyzes Jackson''s personal account of the lifelong physical, sexual, and psychological trauma resulting from involuntary neonatal circumcision, including repressed memories, erectile dysfunction, and dismissive treatment by medical practitioners.\n\nThe review situates Jackson''s memoir within broader psychological literature, historical rationales for sexual control, and contemporary bodily integrity movements. Hammond connects the denial of circumcision-induced harm to cultural conditioning and parallels drawn from female genital cutting, arguing that true bodily autonomy and gender equality require protecting all infants from non-therapeutic genital modifications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Jay J. Jackson", "David Chamberlain", "Ron Goldman", "Brian D. Earp", "John Harvey Kellogg", "Maimonides", "Alice Miller", "Nahid Toubia"], "organizations": ["Association for Pre-and Perinatal Psychology and Health", "National Organization of Restoring Men", "Children\u2019s Health & Human Rights Partnership of Canada", "International NGO Coalition on Genital Autonomy", "National Organization to Halt the Abuse and Routine Mutilation of Males", "Brussels Collaboration on Bodily Integrity", "Bloodstained Men"], "themes": ["Genital Autonomy and Bodily Integrity", "Neonatal Circumcision and Psychological Trauma", "Foreskin Restoration", "Medical Ethics and Callousness", "Children''s Human Rights", "Sexual Health and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a68726c1c27ad068d576278f431c1a6a7e7c823ba191c98542c4b55711464bac', 'Hammond Deficiencies-response to Tye & Sardi 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a68726c1c27ad068d576278f431c1a6a7e7c823ba191c98542c4b55711464bac.pdf', 'medical_journal', 'ingested', '{"date": "2022-04-25", "description": "This commentary, published in IJIR: Your Sexual Medicine Journal, responds to work by Marcus C. Tye and Lauren Sardi regarding the psychological and psychosocial aspects of penile circumcision. Author and advocate Tim Hammond argues that medical literature displays a profound cultural and gender bias: while research on female genital cutting rightly documents harms, research on childhood male genital cutting in the United States has historically sought to justify the practice and dismiss men''s negative experiences.\n\nDrawing on his decades of activism and survey research with circumcised men, Hammond emphasizes that non-therapeutic childhood circumcision violates children''s bodily integrity and future genital autonomy. He asserts that the psychological, psychosexual, and emotional distress reported by men subjected to non-consensual genital cutting should be taken seriously rather than minimized by the medical profession.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Marcus C. Tye", "Lauren Sardi", "Robert Darby"], "organizations": ["World Association for Sexual Health", "National Organization of Restoring Men", "Springer Nature"], "themes": ["Male Circumcision", "Genital Autonomy and Bodily Integrity", "Psychological and Psychosocial Impact", "Medical Research Bias", "Children''s Rights and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d70406903176089df1ee74e4a2a0104df0744c196ef690d5371b07a1ab343faa', 'Hammond Evaluating Bailis, Morris ASM 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d70406903176089df1ee74e4a2a0104df0744c196ef690d5371b07a1ab343faa.pdf', 'other', 'ingested', '{"date": "2020", "description": "This document is an analytical rebuttal written by independent researcher Tim Hammond responding to a critique by Bailis, Moreton, and Morris concerning Hammond and Carmack''s survey on long-term adverse outcomes of neonatal circumcision. Hammond defends the survey''s targeted focus on men who experience distress and dissatisfaction with their circumcision status, rejecting claims that respondents were merely biased or misled by intactivists. He further critiques medical establishment biases, the omission of foreskin anatomy in medical education, and advocates for children''s bodily integrity and genital autonomy rights against non-therapeutic genital alteration.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Tim Hammond", "A. Carmack", "Brian J. Morris", "S. A. Bailis", "S. Moreton", "Brian D. Earp", "J. A. Bossio"], "organizations": ["Global Survey of Circumcision Harm", "American Academy of Pediatrics", "NOCIRC", "Brussels Collaboration on Bodily Integrity", "Doctors Opposing Circumcision"], "themes": ["Neonatal Circumcision", "Genital Autonomy", "Bodily Integrity", "Foreskin Anatomy and Function", "Medical Ethics", "Patient Dissatisfaction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('66d54f9ef725dab8128e02a4d82f6557b03bd6fbdf616c7544d008bacb310193', 'Hammond letter re Fihman JSM 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/66d54f9ef725dab8128e02a4d82f6557b03bd6fbdf616c7544d008bacb310193.pdf', 'medical_journal', 'ingested', '{"date": "2026-04-16", "description": "This Letter to the Editor by Tim Hammond comments on a pilot study by Fihman et al. regarding the effects of elective adult circumcision for religious reasons on sexual function and satisfaction. Hammond argues that religious commitment and social pressures may bias postoperative self-evaluations and notes that findings on consenting adults should not be conflated with neonatal circumcision, which lacks consent and can lead to magnified long-term physical, sexual, and psychological harms.\n\nAdditionally, the letter highlights that the 2012 American Academy of Pediatrics (AAP) policy endorsing circumcision expired in 2017 without renewal, and cites recent statements by former task force members Andrew Freedman and Douglas Diekema questioning whether the benefits outweigh the risks. Hammond advocates for medical, ethical, and legal protections to safeguard unconsenting minors'' fundamental human right to bodily integrity and genital autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Andrew Freedman", "Douglas Diekema", "M. Fihman"], "organizations": ["Genital Autonomy Legal Defense and Education Fund", "Oxford University Press", "The International Society for Sexual Medicine", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Adult Circumcision", "Medical Ethics", "Genital Autonomy and Bodily Integrity", "Informed Consent", "Sexual Function and Satisfaction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('46331b53c0b439c2aa99a31203f4eebec1c65301443072dc3bcaed863c87d0fd', 'Hammond Long_Term_Consequences_Springer 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/46331b53c0b439c2aa99a31203f4eebec1c65301443072dc3bcaed863c87d0fd.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This study examines the long-term physical, sexual, and psychological consequences of neonatal circumcision based on a 1993 survey of 313 circumcised men conducted by NOHARMM. The findings indicate that a vast majority of respondents reported negative impacts, including sexual harm, emotional distress, decreased penile sensitivity, scarring, and feelings of bodily violation or mutilated identity. Many men described difficulties with intimacy, painful intercourse due to lack of lubrication, and resentment toward parents and the medical establishment for allowing the procedure without consent.\n\nThe author argues that the widespread lack of awareness regarding these harms stems from cultural silence, medical minimization, and broad ignorance of intact male genital anatomy. Consequently, many circumcised men misattribute their physical issues to aging or birth defects. The paper concludes that learning about intact anatomy often catalyzes the recognition of harm, prompting men to cope through foreskin restoration, peer support groups, and anti-circumcision advocacy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Denniston", "Milos", "Lawrence Dillon", "W. F. Gee", "J. S. Ansell"], "organizations": ["National Organization to Halt the Abuse and Routine Mutilation of Males", "NOHARMM", "Plenum Press", "University of California Extension Center for Media and Independent Learning"], "themes": ["Neonatal Circumcision", "Long-Term Psychological and Sexual Harm", "Male Genital Autonomy and Human Rights", "Foreskin Restoration", "Cultural Taboos and Medical Mistrust"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7f356ad4c82868668d59695245edfc1fd43c0bce52d05c83b5c7e4e8efb7ec7b', 'Hammond Preliminary Poll  BJUI1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7f356ad4c82868668d59695245edfc1fd43c0bce52d05c83b5c7e4e8efb7ec7b.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This academic paper reports the results of a preliminary survey conducted by NOHARMM from 1993 to 1996 involving 546 men circumcised in infancy or childhood. The study examines the physical, sexual, and psychological consequences reported by these men, challenging the presumption within circumcising societies that non-therapeutic neonatal circumcision is benign or without lasting negative outcomes. Respondents reported significant physical issues (such as scarring and insufficient penile skin), reduced sexual sensitivity and satisfaction due to the loss of specialized preputial tissue and glans keratinization, and psychological distress including feelings of mutilation, resentment, and depression.\n\nThe author critiques medical justifications for routine infant circumcision, pointing out the lack of long-term follow-up and the medical community''s general disregard for preputial anatomy. The paper also discusses the role of psychological denial, non-surgical foreskin restoration practices, and frames routine childhood circumcision as a human rights violation, urging medical associations to establish policies protecting children''s physical integrity and bodily autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["T. Hammond", "Lilienfeld", "Schlossberger", "Williams", "Kapila", "William H. Masters", "Virginia E. Johnson", "John Money", "J. Davidson", "N. Toubia", "Alice Miller"], "organizations": ["National Organization to Halt the Abuse & Routine Mutilation of Males (NOHARMM)", "American Academy of Pediatrics", "Virginia Urologic Society", "National Organization of Restoring Men (NORM)", "Attorneys for the Rights of the Child", "Doctors Opposing Circumcision", "Intersex Society of North America"], "themes": ["Long-term consequences of neonatal circumcision", "Male genital integrity and bodily autonomy", "Sexual dysfunction and desensitization", "Psychological impact and trauma of involuntary surgery", "Medical ethics and human rights", "Foreskin restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a57d5ecef29f2b243fbfb56404890376f2d6b09afdadd9efe10b9509d213fac2', 'Hammond Reiss Reply to Bossio Antecedents of Emotional Distress Arch Sex Beh (2017).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a57d5ecef29f2b243fbfb56404890376f2d6b09afdadd9efe10b9509d213fac2.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "In this commentary responding to Bossio and Pukall (2017), the authors explore the physical, sexual, and psychological antecedents of distress in men subjected to nontherapeutic neonatal or childhood circumcision. They identify physical complications such as excessive skin removal, painful erections, meatal stenosis, and nerve scarring, alongside sexual impairments including loss of lubrication, reduced sensitivity, and erectile dysfunction.\n\nThe authors further highlight the profound emotional and psychological repercussions reported by affected men, including feelings of mutilation, grief, depression, and a sense of violated bodily integrity and personal autonomy. Emphasizing that an estimated 30% of global males are circumcised without medical indication, they urge future researchers and public policy makers to acknowledge the lived experiences and adverse long-term outcomes within this subpopulation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Mark D. Reiss", "J. A. Bossio", "C. F. Pukall"], "organizations": ["Global Survey of Circumcision Harm", "Doctors Opposing Circumcision", "Celebrants of Brit Shalom", "Springer Nature"], "themes": ["Neonatal Circumcision", "Sexual Dissatisfaction", "Psychological Trauma", "Bodily Autonomy and Integrity", "Medical Ethics and Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7683fca09a28c0efd38ab3a7a86d967597dc0672ba396cf94f78760e78b3569', 'Hammond Sardi Foreskin-Restorers-ABRIDGED-IJIR-2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7683fca09a28c0efd38ab3a7a86d967597dc0672ba396cf94f78760e78b3569.pdf', 'medical_journal', 'ingested', '{"date": "2023-03-30", "description": "This study analyzes the motivations, outcomes, and healthcare experiences of individuals pursuing non-surgical foreskin restoration through an international survey of 1,790 respondents. The primary drivers for seeking restoration included addressing physical, sexual, and psychological damages attributed to non-voluntary infant or childhood circumcision, such as diminished sensitivity, pain, keratinization, and emotional distress. Respondents broadly reported improvements in sexual pleasure, self-esteem, and emotional well-being following restoration efforts, with the vast majority recommending the practice.\n\nDespite these benefits, the findings reveal a pronounced gap in healthcare engagement and competence. Over 86% of respondents avoided consulting medical or mental health professionals due to feelings of hopelessness, mistrust, or fear of ridicule, while those who did seek help often faced dismissal, ignorance, or trivialization. The authors argue that circumcision sufferers and restorers remain severely underserved by the healthcare system, urging expanded medical training, recognition of bodily integrity rights, and a critical reassessment of non-therapeutic childhood circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Lauren M. Sardi", "William A. Jellison", "Ryan McAllister", "Ben Snyder", "Mohamed A. B. Fahmy"], "organizations": ["Quinnipiac University", "Al-Azhar University", "National Organization of Restoring Men", "Doctors Opposing Circumcision", "Intact America", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Foreskin Restoration", "Circumcision-Related Distress and Trauma", "Psychosexual Health", "Bodily Integrity and Human Rights", "Medical Education and Clinical Competence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('21d3075438feae8dec638df81820bdfa5a8f1b450893928dfbc7aa78ed9f5842', 'Hammond Sardi Foreskin-Restorers-UNABRIDGED-IJIR-2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/21d3075438feae8dec638df81820bdfa5a8f1b450893928dfbc7aa78ed9f5842.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This document serves as an unabridged supplement to a study published in the International Journal of Impotence Research investigating the motivations, physical and psychosexual outcomes, and clinical experiences of individuals undergoing foreskin restoration. Based on an in-depth survey of 1,790 respondents across 60 countries, the findings demonstrate that non-therapeutic neonatal circumcision frequently results in perceived physical, sexual, and psychological trauma, including reduced penile sensitivity, body grief, and erectile or orgasmic challenges. Respondents reported turning to non-surgical tissue expansion primarily to recover sexual pleasure, restore glans protection, and regain bodily autonomy, with a substantial majority (69%) reporting enhanced sexual pleasure and overall psychological relief following restoration.\n\nThe authors highlight significant deficiencies in clinical awareness and medical empathy regarding circumcision-related distress. Most respondents avoided seeking professional healthcare assistance due to fear of ridicule, while those who did consult clinicians frequently encountered dismissal, invalidation, or a lack of anatomical understanding. The report calls for substantial reforms in medical and mental healthcare education, hospital infant cutting policies, diagnostic criteria in the DSM, and public health guidance, arguing for the universal recognition of genital autonomy and bodily integrity across sexes and genders.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Lauren M. Sardi", "William A. Jellison", "Ryan McAllister", "Ben Snyder", "Mohamed A.B. Fahmy", "Edward Wallerstein", "R. Wayne Griffiths"], "organizations": ["International Journal of Impotence Research", "Quinnipiac University", "Al-Azhar University", "National Organization of Restoring Men", "American Academy of Pediatrics", "World Health Organization", "Doctors Opposing Circumcision", "Intact America", "Foregen"], "themes": ["Foreskin Restoration", "Male Circumcision", "Genital Autonomy and Bodily Integrity", "Psychosexual Health", "Medical Ethics and Informed Consent", "Circumcision Grief and Trauma", "Patient-Provider Communication"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dc1baa7c8a2221f60e37533cdb08b8780c4bfc1898c0b3a6c9a0f2b234ecf5f5', 'Hammond-Carmack Long term adverse outcomes IJHR March 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dc1baa7c8a2221f60e37533cdb08b8780c4bfc1898c0b3a6c9a0f2b234ecf5f5.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This study analyzes survey responses from 1,008 men reporting long-term dissatisfaction and adverse outcomes from non-therapeutic neonatal circumcision. The findings document widespread self-reported negative consequences, including reduced penile sensitivity, erectile dysfunction, meatal stenosis, altered sexual function, alexithymia, and psychological trauma such as feelings of violation, mutilation, and parental betrayal. The authors emphasize that these harms are often overlooked due to cultural normalization, denial, and social barriers to reporting.\n\nFraming non-therapeutic infant circumcision as an infringement on a child''s bodily integrity and right to an open future, the authors argue against proxy parental consent for non-essential surgeries. They critique institutions such as the American Academy of Pediatrics for pro-circumcision bias and failing to value the physiological functions of the foreskin. The paper calls for recognizing circumcision harm within diagnostic coding systems, restricting elective circumcisions on minors, and expanding support and research for affected men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tim Hammond", "Adrienne Carmack", "Jennifer A. Bossio", "Brian D. Earp", "Morten Frisch", "Robert Darby", "J. Steven Svoboda"], "organizations": ["Children\u2019s Health and Human Rights Partnership", "American Academy of Pediatrics", "World Health Organization", "Centers for Disease Control and Prevention", "Attorneys for the Rights of the Child", "United Nations Committee on the Rights of the Child", "National Organization of Restoring Men"], "themes": ["Neonatal Circumcision", "Children''s Rights and Bodily Integrity", "Male Sexual Dysfunction", "Medical Bioethics", "Psychological Trauma and Coping", "Foreskin Restoration", "Genital Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c28d237aeca2a6bf9195cc538a497e78770fb172131857fb4d7b7b54e4239eb5', 'Hammond-Klein-Chase PsychPerspHumSex 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c28d237aeca2a6bf9195cc538a497e78770fb172131857fb4d7b7b54e4239eb5.pdf', 'other', 'ingested', '{"date": "2000", "description": "This document consists of an academic book chapter titled ''Genital Surgery on Children below the Age of Consent,'' authored by Hanny Lightfoot-Klein, Cheryl Chase, Tim Hammond, and Ronald Goldman. It critically examines nonconsensual childhood genital operations divided into three interrelated areas: female genital mutilation (FGM), intersex cosmetic genital reconstructions, and routine neonatal male circumcision. The authors analyze the historical origins, cultural and clinical rationales, severe physical and psychological consequences, and ethical issues associated with altering the healthy genitals of infants and children without informed consent.\n\nThe text critiques Western double standards that condemn traditional African cutting rituals while institutionalizing, sanitizing, and defending infant male circumcision and normalizing cosmetic surgeries performed on intersex infants. It highlights the lack of scientific justification, long-term outcome data, and acknowledgment of patient trauma in these clinical practices. The authors argue that such practices are driven primarily by cultural conformity, adult anxieties, and institutionalized tradition rather than medical necessity, urging healthcare professionals to adopt patient-centered approaches that respect bodily autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Hanny Lightfoot-Klein", "Cheryl Chase", "Tim Hammond", "Ronald Goldman", "Lenore T. Szuchman", "Frank Muscarella", "Alice Dreger", "Suzanne Kessler"], "organizations": ["John Wiley & Sons, Inc.", "American Academy of Pediatrics", "Intersex Society of North America", "National Organization to Halt the Abuse and Routine Mutilation of Males", "National Organization of Restoring Men", "Johns Hopkins Hospital"], "themes": ["Female Genital Mutilation", "Intersex Genital Reconstruction", "Neonatal Male Circumcision", "Informed Consent and Bodily Integrity", "Medicalization of Cultural Rituals", "Psychosexual Trauma and Surgical Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b79f89e53c1850a11865e785fd0dfae7e60cf4cd9809bfbaa898192f3a848cc5', 'Han HPV Circ Men JAMAOncol 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b79f89e53c1850a11865e785fd0dfae7e60cf4cd9809bfbaa898192f3a848cc5.pdf', 'medical_journal', 'ingested', '{"date": "2017-01-19", "description": "This cross-sectional study assesses the prevalence of genital human papillomavirus (HPV) infection and vaccination rates among adult men in the United States using data from the 2013-2014 National Health and Nutrition Examination Survey (NHANES). The analysis found an overall genital HPV infection prevalence of 45.2% and a high-risk oncogenic HPV prevalence of 25.1% among men aged 18 to 59 years. HPV infection was widespread across all adult age groups, showing a bimodal distribution that peaked among men aged 28 to 32 years and again among those aged 58 to 59 years.\n\nIn contrast to the high prevalence of infection, HPV vaccination coverage was substantially low, with only 10.7% of vaccine-eligible men reporting receiving the vaccine and only 5.6% having completed the full series. The authors conclude that expanding male HPV vaccination coverage could dramatically reduce HPV transmission and prevent associated anogenital and oropharyngeal cancers in both men and women, suggesting that current age limitations on male HPV immunization guidelines may warrant reevaluation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jasmine J. Han", "Thomas H. Beltran", "John W. Song", "John Klaric", "Y. Sammy Choi"], "organizations": ["Womack Army Medical Center", "Centers for Disease Control and Prevention", "National Center for Health Statistics", "Food and Drug Administration", "American Medical Association"], "themes": ["Human Papillomavirus (HPV)", "Vaccination Coverage", "Sexually Transmitted Infections", "Epidemiology", "Cancer Prevention", "Men''s Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('38a58ebf9e1aef191f8c14fadcb6af02accba3b385681004ddf4af4c96609b9e', 'Hand Circ and VD ArchDermSyphol 1949.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/38a58ebf9e1aef191f8c14fadcb6af02accba3b385681004ddf4af4c96609b9e.pdf', 'medical_journal', 'ingested', '{"date": "1949-09", "description": "This study analyzes the relationship between circumcision and the incidence of venereal disease, specifically gonorrhea, based on data collected in 1945 at the United States Naval Hospital at St. Albans, New York. The author compares the circumcision rates among men without a history of venereal infection to those who contracted gonorrhea, categorizing subjects by demographic groups. The findings indicate that the rate of circumcision was lower among gentile and Black patients presenting with gonorrhea compared to those free of infection, supporting earlier medical beliefs that circumcision may reduce vulnerability to venereal diseases.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eugene A. Hand", "Udo Julius Wile", "Brietenstein", "V. E. Lloyd", "N. L. Lloyd"], "organizations": ["United States Naval Hospital at St. Albans, N. Y.", "American Medical Association"], "themes": ["Circumcision", "Venereal Disease", "Gonorrhea", "Public Health Statistics", "Military Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ead6648650db082514ff2c34ce48cc333608e508afeed04ea1c5df88fb38211', 'Harrison Rethinking Circ Sexualities 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ead6648650db082514ff2c34ce48cc333608e508afeed04ea1c5df88fb38211.pdf', 'other', 'ingested', '{"date": "2002", "description": "In this paper, Dr. Daniel M. Harrison critiques the prevalence and taken-for-granted normalcy of routine neonatal male circumcision in the United States, arguing that sociological and public debates have historically focused too narrowly on hygiene, medical rationale, and disease prevention. Drawing on gender theory and interdisciplinary perspectives, Harrison asserts that the procedure has significant, under-examined consequences for male embodiment, sexual function, and sexual pleasure.\n\nHarrison argues that circumcision reduces penile sensitivity, eliminates the loose sheath necessary for specific forms of sexual dalliance and practices, and functions to prematurely ''sex'' the male body within a rigid, hegemonic gender framework. By analyzing the practice through the lenses of scholars like Susan Bordo, R.W. Connell, and Judith Butler, the author concludes that intact men have access to a more varied, sensuous, and elaborate sexual repertoire, challenging the cultural stigmas and institutional justifications surrounding the uncircumcised penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Daniel M. Harrison", "Susan Bordo", "Sigmund Freud", "Thomas Szasz", "John Lewis A. Sayre", "Judith Lorber", "R.W. Connell", "Lawrence Hoffman", "Judith Butler"], "organizations": ["Western State College of Colorado", "American Academy of Pediatrics", "American Medical Association", "American College of Obstetricians and Gynecologists", "National Organization of Circumcision Information and Resource Centers", "Doctors Opposed to Circumcision", "Brothers United for Future Foreskin"], "themes": ["Male Circumcision", "Sociology of Sexuality", "Gender Theory and Masculinity", "Medicalization", "Sexual Pleasure and Sensation", "Bodily Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bb2b2db7263aef2d50e27c3338edf951c3273881926caaea260c4857cf5f0d98', 'Harryman Anat in Med Textbks Kluwer 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bb2b2db7263aef2d50e27c3338edf951c3273881926caaea260c4857cf5f0d98.pdf', 'medical_journal', 'ingested', '{"date": "2004", "description": "This study analyzes the accuracy of anatomical depictions of the human penis in 90 medical textbooks, reference books, dictionaries, and anatomical models commonly accessible to medical students in Southern California. The author finds that 67% of all images and 71% of primary images represent the penis in a surgically altered (circumcised) state with the foreskin absent, almost always without caveat or explanation. Furthermore, textual entries frequently define the foreskin solely by its removal, while completely omitting its erogenous, mechanical, and neurological structures such as the ridged band.\n\nThe author argues that U.S. medical literature exhibits widespread bias by misrepresenting a partially amputated organ as the natural human condition, whereas female anatomy is consistently depicted intact and accurate. The chapter concludes that circumcision has degenerated from objective science into institutionalized medical dogma, leaving U.S.-trained physicians misinformed about fundamental male anatomy and raising significant ethical and legal concerns.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gary L. Harryman", "George C. Denniston"], "organizations": ["National Organization of Restoring Men (NORM-SoCal)", "Kluwer Academic/Plenum Publishers", "University of California, Los Angeles", "University of Southern California", "Santa Monica College", "National Library of Medicine"], "themes": ["Male Anatomy", "Circumcision", "Medical Education", "Foreskin and Prepuce Anatomy", "Anatomical Accuracy", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ef8ba973be2a81af254241f0fc6dbdd36d8641b58ffa58d6b94e125bf424b1e4', 'Hartelt I Dont Want to Hear About Your Dick 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ef8ba973be2a81af254241f0fc6dbdd36d8641b58ffa58d6b94e125bf424b1e4.pdf', 'other', 'ingested', '{"date": "2018", "description": "This master''s thesis examines how men undergoing non-surgical foreskin restoration communicatively manage the social stigma associated with altering their circumcision status. Drawing upon 13 semi-structured qualitative interviews with men recruited from an online community, the author applies Meisenbach\u2019s Stigma Management Communication (SMC) typology and Smith''s stigma communication framework to explore the discourse surrounding this concealable and self-selected practice.\n\nThe findings reveal that men encounter stigmatizing messages marking intact foreskin as unclean and labeling restoring men as abnormal or obsessive. In response, participants deploy a diverse range of stigma management strategies across all theoretical quadrants, including discursive and physical hiding, bonding with other restorers, evading responsibility by framing restoration as a necessary remedy to non-consensual infant circumcision, and transcendence centered on regaining bodily and emotional wholeness. Additionally, the study identifies bodily and sexual dissatisfaction as primary motivations for restoration and highlights the phenomenon of forced disclosure when concealment becomes untenable.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Joshua Hartelt", "Jenn Anderson", "Dr. Westwick", "Dr. Varenhorst", "Erving Goffman", "Kristen Meisenbach"], "organizations": ["South Dakota State University", "National Organization of Restoring Men", "American Pediatric Association"], "themes": ["Stigma Management Communication", "Foreskin Restoration", "Infant Circumcision", "Body Dissatisfaction", "Concealable Stigmatized Identities", "Forced Disclosure", "Intactivism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('edf695b644ab019b7b1685690e97c48d4f751b62d3223eceb8ce7a9820e328cd', 'Haseebuddin Prepuce Preservation 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/edf695b644ab019b7b1685690e97c48d4f751b62d3223eceb8ce7a9820e328cd.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This review evaluates surgical strategies and clinical outcomes regarding the preservation and reconstruction of the prepuce (foreskin) in conditions traditionally treated with circumcision, including penile degloving procedures, phimosis, hypospadias repair, and localized penile cancer. The authors find that prepuce-sparing approaches are often oncologically and functionally viable without inevitably leading to persistent complications like preputial lymphedema, offering patients improved cosmesis, sexual function, and psychological outcomes.\n\nThe article also surveys historical and modern techniques for preputial reconstruction and uncircumcision, spanning ancient procedures described by Celsus to contemporary methods involving skin grafting, tissue expanders, and vascularized fascial flaps. While preputial preservation is well-supported in selected clinical contexts, the authors conclude that methods for secondary surgical reconstruction remain largely experimental, anecdotal, and lack systematic evaluation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohammed Haseebuddin", "Steven B. Brandes", "Aulus Cornelius Celsus", "Willard E. Goodwin"], "organizations": ["Washington University Medical Center", "Lippincott Williams & Wilkins", "Wolters Kluwer Health", "Oxford Centre for Evidence-Based Medicine"], "themes": ["Prepuce Preservation", "Preputial Reconstruction", "Circumcision and Uncircumcision", "Urologic Reconstructive Surgery", "Penile Cancer and Mohs Micrographic Surgery", "Phimosis and Hypospadias Repair"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3cda0629a665698abe198e20ef71ee686c04399d97917adcf77280f34d50605c', 'Hastings Report Seven things about FGM 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3cda0629a665698abe198e20ef71ee686c04399d97917adcf77280f34d50605c.pdf', 'policy_guideline', 'ingested', '{"date": "2012", "description": "This policy advisory statement, authored by the Public Policy Advisory Network on Female Genital Surgeries in Africa, challenges mainstream Western media narratives and anti-mutilation advocacy regarding female genital modifications. The authors argue that public discourse has relied on sensationalized, inaccurate depictions that conflate all practices with extreme infibulation (Type III) and falsely claim universal consequences of severe morbidity, sexual dysfunction, and death. In contrast, the authors present evidence showing that roughly 90 percent of surgeries in Africa are Type I or II, that severe medical complications are relatively rare and not significantly different from uncut cohorts in matched studies, and that many circumcised women continue to experience sexual arousal and orgasm.\n\nThe document further asserts that customary genital modifications are typically initiated and managed by women as aesthetic enhancements, moral ideals, and cultural expressions of gender identity rather than acts of male domination or patriarchal torture. Calling for balanced, evidence-based policy discussions, the network urges journalists, researchers, and policymakers to avoid inflammatory rhetoric and criminalization that stigmatize women and drive practices underground. They advocate for recognizing adult women''s bodily autonomy, acknowledging cross-cultural parallels with male circumcision and Western cosmetic genital surgery, and centering the voices and self-determination of African women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Fuambai Sia Ahmadu", "Lucrezia Catania", "Ellen Gruenbaum", "Richard A. Shweder", "Bettina Shell-Duncan", "Birgitta Essen", "Carlos Londo\u00f1o Sulkin", "Michelle McKinley", "Wairimu Njambi", "Sara Johnsdotter", "Juliet Rogers", "Jasmine Abdulcadir", "Crista Johnson-Agbakwu", "Corinne Kratz", "Michelle C. Johnson", "A.M. Rosenthal"], "organizations": ["The Public Policy Advisory Network on Female Genital Surgeries in Africa", "The Hastings Center", "World Health Organization"], "themes": ["Female Genital Surgeries (FGS/FGM)", "Bioethics and Cross-Cultural Understanding", "Media Sensationalism and Fact-Checking", "Female Sexuality and Reproductive Health", "Women''s Agency and Bodily Autonomy", "Public Health Policy and Criminalization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('907190a049e0b195c3df0b7f0dab696f70f8c5ee0a5f9e480cdbf2cb36d83038', 'Hegazy Foreskin area IJIR 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/907190a049e0b195c3df0b7f0dab696f70f8c5ee0a5f9e480cdbf2cb36d83038.pdf', 'medical_journal', 'ingested', '{"date": "2026", "description": "This article proposes a simplified geometrical model to estimate the male foreskin surface area using standard glans length and coronal diameter measurements. Treating the foreskin as a double-layered elastic cylinder, the authors re-evaluated historical data from a 2001 penile dimension study involving 143 men aged 18 to 68. By incorporating a conservative 10% adjustment to account for physiological tissue elasticity, the calculations yielded a median foreskin surface area of 79.8 cm\u00b2 (mean 76.2 \u00b1 18.9 cm\u00b2), leading the authors to propose a rounded clinical reference value of 80 cm\u00b2.\n\nThe authors note that this calculation represents an underestimation because it excludes anatomical elements such as the frenulum, the coronal sulcus, and preputial overhang. Despite these limitations, the proposed model provides a practical, non-invasive method for estimating available donor tissue during preoperative planning for reconstructive surgeries, including hypospadias repair, burn contractures, and gender-affirming vaginoplasty.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Guido Hegazy", "Manasseh Seidenberg", "Holger Erb", "Joerg Syllwasschy"], "organizations": ["Springer Nature Limited", "ARGUS-Kinderschutz", "pro familia Landesverband NRW e.V.", "University Hospital of Essen"], "themes": ["Urology and Andrology", "Foreskin Surface Area", "Penile Biometrics", "Reconstructive Surgery", "Geometrical Modeling"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('80ece0cc8815516875817bba0c929b44f502aa9f4028dafbe6de8e1f45f5675c', 'Hegazy Male_circumcision_review TheHealth 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/80ece0cc8815516875817bba0c929b44f502aa9f4028dafbe6de8e1f45f5675c.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This review evaluates the anatomical characteristics of the penile prepuce and the prophylactic and clinical implications of male circumcision. Synthesizing historical background, prevalence data, and clinical evidence, the authors argue that the medical benefits of circumcision\u2014including significant protection against urinary tract infections, penile cancer, cervical cancer in female partners, and sexually transmitted infections such as HIV\u2014vastly outweigh the minor risks and low complication rates of the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Abdelmonem Awad Hegazy", "M. O. Al-Rukban"], "organizations": ["Majmaah University", "Zagazig University", "King Saud University", "American Academy of Pediatrics", "National Organization to Halt the Abuse and Routine Mutilation of Males", "National Organization of Circumcision Information Resource Centers"], "themes": ["Male Circumcision", "Penile Prepuce Anatomy", "HIV and STI Prevention", "Urological Reconstruction", "Genital Hygiene", "Surgical Indications and Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ea35499f84abf29242e0ca8f59568ec7c2ed2282d12358fc7490f7828e02aea9', 'Hellsten Rationalizing circumcision JME 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ea35499f84abf29242e0ca8f59568ec7c2ed2282d12358fc7490f7828e02aea9.pdf', 'medical_journal', 'ingested', '{"date": "2004", "description": "This article offers a critical bioethical analysis of the persistent practice of genital mutilation across both sexes, focusing specifically on the rationalisations surrounding non-therapeutic male circumcision. Responding to symposium papers by Hutson, Short, and Viens, the author argues that the diverse justifications advanced across cultures\u2014ranging from medical and public health benefits to religious freedom and parental autonomy\u2014are largely post-hoc rationalisations that fail to provide rigorous moral justification. Hellsten asserts that framing infant male circumcision as a parental right or cultural tradition overlooks the fundamental principle of child rights and bodily integrity.\n\nBy comparing male circumcision with female genital mutilation (FGM), the author illustrates how various societies universalise bodily alterations to regulate sexuality, preserve social hierarchies, or extract economic and commercial value while cloaking them in cultural or medical legitimacy. The paper concludes that combating harmful, non-therapeutic bodily interventions requires dismantling these false cultural and scientific narratives through education and prioritizing children''s individual rights over collective or parental interests.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["S K Hellsten", "J M Hutson", "R Short", "A Viens"], "organizations": ["University of Birmingham", "Centre for the Study of Global Ethics", "World Health Organisation"], "themes": ["Male Circumcision", "Female Genital Mutilation", "Children''s Rights", "Medical Ethics", "Autonomy and Parental Rights", "Cultural Relativism", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('046bf8c4985576685fb7313163d6523cd29241b33c2e2cbdec6873eeeb18afbc', 'Herrera Physician Attitudes AmJObGyn 1984.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/046bf8c4985576685fb7313163d6523cd29241b33c2e2cbdec6873eeeb18afbc.pdf', 'medical_journal', 'ingested', '{"date": "1980", "description": "This document contains excerpts from medical communications in an academic journal. The first section details a clinical case report describing the sonographic diagnosis and surgical management of a pathologic retraction ring (Bandl''s ring) during obstructed labor, successfully delivered via classical cesarean section. The second section presents a study by Drs. Alfredo J. Herrera and Arthur L. Macaraeg assessing physicians'' attitudes toward routine neonatal circumcision based on a survey of obstetricians and pediatricians, highlighting differences in counseling practices, medical indications, and personal recommendations between the two specialties.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alfredo J. Herrera", "Arthur L. Macaraeg", "L. Bandl", "J. A. Pritchard", "P. C. MacDonald"], "organizations": ["St. Agnes Hospital", "Department of Pediatrics, Division of Neonatology, St. Agnes Hospital"], "themes": ["Obstetrics and Gynecology", "Pathologic Retraction Ring", "Ultrasonography in Labor", "Cesarean Section", "Neonatal Circumcision", "Physician Attitudes and Counseling", "Pediatrics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c0354ee9ccfb9823439f8f91757f3c8144d748419a670a6d90ec53e07c474561', 'Hewett MisReporting Circumcision Zambia PlosOne 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c0354ee9ccfb9823439f8f91757f3c8144d748419a670a6d90ec53e07c474561.pdf', 'medical_journal', 'ingested', '{"date": "2012-05-22", "description": "This study evaluates the accuracy of self-reported male circumcision (MC) status among men and partner reporting by women across urban and rural Zambia and urban Swaziland, comparing survey responses to visual clinical examinations. The findings indicate that self-reported circumcision status is subject to misreporting, with 2\u20137% of uncircumcised men falsely reporting being circumcised, and a much higher rate of misreporting among women regarding their partner''s status (11\u201315%).\n\nTo address this reporting error, the researchers tested interventions including simple and detailed verbal descriptions, visual illustrations of circumcised and uncircumcised penises, and audio computer-assisted self-interviewing (ACASI). The results demonstrated that computerized interviewing (ACASI) did not enhance reporting accuracy, whereas providing clear visual illustrations significantly reduced misreporting, particularly among illiterate participants. The authors conclude that the inaccuracies stem primarily from a lack of understanding rather than social desirability bias, meaning circumcision prevalence may be overstated in national health surveys without adequate descriptive or visual aids.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul C. Hewett", "Nicole Haberland", "Lou Apicella", "Barbara S. Mensch", "Ronald H. Gray"], "organizations": ["Population Council", "University of Zambia", "Swaziland Ministry of Health and Social Welfare", "Population Services International", "Bill & Melinda Gates Foundation", "Marie Stopes International", "Jhpiego", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Survey Methodology and Measurement Error", "Public Health Data Accuracy", "Health Literacy and Visual Aids"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b9bfb46a057cec8013ec95ed6e623f71668165519b025b08bce0ca102438ffb6', 'Hill Case Against Circ JMHG 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b9bfb46a057cec8013ec95ed6e623f71668165519b025b08bce0ca102438ffb6.pdf', 'medical_journal', 'ingested', '{"date": "2007-08-20", "description": "In this debate article, George Hill argues strongly against routine, non-therapeutic neonatal male circumcision in the United States, characterizing it as an unnecessary, injurious amputation that destroys specialized protective, sensory, mechanical, and sexual functions of the foreskin. He contends that medical society statements and literature promoting the practice are compromised by cultural bias, financial self-interest, and emotional denial from circumcised practitioners, leading to exaggerated prophylactic claims (such as HIV prevention) while ignoring clear surgical risks, psychological trauma, and complications like MRSA.\n\nFurthermore, the article examines the ethical, legal, and economic implications of the procedure, asserting that non-therapeutic infant circumcision violates the cardinal principles of medical ethics, infringes upon a child''s human rights to bodily integrity, and exceeds lawful parental consent. Hill highlights the substantial financial burden of infant circumcision, estimating that it diverts over $1.2 billion annually in the United States away from medically necessary care, and concludes that infant genital integrity must be respected and protected.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["George Hill"], "organizations": ["Doctors Opposing Circumcision", "Elsevier Ireland Ltd", "WPMH GmbH"], "themes": ["Neonatal Circumcision", "Medical Ethics", "Human Rights and Bodily Integrity", "Foreskin Physiology and Function", "Healthcare Costs and Resource Allocation", "Informed Consent and Child Protection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c8eed3984b28ab3d5eeef65850296b290e9d23bec0ea911deb85da8fb4c93a76', 'Hill Constituting Children''s Bodily Integrity CaseWestResUniv 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c8eed3984b28ab3d5eeef65850296b290e9d23bec0ea911deb85da8fb4c93a76.pdf', 'legal_document', 'ingested', '{"date": "2014", "description": "This article examines the constitutional rights of minors to bodily integrity, focusing specifically on their rights within the family unit vis-\u00e0-vis parental authority. While courts routinely vindicate minors'' bodily integrity rights against state actors and have developed robust protections in reproductive health contexts like abortion and contraception, the doctrine remains largely unaddressed across other domains, including parental corporal punishment, non-therapeutic surgeries, and general medical decision-making. The author highlights the doctrinal divide between parental control and children''s autonomy, interrogating how the legal system treats these issues under disparate common-law and statutory standards rather than constitutional principles.\n\nThe paper frames this incoherence through two competing theories of the family: the liberal view, which treats the family as an incubator for autonomous democratic citizens subject to state intervention, and the parentalist view, which regards parental authority as pre-political and inherently sovereign against state interference. Drawing on Michel Foucault''s theories of disciplinary power and biopower, the author analyzes key doctrinal obstacles, particularly the elusive nature of ''state action'' in the private sphere and the conceptual paradox that state enforcement of privacy rights ultimately invites invasive judicial oversight into the internal decision-making processes of families.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["B. Jessie Hill", "Michel Foucault", "Linda C. McClain", "Amy Gutmann", "Carol Sanger", "Barbara Bennett Woodhouse", "Ian Hacking"], "organizations": ["Case Western Reserve University School of Law", "Social Science Research Network", "Supreme Court of the United States", "Planned Parenthood"], "themes": ["Children''s Rights", "Bodily Integrity", "Parental Rights", "Family Privacy", "Substantive Due Process", "State Action Doctrine", "Reproductive Freedom", "Medical Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6253b3296d063addd4d1730a94dc2bd5abc6421e28065dd657bb0f7d610d96f4', 'Hill_Typology Of GenCuting in Papua_AIDSCare 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6253b3296d063addd4d1730a94dc2bd5abc6421e28065dd657bb0f7d610d96f4.pdf', 'medical_journal', 'ingested', '{"date": "2011-07-14", "description": "This study employs a modified Delphi consensus method among sexual health specialists in Papua New Guinea (PNG) to classify and document diverse variants of penile cutting to guide HIV prevention policy. The research establishes a typology of three distinct categories: formal circumcision involving circumferential foreskin excision, longitudinal incisions (chiefly dorsal slit cuts and variants like the ''V cut'' and ''cowboy cut''), and superficial incisions that do not alter the penile profile. Because dorsal slit procedures are culturally prevalent, technically simpler, and less resource-intensive than medical circumcision, the authors urge further histological and epidemiological research to verify whether dorsal slits offer equivalent protective efficacy against HIV before rolling out nationwide circumcision initiatives.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Peter S. Hill", "Anna Tynan", "Greg Law", "John Millan", "Kelwyn Browne", "Joyce Sauk", "Martha Kupul", "Angela Kelly", "Peter Siba", "John Kaldor", "Andrew Vallely"], "organizations": ["University of Queensland", "Papua New Guinea Institute of Medical Research", "University of New South Wales", "National Department of Health, Papua New Guinea", "Hope Worldwide", "World Health Organization", "UNAIDS"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Penile Cutting Typology", "Sexual Health", "Public Health Policy", "Papua New Guinea Cultural Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7fa55195e2771c9766d9fcb37af9691596ca24ea9ca701a588ffaa7e47cd6b32', 'Hodges History of Instit of Circ in Cold War Era Plenum 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7fa55195e2771c9766d9fcb37af9691596ca24ea9ca701a588ffaa7e47cd6b32.pdf', 'other', 'ingested', '{"date": "1997", "description": "Frederick Hodges examines the history of involuntary genital cutting of male and female children in the United States, characterizing the practice as an unprecedented historical aberration within Western medicine. He argues that the emergence and institutionalization of this practice was a reaction to the cultural and social anxieties brought on by nineteenth-century modernization and industrialization, which enabled an ascendant middle class to reshape social norms and medicalize social control.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Frederick Hodges", "Thomas Szasz", "Denniston", "Milos"], "organizations": ["Plenum Press"], "themes": ["Involuntary Sexual Mutilation", "History of American Medicine", "Modernization and Industrialization", "The Therapeutic State", "Social Control and Medicalization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8d846bf0a84ae613a133c3d77a1e14da03fd383c659fc7fe9ec573a0305d8400', 'Hodges HumanRights in Biotech Era Kluwer 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8d846bf0a84ae613a133c3d77a1e14da03fd383c659fc7fe9ec573a0305d8400.pdf', 'other', 'ingested', '{"date": "2004", "description": "This text examines routine infant male circumcision through the lenses of medical history, bioethics, and human rights, arguing that the practice persists in the United States not due to medical necessity, but because of institutional authoritarianism and the financial commodification of infant tissue. Author Frederick Mansfield Hodges asserts that the modern biotechnology sector has created a lucrative market for harvested foreskin fibroblasts used in commercial skin substitutes, pharmaceuticals, and cosmetics, thereby creating strong economic incentives to preserve neonatal circumcision routines without informed parental consent.\n\nHodges places this phenomenon in a historical context of American medical ethics, detailing how the American Medical Association (AMA) actively resisted strict human experimentation safeguards from the Nuremberg Code and successfully lobbied to eliminate explicit protections for children and prisoners in the 1964 Declaration of Helsinki. Citing past unconsented experiments on hospitalized children and infants, the paper contends that routine circumcision represents a prolonged institutional violation of male bodily integrity that continues to evade modern human rights and bioethical accountability.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Frederick Mansfield Hodges", "George C. Denniston", "Marilyn Fayre Milos", "Sheila Curran", "Edward Annis", "Joseph Garland", "John A. Erickson"], "organizations": ["American Medical Association", "World Medical Association", "National Organization of Circumcision Information Resource Centers", "Food and Drug Administration", "Yale University", "Advanced Tissue Sciences", "Organogenesis"], "themes": ["Bodily Integrity", "Neonatal Circumcision", "Medical Ethics and Informed Consent", "Biotechnology and Tissue Commodification", "Human Rights", "History of Medical Experimentation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2d45221018532f8cc78542e9c0b484a1a166f1204982c1befc850b13d7a843bf', 'Hodges Med History in Docs Words.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2d45221018532f8cc78542e9c0b484a1a166f1204982c1befc850b13d7a843bf.pdf', 'other', 'ingested', '{"date": "1996", "description": "This document compiles late-19th-century medical writings and statistics tracing the emergence and rationalization of non-religious male circumcision in North America between 1860 and 1896. Through historical quotations from physicians and medical journals, it demonstrates how circumcision was promoted primarily as an intervention to deter or punish masturbation, frequently without anaesthesia to reinforce the deterrent effect, as well as an alleged prophylactic and treatment for a broad spectrum of neurological, systemic, and physical disorders.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Frederick Hodges", "Athol A.W. Johnson", "M.J. Moses", "Lewis L. Sayer", "Angel Money", "John Harvey Kellogg", "Jefferson C. Crossland", "Jonathan Hutchinson", "Charles E. Fisher", "E. J. Spratling"], "organizations": ["Lancet", "New York Medical Journal", "American Medical Association", "Medical Record"], "themes": ["History of Circumcision", "Masturbation and Social Purity", "19th-Century Medicine", "Pediatric Health", "Pain and Surgical Punishment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('69bfae4e33a16747432b23c12a752000a98c1f1615d1e17590a6853189676ca3', 'Hodges-Svob-VanHowe Prophylactic_Interv JME 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/69bfae4e33a16747432b23c12a752000a98c1f1615d1e17590a6853189676ca3.pdf', 'medical_journal', 'ingested', '{"date": "2002", "description": "This article examines the ethical boundaries of prophylactic medical interventions on children, addressing the tension between individual human rights and public health objectives. Because children lack legal competence to provide informed consent and are uniquely vulnerable to proxy decision-making, the authors establish a rigorous framework of criteria that must be met before invasive prophylactic measures can be justified under either the ''best interest of the child'' or ''public health'' doctrines. They argue that irreversible or invasive interventions on healthy minors are ethically impermissible when conditions can instead be prevented through conservative measures or voluntary behavioral decisions made in adulthood.\n\nThe authors apply their proposed criteria to four illustrative procedures: prophylactic mastectomy, routine immunizations, cosmetic ear surgery (otoplasty), and neonatal male circumcision. They conclude that while routine vaccinations against airborne, highly contagious diseases satisfy ethical standards due to minimal bodily alteration and substantial societal benefit, procedures like non-therapeutic cosmetic ear surgery and neonatal circumcision fail to meet necessary thresholds. Specifically, routine infant circumcision violates bodily integrity and human rights without presenting urgent clinical necessity, demonstrable net benefit, or insurmountable public health threats that cannot be addressed conservatively.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["F M Hodges", "J S Svoboda", "R S Van Howe"], "organizations": ["Yale University", "Attorneys for the Rights of the Child", "Michigan State University College of Human Medicine", "American Academy of Pediatrics"], "themes": ["Bioethics", "Pediatric Informed Consent", "Children''s Rights and Bodily Integrity", "Neonatal Circumcision", "Public Health vs. Individual Autonomy", "Prophylactic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d78225be78c5900b45909088cf7bace715eb47156d9b00be04442ad2c7739d42', 'Horowitz African Women Confront Amer Medicine JGIM 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d78225be78c5900b45909088cf7bace715eb47156d9b00be04442ad2c7739d42.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This article explores the complex clinical, cultural, and ethical challenges American healthcare providers face when caring for East African immigrant and refugee women who have undergone female circumcision (traditional female genital surgery). Although Western clinicians largely support efforts to abolish the practice, moral condemnation and visceral reactions often alienate circumcised women and prevent them from seeking necessary medical care. The authors discuss the historical background, classifications, cultural significance, and medical complications of the practice\u2014including urinary obstruction, recurrent infections, sexual dysfunction, and severe obstetric risks.\n\nDrawing on interviews with Somali, Ethiopian, and Eritrean immigrants as well as clinical experience, the authors present practical guidelines and case examples for managing circumcised patients. They advise clinicians to respect patients'' modesty and autonomy, manage obstructive and gynecologic sequelae sensitively (including elective defibulation), avoid sensationalizing or medicalizing traditional practices, and work with professional interpreters. The paper emphasizes that cultural change regarding female circumcision must come from community-led education and trust rather than outsider condemnation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Carol R. Horowitz", "J. Carey Jackson", "Richard Deyo", "Thomas Koepsell", "Lula Hussein"], "organizations": ["Mount Sinai Medical Center", "University of Washington", "Society of General Internal Medicine", "Robert Wood Johnson Foundation", "Henry Kaiser Family Foundation", "World Health Organization", "Equality Now", "Forward USA"], "themes": ["Female Genital Surgery / Circumcision", "Cross-Cultural Healthcare", "Refugee and Immigrant Health", "Obstetric and Gynecologic Complications", "Clinical Guidelines and Defibulation", "Medical Ethics and Cultural Competence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fca461992c86aaf5645454c602ee9803b86f91e8a15735b793df36f9912b338e', 'Hsieh Foreskin development IntJUrol 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fca461992c86aaf5645454c602ee9803b86f91e8a15735b793df36f9912b338e.pdf', 'medical_journal', 'ingested', '{"date": "2006", "description": "This clinical study evaluated foreskin development and the prevalence of physiological phimosis in 2,149 schoolboys across the first, fourth, and seventh grades in suburban Taichung, Taiwan. All examinations were conducted by a single urologist categorizing foreskin retractability into five distinct types, alongside recording other external genital abnormalities. The results revealed a significant developmental progression toward natural foreskin retractability, with normal prepuce incidence rising from 8.2% in first-graders to 58.1% in seventh-graders, while severe phimosis decreased from 17.1% to 1.2%.\n\nThe authors conclude that physiological phimosis is a benign condition that naturally resolves with age as boys approach adolescence. Because spontaneous resolution is widespread and related complications like balanoposthitis are rare, routine surgical interventions such as circumcision are generally unnecessary for school-aged boys presenting with unretractable foreskins.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Teng-Fu Hsieh", "Chaog-Hsian Chang", "Shih-San Chang"], "organizations": ["China Medical University Hospital", "China Medical University", "Blackwell Publishing Asia"], "themes": ["Pediatric Urology", "Foreskin Development", "Physiological Phimosis", "Circumcision", "Adolescent Genital Anatomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7e41b7155294950cc48f487daf956db3af866a4ce0337a0812b3ba94510f79a', 'Hull Male circumcision SE Asia ReproHlth 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7e41b7155294950cc48f487daf956db3af866a4ce0337a0812b3ba94510f79a.pdf', 'medical_journal', 'ingested', '{"date": "2001-11-01", "description": "This academic paper investigates male sexual and reproductive health practices in Southeast Asia, with a particular focus on Indonesia, alongside findings from Thailand, the Philippines, and Vietnam. It examines various manifestations of male circumcision\u2014ranging from unmonitored mass circumcision events and non-clinical procedures to risky traditional rites like West Timor''s sifon\u2014as well as penile enhancements (such as the subdermal insertion of ball bearings, plastics, and silicon) and female ''dry sex'' practices. The authors note that while these interventions are often driven by indigenous constructs of gender, power, and the pursuit of mutual or heightened sexual pleasure, they lack clinical oversight and pose severe health risks, including haemorrhage, infection, permanent tissue trauma, and pain for both sexual partners.\n\nThe authors argue that public health policy has historically overlooked male-specific reproductive health needs following the female-centric focus of the 1994 Cairo Conference. They advocate for standard operating procedures (SOPs) and clinical regulation for male circumcision, alongside targeted health education campaigns to discourage dangerous penile inserts, implants, and vaginal drying agents in favor of sexual practices grounded in mutual communication and safety.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Terence H. Hull", "Meiwita Budiharsana", "Primus Lake", "Wassana Im-Em", "Firman Lubis", "Michael Lim Tan"], "organizations": ["Reproductive Health Matters", "Taylor & Francis", "Australian National University", "Population Council", "Yayasan Kusuma Buana", "Klinik Baruna"], "themes": ["Male Circumcision", "Penis Enhancement", "Sexual and Reproductive Health", "Public Health and Safety Standards", "Gender Constructs and Sexuality", "Traditional Practices and Rites of Passage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4e15d5ab2336a4db3301dc8a18184e8dbbcbc6d53736b594c70cd00537f548b1', 'Hung et al Longitudinal cumulative risk JSurgRes 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4e15d5ab2336a4db3301dc8a18184e8dbbcbc6d53736b594c70cd00537f548b1.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This study presents a longitudinal population analysis investigating the cumulative early and late risks of circumcision in male children under the age of five, utilizing data from the California Office of Statewide Health Planning and Development database between 2005 and 2010. Among the 24,432 patients analyzed, the cumulative complication rate over five years was 1.5% for neonates and 2.9% for non-neonates, with non-neonates facing a significantly higher risk of early complications.\n\nThe authors conclude that circumcision complication rates are higher than previously recognized, noting that most patients who experienced late complications required operative circumcision revision. The findings suggest that clinicians must carefully weigh surgical risks against reported health benefits when counseling parents and obtaining informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ya-Ching Hung", "David C. Chang", "Maggie L. Westfal", "Isobel H. Marks", "Peter T. Masiakos", "Cassandra M. Kelleher"], "organizations": ["Massachusetts General Hospital", "Harvard Medical School", "Northwick Park Hospital", "MassGeneral Hospital for Children", "California Office of Statewide Health Planning and Development", "Elsevier"], "themes": ["Circumcision Complications", "Pediatric Surgery", "Long-term Surgical Outcomes", "Revision Circumcision", "Informed Consent and Risk-Benefit Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('59b566b07a514c5d51989366c9ff51620b3d07042651e1ca7b0b0b97a73cc5ab', 'Hussain Comparative Langerhans in Female Immunology 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/59b566b07a514c5d51989366c9ff51620b3d07042651e1ca7b0b0b97a73cc5ab.pdf', 'medical_journal', 'ingested', '{"date": "1995", "description": "This study conducts a comparative immunohistological analysis of human and primate mucosal epithelia (oral, cervicovaginal, foreskin, urethral, and rectal) to assess the distribution of potential human immunodeficiency virus (HIV) receptors, including CD4 glycoproteins, Fc receptors for IgG (Fc\u03b3R), and HLA class II antigens, alongside Langerhans'' cells. The findings demonstrate that CD4+ Langerhans'' cells are significantly abundant in the foreskin and cervicovaginal mucosa, and Fc\u03b3 receptors are present in urethral, rectal, and endocervical tissues, providing potential biological pathways for sexual transmission and explaining the heightened susceptibility associated with intact foreskin.\n\nIn contrast, normal oral epithelium exhibited a marked paucity of Langerhans'' cells expressing the HIV-binding V1 domain of CD4, lacked Fc\u03b3 receptors (except for Fc\u03b3RIII in gingival tissue), and did not express HLA class II antigens. These morphological and immunological characteristics argue against the transmission of HIV through healthy, intact oral mucosa during oral sex or kissing, although mucosal breaches such as ulcers or gingivitis could circumvent these natural barriers.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["L. A. Hussain", "T. Lehner", "P. Robinson", "M. Jourdan", "M. Chapman"], "organizations": ["United Medical and Dental Schools of Guy''s & St Thomas'' Hospitals", "Medical Research Council", "Blackwell Science Ltd"], "themes": ["HIV Transmission", "Mucosal Immunity", "Langerhans'' Cells", "CD4 Receptors", "Fc Receptors", "Genitourinary and Oral Epithelia"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fe1b027c4c738abb6cb94acec574dfc2486b53536572be82143617fee556ef86', 'Iacob Systematic review of complications BJUICompass 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fe1b027c4c738abb6cb94acec574dfc2486b53536572be82143617fee556ef86.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This systematic review analyzes literature published between 2000 and 2020 on the complications arising from male circumcision, examining 78 selected studies comprising cohort studies, chart reviews, case series, and medical society guidelines. The authors identify and catalog 47 distinct complications resulting from the procedure, ranging from common and treatable issues like postoperative bleeding and minor infections to severe, life-altering outcomes such as partial or complete penile amputation, necrosis, urethrocutaneous fistula, severe meatal stenosis, and death.\n\nThe authors observe that complication rates rise substantially when circumcision is performed outside the neonatal period, by inexperienced practitioners, in non-sterile or non-medical ritual settings, or without prior screening for congenital bleeding disorders. Consequently, the paper stresses that healthcare providers must understand the full spectrum of potential risks to deliver comprehensive, unbiased counseling, allowing parents to make informed decisions and recognize that routine neonatal circumcision can be safely declined.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stanca Iris Iacob", "Richard S. Feinn", "Lauren Sardi", "Andrew L. Freedman"], "organizations": ["Quinnipiac University", "American Academy of Pediatrics", "Canadian Paediatric Society", "Centers for Disease Control and Prevention", "BJU International"], "themes": ["Male Circumcision Complications", "Neonatal Surgery", "Pediatric Urology", "Informed Consent and Medical Ethics", "Surgical Safety and Sanitation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e0a0e5d103a546be490993a1776d6c7b6ab474bc15352dcd2dd2e89c4bceb0de', 'Immerman BioCult Anal Circ SocBiol 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e0a0e5d103a546be490993a1776d6c7b6ab474bc15352dcd2dd2e89c4bceb0de.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This article presents a biocultural hypothesis regarding male circumcision, arguing that beyond its religious, symbolic, and ritualistic roles, the practice serves an adaptive social function by reducing the sexual excitability and distractibility of adolescent males. The authors hypothesize that early excision of the richly innervated prepuce induces lasting cortical reorganization in the somatosensory system, keratinizes and desensitizes the glans penis, and removes Tyson''s glands that secrete potentially disruptive pheromones in smegma.\n\nBy dampening sexual distraction and raising arousal thresholds without reducing potency or necessary inter-group aggression, circumcision is argued to make young men more tractable and amenable to authority. This enhanced behavioral compliance and reduced intra-group friction provides a competitive advantage to tribes and societies practicing circumcision, facilitating group cooperation and long-term societal continuity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ronald S. Immerman", "Wade C. Mackey", "Moses Maimonides"], "organizations": ["MetroHealth Medical Center", "Case Western Reserve University"], "themes": ["Circumcision", "Biocultural Evolution", "Neuroplasticity and Cortical Reorganization", "Sexual Excitability and Behavior", "Societal Competition and Tractability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d91501d9f3a57c5be0d7d4278aeb6c64fc9328721af1a902229dc28a84ba3128', 'Immerman Neural Reorganization JGenPsych 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d91501d9f3a57c5be0d7d4278aeb6c64fc9328721af1a902229dc28a84ba3128.pdf', 'medical_journal', 'ingested', '{"date": "1998-09-01", "description": "This document is an academic article citation titled ''A Proposed Relationship Between Circumcision and Neural Reorganization'' authored by Ronald S. Immerman and Wade C. Mackey. Published in The Journal of Genetic Psychology, the work explores a theoretical connection between male circumcision and subsequent neurological or neural reorganization.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ronald S. Immerman", "Wade C. Mackey"], "organizations": ["The Journal of Genetic Psychology", "ProQuest"], "themes": ["Circumcision", "Neural Reorganization", "Psychology", "Neurology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('98cc55c79063ea50bc9afea4bc7e0965729afac38fdfa38a9b150cfc197d6032', 'Jackson Alt Rituals as Protest-AssnJewStud 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/98cc55c79063ea50bc9afea4bc7e0965729afac38fdfa38a9b150cfc197d6032.pdf', 'other', 'ingested', '{"date": "2021", "description": "In this article, Lindsey Jackson examines the growing phenomenon of Jewish parents choosing not to circumcise their sons and replacing the traditional bris with alternative, noncutting rituals. Rather than representing an abandonment of Jewish identity, Jackson argues that this decision serves as an act of intracommunal protest and active engagement with Jewish tradition, allowing families to dissent against an act they view as patriarchal or harmful while retaining the celebratory, communal, and naming elements of the lifecycle event.\n\nWhile such decisions frequently encounter familial friction, particularly from grandparents, the adaptation of rituals\u2014such as washing the baby''s hands and feet, symbolic fruit cutting, or parental blood donation\u2014demonstrates a dynamic reinterpretation of Jewish ritual practice. Jackson concludes that questioning, debating, and adapting traditions are core tenets of Jewish heritage, framing these alternative rituals as deeply rooted within Jewish tradition rather than external to it.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lindsey Jackson", "Ilana Zeffren", "Benjamin Netanyahu"], "organizations": ["Association for Jewish Studies", "Concordia University", "Brandeis University", "Hornstein Jewish Professional Leadership Program"], "themes": ["Jewish Rituals and Tradition", "Circumcision and Brit Milah", "Intracommunal Protest and Dissent", "Parenting and Generational Conflict", "Religious Innovation and Adaptation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fe279627df2e78adb776e78b1b1f5fe5ec0c73eea340703f50fbe84fb3480282', 'Jackson To_Be_Not_To_Be_Analysis 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fe279627df2e78adb776e78b1b1f5fe5ec0c73eea340703f50fbe84fb3480282.pdf', 'other', 'ingested', '{"date": "2026-02-09", "description": "This independent research paper proposes that male circumcision historically functions as a technology of social control correlated with the emergence of institutionalized sexual violence. Using a human-AI collaborative framework termed the Recursive Inquirors\u2122 methodology, the authors conduct a comparative historical review contrasting circumcising societies (such as Ancient Egypt, Babylon, Islamic Caliphates, and Victorian America) against non-circumcising societies (such as Zoroastrian Persia, pre-Christian Northern Europe, and pre-contact Japan).\n\nThe authors argue that reducing genital sensitivity manufactures population-level sexual frustration, which in turn fosters demand for institutional systems of exploitation like concubinage, prostitution, and mass sexual assault. Citing Victorian-era medical texts from figures like John Harvey Kellogg and Sir Jonathan Hutchinson, the paper asserts that social control and the prevention of masturbation were explicit historical motivations rather than modern medical hygiene.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kannsas City Shadow Jackson", "Malcolm Claude Jackson", "John Harvey Kellogg", "Jonathan Hutchinson", "Paul of Tarsus", "Saladin", "Cyrus of Persia"], "organizations": ["Anthropic", "Kellogg Company", "Darbon Institute", "Wellcome Collection", "Environmental Protection Agency"], "themes": ["Male Circumcision", "Social Control", "Institutional Sexual Violence", "Victorian Medicine", "Comparative History", "Recursive Inquirors Methodology", "Projection Mechanism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('01d9721a0affd9e42f792c56a3bfef7d852b86573a1bad14a56c31911588a229', 'Jacobs Ethics of Inf Circ IMAJ 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/01d9721a0affd9e42f792c56a3bfef7d852b86573a1bad14a56c31911588a229.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This article examines the ethical and legal debates surrounding elective infant male circumcision, arguing against recent efforts in Western democracies to restrict or criminalize the practice. Grounding the defense in political pluralism and parental discretion, the author contends that liberal democratic states should tolerate religious and cultural minority practices unless they cause substantial societal harm or impose burdens no reasonable person would accept. Highlighting medical evidence that shows prophylactic benefits (such as reduced HIV and HPV transmission) paired with minimal surgical risks, the author refutes counterarguments concerning bodily integrity and gender equality, concluding that physicians may ethically perform the procedure with informed parental consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Allan J. Jacobs", "Isaiah Berlin", "Eitan Israeli"], "organizations": ["American Academy of Pediatrics", "Royal Dutch Medical Association", "World Health Organization", "Stony Brook University School of Medicine", "Flushing Hospital Medical Center", "United Nations"], "themes": ["Infant Circumcision", "Medical Ethics", "Religious Liberty", "Pluralism", "Bodily Integrity", "Parental Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('30f4ddaea157baed6154c1a914f029b064ecdc1a8c72fc5b9fe4c69fcda28614', 'Jacobs Phys Alteration JReligHlth 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/30f4ddaea157baed6154c1a914f029b064ecdc1a8c72fc5b9fe4c69fcda28614.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This article examines and refutes arguments that ritual infant male circumcision should be legally prohibited on the grounds that it violates a child''s bodily integrity and personal autonomy. Focusing on Jewish and Islamic traditions, the author critiques the secular, Kantian-influenced framework advanced by groups such as the Brussels Collaboration on Bodily Integrity, which asserts that non-consensual bodily alteration is inherently impermissible even without demonstrable harm. Jacobs argues that the physical and psychological harms attributed to circumcision are objectively de minimis and do not warrant coercive state interference.\n\nThe author contends that rituals like circumcision play a crucial role in fostering community solidarity, identity, and cultural transmission. Evaluating state intervention through a structured harm-and-benefit framework, the paper concludes that infant circumcision entails risks no greater than widely accepted pediatric practices, such as orthodontia or youth contact sports. Consequently, outlawing ritual circumcision represents an overreach of state authority that threatens religious pluralism, minority cultural survival, and familial rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Allan J. Jacobs", "Immanuel Kant", "Brian D. Earp", "Richard A. Shweder", "John Rawls"], "organizations": ["Brussels Collaboration on Bodily Integrity", "Parliamentary Assembly of the Council of Europe", "United Nations", "World Health Organization", "Coney Island Hospital", "Stony Brook University"], "themes": ["Ritual Circumcision", "Bodily Integrity", "Parental Rights", "Religious Freedom", "Bioethics and Autonomy", "State Intervention", "Cultural Pluralism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dfcfafb8c7b38943b6cc1cf39a7c5a03756fda23011507203975bce0b10d4d8b', 'Jacobs-Arora-ritual-male-circumcision&HR AmJBio 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dfcfafb8c7b38943b6cc1cf39a7c5a03756fda23011507203975bce0b10d4d8b.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-12", "description": "This article evaluates the ethical and human rights considerations surrounding ritual male infant circumcision, responding to critics who argue that the practice violates nonmaleficence, bodily integrity, and a child''s right to an open future. Reviewing epidemiological and clinical evidence, the authors demonstrate that the medical risks associated with infant circumcision are low, while evidence-based health benefits\u2014including reduced transmission of HIV, HPV, and other infections\u2014outweigh these risks. Consequently, arguments seeking to abolish the practice on the grounds of nonmaleficence fail.\n\nThe authors further analyze autonomy-based human rights arguments, concluding that ritual male infant circumcision does not constitute a universal human rights violation. They introduce a three-part test (the Jacobs test) to assess parental decisions regarding children and show that circumcision meets the criteria for ethical permissibility. While individual states may regulate or proscribe the practice based on local cultural norms or police powers, there is no universal human rights mandate requiring the legal restriction of ritual infant circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Allan J. Jacobs", "Kavita Shah Arora", "Robert Darby", "J. Steven Svoboda", "Joseph Mazor"], "organizations": ["Stony Brook University School of Medicine", "Case Western Reserve University", "American Academy of Pediatrics", "World Health Organization", "Royal Dutch Medical Association", "Taylor & Francis"], "themes": ["Male Infant Circumcision", "Human Rights", "Bioethics", "Bodily Integrity", "Parental Rights", "Religious Freedom"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('39962e66424cf57017a6caf74029db4fcceea96e73b5ec35d673aba2fcf206f7', 'Jacobson Circumcision Trends2003-2016 Urol 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/39962e66424cf57017a6caf74029db4fcceea96e73b5ec35d673aba2fcf206f7.pdf', 'medical_journal', 'ingested', '{"date": "2021-01", "description": "This retrospective cohort study analyzes nationwide trends in neonatal male circumcision prior to hospital discharge in the United States from 2003 to 2016 using data from the Kids'' Inpatient Database (KID). Evaluating an estimated cohort of over 8 million boys, the researchers found that 55.0% underwent neonatal circumcision, with overall rates decreasing from 57.4% to 52.1% over the study period. Rates did not significantly rebound following the American Academy of Pediatrics'' (AAP) 2012 policy statement affirming medical benefits and recommending reimbursement.\n\nThe findings demonstrate substantial disparities based on socioeconomic and demographic factors. Circumcision was significantly more prevalent among privately insured boys (64.9%) compared to publicly insured boys (44.6%), as well as among Black and White boys, families in higher income quartiles, and residents of the Midwest. The authors conclude that persistent lower rates among publicly insured neonates highlight ongoing barriers to access and insurance coverage disparities despite clinical recommendations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Deborah L. Jacobson", "Lauren C. Balmert", "Jane L. Holl", "Ilina Rosoklija", "Matthew M. Davis", "Emilie K. Johnson", "Timothy B. Lautz"], "organizations": ["American Urological Association Education and Research, Inc.", "American Academy of Pediatrics", "University of Utah", "Primary Children\u2019s Hospital", "Northwestern University", "University of Chicago", "Ann & Robert H. Lurie Children\u2019s Hospital of Chicago", "Agency for Healthcare Research and Quality", "Urology Care Foundation", "Societies for Pediatric Urology"], "themes": ["Neonatal Circumcision Trends", "Healthcare Disparities", "Health Insurance and Reimbursement", "Pediatric Health Policy", "Socioeconomic Determinants of Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('328cb0dfdd7bc133d7160429ec9dbcf2b85f5cd9ec1ae0da276af3bb77aa74ca', 'JAMA Peds Circ-Barrett Email 2025-11-18.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/328cb0dfdd7bc133d7160429ec9dbcf2b85f5cd9ec1ae0da276af3bb77aa74ca.pdf', 'letter', 'ingested', '{"date": "2025-11-18", "description": "This document is a formal complaint letter addressed to the American Medical Association (AMA) Editorial Governance Committee and the Committee on Publication Ethics (COPE) regarding a patient page on circumcision published by JAMA Pediatrics on July 28, 2025. The author argues that the publication contains significant ethical and compliance failures, primarily its reliance on an expired 2012 American Academy of Pediatrics (AAP) policy that lapsed in 2017 without disclosure, thereby misleading readers about current medical endorsements and breaching editorial accuracy standards.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Kevin R. Barrett"], "organizations": ["JAMA Pediatrics", "American Medical Association", "Committee on Publication Ethics", "American Academy of Pediatrics"], "themes": ["Medical Ethics", "Publication Ethics", "Circumcision", "Editorial Accuracy", "Pediatric Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1fb8db6ab83ea4b50561f75397faf7e2912579540ecbcc7175cacf79b1f0d66b', 'JAMA Peds Circ-Barrett Formal Letter 2025-07-28.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1fb8db6ab83ea4b50561f75397faf7e2912579540ecbcc7175cacf79b1f0d66b.pdf', 'letter', 'ingested', '{"date": "2025", "description": "This formal letter addressed to the American Medical Association (AMA) Editorial Governance Committee and the Committee on Publication Ethics (COPE) raises serious ethical and editorial concerns regarding a JAMA Pediatrics Patient Page on infant male circumcision published on July 28, 2025. The author, Kevin Barrett, argues that the publication misleads clinicians and parents by relying on an expired 2012 American Academy of Pediatrics policy, omitting citations for quantitative claims, overstating long-term medical benefits, and providing inadequate mitigation for a lead author''s patent-related conflict of interest.\n\nAdditionally, the letter criticizes the piece for failing to address ethical questions surrounding bodily autonomy and omitting the specialized anatomy and physiological functions of the foreskin, which compromises informed consent. Barrett calls on the AMA and COPE to investigate the editorial process, issue a formal correction or retraction, and update editorial standards to mandate evidence citations, balanced risk-benefit framing, and comprehensive anatomical and ethical disclosures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Kevin Barrett"], "organizations": ["American Medical Association", "Committee on Publication Ethics", "American Academy of Pediatrics", "JAMA Pediatrics"], "themes": ["Infant Circumcision", "Publication Ethics", "Informed Consent", "Conflict of Interest", "Editorial Standards", "Pediatric Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e2b7c1bbc9cc99faea92ebc2bce5468099957b4dda0553df50adc4c97ce1e697', 'JAMA Peds Circ-Change Comparison.jpeg', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e2b7c1bbc9cc99faea92ebc2bce5468099957b4dda0553df50adc4c97ce1e697.pdf', 'other', 'ingested', '{"date": "2025-12-19", "description": "This document presents a side-by-side comparative analysis between the original version of an article on circumcision and its corrected version dated December 19, 2025. The revisions demonstrate a shift toward more neutral, anatomically accurate, and cautious language, incorporating ethical considerations surrounding bodily autonomy, softening claims regarding health benefits and sexual function, removing outdated policy references and alarming imagery, and clarifying conflicts of interest.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["AAP"], "themes": ["Circumcision", "Medical Ethics", "Bodily Autonomy", "Editorial Corrections", "Informed Consent", "Health Communication"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d7750074ddc4b04de34e27af38bbebcf96995fec9b3621f1acc5f9fc5f0219d6', 'JAMA Peds Circ-Influencer Impact.jpeg', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d7750074ddc4b04de34e27af38bbebcf96995fec9b3621f1acc5f9fc5f0219d6.pdf', 'other', 'ingested', '{"date": null, "description": "This document presents a comparative analysis evaluating the influence of different sources on editorial corrections made to the JAMA Pediatrics Circumcision Patient Page. It tracks specific modifications\u2014such as the removal of expired American Academy of Pediatrics (AAP) policy citations, inclusion of bodily autonomy framing, adjustments to risk-benefit claims, and improved anatomical precision\u2014against critiques raised in a formal letter by Kevin Barrett and various public comments.\n\nThe findings conclude that Kevin Barrett''s letter to JAMA editorial leadership served as the primary or shared catalyst for most corrections, notably regarding conflict of interest disclosures, anatomical accuracy, unsupported statistics, and the issuance of a formal correction notice. Meanwhile, public comments, particularly from Van Howe and Bollinger, were identified as influential in refining terminology, benefit claims, and addressing paraphimosis content.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kevin Barrett", "Van Howe", "Bollinger", "Armstrong", "Winter-Stoltzman"], "organizations": ["JAMA Pediatrics", "American Academy of Pediatrics"], "themes": ["Circumcision", "Medical Editorial Standards", "Scientific Accuracy and Corrections", "Conflict of Interest Disclosure", "Bodily Autonomy and Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('aca02bd5ce6930434ee78c121506d43718a8205a78259ff9b450068dcb0d8583', 'Jang Nerves in Glans JAnatSocIndia 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/aca02bd5ce6930434ee78c121506d43718a8205a78259ff9b450068dcb0d8583.pdf', 'medical_journal', 'ingested', '{"date": "2017-11-26", "description": "This immunohistochemical study investigates the micro-neuroanatomy and innervation of the cavernous tissue in the human glans penis using tissue specimens from 20 elderly male cadavers. By evaluating expressions of S100, neuronal nitric oxide synthase (nNOS), tyrosine hydroxylase (TH), and vasoactive intestinal polypeptide (VIP), the researchers mapped the terminal branches of the dorsal nerve of the penis as they traverse through collagenous neurovascular bundles toward the superficial skin.\n\nThe findings show that terminal branches divide into fine nerve fibers within the cavernous tissue, containing both autonomic (sympathetic TH-positive and parasympathetic nNOS-positive) and sensory fibers. While the dorsal half receives thicker nerve branches, the ventral glans skin demonstrates a significantly higher density of thinner nerve branches and arduous nerve paths near the coronal sulcus. These precise anatomical insights provide critical guidance for penile surgical procedures and incisions to prevent inadvertent sensory nerve damage.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hyung Suk Jang", "Nobuyuki Hinata", "Kwang Ho Cho", "Yukari Bando", "Gen Murakami", "Shin-Ichi Abe"], "organizations": ["Ongoul Rehabilitation Hospital", "Kobe University Graduate School of Medicine", "Wonkwang University School of Medicine and Hospital", "Iwamizawa Asuka Hospital", "Tokyo Dental College", "Anatomical Society of India", "Elsevier"], "themes": ["Penile Neuroanatomy", "Immunohistochemistry", "Glans Penis Innervation", "Dorsal Nerve of the Penis", "Autonomic Nervous System", "Surgical Anatomy and Nerve Preservation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1ffa49174d90579371588937f284ec3d3c94d612fdc71adeb8d2bb83d0275209', 'Jansen Routine_circumcision_common ground JPaedsChildHealth 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1ffa49174d90579371588937f284ec3d3c94d612fdc71adeb8d2bb83d0275209.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This viewpoint article addresses the deeply polarized debate over routine infant male circumcision, which ranges from ''intactivists'' advocating for a child''s right to bodily integrity to proponents viewing it as a beneficial surgical intervention. The author notes that while major international pediatric bodies interpret the medical benefits and risks differently, they generally agree on common ground: evidence does not support either a mandatory routine procedure or an outright legal prohibition, leaving the choice within the scope of parental discretion.\n\nGiven that a legal ban in Australia is improbable in the foreseeable future, the author argues for a pragmatic harm-reduction approach. This strategy entails urgent legislative and regulatory reforms to mandate adequate anesthesia\u2014specifically dorsal penile nerve blocks combined with topical cream\u2014restrict the procedure to competent practitioners capable of managing complications, and provide standardized, unbiased information to prospective parents during antenatal and neonatal care to ensure truly informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Melanie Jansen", "Lynn Gillam"], "organizations": ["Royal Australasian College of Physicians", "American Academy of Pediatrics", "Centre for Children\u2019s Health Ethics and Law", "Lady Cilento Children\u2019s Hospital", "Royal Dutch Medical Association", "Royal Australian College of General Practitioners", "Canadian Paediatric Society", "British Medical Association"], "themes": ["Infant Male Circumcision", "Bioethics and Bodily Integrity", "Neonatal Pain Management and Anaesthesia", "Parental Discretion and Informed Consent", "Healthcare Regulation and Law Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('809303cd6e602a1f56173c30c28b7040951a5ff7b3db1aea3e433baea7b0f3ba', 'Jed Eye Stop_Racist Cutting Africa (paper) 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/809303cd6e602a1f56173c30c28b7040951a5ff7b3db1aea3e433baea7b0f3ba.pdf', 'other', 'ingested', '{"date": "2014", "description": "This advocacy document calls for an immediate end to Voluntary Medical Male Circumcision (VMMC) and Early Infant Male Circumcision (EIMC) campaigns funded by Western health and development agencies across 13 African nations. The author contends that the clinical trials linking circumcision to reduced HIV transmission are methodologically flawed, ethically compromised, and scientifically unsupported, arguing that real-world demographic data often correlates circumcision with higher HIV prevalence.\n\nThe document further asserts that mass circumcision efforts exacerbate the HIV epidemic through behavioral risk compensation, surgical transmission, and the potential reuse of non-sterile equipment, while causing irreversible physical trauma and violating fundamental human rights and informed consent. It argues that the millions of dollars allocated to these campaigns represent neocolonial overreach and should instead be redirected toward highly cost-effective preventative measures, such as condom distribution, sanitation, and clean water infrastructure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert Bailey", "Bertran Auvert", "Daniel Halperin", "Rebeca Plank", "Sithembile Mlotshwa", "Yoweri Museveni", "Felix Magalela Mafa", "Rajiv Shah"], "organizations": ["World Health Organization", "United States Agency for International Development", "The United States President''s Emergency Plan for AIDS Relief", "Bill & Melinda Gates Foundation", "Clinton Foundation", "Parliamentary Assembly of the Council of Europe", "Population Services International", "Brigham and Women''s Hospital", "Massachusetts General Hospital"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Medical Ethics and Informed Consent", "Children''s Rights and Bodily Integrity", "Global Health Policy", "Risk Compensation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('328a64cda753f60cedd93fc7a398e605859246feb49ac90b6959a59627c4ebda', 'Johnsdotter Created_by_God_Somalis_in_Sweden 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/328a64cda753f60cedd93fc7a398e605859246feb49ac90b6959a59627c4ebda.pdf', 'other', 'ingested', '{"date": "2002", "description": "This doctoral dissertation investigates how Somali immigrants living in Swedish exile negotiate, reassess, and largely abandon traditional practices of female circumcision, particularly pharaonic circumcision (infibulation). Based on multi-year ethnographic fieldwork and qualitative interviews in Roseng\u00e5rd (Malm\u00f6), the study argues that changed living conditions, shifts in gender roles, and a re-evaluation of Islamic tenets (specifically the belief that harming God''s creation is forbidden) have led to a community-wide tipping point away from the practice.\n\nContrasting the internal Somali discourse of abandonment and changing cultural strategies with the Swedish majority discourse, the author demonstrates how media portrayals, political debates, and public policies often foster an alarmist ''moral panic'' fueled by cultural essentialism. The dissertation challenges the persistent Western stereotype of Swedish Somali girls being widely subjected to illegal genital cutting, scrutinizes international medical and anthropological literature on female circumcision and sexuality, and advocates for empirical nuance over sensationalism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sara Johnsdotter", "Asha Omar", "Aje Carlbom", "Ali Elmi", "Birgitta Ess\u00e9n", "Steven Sampson", "Gerry Mackie"], "organizations": ["Lund University", "Socialstyrelsen", "World Health Organization", "City of Malm\u00f6", "Wadajir", "Sveriges Television (SVT)"], "themes": ["Female Circumcision / Female Genital Mutilation (FGM)", "Somali Exile and Integration in Sweden", "Cultural Change and Convention Theory", "Moral Panic and Media Discourse", "Islamic Theology and Bodily Harm", "Gender Roles and Clan Structures", "Female Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf6925b04bfbc98bad6ab24725942d4faa7fa5d0e2faa7c510b6275c77b2ab95', 'Johnsdotter FGC Global North South 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf6925b04bfbc98bad6ab24725942d4faa7fa5d0e2faa7c510b6275c77b2ab95.pdf', 'other', 'ingested', '{"date": "2020", "description": "This document comprises the front matter, introduction, and opening chapters of an edited academic volume titled ''Female Genital Cutting: The Global North and South'', published in 2020 by Malm\u00f6 University. Originating from the 9th conference of the Nordic Network for Research on FGC (FOKO), the anthology examines the medical, legal, ethical, and anthropological dimensions of female genital cutting/mutilation (FGC/FGM). The introductory sections explore the ongoing controversies surrounding terminology (''female circumcision'' versus ''FGM'' versus ''FGC''), review the WHO typologies, outline the historical emergence of FGC research and policy within the Nordic diaspora, and reflect on decades of intervention strategies.\n\nSubsequent chapters analyze the historical and contemporary tensions between the Global North and South regarding anti-FGC campaigns. Anthropologist Ellen Gruenbaum critiques Western ethnocentrism and neo-colonial narratives, contrasting the zero-tolerance stance on African practices with the Western acceptance of female cosmetic genital surgery, while examining positive-norm initiatives like Sudan''s ''Saleema'' campaign. Anthropologist Lisen Dellenborg discusses the ethical, emotional, and methodological challenges that ethnographers and healthcare providers face when engaging with human vulnerability and observing traditional ceremonies in Casamance, Senegal.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sara Johnsdotter", "R. Elise B. Johansen", "Ellen Gruenbaum", "Lisen Dellenborg", "Fran Hosken", "Nahid Toubia", "Janice Boddy"], "organizations": ["Malm\u00f6 University", "Centre for Sexology and Sexuality Studies", "Nordic Network for Research on FGC (FOKO)", "World Health Organization", "UNICEF", "UNFPA"], "themes": ["Female Genital Cutting (FGC/FGM)", "Cultural Relativism and Ethnocentrism", "Global North and Global South Dynamics", "Human Rights vs. Harm Reduction", "Ethnographic Methodology and Ethics", "Diaspora and Nordic Health Policy", "Genital Cosmetic Surgery Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('250b13c156997229930946e973c829e86d22cc59510fe67245b674e942c299b9', 'Johnsdotter FGC Notions Sweden FinJEthMigr 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/250b13c156997229930946e973c829e86d22cc59510fe67245b674e942c299b9.pdf', 'other', 'ingested', '{"date": "2008", "description": "This academic article examines the 2006\u20132007 Swedish legal proceedings against Ali Elmi Hayow, a Somali-Swedish man convicted and imprisoned for allegedly subjecting his daughter, Muna, to female genital cutting (FGC) in Somalia. Author Sara Johnsdotter argues that Elmi was denied a fair trial and convicted without sufficient corroborating evidence, violating the legal principle of *in dubio pro reo*. The prosecution relied primarily on contradictory testimonies from his teenage daughter, whose initial claims falsely implicated other family members before being retracted.\n\nJohnsdotter contends that the court''s verdict was heavily influenced by ethnocentric assumptions about family organization, radical feminist frameworks that portray African men as the primary perpetrators of FGC, and intense political pressure to secure a conviction under Sweden''s 1982 anti-FGM legislation. The article emphasizes that culturally grounded knowledge\u2014specifically concerning the traditional absence of Somali fathers from circumcision procedures and the practices of child circulation\u2014was neglected by Swedish judicial authorities in favor of persistent cultural stereotypes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sara Johnsdotter", "Ali Elmi Hayow", "Safiya", "Muna", "Meriam", "Fran Hosken"], "organizations": ["District Court of G\u00f6teborg", "Swedish Court of Appeal", "Swedish Supreme Court", "Social Insurance Office", "Swedish Embassy in Addis Ababa", "Malm\u00f6 University"], "themes": ["Female Genital Cutting (FGC/FGM)", "Criminal Justice and Due Process", "Somali Culture and Family Structure", "Ethnocentrism in Legal Systems", "Feminist Legal Theory and Stereotyping"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3d6fcdb33de6141faf0b3db5ae5222ea4605881b2b8fca1fead52db504a121e1', 'Johnsdotter Genitals_and_ethnicity ReproHlthMatt 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3d6fcdb33de6141faf0b3db5ae5222ea4605881b2b8fca1fead52db504a121e1.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This academic article analyzes the ethical, legal, and cultural discrepancies in Western attitudes toward female genital cosmetic surgery (FGCS) among European women compared to traditional female genital cutting (FGC) among African women and girls. The authors argue that while both practices involve anatomical modifications\u2014often with comparable surgical tissue removal\u2014Western societies and international bodies like the World Health Organization strictly criminalize FGC as harmful and patriarchal, yet frame FGCS as an exercise of female autonomy and aesthetic choice.\n\nThe authors highlight how cultural claims-making shapes medical norms and legal prohibitions, resulting in discriminatory double standards based on ethnicity and race. They call for consistent, non-discriminatory legal and policy frameworks that clearly reconcile the principles of child protection, bodily integrity, and adult bodily autonomy without relying on culturally biased distinctions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sara Johnsdotter", "Birgitta Ess\u00e9n", "Fran P. Hosken", "Judith Butler", "Anne Fausto-Sterling", "Caster Semenya", "Carla Makhlouf Obermeyer"], "organizations": ["World Health Organization", "Malm\u00f6 University", "Uppsala University", "Swedish Research Council", "Harborview Medical Center", "Inter-African Committee"], "themes": ["Female Genital Cutting (FGC)", "Female Genital Cosmetic Surgery (FGCS)", "Bodily Autonomy and Integrity", "Medical Ethics and Legal Inconsistency", "Gender and Cultural Constructivism", "Child Protection and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1b16efd5ea32a009c78ceb32e9b875c65db656719b7488b70c1655d98d82c7a', 'Johnsdotter Girls & Boys as Victims Intl Seminar FGM 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1b16efd5ea32a009c78ceb32e9b875c65db656719b7488b70c1655d98d82c7a.pdf', 'other', 'ingested', '{"date": "2017-11-24", "description": "This academic paper by medical anthropologist Sara Johnsdotter analyzes the shifting public and legal discourses in Europe surrounding male and female genital modifications in children. It examines how the 1980s feminist and anti-FGM movements established a sharp conceptual asymmetry by defining all non-therapeutic female genital procedures as ''mutilation'' while leaving male circumcision largely unscrutinized, despite traditional cultural contexts often viewing both practices symmetrically.\n\nThe paper traces how this conceptual divide is increasingly challenged by the contemporary ''intactivist'' movement and European legal and medical authorities who frame both practices under a unified children''s rights and bodily integrity perspective. Analyzing significant legal milestones\u2014such as the 2012 Cologne court ruling, the 2015 British Family Court judgment, and Council of Europe resolutions\u2014Johnsdotter highlights an ongoing societal deadlock that pits universal children''s bodily autonomy against religious freedom, cultural pluralism, and political feasibility.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sara Johnsdotter", "Fran P. Hosken", "Nahid Toubia", "Sir James Munby", "Angela Merkel", "Brian D. Earp", "Morten Frisch"], "organizations": ["Malm\u00f6 University", "World Health Organization", "UNICEF", "American Academy of Pediatrics", "Council of Europe", "Nordic Ombudsmen for Children", "Royal Dutch Medical Association", "Milah UK", "NOCIRC"], "themes": ["Male Circumcision", "Female Genital Mutilation/Cutting (FGM/C)", "Children''s Rights and Bodily Integrity", "Medical Anthropology and Bioethics", "Religious Freedom versus Child Protection", "Legal and Human Rights Discourse"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('66b9a58df8ed4e868f95380c963e3508d46ef71d9d0d4dfdab63a44ad9132259', 'Johnsdotter Self Circ Somali Sweden SexReprHlth 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/66b9a58df8ed4e868f95380c963e3508d46ef71d9d0d4dfdab63a44ad9132259.pdf', 'medical_journal', 'ingested', '{"date": "2016-09-14", "description": "This qualitative study investigates the phenomenon of ''retrospective self-circumcision''\u2014circumcision self-performed during adolescence\u2014among Somali immigrant men residing in Sweden. Drawing from focus groups and interviews with 43 Somali-Swedish fathers, the researchers found that eight participants had circumcised themselves while living in rural Somalia. These actions were primarily motivated by a strong desire to fulfill Islamic religious obligations in settings where access to traditional or professional circumcisers was unavailable.\n\nWhile participants reported that their genital anatomy remained functional for reproduction, many acknowledged implicit issues such as scarring, reduced sensation, and past trauma from bleeding or infection. Despite these complications, cultural reticence and taboos regarding sexual pleasure have historically prevented them from discussing sexual and urological health concerns or seeking penile reconstruction. The authors conclude that healthcare providers, particularly urologists and reproductive health professionals, must establish culturally sensitive clinical pathways framed within an Islamic context to identify and support men with complications arising from self-circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Pauline Binder-Finnema", "Asha Omar Mahmud", "Sara Johnsdotter", "Birgitta Ess\u00e9n"], "organizations": ["Uppsala University", "Malm\u00f6 University", "Swedish Council for Working Life and Social Research", "Elsevier"], "themes": ["Male Circumcision", "Retrospective Self-Circumcision", "Migrant Healthcare", "Sexual and Reproductive Health", "Urological Health", "Islamic Culture and Tradition"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8cc521aa936116b76e1374209ae19c5030a0ce323f58ada6a9e89c42383b86f7', 'Johnsdotter Svoboda Sexual Pleasure GlobDisc 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8cc521aa936116b76e1374209ae19c5030a0ce323f58ada6a9e89c42383b86f7.pdf', 'medical_journal', 'ingested', '{"date": "2013-07-12", "description": "In this response to J. Steven Svoboda, medical anthropologist Sara Johnsdotter examines discourses surrounding sexual pleasure following male, female, intersex, and cosmetic genital modifications. She contends that current debates suffer from ''genital determinism''\u2014the flawed, reductionist assumption that the anatomical status of genitalia solely dictates sexual satisfaction and function. Johnsdotter argues that biomedical claims regarding sexual pleasure are largely cultural constructions influenced by politics and double standards, pointing out that empirical studies showing widespread sexual dysfunction following female circumcision are frequently methodologically weak, while western cosmetic and intersex surgeries are framed differently despite similar physical alterations. Drawing on sexual scripting theory and the anthropology of sensations, the author concludes that sexual pleasure is fundamentally shaped by social, cultural, and subjective factors rather than genital anatomy alone.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sara Johnsdotter", "J. Steven Svoboda", "Richard A. Shweder", "Virginia Braun", "Carla Makhlouf Obermeyer", "Nawal Nour", "Morten Frisch", "John H. Gagnon", "William Simon", "Juliet Richters"], "organizations": ["Malm\u00f6 University", "Routledge", "Taylor & Francis", "World Health Organization", "UNAIDS", "JHPIEGO", "The Public Policy Advisory Network on Female Genital Surgeries in Africa", "American Academy of Pediatrics"], "themes": ["Genital Modifications", "Genital Determinism", "Sexual Pleasure and Function", "Cultural Constructions of Sexuality", "Circumcision Debates", "Bioethics and Bodily Autonomy", "Sexual Scripting Theory"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('86ee253667a18e02f91dbe9612ae35f02c2b1603733cb417af7a5028f0328584', 'Johnson Impact_neonatal_circ Regressive Springer 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/86ee253667a18e02f91dbe9612ae35f02c2b1603733cb417af7a5028f0328584.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This academic book chapter by Robert Clover Johnson examines the lasting psychological, emotional, and physical ramifications of neonatal circumcision, drawing on neuroscience, regressive psychotherapy, and personal narrative. Johnson argues that despite long-standing medical assumptions that infants do not register or retain trauma, deep-brain structures like the amygdala store the intense pain and terror of circumcision, frequently resulting in adult relational anxieties, intimacy fears, and emotional dissociation. Through modalities such as Primal Therapy and Bioenergetic Analysis, adult men can access and cathartically release these repressed infant traumas.\n\nThe author critiques common medical and historical justifications for neonatal circumcision, such as disease prevention and moral restraint, arguing they lack sound modern empirical backing. Johnson advocates for a combined approach of regressive psychological healing and non-surgical foreskin restoration to regain lost agency and function, while urging medical professionals to reconsider routine infant circumcision under the ethical imperative of the Hippocratic Oath.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Clover Johnson", "George C. Denniston", "Frederick M. Hodges", "Marilyn Fayre Milos", "Arthur Janov", "Alexander Lowen", "Paul Vereshack", "Tom Golden", "John Rhinehart", "John Harvey Kellogg", "Sigmund Freud", "Gabriela Monasterio"], "organizations": ["Springer Science and Business Media", "National Organization of Restoring Men (NORM)"], "themes": ["Neonatal Circumcision", "Infant Trauma and Memory", "Regressive Psychotherapy", "Primal Therapy", "Medical Ethics", "Foreskin Restoration", "Sexual and Psychological Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('24cefcf05f83e777ce4ea49a2a2ed8eaf82ef91a1b7edd8e6f4d5bb6eff37f01', 'Johnson MGM Beyond Tolerable Ethnicities 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/24cefcf05f83e777ce4ea49a2a2ed8eaf82ef91a1b7edd8e6f4d5bb6eff37f01.pdf', 'other', 'ingested', '{"date": "2010", "description": "This academic paper critically evaluates the liberal stance on genital alteration practices, focusing on the philosophical arguments of Martha Nussbaum. The author argues that while Western liberals condemn Female Genital Mutilation (FGM) as an intolerable violation of autonomy, bodily integrity, and physical well-being under the harm principle, they inconsistently accept routine male circumcision\u2014termed Male Genital Mutilation (MGM)\u2014as benign, hygienic, or medically justified. By examining historical origins, surgical risks, pain, psychological trauma, and evidence of diminished sexual sensitivity, the paper demonstrates significant qualitative parallels between FGM and MGM.\n\nThe author identifies key ideological obstacles preventing liberals from acknowledging MGM''s harms, including ethnocentric conditioning, questionable medicalization, a simplistic ''oppressor/oppressed'' gender framework that overlooks male vulnerability, and inconsistent appeals to religious toleration. The paper concludes that to maintain critical consistency and overcome justifiable accusations of cultural hypocrisy, liberals must apply their principles of physiological autonomy and bodily integrity universally, challenging non-consensual male circumcision just as they do female genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Matthew Johnson", "Martha Nussbaum", "Yael Tamir", "Haseena Lockhat"], "organizations": ["Newcastle University", "American Academy of Paediatrics", "SAGE Publications"], "themes": ["Male Circumcision and MGM", "Female Genital Mutilation (FGM)", "Liberalism and Toleration", "Bodily Integrity and Autonomy", "Ethnocentricity", "Gender Oppression", "Multiculturalism and Religious Obligation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3340561c0b012076941e563b911c720c91c41a6e978f953b72d2e84e856dc2b9', 'Johnson Religious Circ JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3340561c0b012076941e563b911c720c91c41a6e978f953b72d2e84e856dc2b9.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-22", "description": "This paper examines the political, philosophical, and ethical challenges surrounding non-therapeutic circumcision and other invasive cultural rites inflicted on minors, framed by the 2012 Cologne regional court decision that ruled non-medical infant circumcision constitutes bodily harm. The author argues that non-therapeutic male circumcision shares qualitative similarities with prohibited practices like female genital cutting, as both infringe upon a minor''s bodily integrity and are often irreversible, involuntary, and coercive. \n\nRather than endorsing outright legal prohibition\u2014which risks pushing practices underground and causing greater physical harm to children\u2014or endorsing state-funded provision through public bodies like the NHS, the author proposes a regulated medicalization framework. Drawing on the political liberalism of Chandran Kukathas and Peter Jones''s arguments on the burdens of belief, the author advocates that the communities and religious groups requiring or encouraging these practices should bear the financial costs, ensure medical oversight, and be held accountable to criticism and legal recourse by individuals who feel harmed by these childhood procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Matthew Thomas Johnson", "Aziz Sheikh", "Peter Jones", "Chandran Kukathas", "John Rawls", "Martha Nussbaum"], "organizations": ["BMJ", "University of York", "National Health Service", "Royal Dutch Medical Association", "German Regional Court in Cologne"], "themes": ["Religious Circumcision", "Bodily Integrity and Consent", "Political Liberalism and State Neutrality", "Harm Minimization vs. Criminalization", "Burdens and Consequences of Belief", "Comparative Analysis of Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e754be12f4e7c64e12ec3c6bbd6a425472ec609afa97f8a177c88bd0d9ad8098', 'Jones Of Rights and Men JHumRts 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e754be12f4e7c64e12ec3c6bbd6a425472ec609afa97f8a177c88bd0d9ad8098.pdf', 'other', 'ingested', '{"date": "2002", "description": "This academic article argues that mainstream human rights discourse often limits gender analysis to the experiences of women and girls, while overlooking systemic abuses targeting men. Author Adam Jones contends that severe, institutionalized human rights abuses in the United States overwhelmingly impact men\u2014especially young, poor, and minority males. To illustrate this, the paper examines four key institutions: disproportionate mass incarceration, sex-selective capital punishment, police brutality, and mandatory registration for military conscription.\n\nThe author advocates for adopting a ''men and minorities'' framework rather than the traditional ''women and minorities'' pairing. The article suggests that young men face pervasive structural disadvantages, cultural demonization, and extreme rates of violence and mortal victimization, which warrants treating them analytically as an identifiable minority group deserving of human rights attention and empathy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Adam Jones", "Stephen Donaldson", "Rodney King", "Marc Mauer", "Pierre San\u00e9", "Thurgood Marshall", "Warren Farrell", "Noam Chomsky"], "organizations": ["Amnesty International", "Human Rights Watch", "The Sentencing Project", "Selective Service System", "United States Department of Justice"], "themes": ["Gender Analysis", "Male Victimization", "Mass Incarceration", "Capital Punishment", "Police Brutality", "Military Conscription", "Human Rights Violations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0033024cbeed1acbc5b5b38da1711db674a01f36bbcd42abbf520e1fcfae8eba', 'Kalaskar TextbookPlastic&ReconstrSurgery 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0033024cbeed1acbc5b5b38da1711db674a01f36bbcd42abbf520e1fcfae8eba.pdf', 'other', 'ingested', '{"date": "2016", "description": "This text comprises front matter, table of contents, and opening chapters from the open-access ''Textbook of Plastic and Reconstructive Surgery''. It establishes foundational concepts in plastic and reconstructive surgery, covering dermatological anatomy, wound biology across haemostatic, inflammatory, proliferative, and remodelling phases, and systematic wound bed preparation using framework tools like DIME. Additionally, it outlines techniques for minimizing scar visibility and achieving tension-free primary closure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Deepak M. Kalaskar", "Peter E. Butler", "Shadi Ghali", "George Adigbli", "Feras Alshomer", "Jekaterina Maksimcuka", "Ali Alhamdi"], "organizations": ["UCL Press", "University College London", "The British Library", "Royal Free Hospital", "British Association of Plastic Reconstructive and Aesthetic Surgeons"], "themes": ["Plastic and Reconstructive Surgery", "Wound Healing and Tissue Repair", "Skin Grafts and Flap Techniques", "Abdominal Wall Reconstruction", "Surgical Closure and Scar Revision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('990a18a0b1231401a9fbe77bbf9e0a796da0fbe0bb55d4854350c76c61e5e646', 'Kayaba Retractiability Prepuce JUrol1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/990a18a0b1231401a9fbe77bbf9e0a796da0fbe0bb55d4854350c76c61e5e646.pdf', 'medical_journal', 'ingested', '{"date": "1996", "description": "This clinical study evaluated preputial development, retractability, and tight ring formation in 603 Japanese boys aged 0 to 15 years to understand the natural history of the prepuce. The researchers observed that complete preputial retractability increased steadily from 0% at age 6 months to 62.9% between ages 11 and 15, while the presence of a tight ring declined dramatically from 84.3% in infants to 8.6% in older boys.\n\nThe authors conclude that incomplete preputial separation is a normal, physiological condition in infants and young children that resolves spontaneously as boys mature toward adolescence. Consequently, awareness of natural preputial development and proper genital hygiene can prevent unnecessary infant circumcisions and medical interventions, reserving surgery only for specific pathological conditions such as paraphimosis or severe dysuria.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hiroyuki Kayaba", "Hiromi Tamura", "Seiichi Kitajima", "Yoshiyuki Fujiwara", "Tetsuo Kato", "Tetsuro Kato", "Douglas Gairdner"], "organizations": ["American Urological Association", "Fujiwara Memorial Hospital", "Akita University School of Medicine", "American Academy of Pediatrics"], "themes": ["Pediatric Urology", "Preputial Development", "Phimosis", "Neonatal Circumcision", "Genital Hygiene"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d71016f2af9d4737cb09f4c4420fd144576f4fc091343c948719f839fc4ede82', 'Kehrer Cuts into Children''s Future PHRG 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d71016f2af9d4737cb09f4c4420fd144576f4fc091343c948719f839fc4ede82.pdf', 'other', 'ingested', '{"date": "2019", "description": "This article presents a comparative legal and human rights analysis of non-therapeutic, irreversible genital alteration practices performed on non-consenting children, specifically examining female genital modification (FGM), male circumcision, and intersex genital surgeries. The author investigates why legal systems enforce stark double standards\u2014strictly banning FGM while broadly permitting male circumcision as a parental religious prerogative and intersex surgeries as conventional medical interventions\u2014despite all three lacking immediate therapeutic necessity and permanently removing healthy, sensitive tissue.\n\nEvaluating these practices through the frameworks of surrogate parental decision-making, the best interest standard, the harm principle, and the right to bodily integrity, the article demonstrates that definitions of ''harm'' and ''best interest'' remain overly subjective and culturally relative. Kehrer argues that bodily integrity and the child''s right to an ''open future'' require postponing all medically unnecessary, non-urgent genital modifications until the individual is mature enough to make an autonomous, informed choice, advocating for a consistent, gender-neutral child rights approach.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Ino Kehrer", "Els Leye", "John Money", "Joel Feinberg"], "organizations": ["University of Padova", "World Health Organization", "UNICEF", "United Nations Population Fund", "Office of the High Commissioner for Human Rights", "European Parliament", "Parliamentary Assembly of the Council of Europe", "American Academy of Pediatrics"], "themes": ["Children''s Rights", "Bodily Integrity", "Female Genital Modification", "Male Circumcision", "Intersex Genital Surgery", "Best Interest Standard", "Harm Principle", "Surrogate Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9ac1263a5a2fb960ab563c96b0b0f6098931255a22f0af1c19946b3d3029dac2', 'Kelly Women_Object_to_Male_Circ 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9ac1263a5a2fb960ab563c96b0b0f6098931255a22f0af1c19946b3d3029dac2.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This qualitative study investigates the acceptability of adult male circumcision as a biomedical strategy for HIV prevention among women across four distinct regions of Papua New Guinea. Drawing on 21 focus group discussions and 18 in-depth interviews with 210 women, the findings show that the majority of participants objected to government-led scale-up of male circumcision. The main objections centered on three factors: fears of sexual risk compensation resulting in reduced condom usage, promiscuity, and potential gender-based sexual violence; perceived incompatibility with Christian beliefs regarding bodily integrity; and concerns that circumcision would disrupt customary practices or introduce culturally inappropriate interventions.\n\nA minority of women\u2014largely educated or urban participants\u2014supported male circumcision primarily due to beliefs in its ability to prevent HIV/STIs and improve penile hygiene. The authors conclude that biomedical interventions must be integrated into local sociocultural and gender frameworks, warning that scaling up male circumcision without addressing gender disparities and local concerns could increase women''s vulnerability and undermine prevention efforts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Angela Kelly", "Martha Kupul", "Herick Aeno", "Patti Shih", "Richard Naketrumb", "James Neo", "Lisa Fitzgerald", "John M. Kaldor", "Peter M. Siba", "Andrew Vallely"], "organizations": ["Papua New Guinea Institute of Medical Research", "University of New South Wales", "University of Queensland", "World Health Organization", "UNAIDS", "Papua New Guinea National AIDS Council Secretariat"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Sexual Risk Compensation", "Gender Relations and Disparities", "Sociocultural and Religious Beliefs", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9ac1a46acb97ccd6c88599e7e12e7a3acf8bbb0d6adada4225ea55bfb71fb693', 'Kennedy Embodiment and Restoration IJMH 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9ac1a46acb97ccd6c88599e7e12e7a3acf8bbb0d6adada4225ea55bfb71fb693.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This academic article investigates the practice of nonsurgical foreskin restoration among circumcised men in the United States, analyzing the intersection of embodiment, masculinity, and body politics. The author explores how restoring men and intactivist organizations frame restoration as an autonomous reclamation of the body and an effort to reverse the perceived physical, sexual, and psychological harms of infant circumcision.\n\nKennedy contends that while foreskin restoration challenges hegemonic American aesthetics that favor the circumcised penis, it paradoxically reinforces conventional masculine norms. Restorers often conform to a shared, socially constructed aesthetic centered on penile length and skin overhang, treating the restoration process as a physical remedy for complex emotional grievances. Ultimately, the practice demonstrates how alternative bodily projects remain constrained by cultural ideals that place the phallus at the center of masculine identity and self-worth.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Amanda Kennedy", "Tim Hammond", "R. Wayne Griffiths", "Jim Bigelow", "Marilyn Milos", "Edward Wallerstein"], "organizations": ["Stony Brook University", "Men''s Studies Press", "National Organization of Restoring Men (NORM)", "Brothers United for Future Foreskins (BUFF)", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)", "Doctors Opposing Circumcision"], "themes": ["Foreskin restoration", "Masculinity and embodiment", "Male circumcision", "Intactivism", "Body modification and aesthetics", "Phallocentrism and sexual health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('aae5755d20253c1387d706e2227844f3b8a364433da00da206987b1e9703ffc0', 'Kennedy Sardi Male Anti-Circ Movement Case Western Law 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/aae5755d20253c1387d706e2227844f3b8a364433da00da206987b1e9703ffc0.pdf', 'other', 'ingested', '{"date": "2016", "description": "This academic article examines the contemporary male anti-circumcision (''intactivist'') movement and its online advocacy across social media platforms. The authors analyze how the movement frames neonatal male circumcision as a violation of bodily integrity, informed consent, and human rights, while tracing the historical transition of the practice in the United States from religious ritual to medicalized social control rooted in 19th-century class, racial, and anti-masturbation anxieties.\n\nApplying Michael Messner''s sociological model of men''s movements, Kennedy and Sardi argue that the intactivist movement has severely hindered its own progress and alienated potential allies, particularly feminists and broader human rights organizations. By excessively focusing on the costs of masculinity, adopting rhetoric associated with the anti-feminist Men''s Rights Movement, and ignoring issues of racial, masculine, and heterosexual privilege\u2014exemplified by controversies surrounding the comic series ''Foreskin Man''\u2014the movement frequently falls into anti-feminist backlash. The authors conclude that to build effective progressive coalitions and achieve true equity, the movement must critically confront structural privilege and disentangle itself from sexist, racist, and anti-Semitic tropes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Amanda Kennedy", "Lauren M. Sardi", "Michael A. Messner", "Matthew Hess", "J. Steven Svoboda", "Gary Costanza", "Hammad Malik"], "organizations": ["Curry College", "Quinnipiac University", "Case Western Reserve University School of Law", "Intact America", "Doctors Opposing Circumcision", "National Organization to Halt the Abuse and Routine Mutilation of Males", "National Coalition for Men", "Attorneys for the Rights of the Child", "American Civil Liberties Union"], "themes": ["Male Circumcision", "Intactivism", "Social Media Activism", "Men''s Rights Movement", "Feminism and Gender Equality", "Bodily Integrity and Consent", "Privilege and Intersectionality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7cfdf3a968df34e607e3d97e563bef82b4b35753cda677c550afa1cb1f4dd301', 'Kennedy Understanding Intactivism (dissertn) 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7cfdf3a968df34e607e3d97e563bef82b4b35753cda677c550afa1cb1f4dd301.pdf', 'other', 'ingested', '{"date": "2016-05", "description": "This doctoral dissertation examines the ''Intactivist'' movement in the United States, an anti-male circumcision social movement largely composed of men that emerged around 1980. Drawing on qualitative content analysis of organizational websites, participant observation at protests and symposia, and in-depth interviews, the author analyzes the movement through the lens of gender, embodiment, and social movement framing, demonstrating how the movement repurposes feminist rhetoric and aligns with Men''s Rights activism.\n\nWhile the movement has largely failed to achieve widespread legal bans on routine infant circumcision, it has achieved an ''embodied success'' by politicizing the foreskin and allowing circumcised men to reconstruct their identities from ''mutilated victims'' into heroic defenders of bodily integrity. The dissertation also contextualizes this activism within the medical history of circumcision in the United States, tracking its late-19th-century rise as a cure-all and moral prophylactic under figures like Dr. Lewis Sayre, to its contemporary debates concerning medical ethics, bodily autonomy, and declining hospital circumcision rates.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Amanda Kennedy", "Michael Kimmel", "Catherine Marrone", "Melissa Forbis", "Wairimu Njambi", "Charles Taber", "Marilyn Milos", "Matthew Hess", "Lewis A. Sayre", "Peter Charles Remondino"], "organizations": ["Stony Brook University", "National Organization of Circumcision Information Resource Centers", "National Organization of Restoring Men", "American Academy of Pediatrics", "Stop Infant Circumcision Society", "End Routine Infant Circumcision", "Doctors Opposing Circumcision", "Bay Area Intactivists", "Nurses for the Rights of the Child", "World Health Organization"], "themes": ["Intactivism and Anti-Circumcision Organizing", "Masculinity and Gender Politics", "Medicalization and Bodily Autonomy", "Social Movement Framing and Identity", "Foreskin Restoration", "Medical Ethics and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a8cd34dd0262c3867c2ccd20993b9a71ad5f8652f0bd76b32d32740e428fda0f', 'Khan Ruling of Circumcision 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a8cd34dd0262c3867c2ccd20993b9a71ad5f8652f0bd76b32d32740e428fda0f.pdf', 'other', 'ingested', '{"date": "2014-03-21", "description": "This document is an Islamic legal ruling (fatwa) answering inquiries from an adult convert to Islam regarding male circumcision (khitan). The inquirer expresses fear, financial obstacles, and emotional distress over social pressure, stigmas, and concerns regarding religious validity, leading prayers, and marriage eligibility while uncircumcised.\n\nMufti Waseem Khan clarifies the differing scholarly viewpoints among Islamic jurists, noting that while scholars like Imams Shafi and Malik regard circumcision as obligatory (wajib), Imam Abu Hanifah and Hassan Basri deem it an emphasized Sunnah. Consequently, remaining uncircumcised does not invalidate one''s faith or make one a disbeliever. If thorough ritual purity (taharah) and hygiene are maintained, an uncircumcised man may lead prayer, stand in the front prayer row according to the Hanafi school, and legally marry a Muslim woman, with disclosure recommended to ensure marital harmony.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Mufti Waseem Khan", "Imam Abu Hanifah", "Imam Malik", "Imam Shafi", "Allama Khatabi"], "organizations": ["Darul Uloom Trinidad and Tobago"], "themes": ["Islamic Jurisprudence (Fiqh)", "Male Circumcision (Khitan)", "Converts to Islam", "Ritual Purity (Taharah)", "Validity of Prayer (Salah)", "Islamic Marriage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ce704eec5a07e56ec93acdaaae13bbefe3fad66c121440fb887f2250f79e09b5', 'Kibira Risky_sex behaviors Circ ReproHealth 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ce704eec5a07e56ec93acdaaae13bbefe3fad66c121440fb887f2250f79e09b5.pdf', 'medical_journal', 'ingested', '{"date": "2014-03-24", "description": "This study analyzes data from the 2011 Uganda AIDS Indicator Survey, evaluating 7,969 sexually active men aged 15\u201359 to determine the relationship between safe male circumcision (SMC), risky sexual behaviors, and HIV prevalence. The findings reveal that circumcised men had higher odds of engaging in risky sexual behaviors, such as having multiple lifetime partners and non-marital sex, potentially indicating behavioral risk compensation. \n\nDespite the elevated prevalence of risky sexual behaviors among circumcised men, their overall HIV prevalence was significantly lower (4.8%) compared to uncircumcised men (7.8%). The authors conclude that while circumcision provides substantial protective benefits against heterosexual HIV acquisition, safe male circumcision programs must continue promoting established prevention methods and counseling to mitigate behavioral disinhibition.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Simon PS Kibira", "Elizabeth Nansubuga", "Nazarius M Tumwesigye", "Lynn M Atuyambe", "Fredrick Makumbi", "Wenjuan Wang", "Sarah Staveteig", "Helen Nviiri", "Joy Fishel"], "organizations": ["Makerere University", "Ministry of Health", "ICF International", "Uganda Bureau of Statistics", "Uganda Virus Research Institute", "Centers for Disease Control and Prevention", "Uganda National Council of Science and Technology", "United States Agency for International Development", "World Health Organization", "UNAIDS", "BioMed Central Ltd."], "themes": ["Safe Male Circumcision", "HIV/AIDS Prevention", "Risky Sexual Behaviors", "Risk Compensation Theory", "Epidemiology and Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('25cea0b399522109ad0439ccf6199b8fd791404e8cb9300dc63f46a933cff6b8', 'Kielholz Clit Penile Histology JSSM 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/25cea0b399522109ad0439ccf6199b8fd791404e8cb9300dc63f46a933cff6b8.pdf', 'medical_journal', 'ingested', '{"date": "2026", "description": "This study evaluated the implementation of an updated undergraduate medical curriculum at the University of Geneva designed to address the persistent disparity between clitoral and penile histology education. Prior to a hands-on practical session using stained tissue sections, only 34% of medical students reported being able to identify major clitoral structures, compared to 84% for penile anatomy. Following the practical training, recognition of clitoral histology rose significantly to 93%, demonstrating that focused educational interventions can effectively bridge substantial structural knowledge gaps. The authors argue that equitable teaching of genital histology is essential for clinical competence in sexual medicine and represents an important step toward gender equity and pedagogical justice in medical training.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["M. Kielholz", "P. Souli\u00e9", "B. Celine", "M. Badr\u00e9", "J. Abdulcadir"], "organizations": ["Geneva University", "Geneva University Hospitals", "International Society for Sexual Medicine", "European Society for Sexual Medicine"], "themes": ["Medical Education", "Histology", "Sexual Medicine", "Gender Equity in Medicine", "Curriculum Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f8796327c40662007c49ceb7416eb2d2da178e61f5a8c3d1580d46ef2364dd21', 'Kigozi Foreskin Surface Area AIDS 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f8796327c40662007c49ceb7416eb2d2da178e61f5a8c3d1580d46ef2364dd21.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This concise communication examines whether the surface area of the foreskin correlates with the risk of HIV acquisition among uncircumcised men prior to undergoing male circumcision in Rakai, Uganda. Utilizing data from 965 initially HIV-negative men participating in the Rakai Community Cohort Study and subsequent randomized circumcision trials, the researchers measured surgically removed foreskin surface area and evaluated HIV incidence over 3,920.8 person-years of pre-circumcision observation.\n\nThe findings revealed that men who acquired HIV had a significantly larger mean foreskin surface area (43.3 cm\u00b2) compared to those who remained uninfected (36.8 cm\u00b2). Men in the highest quartile of foreskin surface area (>45.6 cm\u00b2) had an adjusted incidence rate ratio of 2.37 for HIV acquisition compared to men in the lowest quartile. The authors conclude that larger foreskin surface area increases male HIV acquisition risk\u2014likely due to a greater quantity of mucosal target cells and heightened exposure during intercourse\u2014and emphasize the clinical importance of minimizing residual foreskin tissue during circumcision procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Godfrey Kigozi", "Maria Wawer", "Absalom Ssettuba", "Joseph Kagaayi", "Fred Nalugoda", "Stephen Watya", "Fred Wabwire Mangen", "Noah Kiwanuka", "Melanie C. Bacon", "Tom Lutalo", "David Serwadda", "Ronald H. Gray"], "organizations": ["Rakai Health Sciences Program", "Johns Hopkins University Bloomberg School of Public Health", "Makerere University School of Public Health", "Mulago Hospital", "National Institute of Allergy and Infectious Diseases", "National Institutes of Health", "Uganda Virus Research Institute", "World Health Organization", "UNAIDS", "Bill and Melinda Gates Foundation"], "themes": ["Male Circumcision", "HIV Acquisition", "Foreskin Surface Area", "HIV Prevention", "Epidemiology", "Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('152c5d79bb8dcaf805f5a67a71f67c2de800b2dbc6f6e63b08057c41a2358cd1', 'Kilic Comparative Two Methods BMC Urology 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/152c5d79bb8dcaf805f5a67a71f67c2de800b2dbc6f6e63b08057c41a2358cd1.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This retrospective study compares the clinical outcomes, operative durations, complications, and costs between two circumcision methods\u2014the disposable NeoAlis clamp and the traditional sleeve technique\u2014across a cohort of 2,626 pediatric patients treated between 2017 and 2023. The NeoAlis clamp procedure was performed under local anesthesia primarily on infants under one year of age, while the classic sleeve technique was conducted under general anesthesia in older children.\n\nThe findings indicate that the NeoAlis clamp method significantly reduced surgical operation time and lowered rates of early post-procedure bleeding and surgical revisions compared to the traditional sleeve technique, with comparable overall costs. The author concludes that disposable ring devices like the NeoAlis clamp offer a safe, fast, and sutureless alternative for infant circumcision that minimizes complications associated with general anesthesia.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sinan K\u0131l\u0131\u00e7"], "organizations": ["Private Gebze Yuzyil Hospital", "Istanbul Medipol University", "Aba Group Healthcare Company", "World Health Organization", "UNAIDS", "Springer Nature"], "themes": ["Pediatric Urology", "Male Circumcision", "Surgical Techniques", "Postoperative Complications", "Comparative Clinical Study"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8e8b7d1707466f1ae52b7420d9be425dac094b264b997eee88db6b74b6745b2c', 'Kilmarx Clark US Insurance Coverage HlthAffairs 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8e8b7d1707466f1ae52b7420d9be425dac094b264b997eee88db6b74b6745b2c.pdf', 'medical_journal', 'ingested', '{"date": "2011-12", "description": "This study examines public and private health insurance coverage and reimbursement for routine newborn and adult male circumcision in the United States, evaluating data collected from large private insurers and state Medicaid programs in 2009. Despite clinical evidence demonstrating that male circumcision reduces the transmission of HIV, other sexually transmitted infections, urinary tract infections, and penile cancer, the authors found significant disparities in coverage. While private insurers broadly cover routine newborn circumcision, state Medicaid programs exhibit substantial gaps, with seventeen states providing no coverage despite low-income populations facing higher risks for HIV and STIs.\n\nCoverage for adult male circumcision remains sparse and highly restricted across both public and private health plans, predominantly limited to specific, documented medical indications rather than preventive measures. The authors conclude that without explicit evidence-based guidance and cost-effectiveness data\u2014such as forthcoming recommendations from the Centers for Disease Control and Prevention and the American Academy of Pediatrics\u2014public and private payers are unlikely to expand coverage, perpetuating inequitable access to the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sarah J. Clark", "Peter H. Kilmarx", "Katrina Kretsinger"], "organizations": ["Centers for Disease Control and Prevention", "University of Michigan", "American Academy of Pediatrics", "Project HOPE", "National Association of Insurance Commissioners"], "themes": ["Male Circumcision", "Health Insurance Coverage", "Medicaid Policy", "HIV and STI Prevention", "Health Disparities", "Preventive Healthcare Reimbursement"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ee43cfe8a0a45981ebfa6a30681e8e726f776739f76bfca5edc226cd63452f07', 'Kim Effects of MGM on Sexuality BJU International 12-06.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ee43cfe8a0a45981ebfa6a30681e8e726f776739f76bfca5edc226cd63452f07.pdf', 'medical_journal', 'ingested', '{"date": "2006-09-18", "description": "This prospective study investigates the effects of adult male circumcision on sexual function and satisfaction among 373 sexually active men in South Korea, comparing circumcised and uncircumcised cohorts as well as pre- and post-circumcision experiences. While no significant differences were observed regarding sexual drive, erection quality, or ejaculatory latency time, circumcision was found to have notable negative impacts on sexual and masturbatory pleasure. Specifically, 48% of respondents reported reduced masturbatory pleasure, 63% experienced increased masturbatory difficulty, and 20% reported an overall worse sex life post-procedure compared to only 6% reporting improvement.\n\nThe authors conclude that adult male circumcision can adversely affect sexual function and enjoyment for a significant proportion of men. These negative outcomes are primarily attributed to the loss of fine-touch nerve endings in the foreskin and physical surgical complications, including reduced penile skin, painful erections, and prominent scarring.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["DaiSik Kim", "Myung-Geol Pang"], "organizations": ["Seoul National University", "Chung-Ang University", "BJU International"], "themes": ["Male Circumcision", "Male Sexuality", "Sexual Function and Satisfaction", "Masturbation", "Surgical Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d666495454b46e720ab9ff60361992e8c15ed42493fdf0a4653f7666586566cc', 'Ko Age-specific Prevalence Phimosis JFormosMenAssn 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d666495454b46e720ab9ff60361992e8c15ed42493fdf0a4653f7666586566cc.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This study investigates the age-specific prevalence rates of phimosis and circumcision among Taiwanese boys, analyzing cross-sectional data from 1,145 schoolboys aged 7 to 13 years and 59 newborn male infants. The findings indicate that while nonretractable prepuce is ubiquitous in newborns, natural preputial separation progresses steadily with age, accelerating during adolescence, such that complete preputial retractability reaches 84.1% by age 13. Concurrently, circumcision rates remain relatively low and stable, suggesting that unretractable prepuce in early childhood usually resolves naturally without requiring surgical intervention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ming-Chung Ko", "Chih-Kuang Liu", "Wen-Kai Lee", "Huey-Sheng Jeng", "Han-Sun Chiang", "Chung-Yi Li"], "organizations": ["Taipei City Hospital", "Fu-Jen Catholic University", "Formosan Medical Association", "Elsevier", "American Academy of Pediatrics"], "themes": ["Phimosis Prevalence", "Male Circumcision", "Pediatric Urology", "Preputial Development", "Childhood and Adolescent Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f75c4f39fb50d1ca53fef5d842452c077c731402ff427c6f0c286b812ada1c94', 'Kokorowski Circ Revision ClinPed 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f75c4f39fb50d1ca53fef5d842452c077c731402ff427c6f0c286b812ada1c94.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This study analyzes trends in revision circumcision (RC) rates at freestanding children''s hospitals in the United States using data from the Pediatric Health Information Systems (PHIS) database between 2004 and 2009. The researchers identified 34,568 patients undergoing penile procedures, including 5,632 revision circumcisions, and found that the rate of revision circumcision relative to total male ambulatory surgical volume increased by 119% over the study period. This increase significantly outpaced changes in primary circumcision (19%) and lysis of penile adhesions (37%).\n\nThe findings demonstrated that the rising trend was widespread across all geographic regions and mostly performed as stand-alone procedures by pediatric urologists, primarily involving young, publicly insured boys. While the precise drivers of this increase remain uncertain, potential contributing factors include variability or decline in the quality and training of newborn circumcision, growing total circumcisions, and evolving parental or provider expectations regarding post-circumcision cosmetic appearance.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul J. Kokorowski", "Jonathan C. Routh", "Katherine Hubert", "Dionne A. Graham", "Caleb P. Nelson"], "organizations": ["Children\u2019s Hospital Los Angeles", "University of Southern California", "Boston Children\u2019s Hospital", "Harvard Medical School", "Duke University", "Child Health Corporation of America"], "themes": ["Pediatric Urology", "Revision Circumcision", "Surgical Trends", "Healthcare Costs", "Neonatal Circumcision Outcomes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9364a0de15a92b3e2b7024e5e7e5a98898ba3b687ab6fe5c35c01898fcb297d3', 'Kotowski Circumcision&German Multiculti (paper) 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9364a0de15a92b3e2b7024e5e7e5a98898ba3b687ab6fe5c35c01898fcb297d3.pdf', 'other', 'ingested', '{"date": "2013-03-28", "description": "This academic working paper examines the 2012 German circumcision debate (Beschneidungsdebatte), which arose after a Cologne Regional Court ruled that non-medical religious circumcision of young boys constituted criminal bodily harm. Despite considerable public support for the court ruling and widespread political rhetoric claiming multiculturalism had failed, the German parliament (Bundestag) rapidly passed legislation legalizing the practice under specific medical and professional standards.\n\nAnalyzing the controversy through a three-dimensional framework of multiculturalism (policy, discourse, and description), the author argues that the quick legislative response represents an unacknowledged multicultural policy intervention. Rather than reflecting a committed national shift toward multiculturalism, the political class acted out of political expediency and Staatsr\u00e4son\u2014primarily motivated by Germany''s historical responsibility toward the Jewish community and international reputation, even while public discourse expressed intense, assimilationist hostility toward the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jan Michael Kotowski", "Angela Merkel", "Guido Westerwelle", "Dieter Graumann", "Holm Putzke", "Charlotte Knobloch", "Will Kymlicka"], "organizations": ["University of California, Santa Cruz", "Western Political Science Association", "German Bundestag", "Cologne Regional Court (Landgericht K\u00f6ln)", "German Ethics Council (Deutscher Ethikrat)", "Central Council of Jews in Germany", "Central Council of Muslims in Germany", "German Society for Pediatric Surgery (DGKCH)"], "themes": ["Religious Circumcision Controversy", "Multiculturalism and Diversity Policy", "Religious Freedom vs. Child Physical Integrity", "Parental Rights and Secularism", "German National Identity and Staatsr\u00e4son", "Islamophobia and Anti-Semitism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6f2e0e27336ff5a02ddd1a1ee2f0cea653c33113a71e961f5ecc6cb8f90a57ee', 'La Barbera Ban without Prosecution GlobJurist 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6f2e0e27336ff5a02ddd1a1ee2f0cea653c33113a71e961f5ecc6cb8f90a57ee.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic article critically examines anti-female genital mutilation (FGM) legislation in Europe, focusing on comparative case studies of France, the United Kingdom, and Italy. Drawing on intersectionality and Carol Bacchi''s policy representation framework, the author argues that framing ritual genital alterations strictly through the lens of gender-based violence ignores complex structural dynamics involving race, ethnicity, migration status, and neo-colonialism. The paper highlights legal double standards in Western nations, contrasting the strict criminalization of ritual practices with the normalization and medical approval of female cosmetic genitoplasty and infant male circumcision.\n\nThe author demonstrates that current European legal regimes produce ineffective enforcement paradigms, characterized by ''ban without prosecution'' or ''conviction without punishment.'' These measures alienate displaced African communities, push practices underground, and compound vulnerabilities for women of African descent. Analyzing discarded harm-reduction alternatives, such as Dr. Abdulcadir''s proposal for ''circumcision without cutting,'' the article advocates for community-centered, grassroots approaches to cultural change rather than relying on punitive criminal sanctions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Dr. Maria Caterina La Barbera", "Kimberlee Crenshaw", "Dr. Omar Abdulcadir", "Carol Bacchi"], "organizations": ["Nebrija University", "De Gruyter", "World Health Organization", "United Nations", "United Nations Population Fund", "European Parliament", "Council of Europe", "American Academy of Pediatrics", "American Society of Plastic Surgeons"], "themes": ["Female Genital Mutilation (FGM)", "Intersectionality", "Comparative Law", "Gender-Based Violence", "Bodily Integrity and Autonomy", "Cosmetic Genitoplasty", "Neo-Colonialism and Cultural Diversity", "Circumcision Without Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a2ae56ef77d63c0ce1d4fe123cc09ef2e3a6404454b95e9fc75aa6467d34cc08', 'Lagarde Tara Klamp SAMJ 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a2ae56ef77d63c0ce1d4fe123cc09ef2e3a6404454b95e9fc75aa6467d34cc08.pdf', 'medical_journal', 'ingested', '{"date": "2009-03", "description": "This randomized controlled trial evaluated the safety of the Tara KLamp (TK) device compared to the conventional forceps-guided (FG) surgical method for circumcision among young adult men aged 18\u201324 in South Africa. The trial had to be halted prematurely after enrolling only 69 participants due to an unacceptably high incidence of adverse events in the TK group. \n\nParticipants circumcised using the TK device experienced significantly higher rates of adverse events, including intense pain, severe swelling, hematoma, delayed wound healing, infection, and problems with penile appearance compared to those circumcised via the FG method. Additional practitioner training failed to reduce the complication rate, leading the authors to strongly advise against using the Tara KLamp device on young adults.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Emmanuel Lagarde", "Dirk Taljaard", "Adrian Puren", "Bertran Auvert"], "organizations": ["Institut National de la Sant\u00e9 et de la Recherche M\u00e9dicale (INSERM)", "National Institute for Communicable Diseases (NICD)", "Progressus CC", "University of the Witwatersrand", "Agence Nationale de Recherche sur le Sida et les h\u00e9patites (ANRS)"], "themes": ["Male Circumcision", "Tara KLamp Device", "Postoperative Complications", "Randomized Controlled Trial", "HIV Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7eb7ab23b5f5245d72ee95849e34e4391dd4eb8a2019c63e5acb898c1320d63', 'Lander Comparison Ring Block, DPNB JAMA 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7eb7ab23b5f5245d72ee95849e34e4391dd4eb8a2019c63e5acb898c1320d63.pdf', 'medical_journal', 'ingested', '{"date": "1997-12-24", "description": "This randomized controlled trial evaluates the efficacy and safety of three anesthetic techniques\u2014subcutaneous ring block, dorsal penile nerve block (DPNB), and topical eutectic mixture of local anesthetics (EMLA)\u2014compared to an untreated placebo in 52 healthy male newborns undergoing circumcision. Physiological and behavioral indicators, primarily heart rate and crying duration, demonstrated that unanesthetized infants experienced extreme distress and post-surgical complications such as choking and apnea, disproving traditional beliefs that neonates do not feel significant pain or that infiltration is more distressing than the surgery itself.\n\nAmong the treatments, the ring block was found to be the most effective, providing comprehensive pain relief across all stages of the circumcision procedure, including foreskin separation. DPNB and EMLA failed to provide adequate anesthesia during separation and incision, with EMLA being the least effective overall and associated with marginally elevated methemoglobin levels. The study concludes with a strong clinical recommendation that anesthesia should always be administered to newborns undergoing circumcision, with the ring block identified as the preferred method.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Janice Lander", "Barbara Brady-Freyer", "James B. Metcalfe", "Shermin Nazerali", "Sarah Muttit"], "organizations": ["American Medical Association", "University of Alberta", "University of Alberta Hospitals", "Health Canada"], "themes": ["Neonatal Circumcision", "Pediatric Pain Management", "Local Anesthesia", "Randomized Controlled Trials", "Neonatal Physiological Stress"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('39ee03e867df3184bb5ee42c14cacc64c70c58d9aaa9bc285fd38322ae692ac4', 'Lang Circ, Dysfunction, Best Interests 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/39ee03e867df3184bb5ee42c14cacc64c70c58d9aaa9bc285fd38322ae692ac4.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-22", "description": "This document features academic commentary published in the Journal of Medical Ethics addressing the ethical permissibility of infant male circumcision, primarily responding to an article by Joseph Mazor. In the primary commentary, David P. Lang criticizes Mazor''s defense of parental discretion, arguing that Mazor minimizes the severe anatomical and physiological harms of modern circumcision (periah). Lang details the destruction of specialized erogenous nerve tissue, physiological blood supply alterations, risks like meatal stenosis, and long-term sexual dysfunction, contending that non-therapeutic excision of healthy genital tissue violates bodily integrity and reflects an indefensible gender double standard compared to female genital cutting.\n\nA subsequent commentary by David Benatar critiques Mazor from an empirical standpoint. Benatar argues that Mazor incorporates speculative claims about circumcision reducing sexual pleasure into his ethical calculus without sufficient or conclusive empirical support, although Benatar ultimately maintains that parental discretion remains morally permissible given the available medical evidence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David P Lang", "Joseph Mazor", "David Benatar", "Paul Fleiss", "Michael Benatar"], "organizations": ["Journal of Medical Ethics", "BMJ", "Boston College", "University of Cape Town"], "themes": ["Ethics of infant male circumcision", "Bodily integrity and parental rights", "Anatomy and sexual dysfunction", "Prophylactic surgery versus medical necessity", "Gender double standards in genital cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('559490fb1c236980388ace924953add66cf6c9af252c01ceed4ba80f849b067c', 'Lau Identification of circ complic SocPedurol 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/559490fb1c236980388ace924953add66cf6c9af252c01ceed4ba80f849b067c.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "This document appears to be an academic medical abstract regarding the classification and analysis of circumcision complications using a regional claims database. Due to font encoding and character corruption in the source text, only section headers (Introduction, Methods, Results, Conclusions) and the general subject matter relating to pediatric urologic outcomes can be identified.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["The Societies for Pediatric Urology"], "themes": ["Pediatric Urology", "Circumcision Complications", "Healthcare Claims Database Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c92bb2c79ba8aef298c6a9f43a44e43b6518007963d51baab029f1637190821b', 'Laumann Circ in the U.S. JAMA 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c92bb2c79ba8aef298c6a9f43a44e43b6518007963d51baab029f1637190821b.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This study analyzes data from the National Health and Social Life Survey (NHSLS) to evaluate the prevalence, health outcomes, and sexual practices associated with male circumcision in the United States. The findings reveal that circumcision rates are significantly higher among white men and those born to more educated mothers, tracking historical increases in hospital births. \n\nRegarding outcomes, the authors find no evidence that circumcision protects against sexually transmitted diseases (STDs), with circumcised men having slightly higher rates of bacterial infections among highly sexually active groups. However, circumcised men\u2014especially older cohorts\u2014reported lower rates of sexual dysfunction, such as erectile difficulties. Furthermore, circumcised men exhibited a more varied set of sexual practices, including higher rates of masturbation and oral sex, though variations across ethnic groups suggest these behavioral differences are primarily driven by cultural factors rather than biological effects.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Edward O. Laumann", "Christopher M. Masi", "Ezra W. Zuckerman"], "organizations": ["University of Chicago", "American Academy of Pediatrics", "National Institutes of Health", "Ford Foundation"], "themes": ["Male Circumcision Prevalence", "Sexually Transmitted Diseases", "Sexual Dysfunction", "Sexual Behavior and Practices", "Socioeconomic and Ethnic Disparities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('544c30b4c8acaac2fc647a52b5d14be74239cbfd35187326359fd2a1f8c1aa68', 'Lawler Circ Medical Value FamMed 1991.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/544c30b4c8acaac2fc647a52b5d14be74239cbfd35187326359fd2a1f8c1aa68.pdf', 'medical_journal', 'ingested', '{"date": "1991", "description": "This study presents a decision-tree and cost-effectiveness analysis evaluating the medical value of routine neonatal circumcision compared to noncircumcision over a simulated 85-year life expectancy. The analysis found that routine circumcision resulted in an expected lifetime cost of $164.61 and 84.999 quality-adjusted life years, compared to $139.26 and 84.971 years for noncircumcision, yielding a net cost-effectiveness ratio of $919.87 per quality-adjusted life year.\n\nDespite being within the range traditionally considered worthwhile for public health policy, the individual differences in lifetime cost ($25) and benefit (approximately 10 days of life) are minimal. Given these marginal differences and the uncertainty of reported disease incidence and surgical risks, the authors conclude there is no clear medical indication for or against routine neonatal circumcision, suggesting the choice should rely on nonmedical considerations such as parental preference and religious conviction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Frank H. Lawler", "Roberto S. Bisonni", "David R. Holtgrave"], "organizations": ["University of Oklahoma Health Sciences Center", "National Center for Health Statistics"], "themes": ["Neonatal Circumcision", "Cost-Effectiveness Analysis", "Medical Decision Modeling", "Preventive Health and Penile Cancer", "Surgical Risks vs. Benefits"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('214f8dcdd67109749816d97ba055f2cf98511665798aa88c07c4852aae0049be', 'Layer After_my_husband''s_circ PlosOne 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/214f8dcdd67109749816d97ba055f2cf98511665798aa88c07c4852aae0049be.pdf', 'medical_journal', 'ingested', '{"date": "2013-08-29", "description": "This qualitative study evaluates women''s attitudes and risk perceptions toward male circumcision in the Iringa Region of Tanzania, an area undergoing rapid public health scale-up of circumcision services. Through in-depth interviews and focus groups, the researchers found a strong preference among women for circumcised men, driven by social stigma surrounding uncircumcised men, perceived increases in sexual pleasure and desirability, and assumptions of reduced disease risk.\n\nHowever, the study highlights critical misconceptions: many female respondents substantially overstated the health benefits, believing that male circumcision directly protects women from HIV transmission and completely eliminates the risk of other sexually transmitted infections. The authors conclude that public health messaging must be revised to clearly communicate the limits and partial protection offered by male circumcision to prevent behavioral risk disinhibition among both men and women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Erica H. Layer", "Sarah W. Beckham", "Lilian Mgeni", "Catherine Shembilu", "Romani B. Momburi", "Caitlin E. Kennedy", "D William Cameron"], "organizations": ["Johns Hopkins Bloomberg School of Public Health", "Muhimbili University of Health and Allied Sciences", "Primary Health Care Institute", "Tanzania National Institute for Medical Research", "World Health Organization"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Risk Perception and Compensation", "Women''s Sexual and Reproductive Health", "Social Norms and Stigmatization", "Public Health Messaging"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('df1532f4b00ac8923e1d22fe2996145da5f365dda888f9a9e8d307c1e102cdf8', 'LeBourdais Circ No Longer Routine CanMedAssnJ 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/df1532f4b00ac8923e1d22fe2996145da5f365dda888f9a9e8d307c1e102cdf8.pdf', 'medical_journal', 'ingested', '{"date": "1995-06-01", "description": "This article examines the shifting medical, legal, and ethical consensus surrounding routine neonatal male circumcision in Canada during the mid-1990s. While historically practiced widely due to custom, tradition, and purported prophylactic benefits, nontherapeutic circumcision faces increasing scrutiny regarding surgical necessity, infant pain management, human rights, and the child''s bodily autonomy under Canadian law. Although provincial insurance plans largely delisted routine circumcision and pediatric societies withdrew support for it as a standard procedure, medical licensing bodies remain hesitant to institute outright prohibitions or formal protocol restrictions due to entrenched religious and cultural traditions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eleanor LeBourdais", "Dr. Paul Thiessen", "Janet Ecker", "Dr. Morris Vanandel", "Dr. Robert Brown", "Susan Hodges"], "organizations": ["Canadian Medical Association", "Canadian Paediatric Society", "Registered Nurses'' Association of British Columbia", "College of Physicians and Surgeons of British Columbia", "College of Physicians and Surgeons of Ontario", "Health Canada", "Canadian Institute of Child Health", "ETHIC (End the Horror of Infant Circumcision)", "RECAP (RECover A Penis)", "Supreme Court of Canada"], "themes": ["Neonatal Circumcision", "Children''s Rights and Autonomy", "Medical Necessity and Ethics", "Infant Pain and Analgesia", "Religious and Cultural Freedom", "Healthcare Coverage and Policy", "Female Genital Mutilation vs. Male Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d7c36c01fa029a4b47b0c9764e9019e45fce275017994beb3a6b9797502a0dab', 'Lee Filipino experience male circ CulHlthSex 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d7c36c01fa029a4b47b0c9764e9019e45fce275017994beb3a6b9797502a0dab.pdf', 'medical_journal', 'ingested', '{"date": "2006-08-17", "description": "This academic paper examines the practice and perception of ritual male circumcision (tuli) among Filipino men, drawing on qualitative data from interviews with 114 circumcised males in 2002. The findings indicate that circumcision in the Philippines is predominantly viewed as an indispensable cultural rite of passage tied directly to masculinity, social acceptance, and peer conformity rather than strictly medical or religious considerations. The author argues that contemporary anti-circumcision campaigns often fail because they deploy Western biomedical and bioethical arguments that overlook the cultural embeddedness of the practice; consequently, advocacy efforts should focus on addressing notions of manhood and promoting risk-free, hygienic circumcision standards rather than outright eradication.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Romeo B. Lee", "Reynaldo Joson", "Meiwita Budiharsana", "Terrence Hull"], "organizations": ["De La Salle University-Manila", "Ford Foundation", "Australian National University"], "themes": ["Male circumcision", "Masculinity and gender identity", "Rites of passage", "Anti-circumcision advocacy", "Public health and surgical safety"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('efdee8370fe0564b62a704e0f062414243c886416d7b6013998a890a8c2d0f22', 'Lee Neuroanatomy clitoris 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/efdee8370fe0564b62a704e0f062414243c886416d7b6013998a890a8c2d0f22.pdf', 'medical_journal', 'ingested', '{"date": "2026-03-20", "description": "Using Hierarchical Phase-Contrast Tomography (HiP-CT) powered by synchrotron radiation, this study maps the three-dimensional neuroanatomy of the human clitoris at micrometer-scale resolution. Overcoming historical limitations of gross dissection, the researchers traced the complete trajectory of the dorsal nerve of the clitoris (DNC), discovering that rather than diminishing near the glans, it divides into five major nerve trunks exhibiting an extensive tree-like branching pattern innervating each hemisphere without crossing the midline.\n\nThe findings also demonstrate that branches of the DNC extend to innervate the clitoral hood and mons pubis, while the posterior labial nerve provides sensory innervation to both the labia and the lateral surroundings of the clitoral body. These anatomical insights redefine conventional surgical ''danger zones'' and offer critical guidance for optimizing outcomes in female genital cosmetic surgeries, gender-affirmation procedures, and reconstructive surgeries for survivors of female genital mutilation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ju Young Lee", "Bernadette S de Bakker", "Demi Alblas", "Claire L Walsh", "Peter D Lee", "Paul Tafforeau", "Judith AF Huirne"], "organizations": ["Amsterdam UMC", "University College London", "European Synchrotron Radiation Facility", "Univ. Grenoble Alpes", "Medische Kliniek Velsen"], "themes": ["Clitoral Neuroanatomy", "Phase-Contrast Tomography", "Surgical Anatomy and Danger Zones", "Female Genital Mutilation Reconstruction", "Vulvar and Pelvic Innervation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('103bd5be4ba7f88af20ec4e6b38377fc2ce5e02ce1dc3dc92996714398fd69fb', 'Leeming Religion and Sexuality 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/103bd5be4ba7f88af20ec4e6b38377fc2ce5e02ce1dc3dc92996714398fd69fb.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This article examines the historical rupture between religion and sexuality, arguing that their ancient, natural synergy has been systematically dismantled by patriarchal religious structures. Author David Leeming traces how early human history and goddess-centered mythologies celebrated sexuality as a sacred metaphor for divine fertility and cosmic creation. With the rise of warrior-led patriarchies and the establishment of the Abrahamic monotheisms, the sacred feminine was marginalized, leading to the repression of women, the framing of sexual expression as sinful, and deep cultural neuroses.\n\nLeeming links this historical repression to modern systemic issues within religious institutions, most notably the recurring problem of clerical sexual abuse. He argues that addressing such crises requires looking beyond immediate administrative or legal blame to address the broader psychological alienation of religion from the body. Finally, he proposes that drawing upon mystical traditions\u2014such as those of St. John of the Cross and Rumi, who utilized erotic and passionate language to describe union with the divine\u2014can help reconcile human spirituality with natural sexuality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David Leeming", "Karen Armstrong", "John Donne", "Saint Augustine", "Tertullian", "San Juan de la Cruz", "Jelaluddin Rumi"], "organizations": ["Springer", "JSTOR", "Blanton-Peale Institute", "University of Connecticut", "Roman Catholic Church", "Episcopal Church"], "themes": ["Religion and Sexuality", "Patriarchy and the Repression of Women", "Goddess Mythology and Sacred Marriage", "Clergy Sexual Abuse", "Abrahamic Monotheism", "Mysticism and Erotic Spiritual Language"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2d24ed2b0eefe9f0dc85cb2ecc41f27fd664e4378b1307817d2c3dc2491b73a2', 'Lempert Earp Non_therapeutic_circumcision_UK ClinEth 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2d24ed2b0eefe9f0dc85cb2ecc41f27fd664e4378b1307817d2c3dc2491b73a2.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This academic article provides a comprehensive ethical and legal critique of the British Medical Association''s (BMA) 2019 guidance regarding non-therapeutic penile circumcision (NPC) of healthy minors. The authors argue that the BMA''s nominally ''neutral'' stance functions as an incoherently permissive policy that improperly applies the ''best interests'' standard, prioritizing parental religious and cultural preferences over the child''s future bodily autonomy and physical integrity.\n\nThe authors further contend that current UK medical and legal policies create unjustifiable double standards based on sex and gender, especially when contrasted with the strict legal prohibitions against female genital mutilation (FGM) and growing protections for intersex children. Highlighting recent UK case law where courts consistently favored deferring circumcision until the child is competent to consent, the article advocates for a unified ethical and safeguarding framework that protects all children from non-consensual, medically unnecessary genital modifications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antony Lempert", "James Chegwidden", "Rebecca Steinfeld", "Brian D. Earp", "Lord Justice Munby", "Rebecca Mussell"], "organizations": ["British Medical Association", "National Secular Society", "Old Square Chambers", "Oxford University", "Yale University", "The Hastings Center", "General Medical Council", "World Health Organization", "Royal Dutch Medical Association", "Danish Medical Association", "Finnish Medical Association", "American Academy of Pediatrics"], "themes": ["Medical Ethics", "Non-Therapeutic Penile Circumcision", "Bodily Autonomy and Integrity", "Child Safeguarding", "Gillick Competence and Informed Consent", "Best Interests Standard", "Sex Discrimination in Healthcare Law", "Religious and Cultural Rights vs. Children''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('04ddd3cb0b4382b3c1fc005f78665206ffe6b3fa86b72eb4a5a3c304f83080aa', 'Lempert Roadblocks reforming UK ClinEthics 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/04ddd3cb0b4382b3c1fc005f78665206ffe6b3fa86b72eb4a5a3c304f83080aa.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This article examines the ethical, professional, and safeguarding contradictions in UK medical guidance regarding medically unnecessary penile circumcision (MUPC) performed on non-consenting male children. The author argues that regulatory and professional guidance issued by the General Medical Council (GMC) and the British Medical Association (BMA) creates an anomalous, permissive exception for MUPC. This stance prioritizes parental religious and cultural preferences over child-centered safeguarding principles, bodily integrity, and the preservation of future autonomous choices, presenting a stark contrast to how UK guidelines strictly regulate other non-therapeutic pediatric interventions such as labiaplasty and female genital mutilation.\n\nProviding an insider perspective as a doctor and BMA representative, the author details persistent institutional resistance, lack of transparent engagement, and procedural roadblocks to debating or reforming circumcision guidelines within UK medical bodies. The author calls on regulatory authorities and child safeguarding boards to eliminate these double standards, align MUPC policies with established medical ethics regarding consent and bodily harm, and protect all children regardless of cultural or religious background.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antony Lempert", "Al Aynsley-Green", "James Munby", "Brian D. Earp"], "organizations": ["General Medical Council", "British Medical Association", "National Secular Society", "Secular Medical Forum", "National Health Service", "Council for Healthcare Regulatory Excellence", "Parliamentary Assembly of the Council of Europe", "UN Committee on the Rights of the Child", "Royal Dutch Medical Association", "British Society for Paediatric and Adolescent Gynaecology"], "themes": ["Non-therapeutic Male Circumcision (NTMC)", "Child Safeguarding and Bodily Integrity", "Medical Ethics and Informed Consent", "Parental Rights vs. Child Autonomy", "Healthcare Policy and Regulatory Reform", "Religious and Cultural Freedom in Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1ab8b0f921d447b05a19c5cf9f436965332e175351599b71686968514e06ff03', 'Levey Male circ after Cologne GlobDisc 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1ab8b0f921d447b05a19c5cf9f436965332e175351599b71686968514e06ff03.pdf', 'other', 'ingested', '{"date": "2013-06-07", "description": "This article analyzes the 2012 Cologne regional court decision that criminalized non-therapeutic infant male circumcision on the grounds of bodily integrity and consent, alongside the German parliament''s subsequent legislation affirming the right of parents to continue the practice. While acknowledging that the court pinpointed the primary liberal concern\u2014irrevocably altering an individual''s body without consent\u2014the author argues that abrupt judicial criminalization of an ancient, widely accepted cultural and religious tradition was inappropriate and contrary to liberal governance.\n\nThe author contends that liberal democracies regularly exhibit gaps and variegation in how principles of autonomy and consent are applied, balancing them against parental decision-making and religious traditions. Rather than imposing abrupt bans, liberal states should manage such complex, divided issues through ''principled pragmatism,'' employing regulation, public discourse, and non-criminal policy levers.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Geoffrey Brahm Levey", "Angela Merkel", "Alan Dershowitz", "Jonathan Sacks", "Brian Barry", "George Williams"], "organizations": ["Cologne Regional Court", "German Parliament", "American Academy of Pediatrics", "World Health Organisation", "Conference of European Rabbis", "University of New South Wales"], "themes": ["Infant male circumcision", "Bodily integrity and autonomy", "Religious freedom", "Multiculturalism", "Parental rights and consent", "Principled pragmatism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2c2a0cf9438f78599d994d23e51f50edb88884c2010029f84364bc1de17ed9ab', 'Li Legal Database Review Urology 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2c2a0cf9438f78599d994d23e51f50edb88884c2010029f84364bc1de17ed9ab.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This academic study analyzes circumcision-related medical malpractice litigation in the United States from 1939 to 2021 using the Nexis Uni legal database. Reviewing 70 relevant legal cases, the researchers found that most claims were processed in state or appellate courts and primarily involved pediatric patients, with urologists being the most frequently sued specialists. The leading alleged grounds for lawsuits were negligent surgical performance (49%) and negligent informed consent (30%), with common complications including aesthetic dissatisfaction, pain, and impaired sexual function.\n\nOverall, trial verdicts favored physicians in 59% of cases, with plaintiff victories resulting in a median indemnity of $175,000. The study determined that claims centered on negligent informed consent were significantly more likely to resolve in favor of the physician compared to those alleging surgical errors. The authors conclude that while circumcision litigation remains rare and generally favors defendants, clinicians must mitigate liability by obtaining comprehensive informed consent, communicating potential complications, and ensuring proper surgical indications and technique.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kevin D. Li", "Nizar Hakam", "Patrick Low", "Jason Lui", "Michael J. Sadighian", "Behnam Nabavizadeh", "Nathan M. Shaw", "Benjamin N. Breyer", "Shirin Razdan", "Jeffrey A. Stock"], "organizations": ["University of California San Francisco", "American Urological Association", "American Medical Association", "Icahn School of Medicine at Mount Sinai", "Elsevier Inc."], "themes": ["Medical Malpractice", "Circumcision", "Urologic Surgery", "Informed Consent", "Surgical Negligence", "Tort Litigation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('327f0cc11cbe0a14ed790606a27a91487f0405de20b6c6c99629280046108ba6', 'Li, Malhotra Advice Uncirc Ped Urol 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/327f0cc11cbe0a14ed790606a27a91487f0405de20b6c6c99629280046108ba6.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This academic study examines the frequency, confidence, and variability of advice given by pediatric residents to parents regarding the care of the uncircumcised penis. Utilizing an IRB-approved survey administered to 244 pediatric residents across five urban programs, the authors found that 49% of responding residents had never received instruction on preputial care, less than half routinely offered advice to families, and their median confidence level was low. Furthermore, among residents who did provide counsel, recommendations regarding the timing and frequency of foreskin retraction varied widely.\n\nThe authors conclude that pediatric residents lack the preparedness and standardized knowledge necessary to advise parents properly, which can lead to inappropriate interventions such as forceful retraction or unnecessary specialist referrals. The study emphasizes an urgent need for standardized best-practice guidelines and the integration of structured pediatric urology curricula, such as web-based e-learning modules, within residency programs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Neha R. Malhotra", "Ilina Rosoklija", "Rachel Shannon", "Anthony D\u2019Oro", "Dennis B. Liu"], "organizations": ["University of Illinois at Chicago", "Ann & Robert H. Lurie Children''s Hospital of Chicago", "Northwestern University Feinberg School of Medicine", "American Academy of Pediatrics", "Accreditation Council for Graduate Medical Education"], "themes": ["Pediatric Urology", "Medical Resident Training", "Uncircumcised Penile Care", "Parental Education", "Phimosis and Foreskin Retraction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('78f8f6687d62fa978a5e8728b72e0d6c91c8d73acfa8ad120da50a37ab52a90d', 'Liao Adult recall FGM J Ob-Gyn 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/78f8f6687d62fa978a5e8728b72e0d6c91c8d73acfa8ad120da50a37ab52a90d.pdf', 'medical_journal', 'ingested', '{"date": "2013-04-03", "description": "This pilot study examines adult recall and long-term perceptions of female genital mutilation (FGM) among 17 Somali-speaking women attending a specialist African Women''s Clinic in London. Conducted to evaluate service improvement and research feasibility, the study revealed that most participants underwent FGM during early childhood without consent, with over 40% attributing ongoing physical and mental health issues\u2014including sexual and emotional difficulties\u2014to the procedure.\n\nThe findings highlight a substantial gap in existing clinic services, which traditionally focus on physical de-infibulation rather than addressing psychological trauma. The authors emphasize the feasibility of conducting psychosocial research within clinical contexts when language barriers are mitigated, recommending the integration of psychological screening, triaging, and educational strategies to safeguard future generations and better support affected women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["L.-M. Liao", "C. Elliott", "F. Ahmed", "S. M. Creighton"], "organizations": ["University College London", "Institute for Women''s Health", "University College London Hospitals NHS Foundation Trust", "African Women''s Clinic", "Ampelos Trust"], "themes": ["Female Genital Mutilation (FGM)", "Psychological Impact and Mental Health", "Women''s Health and Gynaecology", "Healthcare Service Improvement", "Patient Perceptions and Attitudes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2903a259439f5dc215d6361b9453e899b49a315a5b6c180ce8dedd9789fea096', 'Lien Gambian men view cut&uncut women Sexualities 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2903a259439f5dc215d6361b9453e899b49a315a5b6c180ce8dedd9789fea096.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This qualitative study investigates the perspectives of 50 Gambian men (Mandinka and Wolof) and eight Mandinka women on how female genital cutting (FGC) impacts male and female sexuality, sensitivity, and intimate relationships. The author examines whether men notice differences between cut and uncut sexual partners and how those experiences influence their attitudes toward the practice.\n\nThe findings reveal that men perceive substantial differences between cut and uncut women, associating FGC with reduced female lubrication, passivity, reduced sexual pleasure, and pain during intercourse. Men reported needing to adopt distinct sexual scripts to compensate for these effects, such as taking more time or stimulating alternative sensitive areas. Because men found intercourse with uncut women more pleasurable and emotionally rewarding, personal sexual experience led the majority of interviewed men\u2014even among ethnic groups that traditionally practice FGC\u2014to express a preference for uncut partners.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Inger-Lise Lien"], "organizations": ["Norwegian Centre for Violence and Traumatic Stress Studies", "World Health Organization", "UNICEF"], "themes": ["Female Genital Cutting (FGC)", "Sexuality and Sexual Pleasure", "Sexual Scripts and Communication", "Cultural and Ethnic Practices in The Gambia", "Male Perspectives on Female Sexuality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('724c0f7056ee4666a5ad349e0477f3367fff11d0f7e9b3c805d34de36c299d76', 'Litleskare Refusal ritual circumcision BMC MedEth 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/724c0f7056ee4666a5ad349e0477f3367fff11d0f7e9b3c805d34de36c299d76.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This qualitative study investigates the ethical and professional reasoning of ten Norwegian urologists who refuse to perform ritual infant male circumcision following a 2015 law integrating the procedure into Norway''s public healthcare system with a conscience clause. Utilizing systematic text condensation, the researchers found that physicians uniformly justify their refusal through core healthcare ethics principles\u2014noting a lack of medical indication (beneficence), risks of harm and bodily mutilation (non-maleficence), inability of the infant to give consent (autonomy), and inappropriate diversion of limited hospital resources from sick patients (justice).\n\nAlthough grounded in objective professional standards, about half of the interviewed physicians expressed that participating in the procedure would also compromise their personal conscience and integrity. Consequently, the authors conclude that the theoretical boundary separating professional refusals from conscience-based objections is less distinct in practice, as professional norms often become deeply integrated into a physician''s core personal moral identity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Liv Astrid Litleskare", "Mette Tol\u00e5s Strander", "Reidun F\u00f8rde", "Morten Magelssen", "Mark R. Wicclair"], "organizations": ["University of Oslo", "Norwegian Medical Association", "Norwegian Directorate of Health", "Norwegian Centre for Research Data"], "themes": ["Conscientious Objection", "Professional Ethics", "Ritual Circumcision", "Pediatric Autonomy", "Healthcare Resource Allocation", "Moral Distress"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4a5062eaff8b267908424607e66f619367c49eb2942df65ed3f1f0f1b16853d5', 'Litwiller Circ Bleeding J MatFetNeoMed 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4a5062eaff8b267908424607e66f619367c49eb2942df65ed3f1f0f1b16853d5.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This observational cohort study evaluated the rate of bleeding complications following Gomco clamp circumcision among 260 male infants, comparing those admitted to the neonatal intensive care unit (NICU) with those in the normal newborn nursery (NNN). The authors found that infants admitted to the NICU experienced a significantly higher rate of post-circumcision bleeding complications compared to normal nursery neonates (22% vs. 9.6%). Furthermore, circumcisions performed on or after the fifth day of life were associated with an elevated bleeding rate (28% vs. 10.3%), with all of these delayed procedures occurring in infants initially admitted to the NICU.\n\nThe authors hypothesize that the heightened risk in delayed circumcisions may be related to the waning effectiveness of prophylactic Vitamin K given at birth before endogenous production becomes sufficient. The study suggests that further randomized controlled trials are needed to assess whether redosing Vitamin K or modifying clamping protocols prior to late circumcisions could mitigate bleeding complications in high-risk neonatal populations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Abigail R. Litwiller", "David M. Haas", "C. Browne"], "organizations": ["University of Illinois at Chicago", "Indiana University School of Medicine"], "themes": ["Neonatal Circumcision", "Postoperative Bleeding Complications", "Neonatal Intensive Care", "Vitamin K Prophylaxis", "Gomco Clamp Procedures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c9db2d95c3103bebed9d95adf653dd9e02969348168e0c4f958045d6b211466c', 'Llewellyn Thoughts on Legal Remedies 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c9db2d95c3103bebed9d95adf653dd9e02969348168e0c4f958045d6b211466c.pdf', 'other', 'ingested', '{"date": "1999", "description": "In this chapter, attorney David J. Llewellyn assesses legal strategies to curtail routine infant male circumcision in the United States. He argues that legislative prohibitions and sweeping class actions face immense cultural, religious, and psychological resistance, particularly because circumcision has been deeply medicalized and emotionally normalized by society and the medical profession. Because societal change requires shifting these underlying attitudes, direct bans or attacks on parental consent remain largely ineffective in the short term.\n\nInstead, Llewellyn advocates for strategic, incremental civil litigation focused on conventional tort claims\u2014including medical malpractice, battery, lack of informed consent, and severe surgical harm. Targeting physicians, hospitals, and insurers through well-substantiated cases imposes financial consequences and forces the medical community to confront the anatomical risks and lack of necessity of the procedure. Over time, successful lawsuits and the resulting publicity can educate the public and undermine the financial incentives driving routine neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["David J. Llewellyn", "Terry W. Hensle", "Edgar J. Schoen", "Edward Wallerstein", "Ronald Goldman", "Marilyn F. Milos", "James L. Snyder"], "organizations": ["National Organization of Circumcision Information Resource Centers (NOCIRC)", "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)", "American Academy of Pediatrics", "Columbia College of Physicians and Surgeons", "Jackson Hospital & Clinic"], "themes": ["Neonatal Circumcision", "Medical Malpractice and Tort Liability", "Informed Consent", "Medicalization of Cultural Practices", "Bodily Integrity and Legal Remedies"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('40954dd246e94d458ac7b3cb1ca985cf435543137ca690518be7857be87958e4', 'Loehle, Bossio Male genital image CanJHumSex 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/40954dd246e94d458ac7b3cb1ca985cf435543137ca690518be7857be87958e4.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This empirical study investigates the factors influencing men''s genital self-image across different sexual orientations and geographic regions, analyzing survey data from 674 gay, bisexual, MSM, and heterosexual men across Canada, the United States, and Western Europe. Utilizing multiple regression models, the researchers examined the impact of variables such as body image self-consciousness, social appearance anxiety, solo pornography consumption, circumcision status, and age on genital self-perception.\n\nThe findings reveal that men''s genital self-image was uniquely predicted by social appearance anxiety and body image, though unexpectedly, higher genital self-image was associated with worse body image and higher social appearance anxiety. Sexual orientation did not significantly impact genital self-image, and while univariate analyses indicated that intact men and younger men reported somewhat higher genital satisfaction, these demographic and behavioral variables were not significant predictors in the full multivariate model.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brandon Loehle", "Raymond M. McKie", "Drake Levere", "Jennifer A. Bossio", "Terry P. Humphreys", "Robb Travers"], "organizations": ["Wilfrid Laurier University", "University of Ottawa", "University of British Columbia", "Trent University", "University of Toronto Press"], "themes": ["Genital Self-Image", "Body Image Dissatisfaction", "Social Appearance Anxiety", "Sexual Orientation and MSM", "Male Circumcision", "Pornography Use", "Social Comparison Theory"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('50ccf97cbb16c8d896945306a96ffaa5f7baf535d1ad4e47174864253ed93521', 'Lukacs NonSurg Zipper EurJEmergMed 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/50ccf97cbb16c8d896945306a96ffaa5f7baf535d1ad4e47174864253ed93521.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This medical report introduces a novel, simple, and nonsurgical procedure for managing zipper-related penile skin entrapment. The technique involves cutting the zipper tape and teeth closely above and below the connector, applying lubrication and local anesthesia, and using a needle holder with gentle counter-traction to pull the zipper apparatus apart, successfully freeing the entrapped tissue.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Szilveszter Lukacs", "Benjamin Tschobotko", "Evangelos Mazaris"], "organizations": ["St Mary\u2019s Hospital Imperial College Healthcare NHS Trust", "Wolters Kluwer Health", "Lippincott Williams & Wilkins"], "themes": ["Penile zipper entrapment", "Emergency medicine", "Nonsurgical interventions", "Urological trauma management", "Surgical techniques"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e892dd01448b88fd244f5b858d871f511e7443bb71e28c374fb4b2edbaa5f590', 'Luo Infant Pain BMJ Peds 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e892dd01448b88fd244f5b858d871f511e7443bb71e28c374fb4b2edbaa5f590.pdf', 'medical_journal', 'ingested', '{"date": "2023-10-11", "description": "This single-centre cross-sectional study evaluates the procedural pain experienced by 957 neonates across 15 routine clinical procedures in a neonatal intensive care unit (NICU) setting. Using the Neonatal Infant Pain Scale (NIPS), researchers categorized procedures into three distinct pain severity levels: severe pain (such as peripheral IV cannulation, arterial blood sampling, and PICC placement), mild-to-moderate pain (such as heel pricks, lumbar punctures, and intramuscular injections), and no pain to mild pain (such as gastric tube insertion and enemas).\n\nThe authors conclude that neonatal pain responses follow distinct patterns, advocating for proactive, pre-intervention pharmacological analgesia for procedures with consistently high pain scores. For procedures showing more variable or lower pain scores, they recommend universal non-pharmacological pain relief strategies complemented by real-time pain monitoring to determine if additional analgesia is warranted.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Feixiang Luo", "Huaiyu Zhu", "Lingli Mei", "Qi Shu", "Xiaoying Cheng", "Xiaofei Chen", "Yisheng Zhao", "Shuohui Chen", "Yun Pan"], "organizations": ["The Children''s Hospital, Zhejiang University School of Medicine", "Zhejiang University", "National Clinical Research Center for Child Health", "BMJ", "National Natural Science Foundation of China"], "themes": ["Neonatal Procedural Pain", "Neonatal Intensive Care Unit (NICU)", "Neonatal Infant Pain Scale (NIPS)", "Pediatric Pain Management", "Pharmacological and Non-Pharmacological Analgesia"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('399ebe47d48cb272c49095624c889a0203d8efee91362628bb6eea52acb6c8f3', 'Lyons Circ as HIV Vaccine Pub Health 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/399ebe47d48cb272c49095624c889a0203d8efee91362628bb6eea52acb6c8f3.pdf', 'medical_journal', 'ingested', '{"date": "2013-01-23", "description": "This article critically evaluates proposals advocating mass prophylactic male infant circumcision (MIC) as a ''surgical vaccine'' against heterosexual HIV transmission in countries with low HIV prevalence, such as the UK and Australia. The author reviews epidemiological data and public health ethics frameworks to argue that circumcision provides at best partial protection, carries non-negligible surgical risks and pain, and offers virtually no health benefit to children during minority. Additionally, the paper contends that framing a surgical procedure as a ''vaccine'' is biologically inaccurate and misleading, which risks compromising parental informed consent and damaging public trust in conventional childhood immunizations. Consequently, the author concludes that mass infant circumcision is ethically unjustified in low-prevalence settings and that any decision regarding prophylactic circumcision should be deferred until individuals reach the age of informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Barry Lyons", "Brian J. Morris", "David A. Cooper", "Alex D. Wodak", "Nancy Kass"], "organizations": ["Trinity College Dublin", "World Health Organization", "UNAIDS", "British Medical Association", "Royal Australasian College of Physicians", "Conseil National du Sida", "American Academy of Pediatrics"], "themes": ["Male Infant Circumcision", "HIV Prevention", "Public Health Ethics", "Bodily Integrity", "Informed Consent", "Medical Terminology and Misrepresentation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b971c16b049e86e558eba5bc592dfda77fa3fda4629da1b920e517f859f2780c', 'Lyons The Jacobs-parental-prerogative-test-AmJBio-2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b971c16b049e86e558eba5bc592dfda77fa3fda4629da1b920e517f859f2780c.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-12", "description": "In this commentary, Barry Lyons and Ralph Hurley O''Dwyer critique the ''Jacobs Test,'' arguing that it operates to shield parental authority and religious decisions from state interference rather than genuinely evaluating male infant circumcision (MIC) from a human rights or child welfare perspective. The authors contend that both Jacobs and the American Academy of Pediatrics (AAP) display a pronounced cultural bias that prioritizes parental rights and family privacy over an infant''s fundamental right to bodily integrity, noting that the same rationale was historically used by the AAP to controversially contemplate ritual female genital cutting.\n\nThe authors also examine a significant transatlantic ethical divide, contrasting the enduring religiosity and emphasis on parental prerogative in the United States with the secular, human rights-oriented framework emerging across Northern Europe. While medical associations in countries such as the Netherlands and Sweden increasingly classify non-therapeutic circumcision of minors as a violation of physical integrity and children''s rights, U.S. institutions continue to privilege parental choices, prompting the authors to question whether bodily integrity is treated as a right only afforded to European children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Barry Lyons", "Ralph Hurley O''Dwyer", "Allan J. Jacobs", "Kavita Shah Arora", "Douglas S. Diekema", "Lainie Friedman Ross", "Joseph Goldstein"], "organizations": ["Trinity College Dublin", "American Academy of Pediatrics", "Royal Dutch Medical Association", "Swedish Pediatric Surgeons Association", "United Nations", "Routledge"], "themes": ["Male Infant Circumcision", "Parental Prerogative vs. Children''s Rights", "Bodily Integrity", "Bioethics and Medical Decision-Making", "Cultural Bias in Pediatric Policy", "Female Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f1c86bae5cf2ee4e681280bc1aa839e71194c91c5ae19798afefcaf3cb7efa00', 'MacClymont Female Circ America Free Inquiry 2026.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f1c86bae5cf2ee4e681280bc1aa839e71194c91c5ae19798afefcaf3cb7efa00.pdf', 'other', 'ingested', '{"date": "2026", "description": "This article presents an interview by Daniel N. MacClymont with Patricia Robinett, an American survivor of childhood female circumcision and author of ''The Rape of Innocence.'' Robinett describes how she was subjected to genital cutting at around seven years old in 1950s Kansas, a procedure then promoted by segments of the U.S. medical system as a Victorian-rooted ''cure'' for masturbation and non-normative behavior. She shares her journey of uncovering this deeply suppressed personal trauma later in life, the resulting physical and emotional damages, and how her discovery led her to become an activist against childhood genital cutting.\n\nThe discussion also examines broader ethical issues surrounding non-consensual childhood surgeries in the United States, including male circumcision, intersex genital surgeries, and episiotomies. Robinett and MacClymont argue that differentiating between male and female genital modifications creates a cultural and legal double standard, asserting that all non-therapeutic, non-consensual alterations of children''s genitalia constitute violations of bodily autonomy and equal human rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Daniel N. MacClymont", "Patricia Robinett", "John Erickson", "Marilyn Milos", "Edward Bernays", "Tim Hammond"], "organizations": ["Free Inquiry", "Blue Cross Blue Shield", "World Health Organization", "Genital Autonomy Legal Defense and Education Fund (GALDEF)", "Intact Global", "Kansas City Intactivists"], "themes": ["Female Genital Mutilation / Circumcision", "Medical Ethics and History", "Bodily Autonomy and Children''s Rights", "Intactivism", "Psychological Trauma", "Gender and Equal Protection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0ef0f2033d98f0a4be5b0df8efbaecc2373dc3944c68a47682c41481fabf16fd', 'MacDonald GetTimingRight CMAJ 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0ef0f2033d98f0a4be5b0df8efbaecc2373dc3944c68a47682c41481fabf16fd.pdf', 'medical_journal', 'ingested', '{"date": "2011-03-21", "description": "This editorial examines whether randomized trials from sub-Saharan Africa demonstrating that adult male circumcision significantly reduces the risk of acquiring HIV and other sexually transmitted infections should prompt pediatric societies in Canada, the United States, and Australia to revise their policies against routine infant circumcision. The author notes that these findings have limited relevance to low-prevalence countries and that the health benefits of circumcision do not emerge until an individual becomes sexually active, leaving little justification for subjecting neonates to a painful elective procedure.\n\nThe author argues that professional pediatric organizations should instead focus on evaluating the evidence and cost-effectiveness of routine peripubertal male circumcision. Offering the procedure to adolescents rather than infants provides the distinct ethical advantage of patient assent and informed consent, while simultaneously creating an educational opportunity to discuss broader methods of preventing sexually transmitted infections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Noni MacDonald"], "organizations": ["Canadian Medical Association", "Royal Australasian College of Physicians", "American Academy of Pediatrics"], "themes": ["Male Circumcision", "Infant Health", "Adolescent Health", "HIV/STI Prevention", "Medical Ethics and Informed Assent", "Pediatric Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ebe79e82025dd48cc0218e30b5f9d2d1d16888ece4585646e441ae6e12088c1d', 'Maguire Surgery & Loss of Body Parts BMJ 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ebe79e82025dd48cc0218e30b5f9d2d1d16888ece4585646e441ae6e12088c1d.pdf', 'medical_journal', 'ingested', '{"date": "1998-04-04", "description": "This collection of articles from the British Medical Journal addresses three distinct medical and socio-political topics. First, Gareth Williams critiques the United Kingdom''s Research Assessment Exercise (RAE), arguing that its evaluation criteria are methodologically flawed, biased toward established institutions, and harmful to scholarship and teaching, proposing instead an objective system based on total publication output. Second, Vivienne Nathanson provides a firsthand account of Cambodia''s public health crisis surrounding landmines and unexploded ordnance, highlighting the dire state of military hospitals, the indispensable role of nongovernmental demining organizations, and the ongoing need for long-term international aid and prosthetics support. \n\nFinally, Peter Maguire and Colin Murray Parkes examine the psychological repercussions of surgical loss of body parts, such as limbs and breasts, as well as the emotional toll of cancer and cardiac procedures. They compare reactions to amputation with bereavement, noting that loss of bodily function and altered body image frequently cause persistent grief, anxiety, and depression that require proactive communication, counselling, and specialized mental health support.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gareth Williams", "Vivienne Nathanson", "Peter Maguire", "Colin Murray Parkes"], "organizations": ["British Medical Association", "Higher Education Funding Councils", "University of Liverpool", "International Committee of the Red Cross", "Mines Advisory Group", "Handicap International", "M\u00e9decins Sans Fronti\u00e8res", "UNICEF"], "themes": ["Research Assessment Exercise (RAE)", "Academic Evaluation and Research Funding", "Landmine Injuries and Demining", "Surgical Amputation and Rehabilitation", "Psychological Coping and Body Image Loss"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5dfe489d39c32d5a54bbcbf999a1543cd694fb2cb5003c3a353efeb5db0feb53', 'Maloney Circ Regret 2022_SRSP.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5dfe489d39c32d5a54bbcbf999a1543cd694fb2cb5003c3a353efeb5db0feb53.pdf', 'medical_journal', 'ingested', '{"date": "2022-05-06", "description": "This study examines personal comfort, regret, and sexual satisfaction among adult males in the United States based on their circumcision status. Administering a cross-sectional survey via Amazon Mechanical Turk to over 400 men, the researchers found no statistically significant differences between circumcised and uncircumcised respondents regarding circumcision regret, desire to alter their status, overall sexual satisfaction, or self-reported medical complications.\n\nMinor differences were observed in specific perceptual areas: uncircumcised men were slightly more likely to believe their status conferred a mild increase in sexual pleasure, whereas circumcised men reported greater comfort with partners or others viewing their penis. The authors conclude that adult satisfaction with circumcision status is generally high regardless of whether the procedure was performed, providing valuable empirical data for healthcare providers and parents engaged in shared decision-making concerning neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Trevor J. Maloney", "Charles A. Loeb", "Kyle Waisanen", "Rohan Shah", "Nomi S. Weiss-Laxer", "Ezekiel Young"], "organizations": ["Philadelphia College of Osteopathic Medicine", "University of California Irvine", "University at Buffalo", "John R. Oishei Children''s Hospital", "American Academy of Pediatrics", "American Urological Association", "Springer Nature"], "themes": ["Male Circumcision", "Sexual Satisfaction", "Circumcision Status Regret", "Men''s Health", "Neonatal Circumcision Policy", "Shared Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5ff81500684bc028e0d92983b59e9ce73061cf98c3a28d2046c9e65c0fe1b0eb', 'Mansfield Hosp Stay JFamPract 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5ff81500684bc028e0d92983b59e9ce73061cf98c3a28d2046c9e65c0fe1b0eb.pdf', 'medical_journal', 'ingested', '{"date": "1995-10", "description": "This study analyzes the parental, provider, and clinical factors associated with neonatal circumcision, as well as its impact on hospital length of stay and costs. Examining records of 3,703 healthy male infants born across four U.S. sites in 1990 and 1991, researchers found that 85% were circumcised. Circumcision was significantly more prevalent among White and African-American infants, patients covered by private insurance, and infants whose mothers had interventional deliveries such as an episiotomy or cesarean section.\n\nAdditionally, circumcised infants had an average hospital stay that was approximately one-fourth of a day longer than uncircumcised infants. The authors extrapolate that this increased length of stay contributes between $234 million and $527 million annually to nationwide hospital costs, above and beyond the direct fees for the surgical procedure itself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Christopher J. Mansfield", "William J. Hueston", "Mary Rudy"], "organizations": ["East Carolina University School of Medicine", "University of Wisconsin-Madison School of Medicine", "St Claire Medical Center", "American Academy of Pediatrics", "American College of Obstetrics and Gynecology", "North American Primary Care Research Group"], "themes": ["Neonatal Circumcision", "Length of Hospital Stay", "Healthcare Costs", "Maternal Health and Interventions", "Socioeconomic Factors in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e12157d22d28ef6ffa284d164871f9be899d9bfd1fc56bbccadce7390d48ec22', 'Mao Circ Difference Gay Men 2008 JSM.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e12157d22d28ef6ffa284d164871f9be899d9bfd1fc56bbccadce7390d48ec22.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This study analyzes data from 1,426 HIV-negative homosexually active men in the Health in Men (HIM) cohort to examine the effect of circumcision on sexual experience and behavior. The researchers found that general circumcision status had no significant impact on anal intercourse practices, condom usage difficulties, or general sexual difficulties such as loss of libido. However, differences emerged based on the timing of circumcision: men circumcised after infancy were significantly more likely to engage in receptive anal intercourse and report erection difficulties, but were less likely to practice insertive anal intercourse or experience premature ejaculation compared to those circumcised at infancy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Limin Mao", "David J. Templeton", "June Crawford", "John Imrie", "Garrett P. Prestage", "Andrew E. Grulich", "Basil Donovan", "John M. Kaldor", "Susan C. Kippax"], "organizations": ["University of New South Wales", "National Centre in HIV Social Research", "National Centre in HIV Epidemiology and Clinical Research", "Sydney South West Area Health Service", "International Society for Sexual Medicine"], "themes": ["Male Circumcision", "Gay and Bisexual Men''s Health", "HIV Prevention", "Sexual Behavior", "Sexual Health and Dysfunction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('74ce7b14f559ef805d2464de5e7ef67d49c1c06b11c72982343de16a2d38435d', 'Mao Circ Difference to Gay Men InSocSexMed 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/74ce7b14f559ef805d2464de5e7ef67d49c1c06b11c72982343de16a2d38435d.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This study analyzes data from 1,426 HIV-negative homosexually active men in the Health in Men (HIM) cohort to determine whether circumcision status influences sexual experience, anal intercourse practices, condom use, or sexual difficulties. After adjusting for age and ethnicity, researchers found no significant differences between circumcised and uncircumcised men across anal intercourse roles, condom difficulties, or sexual problems like loss of libido.\n\nHowever, secondary analyses examining the timing of circumcision revealed differences: men circumcised after infancy were significantly more likely to engage in and prefer receptive anal sex and report erection difficulties, but less likely to practice insertive anal sex or experience premature ejaculation compared to those circumcised as infants. The authors note that post-infancy circumcision was often driven by medical conditions such as phimosis, suggesting prior penile pathology may confound these behavioral outcomes rather than the circumcision procedure itself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Limin Mao", "David J. Templeton", "June Crawford", "John Imrie", "Garrett P. Prestage", "Andrew E. Grulich", "Basil Donovan", "John M. Kaldor", "Susan C. Kippax", "Juliet Richters", "Paul Van de Ven"], "organizations": ["University of New South Wales", "National Centre in HIV Social Research", "National Centre in HIV Epidemiology and Clinical Research", "Sydney South West Area Health Service", "International Society for Sexual Medicine", "Commonwealth Department of Health & Ageing", "New South Wales Health Department", "National Institutes of Health", "Australian Federation of AIDS Organisations", "AIDS Council of New South Wales"], "themes": ["Male Circumcision", "Gay and Bisexual Men''s Sexual Health", "HIV Transmission and Prevention", "Sexual Dysfunction and Behaviors", "Health in Men (HIM) Cohort Study"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6bef038c5f3e478af36a858204a38d388613bb64de0d2e01077ac6c68ed1e674', 'Marcus Circumcision_weeks S AfrFamPrac 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6bef038c5f3e478af36a858204a38d388613bb64de0d2e01077ac6c68ed1e674.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This study evaluates a three-year implementation of medical male circumcision services and clinician training at a Level 1 district hospital in Gauteng, South Africa. Reviewing over 220 procedures performed primarily under local anaesthetic, the authors found a very low complication rate (1.8%), with the majority of patients electing to undergo surgery for cultural reasons to ensure safe rites of passage compared to high-risk traditional procedures.\n\nTo meet escalating public demand and support the World Health Organization''s call for scaled-up circumcision to reduce HIV and STI transmission, the study proposes ''circumcision weeks.'' This model pairs routine service delivery with concentrated clinical and minor surgical training for medical students and practitioners, successfully expanding healthcare capacity while mitigating severe traditional circumcision complications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Frank Peters", "T. S. Marcus"], "organizations": ["University of Pretoria", "Pretoria West Hospital", "World Health Organization"], "themes": ["Voluntary Medical Male Circumcision", "HIV and STI Prevention", "Surgical Skills Training", "District Health Systems", "Traditional vs. Clinical Initiation Rites"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('70a655611f439b8bfeb028e235445759452c1e458b5d39b0d584cba4956720ac', 'Marotta Foreskin Regeneration Market Hegemon 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/70a655611f439b8bfeb028e235445759452c1e458b5d39b0d584cba4956720ac.pdf', 'other', 'ingested', '{"date": "2023-06-28", "description": "This newsletter article analyzes survey data to estimate the commercial market for foreskin regeneration, calculating that it represents over $200 billion in the United States and up to $2.5 trillion globally. Based on an online survey of over 10,000 circumcised men conducted by researcher Aella, approximately 40.3% expressed a desire to regain their foreskin, with 9.1% willing to pay over $20,000 for full function and sensation. The author argues that this represents an untapped ''blue ocean'' market for biotechnology and regenerative medicine, while identifying barriers to entry such as medical liability, high upfront research costs, and cultural taboos surrounding circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Brendon Marotta", "Tim Hammond", "Aella"], "organizations": ["Foregen", "Substack", "United States Census Bureau", "Centers for Disease Control and Prevention", "American Medical Association"], "themes": ["Foreskin Regeneration", "Circumcision", "Biotechnology and Regenerative Medicine", "Market Valuation and Economic Analysis", "Men''s Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('12cbfd88e35f330cd21c23d31cd56fe1c50f830750adb64e70b6104d95333060', 'Marti Tradition_Circumcision_Equat Guinea ZeitEthno 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/12cbfd88e35f330cd21c23d31cd56fe1c50f830750adb64e70b6104d95333060.pdf', 'other', 'ingested', '{"date": "2010", "description": "This article examines male circumcision practices in Equatorial Guinea and among Equatorial Guinean diaspora communities in Catalonia, Spain. Drawing on ethnographic fieldwork conducted between 2008 and 2009, the author explores the traditional ritual elements of male circumcision\u2014predominantly practiced among ethnic groups such as the Fang, Ndowe, and Bubi\u2014which serve as critical rites marking masculinity, virility, and the strict separation of sexes rather than simply transitions to adulthood.\n\nThe paper also investigates the ongoing ''deritualization'' process driven by modernization, urbanization, and medicalization in both Equatorial Guinea and Spain, where circumcisions increasingly occur in clinical settings with anesthesia. Additionally, it analyzes how the practice functions as an assertion of pan-African identity among immigrant communities in Spain, while offering a critical perspective on international health policies that promote male circumcision as an HIV prevention strategy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Josep Mart\u00ed", "Donato Ndongo", "Antonio Aymem\u00ed", "G\u00fcnter Tessmann", "Juan Rondo", "Pierre Bourdieu"], "organizations": ["CSIC (Consejo Superior de Investigaciones Cient\u00edficas)", "Dietrich Reimer Verlag", "World Health Organization (WHO)", "UNAIDS", "La Paz Hospital"], "themes": ["Male Circumcision", "Equatorial Guinean Ethnography", "Cultural Tradition and Deritualization", "Masculinity and Gender Separation", "Immigration and Diaspora Identity", "HIV/AIDS Prevention Controversy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('58726dd37f8487069bda1e728da211106381229c244b53c51524838a3322e82f', 'Mason Male Circ Discussion_Paper 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/58726dd37f8487069bda1e728da211106381229c244b53c51524838a3322e82f.pdf', 'policy_guideline', 'ingested', '{"date": "2007-08-23", "description": "This discussion paper, prepared by Paul Mason, the Commissioner for Children in Tasmania, examines the legal, ethical, and human rights implications of non-therapeutic male infant and child circumcision. It contends that the removal of healthy foreskin tissue without medical necessity constitutes an assault under common law and the Tasmanian Criminal Code, arguing that parents lack the legal authority to consent to non-therapeutic, irreversible procedures that compromise a minor''s bodily integrity without explicit court authorization.\n\nThe paper highlights consensus statements from organizations like the Royal Australasian College of Physicians stating there is no medical indication for routine neonatal circumcision. Furthermore, it argues that current legal protections against female genital mutilation create an inconsistency under human rights frameworks and state anti-discrimination legislation, recommending that Tasmanian law either prohibit non-medical genital procedures for boys or impose stringent medical and regulatory safeguards.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Paul Mason", "Shane Peterson", "Stan Bordeaux"], "organizations": ["Commissioner for Children (Tasmania)", "Parliament of Tasmania", "Royal Australasian College of Physicians", "Family Court of Australia", "High Court of Australia", "Queensland Law Reform Commission", "United Nations"], "themes": ["Male Circumcision", "Children''s Rights", "Informed Consent", "Assault and Criminal Law", "Bodily Integrity", "Medical Ethics", "Equal Protection and Anti-Discrimination"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7df09762c7f5db397bd7abd8ce29cd6e1cdf77a63af2288bae91b7b8d9db5440', 'Massa_Euro_Conv_HR Male Circ (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7df09762c7f5db397bd7abd8ce29cd6e1cdf77a63af2288bae91b7b8d9db5440.pdf', 'legal_document', 'ingested', '{"date": null, "description": "This essay examines whether a state bound by the European Convention on Human Rights (ECHR) can legally justify enacting legislation that prohibits ritual infant male circumcision. The analysis focuses primarily on two key provisions of the ECHR: Article 8, which balances a child''s right to bodily integrity against parental rights to family privacy and autonomy, and Article 9, which weighs an individual''s right to religious freedom and an open future against the parents'' right to raise children within their religious tradition.\n\nThe author concludes that while concerns regarding children''s bodily integrity are serious, a state prohibition would severely impair the religious freedom of families and communities, specifically within Jewish and Muslim traditions. Ultimately, the essay submits that attempts to justify a legal ban under the ECHR would likely fail against existing protections for parental discretion and cultural-religious continuity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Alessandro Massa", "Nelson Mandela", "Martha Nussbaum"], "organizations": ["Council of Europe", "Bundestag", "American Academy of Pediatrics"], "themes": ["Ritual Male Circumcision", "European Convention on Human Rights", "Bodily Integrity", "Freedom of Religion", "Parental Discretion", "Children''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5fdfa5f920420fabc3b0c9b447b20464744c9c0c9071781e373d6884ac53c57d', 'Massey If_male_circumcised_Covenant (paper) 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5fdfa5f920420fabc3b0c9b447b20464744c9c0c9071781e373d6884ac53c57d.pdf', 'other', 'ingested', '{"date": "2016", "description": "In this essay, Alexander Massey critiques the practice and requirement of circumcision (brit milah) for infant boys and adult male converts within Progressive and Liberal Judaism in the UK. Centering the discussion around four key values\u2014covenant, community, compassion, and conscience\u2014the author challenges the necessity of physical circumcision as an obligatory sign of Jewish identity, arguing that true covenantal relationship is defined by ethical monotheism, sincere commitment, and Torah values rather than bodily alteration.\n\nMassey lays out six core objections to circumcision: the lack of informed infant consent and medical harm; the conflation of physical markers with authentic spiritual covenant; the distinct physical and psychological trauma imposed on adult proselytes; the injustice of demanding physical sacrifices of others; the resulting gender inequalities in Jewish ritual; and the Progressive theological principle that halachah (law) and minhag (custom) must bend to ethical reflection and modern moral conscience. The paper concludes with an appeal for Liberal Judaism to remove circumcision queries from conversion applications and fully welcome uncircumcised men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Alexander Massey", "Margaret Jacobi", "Jenny Goodman", "Daniel Halperin", "Helen Freeman", "Marcia Plumb", "Eugene Borowitz", "Elizabeth Tikvah Sarah", "Rabbi Bamberger"], "organizations": ["Liberal Judaism UK", "World Health Organization", "UNICEF", "Centers for Disease Control and Prevention", "National Institutes of Health", "Harvard School of Public Health", "Committee for Parental Choice and Religious Freedom"], "themes": ["Circumcision (Brit Milah)", "Jewish Conversion and Proselytism", "Liberal and Progressive Judaism", "Conscientious Objection", "Gender Equality in Religion", "Bodily Integrity and Informed Consent", "Halachah and Minhag Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('64ebaedfc49f7c73457016230cecaa2da64fedfbdfb7424cbf4d7882e676a21c', 'Matar Medical risks benefits JIntAssocAIDS Care2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/64ebaedfc49f7c73457016230cecaa2da64fedfbdfb7424cbf4d7882e676a21c.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This cross-sectional study investigates U.S. physicians'' perspectives on the risks and benefits of newborn male circumcision prior to the updated 2012 policy statements from the American Academy of Pediatrics (AAP) and the American Congress of Obstetricians and Gynecologists (ACOG). Based on a 2008 electronic survey of 1,500 physicians across various specialties, only 33.2% of respondents believed that the medical benefits of newborn male circumcision outweighed the risks, and only 31.1% reported that they would recommend the procedure when counseling parents.\n\nSupport for circumcision was significantly higher among family practitioners and internists compared to OB/GYNs, among male physicians compared to female physicians, and among physicians serving predominantly African American patients. The authors suggest that physician skepticism and neutral or non-recommending counseling practices may be associated with declining newborn circumcision rates in the United States, highlighting the need to assess how recent professional guidelines influence clinical counseling.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lea Matar", "Julia Zhu", "Robert T. Chen", "Deborah A. Gust"], "organizations": ["Centers for Disease Control and Prevention", "Emory University", "American Academy of Pediatrics", "American Congress of Obstetricians and Gynecologists", "American Medical Association", "Porter Novelli, Inc."], "themes": ["Newborn Male Circumcision", "Physician Attitudes and Counseling Practices", "Medical Risks and Benefits", "HIV and STI Prevention", "Pediatric Health Guidelines"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6c9f9dccbf74067320f1c1241939426a042e8e93bc72544f66bb8471e2d145bd', 'Matteoli German_Court_Circumcision (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6c9f9dccbf74067320f1c1241939426a042e8e93bc72544f66bb8471e2d145bd.pdf', 'newspaper_clipping', 'ingested', '{"date": "2012-08-07", "description": "This commentary supports a German court decision banning non-therapeutic circumcision of minors, arguing that routine infant circumcision lacks valid medical, religious, or legal standing and should be classified as a crime against humanity and child abuse. Drawing on ritual theory, ancient history, and sociological concepts, the author contends that the practice evolved through syncretism and serves as a tool of social repression and dominance rather than true religious necessity.\n\nThe document further critiques the legal status of circumcision in the United States, arguing that religious exemptions to child abuse laws and gendered distinctions regarding genital mutilation violate equal protection. It asserts that international human rights declarations and constitutional guarantees of physical intactness, such as those found in Germany''s Basic Law, morally and legally obligate states to protect children from non-consensual religious cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Richard L. Matteoli", "Catherine Bell", "Lloyd Schofield", "John Douglas"], "organizations": ["Salem-News", "Brit Shalom Society", "World Health Organization", "Federal Bureau of Investigation", "United Nations"], "themes": ["Circumcision Ban", "Child Protection and Human Rights", "Religious Rituals and Secular Law", "Equal Protection", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('27a3439c83ec87f0196d9db8c3e9c97ab9c5abe29f5cded9ebd49ac14fe90ddf', 'Maughan-Brown Cut_Above_the_Rest J AIDS 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/27a3439c83ec87f0196d9db8c3e9c97ab9c5abe29f5cded9ebd49ac14fe90ddf.pdf', 'medical_journal', 'ingested', '{"date": "2011-12-15", "description": "This study investigates the association between traditional male circumcision practices\u2014specifically foreskin removal extent and age at procedure\u2014and HIV risk among young Xhosa men in Cape Town, South Africa, using data from the Cape Area Panel Study. The authors find that while medical circumcision is widely recognized as protective against HIV, partial foreskin removal via traditional circumcision confers no risk reduction compared to remaining uncircumcised. In contrast, full foreskin removal is associated with a 7 percentage point reduction in HIV prevalence, and older age at circumcision correlates with increased HIV risk due to later timing relative to sexual debut.\n\nGiven the strong cultural adherence to traditional initiation rites over clinical procedures, the authors recommend collaborating with traditional practitioners to encourage full foreskin excision and earlier circumcision ages. Additionally, the study highlights that standard population health surveys, such as the Demographic and Health Surveys, must record procedure completeness and timing to accurately assess the epidemiology of circumcision and HIV transmission.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brendan Maughan-Brown", "Atheendar S. Venkataramani", "Nicoli Nattrass", "Jeremy Seekings", "Alan W. Whiteside"], "organizations": ["University of Cape Town", "Harvard Medical School", "Massachusetts General Hospital", "University of KwaZulu-Natal", "University of Michigan"], "themes": ["HIV/AIDS Prevention", "Traditional Male Circumcision", "Epidemiology", "Xhosa Initiation Rites", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4d6430362f012fe2c970cf71f240708f16b521fb7dcf4c15e1d882a523426f3f', 'Maxor Strength_of_Childrens_Right JApplPhilos 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4d6430362f012fe2c970cf71f240708f16b521fb7dcf4c15e1d882a523426f3f.pdf', 'other', 'ingested', '{"date": "2017", "description": "This article examines the moral strength of pre-autonomous children''s right to bodily integrity through the lens of male infant circumcision, taking as given the opponents'' claims regarding its harms. The author argues that a child''s claim against being circumcised represents a ''right-as-priority'' rather than a mere interest or a ''right-as-trump'' that categorically overrides all competing social interests. Because the expected harms are moderate rather than catastrophic, and because the procedure is typically authorized by non-negligently benevolent parents rather than malevolent actors, the associated expressive wrong is substantially reduced.\n\nConsequently, the article concludes that the debate over banning circumcision cannot be decided strictly by prioritizing bodily integrity over all other considerations. Rather, the aggregate weight of children''s rights against circumcision falls short of interest-trumping status, meaning that significant competing societal interests\u2014such as preventing the alienation and exit of religious minority groups like Jews and Muslims\u2014must be factored in and may plausibly justify permitting the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Joseph Mazor", "Ronald Dworkin", "Warren Quinn", "E. Ungar-Sargon", "J. S. Svoboda", "Reinhard Merkel", "Holm Putzke"], "organizations": ["Society for Applied Philosophy", "London School of Economics", "Nordic Ombudsmen for Children", "Hastings Center for Bioethics", "Centers for Disease Control and Prevention"], "themes": ["Bodily Integrity", "Children''s Rights", "Male Infant Circumcision", "Bioethics and Moral Philosophy", "Rights-as-Trumps", "Expressive Wrongs and Parental Benevolence", "Religious Freedom and Pluralism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('be92043873094dedd17ca7b37d0b254d71afb767e15b7041f67e03a8a7cb4e42', 'Mazor_Childs_Interests_JME (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/be92043873094dedd17ca7b37d0b254d71afb767e15b7041f67e03a8a7cb4e42.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This academic paper examines the moral permissibility of neonatal male circumcision, responding to a German court ruling that declared the practice illegal on grounds of violating a child''s rights to bodily integrity and self-determination. Author Joseph Mazor argues that absolute ''rights-as-trumps'' frameworks are misplaced in this debate. Instead, the morality of the procedure should be evaluated through a careful balancing of the child''s actual interests, including the medical risks and benefits, potential moderate reductions in future sexual pleasure, self-determination, and the significant costs of deferring circumcision to adulthood.\n\nMazor argues that in secular settings, neonatal circumcision falls within accepted parental prerogatives due to the scope of reasonable disagreement concerning medical and personal well-being. In religious contexts, particularly within Orthodox Judaism, Mazor asserts that the balance shifts decisively in favor of infant circumcision. Because boys raised in these environments overwhelmingly choose circumcision in adulthood, infant circumcision avoids the severe physical, psychological, and social costs of adult surgery while minimizing the frustration of the child''s future self-determination.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Joseph Mazor", "Ronald Dworkin", "John Stuart Mill", "David Benatar", "Michael Benatar", "Moses Maimonides"], "organizations": ["Landgericht Cologne", "German Parliament", "Pew Forum on Religion & Public Life"], "themes": ["Male Infant Circumcision", "Bodily Integrity", "Autonomy and Self-Determination", "Parental Prerogative", "Bioethics and Medical Law", "Religious Freedom and Rituals"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cfc4b3649d21544e8401b8f1fb4bdbb1c5b4d0665bb5e6821a0560539c14033d', 'McAllister Bollinger_Cost_to_Circumcise_Africa IJMH 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cfc4b3649d21544e8401b8f1fb4bdbb1c5b4d0665bb5e6821a0560539c14033d.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This study evaluates the financial cost, feasibility, and epidemiological effectiveness of implementing mass male circumcision across sub-Saharan Africa compared to condom distribution programs for HIV prevention. Expanding upon earlier localized models and incorporating updated UNAIDS data and realistic surgical complication rates, the authors estimate that circumcising all 69.9 million uncircumcised, HIV-negative adult males in the region would cost approximately $5.1 billion, plus an ongoing annual maintenance cost of $763 million.\n\nIn contrast, the authors argue that behavior change interventions and free condom distribution are substantially more viable and cost-effective. They calculate that condom usage is at least 95 times more cost-effective per HIV infection averted than circumcision and provides critical bidirectional protection to women, who account for over 60% of adults living with AIDS in sub-Saharan Africa. The paper concludes that public health funding should prioritize proven barrier methods and behavioral programs over mass surgical interventions, given the immense resource constraints and infrastructural deficits in African clinics.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ryan G. McAllister", "John W. Travis", "Dan Bollinger", "Claire Rutiser", "Veeraraghavan Sundar", "James G. Kahn"], "organizations": ["Georgetown University", "Wellness Associates", "Tott Inc.", "UNAIDS", "World Health Organization", "Men''s Studies Press, LLC"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Cost-Effectiveness Analysis", "Condom Distribution", "Public Health Policy in Sub-Saharan Africa", "Healthcare Infrastructure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2083a8d272be7fdb8c41099bb03eb78957ef730f3ea0eb568c20fc78545c6b78', 'McGrath-Young Circ in NZ Plenum 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2083a8d272be7fdb8c41099bb03eb78957ef730f3ea0eb568c20fc78545c6b78.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This paper examines the history of neonatal male circumcision in New Zealand, charting its rapid rise during and following World War II and its subsequent decline. Influenced by British medical traditions, pervasive military hygiene myths (such as the ''Sand Myth''), and a conformist colonial culture, circumcision rates among European New Zealanders soared to over 90% in the 1940s, while the indigenous Maori population historically shunned the practice.\n\nFollowing the publication of Douglas Gairdner''s 1949 study on the anatomy and development of the foreskin, medical practitioners gradually recognized the lack of scientific justification for routine circumcision and phased it out by avoiding discussion of the procedure with parents. By the late 1970s, Caucasian infant circumcision fell below 1%. The authors observe, however, that the practice persists among Pacific Island immigrant communities (such as Samoans and Tongans) due to strong cultural norms, and argue that New Zealand''s human rights and child protection laws fail to offer male infants the same legal safeguards granted against female genital mutilation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ken McGrath", "Hugh Young", "Douglas Gairdner", "Sir Frederic Truby King", "George McCall Smith", "Sir Duncan Stout"], "organizations": ["Auckland University of Technology", "Plunket Society", "New Zealand Medical Association", "Otago Medical School", "National Women''s Hospital", "National Health Service", "New Zealand Department of Health"], "themes": ["Neonatal Circumcision", "Medical History and Myths", "Social Conformity", "Pediatric Health", "Pacific Islander Cultural Practices", "Human Rights and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c528091b3549eae752a1295bbbe1a7c73e183db1fd22163f6c06698db5622f09', 'McGregor Pathol and Physio Phimosis CanFamPhys 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c528091b3549eae752a1295bbbe1a7c73e183db1fd22163f6c06698db5622f09.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This clinical review outlines the critical differences between physiologic and pathologic phimosis, addressing foreskin care and referral practices in primary care. Physiologic phimosis is a normal, non-retractile state common in children that resolves naturally over time with gentle hygiene and routine washing, requiring parental reassurance rather than intervention. In contrast, pathologic phimosis involves true scarring or disease requiring pediatric urological consultation and surgical management. Unnecessary referrals for benign physiologic phimosis inflate waitlists and provoke undue anxiety among parents and patients.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Thomas B. McGregor", "John G. Pike", "Michael P. Leonard"], "organizations": ["Children\u2019s Hospital of Eastern Ontario", "Canadian Family Physician"], "themes": ["Physiologic and Pathologic Phimosis", "Pediatric Urology", "Preputial Hygiene and Foreskin Care", "Clinical Referrals and Surgical Indications", "Patient and Parental Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf0de85254fc45b46adff490b75722208eaacba704304d3a4b7f80933ca58156', 'McLaughlin Legal Medical Ethical Entanglements JMLE 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf0de85254fc45b46adff490b75722208eaacba704304d3a4b7f80933ca58156.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article explores the legal, ethical, and medical dilemmas surrounding infant male circumcision under international human rights frameworks and domestic law. It details the historical shift in parent-child relations from viewing children as parental property to recognizing them as autonomous rights-bearers entitled to bodily integrity, self-determination, and protection under treaties such as the UN Convention on the Rights of the Child. Examining key court rulings in Germany and the United States, the author highlights an increasing judicial and ethical reluctance to permit non-therapeutic, irreversible genital surgeries on minors without their informed consent.\n\nThe author argues that the ethical and human rights objections historically raised against female genital mutilation apply equally to infant male circumcision, as both procedures inflict non-therapeutic bodily harm on non-consenting children. Furthermore, the article contends that establishing legal protections exclusively for female minors while permitting infant male circumcision violates equal protection principles under international law and the U.S. Constitution. Consequently, international legal bodies and medical practitioners are urged to oppose infant male circumcision with the same vigor directed toward female genital mutilation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul Jerome McLaughlin Jr.", "Angela Merkel"], "organizations": ["Florida A&M University College of Law", "United Nations", "American Academy of Pediatrics", "Council of Europe", "Netherlands Institute of Human Rights", "Landgericht K\u00f6ln", "Oberlandesgericht Hamm"], "themes": ["Infant Male Circumcision", "Children''s Rights and Autonomy", "Medical Ethics and Informed Consent", "International Human Rights Law", "Female Genital Mutilation Comparison", "Parental Rights versus State Protection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ac49406cc7a115c96be4919d2aa6e0d7b1285dd9336b5ed0b3fa76fb24c52037', 'McLintock Phimosis clitoral prepuce JRSM 1984.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ac49406cc7a115c96be4919d2aa6e0d7b1285dd9336b5ed0b3fa76fb24c52037.pdf', 'medical_journal', 'ingested', '{"date": "1985-03", "description": "This excerpt from the Journal of the Royal Society of Medicine compiles multiple clinical case reports across surgical subspecialties. The text concludes a discussion on managing ureteric rupture due to stone impaction via endoscopic Dormia basket extraction without open drainage, followed by a report of clitoral prepuce phimosis in a 24-year-old diabetic female successfully managed through surgical circumcision/dorsal slit, and begins a report detailing an unusual case of Meckel''s diverticulum presenting as an ileorectal fistula caused by an enterolith.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["I Cour Palais", "D G McLintock", "Michael Grant", "N A R Watt", "I H K Scott", "M P Williams"], "organizations": ["Royal Society of Medicine", "West Middlesex Hospital", "Mayday Hospital", "Addenbrooke''s Hospital", "Princess Margaret Rose Orthopaedic Hospital", "Ipswich Hospital"], "themes": ["Urology and Ureteric Rupture", "Endoscopic Stone Extraction", "Clitoral Phimosis and Female Circumcision", "Meckel''s Diverticulum and Enteroliths", "Surgical Case Reports"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3306f4e3202e4f8d879418c32ebe2eb4996ab1e953295c146734785f66946c14', 'McMath Infant circumcision and autonomy JME 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3306f4e3202e4f8d879418c32ebe2eb4996ab1e953295c146734785f66946c14.pdf', 'medical_journal', 'ingested', '{"date": "2015-02-20", "description": "This article addresses the ethical controversy surrounding routine neonatal male circumcision through the lens of child autonomy. The author analyzes two primary ethical dilemmas: whether ethicists should adopt a realist or idealist approach toward a child''s future autonomous choices, and whether the child possesses a right, an interest, or neither regarding making their own decision about circumcision.\n\nThe author argues that when considering the child''s own interests, an idealist perspective must be adopted to avoid objectionable paternalism by assuming future autonomous choices will align with their best interests; conversely, a realist approach is appropriate when assessing public health justifications involving risks to others. Furthermore, the paper posits that while the child does not possess an absolute right to delay circumcision, he has a distinct interest in autonomy to ensure choices reflect his specific values and actual interests. The author concludes that debates should place greater emphasis on public health considerations and the appropriate timing of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Akim McMath"], "organizations": ["Journal of Medical Ethics", "BMJ Publishing Group", "American Academy of Pediatrics"], "themes": ["Infant Male Circumcision", "Patient Autonomy", "Public Health Ethics", "Paternalism and Informed Consent", "Pediatric Bioethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('502114538caaeeb31b3786290dd65fc6b500c19c43b04a5e0cc7f33d5164e626', 'McQueen Circ Jewish Mother''s Dilemma Fem&Psych 1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/502114538caaeeb31b3786290dd65fc6b500c19c43b04a5e0cc7f33d5164e626.pdf', 'other', 'ingested', '{"date": "1996", "description": "The provided text contains download metadata and copyright notices from SAGE Social Science Collections rather than substantial document content. It indicates that an academic paper hosted on SAGE Journals (fap.sagepub.com) was accessed through the University of Victoria on March 1, 2016.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["SAGE Social Science Collections", "University of Victoria"], "themes": ["Academic Publishing", "Institutional Access", "Copyright and Distribution"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('97b60071c2542f7104cfb9e343c3c041f34e32f9fd308ce489ca465a4bf0ab73', 'Meddings Wisdom Genital_Autonomy RationalistSocAustral 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/97b60071c2542f7104cfb9e343c3c041f34e32f9fd308ce489ca465a4bf0ab73.pdf', 'policy_guideline', 'ingested', '{"date": "2017-02", "description": "This policy statement published by the Rationalist Society of Australia argues that non-consensual, medically unnecessary male circumcision and intersex genital modification constitute harmful practices and violate medical ethics and international human rights law. The authors assert that peak international medical bodies do not recommend routine infant circumcision, and that parental preference or religious freedom cannot ethically or legally justify inflicting permanent, non-therapeutic bodily alterations on non-consenting children.\n\nThe document calls for reforms in Australian law to eliminate sex-based discrimination by extending the existing criminal prohibitions against female genital mutilation to male and intersex children. It recommends that all non-therapeutic genital modifications be condemned as mutilation, deferred until the individual has the capacity to provide informed consent, and granted no exemptions on religious or cultural grounds.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Jonathan I. Meddings", "Travis L.C. Wisdom"], "organizations": ["Rationalist Society of Australia", "University of Adelaide", "Royal Australasian College of Physicians", "American Academy of Pediatrics", "Canadian Paediatric Society", "Royal Dutch Medical Association"], "themes": ["Genital Autonomy", "Male Circumcision", "Intersex Genital Modification", "Children''s Rights", "Medical Ethics", "Human Rights Law", "Secularism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6a7d802e274dfa2467934881a893f5b7710af658917a16dcaabd5825a0bb4f1a', 'Medicaid NC 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6a7d802e274dfa2467934881a893f5b7710af658917a16dcaabd5825a0bb4f1a.pdf', 'policy_guideline', 'ingested', '{"date": "2021-01-01", "description": "This clinical coverage policy document from NC Medicaid and NC Health Choice details the coverage criteria, billing limitations, and administrative guidelines for medically necessary male circumcision and related post-circumcision procedures. Routine, elective, or ritualistic circumcisions are explicitly not covered; coverage is limited to clinical indications such as urinary tract anomalies, severe phimosis, recurrent infections, spina bifida, and Human Immunodeficiency Virus (HIV) prophylaxis for both newborns and non-newborns.\n\nThe policy outlines procedural requirements, including the mandatory use of analgesia or anesthesia stronger than topical agents for surgical interventions, documentation obligations, and provider qualifications under North Carolina Department of Health and Human Services (DHHS) oversight. It also details billing codes, claims-related information, lifetime procedure limitations, and special provisions governing Medicaid beneficiaries under Early and Periodic Screening, Diagnostic, and Treatment (EPSDT).", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["NC Medicaid", "NC Health Choice", "North Carolina Department of Health and Human Services", "Centers for Medicare and Medicaid Services", "American Medical Association"], "themes": ["Medicaid Coverage Policy", "Medically Necessary Circumcision", "Pediatric Health", "HIV Prophylaxis", "Medical Billing and Coding", "Health Insurance Regulations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2e10907d18cd40e9020b6ba06865322cdeb3893ea9737c35325f220adcc71950', 'Meislahn-Taylor Sexual Reflexes Kluwer 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2e10907d18cd40e9020b6ba06865322cdeb3893ea9737c35325f220adcc71950.pdf', 'other', 'ingested', '{"date": "2004", "description": "This document is the title and front-matter page for the edited academic volume titled ''Flesh and Blood: Perspectives on the Problem of Circumcision in Contemporary Society.'' Edited by George C. Denniston, Frederick Mansfield Hodges, and Marilyn Fayre Milos, the work compiles multidisciplinary critiques and examinations of circumcision practices and controversies in modern society.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["George C. Denniston", "Frederick Mansfield Hodges", "Marilyn Fayre Milos"], "organizations": ["University of Washington", "Yale University", "National Organization of Circumcision Information Resource Centers", "Kluwer Academic/Plenum Publishers"], "themes": ["Circumcision", "Medical Ethics", "Contemporary Society", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f8397657c5b2d7300e6f37c1e663e12b066d1579a8654c5657687bef5552c7d', 'Men''s Confidential Circumcision Uncut 1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8f8397657c5b2d7300e6f37c1e663e12b066d1579a8654c5657687bef5552c7d.pdf', 'other', 'ingested', '{"date": "1996-03", "description": "This article from Men''s Confidential presents the results of a reader survey exploring men''s personal attitudes toward circumcision, foreskin status, and sexual function. Survey responses are broken down into categories: happily circumcised (23%), circumcised and unhappy (23%), circumcised as adults (17%), happily uncircumcised (31%), uncircumcised and unhappy (1%), and partially circumcised (5%). The varied testimonials reflect deeply personal perspectives on sexual sensitivity, ease of intercourse, hygiene, aesthetics, locker-room peer pressure, and non-surgical foreskin restoration.\n\nThe piece also reviews ''MAN HOOD,'' a commercial penile sleeve produced by R&C Associates intended to protect the glans from chafing and restore sensitivity in circumcised men, noting its potential benefits alongside practical drawbacks such as fit and retention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Men''s Confidential", "R&C Associates"], "themes": ["Circumcision", "Male Sexual Health", "Foreskin Restoration", "Penile Sensitivity", "Body Image and Peer Pressure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9f2302186f4f9f6624b87d0b4a6bfb4f856842ab7396aea9c54ccc6ca149ada9', 'Merkel Putzke After Cologne JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9f2302186f4f9f6624b87d0b4a6bfb4f856842ab7396aea9c54ccc6ca149ada9.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-22", "description": "This article critically examines the ethical and legal foundations of non-therapeutic male infant circumcision following a 2012 Cologne district court ruling that declared the practice to be criminal bodily assault. Authors Reinhard Merkel and Holm Putzke argue that non-therapeutic circumcision violates a child''s fundamental rights to bodily integrity and self-determination, noting that religious liberty and parental rights cannot legitimately justify direct, permanent physical intrusion into another person''s body without medical necessity or informed consent.\n\nThe authors evaluate and condemn the subsequent German legislative reaction, which enacted Article 1631d of the German Civil Code to explicitly legalize infant circumcision. They highlight two fundamental flaws in the statute: first, that it allows non-medical religious practitioners (mohalim) to perform surgery without the legal or practical ability to administer adequate, medically standard anaesthesia; and second, that its clause regarding ''particular purpose'' fails as a legal mechanism to filter out improper or harmful parental motives, effectively legalizing circumcision for virtually any parental reason.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Reinhard Merkel", "Holm Putzke", "Joel Feinberg", "William O. Douglas", "Yona Metzger"], "organizations": ["BMJ", "University of Hamburg", "University of Passau", "German Bundestag", "Cologne District Court (Landgericht K\u00f6ln)", "German Federal Ministry of Justice"], "themes": ["Male circumcision", "Bodily integrity", "Religious liberty", "Parental rights", "Medical ethics", "Children''s rights", "German legislation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eb797787873e05c1f0d7bc8e634aea52d55246562c9fc46581a0d480cb325c5f', 'Metaxas-Earp Voluntary FGC Clinical_ethical_and_legal ArchSexBeh 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eb797787873e05c1f0d7bc8e634aea52d55246562c9fc46581a0d480cb325c5f.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This academic paper examines the clinical, ethical, and legal dilemmas surrounding Female Genital Cosmetic Surgery (FGCS), specifically labiaplasty, through three case studies of European women who reported feeling genitally mutilated following consensual procedures. After experiencing adverse physical, aesthetic, and psychosexual outcomes, these patients sought care at an outpatient clinic at Geneva University Hospitals originally established to support migrants affected by Female Genital Mutilation/Cutting (FGM/C). All three patients also had unaddressed histories of sexual violence, highlighting the necessity of psychological screening and anatomical education prior to elective interventions.\n\nThe authors analyze the inconsistencies in international policy and criminal law, particularly the World Health Organization''s definition of FGM/C and the Swiss criminal code, which distinguish between permissible cosmetic surgery and criminal genital mutilation based on ambiguous ''non-medical reasons'' rather than consent, outcome, or harm. They argue that this framework introduces racial, cultural, and gendered double standards by criminalizing traditional African practices while functionally legalizing Western cosmetic procedures that cause identical anatomical alterations. The paper urges medical societies and legislators to adopt standardized, non-discriminatory ethical principles rooted in bodily integrity, objective consent capacity, and thorough pre-operative counseling.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Tania Metaxas", "Brian D. Earp", "Dina Bader", "Sotoudeh Ghasemi", "Milena Solari", "Jasmine Abdulcadir"], "organizations": ["Geneva University Hospitals", "University of Geneva", "National University of Singapore", "University of Oxford", "World Health Organization", "American College of Obstetricians and Gynecologists", "Royal College of Obstetricians and Gynaecologists", "American Society of Plastic Surgeons"], "themes": ["Female Genital Cosmetic Surgery (FGCS)", "Female Genital Mutilation/Cutting (FGM/C)", "Labiaplasty", "Informed Consent", "Medical Ethics", "Legal Double Standards", "Psychosexual Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1a5602261c5705a9c6c110f6ad995d2284109cc029fed8e4a6fb831bbef02d4a', 'Miani Socio Affective Processing Heliyon 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1a5602261c5705a9c6c110f6ad995d2284109cc029fed8e4a6fb831bbef02d4a.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This research study examines whether routine neonatal male circumcision is associated with long-term psychological effects on adult socio-affective processing. Evaluating a sample of 408 early-circumcised men and 211 non-circumcised men recruited via TurkPrime in the United States, the authors assessed attachment styles, personality meta-traits, empathy, trust, sociosexuality, libido, perceived stress, and sensation seeking using validated psychometric scales.\n\nThe findings indicate that early-circumcised men exhibited significantly lower attachment security, reduced emotional stability, higher perceived stress, greater sensation seeking, and less restricted sociosexuality with higher sexual drive compared to non-circumcised peers, while no significant differences were observed in empathy or trust. The authors contextualize these results within life-history theory, suggesting that extreme procedural pain and stress during the highly plastic neonatal period may induce subtle, enduring shifts in adult psychosocial functioning and stress regulation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alessandro Miani", "Gian Antonio Di Bernardo", "Astrid Ditte H\u00f8jgaard", "Brian D. Earp", "Paul J. Zak", "Anne M. Landau", "J\u00f8rgen Hoppe", "Michael Winterdahl"], "organizations": ["Aarhus University", "University of Neuch\u00e2tel", "University of Modena and Reggio Emilia", "Aalborg University Hospital", "Yale University", "Claremont Graduate University", "Elsevier"], "themes": ["Neonatal Male Circumcision", "Socio-Affective Processing", "Early Life Stress", "Attachment Style", "Emotional Stability", "Sociosexuality and Sensation Seeking"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('507294015fe45c761ff29650e1b54782807da1b6ba3d83dde8bb4354ec18e000', 'Miller Cultural-Legal Analysis Springer 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/507294015fe45c761ff29650e1b54782807da1b6ba3d83dde8bb4354ec18e000.pdf', 'legal_document', 'ingested', '{"date": "2002", "description": "This article examines the legal and cultural foundations of male neonatal circumcision in the United States, exploring why American law historically favored and accommodated the procedure despite risks and lack of infant consent. Applying a cultural-legal framework based on social polarities (such as purity and pollution, health and harm, and natural and unnatural), the author traces how late nineteenth-century physicians acted as norm entrepreneurs, transforming an uncommon practice into a ubiquitous medical prophylactic designed to manage Victorian anxieties surrounding masturbation and disease.\n\nThe document further analyzes the rise of contemporary anti-circumcision activism seeking to reverse these cultural polarities by framing the intact prepuce as healthy, natural, and protective. The author predicts that while medical circumcision rates will continue to decline toward a cultural tipping point, an outright legal ban remains unlikely due to resistance from religious communities and human rights advocates distinguishing it from female genital mutilation. Instead, anticipated legal reforms will occur at the margins through heightened informed consent standards, tort liability for complications, and strict requirements for anesthesia.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Geoffrey P. Miller", "Lewis Sayre", "Jonathan Hutchinson", "P.C. Remondino", "Paul Fleiss"], "organizations": ["American Medical Association", "American Academy of Pediatrics", "Royal College of Surgeons"], "themes": ["Male Circumcision", "Cultural-Legal Analysis", "Informed Consent", "Medical History and Norm Entrepreneurship", "Bodily Integrity and Child Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e5826a93eea382d4188dab11a5000a76b8ee7f1e87a0b929d46920e9a35ce689', 'Milos-Denniston-DeMeo_SexualMutilations-AHumanTragedy_Springer 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e5826a93eea382d4188dab11a5000a76b8ee7f1e87a0b929d46920e9a35ce689.pdf', 'other', 'ingested', '{"date": "1997", "description": "This document comprises the proceedings and introductory chapters of the Fourth International Symposium on Sexual Mutilations, published as ''Sexual Mutilations: A Human Tragedy.'' The text addresses both male and female genital cutting from human rights, anthropological, and historical medical perspectives, arguing that involuntary non-therapeutic genital cutting violates children''s bodily integrity and causes documented physiological and psychological harm.\n\nKey sections include an analysis by James DeMeo on the geographical diffusion and patriarchal cultural origins of male and female genital mutilation, alongside a historical overview by Frederick Hodges documenting the rise of involuntary routine circumcision in the United States. Hodges traces how 19th-century theories regarding childhood sexuality, masturbation hysteria, and reflex neurosis pathologized normal anatomy, and how proponents shifted medical rationales across decades\u2014from preventing epilepsy and cancer to urinary tract infections and HIV\u2014to perpetuate the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["George C. Denniston", "Marilyn Fayre Milos", "James DeMeo", "Frederick Hodges", "Ashley Montagu", "Sami Aldeeb", "Abraham L. Wolbarst"], "organizations": ["National Organization of Circumcision Information Resource Centers (NOCIRC)", "Springer Science+Business Media", "American Medical Association", "American Academy of Pediatrics", "Swiss Institute of Comparative Law"], "themes": ["Genital Mutilation and Circumcision", "Children''s Rights and Bodily Integrity", "Medicalization and Pathologization of Sexuality", "History of Medical Ethics", "Cross-Cultural Anthropology and Geography"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('71ef48bcfcb581de80af130736b90b187500e00560c3918c3d6265f2d29a9f85', 'Milos-Macris Circumcision_Medical or Human Rights Issue 1992.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/71ef48bcfcb581de80af130736b90b187500e00560c3918c3d6265f2d29a9f85.pdf', 'medical_journal', 'ingested', '{"date": "1992", "description": "This article examines neonatal male circumcision through the dual lenses of medical efficacy and human rights, arguing that the routine surgical removal of normal foreskin tissue is medically unnecessary, ethically problematic, and harmful. The authors critically deconstruct common historical and modern justifications\u2014such as hygiene, cancer prevention, and disease transmission\u2014demonstrating that conservative medical care and basic hygiene are sufficient alternatives without the surgical and psychological risks associated with circumcision.\n\nFraming bodily integrity as an inalienable human right, the article emphasizes that infants cannot provide informed consent and highlights growing international opposition to both male and female genital modifications. The authors urge healthcare providers, particularly certified nurse-midwives and the American College of Nurse-Midwives (ACNM), to reevaluate their participation in routine neonatal circumcision, adopt conscientious objection, and implement a moratorium on the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Marilyn Fayre Milos", "Donna Macris", "Douglas Gairdner", "Jacob Oster", "Benjamin Spock", "Frederick Leboyer", "Eugene Robin"], "organizations": ["American College of Nurse-Midwives", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "National Organization of Circumcision Information Resource Centers", "International Symposium on Circumcision", "British National Health Service"], "themes": ["Routine Neonatal Circumcision", "Bodily Integrity and Human Rights", "Medical Ethics and ''Do No Harm''", "Informed Consent in Infant Care", "Nurse-Midwifery Professional Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2008a41592190f2081ba41d7682d4de5ee85ce6432312df0c958638e772e6ae1', 'Milos_Dont_Be_Conned_by_Pros Journeymen 1992.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2008a41592190f2081ba41d7682d4de5ee85ce6432312df0c958638e772e6ae1.pdf', 'other', 'ingested', '{"date": "1992", "description": "In this article, Marilyn Fayre Milos argues against the practice of routine infant male circumcision, framing it as an unnecessary, painful, and harmful surgical procedure that violates basic human rights and bodily integrity. Opening with a graphic account of the physical and psychological trauma inflicted on a restrained newborn undergoing the procedure without anesthesia, the author challenges the historical and cultural justifications that have perpetuated circumcision in the United States while most other developed nations do not routinely perform it.\n\nThe article systematically analyzes and refutes widespread medical justifications\u2014termed ''myths''\u2014including claims that circumcision improves hygiene, prevents penile or cervical cancer, protects against sexually transmitted infections, prevents urinary tract infections, and simplifies penile care. Drawing on testimony and research from various physicians and human rights declarations, Milos contends that the anatomical foreskin has significant sensory and protective functions and asserts that infant circumcision constitutes non-consensual genital mutilation driven by cultural bias rather than genuine medical necessity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Marilyn Fayre Milos", "Leonard Marino", "Sydney Gellis", "Robert Leon Baker", "William Cameron", "Aaron Fink", "Eugene Robin", "Edward Wallerstein", "Rima Laibow", "Frederick Leboyer", "John Taylor", "James DeMeo"], "organizations": ["American Academy of Pediatrics", "Canadian Paediatric Society", "National Organization of Circumcision Information Centers", "United Nations", "The National Coalition of Free Men"], "themes": ["Infant Circumcision", "Bodily Integrity and Human Rights", "Medical Ethics and Informed Consent", "Psychological Trauma in Infancy", "Critique of Medical Myths"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a9c93fe9e26731e673c5d6c56eac57432dd5e90e65dfdfa6c91c6e48991b576c', 'Miruka Male Circ Gender Violence Nation 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a9c93fe9e26731e673c5d6c56eac57432dd5e90e65dfdfa6c91c6e48991b576c.pdf', 'newspaper_clipping', 'ingested', '{"date": "2025-02-23", "description": "This article highlights findings from a Kenyan study investigating the severe complications associated with traditional male circumcision, documenting 11 deaths among 129 examined patients between 2014 and 2023. Although clinical circumcision generally provides safer outcomes when administered by trained medical professionals, complications still reach approximately 18 percent when practitioners lack sufficient training.\n\nIn light of these health hazards and the permanent loss of the foreskin''s protective and sensory functions, the piece questions whether male circumcision should be re-evaluated and categorized as a form of gender-based violence (GBV).", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Dr Okumba Miruka"], "organizations": ["Nation Media Group"], "themes": ["Male Circumcision", "Gender-Based Violence", "Traditional Practices", "Public Health", "Medical Complications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3c4ca1ce120feeff58fe7fb6981b3d470d2a0d0411358496ddcd848382250d52', 'Mitchell Shared Decision JPeriEduc 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3c4ca1ce120feeff58fe7fb6981b3d470d2a0d0411358496ddcd848382250d52.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This pilot study investigates the implementation of a three-phase shared decision making (SDM) program based on the Ottawa Decision Support Framework to assist expectant parents in deciding whether to elect routine infant circumcision (RIC) for their sons. Held within childbirth education classes at an out-of-hospital birthing center, the intervention incorporated in-class education, an online decision aid tool, and personalized decision-support counseling to align clinical risks and benefits with parental personal values.\n\nThe findings indicated that participants experienced high levels of decision-making preparedness across all three phases, with the highest scores observed among parents who decided to keep their son''s penis intact. The structured educational process reduced baseline leanings toward circumcision from 84.2% to 52.6% post-counseling, demonstrating that prenatal SDM allows sufficient contemplation time and objective risk presentation to effectively empower parents facing values-sensitive medical choices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Teri M. Mitchell", "Claudia Beal", "Dora Bradley", "Barbara McAlister", "Jeff Giles", "Amy Giles"], "organizations": ["American Academy of Pediatrics", "Baylor University", "Ottawa Hospital Research Institute", "Allen Birthing Center", "World Health Organization"], "themes": ["Routine Infant Circumcision", "Shared Decision Making", "Childbirth Education", "Informed Consent", "Parental Decision Making", "Neonatal Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('064556412e8f75057b1a76abce21b2561748e433af97f56d763fef36b4578df0', 'Mohl Prepuce Restore Seekers ArchSexBeh 1981.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/064556412e8f75057b1a76abce21b2561748e433af97f56d763fef36b4578df0.pdf', 'medical_journal', 'ingested', '{"date": "1981", "description": "This academic article examines the psychiatric aspects of patients seeking prepuce (foreskin) restoration surgery, focusing on a newly identified subgroup within the homosexual community who exhibit an erotic attachment to or preoccupation with the foreskin. The authors examine four circumcised men who sought surgical reconstruction, reporting that these individuals associated their circumcised state with feelings of incompleteness, anger over lack of bodily autonomy/choice, and diminished sense of masculinity.\n\nNone of the four patients were psychotic or Jewish, and all tolerated surgical reconstruction well. Based on these observations, the authors advance preliminary etiologic hypotheses to explain this phenomenon, highlighting psychodynamic influences and the possibility of psychological imprinting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul C. Mohl", "Russel Adams", "Donald M. Greer", "Kathy A. Sheley"], "organizations": ["University of Texas Health Science Center at San Antonio", "University of Oklahoma Health Science Center", "Audie Murphy Veterans Administration Hospital", "Plenum Publishing Corporation"], "themes": ["Circumcision", "Prepuce reconstruction", "Psychiatry", "Homosexuality", "Body image and masculinity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('baa88978117818330d986b16160dc3bb4cfb6cd8652f686fee093195386974dd', 'Mohr Conundrum NurseEthics 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/baa88978117818330d986b16160dc3bb4cfb6cd8652f686fee093195386974dd.pdf', 'medical_journal', 'ingested', '{"date": "2001", "description": "This article examines the lack of legal and medical recognition of children''s bodily autonomy and decision-making rights within the United States healthcare system, contrasting this with international standards established by the 1989 UN Convention on the Rights of the Child. The authors analyze how American jurisprudence historically prioritizes parental authority and state interests over minor self-determination, presuming individuals under 18 to be legally incompetent regardless of cognitive and developmental maturity.\n\nDrawing on developmental psychology and cognitive research, particularly Piagetian concepts, the authors demonstrate that adolescents often possess the reasoning capacity required for informed consent. They argue that healthcare professionals hold an ethical and fiduciary obligation to adopt an empowerment-based practice\u2014ensuring minors are actively consulted and granted developmentally appropriate autonomy in healthcare decisions, even in the absence of explicit legal mandates.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wanda K Mohr", "Sheila Suess Kennedy", "Jean Piaget", "Benny Agrelo", "William J. Mlyniec"], "organizations": ["United Nations", "United Nations General Assembly", "UNICEF", "American Nurses Association", "Indiana University Purdue University Indianapolis", "Supreme Court of the United States"], "themes": ["Children''s Rights", "Healthcare Decision Making", "Bodily Autonomy", "Pediatric Informed Consent", "Professional Ethics and Advocacy", "UN Convention on the Rights of the Child"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c2ee17a6ebc1803056bc10d8cec58dcbe97f695e33f7c28096730432ef63fa60', 'Moldwin Nerve Distrib Prepuce AnesthAnalg1990.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c2ee17a6ebc1803056bc10d8cec58dcbe97f695e33f7c28096730432ef63fa60.pdf', 'medical_journal', 'ingested', '{"date": "1990", "description": "This study examines the histological patterns of nerve distribution and density in prepucial tissue obtained from 35 patients ranging in age from newborns to adults undergoing circumcision. The results demonstrate that prepucial tissue possesses rich peripheral innervation from birth, with a significantly higher density of nerve bundles found in ventral tissue compared to lateral and dorsal regions.\n\nBased on these findings, the authors conclude that standard dorsal penile nerve blocks alone are often insufficient to provide complete analgesia because they may spare ventral branches and contributions from the perineal nerve. To ensure maximum pain relief during neonatal circumcision, the authors advocate for the addition of a simultaneous circumferential nerve block.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R. Moldwin", "E. Valderrama"], "organizations": ["Long Island Jewish Medical Center", "Dakopatts Labs"], "themes": ["Neonatal Circumcision", "Penile Nerve Block", "Pediatric Pain Management", "Preputial Neuroanatomy", "Histochemistry"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('38dbe3b3522f229c74d83d77024818bf7db42cfd0d47f142cb9cab7fe59139ae', 'Mooney Corporeal Mentality JHumRts 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/38dbe3b3522f229c74d83d77024818bf7db42cfd0d47f142cb9cab7fe59139ae.pdf', 'other', 'ingested', '{"date": "2014-09-10", "description": "This article proposes the ''corporeal mentality,'' an interpretative convention for human rights texts that compels readers and legal practitioners to center human embodiment and the shared physical vulnerability of people. Drawing inspiration from Leibniz Lab''s interactive artwork ''The Book of Blood: Human Writes''\u2014which transcribes the Universal Declaration of Human Rights (UDHR) using donated human blood as ink\u2014the author examines how blood functions both culturally as a signifier and semiotically as an index pointing necessarily to the human body.\n\nMooney argues that modern legal interpretation often abstracts and erases the physical person, reducing individuals to bureaucratic categories or legal entities. By recognizing that all texts possess a sensory, visual, and corporeal foundation, and demonstrating this through a re-reading of Article 6 of the UDHR (''recognition everywhere as a person before the law''), she contends that human rights must acknowledge the shared, concrete bodily existence of all people\u2014including basic physical needs and vulnerability to suffering\u2014to preserve their genuinely universal validity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Annabelle Mooney", "Ernst Fischer", "Judith Butler", "Anna Grear", "Martin Howe"], "organizations": ["University of Roehampton", "United Nations", "Leibniz Lab", "Taylor & Francis Group"], "themes": ["Universal Human Rights", "Corporeal Mentality", "Embodiment and Vulnerability", "Semiotics of Blood", "Universal Declaration of Human Rights (UDHR)", "Legal Hermeneutics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a5f2bad314bc159cb2e7c136c3c92da411d57edf2831dab1cfcbf2a6e282d9d2', 'Moore Young Americans less supportive YouGov 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a5f2bad314bc159cb2e7c136c3c92da411d57edf2831dab1cfcbf2a6e282d9d2.pdf', 'other', 'ingested', '{"date": "2015-02-03", "description": "This document represents a YouGov survey report examining shifting public attitudes toward infant circumcision in the United States. The findings indicate a generational divide, with younger Americans demonstrating significantly less support for the procedure at birth compared to older cohorts.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["YouGov"], "themes": ["Circumcision", "Public Opinion", "Generational Differences", "Infant Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ecc0bc09495a828c7487f482a1a9ab9b55e1a0cfd55e5c4b8c2e4fbd764562bf', 'Mor Declining_Rates PLoSOne 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ecc0bc09495a828c7487f482a1a9ab9b55e1a0cfd55e5c4b8c2e4fbd764562bf.pdf', 'medical_journal', 'ingested', '{"date": "2007-09-12", "description": "This cross-sectional study examines trends in male circumcision among 58,598 men who attended the San Francisco municipal STD clinic between 1996 and 2005, evaluating circumcision status via clinical physical examinations and correlating findings with race, birth decade, sexual orientation, HIV, and syphilis infection. The authors found an overall circumcision prevalence of 55.7%, with rates declining sharply by approximately 33% among cohorts born after the 1960s across all racial and ethnic groups.\n\nWhile circumcision showed a modest protective effect against syphilis infection in heterosexual men without HIV, no significant protective benefit against HIV or syphilis was observed among gay and bisexual men, likely due to differences in transmission modes such as receptive anal intercourse. In light of rising clinical evidence worldwide demonstrating the public health and disease prevention benefits of male circumcision, the authors conclude that national health policy guidelines in the United States should be reviewed and updated to address declining circumcision rates.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Zohar Mor", "Charlotte K. Kent", "Robert P. Kohn", "Jeffrey D. Klausner", "Keymanthri Moodley"], "organizations": ["San Francisco Department of Public Health", "Emory University Rollins School of Public Health", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Sexually Transmitted Diseases (STDs)", "Public Health Policy", "Epidemiology", "Sexual Health and Disparities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d69951ef94cb9fc9998633d46c55155950e5c5b006f446997a736431149bb4cf', 'Morag Relig Trad and Corporal Punish-IntJLawPolFam 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d69951ef94cb9fc9998633d46c55155950e5c5b006f446997a736431149bb4cf.pdf', 'legal_document', 'ingested', '{"date": "2011-09-22", "description": "This comparative legal study explores how religious traditions influenced the divergent evolution of child corporal punishment laws in the United States and Israel. In the 1940s, both jurisdictions shared virtually identical common-law defences permitting parents to administer moderate corporal discipline. However, by the early 2000s, Israel completely banned corporal punishment in both criminal and tort law, whereas the United States largely preserved broad parental defences.\n\nThe author argues that this divergence is rooted in distinct religious traditions and their interaction with the state. In the United States, Protestant and Puritan traditions\u2014characterized by literal biblical interpretations, concepts of original sin, and the perceived duty to break a child''s will\u2014deeply informed early law and continue to protect corporal punishment under the modern guise of parental rights and religious freedom. In contrast, Israeli law shifted toward an absolute prohibition facilitated by Jewish hermeneutical tradition, which rejects original sin, relies on continuous value-based reinterpretations of biblical text (such as metaphoric readings of ''sparing the rod''), and utilized the 1980 Foundations of the Law statute to anchor child protection within Jewish heritage.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Tamar Morag", "Philip Greven", "Shneur Zalman Cheshin", "Simha Assaf", "Dorit Beinish", "Saviona Rotlevi", "Yitzhak Levi", "Yitzhak Kadman"], "organizations": ["The Haim Striks School of Law", "The College of Management Academic Studies", "Oxford University Press", "Supreme Court of Israel", "National Council for the Child", "Christian Coalition"], "themes": ["Corporal Punishment", "Comparative Law", "Parental Authority vs Children''s Rights", "Protestant Theology and Child Rearing", "Jewish Law and Hermeneutics", "Church and State Relations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ac3adea9ab562689eed9f173ef843fa938d7b0ba2cf8526ded62c612c99832ba', 'Moreton False Beliefs ASM 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ac3adea9ab562689eed9f173ef843fa938d7b0ba2cf8526ded62c612c99832ba.pdf', 'medical_journal', 'ingested', '{"date": "2020-04-17", "description": "This article offers a critical review of a 2018 survey study by Brian D. Earp, L. M. Sardi, and W. A. Jellison, which asserted that false beliefs predict increased circumcision satisfaction among American men. Author Stephen Moreton argues that this conclusion contradicts a substantial body of international public health literature demonstrating that accurate knowledge about male circumcision correlates with higher satisfaction and acceptance, particularly in the context of HIV prevention.\n\nMoreton contends that Earp et al.''s methodology is deeply flawed, highlighting that at least half of the ten true/false quiz items used in the survey are ambiguous, factually disputed, or irrelevant to sexual satisfaction. The paper also critiques the authors for alleged bias, selective citation, and failing to investigate whether men dissatisfied with circumcision hold misconceptions promoted by anti-circumcision activists.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stephen Moreton", "Brian D. Earp", "L. M. Sardi", "W. A. Jellison"], "organizations": ["Circ Facts", "World Health Organization", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Royal Dutch Medical Association", "Royal Australasian College of Physicians", "Canadian Pediatric Society"], "themes": ["Male Circumcision", "Circumcision Satisfaction", "HIV Prevention", "Sexual Health", "Scientific Bias and Methodology", "Public Health Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('776a15f9206274183a6d386d9fa1a7140465ed2b8aadc1efb676413b220e2ec4', 'Morgan Rape of Phallus JAMA 1965.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/776a15f9206274183a6d386d9fa1a7140465ed2b8aadc1efb676413b220e2ec4.pdf', 'medical_journal', 'ingested', '{"date": "1965", "description": "In this commentary, Dr. William Keith C. Morgan critically examines the widespread practice of routine neonatal circumcision in the United States, arguing that the standard medical, hygienic, and aesthetic justifications for it are largely unfounded. He asserts that conditions like infant phimosis are widely misunderstood and that the low incidence of penile cancer does not warrant prophylactic surgery any more than appendicitis warrants routine appendectomies, dubbing financial incentives ''chronic remunerative balanitis.''\n\nMorgan further details the physiological and protective functions of the foreskin, noting that its excision diminishes sensitivity and disrupts natural sexual mechanics. He concludes that outside of genuine religious traditions, routine non-therapeutic circumcision persists primarily due to social conformity, medical habit, and hospital culture rather than sound clinical evidence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["William Keith C. Morgan", "Alan Ross", "Nancy Mitford", "Alexander Pope"], "organizations": ["University of Maryland School of Medicine"], "themes": ["Neonatal Circumcision", "Medicalization and Social Conformity", "Surgical Indications and Ethics", "Anatomy and Sexual Function", "Cultural and Religious Rituals"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ed6ef0a727b8c211fe259eb86dd5c3c7868b78b413554aab7674c0301012ecd7', 'Morison Long-term harm FGM Gambia TropMedIntHlth 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ed6ef0a727b8c211fe259eb86dd5c3c7868b78b413554aab7674c0301012ecd7.pdf', 'medical_journal', 'ingested', '{"date": "2001-08", "description": "This academic paper evaluates the long-term reproductive health consequences of female genital cutting (FGC) based on a 1999 community survey of 1,348 women in rural Gambia. Clinical examinations and laboratory testing revealed that women who had undergone FGC (predominantly WHO Type II clitoridectomy and labia minora excision) exhibited significantly higher rates of bacterial vaginosis and herpes simplex virus 2 (HSV2), the latter indicating an increased potential risk for HIV transmission. However, other frequently cited long-term complications\u2014such as perineal damage, prolapse, infertility, painful intercourse, and vulval tumors\u2014were not significantly associated with FGC in this population.\n\nThe authors note that circumcision status was deeply correlated with ethnicity (nearly universal among Mandinka women and rare among Wollof women), complicating the separation of ethnic-specific factors from surgical outcomes. Given that many commonly attributed physical morbidities did not demonstrate significant differences between cut and uncut women, the study suggests that public health and eradication campaigns should not rely solely on health-harm arguments, but should integrate a human rights framework focusing on bodily integrity and gender equality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Linda Morison", "Caroline Scherf", "Gloria Ekpo", "Katie Paine", "Beryl West", "Rosalind Coleman", "Gijs Walraven"], "organizations": ["London School of Hygiene and Tropical Medicine", "University of Wales", "Medical Research Council Laboratories, The Gambia", "World Health Organization"], "themes": ["Female Genital Cutting (FGC)", "Reproductive Health", "Sexually Transmitted Infections", "Herpes Simplex Virus 2 (HSV2)", "Bacterial Vaginosis", "Human Rights", "Public Health Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('509b98ca6dcc41bd49f64ad679ce0112e921406db99a94e8bdfbb362c02c44a2', 'Morris B Medical_evidence_IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/509b98ca6dcc41bd49f64ad679ce0112e921406db99a94e8bdfbb362c02c44a2.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This review article by Brian J. Morris and colleagues challenges a critical review by Deacon and Muir regarding non-therapeutic male circumcision (NTMC) of infants and boys. The authors contend that Deacon and Muir relied on flawed, outdated, and low-quality studies while disregarding large-scale systematic reviews, meta-analyses, and official policy evaluations by organizations such as the CDC and AAP. They argue that infant circumcision has a low adverse event rate (0.4%) compared to higher risks associated with circumcision later in life, and that benefits significantly exceed risks.\n\nThe authors provide evidence demonstrating that early NTMC substantially reduces lifetime risks of urinary tract infections, sexually transmitted infections including HIV and HPV, penile cancer, and subsequent medical interventions. They conclude that infant circumcision provides major health and cost advantages, involves manageable pain protocols when properly administered, and represents an evidence-based preventive health measure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Stephen Moreton", "John N. Krieger", "Jeffrey D. Klausner", "Guy Cox"], "organizations": ["American Academy of Pediatrics", "Centers for Disease Control and Prevention", "University of Sydney", "University of Washington School of Medicine", "Keck School of Medicine of the University of Southern California", "CircFacts"], "themes": ["Non-therapeutic male circumcision (NTMC)", "Infant and neonatal health", "Risk-benefit analysis in healthcare", "Urinary tract infections (UTIs)", "Sexually transmitted infections and oncology prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b79f353e27ca6399498aace57d27048358ca93977448515797c921017b2d2707', 'Morris Circ Denialism Unfounded AmJPrevMed 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b79f353e27ca6399498aace57d27048358ca93977448515797c921017b2d2707.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This academic review critically evaluates arguments raised by opponents of male circumcision (MC) in developed nations, specifically addressing claims that the procedure impairs sexual function, causes high infant mortality, is economically unwarranted, and lacks preventative health value. The authors refute these assertions using empirical epidemiological and clinical evidence, demonstrating that medical circumcision is a safe, low-risk, and cost-effective intervention that provides lifelong partial protection against HIV, multiple sexually transmitted infections, and genital cancers without negatively impacting sexual sensitivity or satisfaction.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Robert C. Bailey", "Jeffrey D. Klausner", "Joya Banerjee", "Richard G. Wamai", "Jake H. Waskett", "Arleen Leibowitz", "Daniel T. Halperin", "Laurie Zoloth", "Helen A. Weiss", "Catherine A. Hankins", "Robert S. Van Howe"], "organizations": ["University of Sydney", "University of Illinois at Chicago", "University of California, San Francisco", "London School of Hygiene and Tropical Medicine", "Harvard School of Public Health", "Centers for Disease Control and Prevention", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Public Health Policy", "Sexually Transmitted Infections", "Sexual Function and Health", "Medical Ethics and Evidence-Based Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1f726f13f9f7e65c39462053cd3f0b556f77e562c50f37172922a7f96791530e', 'Morris L Circ and-mental-health CHS 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1f726f13f9f7e65c39462053cd3f0b556f77e562c50f37172922a7f96791530e.pdf', 'medical_journal', 'ingested', '{"date": "2025-01-06", "description": "This qualitative study investigates the long-term psychological and mental health impacts of medically unnecessary, non-consensual childhood penile circumcision on adult men. Through interpretative phenomenological analysis of interviews with five UK men, the paper identifies three super-ordinate themes: disenfranchised grief resulting from a societal taboo and lack of validation; relational injuries termed ''spiritual divorce'' characterized by fractured trust toward mothers, doctors, and intimate partners; and enduring trauma from bodily alteration, shame, and feelings of belonging to an alienated out-group.\n\nThe author argues that circumcision-related distress represents a chronic form of disenfranchised grief and trauma that is frequently dismissed or ridiculed by society and healthcare providers. The paper offers therapeutic recommendations for mental health practitioners, advocating for empathetic validation, attachment-based therapies, and dual-process grief models to support affected individuals in processing grief, addressing intimacy issues, and rebuilding agency and self-worth.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Leeanne Morris", "Brian Earp", "James Vernon"], "organizations": ["Staffordshire University", "Taylor & Francis Group", "15 Square"], "themes": ["Male Circumcision", "Disenfranchised Grief", "Mental Health and Trauma", "Attachment Disruption", "Bodily Autonomy", "Psychotherapeutic Interventions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('15a8e39705e6adf3fcc21d5e6823873515c5c632d54011460668e5eda086c85a', 'Morris R 1985 London First Circ Lawsuit-Morris (1989 Symposium).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/15a8e39705e6adf3fcc21d5e6823873515c5c632d54011460668e5eda086c85a.pdf', 'legal_document', 'ingested', '{"date": "1989-03-01", "description": "This document, authored by attorney Richard W. Morris and presented at the First International Symposium on Circumcision in 1989, details the legal history of the Adam London case, recognized as the first lawsuit to challenge infant circumcision. The suit was brought against the physician Dr. Mark Glasser and the Permanente Medical Group on several grounds, including battery, child abuse, and infliction of pain. After the lower courts dismissed most claims and granted summary judgment based on parental consent, the core legal question was appealed: whether parents possess the legal authority to consent to an irreversible surgical procedure that serves no therapeutic or medical purpose.\n\nMorris outlines the arguments presented before the California Court of Appeal and the California Supreme Court, asserting that parental autonomy is not absolute and should be constrained strictly to medical ''treatment'' necessary to remedy an injury or disease. Despite citing precedents from other jurisdictions regarding organ donations by minors, the California appellate courts held that parents have broad discretion to consent to surgical procedures regardless of purpose, and the California Supreme Court subsequently declined review without comment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Richard W. Morris", "Adam London", "Mark Glasser"], "organizations": ["Permanente Medical Group", "California Superior Court (Marin County)", "California Court of Appeal", "Supreme Court of California", "The First International Symposium on Circumcision"], "themes": ["Infant Circumcision", "Parental Consent", "Medical Necessity", "Bodily Integrity", "Children''s Rights", "Assault and Battery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('65a95cb83d647b4b68b6d4078446feb2ff524458ca0f49e503b676cd844f8c52', 'Moxon Only_MGM is Control NewMaleStudies 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/65a95cb83d647b4b68b6d4078446feb2ff524458ca0f49e503b676cd844f8c52.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic paper investigates the evolutionary and social functions of male and female genital modification (MGMo and FGMo). The author argues that while both procedures proximally reduce genital sensitivity and decrease the inclination for extra-pair copulation, their distal evolutionary functions diverge significantly. MGMo originated as an intrasexual imposition by dominant older males onto younger males to reduce their competitiveness for fertile young females within a male dominance hierarchy.\n\nIn contrast, the author argues that FGMo is not an instrument of patriarchal ''male control,'' but rather a female intrasexual competitive strategy. Operated, organized, and upheld almost exclusively by women within systems of arranged marriage, FGMo acts as an ''honest signal'' of future fidelity used to attract and secure high-status, high-genetic-quality male pair-bond partners. The paper contends that alpha males do not benefit from FGMo due to decreased female sexual responsiveness, concluding that contemporary anti-FGM and circumcision discourses frequently rely on ideological misconceptions rather than biological and evolutionary evidence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Steve Moxon", "Germaine Greer", "C. G. Wilson", "Roy F. Baumeister", "W. C. Mackey", "B. S. Immerman"], "organizations": ["Australian Institute of Male Health and Studies", "World Health Organization", "UNFPA", "UNICEF", "British Association of Urological Surgeons"], "themes": ["Evolutionary Biology and Human Mating", "Male Genital Modification (MGMo)", "Female Genital Modification (FGMo)", "Intrasexual Competition", "Dominance Hierarchies", "Pair-Bonding and Fidelity", "Critique of Male Control Theory"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('19e10dc922f67f23c02a77722066ea22cb7a58196d883d32524a9c3198434f3c', 'Möller Male female genital cutting best interest OxfJLegStud2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/19e10dc922f67f23c02a77722066ea22cb7a58196d883d32524a9c3198434f3c.pdf', 'other', 'ingested', '{"date": "2020-06-26", "description": "This article analyzes the legal discrepancy in the United Kingdom regarding genital cutting, wherein female genital cutting (FGM) is categorically banned and criminalized, while male genital cutting remains legally permissible under parental consent or the judicial ''best interest of the child'' balancing test. The author examines common justifications used by courts and commentators to defend this distinction\u2014including differences in physical harm, purported medical benefits, religious motivations, and patriarchal power dynamics\u2014and concludes that none provide a coherent or sustainable basis for treating the two practices differently under the law.\n\nTo resolve this incoherence, the author argues that non-consensual, medically unnecessary genital cutting of children is intrinsically wrong as a matter of principle, deriving from a child''s fundamental right to physical integrity and personal freedom. Because parents should not possess the authority to permanently alter their child''s intimate body parts for non-therapeutic or cultural benefits, the author asserts that the law must abandon the balancing approach and treat both male and female genital cutting as categorically impermissible.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kai M\u00f6ller", "James Munby", "Brenda Hale", "Nicholas Wall", "Brian D. Earp", "Joel Feinberg"], "organizations": ["London School of Economics and Political Science", "Oxford University Press", "World Health Organization", "National Health Service", "UNICEF"], "themes": ["Male Genital Cutting", "Female Genital Mutilation (FGM)", "Bodily Integrity", "Best Interest of the Child", "Children''s Rights", "Human Rights Law", "Parental Authority"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dfe3d7b3bd0cc1e3b2b5e72eeb6194315346dfe2f999f2393bfbda4d0b4b1637', 'Möller Ritual and Parental Authority LawSocEcon 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dfe3d7b3bd0cc1e3b2b5e72eeb6194315346dfe2f999f2393bfbda4d0b4b1637.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic paper examines the legal and philosophical boundaries of parental authority regarding ritual male circumcision. Prompted by a 2012 Cologne District Court ruling, the author critiques the standard ''best interest'' test for prioritizing general well-being over personal autonomy and failing to respect children as future autonomous individuals. Instead, the author advocates for an ''autonomy conception'' of parental authority, arguing that parents must raise children in a manner that preserves their ability to independently accept or reject religious and ethical traditions later in life.\n\nBecause ritual circumcision permanently and irreversibly alters a child''s body without their informed consent, the paper concludes it constitutes a human rights violation that lies outside the scope of legitimate parental authority. The author addresses various objections\u2014including comparisons to psychological harm, ear piercing, and medically indicated alterations\u2014maintaining that profound physical sacrifices tied to religious identity can only be legitimately authorized by the individuals themselves once they reach adulthood.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kai M\u00f6ller", "Ronald Dworkin", "David Benatar", "Michael Benatar", "Joel Feinberg", "John Eekelaar"], "organizations": ["London School of Economics and Political Science", "Social Sciences Research Network", "District Court of Cologne", "Bundestag", "British Medical Association"], "themes": ["Ritual Male Circumcision", "Parental Authority", "Children''s Rights", "Personal Autonomy", "Religious Freedom and Ethics", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('223b5798355a2afd2314e29d7fb0f02bb5799eb355beaf5871619ed5ee0e5f74', 'Muir What is the medical evidence on circ IJIR 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/223b5798355a2afd2314e29d7fb0f02bb5799eb355beaf5871619ed5ee0e5f74.pdf', 'medical_journal', 'ingested', '{"date": "2021-11-15", "description": "This review article critically examines the medical evidence regarding non-therapeutic child circumcision (NTC), assessing its purported benefits against reported risks and complications. The authors evaluate claims concerning the prevention of phimosis, urinary tract infections (UTIs), HIV, non-HIV sexually transmitted infections, and penile and cervical cancers, determining that many claimed benefits either have high numbers needed to treat (NNT), lack relevance to non-endemic or infant populations, or are mitigated by alternative preventive measures such as HPV vaccination and safe sex practices.\n\nConversely, the procedure carries known risks of surgical complications\u2014including bleeding, meatal stenosis, infection, severe injury, and acute pain with potential neurological consequences\u2014alongside debated impacts on sexual sensitivity. The authors conclude that there is little to no high-quality medical evidence justifying non-therapeutic circumcision in healthy male infants and children. They advocate delaying the procedure until the individual reaches an age where he can comprehend the risks and benefits to provide informed consent himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Matthew Deacon", "Gordon Muir", "Nicholas Watkin"], "organizations": ["King''s College Hospital", "Springer Nature Limited", "American Academy of Pediatrics", "Centres for Disease Control and Prevention", "Royal Dutch Medical Association", "Danish Medical Association", "Canadian Paediatric Society", "World Health Organization"], "themes": ["Non-therapeutic child circumcision", "Pediatric medical ethics", "Informed consent", "Surgical complications and risks", "Disease prevention and epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1f0eca43589ba2b8d6fdd454b5adbf91885b345d95ea51dd4ab2ba0bcd452cb9', 'Muller Personal Circ Factors Influence Physicians JMH 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1f0eca43589ba2b8d6fdd454b5adbf91885b345d95ea51dd4ab2ba0bcd452cb9.pdf', 'medical_journal', 'ingested', '{"date": "2010-09-06", "description": "This study examines the factors that influence primary care physicians'' positions and counseling regarding elective newborn male circumcision in Saskatchewan, Canada. Surveying 572 physicians and residents across various specialties, the author found that while 77.1% of respondents claimed to base their recommendations on medical evidence, personal factors significantly influenced their stances. Specifically, circumcised male physicians and those with circumcised sons were overwhelmingly in favor of the procedure, while uncircumcised physicians and those with uncircumcised sons were predominantly opposed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Andries J. Muller", "Surika Julyan", "Shari McKay", "Tessa Laubscher"], "organizations": ["University of Saskatchewan", "College of Physicians and Surgeons of Saskatchewan", "Canadian Paediatric Society", "British Medical Association", "Saskatchewan Medical Association", "WPMH GmbH", "Elsevier Ireland Ltd."], "themes": ["Neonatal Circumcision", "Physician Decision-Making", "Medical Evidence vs Personal Bias", "Pediatric Ethics", "Men''s Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('efe41532b5901523f6dc4b9dcd23fd9298439c4ac06365b406726c6c2d13f69f', 'Munby Case of BandG LeedsFamCourt 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/efe41532b5901523f6dc4b9dcd23fd9298439c4ac06365b406726c6c2d13f69f.pdf', 'legal_document', 'ingested', '{"date": "2015-01-14", "description": "In care proceedings initiated by Leeds City Council regarding two young children, B and G, the Family Court addressed whether the female infant, G, had been subjected to Female Genital Mutilation (FGM Type IV) and whether this established threshold under section 31 of the Children Act 1989. After a detailed evaluation of contradictory medical expert evidence, Sir James Munby accepted the testimony of Professor Sarah Creighton and rejected the inconsistent and unreliable assessments of Dr Alison Share and Dr Comfort Momoh, concluding that the local authority failed to establish that G had been subjected to or was at risk of FGM.\n\nThe judgment also evaluated the broader legal principles surrounding FGM in family law, determining that any form of FGM constitutes ''significant harm'' that can never be justified as reasonable parenting. Sir James drew a legal comparison between FGM and non-therapeutic male circumcision, noting that while both cause physical harm, family law and societal standards continue to accommodate male circumcision for religious and cultural reasons while maintaining zero tolerance for FGM. Additionally, the court outlined recommendations for future cases, urging better training for medical professionals and the standardized use of WHO classifications and colposcope examinations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Sir James Munby", "Dr Alison Share", "Dr Comfort Momoh", "Professor Sarah Creighton", "John Hayes QC", "John Myers", "Nkumbe Ekaney QC", "Victoria Wilson"], "organizations": ["Family Court", "Leeds City Council", "World Health Organization", "UNICEF", "University College London Hospital", "Guy''s and St Thomas NHS Foundation Trust", "St James''s University Hospital"], "themes": ["Female Genital Mutilation (FGM)", "Child Protection and Care Proceedings", "Children Act 1989 Threshold Criteria", "Expert Medical Witness Reliability", "Male Circumcision versus FGM Legal Distinction", "Pediatric Gynaecological Examination Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0123adb2375e7debcf6ee394cbed55454ca0adbb7a46f2b3e354e8b2586818e0', 'Munzer Examine_Nontherapeutic_Circ HealthMatrix 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0123adb2375e7debcf6ee394cbed55454ca0adbb7a46f2b3e354e8b2586818e0.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "In this article published in Health Matrix: The Journal of Law-Medicine, legal scholar Stephen R. Munzer examines the ethical, political, and legal dimensions of nontherapeutic neonatal and male minor circumcision. Munzer argues that male minors possess an anticipatory moral right-in-trust to bodily integrity and autonomy not to be circumcised without a medical indication. His position is developed through three direct philosophical arguments: the irreversible loss of nonrenewable functional tissue, the heightened social and personal salience of the genitals, and the limitations on parental authority to permanently alter a child''s body. He additionally introduces an indirect argument grounded in gender equality, comparing male circumcision to mild, rare forms of female genital cutting.\n\nThe article also critically assesses asserted medical benefits of neonatal circumcision, evaluating analyses from institutions like the Mayo Clinic and the American Academy of Pediatrics concerning reduced risks of urinary tract infections, STDs, penile cancer, and cervical cancer in partners. Munzer concludes that these asserted prophylactic benefits are largely modest, manageable through conservative alternatives, and insufficient to override a child''s anticipatory rights. Nevertheless, while maintaining that nontherapeutic circumcision is difficult to justify morally, Munzer concludes that state legal intervention, criminalization, or civil penalties remain ill-advised under current social, religious, and multicultural conditions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stephen R. Munzer", "Joel Feinberg", "Claudia Mills", "Susan Moller Okin", "Shaye J. D. Cohen", "Erik P. Castle", "Xavier Castellsagu\u00e9"], "organizations": ["Case Western Reserve University School of Law", "UCLA School of Law", "Mayo Clinic", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "American Cancer Society", "World Health Organization"], "themes": ["Nontherapeutic Circumcision", "Bodily Integrity", "Anticipatory Autonomy", "Parental Rights and Children''s Rights", "Bioethics and Pediatric Medicine", "Religious Freedom and Cultural Practices", "Gender Equality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('94bb0f57dfa4ed105e009ba0a786ab3d682d9d6a31ad403ae68ab2921bb30ed9', 'Musa Post_traditional_Circumcision IntJDentMed 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/94bb0f57dfa4ed105e009ba0a786ab3d682d9d6a31ad403ae68ab2921bb30ed9.pdf', 'medical_journal', 'ingested', '{"date": "2015-05-30", "description": "This medical case report describes a rare and severe complication of traditional male circumcision involving complete penile skin degloving in a five-year-old Hausa Muslim boy. Following a traditional circumcision and the application of an unknown hemostatic concoction, the patient developed acute infection, severe pain, swelling, and subsequent sloughing of the entire penile shaft skin. The medical team successfully managed the case with parenteral antibiotics, wound debridement, urinary catheterization, and a split-thickness skin graft harvested from the patient''s thigh, achieving approximately 95% graft take and complete recovery.\n\nThe authors review the literature surrounding circumcision complications and penile injuries, noting that while traditional circumcisions are widely practiced as cultural and religious rites of passage in Sub-Saharan Africa, unprofessional practices and harmful traditional applications pose severe health risks. The article stresses the need for adherence to surgical asepsis, proper surgical training, and urgent policy or cultural interventions to protect young boys from avoidable genital trauma and life-threatening complications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Muhammad Ujudud Musa", "Abdulkadir Abubakar", "Bashir Yunusa"], "organizations": ["Federal Medical Centre, Katsina State", "Aminu Kano Teaching Hospital, Kano State", "Renu Publishers"], "themes": ["Traditional Circumcision Complications", "Penile Skin Degloving", "Pediatric Urology and Reconstructive Surgery", "Split-Thickness Skin Grafting", "Public Health and Traditional Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('680c41e92cec52b2604d48888b82c8223bb535df974d98a4a4b33008311a39f0', 'Myers Earp best_age_to_circumcise_Bioethics 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/680c41e92cec52b2604d48888b82c8223bb535df974d98a4a4b33008311a39f0.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article provides a critical medical and ethical evaluation of non-voluntary neonatal male circumcision (NNMC) compared to circumcision performed later in life. The authors scrutinize common arguments asserting that neonatal circumcision is safer, simpler, cheaper, and confers a superior benefit-to-risk ratio. They present medical evidence demonstrating that claimed health benefits (such as reductions in HIV and penile cancer risks) are often small, treatable by less invasive means, or primarily relevant only after sexual debut, while early procedures carry underreported risks, surgical complications, and irreversible loss of erogenous, functional tissue.\n\nFrom an ethical standpoint, the authors contend that even granting favorable medical ratios, medically unnecessary genital cutting of non-consenting minors violates bodily integrity and autonomy. Drawing parallels to procedures like female cosmetic labiaplasty and tattooing, they conclude that absent urgent medical necessity, circumcision should be deferred until an individual attains an appropriate age of consent (typically between 14 and 18 years) to make an informed, autonomous decision about their own body.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alex Myers", "Brian D. Earp", "Brian J. Morris", "Wolfram Hartmann", "J. M. Hutson", "David Tomlinson"], "organizations": ["American Academy of Pediatrics", "Canadian Paediatric Society", "Royal Dutch Medical Association", "Royal Australasian College of Physicians", "Danish Medical Association", "World Health Organization", "Centers for Disease Control and Prevention", "PEPFAR", "Brussels Collaboration on Bodily Integrity", "Circumcision Academy of Australia"], "themes": ["Neonatal Male Circumcision", "Medical Ethics and Bodily Integrity", "Informed Consent and Minors'' Autonomy", "Risk-Benefit Analysis in Pediatric Surgery", "HIV Prevention and Public Health Policy", "Genital Autonomy and Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fc9c1b9dc113a296a2b0d1c6cda7b2c5f21aac1c6c2576063d0279523dedbd6a', 'Myers FGC in Islam&West 2015 (paper).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fc9c1b9dc113a296a2b0d1c6cda7b2c5f21aac1c6c2576063d0279523dedbd6a.pdf', 'other', 'ingested', '{"date": "2015-08-05", "description": "This seminar paper examines the complex intersections among Female Genital Cutting (FGC), Islamic jurisprudence, and Western discourse. The author argues that while FGC predates Islam and is not mentioned in the Qur''an, it remains deeply rooted in classical Islamic fiqh and contemporary religious traditions across various Sunni and Shi''i schools. Through a detailed comparative case study of Egyptian Arab and Kurdish women, the paper reviews empirical medical data showing the prevalence, anatomical variations (predominantly Type I), psychosexual impacts, and persistent traditional and religious rationales perpetuating the procedure.\n\nThe document further analyzes Western historical interactions and contemporary double standards concerning genital alterations. By evaluating controversies such as the 1996 Seattle Compromise and the American Academy of Pediatrics'' 2010 policy retraction, the author critiques Western condemnation of minor female cutting in contrast to the cultural normalization of non-therapeutic infant male circumcision. The paper concludes that ethical consistency is necessary, advocating that while non-consensual cutting of minors should be discouraged, harm-reduction strategies\u2014such as clinical medicalization and milder ceremonial alternatives\u2014are more effective than outright legal bans that drive the practice underground.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Alex Myers", "Dr. Liat Kozma", "Y\u016bsuf al-Qara\u1e0d\u0101w\u012b", "Naw\u0101l el-Sa\u02bfad\u0101w\u012b", "Ayaan Hirsi Ali", "Martha Nussbaum", "R\u00fcdiger Nehberg", "Sami Aldeeb Abu Sahlieh"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "UNICEF", "Al-Azhar University", "Target", "Equality Now"], "themes": ["Female Genital Cutting (FGC)", "Islamic Jurisprudence (Fiqh)", "Male Circumcision", "Cross-Cultural Bioethics", "Women''s Health and Rights", "Harm Reduction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('59aebbda39c3bf16f6941230f1c640ab989735504fba3f9f155964a946f2ed7b', 'Nabavizadeh Incidence Circ in US PloSOne 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/59aebbda39c3bf16f6941230f1c640ab989735504fba3f9f155964a946f2ed7b.pdf', 'medical_journal', 'ingested', '{"date": "2022-10-17", "description": "This study investigates the incidence and indications for adult circumcision among commercially insured men aged 18 to 64 in the United States between 2015 and 2018 using the IBM MarketScan Commercial Database. Analyzing 12,298 claims, researchers found a stable average incidence rate of approximately 98.2 per 100,000 person-years, with a mean patient age of 39 years. Phimosis was identified as the primary indication for surgery (52.5%), followed by routine or ritual circumcision (28.7%).\n\nThe findings reveal substantial geographic and demographic variation across the United States. The Northeast region and states such as South Dakota, Missouri, and Ohio exhibited the highest age-standardized incidence rates, whereas Western states reported lower rates. Additionally, indications differed significantly across age cohorts, with older men more frequently undergoing the procedure for phimosis. The authors emphasize that while adult circumcision remains relatively uncommon due to high neonatal circumcision rates, further research is warranted to understand the clinical, cultural, and regional factors driving these disparities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Behnam Nabavizadeh", "Kevin D. Li", "Nizar Hakam", "Nathan M. Shaw", "Michael S. Leapman", "Benjamin N. Breyer", "James Mockridge"], "organizations": ["Weill Cornell Medicine", "University of California San Francisco", "Yale University School of Medicine", "Public Library of Science", "American Academy of Pediatrics", "American Urological Association", "IBM"], "themes": ["Adult Circumcision", "Urologic Surgery", "Phimosis", "Epidemiology", "Health Insurance Claims Analysis", "Geographic Healthcare Disparities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('786db7da8da34e12cf73e5eb822730844b6d9b4b2f2bb7f34ab52fad245be6d6', 'Nagarwala FGM (Judge Friedman) 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/786db7da8da34e12cf73e5eb822730844b6d9b4b2f2bb7f34ab52fad245be6d6.pdf', 'legal_document', 'ingested', '{"date": "2019-04-10", "description": "In United States v. Nagarwala, the U.S. District Court for the Eastern District of Michigan dismissed federal female genital mutilation (FGM) charges under 18 U.S.C. \u00a7 116, declaring the federal ban unconstitutional. Senior District Judge Bernard A. Friedman held that Congress lacked authority to enact the statute under both the Necessary and Proper Clause\u2014finding no rational nexus between the statute and the International Covenant on Civil and Political Rights (ICCPR)\u2014and the Commerce Clause, reasoning that FGM constitutes local, non-economic violent criminal conduct lacking a statutory jurisdictional nexus to interstate commerce.\n\nAccompanying the judicial opinion is an April 2019 transmittal letter from Assistant Attorney General Stephen E. Boyd to Vice President Michael R. Pence. The Department of Justice formally announced it would decline to appeal the district court''s decision, citing adverse Supreme Court federalism precedents such as United States v. Morrison and United States v. Lopez. Instead, the DOJ submitted a legislative proposal urging Congress to amend 18 U.S.C. \u00a7 116 to include explicit Commerce Clause jurisdictional elements\u2014such as interstate travel, communications, and commercial transactions\u2014to establish clear constitutional authority over the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Bernard A. Friedman", "Jumana Nagarwala", "Stephen E. Boyd", "Michael R. Pence", "Fakhruddin Attar", "Farida Attar"], "organizations": ["United States District Court for the Eastern District of Michigan", "U.S. Department of Justice", "United States Senate", "Centers for Disease Control and Prevention", "Office of Management and Budget"], "themes": ["Female Genital Mutilation", "Constitutional Law", "Commerce Clause", "Federalism and State Police Powers", "Necessary and Proper Clause", "Criminal Law Jurisdiction", "Legislative Amendments"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1cf9340f21b5ad959ce9540e0649c4c8521735ac1634bbf8cf168bf114184e55', 'Naha Circ Availability in U.S. BMC Urol 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1cf9340f21b5ad959ce9540e0649c4c8521735ac1634bbf8cf168bf114184e55.pdf', 'medical_journal', 'ingested', '{"date": "2021-10-08", "description": "This study investigates the availability of neonatal circumcision across United States hospitals through a cross-sectional survey of 367 pediatric urologists and pediatric hospitalists. While 86% of represented hospitals offered neonatal circumcision, access varied significantly by region and setting; institutions in the Western United States and those situated in urban areas were significantly more likely not to offer the procedure. \n\nAmong hospitals that did not provide neonatal circumcision, the primary reasons cited included the facility not being a birth hospital, lack of insurance coverage, and low insurance reimbursement rates. Qualitative responses highlighted recurring themes around provider availability, payment barriers, and ethical debates regarding routine elective circumcisions. The authors conclude that systemic and geographic disparities affect access to neonatal circumcision, underscoring the need for structured hospital workflows and equitable insurance policies to prevent riskier, costlier post-neonatal procedures under general anesthesia.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ushasi Naha", "Hans C. Arora", "Ryan F. Walton", "Ilina Rosoklija", "Lindsay M. Skibley", "Emilie K. Johnson"], "organizations": ["Societies for Pediatric Urology", "American Academy of Pediatrics", "Ann & Robert H. Lurie Children\u2019s Hospital of Chicago", "Northwestern University Feinberg School of Medicine", "University of Illinois College of Medicine"], "themes": ["Neonatal Circumcision Access", "Healthcare Disparities", "Pediatric Urology", "Health Insurance Coverage and Reimbursement", "Geographic Variation in Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5f21dd073c03df50d8fd13b994af75e21ede6f2be334393f4a20f01fb06ffa9c', 'Nakamura FGMC Springer 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5f21dd073c03df50d8fd13b994af75e21ede6f2be334393f4a20f01fb06ffa9c.pdf', 'other', 'ingested', '{"date": "2023", "description": "This volume examines the intersection between the global anti-FGM/C (Female Genital Mutilation/Cutting) campaign''s ''zero tolerance'' policy and the diverse sociocultural realities of local communities across Africa and Asia. Contributing scholars argue that while international legal bans and eradication policies have contributed to statistical declines in some areas, rigid top-down prohibitions often fail to address deeply entrenched patriarchal norms, resulting in unintended consequences such as pushing the practice underground, shifting toward milder or alternative cutting forms, and alienating women from public healthcare systems.\n\nThrough anthropological and regional case studies in Ethiopia, Kenya, Malaysia, and Sudan, the text emphasizes the necessity of moving beyond inflexible criminalization toward localized, adaptive strategies. These include utilizing positive deviance approaches, partnering with religious and community leaders, addressing underlying socioeconomic factors like poverty and marital norms, and recognizing local diversity and agency rather than imposing monolithic Western-centric frameworks.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kyoko Nakamura", "Kaori Miyachi", "Yukio Miyawaki", "Makiko Toda", "Fran Hosken", "Nawal El Saadawi", "Rogaia Mustafa Abusharaf"], "organizations": ["World Health Organization (WHO)", "UNICEF", "United Nations Population Fund (UNFPA)", "United Nations General Assembly (UNGA)", "African Union (AU)", "Toyo University", "Kyoto Women''s University"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Zero Tolerance Policy", "Human Rights vs. Cultural Relativism", "Medicalization", "Patriarchal Norms and Gender Equality", "Adaptive Governance and Positive Deviance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d65203ae695ba924eacf94dd81a8306b0743c5d4a0c09d65bdce3244d415d175', 'Namavar Removal foreskin_remnants Prem Ejac Saudi Urol Assn 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d65203ae695ba924eacf94dd81a8306b0743c5d4a0c09d65bdce3244d415d175.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This clinical study investigates the efficacy of surgically excising residual foreskin tissue to treat premature ejaculation (PE) in 47 adult circumcised men in Iran. Noting that incomplete circumcision leaves behind erogenous and nerve-dense preputial remnants that contribute to penile hypersensitivity, the authors performed corrective excision of the sensitive remaining tissue under local anesthesia.\n\nThe procedure resulted in a statistically significant increase in mean intravaginal ejaculatory latency time (IVELT), which improved from 64.25 seconds before surgery to 731.49 seconds afterward. Over 95% of patients reported enhanced ejaculatory control alongside marked reductions in penile sensitivity and substantial improvements in overall sexual satisfaction for both themselves and their partners, indicating that foreskin remnant excision is a viable surgical intervention for select PE patients.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mohammad Reza Namavar", "Boroomand Robati"], "organizations": ["Shiraz University of Medical Sciences", "Dr. Robati Clinic"], "themes": ["Premature Ejaculation", "Adult Circumcision", "Foreskin Remnants", "Intravaginal Ejaculatory Latency Time (IVELT)", "Penile Hypersensitivity", "Sexual Health and Satisfaction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b5f63af67c8a899dc5fd289491032f55e6fd131f2b678129ebc5328c5c263cda', 'Nawaf KnowledgeParents SArabia IntJMedResProf 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b5f63af67c8a899dc5fd289491032f55e6fd131f2b678129ebc5328c5c263cda.pdf', 'medical_journal', 'ingested', '{"date": "2018-11", "description": "This cross-sectional study investigates parental knowledge and attitudes toward male circumcision among 321 parents at King Saud Hospital in Unaizah City, Saudi Arabia. The findings show near-universal acceptance of male circumcision, with 97.8% of parents considering it an absolute necessity, predominantly motivated by religious reasons (89.1%) and penile hygiene (9.0%). Most parents preferred circumcision to take place immediately after birth or within the first month.\n\nDespite the overwhelming support for the procedure, notable misconceptions were identified. Over half of the respondents (55.5%) erroneously believed that anesthesia is unnecessary during neonatal circumcision because newborns do not experience pain. Additionally, parents from lower-income backgrounds were significantly more likely to hold misconceptions regarding neonatal pain and to express concern over social ridicule from peers if their sons remained uncircumcised. The authors emphasize the necessity of targeted educational campaigns to address pain management misconceptions and improve parental awareness of the clinical and surgical aspects of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hanadi Mufakkir ALMutairi", "Abdulaziz Yousef Alturki", "Nawal Hamad Alawaji", "Thekra Fahad AlHarbi", "Mona Ali Al-Sugair", "Nawaf Faisal Almukaibil"], "organizations": ["King Saud Hospital", "Qassim University", "Imam Muhammad Ibn Saud Islamic University", "Princesses Norah Bint Abdulrahman University", "Ibn Sina Academy of Medieval Medicine & Sciences"], "themes": ["Male Circumcision", "Pediatric Health", "Parental Knowledge and Attitudes", "Neonatal Anesthesia and Pain Management", "Religious and Cultural Practices", "Socioeconomic Disparities in Health Perception"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('aac6c51bf4a2d45dfc56f7458ad67a27a04aa2ae6fa570c770bd568661c4c7b2', 'Nayan Circ HIV among men Ontario Canada J Urol 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/aac6c51bf4a2d45dfc56f7458ad67a27a04aa2ae6fa570c770bd568661c4c7b2.pdf', 'medical_journal', 'ingested', '{"date": "2021-09-02", "description": "This population-based matched cohort study investigates whether male circumcision is associated with a reduced risk of acquiring HIV among 569,950 males born in Ontario, Canada, between 1991 and 2017. While earlier randomized controlled trials conducted in Eastern and Southern Africa demonstrated that circumcision significantly reduced the risk of heterosexual HIV acquisition, the authors sought to determine whether these findings translate to a Western population with lower HIV prevalence and different transmission dynamics.\n\nAnalyzing 203,588 circumcised males and 366,362 matched uncircumcised controls, the study identified 142 incident cases of HIV and found no statistically significant difference in risk between the two groups (adjusted hazard ratio 0.98, 95% CI 0.72\u20131.35). Sensitivity analyses confirmed these findings, leading the authors to conclude that circumcision is not independently associated with decreased HIV risk in Ontario. The results support clinical guidelines emphasizing safe-sex education and counselling rather than routine circumcision for HIV prevention in similar low-prevalence Western settings.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Madhur Nayan", "Robert J. Hamilton", "David N. Juurlink", "Peter C. Austin", "Keith A. Jarvi"], "organizations": ["The Journal of Urology", "American Urological Association Education and Research, Inc.", "University of Toronto", "University Health Network", "Princess Margaret Cancer Centre", "ICES", "Mount Sinai Hospital", "Lunenfeld Tannenbaum Research Institute", "Canadian Institute for Health Information", "Ontario Ministry of Health and Long-Term Care"], "themes": ["Male Circumcision", "HIV Transmission and Prevention", "Public Health Interventions", "Epidemiology and Population Health", "Urology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f2635fd6afe9786b6bdebec0f7c5b0270b5214966384f47f3194ceea5207e976', 'Nelson Relativists on Earp KIJE 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f2635fd6afe9786b6bdebec0f7c5b0270b5214966384f47f3194ceea5207e976.pdf', 'medical_journal', 'ingested', '{"date": "2016-06", "description": "In this commentary, Jamie Lindemann Nelson examines Brian Earp''s analysis of Western discourse surrounding genital cutting practices. Nelson explores Earp''s central argument that Western condemnation of female genital cutting (FGC) exemplifies moral hypocrisy, especially given Western acceptance of routine infant male circumcision and elective cosmetic genital surgeries on minors. Earp advocates for deferring all non-therapeutic genital alterations until an individual can provide informed consent, while attempting to reframe acceptable parental decisions under a broadened standard of ''enhancement'' and the child''s best interests.\n\nWhile Nelson praises Earp for dismantling Western double standards and urging greater conceptual nuance, she expresses skepticism toward parts of his defense. In particular, she questions attempts to minimize the severity of invasive forms of cutting or to rationalize associated suffering. Furthermore, Nelson warns that framing parental permissions around cultural standards of ''enhancement'' or ''best interests'' could inadvertently legitimize harmful modifications driven by prevailing aesthetic or social prejudices rather than protecting children''s welfare.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jamie Lindemann Nelson", "Brian Earp", "Simon Blackburn", "Fuambai Ahmadu"], "organizations": ["Johns Hopkins University Press", "Kennedy Institute of Ethics", "World Health Organization", "United Nations", "Columbia University"], "themes": ["Female Genital Cutting (FGC)", "Male Circumcision", "Moral Relativism and Hypocrisy", "Bioethics and Bodily Integrity", "Informed Consent and Pediatric Ethics", "Cultural Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d2315c3f629e822129672991975c8561b15b850cf563bab936d288db7f30c942', 'Neutel Iceland Circumscribing Freedom ReligionFactor 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d2315c3f629e822129672991975c8561b15b850cf563bab936d288db7f30c942.pdf', 'other', 'ingested', '{"date": "2018-03-29", "description": "In early 2018, Icelandic Member of Parliament Silja D\u00f6gg Gunnarsd\u00f3ttir proposed legislation to criminalize non-medical infant male circumcision, framing the initiative strictly as a matter of child protection and bodily integrity rather than religious freedom. The proposal sparked widespread debate across Europe, reflecting broader cultural tensions between children''s rights advocacy and the traditional practices of Jewish and Muslim minorities amid rising anti-Semitism and Islamophobia.\n\nFeaturing commentary from legal and religious studies scholars, the piece examines the specific Northern European context driving such bans. In particular, scholar Karin Berber Neutel argues that a secularized Lutheran worldview dominates Nordic discourse, defining religion primarily as private, voluntary adult belief rather than communal, bodily practice. Because Nordic institutions frequently recognize only biomedical justifications as valid, traditional religious imperatives are often excluded from policy considerations, potentially leading to the marginalization of minority religious communities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Silja D\u00f6gg Gunnarsd\u00f3ttir", "M\u00e9adhbh McIvor", "Karin Berber Neutel", "Anne Lindboe", "Pinchas Goldschmidt"], "organizations": ["The Religion Factor", "Progressive Party", "Left-Green Movement", "Nordic Ombudsmen for Children", "University of Oslo"], "themes": ["Male Circumcision", "Religious Freedom", "Children''s Rights and Bodily Integrity", "Nordic Secularism", "Minority Rights", "Anti-Semitism and Islamophobia"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ac2b378448674bff5615686ba59e3aa8972282856127546bddc4987a44cd8aa', 'Neutel Shed_Relig_Skin ReligFrdm 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ac2b378448674bff5615686ba59e3aa8972282856127546bddc4987a44cd8aa.pdf', 'other', 'ingested', '{"date": "2017", "description": "This academic paper examines the legal and philosophical claim\u2014sparked by a 2012 Cologne District Court decision\u2014that infant male circumcision restricts a child''s future religious freedom and ability to convert. Author Karin Neutel uses an intersectional analysis to deconstruct how legal scholars view circumcision as an irreversible physical mark that limits personal autonomy. The article argues that these arguments rely on unacknowledged, mainstream cultural assumptions about gender and religion.\n\nSpecifically, the author highlights two key blind spots in the debate: first, legal commentators routinely erase gender by using neutral language that obscures the specifically male genital nature of the practice, reinforcing norms of male invulnerability. Second, the underlying legal concept of religion is heavily skewed toward an individualized, belief-centered model originating from Protestant Christian history\u2014a tradition that historically defined itself in explicit opposition to physical rituals like circumcision. Consequently, modern legal criticisms of circumcision as an impediment to belief mirror Western Christian theological frameworks rather than culturally neutral standards.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Karin Neutel", "Paul Cliteur", "Reinhard Merkel", "Holm Putzke", "Eldar Sarajlic", "Linda Woodhead", "T. Jeremy Gunn"], "organizations": ["University of Oslo", "University of Erfurt", "Max Weber Centre", "Landgericht K\u00f6ln", "World Health Organization"], "themes": ["Male Circumcision", "Religious Freedom", "Intersectionality", "Religious Conversion", "Bodily Integrity", "Gender Constructs", "Secular Law and Protestant Normativity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0ab48fc9e3a3c531eb6c14c41007cc8bb0672b090c56fa2fca629033be6aad12', 'Ngambouk Gendered_Identity_Anti_FGM ASSJ 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0ab48fc9e3a3c531eb6c14c41007cc8bb0672b090c56fa2fca629033be6aad12.pdf', 'other', 'ingested', '{"date": "2010-10-28", "description": "This ethnographic study critically examines anti-female genital cutting (FGC) activism among the Ejagham communities in Southwest Cameroon. The author contends that external and local NGO interventions framing FGC strictly as a ''harmful traditional practice'' through human rights and biomedical paradigms have produced mixed results, often alienating local populations and provoking cultural resistance. For the Ejagham, the practice is deeply intertwined with feminine personhood, aesthetic ideals, social reproduction, and community identity rather than mere adherence to static tradition.\n\nHighlighting recent dynamics surrounding the HIV/AIDS pandemic and shifting marital preferences among youth, the paper argues that effective abandonment of FGC requires abandoning pejorative top-down rhetoric. Instead, it advocates for a community-led ''Positive Deviance Approach'' paired with alternative rites of passage (''circumcision with words'') and holistic development initiatives that engage local stakeholders, address economic vulnerabilities, and honor community values.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Vitalis Pemunta Ngambouk", "Judith Butler", "Mary Douglas", "Michel Foucault", "Ellen Gruenbaum"], "organizations": ["Noble Philanthropic NGO", "World Health Organization", "UNICEF", "UNFPA", "USAID", "Equality Now", "Association for the Fight Against Female Genital Mutilation", "ABEMO"], "themes": ["Female Genital Cutting (FGC)", "Cultural Identity and Personhood", "Human Rights vs. Cultural Relativism", "Public Health and HIV/AIDS", "Positive Deviance Approach", "Gender and Body Politics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('34b0113fd8e0e1313db96f6bd54eb98f11a810d9a63e8a33dc39be07c4da2bb1', 'Niehoff Circumcision_Marker Identity JewStudQrly 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/34b0113fd8e0e1313db96f6bd54eb98f11a810d9a63e8a33dc39be07c4da2bb1.pdf', 'other', 'ingested', '{"date": "2003", "description": "This article analyzes the historical evolution of circumcision as a marker of religious and cultural identity from the Hellenistic period through Late Antiquity, examining how Gen 17:1\u201314 was interpreted by Philo of Alexandria, early Christian authors (Justin Martyr and Origen), and the rabbinic redactors of Genesis Rabbah. Philo moved the discourse away from exclusive covenantal territorialism toward a paradigm of Mosaic law, virile self-restraint (enkrateia), and the teleological perfection of creation. Early Church Fathers adapted and contested these concepts: Justin Martyr argued that circumcision was contrary to nature and a sign of divine reproach, while Origen radicalized the Pauline dichotomy by insisting exclusively on an allegorical circumcision of the heart and ridiculing Jewish literalism.\n\nIn response to these pervasive Christian polemics and the Christianization of the Roman Empire, Genesis Rabbah internalized and directly engaged with these external challenges. Rabbinic sages like Rabbi Akiva, Rabbi Ishmael, and Rabbi Hoshaya defended the physical rite by conceptualizing it as the bodily cultivation of creation and a prerequisite for priestly blamelessness. Rather than evidencing an abrupt ''parting of the ways,'' the trajectories traced demonstrate a nuanced, prolonged, and interactive exegetical dialogue wherein Christian critiques directly shaped and prompted internal rabbinic discourse and identity defense.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Maren R. Niehoff", "Philo of Alexandria", "Origen", "Justin Martyr", "Rabbi Hoshaya", "Rabbi Akiva", "Rabbi Ishmael", "Marcion of Sinope", "Paul the Apostle"], "organizations": ["Mohr Siebeck", "Alexander von Humboldt-Stiftung", "Society of Biblical Literature"], "themes": ["Circumcision and Identity", "Patristic and Rabbinic Exegesis", "Parting of the Ways", "Hellenistic Judaism", "Allegorical versus Literal Hermeneutics", "Genesis Rabbah"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8fd292d26f59a2afbbf985a721494e3e6c415f3f68d99a7c55f4674e23e1f82d', 'Norton Foreskin Molecular Politics SocStudSci 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8fd292d26f59a2afbbf985a721494e3e6c415f3f68d99a7c55f4674e23e1f82d.pdf', 'other', 'ingested', '{"date": "2017", "description": "This article examines the scientific and policy disputes surrounding claims that male circumcision reduces the risk of HIV transmission. While randomized controlled trials (RCTs) conducted in sub-Saharan Africa demonstrated a statistical reduction in female-to-male HIV acquisition, they did not identify the underlying biological mechanisms. In response, medical authorities and advocates turned to histo-immunological research on the foreskin''s cellular vulnerability\u2014specifically target cells such as Langerhans cells\u2014thereby ''molecularizing'' risk. Norton argues that by locating risk directly within normal, healthy anatomical tissue, researchers and policymakers constructed circumcision status as a categorical risk factor independent of an individual''s specific sexual behaviors or local epidemiological context.\n\nThe author contrasts policy reactions across different settings, notably comparing the American Academy of Pediatrics'' 2012 endorsement of routine neonatal circumcision with the Royal Australasian College of Physicians'' rejection of routine circumcision based on context-specific transmission patterns. Through analysis of scientific literature, policy documents, and expert interviews, the paper complicates Nikolas Rose''s thesis on the individualization of biomedical risk, showing instead how molecular explanations have been mobilized to shore up population-level categorizations and facilitate the controversial generalization of trial findings to diverse global settings.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Aaron T Norton", "Patrick Pognant", "Valiere Alcena", "Andrew Fink", "Brian Morris", "Robert Van Howe", "Richard Darby", "Robert Bailey", "Nikolas Rose"], "organizations": ["Northwestern University", "World Health Organization", "UNAIDS", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Royal Australasian College of Physicians"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Molecularization of Risk", "Evidence-Based Medicine", "Biopolitics", "RCT Generalizability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('46226cf2ddb396f205036d5a6c3b4fd9d50c9eee61d358f071642c7afd48dbce', 'Notini Earp Icelands_proposed_ban Pursuit 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/46226cf2ddb396f205036d5a6c3b4fd9d50c9eee61d358f071642c7afd48dbce.pdf', 'other', 'ingested', '{"date": "2018-04-22", "description": "This article examines Iceland''s proposed legislation criminalizing non-therapeutic male circumcision before the age of consent, which mirrors the country''s existing ban on female genital cutting. The piece analyzes the tension between two competing rights: a child''s right to bodily integrity and protection from harm versus parents'' rights to freedom of religion and autonomous decision-making.\n\nThe authors highlight that male circumcision is frequently performed for non-religious, psychosocial reasons in countries like the United States, challenging the premise that parental religious motives alone justify irreversible bodily alteration. Highlighting the ethical complications of religious exemptions and the irreversible nature of the procedure, the article concludes that decisions regarding non-therapeutic genital surgery should be deferred until the individual is old enough to provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lauren Notini", "B. D. Earp", "Silja D\u00f6gg Gunnarsd\u00f3ttir", "Akim McMath"], "organizations": ["University of Melbourne", "Melbourne Law School", "Murdoch Children\u2019s Research Institute"], "themes": ["Male Circumcision", "Children''s Rights", "Bodily Integrity", "Religious Freedom", "Bioethics", "Informed Consent", "Female Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d8f3ebd5e6e7c97e2664542e68818a0a02d2038abc0056e6752055c87c50a1ab', 'Notini Earp Should_Iceland_ban_PractEth2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d8f3ebd5e6e7c97e2664542e68818a0a02d2038abc0056e6752055c87c50a1ab.pdf', 'other', 'ingested', '{"date": "2018-04-22", "description": "This article analyzes Iceland''s proposed legislation to ban non-therapeutic male circumcision before the age of consent, evaluating the ethical and legal dimensions of extending existing female genital cutting protections to all children. Authors Lauren Notini and Brian D. Earp argue that non-therapeutic circumcision infringes upon a child''s bodily integrity and right to future self-determination, noting that temporary incapacity to consent does not grant parents the authority to sanction permanent, non-essential genital alterations.\n\nThe authors assess the balance between purported health benefits and surgical harms, concluding that international medical consensus does not support routine infant circumcision as medically justified. They address the tensions between parental religious freedoms and child welfare, maintaining that the protection of children from permanent harm supersedes parental autonomy, while warning that the Icelandic bill''s undefined use of ''health reasons'' could create problematic legal loopholes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lauren Notini", "Brian D. Earp", "Silja D\u00f6gg Gunnarsd\u00f3ttir", "Akim McMath", "Robert Darby"], "organizations": ["University of Oxford", "Practical Ethics", "University of Melbourne", "Murdoch Children''s Research Institute", "The Hastings Center", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Male Circumcision", "Children''s Rights", "Bodily Integrity", "Informed Consent", "Religious Freedom", "Bioethics", "Female Genital Cutting"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf0eb97751cd682693c14717d2a4a6e04c4fe540aefa77b2018f4aa371b6d5fc', 'Ntozini Gay Xhosa men’s experiences of ulwaluko 2016 CultHlthSex.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf0eb97751cd682693c14717d2a4a6e04c4fe540aefa77b2018f4aa371b6d5fc.pdf', 'medical_journal', 'ingested', '{"date": "2016-05-27", "description": "This qualitative study investigates the experiences of nine young, openly or suspected gay Xhosa men aged 18 to 26 undergoing ulwaluko (traditional male initiation and circumcision) in the Eastern Cape, South Africa. In amaXhosa culture, the rite serves as a sacred cultural transition to manhood that implicitly assumes heterosexuality, often serving as a tool used by families and communities attempting to ''convert'' gay men into conforming to heteropatriarchal standards. Participants reported motivations ranging from cultural validation and societal pressure to wanting to actively disprove homophobic assumptions that gay men are weak or inferior.\n\nThe findings outline key strategies used by gay initiates to navigate the hostile and heteronormative environment of initiation school. While some experienced severe isolation or chose to downplay their sexuality to avoid mistreatment, others actively resisted hegemonic masculinity by refusing to learn the traditional initiation vocabulary (isikhwetha), disengaging from post-initiation socialization, or openly having a same-sex partner visit. Ultimately, the study highlights how gay men assert agency and redefine cultural manhood without relinquishing their sexual identities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Anathi Ntozini", "Hlonelwa Ngqangweni", "Ali A Abdullahi"], "organizations": ["University of Fort Hare", "Taylor & Francis", "Informa UK Limited"], "themes": ["Traditional Male Initiation (Ulwaluko)", "Hegemonic Masculinity and Heteronormativity", "Homosexuality in South Africa", "Xhosa Cultural Practices", "Identity Negotiation and Resistance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e11c3079f9479182f0a9b4db33b295fcbe8756e6b09e9972dd051b3fbf8cdd2b', 'Nuzzo-Male-Circ-Female-GM-Gender-Bias-IJHR-2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e11c3079f9479182f0a9b4db33b295fcbe8756e6b09e9972dd051b3fbf8cdd2b.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This study examines the reasons parents choose genital cutting procedures for boys and girls and analyzes the use of terminology in medical literature. Reviewing dozens of survey studies, the author finds that non-medical factors, particularly tradition and culture, predominantly drive both male circumcision and female genital cutting. Furthermore, a bibliometric analysis of PubMed literature reveals a stark linguistic disparity: female procedures are predominantly labeled with value-laden terms like ''genital mutilation'' (61.7%), whereas male procedures are almost exclusively referred to via clinical nomenclature as ''circumcision'' (99.4%). The author argues that this asymmetry reflects a gender bias in medical ethics concerning bodily integrity and points to a broader ''male empathy gap'' in public health discourses.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["James L. Nuzzo"], "organizations": ["Edith Cowan University", "United Nations International Children''s Emergency Fund", "World Health Organization", "American Academy of Family Physicians", "American Medical Association", "American College of Obstetricians and Gynecologists", "Australian Medical Association", "Royal Australian and New Zealand College of Obstetricians and Gynaecologists", "Taylor & Francis Group"], "themes": ["Circumcision", "Female Genital Mutilation", "Gender Bias", "Medical Ethics", "Medical Nomenclature", "Bodily Integrity", "Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ec4cf71a09306b16b6253da3b0b5d784c1f8c319f1e0d43822d94b2a5869b038', 'OBG Mgmt Circ Fees 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ec4cf71a09306b16b6253da3b0b5d784c1f8c319f1e0d43822d94b2a5869b038.pdf', 'medical_journal', 'ingested', '{"date": "1994-10", "description": "This document contains two distinct sections from an obstetrics and gynecology medical publication. The left section provides a prescribing information summary and warnings for the nonsteroidal anti-inflammatory drug Anaprox/Anaprox DS (naproxen sodium), detailing risks of gastrointestinal toxicity, renal impairment, drug interactions, contraindications, and adverse reactions. The right section presents survey findings regarding circumcision practices among Ob/Gyns, noting fee structures, low anesthesia utilization rates (particularly among younger practitioners), and reports that over 80-90% of delivered male infants undergo circumcision in the first month of life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["Syntex Puerto Rico, Inc.", "OBG Management"], "themes": ["NSAID Risks and Prescribing Guidelines", "Gastrointestinal and Renal Toxicity", "Infant Circumcision Practices", "Anesthesia Utilization in Minor Procedures", "Obstetrics and Gynecology Survey Data"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('409798410f2697d58c94f94355bc44e1a7734e8e4ef031720e0e4c1479184def', 'OBG Mgmt Circ Reimb How 1993.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/409798410f2697d58c94f94355bc44e1a7734e8e4ef031720e0e4c1479184def.pdf', 'medical_journal', 'ingested', '{"date": "1993-10-01", "description": "This reimbursement advisory column provides guidance for obstetric and gynecologic practices on proper procedure coding and billing to ensure accurate reimbursement. It addresses specific questions regarding the unbundling of fractional curettage, the appropriate ICD-9 and CPT codes for routine versus medically necessary infant circumcision, and billing under the child''s rather than the mother''s ID to prevent sex-edit denials. Additionally, it clarifies that CPT code 56356 applies to endometrial ablation regardless of the electrode method used, and provides recommendations on reporting antepartum visits outside of global obstetrical packages.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["Medicaid", "St. Anthony Publishing"], "themes": ["Medical Billing and Coding", "Healthcare Reimbursement", "Obstetrics and Gynecology", "CPT and ICD-9 Coding", "Insurance Claim Processing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('941dbcd87ff339be016f5f64a8eb3d072b797d21d2021753ba87593b80252ff2', 'Odour Death by Circ Parent Consent 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/941dbcd87ff339be016f5f64a8eb3d072b797d21d2021753ba87593b80252ff2.pdf', 'legal_document', 'ingested', '{"date": "2023", "description": "This legal research paper examines the legal and ethical boundaries of parental consent concerning elective pediatric surgeries, specifically routine, non-therapeutic male circumcision in Kenya. The author argues that while the law vests parents with proxy decision-making authority due to a child''s legal incapacity, this authority is strictly limited to medically necessary treatments that serve the best interests of the child. Drawing on domestic statutes such as the Children Act and the Health Act, comparative Commonwealth jurisprudence, and cases of parental neglect and child abuse, the author contends that parental rights must not override a child''s fundamental right to life, health, and bodily integrity.\n\nAnalyzing surgical classifications and medical definitions from organizations like the World Health Organization, the paper asserts that routine male circumcision is an elective, non-therapeutic surgery that carries severe risks of complications and death without addressing an existing medical condition. Consequently, the author recommends that parliament enact legislation circumscribing parental consent to strictly therapeutic interventions, thereby deferring non-essential circumcision until the individual attains the age of majority and can personally exercise informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Alphonce Odhiambo Oduor", "Ibrahim Kirwa Maina", "Mariah Walton", "Kaylea Titford", "Sebastian Kalinowski", "Dan Bollinger", "Lord Donaldson"], "organizations": ["Law Society of Kenya", "East African Law Society", "World Health Organization", "Brussels Collaboration on Bodily Integrity", "American Academy of Family Physicians", "Ministry of Labour and Social Protection of Kenya"], "themes": ["Parental Consent Limits", "Routine Male Circumcision", "Children''s Rights", "Bodily Integrity", "Medical Ethics and Law", "Best Interests of the Child"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fc2aa1eca61ab84b820028c4a7c1fb2237a28171b5fd68236cc7af4e726dc99c', 'Okonofua Assoc between FGC Nigeria IntJObGyn 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fc2aa1eca61ab84b820028c4a7c1fb2237a28171b5fd68236cc7af4e726dc99c.pdf', 'medical_journal', 'ingested', '{"date": "2002", "description": "This cross-sectional study examines the relationship between female genital cutting (FGC) and sexual and gynaecological morbidity among 1,836 premenopausal women in Edo State, Nigeria. Through clinical examinations and structured surveys, the authors found no significant differences between cut and uncut women regarding sexual frequency, arousal, or ability to reach orgasm, though cut women more often reported the breasts as their most sensitive bodily area compared to uncut women who predominantly reported the clitoris.\n\nThe findings challenge traditional assertions that FGC reduces female promiscuity or prevents adverse sexual outcomes. In contrast to these cultural justifications, cut women were 1.25 times more likely to get pregnant at a given age and had significantly higher risks of reporting gynaecological complications and symptoms of reproductive tract infections, such as lower abdominal pain, abnormal vaginal discharge, and genital ulcers.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["F.E. Okonofua", "U. Larsen", "F. Oronsaye", "R.C. Snow", "T.E. Slanger"], "organizations": ["Women''s Health and Action Research Center", "Karolinska Institute", "Harvard School of Public Health", "University of Heidelberg", "University of Benin Teaching Hospital", "Central Hospital in Benin City", "Otibhor Okhae Specialist Hospital", "World Health Organization", "Ford Foundation"], "themes": ["Female Genital Cutting", "Reproductive Health", "Gynaecological Morbidity", "Sexuality and Orgasm", "Reproductive Tract Infections", "Public Health and Advocacy in Nigeria"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ffdde9dd9e8c2358109224bc2837e198a06ed110b061f1a276183ff03a7be6ba', 'Opsomer Vaginoplasty Uncirc PRS J 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ffdde9dd9e8c2358109224bc2837e198a06ed110b061f1a276183ff03a7be6ba.pdf', 'medical_journal', 'ingested', '{"date": "2018-11-01", "description": "This study evaluates a single-stage penile inversion vaginoplasty technique designed to construct both a clitoral hood and labia minora in transwomen, utilizing prepuce skin in uncircumcised patients or distal penile shaft skin in circumcised patients. Reviewing a cohort of 161 patients treated between 2014 and 2016 at Ghent University Hospital, the authors demonstrated that the technique successfully creates aesthetically satisfying and anatomically realistic external genitalia across both patient groups with an average follow-up of over 29 months.\n\nThe findings show low complication and revision rates, with an early revision rate of 4.3 percent primarily for hematoma drainage and a late revision rate of 5.6 percent for urethral stricture correction, alongside minor elective aesthetic touch-ups. Statistical analyses revealed no significant differences in revision risk or outcomes between circumcised and uncircumcised patients, nor any correlation with patient risk factors such as age, BMI, smoking, or duration of hormone replacement therapy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dries Opsomer", "Katherine M. Gast", "Lisa Ramaut", "Edward De Wolf", "Karel Claes", "Casper Sommeling", "Stan Monstrey"], "organizations": ["American Society of Plastic Surgeons", "University of Ghent", "University of Wisconsin School of Medicine and Public Health", "Bimetra Clinical Research Center Ghent", "World Professional Association for Transgender Health"], "themes": ["Gender-Affirming Surgery", "Penile Inversion Vaginoplasty", "Vulvoplasty and Labia Minoraplasty", "Surgical Outcomes in Circumcised vs. Uncircumcised Patients", "Transgender Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('55a2d51847942c4b737619d5eef9914ed840327bcb1646c704c51b9b8d90d086', 'Orsola ConservTx Phimosis PedUrol 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/55a2d51847942c4b737619d5eef9914ed840327bcb1646c704c51b9b8d90d086.pdf', 'medical_journal', 'ingested', '{"date": "2000", "description": "This prospective clinical study evaluates the efficacy and safety of conservative treatment for childhood phimosis using topical corticosteroid application. Conducted between 1997 and 1998, 137 boys with primary or secondary phimosis were treated with 0.05% betamethasone cream twice daily for four weeks combined with gentle foreskin retraction. At the six-month follow-up, 90% of patients achieved an easily retractable prepuce without a phimotic ring, showing no significant differences in success rates across age groups, phimosis severity, or whether the condition was primary or secondary.\n\nThe authors conclude that topical steroid therapy offers a safe, simple, cost-effective, and viable alternative to surgical circumcision. Treatment was well tolerated without local or systemic adverse effects. The findings highlight that long-term success heavily depends on sustained parental compliance and regular preputial hygiene habits following initial medical treatment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Anna Orsola", "Jorge Caffaratti", "Jose Maria Garat"], "organizations": ["Fundacio Puigvert", "Children''s Hospital, Harvard Medical School", "Elsevier Science Inc."], "themes": ["Pediatric Urology", "Phimosis Treatment", "Topical Corticosteroids", "Circumcision Alternatives", "Preputial Hygiene"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9017d24a352eaa5d190bc1de181e1138ee1cda9022e7f83c52103a9753f56e12', 'Osserman Real Circ of Heart JCRT 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9017d24a352eaa5d190bc1de181e1138ee1cda9022e7f83c52103a9753f56e12.pdf', 'other', 'ingested', '{"date": "2017", "description": "This article analyzes the divergent philosophical and theological interpretations of Saint Paul by Alain Badiou and Daniel Boyarin, using Paul''s stance on circumcision as the primary focal point. While Badiou views Paul''s indifference to circumcision as an emancipatory event of subtractive universalism that breaks free from communitarian particularism, Boyarin interprets it as a Platonic, supersessionist move that devalues the bodily, historical specificity of Judaism and inaugurates the ''Jewish Question.''\n\nDrawing on Lacanian psychoanalytic concepts of sexuation, author Jordan Osserman proposes a potential synthesis between the two perspectives. He argues that both Badiou''s anti-communitarian universalism and the Rabbinic defense of bodily circumcision can be theorized as ''feminine'' modes of collectivity that confront castration and lack, rather than ''masculine'' paradigms rooted in identitarian exclusion and territorial mastery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jordan Osserman", "Alain Badiou", "Daniel Boyarin", "Saint Paul", "Jacques Lacan", "Philo of Alexandria", "Sigmund Freud"], "organizations": ["University College London", "Journal for Cultural and Religious Theory"], "themes": ["Pauline Theology", "Universalism vs. Particularism", "Circumcision", "Rabbinic Judaism", "Lacanian Psychoanalysis", "Philosophy of Religion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('faac106c913c4b418e93ca4b9fbc254c30a6c9a0f4d29ef63be8269bd2207845', 'Oster Further Fate of the Foreskin ArchDisChild 1968.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/faac106c913c4b418e93ca4b9fbc254c30a6c9a0f4d29ef63be8269bd2207845.pdf', 'medical_journal', 'ingested', '{"date": "1968", "description": "This longitudinal pediatric study analyzes 9,545 examinations of 1,968 Danish schoolboys aged 6 to 17 conducted between 1957 and 1965 to determine the natural developmental trajectory of the prepuce. The author finds that physiological phimosis and preputial adhesions are benign, normal developmental stages that resolve spontaneously over time, with phimosis decreasing from 8% in 6-7-year-olds to 1% in 16-17-year-olds, and adhesions diminishing from 63% to 3% over the same period.\n\nThe study concludes that surgical intervention or circumcision is rarely warranted and that forceful or premature retraction by parents or physicians may cause tissue injury and iatrogenic secondary phimosis. Furthermore, smegma production typically commences around ages 12\u201313 and presents no health concerns when accompanied by routine hygiene education.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jakob Oster", "Douglas Gairdner", "Sir James Spence"], "organizations": ["Department of Paediatrics, Central Hospital, Randers"], "themes": ["Pediatric Urology", "Preputial Development", "Phimosis", "Circumcision", "Smegma and Genital Hygiene"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('acc6174ea9a441ae546d86ad88307e02df4b1ed1f8f097a9a00266ece02b9249', 'Owings Trends in Circumcision 1979-2010 - CDC 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/acc6174ea9a441ae546d86ad88307e02df4b1ed1f8f097a9a00266ece02b9249.pdf', 'medical_journal', 'ingested', '{"date": "2013-08", "description": "This statistical report examines trends in male newborn circumcisions performed during birth hospitalizations in the United States from 1979 through 2010 using data from the National Hospital Discharge Survey (NHDS). Over this 32-year period, the national circumcision rate experienced an overall decline of 10%, decreasing from 64.5% in 1979 to 58.3% in 2010, with peak rates observed in 1981 (64.9%) and a low in 2007 (55.4%). The report highlights that these national fluctuations coincided with shifting policy statements from the American Academy of Pediatrics regarding routine infant circumcision.\n\nRegional analyses revealed distinctly different patterns across the four U.S. census regions. The Northeast remained relatively stable, while the Midwest and South generally tracked the national pattern of decline, increase, and subsequent decline. In sharp contrast, the West experienced a substantial 37% decrease in newborn hospital circumcision rates, dropping from 63.9% in 1979 to 40.2% in 2010, largely driven by steep declines in the 1980s.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maria Owings", "Sayeedha Uddin", "Sonja Williams"], "organizations": ["Centers for Disease Control and Prevention", "National Center for Health Statistics", "Division of Health Care Statistics", "American Academy of Pediatrics", "Agency for Healthcare Research and Quality", "SDI Health"], "themes": ["Male Newborn Circumcision", "Hospital Discharge Statistics", "Pediatric Health Policy", "Regional Health Disparities", "Healthcare Trends and Utilization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c0ef9e03ae262817adb6572d6eba0c78614b363c6877481b9926d851c01846cd', 'Oyefara FGM_sexual funcion AfrPopStud 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c0ef9e03ae262817adb6572d6eba0c78614b363c6877481b9926d851c01846cd.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study examines the relationship between Female Genital Mutilation (FGM) and the sexual functioning of married women in the Oworonshoki community of Lagos State, Nigeria. Utilizing a cross-sectional survey of 350 ever-married women, the research evaluates three primary domains: sexual desire and initiation, sexual activity, and sexual satisfaction. The findings reveal that FGM severely impairs female sexual health and well-being, with circumcised women reporting significantly higher rates of sexual dysfunction, pain during intercourse, fear of sexual intimacy, and marital sexual coercion compared to their uncircumcised peers.\n\nFurthermore, the study highlights that circumcised women experience substantial difficulty achieving orgasm and overall sexual fulfillment, frequently engaging in sexual intercourse solely for childbearing purposes. Based on these findings, the author calls for multi-dimensional, bottom-up intervention programs involving healthcare workers, educators, and traditional community leaders to eradicate the practice of FGM and restore women''s reproductive and sexual rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["John Lekan Oyefara"], "organizations": ["University of Lagos", "National Population Commission", "United Nations General Assembly", "UNAIDS", "World Health Organization"], "themes": ["Female Genital Mutilation (FGM)", "Female Sexual Functioning", "Reproductive Health", "Gender-Based Violence", "Marital Relations"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cb6ef51cd4fc38b6f8ad5d1aa510e4db09593897f842e4cafb8d2f75573f3905', 'Paakkanen Entitled empowered MC-FC IJHR 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cb6ef51cd4fc38b6f8ad5d1aa510e4db09593897f842e4cafb8d2f75573f3905.pdf', 'other', 'ingested', '{"date": "2019-05-16", "description": "This academic article examines the divergent international and domestic human rights discourses surrounding non-therapeutic genital modifications: infant male circumcision (or male genital cutting), female genital cutting/mutilation (FGC/FGM), and female genital cosmetic surgery. The author argues that disparities in how these procedures are regulated and perceived cannot be explained solely by physical severity or health outcomes. Instead, they stem from deeply rooted gendered and heteronormative structures, along with Western cultural biases, that view men as public actors whose bodily integrity can be compromised for cultural or religious preservation, while framing non-Western women universally as victims lacking agency.\n\nDrawing upon feminist legal theory and Michel Foucault''s concept of biopower, the paper illustrates how male genital cutting is largely medicalized and accepted, female genital cosmetic surgery in the West is celebrated as an autonomous choice, and non-Western female genital cutting is strictly condemned as a human rights violation regardless of age, severity, or consent. The author concludes that while strict human rights protections shield women and girls from severe harm, they simultaneously reinforce paternalistic stereotypes and leave the bodily integrity of infant males unprotected under the guise of cultural and religious accommodation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["E. Katariina Paakkanen", "Michel Foucault", "Dianne Otto", "Angela Merkel"], "organizations": ["University of Helsinki", "World Health Organization", "United Nations General Assembly", "Council of Europe", "European Court of Human Rights", "Supreme Court of Finland", "Regional Court of Cologne", "UNICEF", "UNFPA"], "themes": ["Human Rights", "Male Genital Cutting and Circumcision", "Female Genital Mutilation (FGM/FGC)", "Genital Cosmetic Surgery", "Gender and Heteronormative Structures", "Feminist Legal Theory", "Foucault''s Biopower", "Children''s Rights vs. Parental Freedom of Religion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7f7ce531bd3239c1892520fb20437c357cc3c49f5bc3a8d70155ccade2e49e8d', 'Pacho Complexity_of_FGM J SocWkValEthics 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7f7ce531bd3239c1892520fb20437c357cc3c49f5bc3a8d70155ccade2e49e8d.pdf', 'other', 'ingested', '{"date": "2015", "description": "This article examines the persistence and complexity of Female Genital Mutilation/Cutting (FGM/C) in Kenya, analyzing the cultural, social, and religious dynamics that perpetuate the practice alongside recent trends such as medicalization and lowering the age of cutting. While overall national prevalence has declined, the practice remains widespread among specific ethnic communities due to entrenched beliefs regarding womanhood, marriageability, and chastity.\n\nThe author argues for the total eradication of FGM/C, demonstrating that it offers zero health benefits and inflicts severe physical and psychological trauma. Frame-working the issue around social work values, medical ethics, and universal human rights, the article firmly refutes ethical relativism, asserting that cultural traditions cannot justify practices that violate bodily integrity, individual autonomy, and human dignity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Titus Ogalo Pacho", "Immanuel Kant", "Cheryl Noble"], "organizations": ["University of Hamburg", "World Health Organization", "UNICEF", "UNFPA", "Association of Social Work Boards", "Kenya National Bureau of Statistics", "African Union", "Population Council"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Social Work Values and Ethics", "Human Rights", "Medical Ethics", "Ethical Relativism", "Public Health and Harm Reduction"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b8ec06d4e309f2e228c371dc3b6346d19e75e1f7245cedde0a62c6a8b4b27b7e', 'Pagaza Protecting_Children_against_Practices (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b8ec06d4e309f2e228c371dc3b6346d19e75e1f7245cedde0a62c6a8b4b27b7e.pdf', 'other', 'ingested', '{"date": "2013", "description": "This academic paper examines international human rights conventions and interventions aimed at eliminating female genital mutilation (FGM) among children, focusing specifically on Ethiopia as a case study. It explores the tension between collective cultural traditions and individual human rights, notably bodily integrity and the best interests of the child as enshrined in the UN Convention on the Rights of the Child and CEDAW. Despite national legislation criminalizing FGM in Ethiopia, enforcement remains weak due to deep-rooted community norms, low educational attainment, and traditional dispute resolution mechanisms.\n\nThe author also critiques the international community''s contrasting positions on female versus male genital alterations, arguing that international endorsement of infant male circumcision constitutes an inconsistent policy and sex-based bias given that both procedures permanently alter healthy tissue without child consent. The paper concludes that legal mechanisms must be coupled with transnational advocacy, grassroots community engagement, education, and women''s empowerment to effectively shift cultural norms away from prejudicial practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Alfonso Pagaza", "Peter Hoffman", "Kathryn Sikkink", "Thomas Risse"], "organizations": ["New School University", "United Nations", "UNICEF", "World Health Organization", "Office of the United Nations High Commissioner for Human Rights", "United Nations Population Fund", "Ethiopian Women Lawyers Association"], "themes": ["Female Genital Mutilation", "Children''s Rights", "Human Rights Norms", "Bodily Integrity", "Cultural Relativism vs. Universalism", "Male Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('39ef889b15a3cd04659541d9e58e3a4b8d5c82282de66f4c546c5e2275b997df', 'PAHO-WHO Promotion Sexual Health 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/39ef889b15a3cd04659541d9e58e3a4b8d5c82282de66f4c546c5e2275b997df.pdf', 'policy_guideline', 'ingested', '{"date": "2000-05-22", "description": "This document presents the proceedings and recommendations resulting from a regional consultation convened by the Pan American Health Organization (PAHO) and the World Health Organization (WHO) in collaboration with the World Association for Sexology (WAS) in May 2000. It establishes a comprehensive conceptual framework that defines sex, sexuality, sexual rights, and sexual health\u2014framing sexual health not merely as the absence of disease, but as a state of ongoing physical, psychological, and socio-cultural well-being underpinned by universal human rights. The report addresses urgent public health challenges including the HIV/AIDS pandemic, sexually transmitted infections, sexual violence, and sexual dysfunctions.\n\nTo address these challenges, the consultation outlines five strategic goals: integrating sexual health and gender equity into broader public health initiatives; delivering comprehensive, lifespan-oriented sexuality education; training and establishing standards for health professionals and sexologists; expanding access to clinical sexual health services; and advancing multidisciplinary research and evidence dissemination across the Region of the Americas.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Eusebio Rubio Aurioles", "Eli Coleman", "Esther Corona Vargas", "Rafael Maz\u00edn", "B. R. Simon Rosser", "Fernando Zacar\u00edas"], "organizations": ["Pan American Health Organization", "World Health Organization", "World Association for Sexology", "Sexuality Information and Education Council of the United States", "Spanish Agency for International Cooperation"], "themes": ["Sexual Health Promotion", "Sexual Rights as Human Rights", "Comprehensive Sexuality Education", "Gender Equity and Non-Discrimination", "HIV/AIDS and STI Prevention", "Professional Training in Sexology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5930da73e6e1edb8b15d34bfd9277c9ba7ab0b49f8dfd7c47eaea2f34af6b1bc', 'Palmer Intl Views Brazil,Italy, etc PedUrol 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5930da73e6e1edb8b15d34bfd9277c9ba7ab0b49f8dfd7c47eaea2f34af6b1bc.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This symposium issue of Dialogues in Pediatric Urology examines the multifaceted global perspectives on male circumcision across different nations, including the United States, Italy, Brazil, Israel, Japan, and India. The contributors discuss how cultural traditions, religious mandates (notably in Judaism and Islam), medical indications such as phimosis and balanoposthitis, and prophylactic benefits regarding UTIs, penile cancer, and HIV transmission influence circumcision practices worldwide.\n\nWhile neonatal circumcision remains widely practiced in the United States and is central to Jewish and Muslim religious identity, it is rarely performed routinely in European countries like Italy, or in Japan and Brazil, where medical consensus favors conservative approaches such as topical corticosteroid therapy or prepuce-sparing procedures over routine surgical removal.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Anthony A. Caldamone", "Jeffrey S. Palmer", "C.D. Anthony Herndon", "Roberto De Castro", "Lisieux Eyer de Jesus", "Jo\u00e3o L. Pippi Salle", "Yoram Mor", "Yutaro Hayashi", "Devendra K. Gupta"], "organizations": ["Society for Pediatric Urology", "American Academy of Pediatrics", "Cleveland Clinic", "University of Alabama at Birmingham", "Ospedale Maggiore of Bologna", "The Hospital for Sick Children", "Chaim Sheba Medical Centre", "Nagoya City University", "All India Institute of Medical Sciences"], "themes": ["Male Circumcision", "Pediatric Urology", "Religious and Cultural Traditions", "Phimosis and Conservative Treatment", "Preventative Medicine", "Surgical Ethics and Patient Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6e6ba29c6d32e43773c0c9bacb1b0b4cfcc6ea6b15e91b44f5747b6495f85dd2', 'Pando Male circ unwilling BuenosAires JIntAIDSSoc 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6e6ba29c6d32e43773c0c9bacb1b0b4cfcc6ea6b15e91b44f5747b6495f85dd2.pdf', 'medical_journal', 'ingested', '{"date": "2013-06-06", "description": "This cross-sectional study investigated the frequency of male circumcision, its association with sexually transmitted infections (STIs), and the willingness to undergo the procedure among 500 men who have sex with men (MSM) in Buenos Aires, Argentina. The researchers found a low circumcision rate of only 13%, with over 70% of uncircumcised men expressing unwillingness to be circumcised even if it reduced HIV transmission risk, citing reasons such as bodily aesthetics, fear of surgery, and skepticism about efficacy.\n\nWhile circumcision status was not significantly associated with overall rates of HIV, HBV, HCV, Treponema pallidum, or HPV across the entire sample, a protective effect emerged when restricted to men who did not practice receptive anal intercourse (RAI): circumcised men in this subgroup showed zero HIV cases compared to a 14.8% prevalence among uncircumcised men. Furthermore, circumcised men exhibited significantly fewer HPV types and lower frequencies of high-risk HPV genotypes, leading authors to conclude that circumcision provides partial, practice-dependent protection that would require considerable awareness and education efforts if implemented as an intervention strategy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mar\u00eda A Pando", "Ivan C Balan", "Curtis Dolezal", "Ruben Marone", "Victoria Barreda", "Alex Carballo-Dieguez", "Mar\u00eda M Avila"], "organizations": ["Instituto de Investigaciones Biom\u00e9dicas en Retrovirus y SIDA (INBIRS)", "Universidad de Buenos Aires", "Consejo Nacional de Investigaciones Cient\u00edficas y T\u00e9cnicas (CONICET)", "New York State Psychiatric Institute", "Columbia University", "Nexo Asociaci\u00f3n Civil", "National Institute of Mental Health (NIMH)", "International AIDS Society"], "themes": ["HIV Prevention", "Male Circumcision", "Men Who Have Sex with Men (MSM)", "Sexually Transmitted Infections (STIs)", "Human Papillomavirus (HPV)", "Sexual Health and Behavior"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('074d479704089767cd1338bf8ccc21046334524d476820f942e465d2ff22b3af', 'Park Penile Length CanUrolAssnJ 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/074d479704089767cd1338bf8ccc21046334524d476820f942e465d2ff22b3af.pdf', 'medical_journal', 'ingested', '{"date": "2016-09-13", "description": "This prospective study investigates the relationship between newborn male circumcision (NMC), second to fourth digit ratio, and penile length among 248 adult male patients aged 18 to 28. The findings demonstrate that flaccid penile length, second to fourth digit ratio, and age of circumcision are statistically significant predictive factors for erectile penile length, with lower digit ratios\u2014indicative of higher prenatal testosterone exposure\u2014correlating with longer penile length.\n\nFurthermore, the study found that men who underwent circumcision as newborns had significantly shorter flaccid and erectile penile lengths compared to those circumcised later in life. The authors suggest that newborn circumcision may negatively influence penile growth, proposing that these outcomes could assist physicians in counseling parents regarding the timing and potential developmental impacts of the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jong Kwan Park", "A. Ram Doo", "Joo Heung Kim", "Hyung Sub Park", "Jung Mo Do", "Hwang Choi", "Seung Chol Park", "Myung Ki Kim", "Young Beom Jeong", "Hyung Jim Kim", "Young Gon Kim", "Yu Seob Shin"], "organizations": ["Canadian Urological Association", "Chonbuk National University Medical School", "Yonsei University College of Medicine", "Severance Hospital", "Seoul National University Bundang Hospital", "Seoul National University College of Medicine", "Armed Forces Capital Hospital", "Wonkwang University School of Medicine and Hospital", "American Academy of Pediatrics"], "themes": ["Newborn Male Circumcision", "Penile Growth and Development", "Second to Fourth Digit Ratio", "Prenatal Testosterone", "Urology and Andrology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('facd97f5e86f2a5f60f04381b20790d1e8f4382fe762ddf1fe4c146779532e05', 'Payne Sensation Arousal Circ-Uncirc IntSocSexMed 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/facd97f5e86f2a5f60f04381b20790d1e8f4382fe762ddf1fe4c146779532e05.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This academic study investigates genital and nongenital sensitivity as a function of sexual arousal in 20 uncircumcised and 20 age-matched circumcised men. Using calibrated monofilaments to evaluate touch and pain thresholds on the glans penis, penile shaft, and forearm, and thermal imaging to noninvasively measure penile temperature during erotic and control films, the researchers tested long-standing assumptions that circumcision reduces penile sensation.\n\nThe findings revealed no significant differences in genital touch or pain sensitivity between circumcised and uncircumcised men, contradicting popular hypotheses. Both groups showed a decrease in tactile sensitivity and an increase in penile temperature during sexual arousal. While uncircumcised men displayed lower baseline penile temperatures and a greater temperature increase upon arousal, circumcised men exhibited higher forearm touch sensitivity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kimberley Payne", "Lea Thaler", "Tuuli Kukkonen", "Serge Carrier", "Yitzchak Binik"], "organizations": ["Riverside Professional Center", "University of Nevada", "McGill University", "McGill University Health Center", "Jewish General Hospital", "International Society for Sexual Medicine", "Canadian Institute for Health Research"], "themes": ["Male Circumcision", "Penile Somatosensory Perception", "Sexual Arousal and Physiology", "Thermal Imaging in Sexology", "Tactile and Pain Thresholds"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a4ad68667216396670b11f6ad0e6d610c8b35f806f14ed6054ef60ceba33217b', 'Peacock Male_circum HIV challenges Lancet 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a4ad68667216396670b11f6ad0e6d610c8b35f806f14ed6054ef60ceba33217b.pdf', 'medical_journal', 'ingested', '{"date": "2007-02-24", "description": "This viewpoint article examines the significant public health opportunities and implementation challenges of scaling up male circumcision as an HIV prevention strategy following randomized controlled trials in Kenya, Uganda, and South Africa that demonstrated an approximate 50% reduction in HIV acquisition risk for men. The authors outline 13 crucial considerations for policymakers and health practitioners, including public acceptability, risk communication, the integration of circumcision into comprehensive combination prevention frameworks, and the potential impact on women.\n\nThe authors also address broader sociocultural and systemic factors, warning against the stigmatization and negative stereotyping of African men, cautioning against exacerbating gender inequality, and highlighting the danger of diversion of limited health system resources. They call for multilateral support, robust clinical training, engagement with traditional practitioners and local religious leaders, and comprehensive reproductive health services to ensure that circumcision rollouts are safe, ethical, culturally appropriate, and effectively integrated with other HIV interventions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sharif R Sawires", "Shari L Dworkin", "Agn\u00e8s Fiamma", "Dean Peacock", "Greg Szekeres", "Thomas J Coates", "Brian G. Williams"], "organizations": ["National Institutes of Health", "World Health Organization", "UNAIDS", "University of California, Los Angeles", "Columbia University", "Sonke Gender Justice", "American Academy of Pediatrics", "Ford Foundation"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Global Health Policy", "Harm Reduction", "Gender Inequality", "Health Systems Capacity", "Reproductive Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('78cc586e90ad40ec768455108f1095dfe06976b9820c16233f8fe34c25bacb3c', 'Penny Autism and Circ Benefits EuroUrol 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/78cc586e90ad40ec768455108f1095dfe06976b9820c16233f8fe34c25bacb3c.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This collection of conference abstracts from European Urology Open Science covers various clinical investigations and surgical outcomes in urology. The first study evaluates 50 cases of radical nephrectomy with inferior vena cava thrombectomy for advanced renal cell carcinoma, highlighting the necessity of a multidisciplinary approach involving hepatobiliary and cardiothoracic surgery. The second abstract assesses the resource burden and low malignancy detection rate of investigating non-visible haematuria in a tertiary center, calling for revised clinical guidelines.\n\nThe remaining two studies address pediatric and adolescent urological conditions. One study indicates that circumcision significantly improves behavioral symptoms, sensory irritation, and urinary function in boys with autism spectrum disorder suffering from bothersome phimosis. The final study shows that bowel and bladder retraining with biofeedback yields markedly higher cure rates and faster recovery than traditional antibiotic/anticholinergic therapy in adolescent males with posterior urethritis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["C. O\u2019Connell", "S.S. Connolly", "C. O\u2019Mahony", "C. Dowling", "Z. Penny", "G.J. Nason", "N.F. Davis", "F. O\u2019Kelly"], "organizations": ["Mater Misericordiae University Hospital", "University Hospital Galway", "St. Vincent\u2019s University Hospital", "Beacon Hospital", "Royal College of Surgeons in Ireland"], "themes": ["Renal Cell Carcinoma and Thrombectomy", "Non-visible Haematuria Screening", "Pediatric Circumcision and Autism Spectrum Disorder", "Adolescent Posterior Urethritis", "Voiding Dysfunction and Bladder Retraining"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('126a67296225bd0ae0554066b91a42632a8df200e04bb5cd4fae64074d956e5e', 'Perez Gender_perspective_VMMC GlobPubHlth  2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/126a67296225bd0ae0554066b91a42632a8df200e04bb5cd4fae64074d956e5e.pdf', 'medical_journal', 'ingested', '{"date": "2015-03-02", "description": "This article synthesizes qualitative research on voluntary medical male circumcision (VMMC) in east and southern Africa, arguing for the critical integration of a gendered perspective in biomedical and social scientific inquiry. While VMMC was endorsed by the WHO and UNAIDS to reduce female-to-male HIV transmission, existing qualitative research has predominantly focused on acceptability and uptake among heterosexual men, frequently overlooking the perspectives of women and sexual minorities who remain disproportionately vulnerable to HIV/AIDS.\n\nThe authors highlight five central thematic areas necessitating gendered analysis: sexual disinhibition and risk compensation, social stigma toward intact men, the conceptual tensions and relationships between VMMC and female genital cutting (FGC), sociocultural and aesthetic perceptions of the foreskin, and the inclusion of men who have sex with men (MSM). The authors conclude that incorporating gender-informed qualitative frameworks is vital for designing effective pre- and post-circumcision counseling, avoiding potential increases in female vulnerability, and accurately guiding public health policy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Guillermo Mart\u00ednez P\u00e9rez", "Laura Trivi\u00f1o Dur\u00e1n", "Angel Gasch", "Nicole Desmond", "Brian Earp", "Jeffrey Edwards", "Robyn Mosdell", "Marc Biot"], "organizations": ["World Health Organization", "UNAIDS", "M\u00e9decins Sans Fronti\u00e8res", "University of Zaragoza", "Malawi Liverpool Wellcome Trust", "Liverpool School of Tropical Medicine", "Routledge", "Taylor & Francis"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV/AIDS Prevention", "Gender Perspective", "Risk Compensation", "Female Genital Cutting (FGC)", "Men Who Have Sex with Men (MSM)", "Qualitative Health Research"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0a9373d4ffa7ba1ca44084b74b2ec220cccddb6cca21935a35b7170aa2349da2', 'PHR Surgery Intersex Children Must Stop 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0a9373d4ffa7ba1ca44084b74b2ec220cccddb6cca21935a35b7170aa2349da2.pdf', 'other', 'ingested', '{"date": "2024-02-18", "description": "This document represents a publication or statement from Physicians for Human Rights (PHR) advocating against performing medically unnecessary, non-consensual surgeries on intersex infants and children. It calls for an end to cosmetic genital surgeries, emphasizing bodily autonomy and the protection of intersex individuals'' human rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Physicians for Human Rights"], "themes": ["Intersex Rights", "Medical Ethics", "Bodily Autonomy", "Pediatric Surgery", "Human Rights Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a19583fbad91276c6120da6ace1ac7d0e73fa6c8b48021cf2d6e0ca574a33769', 'Podnar BulboCavern Circ BJUInt 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a19583fbad91276c6120da6ace1ac7d0e73fa6c8b48021cf2d6e0ca574a33769.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This clinical study examines the elicitability of the penilo-cavernosus (bulbocavernosus) reflex in circumcised men, men with foreskin retraction, and uncircumcised control subjects. Testing revealed that the reflex was clinically non-elicitable in 73% of circumcised men and 64% of men with foreskin retraction, compared to only 8% of intact controls, despite normal neurophysiological elicitability and latency across all groups via electrical and electromechanical stimulation.\n\nThe findings suggest that the absence of a clinically detectable reflex in circumcised men and those with foreskin retraction results from the removal or desensitization of fine-touch mechanoreceptors in the foreskin and glans rather than neurological dysfunction. Consequently, clinicians are advised that a clinically absent penilo-cavernosus reflex in these populations has low predictive value for sacral neurogenic lesions, and neurophysiological testing should be considered before diagnosing sacral neuropathy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Simon Podnar", "David B. Vodu\u0161ek", "Dianne Jones"], "organizations": ["University Medical Centre Ljubljana", "Ministry of Science and Technology of the Republic of Slovenia", "National Ethics Committee of Slovenia", "BJU International"], "themes": ["Bulbocavernosus reflex", "Penilo-cavernosus reflex", "Circumcision", "Uro-neurophysiology", "Sacral nerve evaluation", "Penile sensation and mechanoreceptors"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5602992f95f90ddd5fdd02e7eea05121cd63adbd7ee6a99fdf9df071d42783b5', 'Pollack Identity-Gender-Power Tikkun 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5602992f95f90ddd5fdd02e7eea05121cd63adbd7ee6a99fdf9df071d42783b5.pdf', 'other', 'ingested', '{"date": "2011-06-27", "description": "Miriam Pollack critiques the ritual of male neonatal circumcision (brit milah), arguing that the practice is fundamentally driven by patriarchal power dynamics, gender hierarchy, and the subordination of maternal authority rather than genuine spiritual necessity. She details the severe physiological and psychological trauma inflicted on infants, along with the permanent reduction in male sexual sensitivity, referencing historical commentary by Philo and Maimonides as well as modern anatomical and medical research.\n\nPollack contends that equating Jewish survival and covenantal identity with infant genital cutting is inherently sexist and ethically indefensible. Drawing parallels to female genital cutting and the historical Jewish evolution away from animal sacrifice, she advocates for abolishing circumcision in favor of ''brit b\u2019lee milah'' (a covenant without cutting), emphasizing bodily integrity, genuine spiritual education, and compassionate ethics.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Miriam Pollack", "Leonard B. Glick", "Nancy Jay", "Moses Maimonides", "Eliyahu Unger-Sargon", "Karen Ericksen Paige", "Jeffrey M. Paige"], "organizations": ["Tikkun", "Literacy & Language Center", "Israeli Supreme Court"], "themes": ["Circumcision and Brit Milah", "Patriarchy and Gender Power Dynamics", "Jewish Identity and Continuity", "Infant Trauma and Bodily Integrity", "Maternal-Infant Bond", "Intactivism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('73b7d71e863ca91f3339c22feb9cc2f6b60c312c4c65ddff60622eeb2640fb9e', 'Pollack WhoNamestheSacred 2005 (paper).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/73b7d71e863ca91f3339c22feb9cc2f6b60c312c4c65ddff60622eeb2640fb9e.pdf', 'other', 'ingested', '{"date": "2005-02-25", "description": "In this conference presentation, author Miriam Pollack critically examines neonatal circumcision through personal, medical, psychological, and Jewish theological perspectives. Reflecting on the trauma of subjecting her own sons to the ritual, Pollack argues that neonatal circumcision causes profound physiological and psychosexual harm, severely blunting adult sexual sensitivity and disrupting the vital early attachment between mother and infant. She contends that the procedure violates core Judaic tenets dedicated to preserving physical integrity and sanctifying life, such as pikuah nefesh and sh''mirat haguf.\n\nPollack further critiques the rite from a feminist standpoint, framing it as an ancient patriarchal mechanism designed to disempower maternal authority and sever the protective mother-child bond. Drawing parallels to the biblical narrative of the binding of Isaac and Sarah''s subsequent erasure, she posits that circumcision historically arose to suppress women and bodily pleasure, calling on Jewish mothers and communities to reconsider the practice and reclaim the definition of what is sacred.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Miriam Pollack", "Marilyn Milos", "Robert S. Van Howe", "Erik Erikson", "Rima Laibow", "Moses Maimonides"], "organizations": ["National Organization of Circumcision Information Resource Centers (NOCIRC)", "Congress on Pre- and Perinatal Psychology", "Israeli Supreme Court"], "themes": ["Circumcision", "Jewish Ethics and Tradition", "Maternal-Infant Bonding", "Psychological Trauma", "Patriarchy and Feminism", "Sexual Anatomy and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('73efeee5ff882a00004168c059c71bdfe70d34cbf49c81d3e213f6ccd9589f25', 'Prescott Pain Pleasure TruthSeeker 1989.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/73efeee5ff882a00004168c059c71bdfe70d34cbf49c81d3e213f6ccd9589f25.pdf', 'other', 'ingested', '{"date": "1989", "description": "In this article, developmental neuropsychologist James W. Prescott argues that male circumcision and female genital mutilation are rooted in religious dogmas, cultural customs, and an anti-pleasure moral dualism rather than valid medical necessity. Inflicting severe pain on non-consenting infants and children is characterized as an act of torture violating Article 5 of the United Nations Universal Declaration of Human Rights, with Prescott challenging contemporary epidemiological defenses regarding urinary tract infections and HIV prevention.\n\nPrescott advances his Somatosensory Affectional Deprivation (SAD) theory, contending that early genital trauma fundamentally alters the developing brain by encoding pain onto neurological circuits designed for pleasure and affection. Analyzing theological sources like Moses Maimonides alongside perinatal trauma and cross-cultural data, he posits that substituting sensory pleasure with excruciating pain fosters adult violence, depression, sadomasochism, and suicide, ultimately arguing that bodily pleasure must be recognized as essential for human morality and peaceful development.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["James W. Prescott", "Fran Hosken", "William Cameron", "Thomas Wiswell", "David Levy", "Moses Maimonides", "Sherwin Wine", "Joseph Lewis"], "organizations": ["United Nations", "American Academy of Pediatrics", "University of Manitoba", "NOCIRC", "Catholic Church"], "themes": ["Male Circumcision", "Female Genital Mutilation", "Somatosensory Affectional Deprivation (SAD)", "Neuropsychology and Brain Development", "Human Rights", "Religious and Philosophical Dualism", "Pain vs. Pleasure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4bae94cf233b67d308f087bc45732133bceee0f8d737696e6e9f3bf32235baff', 'Rape definition FAQ FBI 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4bae94cf233b67d308f087bc45732133bceee0f8d737696e6e9f3bf32235baff.pdf', 'policy_guideline', 'ingested', '{"date": "2014-12-11", "description": "This document provides guidance from the Federal Bureau of Investigation (FBI) and the Police Executive Research Forum (PERF) regarding the revised definition of rape implemented in the Uniform Crime Reporting (UCR) Program effective January 1, 2013. The updated definition removes the historical limitation of forcible carnal knowledge of a female to include any non-consensual penetration of the vagina or anus with any body part or object, or oral penetration by a sex organ, thereby encompassing male victims and instances where victims cannot consent due to age, drugs, alcohol, or incapacity.\n\nThe guidance addresses practical implementation issues for law enforcement agencies, detailing how data from the Summary Reporting System and the National Incident-Based Reporting System (NIBRS) are harmonized for federal publication. It also outlines electronic reporting formats, coordination with centralized state UCR programs, and classification protocols for statutory rape and incidents reported after the policy''s effective date.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["Federal Bureau of Investigation", "Police Executive Research Forum", "Department of Justice", "Criminal Justice Information Services Division", "CJIS Advisory Policy Board", "Association of State Uniform Crime Reporting Programs"], "themes": ["Crime Statistics Reporting", "UCR Definition of Rape", "National Incident-Based Reporting System (NIBRS)", "Law Enforcement Administration", "Sexual Assault Legislation and Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9fcfcb92511c1d0f1c4109359442315c21126368a33b4b6350263f2346f4a6ca', 'Rasool Circ Role_in_Hiv_IIOABJ 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9fcfcb92511c1d0f1c4109359442315c21126368a33b4b6350263f2346f4a6ca.pdf', 'medical_journal', 'ingested', '{"date": "2011-08-19", "description": "This review evaluates the role of male circumcision (MC) as a biological intervention in reducing the risk of heterosexually acquired HIV-1 infection and other sexually transmitted diseases. Drawing on observational studies, clinical trials, and biological mechanisms, the authors highlight that circumcision removes susceptible foreskin tissue rich in HIV target cells, with randomized trials in sub-Saharan Africa demonstrating a 48% to 60% reduction in female-to-male transmission.\n\nWhile epidemiological evidence strongly supports the protective effect of male circumcision, especially in high-prevalence settings and discordant partnerships, the authors emphasize that it is not a standalone solution. Instead, voluntary medical male circumcision should be integrated alongside behavioral risk reduction, condom promotion, early diagnosis, and access to antiretroviral therapy as part of a comprehensive HIV prevention framework.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Roohi Rasool", "A. Syed Sameer", "Mushtaq A. Siddiqi", "R. C. Bailey", "B. Auvert"], "organizations": ["Sher-I-Kashmir Institute of Medical Sciences", "Institute of Integrative Omics and Applied Biotechnology", "World Health Organization", "American Academy of Pediatrics", "National Institutes of Health", "Canadian Institute for Health Research"], "themes": ["Male Circumcision", "HIV Prevention", "Sexually Transmitted Infections", "Epidemiology", "Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('02bb2a6db0e5afa75983c5b3cc7f35333e7376c5ea908b2954def40a5b6791f3', 'Rathmann Female Circumcision_ Indications Technique. GP 1959.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/02bb2a6db0e5afa75983c5b3cc7f35333e7376c5ea908b2954def40a5b6791f3.pdf', 'medical_journal', 'ingested', '{"date": "1959", "description": "This article discusses the clinical indications and surgical technique for female circumcision (preputial excision or clitoral unhooding) to treat clitoral phimosis and redundancy. The author argues that anatomic obstruction of the clitoris frequently causes anorgasmia, leading to marital distress, divorce, and psychosomatic illness, which he asserts can be resolved through surgical intervention and proper sexual education.\n\nA survey of 112 patients treated by the author over 15 years reported an approximate 87.5% success rate in achieving or improving orgasm post-surgery. The paper introduces a modified ''vise-grip'' clamp designed by the author to simplify the procedure, reduce bleeding, eliminate extensive suturing, and shorten recovery time.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["W.G. Rathmann", "Felix Bryk"], "organizations": ["Centinella Hospital", "University of Nebraska", "U.S. Marine Hospital"], "themes": ["Female Circumcision", "Sexual Dysfunction", "Psychosomatic Medicine", "Surgical Innovation", "Marital Compatibility"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3ab0046a77b55daffc025d90ebe2feb3d59f668f27778f00d9d41c40c62b3ff8', 'Raveenthian Zipper Injury PedEmerg 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3ab0046a77b55daffc025d90ebe2feb3d59f668f27778f00d9d41c40c62b3ff8.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This article presents a novel, nonsurgical technique for freeing zipper-entrapped penile foreskin in children. The method involves inserting the blade of a small flat-head screwdriver between the outer and inner faceplates of the zipper fastener and twisting it toward the median bar. This widens the gap between the faceplates, effortlessly releasing the entrapped prepuce without resorting to invasive emergency circumcision or using hazardous cutting tools such as bone cutters or hacksaws.\n\nThe procedure was evaluated in 12 pediatric patients aged 1 to 9 years, achieving successful release in all cases without complications or need for formal anesthesia. The author concludes that this technique is safe, simple, effective, and minimally traumatic, making it a valuable addition to pediatric emergency care that can even be utilized in nonhospital settings.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Venkatachalam Raveenthiran"], "organizations": ["Lippincott Williams & Wilkins", "Rajah Muthiah Medical College", "Annamalai University"], "themes": ["Penile Zipper Injury", "Pediatric Emergency Medicine", "Nonsurgical Interventions", "Foreskin Entrapment Release", "Surgical Alternatives"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('66c9d29d7a11a7552dff807f0d5953c64768c18eb9ff377783c7a30d5b2abe6f', 'Rediger-Muller Parents'' rationale CanFamPhys 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/66c9d29d7a11a7552dff807f0d5953c64768c18eb9ff377783c7a30d5b2abe6f.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This prospective survey study examines the factors that influence expectant parents'' decisions regarding elective male neonatal circumcision in Saskatoon, Saskatchewan. Although participants most frequently cited hygiene, infection or cancer prevention, and lack of medical necessity as their overt rationales, statistical analysis revealed that paternal circumcision status was the single most powerful predictor of the decision. When the expectant father was circumcised, 81.9% of couples supported elective circumcision, compared to only 14.9% when the father was uncircumcised.\n\nThe authors conclude that despite updated medical guidelines and clinical evidence regarding risks and benefits, parental choices regarding newborn circumcision continue to be predominantly driven by personal and family precedent\u2014specifically whether the child''s father is circumcised\u2014rather than independent medical literature or health policy recommendations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Chris Rediger", "Andries J. Muller"], "organizations": ["University of Saskatchewan", "Saskatoon Health Region", "Canadian Paediatric Society", "British Medical Association", "Saskatchewan Ministry of Health"], "themes": ["Elective Newborn Circumcision", "Parental Decision-Making", "Paternal Influence", "Pediatric Preventive Care", "Hygiene and Infection Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('90d755d525e8916682057d7b79edde319d40386bb3b186ee780656ad581e16e1', 'Reeves Parental regret SSM 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/90d755d525e8916682057d7b79edde319d40386bb3b186ee780656ad581e16e1.pdf', 'medical_journal', 'ingested', '{"date": "2022-07-19", "description": "This qualitative study investigates the decision-making processes of 33 parents in the United States regarding whether to circumcise their newborn sons, alongside insights from five key informants including medical providers and childbirth assistants. The authors explore how parents navigate medical evidence, ideas about hygiene and infection prevention, interactions with healthcare professionals, and past personal experiences with prior children''s procedures. \n\nThe study highlights a significant tension between parents'' experiential knowledge and the authoritative medical knowledge of physicians and guidelines, such as those from the American Academy of Pediatrics (AAP). While parents frequently seek out evidence-based information, ambiguous domestic guidelines and differing international stances often lead to doubt, leaving some parents feeling inadequately informed and raising critical questions regarding the standard and execution of informed consent for neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Karli M. Reeves", "Joanna Mishtal"], "organizations": ["University of Central Florida", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "World Health Organization", "American Medical Association"], "themes": ["Neonatal Male Circumcision", "Parental Decision-Making", "Informed Consent", "Authoritative Knowledge", "Scientific Motherhood", "Experiential Knowledge"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d659da28e0d66b5b1b188a0cce8840c2d8bc9baa1dd0b21ac070464ba6b82e6b', 'Reich Armoring-in-a-Newborn-Infant-OrgEnergyBull 1951.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d659da28e0d66b5b1b188a0cce8840c2d8bc9baa1dd0b21ac070464ba6b82e6b.pdf', 'medical_journal', 'ingested', '{"date": "1951", "description": "This article presents a clinical case study by Wilhelm Reich on the emergence and early treatment of emotional and somatic ''armoring'' in a newborn infant under the care of the Orgonomic Infant Research Center (OIRC). Reich details how an infant developed early bronchial and diaphragmatic respiratory blocks linked to a disruption in ''orgonotic contact'' between the mother and child, exacerbated by the mother''s feelings of guilt and unrealistic ideals of absolute health, as well as parental and familial conflicts. Through direct physical stimulation of intercostal muscles, orgone accumulator treatments, and parental counseling focused on emotional contact and self-regulation rather than rigid perfectionism, the infant showed marked physical and behavioral improvement.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wilhelm Reich", "Mrs. L", "Mr. L", "Dr. M"], "organizations": ["Orgonomic Infant Research Center", "Orgone Institute Press"], "themes": ["Orgonomy", "Infant Development", "Bio-energetic Armoring", "Mother-Infant Contact", "Diaphragmatic and Respiratory Blocking", "Self-Regulation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1bf3f5c95b8bb9cf640e5e19b1571d3584c3f20842ff36f3f12ee00b25dbd263', 'Reich Children-of-the-Future IntJOrgRes 1950.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1bf3f5c95b8bb9cf640e5e19b1571d3584c3f20842ff36f3f12ee00b25dbd263.pdf', 'medical_journal', 'ingested', '{"date": "1950-08-25", "description": "This document presents Wilhelm Reich''s report on the Orgonomic Infant Research Center (OIRC), originally delivered at the Second International Orgonomic Conference in August 1950. Reich contends that previous generations have failed to reform society through politics and ideology because adult character structures are rigidly armored and distorted by cultural conditioning. Consequently, the true responsibility of adults is to act as transmission belts\u2014stepping back to prevent the systemic armoring of newborn infants and allowing children to develop self-regulation and biological vigor naturally.\n\nThe text outlines the foundational structure and research program of the OIRC, which was established to study natural health in infants rather than focusing solely on pathology. Reich details a long-term research framework divided into prenatal care, birth and neonatal supervision, the prevention of armoring in early childhood, and longitudinal observation into puberty. He stresses the need for clinical objectivity, warning that armored society and ingrained ''emotional plague'' harbor an inherent hostility toward genuine life and spontaneous vitality in children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wilhelm Reich", "Eva Reich", "A. S. Neill", "Theodore P. Wolfe"], "organizations": ["Orgonomic Infant Research Center", "Orgone Institute", "Projeto Arte Org"], "themes": ["Orgonomic Functionalism", "Prevention of Armoring", "Infant Development and Health", "Preventive Mental Hygiene", "Self-Regulation", "Emotional Plague"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ecd3c172bd83b8cff2cffeb7cb30dd0ab04eaa43588a4b7a17883fa2a0934bfb', 'Reis Iatrogenic Blame AMA 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ecd3c172bd83b8cff2cffeb7cb30dd0ab04eaa43588a4b7a17883fa2a0934bfb.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article examines whether physicians are blameworthy for physical and emotional iatrogenic harm caused by medically unnecessary genital surgeries performed for sociocultural or aesthetic reasons. The authors focus on three specific practices: ''normalizing'' surgeries on infants and children with intersex traits, routine neonatal male circumcision, and cosmetic vaginal surgeries such as labiaplasty. They argue that irreversible surgical modifications lacking clear clinical indications violate bodily integrity and patient autonomy.\n\nThe authors contend that physicians should be held accountable for performing or promoting these nontherapeutic procedures, asserting that negative reactive attitudes\u2014such as blame and resentment from affected patients\u2014are morally fitting. Rather than pathologizing natural anatomical variation and yielding to social pressure, clinicians are urged to champion body positivity, defer irreversible choices to autonomous patients when they are mature enough to decide, and engage in restorative practices, including apology and accountability, to heal compromised physician-patient relationships.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Samuel Reis-Dennis", "Elizabeth Reis", "Susan Wolf"], "organizations": ["American Medical Association", "American Academy of Pediatrics", "International Society of Aesthetic Plastic Surgery", "American College of Obstetricians and Gynecologists"], "themes": ["Medical Ethics", "Iatrogenic Harm", "Physician Blameworthiness and Moral Accountability", "Intersex and Differences of Sex Development (DSD)", "Neonatal Male Circumcision", "Cosmetic Vaginal Surgery", "Patient Autonomy and Informed Consent", "Body Positivity and Genital Diversity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('48edd10883890f52ef4c90bf26a077a49eb12d2ce14e6c0b75591d68b5bfeb0e', 'Reiss My Painful Journey Kluwer 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/48edd10883890f52ef4c90bf26a077a49eb12d2ce14e6c0b75591d68b5bfeb0e.pdf', 'other', 'ingested', '{"date": "2004", "description": "In this autobiographical essay, retired physician Mark D. Reiss details his personal awakening at age sixty-five to the psychological and physiological trauma of his own infant circumcision. This realization prompted his involvement in the intactivism movement, his personal pursuit of foreskin restoration, and his efforts to educate medical students at institutions such as UCSF and Stanford on genital integrity and patient examination.\n\nReiss addresses the complex intersections of routine medical circumcision in the United States and longstanding religious traditions within Judaism. Despite facing pushback from fellow congregants and colleagues, he actively promotes non-cutting alternative ceremonies, such as brit shalom, and advocates for an end to routine neonatal circumcision, arguing that infant circumcision infringes upon bodily integrity and lacks compelling medical justification.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Mark D. Reiss", "Ronald Goldman", "Tim Hammond", "Norma Wilcox", "Morrie Sorrells", "R. Wayne Griffiths", "Marilyn Fayre Milos", "Joan Reinhardt Reiss"], "organizations": ["American Academy of Pediatrics", "National Organization of Restoring Men", "National Organization of Circumcision Resource Centers", "University of California, San Francisco", "Stanford Medical School", "Touro School of Osteopathy"], "themes": ["Circumcision Trauma", "Intactivism", "Jewish Tradition and Brit Shalom", "Medical Ethics and Education", "Foreskin Restoration", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0eb71aeed0d0e83c942e590ff2c99993695d7da19c952adb3fbd682adca2d584', 'Remondino Negro Rapes NatPopRev 1894.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0eb71aeed0d0e83c942e590ff2c99993695d7da19c952adb3fbd682adca2d584.pdf', 'medical_journal', 'ingested', '{"date": "1894", "description": "In this 1894 article from ''The National Popular Review,'' Dr. P. C. Remondino argues from the perspective of late-nineteenth-century criminal anthropology that psychological behavior and criminality are heavily influenced by physiological reflexes and anatomical conditions. Utilizing racist pseudoscientific theories of the era, the author advocates for state-enforced wholesale circumcision of Black men, contending that such an intervention would curb perceived predispositions to crime more effectively and humanely than mob violence, lynching, or punitive castration.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["P. C. Remondino", "Johann Georg Zimmermann"], "organizations": ["The National Popular Review"], "themes": ["Criminal Anthropology", "Scientific Racism", "History of Medicine", "Circumcision", "Social Control"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a93b76ae28c68b5cd30558a16ce3c99d272d6f7443e849f362c4ad929a2c8bb9', 'Rennie Ethics-circumcision-hiv-prevention Therapy 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a93b76ae28c68b5cd30558a16ce3c99d272d6f7443e849f362c4ad929a2c8bb9.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This perspective article examines the ethical discourse surrounding the use of male circumcision as an HIV prevention strategy following randomized controlled trials in South Africa, Uganda, and Kenya demonstrating a 50\u201360% protective effect. The author distinguishes between debates concerning the scientific evidence itself and debates regarding real-world implementation ethics, aiming to highlight moderate, nuanced positions between outright rejection and uncritical promotion.\n\nWhile the scientific consensus generally supports the biological efficacy of the intervention, significant implementation challenges remain. These include ethical considerations regarding the target age (infants versus adults and autonomy concerns), the risk of behavioral disinhibition or reduced condom usage, and healthcare infrastructure constraints regarding surgical safety and resource allocation in low-resource settings. Consequently, the author suggests that despite strong clinical trial results, male circumcision may ultimately play only a modest role in global HIV/AIDS prevention due to these cultural, logistical, and ethical hurdles.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stuart Rennie"], "organizations": ["University of North Carolina", "World Health Organization", "UNAIDS", "National Institutes of Health", "Future Medicine Ltd"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Implementation Ethics", "Bioethics", "Public Health Policy", "Global Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e6d3655526d5547e46b24f109e84099c2d8638e20af075251980e842f49db18c', 'RennieTradeoffs JME 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e6d3655526d5547e46b24f109e84099c2d8638e20af075251980e842f49db18c.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This academic paper examines the ethical, medical, and public health trade-offs of adopting male circumcision as an HIV prevention strategy in low-income, high-prevalence regions, specifically sub-Saharan Africa. Following randomized clinical trials demonstrating that circumcision significantly reduces the risk of heterosexual HIV acquisition in men, the authors explore how translating research into large-scale policy requires addressing complex dilemmas. These issues are evaluated across three target age groups: neonates, preadolescents, and adults.\n\nEach life stage presents distinct challenges regarding informed consent or assent, parental autonomy, risk compensation, cultural traditions, and health system capacity. The authors conclude that while male circumcision holds substantial potential alongside other HIV prevention methods, successful and ethical implementation requires robust safety protocols, equitable access, sensitive integration with local cultural norms, sustained condom promotion to counter sexual disinhibition, and ongoing dialogue with affected communities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stuart Rennie", "Adamson S Muula", "Daniel Westreich"], "organizations": ["University of North Carolina at Chapel Hill", "University of Malawi", "National Institutes of Health", "Fogarty International Center"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Bioethics", "Informed Consent and Autonomy", "Risk Compensation", "Public Health Policy", "Global Health Equity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dff45e0c8f8d77aeaea313ec6378b67dcac34e53bb62bc3e92b95dd457022582', 'Richter Circ Social Imagined Body HlthSocRev 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dff45e0c8f8d77aeaea313ec6378b67dcac34e53bb62bc3e92b95dd457022582.pdf', 'medical_journal', 'ingested', '{"date": "2006", "description": "This academic paper examines the sociocultural and symbolic dimensions of routine neonatal male circumcision in Australia, where the practice has transitioned over a generation from a standard procedure to a minority experience. The author argues that rather than being driven purely by rational public health objectives, circumcision serves as a gender-dimorphic body modification. This practice culturally refashions the penis into an unambiguous, insertive phallic tool tailored to a coitus-centered sexual model, while medical rationales often function as post hoc justifications.\n\nThe paper also critiques the limitations of evidence-based medicine in evaluating circumcision''s impact on sexual sensitivity and pleasure. Because medical and sexological discourse predominantly frames male sexuality around erectile and ejaculatory performance rather than the receptive processing of subtle erotic sensations, standard clinical research tools systematically fail to capture or conceptualize potential sensory loss.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Juliet Richters", "Mary Douglas", "William H. Masters", "Virginia E. Johnson", "Terry Russell"], "organizations": ["National Centre in HIV Social Research", "University of New South Wales", "Royal Australasian College of Physicians", "Medicare", "National Health and Medical Research Council"], "themes": ["Male Circumcision", "Sociology of the Body", "Gender Dimorphism", "Evidence-Based Medicine", "Sexual Function and Sensitivity", "Public Health Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ab1b5d8528e31b6dd6d162e3f08640e2c2db37447ee8e1660af862f9b44e367b', 'Richters Circ Penis Size Condom Venerealogy 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ab1b5d8528e31b6dd6d162e3f08640e2c2db37447ee8e1660af862f9b44e367b.pdf', 'medical_journal', 'ingested', '{"date": "1995-05", "description": "This study investigates the adequacy of condom sizing and standards in Australia by evaluating self-reported erect penis measurements from a volunteer sample of 156 men. Using a paper-tape self-measurement kit, researchers found an average erect penis length of 16.0 cm and base circumference of 13.5 cm, demonstrating that the self-measurement technique is reasonably reproducible.\n\nThe findings show a direct correlation between penis dimensions and subjective condom comfort: men with larger circumferences frequently reported condoms being too tight, while those with longer penises complained they were too short. Additionally, non-users tended to have narrower penises on average. The authors conclude that commercial condom offerings in Australia are clustered in too narrow a size range and recommend manufacturing and marketing condoms in a broader variety of lengths and widths to improve fit, comfort, and compliance.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Juliet Richters", "John Gerofi", "Basil Donovan", "Lex Watson", "Geoffrey Berry"], "organizations": ["University of Sydney", "Enersol Consulting Engineers", "Sydney Sexual Health Centre", "Commonwealth AIDS Research Grants Committee", "International Organization for Standardization"], "themes": ["Condom Sizing and Fit", "Penile Anthropometry", "Public Health and STI Prevention", "Manufacturing Standards", "Sexual Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('964ed545750c4338baa4065cdcde841d3889926a93f367979d4d1e34d3d8cca3', 'Rickwood Phimosis Overdiagnosed AnnRoyCollSurgEngland 1989.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/964ed545750c4338baa4065cdcde841d3889926a93f367979d4d1e34d3d8cca3.pdf', 'medical_journal', 'ingested', '{"date": "1989", "description": "This study investigates whether phimosis is overdiagnosed in young boys, leading to excessive and unnecessary circumcisions within England''s National Health Service, specifically focusing on the Mersey Region. Comparing regional surgical data with specialized clinic findings at the Royal Liverpool Children''s Hospital, the authors demonstrate that developmental non-retractile foreskin (physiological phimosis) is frequently misdiagnosed as true pathological phimosis, particularly in boys under five years old. Consequently, the authors conclude that approximately two-thirds of circumcisions performed on young boys in the region are clinically unnecessary, resulting in unwarranted surgical procedures and substantial avoidable costs to the healthcare system.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["A M K Rickwood", "Jenny Walker"], "organizations": ["Royal College of Surgeons of England", "Royal Liverpool Children\u2019s Hospital (Alder Hey)", "National Health Service"], "themes": ["Pediatric Urology", "Circumcision", "Phimosis Overdiagnosis", "Physiological vs. Pathological Phimosis", "Healthcare Resource Allocation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dc59a9f931d836cc9dd91ad7105e020da48081a50c997aa2f8da3582910f620e', 'Riess Bailey When_I_Was_Circumcised PlosOne 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dc59a9f931d836cc9dd91ad7105e020da48081a50c997aa2f8da3582910f620e.pdf', 'medical_journal', 'ingested', '{"date": "2010-08-25", "description": "This qualitative study investigates whether male circumcision (MC) leads to sexual risk compensation\u2014such as decreased condom use or an increased number of sexual partners\u2014among 30 sexually active circumcised men in Kisumu, Kenya. Male circumcision reduces female-to-male HIV transmission by approximately 60%, prompting concerns that perceived immunity might lead men to engage in riskier sexual behaviors. \n\nThe study found that most respondents either maintained their existing sexual behaviors or adopted safer, protective behaviors, including increased condom usage and partner reduction. Only a small minority engaged in risk compensation. Crucially, the adoption of protective behaviors was strongly linked to pre-circumcision counseling, voluntary HIV testing, and a widespread understanding that circumcision provides only partial protection against HIV. The authors conclude that integrating risk-reduction counseling and testing alongside male circumcision rollouts is essential to sustain HIV prevention benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Thomas H. Riess", "Maryline M. Achieng\u2019", "Samuel Otieno", "J. O. Ndinya-Achola", "Robert C. Bailey", "Landon Myer"], "organizations": ["University of Illinois at Chicago", "Kenya Medical Research Institute", "University of Nairobi", "World Health Organization", "UNAIDS", "National Institutes of Health", "Centers for Disease Control and Prevention", "Kenyatta National Hospital"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Risk Compensation", "Sexual Behavior", "HIV Counseling and Testing", "Condom Use"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8889c4d10c560b7c16337843faf41f1e2d1919cc4bb235877b093b0c1f9f3c92', 'Rizalar Children''s Perspectives_IranJPEd 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8889c4d10c560b7c16337843faf41f1e2d1919cc4bb235877b093b0c1f9f3c92.pdf', 'medical_journal', 'ingested', '{"date": "2016-11-05", "description": "This research article investigates the perceptions, emotions, and experiences of 326 circumcised boys aged 7 to 14 in Samsun, Turkey, regarding the medical and cultural dimensions of circumcision. The study found that while the majority of participants underwent the procedure for religious reasons or as a traditional rite of passage into manhood, over one-quarter were not informed beforehand, and nearly half were circumcised during the phallic stage (ages 3\u20136), which can cause elevated psychological distress.\n\nA significant proportion of the boys reported experiencing considerable fear (64.7%), pain (54.6%), and grief (48.2%) during the procedure. These adverse experiences were statistically significantly associated with circumcisions performed outside hospital settings, by traditional circumcisers rather than surgeons, under local rather than general anesthesia, and during inappropriate age windows. The authors emphasize the urgent need for public education ensuring that circumcision is conducted in sterile hospital environments by surgeons with adequate psychological preparation and proper pain management.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Selda Rizalar", "Esra Tural Buyuk", "Nejla Yildirim"], "organizations": ["Istanbul Medipol University", "Ondokuz Mayis University"], "themes": ["Male Circumcision", "Pediatric Surgery", "Pain and Fear in Children", "Cultural and Religious Rituals", "Healthcare Ethics and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a06db80427006fe3b35074872a8c64ba6bed36f63b8d0a25483513cf58829da6', 'Roehrborn Changes Androgen Receptor AmSocClinInv 1987.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a06db80427006fe3b35074872a8c64ba6bed36f63b8d0a25483513cf58829da6.pdf', 'medical_journal', 'ingested', '{"date": "1987", "description": "This study investigates the concentration and intracellular distribution of high-affinity androgen receptors in human foreskin tissue obtained from 49 males ranging from newborns to 59 years old. The researchers observed that total androgen receptor content decreases from infancy, rises significantly through childhood to a peak in the late teenage years (~180 fmol/g), and then declines sharply in men over 40 years of age. Additionally, the amount of receptor located in the nuclear fraction rises markedly during puberty, accounting for approximately half of the total receptor content thereafter.\n\nThe findings indicate that androgen receptor levels parallel the developmental and growth trajectory of the human penis. Because the receptor elevation begins before the pubertal surge in testicular androgens, the authors suggest that tissue receptor levels may be primed by mechanisms not solely dependent on testosterone, while the subsequent decline after late adolescence mirrors the cessation of penile growth.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Claus G. Roehrborn", "John L. Lange", "Fredrick W. George", "Jean D. Wilson"], "organizations": ["The University of Texas Health Science Center at Dallas", "The American Society for Clinical Investigation, Inc.", "National Institutes of Health"], "themes": ["Androgen Receptors", "Penile Growth and Development", "Endocrinology", "Puberty and Aging", "Steroid Hormone Binding"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f4f4408ebc238ce4e53eefcf0419b7fa3e2228f4d530d23daf3aa7c4e488c808', 'Rosenhouse A Foreskin is Missing Hustler Aug 1975.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f4f4408ebc238ce4e53eefcf0419b7fa3e2228f4d530d23daf3aa7c4e488c808.pdf', 'other', 'ingested', '{"date": "1975-08", "description": "This article explores the medical, sexual, psychological, and cultural debates surrounding male circumcision. Through various anecdotes\u2014ranging from a barracks dispute over penis size and a botched circumcision prompting an assault to historical commentary on Michelangelo''s David\u2014the author discusses the shifting medical consensus regarding the procedure. The text examines how the loss of the prepuce impacts sexual sensation, hygiene, marital relations, and male identity, concluding that the medical necessity of circumcision has often been overstated.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Leo Rosenhouse", "Michelangelo", "Herodotus"], "organizations": ["Hustler", "Bellevue Hospital"], "themes": ["Circumcision", "Male Sexual Anatomy", "Sexual Sensation", "Medical Controversy", "Hygiene and Balanitis", "Religious Rituals"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('539ea7cecd2ce4f9d8959bc72fba2f3f794395344862098dc9133f12b05355f6', 'Rossi Mgmt of Pain EurJPed 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/539ea7cecd2ce4f9d8959bc72fba2f3f794395344862098dc9133f12b05355f6.pdf', 'medical_journal', 'ingested', '{"date": "2020-08-03", "description": "This systematic review evaluates the literature from the past two decades concerning pain management and analgesic techniques during neonatal male circumcision. The authors note that while male circumcision is one of the most common surgical procedures performed on newborns, it is frequently conducted with suboptimal or inappropriate analgesia, and standard clinical protocols vary widely among medical centers.\n\nThe findings indicate that relying on a single analgesic method or sucrose alone is insufficient, whereas multimodal approaches combining local pharmacological anesthesia\u2014such as ring block or dorsal penile nerve block with EMLA cream\u2014and non-pharmacological interventions like oral sucrose or non-nutritive sucking yield superior pain control. The review advocates for establishing standardized clinical protocols and suggests incorporating sensorial saturation alongside local anesthetics to achieve effective, near-painless neonatal circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Serena Rossi", "Giuseppe Buonocore", "Carlo Valerio Bellieni", "Gregorio Paolo Milani"], "organizations": ["University of Siena", "Springer Nature"], "themes": ["Neonatal Pain Management", "Male Circumcision", "Local Anesthesia", "Non-pharmacological Analgesia", "Sensorial Saturation", "Pediatric Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8b933ddb7cad3588c1e9e58af8bbff1323e94356a16898f57cdb5645010a48e4', 'Rothaeusler Foreskin AntiViral in Monkeys JVirol2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8b933ddb7cad3588c1e9e58af8bbff1323e94356a16898f57cdb5645010a48e4.pdf', 'medical_journal', 'ingested', '{"date": "2012-04-24", "description": "This study investigates the mucosal immune defenses of the male genital tract by characterizing antiviral immune responses in the foreskin and glans of rhesus macaques infected with simian immunodeficiency virus (SIVmac251). The authors identified a complete population of immune cells within normal penile tissues, where CD4+ and CD8+ T cells were prevalent and B cells were comparatively rare. Following penile exposure to SIV, SIV-specific IgG antibodies were detected in foreskin secretions, and functional, cytokine-secreting SIV-specific CD8+ T cells were isolated from foreskin tissue cell suspensions.\n\nThese findings provide the first direct evidence of virus-specific effector B and T cell activity within the primate foreskin, a primary anatomical site of heterosexual HIV transmission. While the foreskin contains abundant target cells for viral entry, the presence and induction of local antiviral immune mechanisms demonstrate that mucosal vaccination strategies targeting the male reproductive tract could potentially elicit protective immunity to prevent HIV acquisition.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kristina Rothaeusler", "Zhong-Min Ma", "Huma Qureshi", "Timothy D. Carroll", "Tracy Rourke", "Michael B. McChesney", "Christopher J. Miller"], "organizations": ["Center for Comparative Medicine", "California National Primate Research Center", "University of California, Davis", "American Society for Microbiology", "National Institute of Allergy and Infectious Diseases", "National Center for Research Resources"], "themes": ["HIV/SIV Transmission", "Penile Mucosal Immunology", "Foreskin Immune Responses", "CD8+ T-cell Immunity", "Antiviral IgG Antibodies", "Vaccine Development"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3893dafe9985495e4caa06d9d6ec3bdb6a8a3d6e99c5a8ee5b55ba26784cbb1f', 'RoyalAustrCP_2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3893dafe9985495e4caa06d9d6ec3bdb6a8a3d6e99c5a8ee5b55ba26784cbb1f.pdf', 'policy_guideline', 'ingested', '{"date": "2010", "description": "This policy statement from the Paediatrics & Child Health Division of the Royal Australasian College of Physicians (RACP) evaluates the medical, legal, and ethical dimensions of elective infant male circumcision. The document reviews epidemiological evidence regarding potential protective benefits\u2014such as reductions in urinary tract infections, certain sexually transmitted infections, and penile cancer\u2014alongside procedural risks, contraindications, and mandatory analgesia practices. The RACP concludes that the frequency of modifiable conditions in Australia and New Zealand does not justify routine infant circumcision in the general population.\n\nWhile routine circumcision is not endorsed, the statement affirms that informed parental choice should be respected, provided that parents are presented with balanced, evidence-based counseling regarding risks and potential advantages. The document stresses that any circumcision must be performed by a qualified practitioner in a safe clinical environment using adequate pain control, while highlighting ethical considerations surrounding bodily integrity and whether the procedure ought to be deferred until the child can give autonomous consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["The Royal Australasian College of Physicians", "World Health Organization", "American Academy of Pediatrics", "British Medical Association", "Canadian Paediatric Society", "American Urological Association", "Royal Dutch Medical Association", "Scottish Intercollegiate Guidelines Network"], "themes": ["Infant Male Circumcision", "Pediatric Pain Management and Analgesia", "Disease Prevention (UTI, HIV, and STIs)", "Medical Ethics and Minor Autonomy", "Parental Consent and Clinical Decision-Making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d685bb955ad11db3cb1e84198fcbfa47a1d9b591ad914a95521862ecd9dce529', 'RoyalAustrCP_2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d685bb955ad11db3cb1e84198fcbfa47a1d9b591ad914a95521862ecd9dce529.pdf', 'policy_guideline', 'ingested', '{"date": "2022", "description": "This position statement from the Royal Australasian College of Physicians (RACP) reviews the clinical, legal, and ethical considerations surrounding elective and therapeutic circumcision of male infants. After evaluating the available scientific evidence, the RACP concludes that the frequency of modifiable diseases, level of protection offered, and risk of complications do not justify routine infant circumcision in Australia or Aotearoa New Zealand. However, circumcision should be strongly considered for infant males with severe congenital urinary tract abnormalities due to a significantly elevated baseline risk of recurrent infections.\n\nFor infants with normal urinary tracts, the RACP highlights that parental choice should be respected through informed, shared decision-making. If circumcision is pursued, the College mandates that it be performed by appropriately trained medical practitioners in safe, adequately equipped settings utilizing effective anaesthesia and analgesia, while emphasizing that infant anaesthesia carries inherent risks that must be carefully managed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Robert Darby", "Robert Van Howe"], "organizations": ["Royal Australasian College of Physicians", "Australian and New Zealand College of Anaesthetists", "American Academy of Pediatrics", "Royal Dutch Medical Association", "United Nations"], "themes": ["Infant Male Circumcision", "Pediatric Anaesthesia and Pain Management", "Urinary Tract Infections", "Medical Ethics and Informed Consent", "Sexually Transmitted Infections"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('733e1bfe874873aff53f3bd1c06b3e259e5eceaa41d7bfd26455fd0275f37154', 'Rubin Celsus'' Decirc Oper Urology 1980.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/733e1bfe874873aff53f3bd1c06b3e259e5eceaa41d7bfd26455fd0275f37154.pdf', 'medical_journal', 'ingested', '{"date": "1980-07-01", "description": "This article provides a medical and historical analysis of decircumcision and prepuce reconstruction techniques as recorded by the Roman medical writer Celsus in his first-century treatise ''De medicina''. The author examines the two surgical procedures detailed by Celsus\u2014one for congenitally deficient foreskins and another for individuals who had been circumcised\u2014evaluating their anatomical mechanics, wound care, and feasibility against modern plastic surgery techniques.\n\nIn addition to the surgical mechanics, the paper contextualizes the social and cultural motives behind these operations. In Greco-Roman society, an exposed glans was viewed with distaste and associated with circumcision, which carried social stigma and legal liabilities, especially for Jews. Decircumcision served as a plastic surgical solution motivated by decorum, allowing individuals to avoid mockery in public baths and gymnasia, escape anti-Jewish persecution or taxation, and assimilate into Hellenistic and Roman civic life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jody P. Rubin", "Aulus Cornelius Celsus"], "organizations": ["Society for Ancient Medicine"], "themes": ["History of Medicine", "Plastic Surgery", "Decircumcision", "Greco-Roman Culture", "Jewish History"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('23055d308571ab7b7a914a4cff22775d6a9c2aa2ad7e38b8fa6aeabb05aea165', 'Rudrum Discourses Uganda Circ Campaign CultHlthSex 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/23055d308571ab7b7a914a4cff22775d6a9c2aa2ad7e38b8fa6aeabb05aea165.pdf', 'medical_journal', 'ingested', '{"date": "2016-08-11", "description": "This article presents a critical discourse analysis of Uganda''s 2012 ''Stand Proud, Get Circumcised'' public health campaign, which promoted voluntary medical male circumcision as an HIV-prevention strategy. The authors evaluate how the campaign''s posters employ gendered representations, noting that while the materials depart from conservative ''Abstain, Be faithful, Use condoms'' messaging by acknowledging casual and extramarital sex, they inappropriately exploit male anxieties regarding penis size, aesthetics, and sexual performance to encourage circumcision.\n\nThe authors argue that by exclusively featuring women on the posters, the campaign reaffirms harmful gender norms that position women as the primary custodians of family health and deepens the estrangement between men and their own healthcare responsibilities. Furthermore, the campaign''s claim that circumcision reduces HIV risk for couples misrepresents clinical evidence\u2014given that circumcision directly reduces female-to-male transmission only\u2014while reinforcing rigid heteronormativity and marginalizing comprehensive prevention methods such as condom use.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sarah Rudrum", "John L. Oliffe", "Cecilia Benoit"], "organizations": ["University of British Columbia", "University of Victoria", "Uganda Ministry of Health", "United States Agency for International Development (USAID)", "Health Communication Partnership"], "themes": ["HIV Prevention", "Voluntary Medical Male Circumcision", "Hegemonic Masculinity", "Feminine Sexuality", "Public Health Campaigns", "Heteronormativity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9576db8665aa0b55397953c02672b5141791b9562e11ba17c1e7e3954fd075bd', 'Ruesink Genital Hedonic Sensation Nature 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9576db8665aa0b55397953c02672b5141791b9562e11ba17c1e7e3954fd075bd.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This study presents a systematic psychophysical and neuroimaging investigation into how the human brain encodes pleasurable sensory stimulation of male genital skin compared to forearm skin. Using dynamic brushing paradigms and functional magnetic resonance imaging (fMRI) across 19 couples, the authors demonstrated that slow, C-tactile (CT)-targeted stimulation of the penile shaft was perceived as significantly more pleasurable than faster, non-CT-targeted stimulation, mirroring patterns observed in hairy skin of the forearm but with an overall higher baseline of pleasure.\n\nNeurally, the secondary somatosensory cortex (S2) differentiated between affective and discriminative touch speeds on the penile shaft, while insular cortex activity did not exhibit the expected differentiation. Additionally, tactile stimulation of the penile frenulum elicited the highest ratings of subjective pleasure and triggered prominent deactivation of the default-mode network (DMN), suggesting specialized peripheral mechanisms and heightened attentional engagement during intimate genital tactile stimulation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Gerben B. Ruesink", "Francis P. McGlone", "H\u00e5kan Olausson", "Camilla de Jong", "Jan-Bernard Marsman", "Remco J. Renken", "Janniko R. Georgiadis", "Marcel Waldinger"], "organizations": ["University of Groningen", "University Medical Center Groningen", "Liverpool John Moores University", "Link\u00f6ping University", "Netherlands Institute for Mental Health and Addiction (Trimbos Institute)", "Springer Nature"], "themes": ["Affective Touch", "C-tactile Afferents", "Neuroimaging and fMRI", "Genital Hedonic Sensation", "Somatosensory Cortex", "Default Mode Network"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eb30e06b059f2f26ad2f87718ad0fa28f6a137c270ae8d329736877b3c0d2300', 'Ryan-Finer Changing Attitudes Analgesia Circumcision Peds 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eb30e06b059f2f26ad2f87718ad0fa28f6a137c270ae8d329736877b3c0d2300.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This study evaluates an educational and awareness intervention aimed at changing physician practices regarding the routine use of local and regional analgesia during newborn circumcision at the Royal Alexandra Hospital in Edmonton. Prior to the intervention, only one physician routinely used local analgesia. Following an educational program consisting of grand rounds presentations, instructional videos, posters, newsletters, and hands-on demonstrations of prepucial local anesthesia and dorsal penile nerve blocks, an audit was conducted 12 months later.\n\nThe follow-up audit demonstrated a significant shift in clinical practice: 73% of the practicing physicians utilized local analgesia, accounting for 66% of all performed circumcisions. The authors conclude that simple, multimodal educational initiatives can successfully influence physician attitudes and behavior toward routine neonatal pain management.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["C. Anthony Ryan", "Neil N. Finer"], "organizations": ["Royal Alexandra Hospital", "University of Alberta", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Local and Regional Analgesia", "Physician Education and Practice Change", "Pain Management in Infants", "Clinical Audit"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f175d228ee659dac5feecc01016b01f8f56110f9983fac8f097d1d61c2a7fb72', 'Sahay Community_Perspect India PLoSOne 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f175d228ee659dac5feecc01016b01f8f56110f9983fac8f097d1d61c2a7fb72.pdf', 'medical_journal', 'ingested', '{"date": "2014-03-10", "description": "This multi-centric qualitative study investigates the beliefs, experiences, and attitudes of community members and registered healthcare providers across four Indian cities regarding male circumcision (MC) as an HIV prevention strategy. The findings reveal profound religious and cultural divides, as male circumcision is heavily associated with Muslim and Jewish religious identity, creating resistance among non-circumcising communities (NCC) and skepticism among clinicians toward ''foreign'' clinical trial data. Participants cited concerns regarding surgical pain, cost, communal tensions, and the potential exacerbation of HIV-related stigma.\n\nDespite widespread socio-religious hesitation toward programmatic MC scale-up, individual members of non-circumcising communities willingly accept medical circumcision when indicated for clinical conditions such as phimosis or urinary tract infections. Healthcare providers emphasize that mass promotion of MC is not currently viable in India without local clinical evidence, though introducing secularized, voluntary medical circumcision targeted specifically at high-risk groups within clinical settings presents a feasible public health opportunity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Seema Sahay", "Karikalan Nagarajan", "Sanjay Mehendale", "Sibnath Deb", "Abhilasha Gupta", "Shalini Bharat", "Shripad Bhatt", "Athokpam Bijesh Kumar", "Vidisha Kanthe", "Anju Sinha", "Nomita Chandhiok", "Nicholas Jenkins"], "organizations": ["National AIDS Research Institute", "National Institute of Epidemiology", "Pondicherry University", "LLRM College", "Tata Institute of Social Sciences", "Regional Medical Research Centre", "Indian Council of Medical Research", "University of Calcutta", "World Health Organization"], "themes": ["Male Circumcision", "HIV Prevention", "Religious and Cultural Identity", "Healthcare Provider Attitudes", "Medical Indication vs. Faith", "Health Stigma and Communication"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('be90109b68edeb839cca70df8102c7907b493377c1b5c94f7eb72be7b05e34fa', 'Sarajlic Can culture justify circ ResPublica 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/be90109b68edeb839cca70df8102c7907b493377c1b5c94f7eb72be7b05e34fa.pdf', 'other', 'ingested', '{"date": "2014-09-09", "description": "This article evaluates the moral justifiability of non-therapeutic male infant circumcision, focusing on whether social, cultural, or religious benefits can justify the procedure. The author, Eldar Sarajlic, critically examines arguments put forward by scholars like Joseph Mazor and Michael and David Benatar, who argue that cultural integration, parental discretion, and long-term communal interests can outweigh bodily autonomy. Sarajlic rejects these positions, contending that parental beliefs\u2014whether secular or religious\u2014cannot justify irreversible surgical interventions on non-autonomous infants.\n\nTo counter cultural benefit justifications, Sarajlic endorses and expands upon the ''right to an open future'' argument originally articulated by Joel Feinberg and applied to circumcision by Robert Darby. He addresses objections claiming that physical bodily modifications are normatively equivalent to non-physical cultural indoctrination, showing that whereas cultural exposure can be institutionally balanced and beliefs revised, physical foreskin removal permanently closes life options without functional remedy. Although concluding that infant circumcision violates the child''s anticipatory autonomy rights, Sarajlic notes that policy solutions must navigate complex socio-political contexts carefully to avoid driving the practice underground.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Eldar Sarajlic", "Joseph Mazor", "Michael Benatar", "David Benatar", "Joel Feinberg", "Robert J. L. Darby", "Dena S. Davis"], "organizations": ["Central European University", "Springer", "District Court in Cologne", "American Academy of Pediatrics", "British Medical Association", "Open Society Foundation"], "themes": ["Infant Circumcision", "Right to an Open Future", "Bioethics", "Bodily Integrity", "Cultural and Religious Rights", "Parental Authority"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('04a8d18040dc134dbd019285811e796d6396d539d324affec13a131c8daffc30', 'Sardi Parental_Decision_Making JMCN 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/04a8d18040dc134dbd019285811e796d6396d539d324affec13a131c8daffc30.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study examines the parental decision-making process regarding male neonatal circumcision, investigating which healthcare professionals initiate discussions, whether parents feel adequately informed, and what factors influence their choices. Administering surveys to 60 parents and expectant parents, the researchers found that nurses were the most frequent healthcare professionals to first discuss circumcision. However, nearly a quarter of parents reported not receiving sufficient clinical information about the procedure''s risks and benefits.\n\nFactor analysis demonstrated that parental decisions were predominantly shaped by cultural and personal beliefs\u2014such as aesthetic preference, paternal resemblance, and hygiene\u2014rather than solely medical data. The authors emphasize that nurses play a crucial liaison role in parental proxy consent and recommend introducing unbiased, comprehensive education early in pregnancy to ensure parents can provide truly informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lauren Sardi", "Kathy Livingston"], "organizations": ["Quinnipiac University", "American Academy of Pediatrics", "World Health Organization", "Wolters Kluwer Health, Inc."], "themes": ["Neonatal Circumcision", "Informed and Proxy Consent", "Parental Decision-Making", "Clinical Nursing Practice", "Cultural and Medical Health Beliefs"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('318bd9860f7eef2ac31de11d28513e8a57a44de2d4ed5547a99a41b1d38abe1b', 'Sardi Social Movements Citizenship SocBorders 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/318bd9860f7eef2ac31de11d28513e8a57a44de2d4ed5547a99a41b1d38abe1b.pdf', 'other', 'ingested', '{"date": "2011", "description": "This academic article examines the debate surrounding routine male neonatal circumcision in the United States, focusing on the transition of the discourse from a medicalized health intervention to a human rights issue. The author traces the historical medicalization of the procedure during the Victorian era and 20th century, juxtaposing it with the rise of the modern ''intactivist'' social movement. Intactivists argue that infant male circumcision violates human rights, drawing parallels to female genital cutting and non-consensual surgeries on intersex infants regarding bodily integrity, lack of informed consent, pain, and sexual well-being.\n\nConversely, the article analyzes how proponents defend circumcision through frameworks of parental discretion, cultural norms, and religious freedom, particularly within Judaism and Islam, asserting that banning the practice would infringe upon religious rights. Sardi argues that both sides rely on Westernized, conflicting definitions of human rights\u2014pitting individual bodily autonomy against collective religious and cultural rights. Ultimately, the paper concludes that these competing and contradictory human rights frameworks cause opponents and proponents to talk past one another, while revealing underlying ethnocentric double standards in Western law and cultural attitudes toward genital modification.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lauren M. Sardi", "Robert Darby", "David L. Gollaher", "Ronald Goldman", "Bettina Shell-Duncan", "Ed Schoen", "Marilyn Milos", "Van Lewis", "John Harvey Kellogg"], "organizations": ["Quinnipiac University", "Sociologists Without Borders", "Case Western Reserve University School of Law", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "Intact America", "American Academy of Pediatrics", "United Nations"], "themes": ["Male Neonatal Circumcision", "Intactivism and Social Movements", "Bodily Integrity and Informed Consent", "Medicalization of Genitalia", "Human Rights vs. Religious Freedom", "Female Genital Cutting Comparisons", "Children''s Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ed09d870bd8b67d2aec6c585277b9067d50ebb22227a8f54211d8dc714104aa5', 'Schiering_Genital Integrity Early Childhood_2020-01.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ed09d870bd8b67d2aec6c585277b9067d50ebb22227a8f54211d8dc714104aa5.pdf', 'medical_journal', 'ingested', '{"date": "2020-01", "description": "This article argues against non-therapeutic male circumcision, defining it as an irreversible human rights violation that deprives boys of their fundamental right to bodily integrity and sexual self-determination. Written by Victor Schiering, chairman of MOGiS e.V., the text critiques German legislation\u2014specifically Paragraph 1631d of the German Civil Code (BGB)\u2014for failing to protect boys against medically unnecessary foreskin amputations, despite strong public opposition and warnings from pediatric associations.\n\nDrawing on first-person testimonies of lifelong physical, sexual, and psychological trauma, the author challenges the trivialization of circumcision as a minor procedure. The article criticizes dubious medical indications such as routine phimosis diagnoses, as well as international mass-circumcision initiatives in Africa promoted by Western organizations. Schiering calls for public awareness, specialized counseling for affected individuals, strict application of conservative medical guidelines, and legal reforms that guarantee equal protection for children of all genders.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Victor Schiering", "Steffen H.", "Hakan S.", "Johannes D.", "Julius R.", "Jutta Reisinger", "Owino Kennedy", "Prince Hillary Maloba", "Max Fish"], "organizations": ["MOGiS e.V.", "German Ethics Council", "Deutsche Gesellschaft f\u00fcr Chirurgie", "Aktion Regen Vienna", "Bill and Melinda Gates Foundation", "World Health Organization", "UNICEF", "Intact Kenya", "VMMC Experience Project", "Berufsverband der Kinder- und Jugend\u00e4rzte", "National Coalition Germany"], "themes": ["Genital Autonomy", "Children''s Rights", "Male Circumcision", "Bodily Integrity", "Medical Ethics", "Legal Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('51bd7f1434b1b8943168c1d1d59c829983b2092556eac2a8706e308ae067c5ff', 'Schiering_GenitaleIntegritaet frueheKindheit_2020-01.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/51bd7f1434b1b8943168c1d1d59c829983b2092556eac2a8706e308ae067c5ff.pdf', 'other', 'ingested', '{"date": "2020", "description": "In this article, Victor Schiering criticizes the avoidance and defensive attitudes within German media and political spheres regarding the non-therapeutic circumcision of boys. He argues that Paragraph 1631d of the German Civil Code (BGB), enacted in late 2012, strips boys of effective legal and state protection against bodily harm and violates their rights to genital integrity and self-determination.\n\nThe author highlights the stark contrast between public disapproval of the practice and political inaction, pointing out severe medical complications documented by surgical organizations (such as over 400 annual hospitalizations reported by DGCH in 2014) and legally dropped cases of botched circumcisions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Victor Schiering"], "organizations": ["MOGiS e.V.", "Deutscher Ethikrat", "Deutsche Gesellschaft f\u00fcr Chirurgie"], "themes": ["Genital Autonomy", "Male Circumcision", "Children''s Rights", "Child Protection", "Paragraph 1631d BGB"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f2511d1089cb2a79d67de0ee1431fd62ed5769e633a5d338c2d984e6f31323a9', 'Schlossberger Adol Knowl Circ JAdolHlth 1991.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f2511d1089cb2a79d67de0ee1431fd62ed5769e633a5d338c2d984e6f31323a9.pdf', 'medical_journal', 'ingested', '{"date": "1992-06", "description": "This study investigates early adolescent males'' knowledge, perceptions, and satisfaction regarding their circumcision status, as well as the relationship between circumcision and general body image. Evaluating 73 boys aged 11 through 14 via physical examinations, self-report surveys, body image scales, and visual anatomical diagrams, the researchers found that visual aids yielded substantially more accurate self-identification of circumcision status than verbal self-reporting alone.\n\nThe findings indicated that circumcised boys reported significantly higher satisfaction with their status and felt more similar to family members compared to uncircumcised peers. However, circumcision status did not have a measurable impact on overall body image. The authors conclude that while uncircumcised boys appeared to experience lower satisfaction and perceived themselves as a minority, larger multi-institutional studies are necessary to evaluate the long-term psychosocial outcomes across adolescence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Norman M. Schlossberger", "Rebecca A. Turner", "Charles E. Irwin, Jr."], "organizations": ["University of California at San Francisco", "Society for Adolescent Medicine", "Elsevier Science Publishing Co., Inc.", "William T. Grant Foundation", "Bureau of Maternal and Child Health"], "themes": ["Circumcision", "Adolescent Health", "Psychosocial Effects", "Body Image", "Pediatric Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('84efb2a3fa1c3eac1f5f87e6b9ec03bacad3c75d01c1d10b567ba53581c4e21b', 'Schneider Skin Game Genre 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/84efb2a3fa1c3eac1f5f87e6b9ec03bacad3c75d01c1d10b567ba53581c4e21b.pdf', 'other', 'ingested', '{"date": "1997-11", "description": "This article, published in the November 1997 issue of Genre magazine, investigates the growing movement among American men to reverse the effects of infant circumcision through non-surgical foreskin restoration. Written by Scott Seomin, the piece explores the deep frustration, grief, and sense of bodily violation experienced by men who resent having undergone a non-consensual procedure that removes significant erogenous, nerve-rich tissue.\n\nThe feature highlights personal stories and mechanical techniques used to regenerate tissue via skin expansion, primarily focusing on Roland Clark''s invention, the Penis Uncircumcising Device (P.U.D.), as well as alternative tape-and-strap systems and cones. In addition to discussing medical perspectives on surgical limitations and anatomy, the article outlines the emotional healing reported by men undertaking the restoration process and provides a directory of intactivist organizations and restoration resources.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Scott Seomin", "Roland Clark", "Gary Parker", "Brian Lawson", "John Kowalczyk", "Thomas J. Ritter", "Ronald Goldman", "George Denniston", "Tim Hammond", "Marilyn Milos"], "organizations": ["American Bodycrafters, Inc.", "Circumcision Resource Center", "Doctors Opposing Circumcision", "National Organization to Halt the Abuse and Routine Mutilation of Males", "National Organization of Circumcision Information Resource Centers"], "themes": ["Male Circumcision", "Foreskin Restoration", "Bodily Autonomy and Consent", "Men''s Sexual Health", "Genital Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d0deec28443df3ad03d98f4f36f352f83a2ab40432ee55fa754c87c1de45c287', 'Schoen vaccination JMHG 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d0deec28443df3ad03d98f4f36f352f83a2ab40432ee55fa754c87c1de45c287.pdf', 'medical_journal', 'ingested', '{"date": "2007-08-20", "description": "This debate article posits that newborn male circumcision functions effectively as a lifetime vaccination against multiple medical disorders, most notably heterosexual HIV transmission. Citing randomized clinical trials showing a 60% reduction in infection rates, the author highlights endorsements from major global health bodies like the WHO, UNAIDS, and NIH, which recommend circumcision as an essential intervention against the HIV epidemic.\n\nIn addition to HIV prevention, the article outlines numerous other health benefits associated with the procedure. These include reduced risks of sexually transmitted infections such as HPV and syphilis, lower rates of penile cancer and cervical cancer in female partners, decreased incidence of infant urinary tract infections, resolution of phimosis, and simplified genital hygiene.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Edgar J. Schoen"], "organizations": ["Kaiser Permanente Medical Center", "National Institutes of Health", "World Health Organization", "UNAIDS", "Centers for Disease Control and Prevention", "WPMH GmbH", "Elsevier Ireland Ltd"], "themes": ["Male Circumcision", "HIV Prevention", "HPV and Cancer Prevention", "Preventive Health and Hygiene", "Pediatric Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f9522f0a65db4cebafa50aed7dbc86366ba42d388478a00ede0ffa994cee195a', 'Schroeder Serious and fatal complications EUF 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f9522f0a65db4cebafa50aed7dbc86366ba42d388478a00ede0ffa994cee195a.pdf', 'medical_journal', 'ingested', '{"date": "2021-12-12", "description": "This retrospective study examines serious and fatal complications resulting from neonatal circumcision (NNC) treated at the Hospital for Sick Children in Toronto between 2000 and 2013. During this 14-year timeframe, 19 previously healthy neonates were admitted for severe acute complications, including massive hemorrhage, glans amputation, and Plastibell ring obstruction. Bleeding disorders like hemophilia and von Willebrand disease were newly identified in several patients. Seven infants required intensive care unit treatment, with three progressing to septic or hemorrhagic shock, resulting in two deaths.\n\nThe authors estimate an annual incidence of approximately 0.01% for severe post-circumcision complications requiring hospitalization and a 0.0012% fatality rate in the Greater Toronto Area. The paper emphasizes that life-threatening and fatal complications of NNC are not confined to developing nations and are likely underreported in Western healthcare settings, underscoring the vital need for comprehensive practitioner training and parental education on postoperative warning signs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Annette Schr\u00f6der", "Walid A. Farhat", "David Chiasson", "Gregory J. Wilson", "Martin A. Koyle", "Christian Gratzke"], "organizations": ["Hospital for Sick Children", "European Association of Urology", "Elsevier", "American Academy of Pediatrics", "Office of the Chief Coroner of Ontario"], "themes": ["Neonatal Circumcision", "Surgical Complications", "Pediatric Urology", "Postoperative Hemorrhage", "Neonatal Sepsis", "Undiagnosed Bleeding Disorders"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2bb5bf113d41e0bb94fa229f56a39a4cb284052c8b412c66062540915d001740', 'Schueklenk Europe debates circumcision Bioethics 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2bb5bf113d41e0bb94fa229f56a39a4cb284052c8b412c66062540915d001740.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This editorial examines the European debate surrounding non-therapeutic male circumcision of young boys, focusing on legal and medical developments in Germany and the Netherlands. The author argues that in liberal Western democracies, a child''s welfare and right to bodily integrity must override parental religious convictions and cultural practices when there is no uncontroversial medical benefit.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Udo Sch\u00fcklenk"], "organizations": ["Royal Dutch Medical Association", "World Health Organization", "UNAIDS", "Blackwell Publishing Ltd."], "themes": ["Male Circumcision", "Child Welfare and Bodily Integrity", "Bioethics", "Religious Freedom vs. Medical Ethics", "Legal and Medical Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f11e13f74cac43e1dfd39e482d1b21db209d1c29d243ce6c45bf8a8a3d5615b', 'Schultheiss Uncircumcision Historical_Review PlasReconSurg 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8f11e13f74cac43e1dfd39e482d1b21db209d1c29d243ce6c45bf8a8a3d5615b.pdf', 'medical_journal', 'ingested', '{"date": "2021-01-10", "description": "This document text consists entirely of an access watermark footer indicating an article or issue downloaded from the Plastic and Reconstructive Surgery journal portal hosted by Lippincott Williams & Wilkins on January 10, 2021. Due to the lack of body text, no specific medical findings, arguments, or clinical details are present.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["Lippincott Williams & Wilkins"], "themes": ["Medical Publishing", "Digital Article Distribution"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6d156621450c09d1ce9e5d80d68d34bef05e0ef558f5d413362e31e571c132f8', 'Scott Anatomy Physiol Kluwer 1999 corr.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6d156621450c09d1ce9e5d80d68d34bef05e0ef558f5d413362e31e571c132f8.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This document details the anatomy, histology, innervation, and physiological functions of the human prepuce (foreskin), challenging the view that it is a redundant or superfluous tissue. The author reviews its embryological development, vascular architecture, and dense concentration of specialized sensory receptors, particularly Meissner''s corpuscles in the ridged mucosa, which play a critical role in natural sexual sensation and biomechanics.\n\nThe text argues that routine circumcision results in the irreversible excision of highly sensitive, functional erogenous tissue and protective mucosa, leading to desensitization, glans keratinization, and the disruption of natural coital mobility and lubrication. The author advocates for increased anatomical education among medical professionals so parents can make fully informed decisions regarding infant circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Steve Scott", "George C. Denniston", "John R. Taylor"], "organizations": ["American Academy of Pediatrics", "Kluwer Academic / Plenum Publishers", "Doctors Opposing Circumcision"], "themes": ["Anatomy and Physiology of the Prepuce", "Effects of Circumcision", "Erogenous Tissue and Innervation", "Infant and Adolescent Genital Development", "Medical Education and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ae4015988f63ab5604bd6b889458885c61e576985883e17db60c66a410d41507', 'Scott Anatomy_and_Function (2007).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ae4015988f63ab5604bd6b889458885c61e576985883e17db60c66a410d41507.pdf', 'other', 'ingested', '{"date": "2007", "description": "This educational document outlines the anatomy, embryology, and physiological significance of the intact human penis, arguing that the foreskin is an essential, highly innervated, and functional organ rather than an inconsequential flap of skin. It details the development and structure of the prepuce, noting that specialized tissues like the ridged band and frenulum contain dense concentrations of fine-touch receptors and contribute to smooth, low-friction sexual mechanics while protecting the glans from keratinization and trauma.\n\nThe text contrasts intact anatomy with the effects of circumcision, presenting what it terms a ''triple whammy'' of sensitivity loss resulting from the surgical removal of nerve-dense tissue, subsequent desensitization and callousing of the exposed glans, and the elimination of the natural gliding mechanism. Citing urological studies and historical medical literature, the document argues that circumcision fundamentally alters sexual function and concludes with an overview of non-surgical foreskin restoration methods.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Morris L. Sorrells", "James L. Snyder", "Mark D. Reiss", "Christopher Eden", "Marilyn F. Milos", "Norma Wilcox", "Robert S. Van Howe", "Ranulph Fiennes", "C.J. Falliers"], "organizations": ["British Journal of Urology International", "American Medical Association", "National Organization of Restoring Men"], "themes": ["Penile Anatomy and Embryology", "Foreskin Physiology", "Effects of Male Circumcision", "Sexual Function and Sensitivity", "Foreskin Restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('649ace228cfd3d2236cd80fa023a188739d339e6e80ede35c71fbc4b1d7d38cf', 'Serody 18 million men YouGov 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/649ace228cfd3d2236cd80fa023a188739d339e6e80ede35c71fbc4b1d7d38cf.pdf', 'other', 'ingested', '{"date": "2023-10-19", "description": "This document contains a web printout header and footer for an article published on the Foregen website titled ''5 Million Men? More Than Triple That: Over 18 Million Ame...''. The document content is truncated, but the headline suggests an analysis or statistical argument regarding the population of men affected by circumcision or interested in foreskin restoration/regeneration.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Foregen"], "themes": ["Circumcision Demographics", "Men''s Health", "Foreskin Restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('87c088d8dc9a10503c5f74db2bf800cf54a9a7e4c70b87aefef099b9f6896d47', 'Serody 5 million men YouGov 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/87c088d8dc9a10503c5f74db2bf800cf54a9a7e4c70b87aefef099b9f6896d47.pdf', 'other', 'ingested', '{"date": "2021", "description": "This document contains header and URL metadata from a 10-page printout of an online article titled ''Foregen: YouGov Survey 2021 - New Data'' from Foregen''s website. The provided text consists solely of page headers, timestamps, and URLs without the substantive body text of the survey findings.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Foregen", "YouGov"], "themes": ["Public Opinion Survey", "Foreskin Regeneration", "Circumcision"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5a81e7e1391d7a26ca6c4a7da2eba6b09000119b17afbe4b7b2120a60e643e6c', 'Serwada Kigozi AIDS VMMC Cost Effect Lancet 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5a81e7e1391d7a26ca6c4a7da2eba6b09000119b17afbe4b7b2120a60e643e6c.pdf', 'medical_journal', 'ingested', '{"date": "2023-02", "description": "This commentary examines the continued cost-effectiveness of voluntary medical male circumcision (VMMC) for HIV prevention in sub-Saharan Africa against the backdrop of expanding antiretroviral therapy (ART) coverage. Reviewing a study by Loveleen Bansi-Matharu and colleagues utilizing five independent modeling frameworks across 15 countries, the authors highlight that sustaining VMMC for at least five years remains cost-effective or cost-saving and produces positive public health impacts regardless of background HIV incidence.\n\nWhile short-term benefits are consistent across models, long-term projections beyond five years remain mixed and inconclusive. The authors emphasize that discontinuing VMMC would slow progress toward epidemic control, recommending that VMMC be integrated into sustainable, government-led health programs and that its cost-effectiveness be re-evaluated as HIV incidence continues to decline.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David Serwadda", "Godfrey Kigozi", "Loveleen Bansi-Matharu"], "organizations": ["World Health Organization", "UNAIDS", "Makerere University", "Rakai Health Sciences Program", "The Lancet", "PEPFAR"], "themes": ["HIV/AIDS Prevention", "Voluntary Medical Male Circumcision (VMMC)", "Antiretroviral Therapy (ART)", "Cost-Effectiveness Analysis", "Public Health Policy in Sub-Saharan Africa"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f9b1633a346a281eafe0c779a02b946f767e217456f9a1b6b5505d16639756bb', 'Shabanzadeh Circ Complic Analysis Urology 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f9b1633a346a281eafe0c779a02b946f767e217456f9a1b6b5505d16639756bb.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This systematic review, meta-analysis, and meta-regression evaluates the risk of complications requiring additional medical treatment following male circumcision performed by healthcare professionals. Analyzing 351 studies encompassing over 4 million participants, the authors determined an overall complication risk of 3.84%. Therapeutic circumcisions performed for preexisting preputial pathology posed a more than twofold higher complication rate (7.47%) compared to nontherapeutic procedures (3.34%), with adhesions, meatal stenosis, and infections being the most frequent issues.\n\nMetaregression analyses further demonstrated that circumcision in children older than two years carried a significantly higher complication risk compared to infants. However, surgical method, type of provider, and procedural setting were not significantly associated with complication rates. The authors conclude that future research and clinical evaluations should analyze therapeutic and childhood circumcisions separately from infant and nontherapeutic procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Daniel M\u00f8nsted Shabanzadeh", "Signe Clausen", "Katrine Maigaard", "Mikkel Fode"], "organizations": ["Copenhagen University Hospital", "University of Copenhagen", "Zealand University Hospital", "Elsevier Inc."], "themes": ["Male Circumcision", "Postoperative Complications", "Urological Surgery", "Systematic Review and Meta-Analysis", "Pediatric Surgery", "Surgical Safety"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('56d2cdaa96857c7e45d7770eb4ec755b2df70e70c195328496bb8dd52f87c1bd', 'Shabanzadeh Circ Complic Frisch-Earp reply DanMedSoc 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/56d2cdaa96857c7e45d7770eb4ec755b2df70e70c195328496bb8dd52f87c1bd.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "In this critique, Morten Frisch and Brian D. Earp challenge the conclusions drawn in a systematic qualitative review by Shabanzadeh et al., which asserted that male circumcision does not result in inferior perceived male sexual function. The authors argue that this sweeping conclusion is unsupported by the reviewed literature due to severe methodological flaws, including substantial clinical heterogeneity, risk of observer and reporting bias, reliance on unvalidated questionnaires, short follow-up periods, and an inherently heteronormative focus that overlooks diverse sexual practices.\n\nFrisch and Earp also criticize the review''s conflation of voluntary adult and therapeutic circumcisions with non-therapeutic circumcision performed on minors without their consent. They contend that sexual outcomes from adult surgeries\u2014driven by specific personal motivations and lacking long-term tracking\u2014cannot be mapped onto infant circumcisions, where individuals lack a baseline for comparison. Consequently, they conclude that Shabanzadeh et al.''s broad generalizations obscure crucial individual variance and fail to address the core ethical debate regarding non-therapeutic circumcision in underage boys.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morten Frisch", "Brian D. Earp", "D. M. Shabanzadeh", "S. D\u00fcring", "C. Frimodt-M\u00f8ller"], "organizations": ["Statens Serum Institut", "Aalborg University", "The Hastings Center Bioethics Research Institute"], "themes": ["Male Circumcision", "Sexual Function", "Bioethics and Medical Ethics", "Pediatric Surgery and Consent", "Methodological Bias in Systematic Reviews"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7a20bce1565bec9009beaa35fe7dd1cb63dd7c2c03eb5cc386ed429018a0f118', 'Shabanzadeh InferiorSex DanishMedJ 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7a20bce1565bec9009beaa35fe7dd1cb63dd7c2c03eb5cc386ed429018a0f118.pdf', 'medical_journal', 'ingested', '{"date": "2016-07", "description": "This systematic review assesses the impact of male circumcision, medical indication, and age at circumcision on perceived adult male sexual function across 38 included studies, comprising 36 observational studies and two randomized controlled trials. The authors found that non-medical circumcision was not associated with inferior sexual function, showing instead decreased premature ejaculation and increased penile sensitivity.\n\nWhile medical circumcisions were associated with higher difficulty in achieving orgasm and inconsistent reports of erectile dysfunction, these outcomes are likely confounded by pre-existing penile pathologies rather than the surgery itself. Overall, the review concludes that the prevailing narrative that male circumcision leads to sexual dysfunction is unsupported by high-level evidence, though further controlled research on age at circumcision and medical indications is warranted.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Daniel M\u00f8nsted Shabanzadeh", "Signe D\u00fcring", "Cai Frimodt-M\u00f8ller"], "organizations": ["Danish Medical Journal", "Bispebjerg Hospital", "University of Copenhagen", "Mental Health Services of the Capital Region of Denmark", "CFR Hospitals", "Danish College of General Practitioners", "Danish Health Authorities"], "themes": ["Male Circumcision", "Male Sexual Function", "Erectile Dysfunction", "Premature Ejaculation", "Systematic Review", "Evidence-Based Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9d97fbe21b6cdb5e468c2313f1726284c1ac2a56841c419b64648c3744f8562b', 'Shahid Phimosis in Children ISRN Urol 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9d97fbe21b6cdb5e468c2313f1726284c1ac2a56841c419b64648c3744f8562b.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This review article examines phimosis in children, emphasizing the critical distinction between normal physiological phimosis and pathological phimosis. While nonretractable foreskin is natural in infants and toddlers due to congenital adhesions, physician misdiagnosis frequently leads to excessive parental anxiety and unnecessary referrals for surgical circumcision. The author underscores the physiological, immunologic, and sensory functions of the prepuce, advocating for increased physician education and the adoption of noninvasive or conservative medical treatments over conventional circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sukhbir Kaur Shahid", "T. Okamura", "V. Tzortzis"], "organizations": ["International Scholarly Research Network", "Shahid Medical Centre"], "themes": ["Pediatric Urology", "Physiological vs. Pathological Phimosis", "Circumcision", "Penile Anatomy and Development", "Conservative Medical Treatment"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dfebebaf8e244b820391fd783462e07bc6b569d1e094f37014a12ebd5ad8008f', 'Shahvisi Earp law_and_ethics_FGM 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dfebebaf8e244b820391fd783462e07bc6b569d1e094f37014a12ebd5ad8008f.pdf', 'other', 'ingested', '{"date": "2019", "description": "This chapter examines the ethical, legal, and conceptual inconsistencies surrounding nontherapeutic female genital cutting (FGC), female genital cosmetic surgeries (FGCS), and male genital cutting (MGC). Using the United Kingdom''s Female Genital Mutilation Act 2003 as a primary case study, the authors argue that the legal and cultural categories separating ''mutilation'' from ''cosmetic surgery'' are medically arbitrary and functional rather than scientific. Despite involving anatomically identical or similar procedures, practices categorized as FGM are strictly criminalized regardless of consent or age, whereas Western FGCS is permitted under vague mental health exceptions, and medically unnecessary infant male circumcision and intersex surgeries remain virtually unregulated.\n\nThe authors analyze the motivations, risks, and cultural contexts of these procedures, challenging common Western assumptions that non-Western FGC is uniquely misogynistic or coercive while FGCS is an autonomous personal choice. They suggest that prevailing Western laws and attitudes are deeply influenced by racial, gender, and post-colonial biases rather than coherent ethical frameworks. Ultimately, the chapter proposes reforming legislation to prioritize bodily integrity and informed consent, recommending that nontherapeutic genital modifications be prohibited on all non-consenting minors while being legally permitted and clinically regulated for consenting adults.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Arianne Shahvisi", "Brian D. Earp", "Sarah Creighton", "Lih-Mei Liao"], "organizations": ["Cambridge University Press", "World Health Organization", "UNICEF", "British Medical Association"], "themes": ["Female Genital Cutting (FGC)", "Female Genital Cosmetic Surgery (FGCS)", "Male Circumcision", "Genital Autonomy and Bodily Integrity", "Medical Ethics and Law", "Cultural Double Standards and Biopolitics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('985f085327c02a34fc39c8ce80e34dbad6ff4bf2b0225b95d3827195c43893a7', 'Shaw Circ and ConsObjectn ClinEthics 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/985f085327c02a34fc39c8ce80e34dbad6ff4bf2b0225b95d3827195c43893a7.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This paper critically analyzes guidelines issued by the General Medical Council (GMC) and the British Medical Association (BMA) regarding non-therapeutic circumcision (NTC) of male minors. Author David Shaw argues that it is ethically and logically flawed to require physicians who refuse to perform clinically unnecessary, irreversible surgery on non-consenting infants to invoke ''conscientious objection.'' Instead, an objective application of standard consent procedures and the child''s best interests test naturally leads to refusing the procedure.\n\nThe author contends that both sets of guidance improperly compromise objective best interests evaluations to accommodate parental religious preferences, which subverts standard medical ethics and potentially exposes practitioners to legal liability for negligence or human rights violations under the Human Rights Act. Shaw concludes that both the GMC and BMA guidelines must be substantially revised to uphold medical non-maleficence, protect the bodily integrity and future autonomy of the child, and eliminate the misguided reliance on conscientious objection for refusing non-therapeutic procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["David Shaw"], "organizations": ["General Medical Council", "British Medical Association", "University of Glasgow", "Norwegian Council for Medical Ethics", "English Law Commission"], "themes": ["Non-therapeutic Circumcision", "Medical Ethics and Bioethics", "Informed Consent and Best Interests", "Conscientious Objection", "Children''s Rights and Autonomy", "Medical Negligence and Human Rights Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c38652e5a5a6ad2e0bf97e08f1c5e9aa2c066f61bad0a511c3597b4bc0eb4034', 'Shweder Equality Now Earp KIJE 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c38652e5a5a6ad2e0bf97e08f1c5e9aa2c066f61bad0a511c3597b4bc0eb4034.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "In this commentary, Richard A. Shweder responds to Brian Earp\u2019s exploration of moral consistency regarding genital reshaping procedures for males and females across cultural contexts. Shweder examines Earp''s proposed ''enhancement principle,'' which establishes an autonomy-based presumption against nonvoluntary genital modifications unless judged by an impartial observer to advance the individual''s overall well-being. Shweder probes the practical and theoretical limits of this principle by presenting three cultural scenarios: customary Kenyan adolescent male circumcision, voluntary female genital cosmetic surgery and traditional modification, and Jewish neonatal circumcision.\n\nShweder contends that genuine impartiality is difficult to detach from historical and social contexts, arguing that physical integrity and aesthetic well-being are often culturally achieved rather than universally fixed at birth. He critiques Western anti-FGM advocacy and media coverage for asymmetrical stereotyping, factual inaccuracies regarding sexual dysfunction, and double standards that condemn traditional African practices while tolerating Western cosmetic surgeries and infant male circumcision. Shweder concludes that respect for religious freedom, ancestral tradition, and cultural pluralism must inform moral assessments alongside individual autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Richard A. Shweder", "Brian Earp", "Fuambai S. Ahmadu"], "organizations": ["Kennedy Institute of Ethics", "Johns Hopkins University Press"], "themes": ["Genital Reshaping", "Bioethics and Moral Philosophy", "Cultural Pluralism vs. Universalism", "Male and Female Circumcision", "Autonomy and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bb1382290d7ab9523cf72a71ca5144dd3c3762e88a954a5c51bdc35c41c1a497', 'Shweder GooseGander-Genital Wars GlobDisc 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bb1382290d7ab9523cf72a71ca5144dd3c3762e88a954a5c51bdc35c41c1a497.pdf', 'other', 'ingested', '{"date": "2013", "description": "In this academic article, cultural anthropologist Richard A. Shweder examines the global debates and ethical tensions surrounding genital modifications in males and females, framed by a 2012 German court ruling that criminalized non-therapeutic male circumcision. Shweder contrasts divergent regional perspectives on gender equity: European movements advocating the prohibition of both male and female modifications; American norms that permit male circumcision while criminalizing female modifications; and traditions in several African societies that treat both as complementary, gender-inclusive rites of passage into adulthood. Shweder critiques Western anti-FGM advocacy and media coverage, arguing that popular assertions regarding universal sexual impairment and extreme medical harm are contradicted by rigorous empirical studies. He highlights the hypocrisy between the demonization of traditional African genital surgeries and the Western acceptance of female genital cosmetic surgeries. Ultimately, Shweder cautions against dogmatic, inflammatory rhetoric that suppresses evidence, undermines cultural pluralism, and threatens the religious and cultural freedoms of minority communities, including Jews, Muslims, and African ethnic groups.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Richard A. Shweder", "Shaye Cohen", "Fuambai Ahmadu", "Jomo Kenyatta", "Sander Gilman", "Lisa Wade", "Ayaan Hirsi Ali"], "organizations": ["University of Chicago", "Royal Dutch Medical Association (KNMG)", "United Nations", "American Academy of Pediatrics", "The Hastings Center", "Medical Research Council"], "themes": ["Male Circumcision", "Female Genital Cutting", "Gender Equity", "Cultural Pluralism", "Media Bias and Rhetoric", "Religious Freedom and Minority Rights", "Cosmetic Genital Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5ed62c24550e758b97683454947d4d6dd0a500bb1264c2eb9b58496aa7c8bf9b', 'Sibiya Ethical Aspects Circ SAfrica 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5ed62c24550e758b97683454947d4d6dd0a500bb1264c2eb9b58496aa7c8bf9b.pdf', 'other', 'ingested', '{"date": "2014-04", "description": "This academic thesis examines the ethical and public health dilemmas surrounding traditional male circumcision (TMC) in South Africa, focusing primarily on the practices and outcomes among Xhosa initiates in the Eastern Cape. It investigates the crisis of severe, preventable medical complications\u2014including hospitalizations, penile amputations, and deaths\u2014alongside the friction between democratic government regulation and traditional custodianship.\n\nEvaluating the ritual through bioethical frameworks such as beneficence, non-maleficence, and individual autonomy versus communitarian ethics, the author contends that TMC in its current form constitutes a net harm. However, arguing that these defects are remediable without abandoning the ritual''s vital cultural and social significance, the study advocates for collaborative societal and public health interventions, such as incorporating medically trained personnel to perform the surgical excision within traditional settings.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sydney Langelihle Sibiya", "Anton A. van Niekerk", "Thando Mgqolozana", "Kwame Gyekye", "Chief Mwelo Nonkonyane", "Loretta M. Kopelman", "Jeffrey Bishop"], "organizations": ["University of Stellenbosch", "Centre for Applied Ethics", "British Medical Association", "American Academy of Paediatrics", "World Health Organization"], "themes": ["Traditional Male Circumcision (TMC)", "Biomedical Ethics", "Public Health Intervention", "Cultural Relativism vs. Universal Norms", "HIV Transmission and Prevention", "Autonomy and Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('92a301978b1b33320bdbde4a40af245d108ef12d33790e15721dd524091314d3', 'Sidler Neonatal_circ_not_reduce_HIV SAMJ 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/92a301978b1b33320bdbde4a40af245d108ef12d33790e15721dd524091314d3.pdf', 'medical_journal', 'ingested', '{"date": "2008-10", "description": "This opinion piece argues against the promotion of non-therapeutic neonatal and mass male circumcision as a public health strategy for HIV/AIDS prevention in Africa. The authors assert that the evidence supporting circumcision''s protective efficacy is overblown and derived from flawed or narrowly contextual randomized controlled trials, noting that international data\u2014such as high STD rates in the heavily circumcised United States\u2014demonstrates that circumcision is ineffective at controlling sexually transmitted infections.\n\nFurthermore, the authors highlight significant medical, ethical, and cultural risks associated with infant circumcision, including surgical complications, loss of bodily autonomy, ethical concerns surrounding proxy consent, and the potential to undermine condom usage by fostering a false sense of security. They contend that resources would be far better allocated toward proven ''social vaccines'' such as education, female empowerment, and consistent condom use.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["D Sidler", "J Smith", "H Rode"], "organizations": ["Joint United Nations Programme on HIV/AIDS", "World Health Organization", "Tygerberg Children''s Hospital", "United South African Neonatal Association", "Red Cross War Memorial Children''s Hospital", "Centers for Disease Control", "Cochrane Collaboration", "Australian Federation of AIDS Organizations", "Royal Australasian College of Physicians", "Conseil National du SIDA"], "themes": ["Neonatal Circumcision", "HIV/AIDS Prevention", "Medical Ethics and Human Rights", "Public Health Policy", "Informed Consent", "Sexual and Reproductive Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c81dfb34ce9487a7f799e66a5dff4be626fe56c41bfbe4393f1c0d6cae33dc69', 'Siebeck Law_Early Judaism 2019 (paper).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c81dfb34ce9487a7f799e66a5dff4be626fe56c41bfbe4393f1c0d6cae33dc69.pdf', 'other', 'ingested', '{"date": "2019", "description": "This academic chapter examines the rhetoric and legal discourse surrounding the 2012 Cologne regional court (Landgericht K\u00f6ln) decision, which classified non-therapeutic, religiously motivated male infant circumcision as criminal bodily assault. Author Michael Peppard traces the tensions between law and liberty from early Christian Pauline discourse in Galatians to modern European legal debates. He argues that modern secular opponents of circumcision evaluate religious rituals through an individualistic, disembodied framework rooted in Enlightenment-era Protestant assumptions regarding informed consent and religious choice.\n\nFurthermore, the essay investigates the disturbing resurgence of historical anti-Semitic tropes within modern German legal literature, specifically critiquing scholars such as Holm Putzke and Reinhard Merkel who analogize circumcision to punishment, mutilation, and disease while dismissing Jewish communal continuity. Peppard advocates for the necessity of post-Holocaust hermeneutics in German legal and ethical deliberations, emphasizing that the Bundestag''s eventual statutory protection of infant circumcision rightfully accounted for the historical imperative of preserving Jewish ritual life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Michael Peppard", "David Lincicum", "Ruth Sheridan", "Charles M. Stang", "Holm Putzke", "Reinhard Merkel", "Jan F. Orth", "Charlotte Knobloch", "Angela Merkel"], "organizations": ["Mohr Siebeck", "Landgericht K\u00f6ln", "Bundestag", "Deutscher Ethikrat", "Evangelical Church in Germany (EKD)"], "themes": ["Religious Liberty", "Infant Circumcision", "Bodily Integrity and Informed Consent", "Anti-Semitism", "Post-Holocaust Hermeneutics", "Pauline Theology and Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8e570f7f67918d32b0fc5447978eb388585e1c27d397837d9c008c1c11ecd617', 'Silverman Anthropology & Circ AnnRevAnthrop 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8e570f7f67918d32b0fc5447978eb388585e1c27d397837d9c008c1c11ecd617.pdf', 'other', 'ingested', '{"date": "2004-06-16", "description": "This review surveys a century of anthropological research on male and female circumcision, tracing classical sociocultural, symbolic, and psychoanalytic interpretations alongside historical, biblical, and Jewish traditions. It addresses contemporary public health research indicating that male circumcision reduces HIV transmission risks in sub-Saharan Africa, while analyzing the intense moral, legal, and political debates surrounding female genital cutting. The author contrasts Western anti-female circumcision activism\u2014which often depicts African and Muslim women as passive victims of brute patriarchy\u2014with ethnographic evidence highlighting female agency, local aesthetic ideals, and cultural idioms of purity.\n\nAdditionally, the article critically examines the rising and aggressive Western activist movement opposing routine neonatal and ritual male circumcision on human rights, bodily integrity, and psychological grounds. The author argues that circumcision debates expose an epistemological and ethical crisis within anthropology, challenging the discipline to re-evaluate the boundaries between cultural relativism, objective empirical science, and universal human rights advocacy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Eric K. Silverman", "Janice Boddy", "Fuambai Ahmadu", "Richard A. Shweder", "Alice Walker", "Pat Schroeder"], "organizations": ["DePauw University", "Annual Reviews", "World Health Organization", "National Organization of Circumcision Information Resource Centers"], "themes": ["Male Circumcision", "Female Genital Cutting", "Cultural Relativism vs. Human Rights", "Gender and Body Symbolism", "HIV/AIDS Prevention", "Genital Integrity Activism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1e41a6e9926562c30030c07706f9dff14a85e2fae0f66749cc35412dab23513', 'Simkovich Interpretations_of_Abrahams_Circumcision (paper, no date).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1e41a6e9926562c30030c07706f9dff14a85e2fae0f66749cc35412dab23513.pdf', 'other', 'ingested', '{"date": null, "description": "This academic paper examines how early Christian theologians and the rabbinic authors of Genesis Rabbah interpreted Abraham''s circumcision and its relationship to ongoing Israelite circumcision. Beginning with the Apostle Paul, early Christian writers\u2014including Justin Martyr, Tertullian, Origen, John Chrysostom, and Syriac authors such as Aphrahat and Ephrem\u2014systematically decoupled Abraham''s circumcision from Mosaic law. By framing Abraham''s circumcision as a sign of faith or a prefiguration of Christ while reinterpreting Israelite circumcision as an allegorical misunderstanding, a preventive measure against pagan intermarriage, or a mark of divine punishment and exclusion, early Christians claimed Abraham as a proto-Christian forefather while distancing themselves from Jewish identity.\n\nIn response to these Christian typological claims, fifth-century rabbinic exegesis in Genesis Rabbah bound Abraham''s circumcision inextricably to the covenantal election of the Jewish people. The midrashic narratives countered Christian polemics by portraying Abraham''s act as an essential prerequisite for holy lineage and covenantal continuity. The author concludes that these intense theological disputes reflected ongoing social and religious ambiguities in late antiquity, where blurry communal boundaries and persistent Judaizing trends prompted leaders on both sides to use circumcision as a pivotal tool for identity demarcation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Malka Z. Simkovich", "Paul the Apostle", "Abraham", "Justin Martyr", "Tertullian", "Irenaeus", "Origen", "John Chrysostom", "Aphrahat", "Theodoret of Cyrrhus", "Ephrem the Syrian", "Augustine", "Martin Luther"], "organizations": ["Brandeis University", "Council of Laodicea"], "themes": ["Early Christianity and Rabbinic Judaism", "Biblical Exegesis and Typology", "The Theology of Circumcision", "Abrahamic Covenant and Forefatherhood", "Religious Demarcation and Judaizing", "Patristic and Midrashic Literature"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a3ab31c859d89acd9ad16e799a19b86246872e49a8656f27a99c1e5b297f53fa', 'Siroosbakht Comparison Complications HlthSciRep 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a3ab31c859d89acd9ad16e799a19b86246872e49a8656f27a99c1e5b297f53fa.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This retrospective cohort study evaluated and compared the frequency and relative risk of early and late complications of surgical circumcision between 240 neonates and 240 children aged 3\u20135 years treated in Tehran, Iran between 2015 and 2021. All circumcisions were conducted using the surgical dorsal-ventral slit method by a single urologist.\n\nThe study found that the overall rate of complications was significantly higher in neonates (16.7%) than in children (8.8%), presenting an overall relative risk of 2.6. Bleeding was the most frequent early complication, while meatal stenosis was the most common late complication across both cohorts. Notably, neonates exhibited a significantly higher risk of meatal stenosis, meatal web, and incomplete prepuce removal, highlighting the need for healthcare providers to comprehensively educate parents regarding age-related risks when deciding on the timing of circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Soheila Siroosbakht", "Bijan Rezakhaniha"], "organizations": ["AJA University of Medical Sciences", "Golestan Hospital", "Imam Reza Hospital", "Wiley Periodicals LLC"], "themes": ["Male Circumcision", "Pediatric Urology", "Postoperative Complications", "Meatal Stenosis", "Neonatal vs. Child Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('075fc5e5d9e3a7dc285eb06ff63c0fd07fa7dd7e2269995ce691329421bbfa93', 'Sloth-Nielson Foreskin too far LawDemDev 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/075fc5e5d9e3a7dc285eb06ff63c0fd07fa7dd7e2269995ce691329421bbfa93.pdf', 'legal_document', 'ingested', '{"date": "2012", "description": "This article examines the regulation of male circumcision in South Africa under the Children''s Act 38 of 2005, various provincial enactments, and international human rights frameworks such as the UN Convention on the Rights of the Child and the African Charter on the Rights and Welfare of the Child. Originally conceived to curb deaths and injuries from botched traditional initiations and address potentially harmful cultural practices, the statutory framework established strict consent requirements, age limits (setting a baseline at 16 years), and health standards across traditional, medical, and religious circumcisions.\n\nThe author argues that the legal framework has been complicated by subsequent public health policies that promote male circumcision as an effective measure to prevent HIV transmission. This shift has led to international and domestic campaigns advocating mass circumcision for adult men and infants, directly conflicting with the restrictive legal provisions of the Children''s Act. The article concludes that the legislation may have been premature and overly intrusive, particularly in attempting to regulate religious circumcision and setting high age hurdles for consent, suggesting a need for statutory amendments to harmonize child protection law with emerging public health imperatives.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Fidel Hadebe", "King Mswati III"], "organizations": ["South African Law Reform Commission", "National Council of Provinces", "World Health Organization", "UNAIDS", "PEPFAR", "KwaZulu Natal Department of Health", "Family Health International"], "themes": ["Male Circumcision", "Children''s Rights", "Harmful Cultural Practices", "HIV/AIDS Prevention", "Customary Law vs. Public Health Policy", "Legal Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6dce78b60f7ec941cea6be34bfc02f141e058c7d3be2387b156e17a1b51af0a2', 'Smith Male Circumcision and Rights of the Child 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6dce78b60f7ec941cea6be34bfc02f141e058c7d3be2387b156e17a1b51af0a2.pdf', 'legal_document', 'ingested', '{"date": "1998", "description": "This academic paper examines routine and ritual male circumcision through the lens of international human rights law and the rights of the child, contrasting its social and legal acceptance with the widespread condemnation of female genital mutilation (FGM). Drawing upon treaties such as the UN Convention on the Rights of the Child, the Universal Declaration of Human Rights, and the Convention against Torture, the author argues that non-therapeutic infant male circumcision involves the non-consensual removal of healthy tissue and carries unnecessary risks of medical complications, pain, and trauma.\n\nThe author identifies a Western double standard that strictly prohibits female genital procedures while tolerating or medicalizing male circumcision based on tradition, religion, or contested health claims. The article concludes that children''s fundamental rights to bodily integrity, health, and protection from harm should supersede parental and cultural prerogatives, recommending that permanent genital modifications be postponed until an individual reaches the age of consent to make an autonomous, informed decision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Jacqueline Smith", "Peter Baehr", "Hanny Lightfoot-Klein", "Fran P. Hosken", "Nadia Toubia", "Philip E. Veerman"], "organizations": ["Netherlands Institute of Human Rights (SIM)", "University of Utrecht", "United Nations", "American Academy of Pediatrics (AAP)", "British Medical Association (BMA)", "Defence for Children International", "Organisation of African Unity"], "themes": ["Male Circumcision", "Children''s Rights", "Bodily Integrity", "Female Genital Mutilation Comparison", "International Human Rights Law", "Parental Rights vs. Child Autonomy", "Cultural Relativism vs. Universal Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('463efaac6f635ff2145045a53e5eaa18577e68c579d8196fb95f3f448b3d4401', 'Sneppen Foreskin morbidity Peds 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/463efaac6f635ff2145045a53e5eaa18577e68c579d8196fb95f3f448b3d4401.pdf', 'medical_journal', 'ingested', '{"date": "2016-05-01", "description": "This study evaluates the incidence and morbidity of medically indicated foreskin surgery among boys aged 0 to 17 in the Capital Region of Denmark during 2014, a region with a strong culture of foreskin preservation. Out of 181 boys who underwent therapeutic foreskin surgery, the cumulative risk of having a foreskin procedure before age 18 was determined to be 1.66%, with phimosis being the most common indication (95.0%). Additionally, 40 patients had histologically confirmed balanitis xerotica obliterans (BXO), translating to a 0.37% risk in the birth cohort.\n\nPostoperative complications occurred in nearly a quarter of patients, with recurrent phimosis being the most frequent issue and 5.5% requiring redo-surgery. The authors argue that foreskin morbidity in uncircumcised populations is non-negligible, and these epidemiological risks and clinical outcomes should be considered in broader discussions and parental counseling regarding the benefits and drawbacks of newborn male circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ida Sneppen", "J\u00f8rgen Thorup"], "organizations": ["American Academy of Pediatrics", "Rigshospitalet", "University of Copenhagen"], "themes": ["Pediatric Urology", "Foreskin Morbidity", "Male Circumcision Debate", "Phimosis", "Balanitis Xerotica Obliterans (BXO)"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c063168946ed399b2d1b393fd5b5d65561ac52f99f320146f7c6ea7ac089d747', 'Soloman Informed Consent A Proposal NYLawRev 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c063168946ed399b2d1b393fd5b5d65561ac52f99f320146f7c6ea7ac089d747.pdf', 'legal_document', 'ingested', '{"date": "2007", "description": "This article examines whether U.S. hospitals and physicians satisfy legal standards of informed consent when performing routine, non-religious infant circumcisions. Analyzing the patient-centered disclosure framework established in case law such as Canterbury v. Spence, the author argues that current hospital practices routinely fail to provide adequate information. Parents are frequently left uninformed regarding penile anatomy, the lifelong protective and sensory functions of the foreskin, the severe pain involved, the rarity or treatability of conditions circumcision purports to prevent, and potential institutional financial interests in harvested tissue.\n\nTo correct these deficiencies, the author proposes a rigorous informed consent model requiring truthful disclosures of the anatomical consequences of foreskin amputation, discussion of non-surgical alternatives, elimination of coercive consent practices around childbirth, and visual depictions of the procedure. Drawing parallels to the LGBT rights movement''s advocacy for bodily and sexual autonomy, the author critically addresses recent public health initiatives promoting circumcision for HIV prophylaxis, asserting that infant circumcision fundamentally infringes upon individual autonomy without medical necessity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["David Solomon", "Ryan McAllister", "Paul M. Fleiss", "Thomas E. Wiswell", "John S. Wiener"], "organizations": ["New York Law School", "Lesbian, Gay, Bisexual and Transgender Law Association Foundation of Greater New York", "American Academy of Pediatrics", "American Medical Association", "Duke University Health System", "North Carolina Women''s Hospital", "New York University Medical Center", "Northwestern Memorial Hospital"], "themes": ["Informed Consent", "Routine Infant Circumcision", "Medical Ethics and Malpractice", "Patient and Parental Autonomy", "HIV/AIDS Prevention", "LGBT Rights and Sexual Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5ce696c0512ed3b79287b79ac9fc1a01d501f77b6ff6c15db89a3b51a89a9ede', 'Solursh Physicians Lack HumSexEd IntJImpotRes 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5ce696c0512ed3b79287b79ac9fc1a01d501f77b6ff6c15db89a3b51a89a9ede.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This study evaluated human sexuality education across 141 accredited medical schools in the United States and Canada to determine how adequately future physicians are prepared to address sexual health issues. Based on 101 responses, the authors found that while the vast majority of institutions addressed topics like the causes and treatments of sexual dysfunction, most education was limited to lecture formats offering only 3 to 10 total hours of instruction. Psychiatry was the discipline most frequently involved, and nearly two-thirds used a multidisciplinary teaching approach.\n\nDespite high patient need and recommendations from the 1993 NIH Consensus Statement on Impotence, fewer than half of the surveyed schools offered dedicated clinical programs for treating sexual dysfunction, and only 55.5% provided supervised clinical clerkship experiences. The authors conclude that North American medical schools must expand and standardize their human sexuality curricula\u2014integrating clinical skills, attitude self-examination, and continuing medical education\u2014to meet public demand for knowledgeable and comfortable healthcare providers.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["DS Solursh", "JL Ernst", "RW Lewis", "L Michael Prisant", "TM Mills", "LP Solursh", "RG Jarvis", "WH Salazar", "Harold Lief"], "organizations": ["Medical College of Georgia", "National Institutes of Health", "Association of American Medical Colleges", "Universit\u00e9 de Sherbrooke"], "themes": ["Human Sexuality Education", "Medical School Curriculum", "Sexual Dysfunction", "Clinical Training and Clerkships", "Continuing Medical Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d327d0aa95c67a510689f76cab0fc5af5802da0d287b72acacd45d6c6b27844c', 'Somerville Ltr to JusticeMin 1992.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d327d0aa95c67a510689f76cab0fc5af5802da0d287b72acacd45d6c6b27844c.pdf', 'letter', 'ingested', '{"date": "1992-06-10", "description": "This document is an extract from a letter written by Dr. Margaret A. Somerville to the Minister of Justice of Canada examining the legal justifications surrounding male and female circumcision under the Criminal Code. She questions the prevailing legal inconsistency where male circumcision is treated as permissible while female circumcision is deemed illegal, given that no express statutory provisions govern either practice.\n\nDr. Somerville argues that any bodily wounding is prima facie illegal without therapeutic justification or informed consent, neither of which applies to infant male circumcision. She casts doubt on whether male circumcision can still be excused as causing ''de minimis'' harm or justified solely on grounds of parental religious and cultural freedom, concluding that if all forms of female circumcision are rightly prohibited, continuing to legally permit infant male circumcision becomes difficult to defend.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Margaret A. Somerville"], "organizations": ["McGill University", "McGill Centre for Medicine, Ethics and Law", "Department of Justice Canada"], "themes": ["Male Circumcision", "Female Genital Mutilation / Female Circumcision", "Bioethics and Medical Law", "Informed Consent", "Criminal Law and Prima Facie Wounding"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6d372b43cdcbf28fa189c7886fc8869a34bddc0347322ffab67226c8ac543039', 'Sorokan newborn male circ PaedChildHealth 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6d372b43cdcbf28fa189c7886fc8869a34bddc0347322ffab67226c8ac543039.pdf', 'policy_guideline', 'ingested', '{"date": "2015-09-08", "description": "This position statement by the Canadian Paediatric Society evaluates the medical evidence regarding newborn male circumcision. While the review identifies potential health benefits\u2014including reduced risks of urinary tract infections, certain sexually transmitted infections such as HIV, and penile cancer\u2014it concludes that the overall medical risk-benefit ratio is closely balanced. Consequently, the Society does not recommend routine circumcision for all male newborns, though it notes potential utility in specific high-risk populations.\n\nThe document highlights clinical, ethical, and legal considerations surrounding neonatal circumcision, emphasizing that the procedure involves non-therapeutic surgery on an individual unable to provide consent. It advises healthcare providers to offer unbiased, up-to-date information to parents so they can make informed choices based on familial, cultural, and religious values, while stressing the necessity of skilled practitioners, proper analgesia, and appropriate care guidance for both circumcised and uncircumcised boys.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["S Todd Sorokan", "Jane C Finlay", "Ann L Jefferies", "Thierry Lacaze", "Joan L Robinson"], "organizations": ["Canadian Paediatric Society", "American Academy of Pediatrics", "Public Health Agency of Canada", "Centers for Disease Control and Prevention"], "themes": ["Neonatal Male Circumcision", "Urinary Tract Infection Prevention", "STI and HIV Transmission Reduction", "Medical Ethics and Informed Consent", "Surgical Risks and Postprocedural Care"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('35ad1be0edf721c6ef7506f0d0eb147a1d86c565e58250b9ba7fa182e783f4fc', 'Sorrells Fine touch BJUI 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/35ad1be0edf721c6ef7506f0d0eb147a1d86c565e58250b9ba7fa182e783f4fc.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This clinical study maps and compares the fine-touch pressure thresholds across 19 penile locations in circumcised and uncircumcised adult men using calibrated Semmes-Weinstein monofilaments. After controlling for confounding variables such as age, ethnicity, underwear type, and time since last ejaculation, researchers found that the glans of circumcised men had significantly higher pressure thresholds, indicating lower sensitivity to fine touch compared to uncircumcised men.\n\nAdditionally, the study revealed that the most sensitive areas on the intact penis\u2014specifically regions of the prepuce such as the ridged band and preputial orifice rim\u2014are completely excised during circumcision. In circumcised men, the most sensitive location was the ventral circumcision scar, which remained less sensitive than several preputial sites present on the intact penis, leading the authors to conclude that circumcision removes the most sensitive parts of the penis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Morris L. Sorrells", "James L. Snyder", "Mark D. Reiss", "Christopher Eden", "Marilyn F. Milos", "Norma Wilcox", "Robert S. Van Howe"], "organizations": ["BJU International", "National Organization of Circumcision Information Resource Centers", "Michigan State University College of Human Medicine", "Western Institutional Review Board"], "themes": ["Male Circumcision", "Penile Somatosensory Sensitivity", "Fine-Touch Pressure Thresholds", "Sexual Medicine", "Anatomy and Neurophysiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('37713eb036ea093f47d121f9e76c9e15e43b3d3a3a995a6b5080bb6993fa5e2e', 'Spence Circumcision_prostate_cancer BJU Intl 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/37713eb036ea093f47d121f9e76c9e15e43b3d3a3a995a6b5080bb6993fa5e2e.pdf', 'medical_journal', 'ingested', '{"date": "2014", "description": "This study analyzes data from the Prostate Cancer and Environment Study (PROtEuS), a large population-based case-control study conducted in Montr\u00e9al, Canada, comprising 1,555 prostate cancer cases and 1,586 controls. The researchers investigated whether male circumcision, the timing/age of circumcision, and racial ancestry influence the risk of developing prostate cancer while controlling for confounders such as age, screening history, family history, and sexually transmitted infection (STI) history.\n\nOverall, circumcised men exhibited a slightly reduced risk of prostate cancer that did not reach statistical significance. However, a statistically significant protective effect was identified among men circumcised at age 36 or older and among Black men, who had a 60% reduction in risk compared to uncircumcised peers. A slight protective trend was also observed for neonatally circumcised men. The authors conclude that circumcision may confer protection against prostate cancer in specific subgroups\u2014particularly Black men, who face disproportionately higher baseline rates of the disease\u2014warranting further epidemiological and mechanistic investigation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Andrea R. Spence", "Marie-Claude Rousseau", "Pierre I. Karakiewicz", "Marie-\u00c9lise Parent"], "organizations": ["INRS-Institut Armand-Frappier", "Universit\u00e9 du Qu\u00e9bec", "University of Montr\u00e9al", "University of Montr\u00e9al Hospital Research Centre (CRCHUM)", "BJU International", "Canadian Cancer Society", "Canadian Institutes for Health Research"], "themes": ["Prostate Cancer", "Male Circumcision", "Epidemiology", "Racial Disparities in Oncology", "Sexually Transmitted Infections", "Preventive Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f49f90f33ca4578ff9f8f7372235d8453e69601038a7a13afd97ca8fb7a9facf', 'Spence Men Matter Too BritJGenPrac 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f49f90f33ca4578ff9f8f7372235d8453e69601038a7a13afd97ca8fb7a9facf.pdf', 'medical_journal', 'ingested', '{"date": "2019-10", "description": "In this commentary, the author argues against non-therapeutic male infant circumcision, comparing it to female genital mutilation and calling it an infringement on a child''s human rights and bodily autonomy. He contends that non-medical circumcision offers no health benefits while posing physical and emotional risks, and criticizes regulatory bodies such as the General Medical Council (GMC) and parliament for failing to challenge or restrict the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Des Spence"], "organizations": ["General Medical Council", "Maryhill Health Centre", "Parliament", "British Journal of General Practice"], "themes": ["Male Circumcision", "Medical Ethics", "Children''s Rights and Consent", "Genital Mutilation", "Regulatory Accountability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('31437f98532402518848a1d70f25603f61f1be65b9d036374e6cc99da14879a2', 'Spinelli Circumcision Decision HFordHospMedJ 1988.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/31437f98532402518848a1d70f25603f61f1be65b9d036374e6cc99da14879a2.pdf', 'medical_journal', 'ingested', '{"date": "1988", "description": "This article examines the medical, cultural, and ethical considerations surrounding routine neonatal circumcision in the United States. Despite official stances from the American Academy of Pediatrics and the American College of Obstetricians and Gynecologists stating that routine circumcision lacks absolute medical indications, the procedure remains widespread. The author reviews purported medical benefits\u2014such as reductions in penile cancer, sexually transmitted diseases, phimosis, and urinary tract infections\u2014and weighs them against surgical complications, procedural pain, and significant physiological stress in neonates.\n\nSpinelli emphasizes that most parents choose circumcision based on social conventions, aesthetic preferences, or misinformation rather than informed medical evaluation. She highlights studies showing that structured educational interventions, such as informational counseling and videotapes, markedly reduce circumcision rates and improve understanding. The article concludes with a plea for health care professionals to provide thorough counseling so parents achieve genuine informed consent, recognizing that the procedure is undertaken for social or religious reasons rather than medical necessity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Theresa Spinelli"], "organizations": ["Henry Ford Hospital", "American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "University of Michigan Medical School"], "themes": ["Neonatal Circumcision", "Informed Consent", "Infant Pain and Stress", "Patient Education", "Pediatric Health Policy", "Surgical Risks and Morbidity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d1be03488bb946877809ecc2e382e9baef65353d1ab7bbc9934c5dd6bbf03100', 'Stainfield WHO & Circ 2008 (thesis).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d1be03488bb946877809ecc2e382e9baef65353d1ab7bbc9934c5dd6bbf03100.pdf', 'other', 'ingested', '{"date": "2008-09-06", "description": "This research report examines the rationale behind the March 2007 endorsement by the World Health Organization (WHO) and UNAIDS of male circumcision as a public health initiative for HIV prevention in sub-Saharan Africa. Focusing on the limitations of existing behavioral interventions like the ABC (Abstinence, Be faithful, use Condoms) approach and the plateauing success of treatment-only regimens, the study evaluates how medical evidence from three randomized controlled trials demonstrating a 50% to 60% risk reduction prompted international health bodies to act.\n\nThe report critically investigates the political, social, ethical, and gender implications of scaling up male circumcision within constrained African healthcare systems. It highlights concerns regarding health communication, risk compensation, the dominance of biomedical paradigms over social science, and the danger of overlooking women''s specific vulnerabilities and unequal power dynamics within HIV prevention policymaking.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Tami L. Stainfield", "Dr. Noor Nieftagodien", "Peter Piot", "Kevin De Cock", "Catherine Hankins", "Yoweri Museveni", "Robert Bailey", "Daniel Halperin"], "organizations": ["World Health Organization", "UNAIDS", "University of the Witwatersrand", "PEPFAR", "Southern African Development Community", "Human Sciences Research Council"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Public Health Policy", "Biomedical vs. Behavioral Interventions", "Gender Inequality and Women''s Health", "Global Health Governance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1932be803b767da7b55f9e8ac208f38bb3c1980dbacf1f1458b20d1454902f91', 'Stegman Estim Male Circ VMMC JIntAIDSSoc 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1932be803b767da7b55f9e8ac208f38bb3c1980dbacf1f1458b20d1454902f91.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This commentary describes the collaborative effort between the UNAIDS Reference Group on Estimates, Modelling, and Projections, Avenir Health, and national stakeholders to standardize and integrate voluntary medical male circumcision (VMMC) data into the annual HIV Estimates process. Recognizing that VMMC data across 15 priority countries in sub-Saharan Africa lacked standardization for reliable planning, the Decision Makers Program Planning Toolkit (DMPPT) 2 Online was upgraded and aligned with demographic models such as Spectrum and Naomi to generate accurate district- and age-specific coverage projections.\n\nThrough extensive country engagement, 13 of the 15 priority countries successfully validated, updated, and uploaded their VMMC programme data. The process demonstrated success in establishing country ownership and improving data quality for strategic planning, despite ongoing challenges related to population migration, military-administered circumcisions, and refugee populations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Peter M. Stegman", "Randy Yee", "Joshua Davis", "Michel Tchuenche", "Rachael Linder", "Lycias Zembe", "Luisa Frescura", "Katharine E. Kripke", "John Stover"], "organizations": ["Avenir Health", "Joint United Nations Programme on HIV/AIDS (UNAIDS)", "World Health Organization (WHO)", "U.S. President\u2019s Emergency Plan for AIDS Relief (PEPFAR)", "U.S. Agency for International Development (USAID)", "Centers for Disease Control and Prevention (CDC)", "Bill and Melinda Gates Foundation", "Imperial College London"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV Prevention", "Health Data Modeling and Projections", "Sub-Saharan Africa Health Policy", "Data Standardization and Quality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('38cb65c18d3c035422963ac2545067f6acf0d50db498156a178f17c70dd72b36', 'Steinfeld Earp Efforts_to_eliminate_FGM.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/38cb65c18d3c035422963ac2545067f6acf0d50db498156a178f17c70dd72b36.pdf', 'policy_guideline', 'ingested', '{"date": null, "description": "This document argues that efforts to eradicate female genital cutting (FGC) would be significantly strengthened and ethically consistent if protections against non-consensual, non-therapeutic genital cutting were extended to male and intersex children. The authors argue that policy should be centered on consent and bodily integrity rather than sex, which helps negate claims of cultural imperialism, addresses gender-based double standards, and resolves moral confusion in communities that modify the genitals of both sexes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Rebecca Steinfeld", "Brian Earp", "Abu-Sahlieh"], "organizations": ["Centre of the Body", "Goldsmiths, University of London", "Yale-Hastings Program in Ethics & Health Policy", "Yale University"], "themes": ["Female Genital Cutting (FGC)", "Male Circumcision", "Intersex Rights", "Bodily Integrity", "Children''s Rights", "Bioethics", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('96800d4a6371455c164e53bd96f1283c21da6823665ad0b23046aaecac69eff8', 'Steinfeld Jew argues Child Rights Haaretz 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/96800d4a6371455c164e53bd96f1283c21da6823665ad0b23046aaecac69eff8.pdf', 'newspaper_clipping', 'ingested', '{"date": "2013-11-26", "description": "In this opinion piece, political scientist Dr. Rebecca Steinfeld argues that European opposition to non-therapeutic infant circumcision is rooted in children''s rights and bodily integrity rather than anti-Semitism. While acknowledging the historical trauma and cultural weight of circumcision within Judaism, she asserts that the right to manifest religious beliefs cannot override an individual''s right to protection from non-consensual bodily harm.\n\nSteinfeld also addresses internal Jewish perspectives, noting that circumcision does not define Jewish status under Jewish law and has historically evolved. She highlights growing questioning of the practice among Jewish parents, advocates for constructive debate and alternative rituals like brit shalom, and encourages institutions like the Council of Europe to maintain child protection standards universally.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Dr. Rebecca Steinfeld", "Geoffrey Alderman", "Marlene Rupprecht", "Tanya Gold", "Elie Jesner", "Shaye Cohen"], "organizations": ["Council of Europe", "Israel''s Foreign Ministry", "Sweden Democrats", "Birmingham Children''s Hospital", "Harvard University", "SOAS, University of London", "Kahal", "Beyond the Bris", "Jews Against Circumcision", "Haaretz"], "themes": ["Circumcision", "Children''s Rights", "Religious Freedom", "Bodily Integrity", "Anti-Semitism", "Medical Ethics", "Jewish Law and Identity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('14c1bc41982a7bc2930e42f654a0bf541c25038a75f90263d3c9b56d581f6c7f', 'Stewart Adult Prepuceplasty Urology 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/14c1bc41982a7bc2930e42f654a0bf541c25038a75f90263d3c9b56d581f6c7f.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This clinical study evaluates and compares the outcomes of standard prepuceplasty versus foreskin Z-plasty in adult men treated for congenital tight foreskin between 2005 and 2010. Among the 34 patients analyzed (22 standard prepuceplasty and 12 Z-plasty), both techniques achieved successful foreskin release, enabling 82% of patients overall to avoid circumcision, with no significant differences observed regarding postoperative pain or foreskin tightness.\n\nHowever, foreskin Z-plasty demonstrated statistically significant superiority in cosmetic outcomes compared to the standard approach, with patients rating aesthetic appearance as ''good'' to ''very good'' versus ''acceptable'' for standard prepuceplasty. In addition, fewer patients in the Z-plasty group required subsequent circumcision (9.1% vs. 22.7%), leading the authors to conclude that foreskin Z-plasty is a viable, aesthetically preferable alternative to standard prepuceplasty in appropriately selected adult patients.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Grant D. Stewart", "Jonas Gruth\u00f6lter", "Roland Donat", "Willem Bijl"], "organizations": ["Western General Hospital", "Elsevier Inc."], "themes": ["Adult Prepuceplasty", "Foreskin Z-plasty", "Phimosis Treatment", "Circumcision Alternatives", "Urological Surgery", "Surgical Cosmesis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8e5db34c60a340850c8365318f994faaec12fadc0680e386ab29b083135de3b3', 'Svoboda address to UN 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8e5db34c60a340850c8365318f994faaec12fadc0680e386ab29b083135de3b3.pdf', 'letter', 'ingested', '{"date": "2001-09-26", "description": "This document contains an email from J. Steven Svoboda transmitting the text of an oral presentation delivered to the United Nations Sub-Commission on August 14, 2001. The speech praises international human rights advancements made in protecting women and girls\u2014particularly efforts to eliminate female genital mutilation (FGM)\u2014while arguing that male circumcision represents an overlooked violation of bodily integrity and human rights that occurs far more frequently.\n\nSvoboda references recent Swedish legislation regulating male circumcision and cites human rights experts to argue that non-discrimination principles under international law require the protection of male children from non-consensual bodily alterations, just as protections are granted to females.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["J. Steven Svoboda", "Mrs. Warzazi", "Jacqueline Smith", "Gay J. McDougall"], "organizations": ["United Nations", "United Nations Sub-Commission on Prevention of Discrimination and Protection of Minorities", "NOCIRC", "Parliament of Sweden", "Netherlands Institute of Human Rights"], "themes": ["Human Rights", "Male Circumcision", "Female Genital Mutilation", "Children''s Rights", "Sex Discrimination", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0e8cc0ca0367d459adc6bedc51846df6787b4886ff15497a8fcf2b803b5645e5', 'Svoboda Adler Circ Unethical JLawMedEth 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0e8cc0ca0367d459adc6bedc51846df6787b4886ff15497a8fcf2b803b5645e5.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This article excerpt from The Journal of Law, Medicine & Ethics argues that non-therapeutic male circumcision is both unethical and unlawful. Co-authored by legal and medical scholars J. Steven Svoboda, Peter W. Adler, and Robert S. Van Howe, the text introduces critical perspectives on the procedure through historical, clinical, and financial quotes that question the necessity, motivation, and ethical basis of infant circumcision.\n\nThe authors highlight the transition of the procedure from historical disciplinary roots to modern financial incentives within the medical system, underscoring their broader bioethical and human rights arguments against routine infant male circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. Steven Svoboda", "Peter W. Adler", "Robert S. Van Howe", "John Harvey Kellogg", "Helain Landy", "Thomas Wiswell"], "organizations": ["Attorneys for the Rights of the Child", "American Academy of Pediatrics", "Georgetown University Hospital", "Central Michigan University College of Medicine", "United Nations", "Centers for Disease Control and Prevention"], "themes": ["Male Circumcision", "Bioethics", "Pediatric Law and Ethics", "Human Rights", "Medical Necessity and Financial Incentives"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('592b2a1784ba26bc9a5f3568faa15c61c71cd1b48def37e2723c9433e3e52498', 'Svoboda Circ HR Viol JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/592b2a1784ba26bc9a5f3568faa15c61c71cd1b48def37e2723c9433e3e52498.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-20", "description": "This article argues that non-therapeutic infant male circumcision constitutes a severe violation of a child''s fundamental right to bodily integrity and autonomy. The author contends that because neonatal circumcision lacks immediate medical necessity and carries risks of harm, parental proxy consent is legally and ethically invalid. Any potential benefits associated with the procedure can be realized later in life when the individual is mature enough to make a fully informed, voluntary decision.\n\nFurthermore, the paper examines circumcision under international human rights frameworks, asserting that the practice infringes upon major human rights treaties, including the Universal Declaration of Human Rights, the Convention on the Rights of the Child, the International Covenant on Civil and Political Rights, and the Convention Against Torture. Applying social norm theory, the author posits that the persistence of infant circumcision in the United States relies on cultural conditioning rather than objective medical science, predicting that routine circumcision rates will collapse once public and medical perception crosses a critical tipping point.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J Steven Svoboda", "Robert S Van Howe", "Sarah Waldeck", "Immanuel Kant"], "organizations": ["Attorneys for the Rights of the Child", "American Academy of Pediatrics", "American Medical Association", "British Medical Association", "Royal Dutch Medical Association", "United Nations"], "themes": ["Bodily Integrity", "Human Rights", "Infant Male Circumcision", "Medical Ethics", "Informed Consent", "Social Norm Theory"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6c2a72d1f1df96bb65dfe79ecd51ffb1a0063c1ad4b51ff3244d8315e51ec230', 'Svoboda Examine HR Constit Issues Plenum 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6c2a72d1f1df96bb65dfe79ecd51ffb1a0063c1ad4b51ff3244d8315e51ec230.pdf', 'other', 'ingested', '{"date": "1997", "description": "This document represents the title page of the publication titled ''Sexual Mutilations: A Human Tragedy''. It highlights the editorial leadership behind the work, addressing the issue of sexual mutilation and circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["George C. Denniston", "Marilyn Fayre Milos"], "organizations": ["University of Washington", "National Organization of Circumcision Information Resource Centers", "Plenum Press"], "themes": ["Circumcision", "Sexual Mutilation", "Human Rights", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5b66bcbbfa9744c5ac7f94f3b6c3066aa1ad7dc35cc3db2b99f4305448eada93', 'Svoboda Iatrogenic Ethics AMA 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5b66bcbbfa9744c5ac7f94f3b6c3066aa1ad7dc35cc3db2b99f4305448eada93.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article argues that nontherapeutic circumcision (NTC) of male infants and children constitutes an ethically indefensible form of iatrogenic harm. The author maintains that the foreskin possesses vital erogenous, protective, and immunological functions, meaning its excision represents a tangible harm in itself regardless of surgical complications. Purported prophylactic benefits, such as reduced risks of urinary tract infections or heterosexual HIV transmission, are shown to be marginal, context-dependent, or insufficient to justify elective surgery on healthy infants without medical necessity.\n\nApplying core biomedical ethics principles\u2014respect for patient autonomy, nonmaleficence, beneficence, and justice\u2014the article asserts that proxy parental consent for nontherapeutic genital surgery violates a child''s bodily integrity and right to an open future. The author urges the medical profession to break the cycle of routine infant circumcision and defer the procedure until the individual reaches the age of majority and can provide mature, informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. Steven Svoboda", "Douglas Diekema", "Andrew L. Freedman", "Morten Frisch"], "organizations": ["American Medical Association", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Attorneys for the Rights of the Child", "Danish Medical Association", "Royal Dutch Medical Association"], "themes": ["Nontherapeutic Circumcision", "Medical Ethics and Bioethics", "Iatrogenic Harm", "Pediatric Autonomy and Informed Consent", "Bodily Integrity and Human Rights", "Genital Anatomy and Sexual Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f2782be93c942718ea8bed0cfe9cdaa3c69d197a262b350ae5e70ae8a6b12ebe', 'Svoboda Informed Consent Conundrum JContempHlthLaw 2000.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f2782be93c942718ea8bed0cfe9cdaa3c69d197a262b350ae5e70ae8a6b12ebe.pdf', 'legal_document', 'ingested', '{"date": "2000", "description": "This article examines the ethical and legal standards governing informed consent and their specific application to routine neonatal male circumcision. The authors establish that valid consent requires comprehensive disclosure, capacity, and voluntariness\u2014thresholds rarely met by typical parental consent practices for circumcision. Applying legal frameworks developed for incompetent patients and children, the authors argue that parental authority is fiduciary and strictly circumscribed by the child''s temporal best interests; parents lack legal authority to consent to medically non-essential interventions or prophylactic removals of healthy tissue, irrespective of religious conviction.\n\nEvaluating the medical evidence, the article concludes that the purported health benefits of circumcision (including the prevention of urinary tract infections, penile cancer, and sexually transmitted infections) are either minimal, speculative, or achievable through less intrusive means. When weighed against immediate surgical risks, irreversible neurological trauma caused by infant pain, and permanent loss of erogenous and protective anatomical functions, routine neonatal circumcision fails the best-interests test. Consequently, parental consent to the procedure is deemed legally invalid, and the procedure should be deferred until the male patient reaches the age of majority and can decide for himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["J. Steven Svoboda", "Robert S. Van Howe", "James G. Dwyer", "Margaret Somerville"], "organizations": ["Attorneys for the Rights of the Child", "Marshfield Clinic", "William & Mary School of Law", "American Academy of Pediatrics", "American Medical Association", "Canadian Paediatric Society", "British Medical Association", "Queensland Law Reform Commission"], "themes": ["Informed Consent", "Neonatal Circumcision", "Children''s Rights", "Bodily Integrity", "Medical Ethics", "Parental Authority and Fiduciary Duty", "Substituted Judgment and Best Interests Standard"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ad1c302d81e77b8e1a49d4928ef03337d2090a421e4457864eb44048c123fff4', 'Svoboda Limits_of_the_Law Kluwer 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ad1c302d81e77b8e1a49d4928ef03337d2090a421e4457864eb44048c123fff4.pdf', 'other', 'ingested', '{"date": "2001", "description": "This academic chapter by J. Steven Svoboda presents a comparative analysis of five child body mutilation and modification practices: artificial cranial deformation, Chinese footbinding, female infanticide in nineteenth-century India, female genital cutting, and male genital cutting. The author explores the cultural, psychological, economic, and normative mechanisms that normalize and perpetuate these procedures, noting that they consistently harm the child while serving adult anxieties, marital conventions, or social hierarchies. Svoboda emphasizes that cultures routinely condemn foreign practices as barbaric while rationalizing their own traditional bodily interventions.\n\nThe paper evaluates the limits of statutory and coercive legal prohibitions, arguing that legal mandates imposed from above or by external authorities often spark cultural backlash or drive practices underground. In contrast, effective and enduring abandonment generally arises from extralegal, culturally integrated approaches\u2014such as public pledge associations, community education, and economic mitigation\u2014which shift social conventions prior to legal codification. Svoboda concludes that Western societies must confront their own cultural blind spots, particularly routine neonatal male circumcision, before presuming moral authority over foreign traditional practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["J. Steven Svoboda", "E. Adamson Hoebel", "Nancy Scheper-Hughes", "Hanny Lightfoot-Klein", "Gerry Mackie"], "organizations": ["Attorneys for the Rights of the Child", "Kluwer Academic/Plenum Publishers", "United Nations", "American Medical Association"], "themes": ["Child Body Modification", "Male Circumcision", "Female Genital Cutting", "Footbinding", "Female Infanticide", "Legal and Extralegal Reform", "Children''s Rights and Bodily Integrity", "Cultural Relativism and Parochialism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c7bf2e4c8e13b466574a4832e4061c8c6452e9756f752df1f1a6d4da8d27ddd0', 'Svoboda Promoting Genital Autonomy  GlobDisc 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c7bf2e4c8e13b466574a4832e4061c8c6452e9756f752df1f1a6d4da8d27ddd0.pdf', 'other', 'ingested', '{"date": "2013", "description": "This article advocates for the principle of genital autonomy, arguing that all children must be protected from medically unnecessary genital modifications, encompassing female genital cutting (FGC), male genital cutting (MGC), intersex genital cutting (IGC), and cosmetic female genital cutting (CFGC). Author J. Steven Svoboda highlights the shared roots of these practices in historical desires for social and sexual control, enforcing binary gender roles, suppressing alternative sexualities, and demanding cultural conformity. He critiques Western double standards that condemn FGC in non-Western cultures while excusing or medicalizing neonatal male circumcision and infant intersex surgeries.\n\nThe author further argues that subjecting non-consenting minors to irreversible cosmetic and non-therapeutic procedures violates medical ethics, international human rights doctrines, and the principle of equal protection. Svoboda asserts that moving toward universal genital autonomy requires overcoming cultural blind spots, rejecting medicalized rationales for social discipline, and applying uniform bioethical and legal protections to ensure that every individual retains bodily ownership and the right to make decisions regarding their own body.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["J. Steven Svoboda", "Hanny Lightfoot-Klein", "Margaret Somerville", "Kirsten Bell", "Janice Boddy", "Cheryl Chase"], "organizations": ["Attorneys for the Rights of the Child", "American Academy of Pediatrics", "World Health Organization", "British Medical Association", "American College of Obstetricians and Gynecologists", "United Nations"], "themes": ["Genital Autonomy", "Male Circumcision", "Female Genital Cutting", "Intersex Genital Surgery", "Children''s Rights and Bodily Integrity", "Medical Ethics and Informed Consent", "Gender Norms and Social Control", "Cultural Relativism and Double Standards"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6cc96b68e545948b202e0239543f56b6c3cd9a1fc0096bc13eae7c7e6a2dfd02', 'Svoboda Unethical-and-Unlawful-Response-to-Morris JMLE 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6cc96b68e545948b202e0239543f56b6c3cd9a1fc0096bc13eae7c7e6a2dfd02.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This academic article by J. Steven Svoboda, Peter W. Adler, and Robert S. Van Howe serves as a rebuttal to a critique by Brian Morris et al. regarding the ethics and legality of non-therapeutic male circumcision (NTC) on non-consenting minors. The authors argue against Morris et al.''s unprecedented claim that physicians have an ethical duty to recommend infant male circumcision, asserting instead that physicians are both ethically and legally proscribed from performing medically unnecessary surgery on healthy children.\n\nThe authors analyze empirical data and legal precedents, highlighting that the foreskin serves vital protective, moisturizing, and sensory functions, and that the alleged long-term prophylactic benefits of circumcision do not justify overriding a child''s fundamental human rights to bodily integrity, self-determination, and equal protection under the law. They conclude that any decision regarding non-essential surgical alteration should be deferred until the individual reaches the age of consent to evaluate the risks, benefits, and personal trade-offs for himself.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. Steven Svoboda", "Peter W. Adler", "Robert S. Van Howe", "Brian J. Morris", "Michael T. Brady", "Brian D. Earp"], "organizations": ["Attorneys for the Rights of the Child", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Circumcision Academy of Australia", "Royal Dutch Medical Association", "United Nations"], "themes": ["Non-Therapeutic Neonatal Circumcision", "Biomedical Ethics", "Children''s Rights and Bodily Integrity", "Legal Parental Authority vs. Minor Rights", "Medical Decision-Making and Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e7d7dc7e375e76cbb69442d869935d43b4cde02dd8319500d9a575f84f6298c0', 'Svoboda VanHowe Out of Step AAP JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e7d7dc7e375e76cbb69442d869935d43b4cde02dd8319500d9a575f84f6298c0.pdf', 'medical_journal', 'ingested', '{"date": "2013-03-18", "description": "This academic paper critically evaluates the 2012 American Academy of Pediatrics (AAP) policy statement and technical report regarding neonatal circumcision. The authors argue that the AAP''s conclusion\u2014that the medical benefits of infant male circumcision outweigh the risks\u2014is fundamentally compromised by selective literature review, methodological flaws, logical inconsistencies, and unsubstantiated recommendations for third-party insurance coverage.\n\nFurthermore, the authors assert that the AAP ignored the anatomical and sexual functions of the foreskin, minimized potential surgical trauma and complications, and inappropriately extrapolated adult HIV transmission data from Sub-Saharan Africa to American infants. The article concludes that non-therapeutic neonatal circumcision violates foundational biomedical ethics and children''s human rights to bodily integrity, arguing that the AAP should retract its policy to align with international medical consensus.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J Steven Svoboda", "Robert S Van Howe", "Brian D Earp"], "organizations": ["American Academy of Pediatrics", "Attorneys for the Rights of the Child", "Michigan State University College of Human Medicine", "Berufsverband der Kinder- und Jugend\u00e4rzte", "Royal Dutch Medical Association", "BMJ"], "themes": ["Neonatal Circumcision", "Biomedical Ethics", "Children''s Rights and Bodily Integrity", "Evidence-Based Medicine", "HIV Transmission and Prevention", "Healthcare Financing and Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d7d412bc0cc72ae9de2eb070038a50aa9d808850ad01f8d09e009f442621cafa', 'Svoboda-Protect MaleFemale-CardozoJEqualRtsSocJust-2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d7d412bc0cc72ae9de2eb070038a50aa9d808850ad01f8d09e009f442621cafa.pdf', 'legal_document', 'ingested', '{"date": "2025", "description": "This article examines the legal and ethical asymmetry between female genital cutting (FGC) and male genital cutting (MGC), arguing that children of all sexes deserve equal legal protection against non-consensual, medically unnecessary genital modifications. Using two contrasting decisions by federal judge Bernard Friedman\u2014the civil rights lawsuit Armatas v. Elmhurst Hospital Center regarding infant circumcision and the criminal case United States v. Nagarwala regarding FGC\u2014the author illustrates how Western legal frameworks disproportionately tolerate MGC while strictly criminalizing even minimal forms of FGC.\n\nThe author systematically critiques the primary justifications commonly offered for MGC, including purported health benefits, religious and cultural traditions, and alleged lack of harm, arguing that none override a child''s fundamental human rights to bodily integrity, self-determination, and an open future. Surveying emerging jurisprudence and legislative proposals in Europe that increasingly question or restrict non-therapeutic circumcision, the article contends that differential treatment based on sex violates constitutional guarantees of equal protection and international human rights treaties like the CRC and ICCPR.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["J. Steven Svoboda", "Bernard Friedman", "Evagelos Armatas", "Sir James Munby", "Brian D. Earp", "Kai M\u00f6ller"], "organizations": ["Cardozo Journal of Equal Rights and Social Justice", "Attorneys for the Rights of the Child", "Elmhurst Hospital Center", "United States Department of Justice", "American Academy of Pediatrics", "Council of Europe"], "themes": ["Male Genital Cutting", "Female Genital Cutting", "Bodily Integrity", "Children''s Rights", "Equal Protection", "Informed Consent", "Human Rights Law"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dc77aaaa2776d16c6de66e9fcea542f8b49e24e3c8a9577d19c63c65995a74e9', 'Svoboda-Treatise-from-Trenches Springer 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dc77aaaa2776d16c6de66e9fcea542f8b49e24e3c8a9577d19c63c65995a74e9.pdf', 'legal_document', 'ingested', '{"date": "2009", "description": "In this treatise, attorney and activist J. Steven Svoboda examines the multifaceted challenges and procedural obstacles involved in litigating circumcision-related lawsuits in the United States. Drawing heavily on two specific cases he litigated\u2014one involving the nonconsensual circumcision of an infant (Dennis Pappas) and another involving an adult patient circumcised by mistake during a vasectomy (William Anastasian)\u2014Svoboda identifies key barriers that prevent successful outcomes. These factors include financial risks, procedural hurdles like statutes of limitation and repose, the necessity of parental cooperation, difficulties in damage valuation, and a profound scarcity of favorable legal precedent.\n\nThe author further details how courtroom dynamics, societal normalization of male circumcision, and systemic bias among judges and juries hinder plaintiffs. Judicial hostility, questionable defense tactics, and misallocated jury sympathy often disadvantage plaintiffs even in egregious cases of medical negligence or civil rights violations. Despite these pervasive difficulties, Svoboda highlights emerging incremental shifts in legal and cultural consciousness regarding male genital integrity, underscoring the importance of persistent advocacy and precedent-building.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["J. Steven Svoboda", "Dennis Pappas", "Cyril Pappas", "Maria Pappas", "William Anastasian", "Laura Anastasian", "Sarah Bernstein", "John Geisheker", "Bob Van Howe"], "organizations": ["Attorneys for the Rights of the Child", "Springer Science + Business Media", "Elmhurst Hospital", "National Organization of Circumcision Information Resource Centers"], "themes": ["Circumcision Litigation", "Bodily Integrity and Human Rights", "Informed Consent and Medical Malpractice", "Civil Rights and Discrimination", "Judicial Bias and Legal Procedure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8d4ed1816f3f4d1cc70eeafad12690710cf54b081febfe1262f7317266e572e6', 'Szasz Advice & Tactics.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8d4ed1816f3f4d1cc70eeafad12690710cf54b081febfe1262f7317266e572e6.pdf', 'other', 'ingested', '{"date": null, "description": "Dr. Thomas Szasz delivers a philosophical critique of routine infant circumcision (RIC), arguing that it is a ritualistic practice and form of genital mutilation legitimized by social custom and medical authority rather than genuine necessity. He asserts that framing circumcision as preventive medicine is an absurd rationalization, pointing out that human males are not inherently born defective or requiring immediate surgical correction.\n\nSzasz also provides strategic advice to anti-circumcision activists, urging them to bypass complex medical arguments and avoid appealing to doctors directly. Instead, he recommends using simple, emotionally resonant messaging, leveraging media attention, and posing straightforward questions that highlight the normality of the intact body and expose the irrationality of the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Thomas Szasz"], "organizations": [], "themes": ["Routine Infant Circumcision (RIC)", "Genital Mutilation", "Medicalization and Social Control", "Bodily Integrity and Consent", "Language, Law, and Custom", "Activism and Persuasion Strategy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a2db31fde209cfc8784153d86b923a8b659250b6d2436e7fbe11a2d62428e368', 'Szasz Circ Birth Therapeutic State JMedPhil 1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a2db31fde209cfc8784153d86b923a8b659250b6d2436e7fbe11a2d62428e368.pdf', 'medical_journal', 'ingested', '{"date": "1996", "description": "In this paper, Thomas Szasz critiques the practice of routine neonatal circumcision (RNC), arguing that its portrayal as a secular, prophylactic medical procedure is an illusion masking its true nature as an ancient religious ritual. Tracing the history of circumcision from biblical covenantal sacrifice to its 19th-century medicalization as a supposed remedy for masturbation, Szasz contends that modern medical justifications\u2014such as preventing penile cancer and urinary tract infections\u2014are empirically weak rationalizations. He interprets this widespread medical intervention as a prominent manifestation of the ''Therapeutic State,'' where moral and social controls are masqueraded as health imperatives.\n\nWhile identifying RNC as medically unjustifiable and questioning the double standard that exempts male circumcision from being classified as genital mutilation, Szasz cautions against outright state prohibition. He argues that using state coercion against parents'' religious and family autonomy poses a greater long-term danger to civil liberty than the practice itself. Instead, he advocates for a compromise based on education and persuasion, calling on physicians and the media to inform parents about the dubious medical claims and ethical concerns surrounding routine neonatal circumcision without criminalizing parental religious traditions.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Thomas Szasz", "Moses Maimonides", "Jules Romains", "Simon-Andre Tissot", "Edward Wallerstein"], "organizations": ["American Medical Association", "American Academy of Pediatrics", "State University of New York Health Science Center", "British National Health Service"], "themes": ["Routine Neonatal Circumcision", "The Therapeutic State", "Medicalization", "Religious Ritual vs. Medical Prophylaxis", "Parental Rights and State Coercion", "Genital Mutilation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('78266f2839ca8616cbb37f1cb95a8a3a238da1aad11a1cf51916fc4bc1c34575', 'Taddio pain vaccination Lancet 1995.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/78266f2839ca8616cbb37f1cb95a8a3a238da1aad11a1cf51916fc4bc1c34575.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This document consists of excerpts from medical research published in The Lancet in 1994. The primary featured study investigates whether neonatal male circumcision influences subsequent pain responses during routine vaccinations at 4 to 6 months of age. Through a post-hoc analysis of a clinical trial evaluating DPT and HIB vaccinations, researchers observed that circumcised infant boys demonstrated significantly higher pain scores and longer cry durations than uncircumcised boys, suggesting that neonatal pain may have lasting behavioral and nociceptive effects.\n\nThe preceding fragment reports on maternal-infant vertical transmission of the hepatitis C virus (HCV). It finds that HIV coinfection in mothers significantly increases maternal HCV-RNA levels and acts as a major predisposing factor for perinatal HCV transmission, whereas no transmission was observed among non-HIV-infected drug-using mothers in the sample.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["A. Taddio", "Gideon Koren", "M. Goldbach", "M. Ipp", "B. Stevens", "A. R. Zanetti", "E. Tanzi", "S. Paccagnini", "N. Principi"], "organizations": ["Hospital for Sick Children", "University of Toronto", "University of Milan", "Astra Pharma, Canada", "Italian Ministry of Health"], "themes": ["Neonatal Circumcision", "Infant Pain Response", "Vaccination", "Hepatitis C Vertical Transmission", "HIV and HCV Coinfection"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8d55e519da894a0e3a057898fbe2e99116e0d06ecbcb663b54fdf8f20a2b5908', 'Tan Single cell analysis Prepuce BMC Genomics 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8d55e519da894a0e3a057898fbe2e99116e0d06ecbcb663b54fdf8f20a2b5908.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This study presents a single-cell RNA-sequencing analysis of 90,770 qualified cells from human prepuce (foreskin) tissue samples across children and adults to dissect cellular heterogeneity and molecular dynamics. The authors identified 15 distinct cell subtypes, with fibroblasts, smooth muscle cells, and T/NK cells representing the largest populations, though relative proportions varied considerably among individuals and age cohorts.\n\nBy reconstructing gene regulatory networks and cell\u2013cell communication pathways, the researchers revealed distinct functional dynamics between development and tissue maintenance. Key findings include child-specific regulons and signaling pathways (such as AR, KLF10, CD96, EPO, and WNT) linked to prepuce development, contrasting with adult-enriched signaling pathways (such as BMP10, NEGR, ncWNT, and NPR1) involved in tissue maintenance and homeostasis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Fei Tan", "Yuan Xuan", "Lan Long", "Yang Yu", "Chunhua Zhang", "Pengchen Liang", "Yaoqun Wang", "Meiyu Chen", "Jiling Wen", "Geng Chen"], "organizations": ["Tongji University", "Shanghai Skin Disease Hospital", "Anhui Medical University", "East China Normal University", "Shanghai University", "Shanghai Tenth People''s Hospital", "Shanghai East Hospital"], "themes": ["Single-cell RNA sequencing", "Prepuce Biology and Anatomy", "Gene Regulatory Networks", "Cell-Cell Communication", "Pediatric vs. Adult Tissue Dynamics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f0127c7930b4efc9acac9d948bfce02af668b70d12b209c003975cca212638c', 'Tang Prem Ejac IntSocSexMed 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8f0127c7930b4efc9acac9d948bfce02af668b70d12b209c003975cca212638c.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This cross-sectional study investigates the prevalence and correlates of premature ejaculation (PE) among 207 men aged 18 to 70 attending a primary care clinic at the University Malaya Medical Center in Malaysia. Using the Premature Ejaculation Diagnostic Tool (PEDT), the authors identified an overall PE prevalence of 40.6% (comprising 20.3% PE and 20.3% probable PE). \n\nMultivariate logistic regression identified erectile dysfunction, male circumcision, Indian ethnicity, and lower frequency of sexual intercourse (5 or fewer times in 4 weeks) as significant independent predictors of PE, while age showed no significant association. The authors conclude that PE is frequent among primary care attendees and emphasize that primary care physicians should be trained to routinely assess, detect, and treat the condition.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Wei Shuong Tang", "Ee Ming Khoo", "Low Wah Yun", "Ng Chirk Jenn"], "organizations": ["University of Malaya", "University Malaya Medical Center", "Bayan Baru Health Clinic", "International Society for Sexual Medicine"], "themes": ["Premature Ejaculation", "Erectile Dysfunction", "Male Sexual Health", "Primary Health Care", "Cross-Sectional Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('691c4e879bdcaf12ae7bf8dae2c0d378049fcf5c8e6bd0a2ceaf7f7a4c656687', 'Tangwa Circ_African_POV Kluwer 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/691c4e879bdcaf12ae7bf8dae2c0d378049fcf5c8e6bd0a2ceaf7f7a4c656687.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "In this paper, Godfrey B. Tangwa explores circumcision from an African cultural perspective, specifically examining its traditional role as an adolescent rite of passage into adulthood among the Nso'' people of Cameroon. He contrasts traditional practices with modern routine infant circumcision introduced through colonialism, Western medicine, and Christianity, highlighting that traditional rationales are no longer sufficient to justify the practice on infants.\n\nTangwa argues on ethical grounds that non-therapeutic infant circumcision should be abolished because it violates bodily integrity, autonomy, and the necessity of informed consent. He critiques Western discourse for disproportionately condemning female genital mutilation while excusing male circumcision due to cultural biases. However, he maintains that safe circumcision procedures should remain available for fully informed adults who choose them freely.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Godfrey B. Tangwa", "J. O. Sodipo", "Michael Novak", "Joseph Jumbam", "Marilyn Fayre Milos"], "organizations": ["Cameroon Medical Women''s Association", "Inter-African Committee on Harmful Traditional Practices Affecting the Health of Women and Children", "National Organization of Circumcision Information Centers", "Kluwer Academic / Plenum Publishers"], "themes": ["Male circumcision", "Female genital mutilation", "Bioethics and bodily integrity", "Informed consent", "Nso'' cultural traditions", "Cultural relativism and universalism"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d5c26086c49eb9d260d26f41392b754d62e93022712f77c19926903a73ebdf6a', 'Taylor-Cold Prepuce BJUInt 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d5c26086c49eb9d260d26f41392b754d62e93022712f77c19926903a73ebdf6a.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This review paper examines the embryology, anatomy, histology, and physiological functions of the human prepuce (foreskin) in both males and females, challenging historical and cultural justifications for non-therapeutic circumcision. The authors detail how the prepuce functions as a specialized, dynamic mucocutaneous structure equipped with a dense network of encapsulated mechanoreceptors, fine-touch corpuscular receptors, dartos smooth muscle, and immunological cells. They emphasize that incomplete preputial separation and physiological non-retractability are normal developmental stages throughout childhood and adolescence rather than pathological phimosis requiring surgery.\n\nThe authors argue against routine neonatal and childhood circumcision, noting that the involuntary removal of healthy prepuce tissue leads to permanent sensory deficit, loss of temperature-responsive dartos tissue, epithelial hyperkeratinization of the exposed glans, potential meatal stenosis, and the development of painful amputation neuromas. They conclude that circumcision should be restricted to rare conditions refractory to conservative therapies, recommending preputial plasty when intervention is necessary to preserve tissue and sexual function.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["C.J. Cold", "J.R. Taylor"], "organizations": ["Marshfield Clinic", "University of Manitoba", "British Journal of Urology", "Canadian Paediatric Society", "Australasian Association of Paediatric Surgeons"], "themes": ["Prepuce Anatomy and Histology", "Embryological Development", "Neonatal and Childhood Circumcision", "Sexual Function and Neuroanatomy", "Pediatric Urology and Phimosis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ffe55d68aec07a53dd2504400164b87d7e2a198937c97416c2d797989a388810', 'Taylor-Lockwood Prepuce SpecMucosa BJU 1996.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ffe55d68aec07a53dd2504400164b87d7e2a198937c97416c2d797989a388810.pdf', 'medical_journal', 'ingested', '{"date": "1996", "description": "This anatomical and histological study investigates the prepuce and the extent of tissue removed during adult and infant male circumcision, using tissue obtained from 22 adult autopsies and observations of circumcised infants. The researchers found that circumcision removes a substantial portion of tissue\u2014frequently measuring more than 50% of the length of the penile shaft\u2014far exceeding what is typically conveyed to patients or parents during pre-operative counseling.\n\nHistological analysis revealed that the excised tissue includes a specialized, highly vascularized junctional mucosa termed the ''ridged band.'' Rich in Meissner''s corpuscles and sensory nerve endings, this unique transitional tissue acts as an essential component of the human penis''s sensory apparatus, challenging the conventional characterization of the foreskin as merely redundant skin.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J.R. Taylor", "A.P. Lockwood", "A.J. Taylor"], "organizations": ["British Journal of Urology", "University of Manitoba", "Health Sciences Centre"], "themes": ["Male Circumcision", "Prepuce Anatomy", "Ridged Band", "Meissner''s Corpuscles", "Sensory Innervation", "Tissue Loss"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8d7f93315d8c596baa4f9109cc1d3474f080a4972b3ba2b10d1b614be8a6fafa', 'Testa Libertarianism and circumcision IJHPM 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8d7f93315d8c596baa4f9109cc1d3474f080a4972b3ba2b10d1b614be8a6fafa.pdf', 'medical_journal', 'ingested', '{"date": "2014-05-26", "description": "This academic paper presents a libertarian and natural rights critique of involuntary neonatal male circumcision, arguing that the practice violates an infant''s fundamental negative right to self-ownership and bodily integrity. Framing parental ownership as guardianship rather than absolute property rights, the authors assert that subjecting non-consenting infants to irreversible surgical procedures constitutes assault and child abuse, regardless of religious or cultural tradition.\n\nIn addition to the rights-based critique, the authors provide a consequentialist examination of the medical and psychological impacts of circumcision. They challenge conventional justifications concerning hygiene, phimosis, and the reduction of UTIs and HIV transmission, contending that these claims are overstated or better addressed through alternative means. Highlighting physical complications, pain trauma, and potential long-term sexual dysfunction, they argue that circumcision should be prohibited on infants and postponed until individuals reach the age of consent to choose for themselves.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Patrick Testa", "Walter E. Block", "John Locke", "Murray N. Rothbard"], "organizations": ["Loyola University New Orleans", "Kerman University of Medical Sciences", "United Nations", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Libertarianism", "Male Circumcision", "Natural Rights", "Children''s Rights", "Bodily Autonomy", "Medical Ethics", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a92371393192aa3385cbef8f62fefb45ae933fc2739572e24c2636defee2d6d3', 'Thakrar US Infant Mortality GlobHlth 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a92371393192aa3385cbef8f62fefb45ae933fc2739572e24c2636defee2d6d3.pdf', 'medical_journal', 'ingested', '{"date": "2018-01", "description": "This study analyzes child mortality trends for individuals ages 0\u201319 across fifty years (1961\u20132010), comparing the United States with nineteen other Organization for Economic Cooperation and Development (OECD) nations. Despite spending significantly more per capita on healthcare for children, the United States progressively fell behind peer nations beginning in the 1970s and 1980s, ranking last in child mortality among all comparator nations by the 2000s. Between 2001 and 2010, US infants had a 76 percent higher risk of death, and children ages 1\u201319 had a 57 percent higher risk, culminating in more than 600,000 cumulative excess deaths over the fifty-year span.\n\nThe findings identify two primary age cohorts driving these disparities: infants and adolescents ages 15\u201319. Disparities in infant mortality were predominantly attributable to perinatal conditions, especially extreme prematurity and low birthweight, which correlate strongly with poverty and racial inequality. In older adolescents, violent deaths and injuries were the leading factors, with US youth ages 15\u201319 being eighty-two times more likely to die from gun homicide than peers in comparator nations. The authors attribute these systemic shortcomings to higher relative child poverty, lower educational attainment, and a weaker social safety net, urging targeted policy interventions toward perinatal care, firearm safety, and social welfare programs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ashish P. Thakrar", "Alexandra D. Forrest", "Mitchell G. Maltenfort", "Christopher B. Forrest", "Donald Trump"], "organizations": ["Organization for Economic Cooperation and Development", "World Health Organization", "Children''s Hospital of Philadelphia", "Johns Hopkins Hospital and Health System", "Drexel University College of Medicine", "University of California, Berkeley", "Max Planck Institute for Demographic Research", "UNICEF", "Project HOPE"], "themes": ["Child and Infant Mortality", "Health Equity and Disparities", "International Health Systems Comparison", "Gun Violence and Injury Prevention", "Perinatal Health and Premature Birth", "Social Determinants of Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8031c25675f3533d78f826cc22158c07825e179d3abafd50fa958c5c22c42625', 'Tietjen Laser Penile Cancer Urol 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8031c25675f3533d78f826cc22158c07825e179d3abafd50fa958c5c22c42625.pdf', 'medical_journal', 'ingested', '{"date": "1998", "description": "This clinical study investigates the efficacy, safety, and long-term outcomes of aggressive laser ablation in treating premalignant penile intraepithelial neoplasia (PENIN) and squamous cell carcinoma (SCC) of the penis. Over a 10-year period, 52 men were evaluated using 5% acetic acid preparation and mapping biopsies to identify the full extent of the human papillomavirus (HPV)-induced ''field-of-change.'' Depending on the lesion''s depth and stage, patients were treated using CO2, Nd:YAG, or KTP/532 lasers, along with simultaneous circumcision in uncircumcised patients.\n\nOver an average follow-up of 58 months across 44 patients, the overall recurrence rate was 11.4%, with the majority of recurrences successfully salvaged by repeat laser therapy. HPV DNA was detected in 93.5% of tested specimens, and 81% of patients were smokers. The authors conclude that aggressive laser treatment of both the tumor and the dysplastic field-of-change offers excellent cosmetic and functional penile preservation with low recurrence rates for superficial disease (PENIN, Tis, T1), though it remains ineffective for deeply invasive (T2) carcinoma.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Douglas N. Tietjen", "Reza S. Malek"], "organizations": ["Mayo Clinic", "Mayo Foundation", "Elsevier Science Inc.", "American Joint Committee on Cancer"], "themes": ["Squamous Cell Carcinoma", "Laser Therapy", "Human Papillomavirus (HPV)", "Penile Intraepithelial Neoplasia (PENIN)", "Organ-Preserving Oncology", "Field-of-Change Phenomenon"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fcb22218eee33f74cb7da5e87e7951d1f9482d01fe312ef9d8d074f21ea7bd0e', 'Timmermans Restoration Options IJIR 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fcb22218eee33f74cb7da5e87e7951d1f9482d01fe312ef9d8d074f21ea7bd0e.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This review provides a comprehensive overview of the history, motivations, and clinical approaches surrounding foreskin reconstruction following circumcision. Tracing practices from antiquity\u2014such as ancient Greek foreskin manipulation and Roman and Jewish techniques during periods of persecution\u2014to modern times, the authors examine both surgical interventions and conservative, nonsurgical modalities. Men seeking uncircumcision today often report concerns regarding body integrity, psychological distress, and sexual sensitivity.\n\nThe authors highlight that existing surgical literature is dated, sparse, and relies heavily on low-quality anecdotal reports with unclear complication profiles. In contrast, nonsurgical mechanical stretching methods (including manual tugging, taping, and commercial traction devices) are widely utilized in patient communities with promising anecdotal outcomes, but they lack formal clinical trials and empirical quantification. The review concludes that evidence-based protocols, quality-of-life evaluations, and close medical counseling are urgently required to guide patients pursuing foreskin restoration.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Floyd Wilhelmus Timmermans", "Sterre Elisabeth Mokken", "Sahaand Cris Zo\u00eb Poor Toulabi", "Mark-Bram Bouman", "M\u00fcjde \u00d6zer"], "organizations": ["Amsterdam University Medical Center", "Vrije Universiteit Amsterdam", "Springer Nature Limited", "Foregen", "National Organization of Restoring Men (NORM)", "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)"], "themes": ["Foreskin reconstruction and restoration", "Post-circumcision regret and body integrity", "Surgical techniques and reconstructive plastic surgery", "Tissue expansion and nonsurgical traction devices", "History of uncircumcision and genital aesthetics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1829ac82423b60c6f908eb7d8e884ebfc08f41c46a9763869860593ace1d01d1', 'Tobian Circ & HPV IntJCancer 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1829ac82423b60c6f908eb7d8e884ebfc08f41c46a9763869860593ace1d01d1.pdf', 'medical_journal', 'ingested', '{"date": "2011-12-15", "description": "This randomized controlled trial evaluated the efficacy of male circumcision in reducing high-risk human papillomavirus (HR-HPV) across multiple anatomical sites of the penis\u2014specifically comparing the coronal sulcus and the penile shaft\u2014among HIV-negative men in Rakai, Uganda. Evaluating participants at 12 months post-enrollment, the study found that circumcision significantly reduced HR-HPV prevalence on the coronal sulcus (21.5% in the intervention arm vs. 36.3% in the control arm) and demonstrated a comparable proportional reduction on the penile shaft (15.5% vs. 23.8%), which was statistically significant in sensitivity analyses.\n\nOverall, HR-HPV was more commonly detected on the coronal sulcus than on the shaft, particularly among uncircumcised men, suggesting that the subpreputial space provides an environment conducive to viral persistence. By reducing HR-HPV prevalence across both sites and potentially decreasing autoinfection, male circumcision provides broader protection against penile HPV carriage, which is expected to lower transmission rates to female partners and help prevent cervical cancer.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Aaron A. R. Tobian", "Xiangrong Kong", "Patti E. Gravitt", "Kevin P. Eaton", "Godfrey Kigozi", "David Serwadda", "Amy E. Oliver", "Fred Nalugoda", "Frederick Makumbi", "Michael Z. Chen", "Maria J. Wawer", "Thomas C. Quinn", "Ronald H. Gray"], "organizations": ["Johns Hopkins University", "Rakai Health Sciences Program", "Makerere University", "National Institutes of Health", "National Institute of Allergy and Infectious Diseases", "Uganda Virus Research Institute", "Bill and Melinda Gates Foundation"], "themes": ["Male Circumcision", "Human Papillomavirus (HPV)", "Sexually Transmitted Infections (STIs)", "HIV Prevention", "Cervical Cancer Prevention", "Anatomic Site Carriage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8bf9a2f3ea0be57ddf2f7eee03dd8ef7d4ea54c09addd5fa93ca1af148b070aa', 'Tobian Gray HIV APAM 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8bf9a2f3ea0be57ddf2f7eee03dd8ef7d4ea54c09addd5fa93ca1af148b070aa.pdf', 'medical_journal', 'ingested', '{"date": "2010", "description": "This review article evaluates substantial clinical and epidemiological evidence demonstrating that male circumcision significantly reduces the risk of sexually transmitted infections (STIs), arguing for a revision of the American Academy of Pediatrics (AAP) policy on neonatal circumcision. Citing three major randomized controlled trials conducted in South Africa, Kenya, and Uganda, the authors highlight that circumcision decreases heterosexual male HIV acquisition by 50% to 60%, reduces herpes simplex virus type 2 (HSV-2) acquisition by 28% to 34%, and lowers high-risk human papillomavirus (HPV) prevalence by 32% to 35%. Furthermore, female partners of circumcised men experience significant reductions in bacterial vaginosis, Trichomonas vaginalis infection, and genital ulcer disease.\n\nAddressing ethical concerns, procedural risks, and socio-economic disparities, the authors note that serious complications from neonatal circumcision are extremely rare compared to procedures performed later in life. They emphasize that restrictive guidance from professional bodies directly hinders Medicaid coverage in multiple US states, disproportionately affecting disadvantaged minority populations with higher baseline risks of STIs and HIV. Consequently, the authors urge the AAP, the American Medical Association, and the American College of Obstetricians and Gynecologists to update their guidelines to fully reflect circumcision''s long-term health benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Aaron A. R. Tobian", "Ronald H. Gray", "Thomas C. Quinn"], "organizations": ["American Academy of Pediatrics", "Johns Hopkins University", "National Institutes of Health", "National Institute of Allergy and Infectious Diseases", "World Health Organization", "Joint United Nations Programme on HIV/AIDS", "American Medical Association", "American College of Obstetricians and Gynecologists"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Sexually Transmitted Infections", "Neonatal Healthcare", "Medical Ethics and Health Policy", "Medicaid and Healthcare Disparities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b4460af27a0167fc99b8bd4c2b6f73c19d2c42d5179a88ef2c2090700ca23e5b', 'TORTORELLA v CASTRO.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b4460af27a0167fc99b8bd4c2b6f73c19d2c42d5179a88ef2c2090700ca23e5b.pdf', 'legal_document', 'ingested', '{"date": "2006-06-01", "description": "In Tortorella v. Castro, the California Court of Appeal affirmed a trial court order granting plaintiff Marian Tortorella a new trial in her medical malpractice action against Dr. Dan Joshua Castro. Dr. Castro had initially obtained summary judgment after arguing that Tortorella failed to establish a triable issue of material fact regarding causation. Tortorella countered with an expert declaration asserting that Dr. Castro''s preoperative evaluation fell below the standard of care and resulted in unnecessary sinus surgery.\n\nThe appellate court held that the trial court erred in originally granting summary judgment because an expert declaration establishing that a surgery was medically unnecessary is inherently sufficient to establish a triable issue on causation and patient harm. Although the trial court granted the new trial on equitable grounds not strictly outlined in statute, the appellate court affirmed the decision because the original summary judgment was an error in law under California Code of Civil Procedure section 657.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Marian Tortorella", "Dan Joshua Castro", "Paul H. Toffel", "Ellis C. Berkowitz", "Joan Dempsey Klein", "H. Walter Croskey", "Richard D. Aldrich"], "organizations": ["California Court of Appeal", "Regents of the University of California", "UCLA Medical Center", "Maranga & Morgenstern", "Greines, Martin, Stein & Richland", "Wasserman, Comden & Casselman"], "themes": ["Medical Malpractice", "Causation", "Unnecessary Surgery", "Summary Judgment", "Motion for New Trial", "Standard of Care"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3e2ae852c008f0d881da4e4bec5bd4b97f3b1bffcf46ea4fd2636b873b135bd6', 'Toubia FemCirc as Pub Health Issue NEJM 1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3e2ae852c008f0d881da4e4bec5bd4b97f3b1bffcf46ea4fd2636b873b135bd6.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "The provided text contains repeated digital distribution and copyright notices from The New England Journal of Medicine. It indicates that the material was accessed via the University of Victoria in July 2016 under copyright held by the Massachusetts Medical Society in 1994, without containing any substantive article content.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["The New England Journal of Medicine", "Massachusetts Medical Society", "University of Victoria"], "themes": ["Academic Publishing", "Copyright and Licensing", "Institutional Access"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5b4e1ce8c85948bea2edf409ef6b1d8d61e9f51cb681cffcd9e5b79620590227', 'Toubia FGM Reprod Health Prof IntJGynOb1994.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5b4e1ce8c85948bea2edf409ef6b1d8d61e9f51cb681cffcd9e5b79620590227.pdf', 'medical_journal', 'ingested', '{"date": "1994", "description": "This article addresses the practice of female genital mutilation (FGM) and outlines the professional responsibilities of reproductive healthcare providers in addressing and eliminating it. Focusing primarily on its prevalence and health consequences in Africa, the paper examines clinical topography, epidemiology, and the severe psycho-sexual and physiological effects of these procedures, while advocating for medico-legal and healthcare system interventions against these unnecessary practices.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Nahid Toubia", "A.H. Taba", "Herodotus", "Shandaal", "Verzin"], "organizations": ["International Federation of Gynecology and Obstetrics", "World Health Organization", "Columbia University School of Public Health", "Global Action Against FGM Project"], "themes": ["Female Genital Mutilation", "Reproductive Health", "Medical Ethics", "Public Health", "Women''s Health", "Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1a238bfc237bd33a9ab7b6d09f1855c87fd5ccdd73928bcca0e6849a870fdf5e', 'Townsend Culturally Diverse Res Publica 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1a238bfc237bd33a9ab7b6d09f1855c87fd5ccdd73928bcca0e6849a870fdf5e.pdf', 'other', 'ingested', '{"date": "2023-05-23", "description": "This academic paper examines policy and moral double standards surrounding genital cutting and modification (GCM) practices across culturally diverse Western societies. The author argues that public and legal discourses unjustly differentiate between practices conducted by minority groups\u2014such as female genital cutting (FGC), often labeled ''barbaric'' and coercive\u2014and those accepted within dominant cultures, such as female genital cosmetic surgery (FGCS) framed as individual self-improvement, or intersex genital modification (IGM) justified as medical necessity. Contending that all individuals are culturally embedded and influenced by societal norms, the author asserts that this disparate treatment constitutes cultural discrimination, infantilizes women from minority groups, and fails to protect children. Ultimately, the paper advocates for a consistent, universal policy on genital cutting and modification based on equality to protect all children and uniformly respect adult autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kate Goldie Townsend", "Clare Chambers", "Virginia Braun", "Arianne Shahvisi", "Anna Elisabetta Galeotti", "Andrea C. Westlund"], "organizations": ["The University of Exeter", "Springer Nature", "World Health Organization", "The Royal Society of Medicine"], "themes": ["Genital Cutting and Modification (GCM)", "Cultural Discrimination and Integration", "Autonomy and Consent", "Female Genital Cosmetic Surgery (FGCS)", "Intersex Genital Modification (IGM)", "Children''s Rights and Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7c8582435330674e82bf6137321b6a07ad12dd9c41f5c4937f88b957246cd119', 'Townsend-Defending_inclusive_right_to_genital-IJIR-2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7c8582435330674e82bf6137321b6a07ad12dd9c41f5c4937f88b957246cd119.pdf', 'medical_journal', 'ingested', '{"date": "2021-12-02", "description": "This perspective article argues for an inclusive right to genital and bodily integrity for all children, addressing current legal and policy inconsistencies in Western liberal democracies. While female genital cutting (FGC) is strictly prohibited, male genital cutting (MGC) and intersex genital modifications (IGC) remain widely permitted for religious, cultural, or aesthetic reasons. The author critiques this disparity as cultural bias and rejects ''harm-reduction'' proposals to permit minor forms of FGC, maintaining that children of all sex characteristics deserve equal protection from non-therapeutic interventions until they reach adulthood.\n\nDrawing on liberal normative theory, the author posits that an individual''s right to bodily integrity must take precedence over collective group rights and parental religious freedoms. The paper distinguishes bodily integrity from bodily autonomy, emphasizing that the physical body possesses inherent moral value regardless of the individual''s capacity to consent. Consequently, irreversible cultural or religious modifications unjustly impose permanent physical marks, warranting state prohibition until an individual reaches the age of majority.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kate Goldie Townsend", "Richard A. Shweder", "Roswell Duivenbode", "Kai M\u00f6ller", "Aasim I. Padela"], "organizations": ["University of Exeter", "World Health Organisation", "Brussels Collaboration on Bodily Integrity"], "themes": ["Bodily Integrity", "Children''s Rights", "Genital Cutting and Modification", "Bioethics", "Religious Freedom versus Individual Rights", "Policy Parity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('02f58d90bd312575cea195d771b3250f72cdc6e0b62646bc762256df26fec326', 'Townsend_Childs_Right_Genital_Integrity PhilSocCrit 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/02f58d90bd312575cea195d771b3250f72cdc6e0b62646bc762256df26fec326.pdf', 'other', 'ingested', '{"date": "2019", "description": "This article examines the inconsistency in liberal societies regarding the legal and moral acceptance of male genital cutting contrasted with the condemnation and criminalization of female genital cutting. Kate Goldie Townsend argues that this common intuition cannot be defended within a liberal egalitarian framework committed to equal rights for children, as all children share a physical vulnerability and dependency that warrants protection.\n\nTownsend defends the concept of a child''s inviolable right to genital integrity as a ''right in trust,'' intended to safeguard future adult sexual and bodily autonomy. She addresses and refutes common justifications for the policy divergence, contending that contested medical benefits do not justify irreversible, non-consensual procedures, and that symbolic or patriarchal social harms do not diminish the basic physical and rights violation inherent in cutting non-autonomous children of either sex.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Kate Goldie Townsend", "Joel Feinberg", "Brian D. Earp", "Clare Chambers", "Anna Elisabetta Galeotti"], "organizations": ["University of Exeter", "World Health Organisation", "British Medical Association", "American Association of Pediatrics", "Council of Europe"], "themes": ["Children''s Rights", "Genital Integrity", "Bodily Autonomy", "Male and Female Genital Cutting", "Liberal Theory", "Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('92ade0b27a32e0fdede616bd137ea63728caae7bacafad73abd35c2a42065541', 'TruthSeeker Crimes of GenMutil 1989.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/92ade0b27a32e0fdede616bd137ea63728caae7bacafad73abd35c2a42065541.pdf', 'other', 'ingested', '{"date": "1989", "description": "This special edition of The Truth Seeker compiles proceedings and perspectives from the First International Symposium on Circumcision, arguing that both male circumcision and female genital mutilation represent forms of child abuse, torture, and human rights violations. The contributors examine how these practices originated from ancient patriarchal structures, religious dogma, and cultural anxieties surrounding sexual pleasure and bodily autonomy, rather than legitimate medical necessity. Authors argue that early genital pain and sensory affectional deprivation contribute to long-term psychological damage, violent behavior, and sado-masochistic cultural tendencies.\n\nIn response to these findings, the publication outlines international and domestic legal strategies to abolish genital mutilation. Proposed actions include petitioning the World Court at The Hague under Article V of the UN Universal Declaration of Human Rights and introducing legislation in state legislatures to define non-therapeutic infant circumcision and genital cutting as criminal child abuse, asserting children''s fundamental constitutional rights to bodily integrity, privacy, and liberty.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["James W. Prescott", "Marilyn Fayre Milos", "Gerald A. Larue", "James DeMeo", "Fran P. Hosken", "Charles A. Bonner", "Michael J. Kinane", "Bonnie Lange"], "organizations": ["The Truth Seeker Co., Inc.", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "National League for Separation of Church and State", "Women''s International Network News", "World Health Organization", "Inter-African Committee", "Somali Women''s Democratic Organization", "Italian Association for Women in Development (AIDoS)"], "themes": ["Male Infant Circumcision", "Female Genital Mutilation", "Human Rights and Bodily Integrity", "Religious Dogma and Sexual Repression", "Somatosensory Affectional Deprivation (SAD)", "Constitutional Law and Third-Party Consent", "Medical Ethics and Unnecessary Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c02ee4ddbdca7dbc2f46d1b25c5a66d4e2c8af92a0e002a343556c056c11481e', 'Turkey Govt Disposable Circ Instr 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c02ee4ddbdca7dbc2f46d1b25c5a66d4e2c8af92a0e002a343556c056c11481e.pdf', 'policy_guideline', 'ingested', '{"date": "2019", "description": "This Health Technology Assessment (HTA) report conducted by the Turkish Ministry of Health''s Directorate General of Health Services evaluates the clinical efficacy, safety, cost-effectiveness, and socio-ethical dimensions of disposable medical circumcision instruments compared to traditional surgical techniques. Drawing from global literature and localized healthcare data, the study examines various single-use devices (including Plastibell, PrePex, Shang Ring, and AccuCirc) across pediatric and adult populations, noting their role in streamlining procedures, mitigating surgical complications, and preventing infectious diseases such as HIV.\n\nThe assessment concludes that while disposable devices generally provide safe, standardized, and practical alternatives with reduced blood loss and shorter operative times, operator training is critical to avoid complications like pain during device removal, inadequate excision, and local edema. Additionally, the report outlines the economic, regulatory, and ethical considerations surrounding medical circumcision in Turkey, emphasizing the need for skilled practitioner administration, robust hygiene protocols, and targeted support for domestic medical device manufacturing.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Bilgehan Karaday\u0131", "Olgun \u015eener", "G\u00fcven\u00e7 Ko\u00e7kaya", "Haluk \u00d6zt\u00fcrk", "Sel\u00e7uk \u015een", "Ayd\u0131n Ya\u011fmurlu", "\u0130lhan \u0130lk\u0131l\u0131\u00e7", "Hayriye Erba\u015f"], "organizations": ["Republic of Turkey Ministry of Health", "Sa\u011fl\u0131k Hizmetleri Genel M\u00fcd\u00fcrl\u00fc\u011f\u00fc (SHGM)", "World Health Organization (WHO)", "UNAIDS", "Centers for Disease Control and Prevention (CDC)", "American Academy of Pediatrics (AAP)"], "themes": ["Health Technology Assessment", "Disposable Circumcision Instruments", "Surgical Safety and Complications", "Public Health and Disease Prevention", "Health Economics and Cost Evaluation", "Medical Ethics and Sociocultural Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9639ac75c5506d9b33a74dc2ff421aa9f82b9acc1d6bc4f0a0dc06f1124e2c15', 'Turner Problem of Cultural Relativism JHumRts 2002.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9639ac75c5506d9b33a74dc2ff421aa9f82b9acc1d6bc4f0a0dc06f1124e2c15.pdf', 'other', 'ingested', '{"date": "2002", "description": "This academic paper examines why classical and modern sociology has struggled to construct a coherent theory of universal human rights, tracing this deficiency to the legacy of Max Weber''s perspectivism, the historicism debate, and Friedrich Nietzsche''s critique of values. Turner explores how Weber''s insistence on value neutrality and the disenchantment of the world led to an unresolved ethical relativism, which framed rights not as transcendental norms but as outcomes of political power and national sovereignty. This framework deeply influenced later political theorists like Carl Schmitt, who embraced authoritarian decisionism and the friend/foe distinction, and Leo Strauss, who criticized Weberian nihilism.\n\nTo move beyond this impasse, the author proposes two potential sociological pathways for grounding human rights without abandoning critical inquiry. First, following Alasdair MacIntyre, sociology must recognize that normative values actively shape human action and cannot be entirely severed from causal analysis. Second, building on philosophical anthropology and the sociology of the body, Turner argues that shared human embodiment and vulnerability generate cross-cultural moral sentiments and civilizational restraints against cruelty, providing a universal, ontological foundation for a sociology of human rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Bryan S. Turner", "Max Weber", "Carl Schmitt", "Leo Strauss", "Friedrich Nietzsche", "Ernst Troeltsch", "Wilhelm Dilthey"], "organizations": ["Taylor & Francis", "University of Victoria"], "themes": ["Cultural Relativism", "Sociology of Human Rights", "Perspectivism", "Historicism", "Political Theology and Sovereignty", "Secularization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('05d4f4829770b3d5f59fbaf9f92b1ecaba7037f6e582d63ed85ffac9f0b36c3a', 'Tye Sardi Psycho Aspects Penile Circumcision IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/05d4f4829770b3d5f59fbaf9f92b1ecaba7037f6e582d63ed85ffac9f0b36c3a.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This review article critically examines the neglected psychological, psychosocial, and psychosexual consequences of penile circumcision across infancy, childhood, and adulthood. The authors argue that mainstream medical guidance and policy statements, such as those from the American Academy of Pediatrics, have disproportionately focused on disease prevention and conventional sexual dysfunction while ignoring the subjective experiences of sexual pleasure, alterations to penile biomechanics (such as the loss of the mobile foreskin), and the long-term neurodevelopmental effects of neonatal pain.\n\nAdditionally, the authors highlight the crucial role of sociocultural narratives, parental decision-making pressures, and physician bias in framing attitudes toward circumcision. They call for greater cultural humility in medical practice, expanded empirical research examining subjective sexual repertoires, and ethical policy reforms that ensure patients and parents receive balanced, comprehensive information to achieve genuine informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Marcus C. Tye", "Lauren M. Sardi"], "organizations": ["Pace University", "Quinnipiac University", "Springer Nature", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Penile Circumcision", "Psychosexual Well-being", "Neonatal Pain and Trauma", "Parental Decision-Making", "Informed Consent and Medical Ethics", "Sociocultural Norms and Masculinity", "Penile Biomechanics and Sexual Pleasure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d0568ef561e4965450d902b32524b646d1699349fa9a1483dc7458069ce63537', 'Uberoi Potentially under-recognized IJIR 2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d0568ef561e4965450d902b32524b646d1699349fa9a1483dc7458069ce63537.pdf', 'medical_journal', 'ingested', '{"date": "2022", "description": "This study analyzes the under-recognized long-term physical, psychological, and psychosexual complications associated with non-therapeutic neonatal penile circumcision (NTNPC). By evaluating 135 personal posts from 109 users within a Reddit grief community (''r/CircumcisionGrief''), the authors identified significant adverse outcomes, including loss of sexual sensation, erectile discomfort, distorted body image, depression, violation of bodily autonomy, and damaged relationships with parents and physicians. The study also highlights a ''discovery process'' where men realize later in life that their intimate anatomy was altered without consent.\n\nThe authors note that clinical practice regarding infant circumcision lacks high-level evidence from randomized controlled trials, and argue that discussion of circumcision complications is suppressed by a ''prevalence paradox'' and cultural stigma. Consequently, the paper concludes that normal foreskin tissue removal should be restricted to adult men who actively choose the procedure or cases where it is strictly medically indicated.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Megha Uberoi", "Jasmine Abdulcadir", "Dana A. Ohl", "Javier E. Santiago", "Gurpreet K. Rana", "Frank W. J. Anderson"], "organizations": ["University of Michigan School of Public Health", "Geneva University Hospitals", "University of Michigan Medical School", "Taubman Health Sciences Library", "Springer Nature Limited", "Reddit"], "themes": ["Neonatal Penile Circumcision", "Psychosexual Complications", "Bodily Autonomy and Medical Consent", "Prevalence Paradox and Stigma", "Sexual Sensation Loss", "Qualitative Social Media Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cd94269df666675a5bb97b94e9adcb6980e5560db509d95093540a522c108ace', 'Ullman Glucocorticoids TransPsych 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cd94269df666675a5bb97b94e9adcb6980e5560db509d95093540a522c108ace.pdf', 'medical_journal', 'ingested', '{"date": "2017-03-14", "description": "This study investigates whether male circumcision causes long-term psychological trauma and alterations in the limbic-hypothalamic-pituitary-adrenal (LHPA) axis. By evaluating adult Jewish males (both circumcised and uncircumcised) who immigrated to Germany from the former Soviet Union, the researchers assessed long-term stress hormone levels via hair glucocorticoids (cortisol and cortisone) alongside psychometric tests measuring stress, depressiveness, anxiety, psychosomatic symptoms, sense of coherence, and resilience.\n\nThe findings revealed no significant differences in glucocorticoid accumulation or psychological outcomes between circumcised and uncircumcised individuals. Functional LHPA axis responsiveness remained healthy and correlated normally with physical activity patterns. The authors conclude that male circumcision does not promote long-term psychological trauma or stressor-related disorders, and they propose using the psychological construct of ambivalence to foster more objective, multidisciplinary discussions surrounding the practice.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["E Ullmann", "J Licinio", "A Barthel", "K Petrowski", "B Oratovski", "T Stalder", "C Kirschbaum", "SR Bornstein"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "United Nations Council", "Technical University Dresden", "University of Leipzig", "German Central Jewish Council"], "themes": ["Male Circumcision", "Trauma- and Stressor-Related Disorders", "LHPA Axis and Glucocorticoids", "Hair Cortisol Analysis", "Psychological Resilience", "Religious and Medical Traditions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('460365c84eb4f0e4cbcbfb3db7995c21a74e90cf850ca40a7c403ebe7deb393d', 'UNAIDS Male Circ Trends Prevalence 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/460365c84eb4f0e4cbcbfb3db7995c21a74e90cf850ca40a7c403ebe7deb393d.pdf', 'policy_guideline', 'ingested', '{"date": "2007", "description": "This joint report by the World Health Organization (WHO) and UNAIDS examines global trends, determinants, clinical safety, and public health acceptability surrounding male circumcision, with a dedicated focus on sub-Saharan Africa. Approximately 30% of men globally are circumcised, primarily driven by religious, cultural, and hygienic factors. The document highlights conclusive scientific evidence from observational studies and randomized controlled trials demonstrating that male circumcision significantly reduces the risk of female-to-male HIV transmission by roughly 50\u201360%, alongside reducing risks of urinary tract infections, chancroid, syphilis, and invasive penile cancer.\n\nWhile neonatal and clinical circumcisions have low complication rates (under 1\u20134%), traditional procedures in non-clinical settings carry severe risks of infection, hemorrhage, and death due to inexperienced providers and poor conditions. Addressing rising demand across high-HIV-prevalence regions in eastern and southern Africa, the report emphasizes that adult male circumcision is broadly acceptable if safe and low-cost. Crucially, the authors conclude that scaling up voluntary medical male circumcision must be integrated into comprehensive HIV prevention strategies\u2014such as condom use, reduction of sexual partners, and risk-reduction counseling\u2014while distinguishing male circumcision entirely from the harmful and unacceptable practice of female genital mutilation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Helen Weiss", "Jonny Polonsky", "Robert Bailey", "Catherine Hankins", "Daniel Halperin", "George Schmid"], "organizations": ["World Health Organization", "UNAIDS", "London School of Hygiene and Tropical Medicine", "JHPIEGO", "UNICEF", "United Nations Population Fund"], "themes": ["Male Circumcision", "HIV Prevention", "Public Health and Epidemiology", "Surgical Safety and Complications", "Sociocultural and Religious Determinants", "Global Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0ecbee69a9acd887a1fcb3de0908692e6ce6061a4c0dda8bb31d0bf246a9b155', 'Ungar-Sargon Impermissibility JME 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0ecbee69a9acd887a1fcb3de0908692e6ce6061a4c0dda8bb31d0bf246a9b155.pdf', 'medical_journal', 'ingested', '{"date": "2013-09-06", "description": "In this bioethical critique, Eliyahu Ungar-Sargon responds to Joseph Mazor''s defense of infant male circumcision, arguing that Mazor fails to demonstrate that bodily integrity and self-determination are mere negotiable interests rather than fundamental rights. Ungar-Sargon asserts that parents lack the moral authority to impose permanent, irreversible, and non-therapeutic bodily alterations on pre-autonomous children when less drastic alternatives exist and normal bodily function is impaired.\n\nFurthermore, the author challenges Mazor''s interest-balancing calculations in both secular and religious contexts. Ungar-Sargon rejects the premise that adult circumcision is inherently more costly or risky than the infant procedure, highlighting neonatal surgical risks, trauma, inadequate analgesia, and the violation of the child''s future self-determination. He concludes that neither non-religious parental preferences nor Orthodox Jewish religious traditions justify using an infant''s body as a means to parental or communal ends.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Eliyahu Ungar-Sargon", "Joseph Mazor", "Ronald Dworkin", "Raja Halwani", "Gillian Longley"], "organizations": ["BMJ Publishing Group Ltd", "London School of Economics"], "themes": ["Medical Ethics", "Infant Circumcision", "Bodily Integrity", "Self-Determination", "Pediatric Rights", "Informed Consent", "Religious Traditions"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('64047b150316120fd68d0a7fafa70fcd471644bf4efce2e0a6bb07ef0aa9319c', 'UNICEF FGM-C Statistical Explore 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/64047b150316120fd68d0a7fafa70fcd471644bf4efce2e0a6bb07ef0aa9319c.pdf', 'policy_guideline', 'ingested', '{"date": "2005", "description": "This statistical report published by UNICEF examines the global and regional prevalence, trends, and socio-demographic determinants of female genital mutilation/cutting (FGM/C) across 20 countries using data from Demographic and Health Surveys (DHS) and Multiple Indicator Cluster Surveys (MICS). Categorizing countries into three prevalence tiers, the study analyzes factors influencing the practice, including age cohorts, mother''s educational attainment, household wealth, urban-rural residence, religion, and ethnicity. While prevalence remains high in several nations, comparative generational data between mothers and daughters reveals a gradual decline in the practice and increasing opposition among younger and more educated women.\n\nThe publication highlights critical challenges, notably the concerning trend of ''medicalization''\u2014the growing involvement of trained health professionals in performing FGM/C\u2014which legitimizes the practice while obscuring its fundamental nature as an irreversible human rights violation and manifestation of gender inequality. It explores underlying rationales, finding that social conventions, tradition, and marriageability heavily drive continuation despite low personal support in some communities. The report concludes that sustainable abandonment of FGM/C requires culturally adapted, community-based interventions, legal enforcement, and broader initiatives advancing women''s empowerment and rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Edilberto Loaiza", "Rada Noeva", "Claudia Cappa", "Diakathe Ngagne", "Maria Gabriella De Vita", "Catherine Langevin-Falcon", "Ellen Gruenbaum", "P. Stanley Yoder", "Gerry Mackie"], "organizations": ["UNICEF", "World Health Organization", "United Nations Population Fund", "Macro International", "USAID", "African Union"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Child Protection and Rights", "Gender Equality and Discrimination", "Public Health and Medicalization", "Demographic and Survey Data Analysis", "Social and Cultural Norms"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('da81ee740bc34869c94adc068f2f581eb23dc972e1f5a12a7675a096fadc763c', 'USAID Condomfactsheet2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/da81ee740bc34869c94adc068f2f581eb23dc972e1f5a12a7675a096fadc763c.pdf', 'policy_guideline', 'ingested', '{"date": "2015-01", "description": "This document serves as a technical fact sheet detailing the effectiveness of male and female condoms in preventing HIV, other sexually transmitted infections (STIs), and unintended pregnancies. It highlights USAID''s commitment to promoting correct and consistent condom use alongside compatible lubricants across clinics, pharmacies, and community settings to achieve an AIDS-free generation.\n\nAdditionally, the fact sheet provides statistical evidence demonstrating that condoms substantially reduce the transmission of STIs like gonorrhea, syphilis, chlamydia, herpes, and HPV, while offering dual protection against unintended pregnancy. Epidemiological data from South Africa exemplifies population-level success, where increased condom use significantly contributed to nationwide declines in new HIV infections, especially among young women.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["U.S. Agency for International Development", "USAID", "National Institute of Allergy and Infectious Diseases", "NIAID"], "themes": ["HIV/AIDS Prevention", "Sexually Transmitted Infections (STIs)", "Contraception and Dual Protection", "Public Health Programs", "Condom Effectiveness and Lubricants"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d6e6d688dc135d8a82a5245df8a63f3319e135a2aa4a1e69199883a364df166e', 'Van Bavel Genealogy of silencing FGM WomensHistRev 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d6e6d688dc135d8a82a5245df8a63f3319e135a2aa4a1e69199883a364df166e.pdf', 'medical_journal', 'ingested', '{"date": "2024-11", "description": "This article examines the genealogy of the dominant international discourse surrounding ''Female Genital Mutilation'' (FGM), tracing its origins from British colonial politics in Kenya and Sudan through the post-WWII development era to modern human rights and social norms frameworks. The authors argue that while African women, postcolonial feminists, and anthropologists have consistently challenged this hegemonic narrative for its ethnocentric, sensationalist, and imperialist foundations, their critiques have been systematically sidelined, assimilated, or silenced.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hannelore Van Bavel", "Natasha Carver", "Dorothy Takyiakwaa", "Duchess of Atholl", "Eleanor Rathbone", "Jomo Kenyatta", "Fran Hosken", "Tatu Kamau"], "organizations": ["University of Bristol", "Pennsylvania State University", "SOAS University of London", "Vrije Universiteit Brussel", "Taylor & Francis", "Church Missionary Society", "Church of Scotland Mission", "United Nations", "World Health Organization", "UNICEF", "UNFPA", "Kikuyu Central Association"], "themes": ["Female Genital Mutilation / Female Circumcision", "Postcolonial Feminism", "Imperial and White Feminism", "Coloniality and Knowledge Production", "Silencing Mechanisms", "Human Rights vs Harm Reduction", "Bodily Autonomy and Medicalization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c0522b8d401ab4432bbfefea10d4cf2c49d2e8c641a789388aa31a02e319e470', 'van den Berg Langerin Retrovir 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c0522b8d401ab4432bbfefea10d4cf2c49d2e8c641a789388aa31a02e319e470.pdf', 'medical_journal', 'ingested', '{"date": "2014-12-04", "description": "This study investigates the mechanism by which human Langerhans cells (LCs), the first immune cells encountering HIV-1 during sexual transmission, naturally restrict HIV-1 infection. The researchers demonstrate that the C-type lectin receptor langerin co-localizes with caveolin-1 at the cell membrane and within Birbeck granules (BGs), identifying BGs as caveolin-1-positive structures linked to the lysosomal degradation pathway rather than classical clathrin-dependent compartments.\n\nFunctionally, inhibiting caveolar uptake or silencing caveolin-1 via RNA interference caused a marked increase in HIV-1 genome integration and subsequent infection in primary and model LCs. In contrast, blocking clathrin-mediated endocytosis reduced viral uptake without altering viral integration. These findings establish that caveolin-1-mediated uptake via langerin operates as an intrinsic post-entry restriction mechanism against HIV-1, highlighting potential avenues for preventing sexual transmission by enhancing caveolar endocytosis pathways.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Linda M van den Berg", "Carla M S Ribeiro", "Esther M Zijlstra-Willems", "Lot de Witte", "Donna Fluitsma", "Wikky Tigchelaar", "Vincent Everts", "Teunis B H Geijtenbeek"], "organizations": ["Academic Medical Center, University of Amsterdam", "University Medical Center Utrecht", "VU University Medical Center", "Academic Center for Dentistry Amsterdam", "Dutch Burns Foundation", "Dutch Scientific Organization NWO", "BioMed Central"], "themes": ["HIV-1 Restriction", "Caveolin-1", "Langerhans Cells", "Langerin", "Birbeck Granules", "Caveolar Endocytosis", "Viral Transmission"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ba1f948be2b45d441f98d7cd6b54caf4670fb3f22f27093e5bf1e6e7c2df7af', 'van den Brink Shaping Genitals NethQtrHR 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ba1f948be2b45d441f98d7cd6b54caf4670fb3f22f27093e5bf1e6e7c2df7af.pdf', 'other', 'ingested', '{"date": "2012", "description": "This article provides a comparative frame analysis of male and female circumcision, questioning why female circumcision is broadly condemned as a severe human rights violation while male circumcision is largely normalized, medicalized, or tolerated. The authors categorize circumcision practices into three distinct models\u2014the ''African'' (cultural/ritualistic), the ''American'' (cultural/routine neonatal), and the ''Abrahamic'' (religious)\u2014highlighting that both male and female practices share notable anatomical, procedural, and motivational parallels.\n\nThe authors argue that the divergence in normative assessment is driven by gender, cultural, and religious biases rather than objective physical differences. Western discourse often denies female agency by framing women exclusively as victims while neglecting the bodily integrity of boys and men. To ensure the universal validity of human rights and uphold gender equality, the article proposes evaluating all genital modifications under a single, non-discriminatory framework based on the degree of harm, the presence of informed consent, the weight of the rationale, and the legitimacy of its gendered implications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Marjolein van den Brink", "Jet Tigchelaar", "Fran Hosken", "Yakin Ert\u00fcrk", "Wibren van den Burg"], "organizations": ["World Health Organisation", "Netherlands Institute of Human Rights", "Utrecht University", "UNICEF", "CEDAW Committee"], "themes": ["Bodily Integrity", "Male Circumcision", "Female Genital Mutilation", "Universality of Human Rights", "Gender Equality", "Cultural and Religious Framing"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('77a79fbb49e619ad337b751e71d8cfba4aa4324e893be47b129a863082687e42', 'Van Howe Bollinger Alexithymia IntJMenHlth 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/77a79fbb49e619ad337b751e71d8cfba4aa4324e893be47b129a863082687e42.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This preliminary study explores the relationship between early trauma from male circumcision and the prevalence of alexithymia\u2014a trait characterized by difficulty in identifying and expressing emotions. Evaluating 300 self-selected adult men using the Toronto Twenty-Item Alexithymia Scale (TAS-20), the researchers observed that circumcised men exhibited age-adjusted alexithymia scores approximately 19.9 percent higher than intact men, showing particular elevations in difficulty identifying and describing feelings.\n\nFurthermore, the study identified a statistically significant correlation between circumcision status and sexual dysfunction, noting that circumcised participants were 4.53 times more likely to use erectile dysfunction medication. While noting limitations regarding self-selection and the need for randomized population studies, the authors propose that neonatal surgical trauma may have enduring psychological and psychosexual effects in adult men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dan Bollinger", "Robert S. Van Howe", "Graeme J. Taylor"], "organizations": ["Michigan State University College of Human Medicine", "Men''s Studies Press, LLC", "Menstuff.org", "TheMensCenter.com"], "themes": ["Alexithymia", "Male Circumcision", "Neonatal Trauma", "Erectile Dysfunction", "Men''s Mental Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d283de28114df7fe048dbd04fe50b41e0a9570a3ae8ab234bc1a171e286015a2', 'Van Howe CDC-requested_Critique 2015 (paper).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d283de28114df7fe048dbd04fe50b41e0a9570a3ae8ab234bc1a171e286015a2.pdf', 'other', 'ingested', '{"date": "2015-01-15", "description": "This document is an evidence-based critique written by Dr. Robert S. Van Howe in response to the Centers for Disease Control and Prevention''s (CDC) 2014 draft recommendations on male circumcision. Van Howe argues that the CDC draft lacks scientific and scholarly rigor, relies on selective literature and outdated review articles, and suffers from expectation bias. He contends that randomized controlled trials from sub-Saharan Africa showing partial HIV risk reduction are plagued by critical methodological flaws\u2014such as lack of blinding, lead-time bias, and failure to verify infection sources\u2014and cannot be generalized to the United States or applied to infant circumcisions.\n\nFurthermore, Van Howe emphasizes that the CDC fails to account for the foreskin''s normal anatomy, histological function, and immunological benefits, while drastically understating the harms, risks, and complication rates of neonatal circumcision. He highlights that non-therapeutic infant circumcision violates medical ethics and children''s human rights, aligning the CDC with culturally biased viewpoints rather than the consensus of international medical associations that oppose routine infant circumcision. Ultimately, he calls for the CDC to withdraw the draft completely and conduct an objective, rigorous re-evaluation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Robert S. Van Howe", "Robert Bailey"], "organizations": ["Centers for Disease Control and Prevention", "Central Michigan University College of Medicine", "American Academy of Pediatrics", "Council of Europe", "World Health Organization", "UNAIDS", "American Medical Association"], "themes": ["Male Circumcision", "HIV and STI Prevention", "Medical Ethics and Informed Consent", "Evidence-Based Medicine", "Epidemiological Methodology", "Neonatal and Infant Health", "Bias in Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eab8e03c265391cc963f34a5df9e9afd29d97ae8a3894ae27f19f341caf5879a', 'Van Howe Circ will increase HIV JPHA 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eab8e03c265391cc963f34a5df9e9afd29d97ae8a3894ae27f19f341caf5879a.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This article critically evaluates the initiative led by the World Health Organization (WHO) and UNAIDS to promote mass male circumcision as an HIV prevention strategy in sub-Saharan Africa. The authors argue that the recommendation is built on flawed randomized clinical trials that failed to distinguish between sexual and non-sexual transmission routes, suffered from various systemic biases, and lacked biological plausibility. Furthermore, population-level epidemiological data across multiple nations fails to demonstrate a protective effect for circumcised men.\n\nThe authors contend that widespread circumcision programs may inadvertently increase HIV transmission due to risk compensation\u2014where circumcised men decrease condom usage under the false impression of full immunity. They conclude that mass circumcision is an invasive, cost-ineffective diversion of limited resources away from superior interventions, such as condom promotion, antiretroviral therapy (ART) ''test and treat'' programs, and aggressive surveillance of sexually transmitted infections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "Michelle R. Storms"], "organizations": ["World Health Organization", "UNAIDS", "Michigan State University"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Risk Compensation", "Public Health Policy", "Epidemiology", "Healthcare Resource Allocation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ae8ea578d5723a3942719c36280fbfbeb2db760d870f72bb72c7cfa2e878ee25', 'Van Howe Circ_influence_STD BJU 1999.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ae8ea578d5723a3942719c36280fbfbeb2db760d870f72bb72c7cfa2e878ee25.pdf', 'medical_journal', 'ingested', '{"date": "1999", "description": "This literature review evaluates whether male circumcision influences the transmission and prevalence of sexually transmitted diseases (STDs), including HIV, syphilis, gonorrhoea, chlamydia, herpes simplex virus, and human papillomavirus. Assessing 31 controlled studies alongside Hill''s criteria for causality, the author argues that the existing medical literature suffers from severe methodological shortcomings, such as selection bias in STD clinic cohorts and failure to control for critical confounding variables like race, socioeconomic status, and lifetime partner count.\n\nThe review concludes that there is no consistent or methodologically sound evidence demonstrating that circumcision prevents STDs or HIV infection overall. While uncircumcised men appear somewhat more susceptible to genital ulcer disease, circumcised men demonstrate higher or equivalent rates of urethritis and chlamydial infections, leading to the conclusion that routine neonatal or mass circumcision cannot be justified as an effective STD prevention measure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R.S. Van Howe", "E.O. Laumann", "A.B. Hill", "J. Hutchinson", "A.L. Wolbarst"], "organizations": ["Medical College of Wisconsin", "Marshfield Clinic", "BJU International", "Mayo Clinic"], "themes": ["Male Circumcision", "Sexually Transmitted Diseases (STDs)", "HIV Transmission", "Epidemiological Methodology", "Genital Ulcer Disease and Urethritis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6ca77c73d061afdb73c8fba4c611ba404a5e2bc86d1067f7ce413eeb0296d519', 'Van Howe Circ_registry_BMC 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6ca77c73d061afdb73c8fba4c611ba404a5e2bc86d1067f7ce413eeb0296d519.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This academic correspondence features an ethical debate concerning the Danish circumcision registry. Robert S. Van Howe and colleagues argue that maintaining an anonymized circumcision registry is vital for generating accurate epidemiological data on the potential medical risks of non-therapeutic circumcision, thereby enabling informed parental decision-making and protecting child welfare without causing undue social harm or stigmatization.\n\nIn response, Thomas Ploug and S\u00f8ren Holm clarify that their core argument centers on the principle of informed consent in registry-based research rather than the merits or harms of circumcision itself. They contend that registry participation carries plausible risks of social harm, group discrimination, and medicalization, meaning individuals\u2014or parents on their behalf\u2014should retain the right to provide or withhold consent rather than being subjected to mandatory inclusion.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "Morten Frisch", "Peter W. Adler", "J. Steven Svoboda", "Thomas Ploug", "S\u00f8ren Holm"], "organizations": ["Central Michigan University", "Aalborg University", "University of Massachusetts Lowell", "Attorneys for the Rights of the Child", "University of Manchester", "University of Oslo", "Danish Data Protection Agency"], "themes": ["Male Circumcision", "Health Data Registries", "Informed Consent", "Bioethics", "Data Protection and Privacy", "Medicalization and Stigmatization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1b6785b31e61c986396b8365437e67a19be9931c0da4f20ef6062db19d921093', 'Van Howe Cost Utility MedDecMaking 2004.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1b6785b31e61c986396b8365437e67a19be9931c0da4f20ef6062db19d921093.pdf', 'medical_journal', 'ingested', '{"date": "2004", "description": "This academic paper presents a lifetime cost-utility analysis evaluating routine neonatal male circumcision versus noncircumcision from a societal perspective using a Markov model and the Quality of Well-being Scale. Drawing upon published epidemiological data across multiple conditions\u2014such as urinary tract infections, phimosis, penile cancer, sexually transmitted diseases, and procedural complications\u2014the baseline analysis found that neonatal circumcision increased incremental costs by $828.42 per patient and resulted in 15.30 well-years lost per 1,000 males at a 3% discount rate.\n\nExtensive sensitivity analyses and Monte Carlo simulations revealed that even under hypothetical best-case conditions (cost-free, pain-free, and without immediate complications), neonatal circumcision remained more costly and led to net negative health utility compared to leaving genitalia intact. The author concludes that neonatal circumcision cannot be medically or financially justified, represents undesirable health policy, and should not be reimbursed by third-party insurers or endorsed by clinicians as routine medical care.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe"], "organizations": ["Michigan State University College of Human Medicine", "Society for Medical Decision Making", "American Academy of Pediatrics", "Canadian Paediatric Society", "Centers for Disease Control and Prevention", "US Public Health Service"], "themes": ["Neonatal Circumcision", "Cost-Utility Analysis", "Health Economics and Policy", "Preventive Healthcare", "Pediatric Health Outcomes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('990a4cd98c7861f9f5f2a53e177d4f022a9af8e6e3fb204ffa44715aae427179', 'Van Howe dead dogma parental rights JME 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/990a4cd98c7861f9f5f2a53e177d4f022a9af8e6e3fb204ffa44715aae427179.pdf', 'medical_journal', 'ingested', '{"date": "2013-05-22", "description": "In this article, Robert S. Van Howe argues that the concept of sovereignal parental rights is an outdated ''dead dogma'' historically rooted in treating children as property. Drawing from John Rawls'' framework of justice and human rights, Van Howe contends that parents do not hold rights over their children''s bodies; rather, they possess an ethical obligation to safeguard their children''s basic human rights, bodily integrity, and future autonomy until the child can make informed decisions for themselves.\n\nApplying this framework to infant male circumcision, the author asserts that non-therapeutic genital cutting violates bodily integrity without therapeutic necessity or consent, rendering it a human rights violation. He refutes common ethical and medical justifications\u2014including constrained parental autonomy, the harm principle, and health claims cited by the American Academy of Pediatrics (AAP)\u2014concluding that appealing to parental authority is merely the final, flawed defense for subjecting non-consenting infants to irreversible surgical harm.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S Van Howe", "John Rawls", "Douglas Diekema", "Lanie Friedman Ross", "James G. Dwyer", "A. M. Viens"], "organizations": ["Michigan State University College of Human Medicine", "American Academy of Pediatrics"], "themes": ["Infant Circumcision", "Parental Rights vs. Children''s Rights", "Bodily Integrity", "Pediatric Bioethics", "Best Interests Standard", "Religious and Cultural Autonomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('52b1374e62da5c2a5242bf80cfabf15d4e487748548540ee3f0a4d2c04eb90ae', 'Van Howe Expertise reply to Morris GlobPubHealth 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/52b1374e62da5c2a5242bf80cfabf15d4e487748548540ee3f0a4d2c04eb90ae.pdf', 'letter', 'ingested', '{"date": "2017-01-10", "description": "In this response letter published in Global Public Health, Robert S. Van Howe defends his prior meta-regression analysis evaluating the association between male circumcision and HIV infection risk against critiques by Brian J. Morris and colleagues. Van Howe refutes allegations regarding methodological flaws, biased study selection, and unreproducible data, arguing that his use of raw published data and multivariate regression adheres to established statistical standards.\n\nVan Howe contends that Morris and his co-authors lack formal contributory expertise in meta-regression and epidemiology, relying instead on repetitive rebuttals, heavy self-citation, and ad hominem critiques. He argues that their persistent promotion of non-therapeutic circumcision reflects an ideological agenda rather than impartial scientific inquiry, asserting that the purported protective benefits and cost-effectiveness of mass circumcision programs have been substantially overstated.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Robert S. Van Howe", "Brian J. Morris", "Jeffrey N. Krieger", "Richard G. Wamai", "Harry Collins", "Edward Langerak"], "organizations": ["Global Public Health", "Central Michigan University College of Medicine", "Circumcision Academy of Australia", "The Bill and Melinda Gates Foundation", "Clinton Health Access Initiative", "President''s Emergency Plan for AIDS Relief (PEPFAR)"], "themes": ["Male Circumcision and HIV Transmission", "Meta-Regression and Statistical Methodology", "Scientific Integrity versus Ideological Advocacy", "Public Health Intervention Efficacy", "Academic Polemics and Peer Review"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8fd446f2d55e4d86a665c8754b39ab7b58eeb4f98e54cbde20852711a475b34c', 'Van Howe HIV_Hyperbole JRoySocPromoHlth 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8fd446f2d55e4d86a665c8754b39ab7b58eeb4f98e54cbde20852711a475b34c.pdf', 'medical_journal', 'ingested', '{"date": "2005", "description": "This article critically evaluates the medical, epidemiological, and ethical justifications for promoting mass male circumcision as a preventive intervention against HIV infection, especially in sub-Saharan Africa. The authors argue that the purported epidemiological evidence is derived from inconsistent, biased observational studies with significant confounding variables such as religion, hygiene, and tribal affiliation. They assert that claims regarding biological plausibility are unsubstantiated and that mass surgical interventions present serious surgical complication risks, permanently destroy sensitive genital tissue, and infringe upon individual human rights and informed consent.\n\nAdditionally, the authors contextualize the HIV-circumcision hypothesis within a 130-year medical history in English-speaking nations of promoting circumcision as a panacea for various ailments, ranging from masturbation and epilepsy to cancer. They argue that the campaign for universal circumcision in developing countries is largely driven by Western advocates seeking to justify and revive declining rates of routine neonatal circumcision in North America, rather than providing a cost-effective or culturally appropriate public health solution.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S Van Howe", "J Steven Svoboda", "Frederick M Hodges", "Aaron J. Fink", "Robert C. Bailey", "Stephen Moses"], "organizations": ["The Royal Society for the Promotion of Health", "Attorneys for the Rights of the Child", "American Academy of Pediatrics", "Canadian Paediatric Society", "Royal Australasian College of Physicians", "National Institutes of Health"], "themes": ["Male Circumcision", "HIV/AIDS Transmission and Prophylaxis", "Medical Ethics and Informed Consent", "Human Rights and Bodily Integrity", "Epidemiological Bias and Methodology", "History of Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('85d09dd32087a81635078ee9e6e4a2dab36cfe7be84a256a583a88b58dd582ba', 'Van Howe HPV & Circ JInf 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/85d09dd32087a81635078ee9e6e4a2dab36cfe7be84a256a583a88b58dd582ba.pdf', 'medical_journal', 'ingested', '{"date": "2006-09-25", "description": "This meta-analysis evaluates the relationship between male circumcision status and the risk of genital human papillomavirus (HPV) infection. Reviewing sixteen observational studies, the author notes that many suffered from substantial methodological limitations, such as reliance on self-reported circumcision status and the failure to sample the penile shaft, where HPV infections are predominantly localized in circumcised men. Only three studies met strict criteria requiring verified circumcision via physical examination, accurate laboratory diagnostics, and comprehensive multi-site sampling including the penile shaft.\n\nPooling the data from the eligible studies using a random-effects model, the analysis found no statistically significant association between circumcision status and genital HPV infection (OR = 1.20, 95% CI: 0.80\u20131.79). Even after applying meta-regression adjustments to eight studies with reliable diagnostic techniques, no significant protective effect was observed (OR = 1.25, 95% CI: 0.95\u20131.67). The author concludes that the medical literature does not support the claim that circumcision protects against genital HPV infection and emphasizes the necessity of sampling the penile shaft to accurately assess male HPV status.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe"], "organizations": ["Michigan State University College of Human Medicine", "The British Infection Society", "Elsevier", "American Academy of Pediatrics"], "themes": ["Human Papillomavirus (HPV)", "Male Circumcision", "Sexually Transmitted Infections", "Penile Cancer", "Meta-Analysis Methodology", "Diagnostic Sampling Bias"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7f7e5d85ab8a1bdf2229d768b0bafe47ad8991de4ba2c00c18643b798094d729', 'Van Howe HPV & Circ Symposium2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7f7e5d85ab8a1bdf2229d768b0bafe47ad8991de4ba2c00c18643b798094d729.pdf', 'medical_journal', 'ingested', '{"date": "2014-07-24", "description": "In this paper, Dr. Robert S. Van Howe critically evaluates claims that male circumcision reduces the risk of human papillomavirus (HPV) infection and subsequent cervical cancer in female sexual partners. Van Howe argues that studies suggesting a protective effect of circumcision suffer from profound methodological flaws, including sampling bias (such as sampling only the glans rather than the penile shaft where circumcised men frequently carry HPV), misclassification bias from self-reported circumcision status, and geographical confounding. When adjusting for these biases, the apparent protective association between circumcision and HPV risk disappears.\n\nFurthermore, the author examines epidemiological data regarding cervical cancer, highlighting that numerous studies have failed to demonstrate any statistically significant protective link to male partner circumcision, particularly regarding high-risk oncogenic types HPV 16 and 18. Reviewing prospective cohort studies and meta-analyses\u2014including the HIM study\u2014Van Howe concludes that medical evidence does not support promoting circumcision as a preventative measure against HPV or cervical cancer.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "Tim Farley", "Morton Frisch"], "organizations": ["Central Michigan University College of Medicine", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "World Health Organization", "Johns Hopkins University", "University of Washington"], "themes": ["Male Circumcision", "Human Papillomavirus (HPV)", "Cervical Cancer", "Epidemiological Bias", "Sexually Transmitted Infections"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0cffe33c874d35d2161d17e4d789134c54fcb090701ab35ba82907c7f4e841f0', 'Van Howe HPV_&_circ reply Castellsague JInfect 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0cffe33c874d35d2161d17e4d789134c54fcb090701ab35ba82907c7f4e841f0.pdf', 'medical_journal', 'ingested', '{"date": "2007-04-17", "description": "This document is an academic exchange published in the Journal of Infection, primarily featuring a reply by Dr. Robert Storms Van Howe to Dr. Xavier Castellsagu\u00e9 and colleagues regarding a controversial meta-analysis on the relationship between male circumcision and human papillomavirus (HPV) infection. Van Howe defends his analytical methods and inclusion criteria against criticisms of bias, arguing that many prior studies failed to properly detect HPV in circumcised men by neglecting to sample the penile shaft and scrotum, where circumcised men predominantly harbor the virus.\n\nVan Howe contends that incomplete anatomical sampling and reliance on self-reported circumcision status introduce critical misclassification and sampling biases, which artificially inflate the apparent protective effect of circumcision against HPV and cervical cancer. He critiques the methodology of Castellsagu\u00e9''s landmark multicenter study, maintaining that when accounting for anatomical differences in lesion distribution and adjusting for potential confounders, the evidence supporting universal infant circumcision as a protective measure against HPV transmission remains inconclusive.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert Storms Van Howe", "Xavier Castellsagu\u00e9", "Ginesa Albero", "Ram\u00f3n Cl\u00e8ries", "F. Xavier Bosch"], "organizations": ["The British Infection Society", "Elsevier", "Institut Catal\u00e0 d''Oncologia", "Michigan State University College of Human Medicine"], "themes": ["Human Papillomavirus (HPV)", "Male Circumcision", "Epidemiological Methodology", "Sampling and Misclassification Bias", "Cervical Cancer Prevention"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('dfc56f0b9455af6f13b87e8ae80610ed8699c52fdb50d446cefd6a401df515fe', 'Van Howe Meatal_Stenosis ClinPeds 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/dfc56f0b9455af6f13b87e8ae80610ed8699c52fdb50d446cefd6a401df515fe.pdf', 'medical_journal', 'ingested', '{"date": "2006", "description": "This prospective study investigates the incidence of meatal stenosis following neonatal circumcision in a primary care pediatric cohort in rural northern Wisconsin. Among 1,100 examined boys, symptomatic meatal stenosis was identified exclusively in circumcised boys, occurring in 7.29% of circumcised boys older than 3 years at Tanner stage I development, with nearly all requiring surgical meatotomy for resolution.\n\nThe author argues that meatal stenosis is likely the most common post-circumcision complication, frequently overlooked or minimized in major professional guidelines such as those from the American Academy of Pediatrics. The paper concludes that the risk of meatal stenosis and potential subsequent surgical intervention should be routinely disclosed during informed consent for neonatal circumcision, and recommends prepuce-sparing procedures when intervention is necessary.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "William M. Mastin"], "organizations": ["American Academy of Pediatrics", "Michigan State University College of Human Medicine", "Marshfield Clinic", "Westminster Publications, Inc."], "themes": ["Neonatal Circumcision", "Meatal Stenosis", "Pediatric Urology", "Postoperative Complications", "Informed Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('3a930240036c47611b64b1cb4147d335e52bca0a463b24147265aed0c9f7e8f6', 'Van Howe Response to Vogelstein 2012AAP  Bioethics 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/3a930240036c47611b64b1cb4147d335e52bca0a463b24147265aed0c9f7e8f6.pdf', 'medical_journal', 'ingested', '{"date": "2018", "description": "In this response article, Robert S. Van Howe critiques Eric Vogelstein''s endorsement of the 2012 American Academy of Pediatrics (AAP) Task Force on Circumcision as a model for organizational position statements. Van Howe argues that the AAP Task Force demonstrated substantial bias by selectively evaluating evidence, dismissing complications, and deviating from standard quality assessment frameworks to justify infant male circumcision. Additionally, he highlights the panel''s lack of relevant expertise, neglect of substantial ethical discussions on bodily integrity, failure to conduct a legitimate quantitative risk-benefit balance, and growing international isolation among global medical bodies that view non-therapeutic circumcision as an infringement on children''s rights.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert S. Van Howe", "Eric Vogelstein", "Andrew Freedman"], "organizations": ["American Academy of Pediatrics", "Central Michigan University College of Medicine"], "themes": ["Infant male circumcision", "Medical ethics", "Children''s rights and bodily integrity", "Clinical guideline methodology", "Cultural bias in medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c5f58a2ad1ebee262983502a2df7f3bfc9eaf32f4200692ff0cbdd1c399b810c', 'Van Howe Variability appearance BJU 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c5f58a2ad1ebee262983502a2df7f3bfc9eaf32f4200692ff0cbdd1c399b810c.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This prospective study evaluates penile appearance and clinical findings in a cohort of 468 boys examined at a primary care pediatric practice in rural Wisconsin. The findings reveal that circumcised boys under three years of age were significantly more likely to present with non-cosmetic issues\u2014such as coronal adhesions, trapped epithelial debris, a reddened meatus, and balanitis\u2014compared to intact boys or older circumcised children. In contrast, preputial stenosis affected intact and circumcised boys at comparable rates.\n\nThe author concludes that clinical penile complications following neonatal circumcision are substantially more prevalent than previously documented in retrospective studies. The paper emphasizes that the circumcised penis necessitates regular hygiene and gentle skin retraction during the first three years of life to avoid adhesions and debris accumulation, while cautioning against surgical circumcision revisions for purely cosmetic reasons on both clinical and ethical grounds.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R.S. Van Howe", "Cynthia J. Musser"], "organizations": ["Marshfield Clinic", "British Journal of Urology", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Pediatric Urology", "Postoperative Complications", "Penile Hygiene and Anatomy", "Medical Ethics and Cosmetic Surgery"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fa3ee4e8cdf8da6b0f12689314bf438cb8a62604f8beac203f3ecae7dbde025e', 'Van Howe_smegma_carcinogenicity JEADV 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fa3ee4e8cdf8da6b0f12689314bf438cb8a62604f8beac203f3ecae7dbde025e.pdf', 'medical_journal', 'ingested', '{"date": "2006", "description": "This review article critically examines the longstanding medical belief that smegma is a causative agent for penile, cervical, and prostate cancers. Through a detailed historical evaluation and statistical reanalysis of original animal experiments and human epidemiological studies, the authors find no valid empirical evidence demonstrating that smegma possesses carcinogenic properties. Instead, they trace the demonization of smegma to nineteenth-century anti-masturbation anxieties and early twentieth-century pro-circumcision campaigns, concluding that the attribution of malignancy to smegma is an unfounded myth that fails Hill''s criteria for causation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["RS Van Howe", "FM Hodges", "Abraham Wolbarst", "Abraham Ravich", "Claude-Fran\u00e7ois Lallemand", "Roberts Bartholow"], "organizations": ["European Academy of Dermatology and Venereology", "Michigan State University School of Human Medicine", "Blackwell Publishing Ltd"], "themes": ["Carcinogenicity of Smegma", "Male Circumcision", "Penile Cancer", "Cervical Cancer", "Medical History and Myth Debunking", "Epidemiology and Causation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c4c832ded97897ebe3140097794b5b4028cf3d92b6b79882038cded2c0b19e3a', 'Vega Free_Split-Skin_Grafting UroAndro 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c4c832ded97897ebe3140097794b5b4028cf3d92b6b79882038cded2c0b19e3a.pdf', 'medical_journal', 'ingested', '{"date": "2017-06-05", "description": "This medical case report details the successful treatment of a symptomatic partially buried penis resulting from excessive skin excision during childhood circumcision in an 11-year-old boy. The patient suffered from severe pain during erections due to insufficient skin elasticity, which had persisted for two years without adequate surgical intervention.\n\nSurgeons performed a release of the penile shaft skin and reconstructed the circumferential deficit using an autologous split-thickness skin graft harvested from the inguinal region. Over a two-year follow-up, the graft showed good functional and cosmetic integration without contractures or impairment of penile growth, demonstrating that split-skin grafting is a viable and effective procedure to correct radical circumcision complications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Antonio Vega Vega", "Isaac Thangasamy", "Craig Moore"], "organizations": ["Mater Hospital Outpatient Department"], "themes": ["Circumcision Complications", "Urological Reconstruction", "Split-Skin Grafting", "Buried Penis", "Pediatric Urology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('01840cb13582f89007a44ace108bee1a124f47d77bd56f2abac3571451a0a5c5', 'Ventura, Bonsignore Circ, ritual AnnIstSuper 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/01840cb13582f89007a44ace108bee1a124f47d77bd56f2abac3571451a0a5c5.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This article examines the medical, ethical, legal, and public health dimensions of male circumcision (MC), with a specific focus on ritual circumcision of minors in Italy. Following several fatal incidents in Italy resulting from clandestine procedures performed by unqualified practitioners in unhygienic environments, the authors explore the urgent need to address this public health hazard.\n\nAfter reviewing the historical, prophylactic, and cultural frameworks of circumcision alongside international legal precedents on minors'' bodily autonomy and parental religious freedom, the authors analyze the Italian healthcare system''s fragmented regional policies. They argue that to safeguard child health and minimize lethal complications like hemorrhaging, the Italian National Health Service (NHS) should consider providing ritual circumcision under sterile clinical conditions either free of charge or at subsidized rates, accompanied by comprehensive educational campaigns for affected immigrant and minority communities.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Francesco Ventura", "Fiorella Caputo", "Marta Licata", "Alessandro Bonsignore", "Rosagemma Ciliberti", "Lewis Albert Sayre"], "organizations": ["Universit\u00e0 degli Studi di Genova", "Universit\u00e0 degli Studi dell\u2019Insubria", "Istituto Superiore di Sanit\u00e0", "Italian National Health Service", "Comitato Nazionale di Bioetica", "World Health Organization", "American Academy of Pediatrics", "British Medical Association", "Federazione Nazionale degli Ordini dei Medici Chirurghi e degli Odontoiatri"], "themes": ["Male Circumcision", "Ritual and Religious Practices", "Bioethics and Minors'' Rights", "Public Health and Patient Safety", "Healthcare Policy and Access"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2221f41ca20b117efbce4c2eccf31f2e0f2f7426626d48848f0069566996c641', 'Viviani Male Circ Italy Springer 2006.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2221f41ca20b117efbce4c2eccf31f2e0f2f7426626d48848f0069566996c641.pdf', 'other', 'ingested', '{"date": "2006", "description": "The provided document text consists entirely of unreadable control characters, symbols, and corrupted text encoding artifacts. No coherent text, arguments, or factual information could be deciphered.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": [], "themes": []}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0ce403d6eea716dc7cff0c7bf7e5572ade460d284756731963581a4671bc10c4', 'Vloeberghs Coping and consequences FGM Ethn&Hlth 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0ce403d6eea716dc7cff0c7bf7e5572ade460d284756731963581a4671bc10c4.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This mixed-methods study investigates the long-term psychosocial, mental, and relational consequences of female genital mutilation/cutting (FGM/C) among 66 African immigrant women living in the Netherlands. The findings indicate that approximately one in six participants exhibited symptoms of post-traumatic stress disorder (PTSD), and one-third reported symptoms related to depression or anxiety. Infibulation, clear recall of the event, and older age at migration were associated with higher psychological distress.\n\nMigration to the Netherlands heightened women''s awareness of the non-religious, harmful nature of the practice and fostered resistance against continuing it for their daughters. However, encounters with Dutch healthcare professionals frequently induced shame, embarrassment, and perceived stigmatization due to medical staff''s visible shock or lack of understanding. The authors propose a coping taxonomy categorizing the women into three distinct groups\u2014the adaptives, the disempowered, and the traumatized\u2014and emphasize the urgent need for culturally sensitive, informed communication among healthcare providers.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Erick Vloeberghs", "Anke van der Kwaak", "Jeroen Knipscheer", "Maria van den Muijsenbergh"], "organizations": ["PHAROS - Knowledge and Advisory Centre on Refugees'' and Migrants'' Health", "Royal Tropical Institute (KIT)", "Utrecht University", "Arq Foundation", "Radboud University Medical Centre", "World Health Organization (WHO)", "UNICEF", "Federation of Somali Associations in the Netherlands (FSAN)"], "themes": ["Female Genital Mutilation/Cutting (FGM/C)", "Migrant Mental Health", "Post-Traumatic Stress Disorder (PTSD)", "Coping Strategies and Taxonomy", "Cultural Acculturation and Awareness", "Healthcare Provider Communication and Stigma"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5bf68fed832eaa4b39c8a23f6434b0c73e8091c382eeeff26449cb2f5a4f6a4a', 'Wade Politics_of_Acculturation_FGC SocialProb 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5bf68fed832eaa4b39c8a23f6434b0c73e8091c382eeeff26449cb2f5a4f6a4a.pdf', 'other', 'ingested', '{"date": "2011", "description": "This article analyzes a 1996 controversy at Seattle''s Harborview Medical Center, where physicians proposed offering a minor symbolic incision\u2014a clitoral prepotomy or ''ritual nick''\u2014to Somali immigrant girls as a harm-reduction alternative to traditional infibulation. Author Lisa Wade examines how competing discursive frameworks and models of culture shaped perceptions of this compromise. Opponents utilized a reified model of culture that viewed Somali immigrants as rigidly culture-bound, framing any form of genital cutting as symbolically identical to severe mutilation and arguing that multicultural accommodation inherently undermined feminist human rights.\n\nIn contrast, physicians operated under a dynamic model of culture, viewing the procedure as an evolutionary step and a pragmatic bridge toward acculturation and ultimate abandonment. However, Wade demonstrates that this dynamic model also had flaws: physicians over-idealized their capacity to chaperone cultural change, dismissed valid feminist concerns regarding bodily autonomy and patriarchy, and excluded critical stakeholders from the decision-making process. The study concludes that both models problematicized the hermeneutics of cultural change, offering vital lessons for how multicultural democracies navigate conflicts between cultural diversity and gender equality.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Lisa Wade", "Leslie Miller", "Patricia Schroeder", "Meserak Ramsey", "Mariama Barrie-Diamond", "Susan Moller Okin"], "organizations": ["Harborview Medical Center", "Society for the Study of Social Problems", "Oxford University Press", "American Academy of Pediatrics", "Equality Now", "World Health Organization"], "themes": ["Female Genital Cutting (FGC)", "Multiculturalism and Feminism", "Models of Culture", "Acculturation and Cultural Change", "Medical Ethics and Harm Reduction", "Immigrant Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('37504d87b18a3991f8272bbd06ae20523d91f5f11674f378ff80353ccb7c9ee1', 'Wahedi Constitutional Dynamics Relig Manifest (thesis) 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/37504d87b18a3991f8272bbd06ae20523d91f5f11674f378ff80353ccb7c9ee1.pdf', 'other', 'ingested', '{"date": "2019-11-28", "description": "This doctoral dissertation examines whether liberal constitutional democracies should single out religion qua religion for either favored treatment (such as exemptions and legal accommodations) or disfavored treatment (such as targeted bans and discriminatory restrictions). Developing a theoretical framework centered on ''abstraction from the religious dimension,'' the author analyzes how liberal political philosophy tends to defend religious freedom by repackaging religious practices into non-sectarian, egalitarian categories such as conscience, expression, and association.\n\nThrough an analysis encompassing the legal and political approaches to ritual male and female circumcision, European jurisprudence on Islamic dress and religious symbols, and United States immigration measures, the research demonstrates a dual dynamic. While abstraction theoretically prevents sectarian favoritism, it also creates vulnerabilities where facially neutral arguments can be weaponized to reinforce majoritarianism and enact discriminatory policies against minority faiths. The author utilizes the method of reflective equilibrium to advocate for a principled, equality-based approach to religious freedom that guards against both unjust privilege and majoritarian exclusion.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Sohail Wahedi", "R.C.M.E. Engels", "W. van der Burg", "J.D. Temperman", "E. Brems", "T.J. Gunn", "K.A.M. Henrard", "Ren\u00e9e Kool", "Martha C. Nussbaum", "Donald Trump"], "organizations": ["Erasmus University Rotterdam", "Council of Europe", "Parliamentary Assembly of the Council of Europe", "European Court of Human Rights", "Hoge Raad der Nederlanden"], "themes": ["Freedom of Religion", "Religious Accommodation", "Ritual Circumcision", "State Neutrality", "Majoritarianism", "Legal Philosophy and Liberalism", "Discrimination and Minority Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('547fe35c28679f59e97003a7e44908b84a9c61eb8c3de7a15fcc1561bdd93393', 'Wahlberg Sameness_to_difference_FGC MGC CultHlthSex 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/547fe35c28679f59e97003a7e44908b84a9c61eb8c3de7a15fcc1561bdd93393.pdf', 'medical_journal', 'ingested', '{"date": "2018-11-09", "description": "This qualitative study explores how migration to Sweden influences Somali immigrants'' perceptions of non-therapeutic female circumcision (FC) and male circumcision (MC). In Somalia, both procedures have historically been viewed as culturally complementary and positive acts. However, following migration to Sweden\u2014a context where FC is strictly criminalized while MC is legally accepted\u2014Somali immigrants experience a renegotiation of core values concerning religious adherence, avoidance of harm, and social respectability.\n\nThe authors conducted 18 individual interviews and seven focus group discussions with Somali men and women, identifying a significant conceptual divergence between the two practices. While MC remains perceived as an essential, harmless, and religiously mandated standard of manhood and hygiene, FC is increasingly acknowledged as harmful, religiously non-compulsory, and open to modification or total abandonment. This transition illustrates how post-migration legal environments, interactions with other Muslim populations, and shifting gender norms reconstruct cultural conceptions of ideal bodily modifications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Anna Wahlberg", "Birgitta Ess\u00e9n", "Sara Johnsdotter", "Zahra Abdi Mohamed", "Asha Omar Geesdiir"], "organizations": ["Uppsala University", "Malm\u00f6 University", "Taylor & Francis Group", "World Health Organization", "UNICEF"], "themes": ["Female Circumcision", "Male Circumcision", "Migration and Integration", "Somali Diaspora", "Islam and Religion", "Gender and Body Modification", "Sexual and Reproductive Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('589679f56daa2aa843980bcae46f2470ac479045701d36bbc2b4bbd700a2058b', 'Wahlberg Shifting_perceptions FGC Sweden PLoSOne 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/589679f56daa2aa843980bcae46f2470ac479045701d36bbc2b4bbd700a2058b.pdf', 'medical_journal', 'ingested', '{"date": "2019-12-04", "description": "This cross-sectional study investigates attitudes toward female genital cutting (FGC) among 648 Somali immigrants living in Sweden, examining how personal beliefs correlate with perceptions of broader community norms. The researchers found substantial agreement between an individual''s personal stance on FGC and their perception of what other Swedish Somalis approve of, although participants frequently overestimated the level of support for FGC among their peers, particularly among women. Furthermore, participants who supported tissue removal on a hypothetical daughter estimated a significantly higher community-wide prevalence of the practice compared to those who opposed it.\n\nThe findings also demonstrate a clear shift away from the traditional convention linking FGC to marriageability, with over 90% of surveyed men expressing a preference to marry women who are uncircumcised or have undergone only pricking\u2014a preference accurately recognized by the majority of surveyed women. The authors conclude that an individual''s motivation to abandon or continue FGC is closely tied to perceived group norms, warning that inaccurate external portrayals, such as media coverage suggesting the practice remains widespread among diaspora populations, could inadvertently hinder abandonment efforts by skewing community members'' perceptions of peer expectations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Anna Wahlberg", "Sara Johnsdotter", "Katarina Ekholm Selling", "Birgitta Ess\u00e9n", "Kabengele Mpinga Emmanuel Mpinga EK", "Gerry Mackie"], "organizations": ["Uppsala University", "Malm\u00f6 University", "PLOS ONE", "Swedish Research Council for Health, Working Life and Welfare", "Swedish Research Council", "County Administrative Board Uppsala", "Sven Jerring Foundation", "Regional Ethical Review Board of Uppsala", "UNICEF"], "themes": ["Female Genital Cutting (FGC)", "Social Norms Theory", "Migration and Acculturation", "Somali Diaspora", "Marriageability Conventions", "Behavior and Attitude Change"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('80c11651b032af20a4e63a284023722ceddff605234057a315d25f043777952f', 'Wahyudi Circapproved JPedSurg 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/80c11651b032af20a4e63a284023722ceddff605234057a315d25f043777952f.pdf', 'medical_journal', 'ingested', '{"date": "2025-04-27", "description": "This academic paper presents the development and evaluation of ''Circapproved'', a mobile application feature integrated into the ASHOKA app designed to evaluate penile anatomy for circumcision eligibility using artificial neural networks (ANN). By analyzing dorsal, lateral, and ventral digital images of the penis captured via smartphone, the AI models achieved diagnostic accuracies of 88.89% (dorsal using DenseNet121), 90.91% (lateral using VGG16), and 92.5% (ventral using MobileNet) in differentiating normal anatomy from congenital malformations like hypospadias and chordee.\n\nHosted on Google Cloud services to facilitate scalability, the system aims to streamline the pre-circumcision screening process and identify surgical contraindications, particularly in resource-limited and telemedicine environments. The authors emphasize that while the tool shows high diagnostic potential when supported by transfer learning and image augmentation, it is meant to assist initial screening rather than replace comprehensive physical examinations by medical professionals.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Irfan Wahyudi", "Chandra Prasetyo Utomo", "Samsuridjal Djauzi", "Muhamad Fathurahman", "Gerhard Reinaldi Situmorang", "Arry Rodjani", "Putu Angga Risky Raharja", "Kevin Yonathan", "Budi Santoso", "Dwidian Khresna", "Muhammad Wildan Pratama", "Nashuha Insani", "Marco Raditya"], "organizations": ["Universitas Indonesia", "Cipto Mangunkusumo Hospital", "YARSI University", "Elsevier Inc."], "themes": ["Artificial Intelligence in Healthcare", "Pediatric Urology", "Mobile Health (mHealth)", "Circumcision Eligibility Screening", "Digital Pattern Recognition", "Transfer Learning and Convolutional Neural Networks"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7d1d781d8e26bd664321f54275aaaee11abe5257da9ae4e9ffeb1dad7dd723ae', 'Wald Circumcision Springer 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7d1d781d8e26bd664321f54275aaaee11abe5257da9ae4e9ffeb1dad7dd723ae.pdf', 'other', 'ingested', '{"date": "2012-12", "description": "In this essay, Nobel Prize-winning biologist George Wald examines the practice of male circumcision from anthropological, religious, and medical perspectives. Prompted by an encounter with an anti-circumcision activist, Wald explores how ancient cultures, such as the Dogon of West Africa, utilized genital modification as puberty initiation rites to excise perceived bisexual traits and delineate sex roles. Analyzing Jewish tradition, Wald argues that the displacement of the rite to early infancy was rooted in patriarchal religious consecration rather than medical prophylaxis, noting that biblical and historical perspectives viewed it as a perilous sacrifice rather than hygiene.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["George Wald", "Van Lewis", "George C. Denniston", "Frederick M. Hodges", "Marilyn Fayre Milos", "Moses Maimonides", "Sigmund Freud", "Bruno Bettelheim", "E. Noel Preston", "W.K.C. Morgan"], "organizations": ["Harvard University", "Florida State University", "Georgetown University", "National Cancer Institute", "Network for Church Monitoring", "NYC Intactivists"], "themes": ["Circumcision", "Genital Autonomy and Integrity", "Medical Prophylaxis vs. Routine Surgery", "Jewish Tradition and Religious Rituals", "Anthropology and Initiation Rites", "Infant Pain and Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('22f96b4eca5108a586718856a0d4d08123232da2b6758481face9b1afe123e21', 'Waldeck Why parents circumcise AmJBio 2003.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/22f96b4eca5108a586718856a0d4d08123232da2b6758481face9b1afe123e21.pdf', 'medical_journal', 'ingested', '{"date": "2003", "description": "This commentary examines how prevailing social norms, rather than objective medical considerations, predominantly drive parental decisions to circumcise male infants in the United States. Author Sarah E. Waldeck argues that the desire to conform to peer standards and avoid social stigma distorts how parents process medical information and leads them to discount infant pain through cultural lenses of masculinity, presenting a persistent collective-action problem.\n\nTo shift these established norms and encourage more balanced decision-making, Waldeck proposes three incremental policy solutions: eliminating Medicaid and private health insurance coverage for routine neonatal circumcision, establishing civil fines for practitioners who perform the procedure without adequate anesthesia, and conducting comprehensive public-information campaigns targeting prospective parents before conception.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Sarah E. Waldeck", "Michael Benatar", "David Benatar"], "organizations": ["Seton Hall University School of Law", "American Academy of Pediatrics", "Medicaid"], "themes": ["Social Norm Theory", "Male Circumcision", "Parental Decision-Making", "Gender Norms and Masculinity", "Informed Consent", "Healthcare Policy and Insurance"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2fa24b5210b0afe82064fd12b8b9bced4d5f616773a401f34cefbc4e9971f65f', 'Wallace1 Need for Change Penis Types ClinAnat 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2fa24b5210b0afe82064fd12b8b9bced4d5f616773a401f34cefbc4e9971f65f.pdf', 'letter', 'ingested', '{"date": "2015-04-16", "description": "This letter to the editor advocates for a revision in anatomical and medical terminology regarding male penis types. The author argues that using the term ''uncircumcised'' to describe a natural, unaltered penis is pejorative, outdated, and incorrectly frames circumcision as the default human condition. Instead, the author proposes that the natural state should universally be referred to as ''intact.''\n\nFurthermore, the author suggests repurposing the word ''uncircumcised'' to refer specifically to men who have undergone surgical or non-surgical foreskin restoration. Under this revised tripartite nomenclature, three distinct forms would be recognized scientifically: ''intact'' (natural prepuce present), ''circumcised'' (prepuce removed), and ''uncircumcised'' (restored prepuce or pseudo-prepuce).", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["William G. Wallace"], "organizations": ["College of Staten Island", "City University of New York", "World Health Organization"], "themes": ["Medical Terminology", "Circumcision", "Anatomy", "Foreskin Restoration", "Language and Lexicon Reform"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9fb77e5dc11f0d6548aebada6d18f6202b0f6a0b46e762a94c853e7921331967', 'Wallace2 (resp BY Hill) Altered Anatomy ClinAnat 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9fb77e5dc11f0d6548aebada6d18f6202b0f6a0b46e762a94c853e7921331967.pdf', 'letter', 'ingested', '{"date": "2015-07-21", "description": "In this Letter to the Editor published in Clinical Anatomy, Robert V. Hill responds to a proposal by Dr. William G. Wallace regarding the classification and terminology of human penis types. While agreeing with Wallace that the term ''uncircumcised'' should not be used to describe the natural, unaltered penis\u2014advocating instead for ''intact''\u2014Hill argues that ''uncircumcised'' is equally inappropriate for describing a prepuce that has undergone foreskin restoration. He explains that restoration does not revert the penis to an unaltered state but produces an anatomy that is histologically and historically distinct through a demanding and arduous process.\n\nHill cautions against conflating terminology in both male and female genital surgeries and calls on anatomists and medical educators to correct deficiencies in modern textbooks. He proposes that standard anatomical authority recognize three precise penile states: intact, circumcised, and restored, thereby ensuring greater clinical precision, historical accuracy, and respect for patient experiences.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Robert V. Hill", "William G. Wallace"], "organizations": ["NYIT College of Osteopathic Medicine", "World Health Organization", "Wiley Periodicals, Inc."], "themes": ["Penile Anatomy and Terminology", "Foreskin Restoration", "Male Circumcision", "Medical Ethics and Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0a644ac3c05240f3395383154a9215247c20e6c67ded1e3c80740b8ef4e1c7cb', 'Wallace3 (resp TO Hill) Undeniable Need ClinAnat 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0a644ac3c05240f3395383154a9215247c20e6c67ded1e3c80740b8ef4e1c7cb.pdf', 'medical_journal', 'ingested', '{"date": "2015-08-09", "description": "This letter to the editor addresses anatomical terminology regarding the human penis, specifically responding to R.V. Hill''s critique of the author''s previous proposal. The author agrees with adopting the classification ''Intact'' for naturally unaltered anatomy and concedes that ''Restored'' is superior to ''Uncircumcised'' for men who have reconstructed or regrown a foreskin. Furthermore, the author calls on the medical community to formally recognize foreskin restoration, validate the emotional and physical experiences of circumcised men seeking wholeness, invest in dedicated clinical research, and extend societal compassion to these men by acknowledging their efforts as ''BRAVE.''", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["William G. Wallace", "R.V. Hill"], "organizations": ["College of Staten Island/CUNY", "National Organization of Restoring Men (NORM)", "Wiley Periodicals, Inc."], "themes": ["Anatomical Terminology", "Foreskin Restoration", "Circumcision", "Men''s Health and Psychology", "Medical Research and Validation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('405db7daaa3976bcb1561e0c61964e2342442e1cefce4ebf9a604082ce518477', 'Wallerstein Uniquely American UrolClinNA 1985.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/405db7daaa3976bcb1561e0c61964e2342442e1cefce4ebf9a604082ce518477.pdf', 'medical_journal', 'ingested', '{"date": "1985", "description": "Edward Wallerstein examines the persistence of routine neonatal nonreligious circumcision in the United States, characterizing it as a unique medical anomaly among developed nations. While circumcision rates have sharply declined or remain virtually nonexistent in most of the world\u2014including Great Britain, Canada, and Australia\u2014the U.S. continues to perform approximately 1.25 million neonatal circumcisions annually. Wallerstein traces the origins of medical circumcision to 19th-century Victorian misconceptions regarding masturbation and unscientific health claims popularized by figures like Dr. P.C. Remondino.\n\nThe article systematically dismantles contemporary justifications for the surgery, addressing issues of neonatal pain, sexually transmitted disease transmission, penile cancer, and genital hygiene. Wallerstein demonstrates that prophylactic claims regarding cancer and venereal diseases are scientifically groundless, while parental and medical anxieties surrounding penile hygiene stem from widespread ignorance regarding normal foreskin development. He concludes that routine infant circumcision constitutes unnecessary cultural surgery rather than evidence-based medicine, urging professional bodies such as the American Academy of Pediatrics and the American College of Obstetricians and Gynecologists to adopt decisive, unequivocal stances against the procedure.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Edward Wallerstein", "P.C. Remondino", "Douglas Gairdner", "Robert P. Bolande", "H.C. Thompson"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Canadian Paediatric Society", "Australian Paediatric Association", "Commission on Professional and Hospital Activities"], "themes": ["Routine Neonatal Circumcision", "Pediatric Urology and Surgery", "Medical Misconceptions and History", "Penile Hygiene and Foreskin Care", "Cancer Prophylaxis Debunking"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b98b0861e687a4c39ff30a7dec993d9583c321f3ec0b0839664823df816b7760', 'Walton Neo circ after delisting ON CanFamPhys 1997.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b98b0861e687a4c39ff30a7dec993d9583c321f3ec0b0839664823df816b7760.pdf', 'medical_journal', 'ingested', '{"date": "1997", "description": "This cross-sectional survey evaluated the prevalence of neonatal male circumcision and parental decision-making factors immediately following the April 1994 delisting of routine circumcision from Ontario''s provincial health insurance. Conducted at a tertiary perinatal care centre in southwestern Ontario, the study found that the procedure''s prevalence did not significantly decrease post-delisting (59.8% compared to 56.2% pre-delisting), showing that newly introduced out-of-pocket hospital costs did not deter most families.\n\nThe findings identified the father''s circumcision status as the strongest predictor of whether a newborn was circumcised, with parents primarily citing perceived medical benefits and sociocultural considerations (such as familial conformity). In contrast, higher maternal education was associated with opting against the procedure. The study highlighted substantial gaps in informed consent, noting that many parents were unaware of risks or whether pain relief was administered, and recommended that physicians actively address sociocultural factors and pain management options during prenatal consultations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ruth E. Walton", "Truls Ostbye", "M. Karen Campbell"], "organizations": ["University of Western Ontario", "Canadian Paediatric Society"], "themes": ["Neonatal Circumcision", "Healthcare Delisting and Policy", "Informed Consent", "Parental Decision-Making", "Pediatric Pain Management and Anesthesia", "Sociocultural Influences on Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8910bd4ed39c35dc2eee43527265788e33325816af7da58f624155e96182894e', 'Wamai Halpern Is_male_circ_as_good_as_vaccine Future HIV Ther 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8910bd4ed39c35dc2eee43527265788e33325816af7da58f624155e96182894e.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This article examines the evidence supporting voluntary medical male circumcision (MC) as an extraordinarily effective intervention against heterosexual HIV transmission in men, reducing transmission risk by 60% or higher. Presenting data from randomized controlled trials stopped early due to overwhelming efficacy, the authors argue that MC functions effectively as the equivalent of a long-awaited HIV vaccine, offering lifelong protection, additional health benefits against HPV and other STIs, and substantial herd immunity effects that could save millions of lives across sub-Saharan Africa.\n\nDespite clear scientific consensus and endorsement from WHO and UNAIDS, the authors criticize the sluggish global implementation, attributing the lack of mobilization and funding in part to the absence of pharmaceutical corporate profits. They call for immediate accountability, expanded media coverage, institutional restructuring such as a dedicated MC desk at UNAIDS, and rapid resource mobilization to provide safe, equitable, and widespread access to circumcision services in high-prevalence African nations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jeffrey D Klausner", "Richard G Wamai", "Kasonde Bowa", "Kawango Agot", "Jesse Kagimba", "Daniel T Halperin"], "organizations": ["Harvard University School of Public Health", "University of California, San Francisco", "National Institutes of Health", "World Health Organization", "UNAIDS", "University Teaching Hospital, Lusaka", "M\u00e9decins Sans Fronti\u00e8res", "Treatment Action Campaign"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Global Health Policy", "Sub-Saharan Africa Epidemic", "Public Health Equity and Access", "Clinical Trials"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5a5ab660e028abafc45f22fc7b3299701077dda8ff8799f8f410329c3d95d906', 'Wang Anxiety after VMMC JMedInternetRes 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5a5ab660e028abafc45f22fc7b3299701077dda8ff8799f8f410329c3d95d906.pdf', 'medical_journal', 'ingested', '{"date": "2025-11-17", "description": "This multicenter, double-blind, randomized controlled trial evaluated the efficacy of a narrative-enhanced tool (NET) and an artificial intelligence-assisted consultation (AAC) chatbot in improving postoperative recovery and care efficiency following voluntary medical male circumcision (VMMC). Enrolling 388 patients who completed a 30-day follow-up, the study compared participants receiving video-based narrative communications with those receiving standardized risk tools (SRT).\n\nThe findings demonstrated that patients in the NET group experienced significantly lower anxiety scores, improved sleep quality, higher quality-of-life scores, and significantly reduced opioid consumption alongside more regular analgesic compliance. Furthermore, the implementation of the generative AI chatbot streamlined follow-up consultations, cutting staff follow-up time by approximately 70% without compromising patient satisfaction, highlighting the value of combining narrative empathy with AI tools in postsurgical telemedicine.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Linfeng Wang", "Yueqiang Peng", "Gaojie Zhang", "Yong Huang", "Jiayu Liu", "Wei Tang"], "organizations": ["First Affiliated Hospital of Chongqing Medical University", "Peking Union Medical College Hospital", "First Hospital of Jilin University", "Yongchuan Hospital of Chongqing Medical University", "Chongqing Cancer Hospital", "Journal of Medical Internet Research"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "Artificial Intelligence in Healthcare", "Postoperative Anxiety", "Narrative Health Communication", "Pain Management and Opioid Use", "Telemedicine and Mobile Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('650df427fa9ec6f6d01ecf8a2d883d8a06ae7e0de8254bfcf872133e8ea23160', 'Warner Impact Health Insurance AJPH 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/650df427fa9ec6f6d01ecf8a2d883d8a06ae7e0de8254bfcf872133e8ea23160.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This study analyzes hospital discharge data from the 2000\u20132010 Nationwide Inpatient Sample to investigate the factors contributing to the decline in newborn male circumcision across the United States. While overall circumcision rates fell significantly from 61.3% in 2000 to 56.9% in 2010, the decrease was largely concentrated in the South and among births covered by Medicaid, disappearing entirely in statistical models adjusted for insurance type.\n\nThe authors conclude that the nationwide decline was primarily driven by a growing proportion of hospital births covered by Medicaid combined with policy decisions in numerous states to eliminate Medicaid reimbursement for routine neonatal circumcision. Because recent pediatric and public health guidelines acknowledge the preventive health benefits of male circumcision, the authors argue that reimbursement policies and financial barriers restricting access for Medicaid-reliant families warrant reevaluation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lee Warner", "Shanna Cox", "Maura Whiteman", "Denise J. Jamieson", "Maurizio Macaluso", "Pooja Bansil", "Elena Kuklina", "Athena P. Kourtis", "Samuel Posner", "Wanda D. Barfield"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Agency for Healthcare Research and Quality", "Healthcare Cost and Utilization Project"], "themes": ["Newborn Circumcision", "Medicaid Coverage", "Health Insurance Disparities", "Health Policy", "Preventive Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('34e3c822457ecaba1ab9b9f5696f1baf7116d8fae36eb2cdb06a9241456d7c14', 'WAS Declaration Sexual Justice 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/34e3c822457ecaba1ab9b9f5696f1baf7116d8fae36eb2cdb06a9241456d7c14.pdf', 'policy_guideline', 'ingested', '{"date": "2023-11-05", "description": "The WAS Declaration on Sexual Justice, proclaimed by the World Association for Sexual Health, defines sexual justice as an essential dimension of social justice and human rights. It argues that achieving sexual health and equality requires addressing structural discrimination, power imbalances, and social determinants that marginalize underprivileged populations. Furthermore, it emphasizes that sexual justice is inextricably linked with environmental, racial, gender, and economic justice, demanding systemic accountability and legal reforms from both state and non-state actors.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["World Association for Sexual Health"], "themes": ["Sexual Justice", "Sexual Health and Rights", "Social Justice", "Human Rights", "Non-discrimination", "Structural Inequality", "Comprehensive Sexuality Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('896e74aac235b84698ef2dc366ab263f265b17bf727bfe82ba60d3272faa1c6a', 'WAS Declaration Sexual Pleasure 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/896e74aac235b84698ef2dc366ab263f265b17bf727bfe82ba60d3272faa1c6a.pdf', 'policy_guideline', 'ingested', '{"date": "2021", "description": "The Declaration on Sexual Pleasure, issued by the World Association for Sexual Health (WAS), affirms that sexual pleasure is an essential component of sexual health, subjective well-being, and human rights. It defines sexual pleasure as the physical and psychological satisfaction derived from shared or solitary erotic experiences, emphasizing that it must be exercised within a framework of consent, bodily autonomy, safety, equality, and freedom from discrimination or coercion.\n\nThe declaration urges governments, international bodies, healthcare authorities, and educational institutions to formally integrate sexual pleasure into legal policy, comprehensive sexuality education, public health services, and scientific research. By calling for rights-based approaches to human sexuality, WAS highlights that recognizing and supporting diverse, safe experiences of sexual pleasure contributes directly to individual well-being and global sustainable development.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["World Association for Sexual Health", "Global Advisory Board for Sexual Health and Wellbeing"], "themes": ["Sexual Pleasure", "Sexual Rights and Human Rights", "Sexual Health and Well-being", "Comprehensive Sexuality Education", "Bodily Integrity and Consent", "Global Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d9982370492c24d44dcdd600132fe7924524b9cc826645fa20f1070c79852719', 'WAS Declaration Sexual Rights 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d9982370492c24d44dcdd600132fe7924524b9cc826645fa20f1070c79852719.pdf', 'policy_guideline', 'ingested', '{"date": "2015", "description": "This document outlines the World Association for Sexual Health''s (WAS) Declaration of Sexual Rights, affirming that sexual rights are fundamental human rights pertaining to sexuality. It details sixteen comprehensive rights, including equality and non-discrimination, autonomy and bodily integrity, freedom from violence and torture, privacy, the right to the highest attainable standard of sexual health, and the right to comprehensive sexuality education and reproductive choice.\n\nOriginally proclaimed in 1997 and revised through subsequent assemblies up to its ratification in Singapore in 2015, the Declaration emphasizes that fulfilling sexual rights is crucial to human well-being, personal dignity, and public health. It advocates for access to justice, scientifically accurate information, peaceful assembly, and non-discriminatory participation in civic life concerning sexual expression and health.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["World Association for Sexual Health"], "themes": ["Sexual Rights", "Human Rights", "Bodily Autonomy and Integrity", "Sexual and Reproductive Health", "Equality and Non-discrimination", "Comprehensive Sexuality Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5cb69e28f30cd9fd58f17fcc3093a5789e164fa129ab5a79989691ed0dda1895', 'WAS Porto Proclam Sexual Health, Rights and Justice 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5cb69e28f30cd9fd58f17fcc3093a5789e164fa129ab5a79989691ed0dda1895.pdf', 'policy_guideline', 'ingested', '{"date": "2025-09-05", "description": "Adopted at the Inaugural World Sexual Health Assembly in Porto, Portugal, the Porto Proclamation establishes that sexual health, rights, and justice are fundamental to human dignity, human rights, and global development. In the face of political crises, conflict, funding cuts, and systemic inequalities, the proclamation lays out core guiding principles centered on equity, evidence-based practices, accountability, comprehensive sexuality education, person-centered services, and the affirmation of sexual pleasure as an essential element of well-being.\n\nThe document articulates seven strategic priorities to guide international collective action. These priorities include advancing legal and policy reform, ensuring universal access to high-quality healthcare and education, combating censorship and misinformation, establishing digital advocacy strategies, integrating with broader democracy and justice movements, and securing sustainable and equitable funding.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": ["Daniel Reijer", "Tham Hui Ying", "Julia Ehrt", "Manuelle Hurwitz", "Alex Garner", "Eusebio Rubio-Aurioles", "Marieke van der Plas", "Wendy Anderson", "Cristina Ljungberg", "Anne Philpott", "Sally MacPhedran", "Faysal El Kak", "Asa Radix", "Christopher Fox", "Esben Esther Pirelli Benestad", "Bouchra Assarag", "Esther Corona", "Eli Coleman", "Elna Rudolph", "Jacqueline Hendriks", "Kristen Mark", "Erick Janssen", "Pedro Nobre", "Eszter Kism\u0151di", "Philip Anglewicz", "Jesse Ford"], "organizations": ["World Sexual Health Assembly", "Aids Healthcare Foundation", "ARROW", "ILGA World", "International Planned Parenthood Federation", "MPact", "Mexican Association for Sexual Health", "Rutgers", "The Case for Her", "The Pleasure Project", "International Society for the Study of Women\u2019s Sexual Health", "World Association for Sexual Health", "World Professional Association for Transgender Health", "Asia-Oceania Federation of Sexology", "European Federation of Sexology", "Eastern Mediterranean Federation of Sexual Health", "Latin American Federation of Sexology and Sexuality Education Societies", "North American Federation of Sexology Organizations", "Sexual Health Africa", "African Institute for Sexual and Gender Health", "Curtin University", "Eli Coleman Institute For Sexual and Gender Health", "University of Leuven", "University of Porto"], "themes": ["Sexual Health and Rights", "Sexual Justice", "Human Rights", "Comprehensive Sexuality Education", "Equity and Inclusion", "Accountability and Legal Reform", "Misinformation and Digital Advocacy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('902cfb685e9045b7fb3c4a065ca3fe20cdbc038bd36d86ad0830068eeb31345c', 'Watson-Golden Circ Grief NewMaleStud 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/902cfb685e9045b7fb3c4a065ca3fe20cdbc038bd36d86ad0830068eeb31345c.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This article investigates the psychological phenomenon of male circumcision grief (CG) and assesses the experiences of 22 men who sought psychotherapeutic help for distress related to infant circumcision. The authors find that therapists frequently dismiss, pathologize, or minimize this grief through humor, erroneous anatomical beliefs, and misdiagnoses such as OCD or body dysmorphic disorder, with male practitioners exhibiting more resistance and less empathy than female practitioners.\n\nThe authors conclude that circumcision grief constitutes an authentic form of body-loss grief rather than delusion or mere aesthetic dissatisfaction. They advocate for more effective therapeutic strategies, including validating patients'' trauma, recognizing the physiological and sensory functions of the foreskin, and utilizing action-oriented, masculine healing modes such as non-surgical foreskin restoration and peer support groups.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Lindsay Watson", "Tom Golden"], "organizations": ["Australian Institute of Male Health and Studies", "National Organization of Restoring Men"], "themes": ["Male Circumcision", "Circumcision Grief", "Body Loss and Trauma", "Psychotherapy and Counseling", "Men''s Mental Health", "Foreskin Restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4c5e6c99986eb92569c593fe232e33982a32a4e53cdfa1e56c8a55deb206ec3c', 'Wawer Circ in HIV men Lancet 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4c5e6c99986eb92569c593fe232e33982a32a4e53cdfa1e56c8a55deb206ec3c.pdf', 'medical_journal', 'ingested', '{"date": "2009-07-18", "description": "This randomized controlled trial evaluated whether male circumcision (MC) in HIV-infected men reduces HIV transmission to their HIV-uninfected female sexual partners in Rakai, Uganda. Enrolled asymptomatic HIV-positive men with CD4 counts of 350 or higher were assigned to either immediate circumcision or circumcision delayed by 24 months, and their female partners were tracked over time. The trial was halted early for futility after finding that male circumcision did not reduce HIV transmission to female partners over 24 months (cumulative probability of 21.7% in the intervention group versus 13.4% in the control group).\n\nNotably, post-hoc analyses showed an elevated risk of HIV acquisition among women whose male partners resumed sexual intercourse early\u2014at least five days before certified complete surgical wound healing (27.8% transmission vs. 7.9% in the control arm). Additionally, a modest increase in viral load was observed in antiretroviral-na\u00efve men at four weeks post-surgery. The researchers conclude that male circumcision in HIV-positive men does not protect female partners and emphasize the critical need for post-surgical sexual abstinence until full wound healing is certified, alongside consistent condom use.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Maria J. Wawer", "Frederick Makumbi", "Godfrey Kigozi", "David Serwadda", "Stephen Watya", "Fred Nalugoda", "Dennis Buwembo", "Victor Ssempijja", "Noah Kiwanuka", "Lawrence H. Moulton", "Nelson K. Sewankambo", "Steven J Reynolds", "Thomas C Quinn", "Pius Opendi", "Boaz Iga", "Renee Ridzon", "Oliver Laeyendecker", "Ronald H Gray", "Edward Mbidde"], "organizations": ["Johns Hopkins University", "Rakai Health Sciences Program", "Makerere University", "Mulago Hospital", "National Institute of Allergy and Infectious Diseases", "National Institutes of Health", "The Bill & Melinda Gates Foundation", "Uganda Virus Research Institute", "Uganda National Council for Science and Technology", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "HIV Transmission", "Heterosexual Transmission", "Surgical Wound Healing", "HIV-Discordant Couples", "Sexually Transmitted Infections"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('051578ab138497e1674e434254ad5311b807cbe4a214d5a396e2e7cd30ad52c8', 'Wee Willy Pamphlet BoysHealth Advisory.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/051578ab138497e1674e434254ad5311b807cbe4a214d5a396e2e7cd30ad52c8.pdf', 'other', 'ingested', '{"date": null, "description": "This educational guide provides parents with practical instructions and medical advice for caring for an uncircumcised male child. It emphasizes that non-retractability in early childhood is completely normal and warns against the dangers of forced foreskin retraction by caregivers or healthcare providers, which can result in pain, bleeding, and scarring. The guide encourages allowing natural separation over time and teaching proper personal hygiene as the child grows.\n\nIn addition, the guide covers routine care topics such as diaper changing, bathing without irritating soaps, and managing common issues like minor infections or urination ballooning. It advises parents to seek second opinions if a physician recommends circumcision, noting that less invasive treatments such as topical steroid creams or gentle stretching can often resolve penile complications without surgery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["Boy''s Health Advisory", "Circumcision Decision-Maker"], "themes": ["Pediatric Health", "Genital Hygiene", "Foreskin Care", "Circumcision Alternatives", "Childhood Development"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f49c43eacb88f2dd8efdbe6e4cae1c45a07256c9d38e82e81c1e786c4c423182', 'Wei Impact Adult Circ HIV MSM in SanFran SexTransDis 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f49c43eacb88f2dd8efdbe6e4cae1c45a07256c9d38e82e81c1e786c4c423182.pdf', 'medical_journal', 'ingested', '{"date": "2011-04", "description": "This study evaluates the potential public health impact of adult male circumcision as an HIV prevention strategy among men who have sex with men (MSM) in San Francisco, using data from the 2008 National HIV Behavioral Surveillance (NHBS) survey. Because circumcision primarily offers protection to insertive partners during anal intercourse, its effectiveness at the population level relies heavily on baseline circumcision prevalence, sexual role segregation, and willingness to undergo the procedure.\n\nThe findings indicate that circumcision would have very limited public health benefit among MSM in San Francisco. A large majority of HIV-negative MSM in the sample were already circumcised (80.5%), and among the small subset of uncircumcised, HIV-negative men who predominantly engaged in unprotected insertive anal intercourse, fewer than 1% expressed willingness to participate in circumcision clinical trials or undergo the procedure if proven effective.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Chongyi Wei", "H. Fisher Raymond", "Willi McFarland", "Susan Buchbinder", "Jonathan D. Fuchs"], "organizations": ["University of Pittsburgh", "San Francisco Department of Public Health", "University of California, San Francisco", "Centers for Disease Control and Prevention", "National Institutes of Allergy and Infectious Diseases", "American Sexually Transmitted Diseases Association"], "themes": ["HIV/AIDS Prevention", "Male Circumcision", "Men Who Have Sex With Men (MSM)", "Epidemiology and Public Health", "Sexual Risk Behavior"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ea88d88f3b729f1f7ab52e0e63716429e65659bb781c10006194be170c6d31d6', 'Weisenberg Why Inf Circ Unethical Rutgers J Bioethics 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ea88d88f3b729f1f7ab52e0e63716429e65659bb781c10006194be170c6d31d6.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This publication from the Rutgers Journal of Bioethics (Spring 2023) presents editorial commentary alongside a featured academic article by Desmond Weisenberg titled ''Why Non-Therapeutic Infant Circumcision Is Unethical.'' Weisenberg argues that elective infant male circumcision is an inherently harmful practice that excises functional, highly sensitive penile tissue and violates a child''s future autonomy and right to bodily integrity without adequate medical justification. \n\nThe paper critiques common defenses of the procedure, demonstrating that probabilistic health benefits are insufficient to meet pediatric bioethical standards and that parental proxy consent cannot legitimately justify permanent non-therapeutic genital alteration. Drawing comparisons to international consensus and legal prohibitions against female genital mutilation (FGM), the author invokes the bioethical principle of justice to argue for equal bodily protection across sexes, ultimately concluding that non-therapeutic infant circumcision is unethical and should be legally prohibited.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Desmond Weisenberg", "Nikhil Ramavenkat", "Maxim Yacun", "Brian D. Earp", "Andrew L. Freedman", "Mark Aulisio"], "organizations": ["Rutgers University", "Bioethics Society of Rutgers University", "American Academy of Pediatrics", "World Health Organization", "Canadian Urological Association", "Royal Dutch Medical Association"], "themes": ["Bioethics", "Infant Circumcision", "Bodily Autonomy and Consent", "Pediatric Ethics", "Parental Decision-Making", "Female Genital Mutilation (FGM) Comparisons"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1e96a7adb14ba293932a2f4eda9da084ddc2fc0943155628fe6f0b06ad64d328', 'Weiss Halperin Bailey Circumcision_for_HIV_prev AIDS 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1e96a7adb14ba293932a2f4eda9da084ddc2fc0943155628fe6f0b06ad64d328.pdf', 'medical_journal', 'ingested', '{"date": "2008", "description": "This editorial review examines the epidemiological and biological evidence demonstrating that male circumcision reduces the risk of heterosexual HIV acquisition in men by approximately 60%, based on findings from three randomized controlled trials conducted in Uganda, Kenya, and South Africa. It evaluates global circumcision prevalence, biological susceptibility factors such as the mucosal properties of the inner foreskin, and potential indirect benefits including reduced incidence of genital ulcer disease. The authors also discuss public health translation challenges, noting that mathematical modeling predicts significant population-level impact and cost-effectiveness in high-HIV prevalence regions of sub-Saharan Africa.\n\nKey policy and clinical considerations highlighted include the necessity of surgical safety, addressing potential risk compensation through comprehensive counselling, and managing cultural acceptability. The review notes that while male circumcision directly protects men, indirect benefits accrue to women, though definitive direct protection in male-to-female or male-to-male transmission remains unproven. The authors conclude that voluntary adult and neonatal male circumcision programs should be prioritized and embedded within comprehensive HIV prevention frameworks endorsed by WHO and UNAIDS.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Helen A. Weiss", "Daniel Halperin", "Robert C. Bailey", "Richard J. Hayes", "George Schmid", "Catherine A. Hankins"], "organizations": ["London School of Hygiene and Tropical Medicine", "Harvard School of Public Health", "University of Illinois at Chicago", "World Health Organization", "Joint United Nations Programme on HIV/AIDS", "PEPFAR", "Agence Nationale de Recherche sur la SIDA", "Bill and Melinda Gates Foundation", "National Institutes of Health"], "themes": ["HIV Prevention", "Male Circumcision", "Randomized Controlled Trials", "Public Health Policy", "Cost-Effectiveness", "Epidemiology in Sub-Saharan Africa"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('2f9a5e18ac31d82d7ebffedd434216943273aad58a75883dd49d95830e32a728', 'Weiss Hankins Male_circ and HIV_in Women Lancet 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/2f9a5e18ac31d82d7ebffedd434216943273aad58a75883dd49d95830e32a728.pdf', 'medical_journal', 'ingested', '{"date": "2009", "description": "This systematic review and meta-analysis examines the epidemiological evidence regarding whether male circumcision directly reduces the risk of HIV transmission to female partners. Evaluating 19 epidemiological analyses across 11 study populations, the authors find little evidence of a direct protective effect of male circumcision against male-to-female HIV transmission (summary relative risk 0.80, 95% CI 0.53\u20131.36), and note that definitive randomised trials among serodiscordant couples would require logistically unfeasible sample sizes. Nonetheless, ecological and population-level data indicate clear indirect benefits to women through reduced HIV exposure as prevalence among circumcised men declines.\n\nThe review emphasizes the necessity of integrating male circumcision scale-up with established HIV prevention measures, such as condom distribution, testing, and counseling. Additionally, the authors caution that men resuming sexual intercourse prior to complete wound healing may carry a temporarily increased risk of transmitting HIV to uninfected female partners, underscoring the critical need for careful post-surgical counseling and rigorous monitoring.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Helen A Weiss", "Catherine A Hankins", "Kim Dickson", "Natasha Larke", "Ronald H Gray", "Jai Lingappa"], "organizations": ["London School of Hygiene and Tropical Medicine", "United Nations Joint Programme on HIV/AIDS", "World Health Organization"], "themes": ["HIV Prevention", "Male Circumcision", "Heterosexual Transmission", "Meta-Analysis", "Women''s Health", "Sub-Saharan Africa Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0b8caf204f6c4ceb7d8f9f3fdbe7b01a3c4a8fe77886703ac36ddba5a45df150', 'Weiss_ComplicationsOfCircumcision BMCUrol 2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0b8caf204f6c4ceb7d8f9f3fdbe7b01a3c4a8fe77886703ac36ddba5a45df150.pdf', 'medical_journal', 'ingested', '{"date": "2010-02-16", "description": "This systematic review analyzes the frequency and severity of adverse events following neonatal, infant, and child male circumcision across 52 studies from 21 countries. The findings demonstrate that serious adverse events are rare, particularly among neonates and infants, who had a median complication rate of 1.5% with most issues being minor and easily treatable. In contrast, circumcisions performed on older children by medical providers had a higher median complication rate of 6%, while traditional circumcisions conducted as rites of passage in non-sterile settings by untrained providers showed substantially higher frequencies of severe adverse outcomes.\n\nThe authors emphasize that because male circumcision will continue to be widely practiced for religious, cultural, and HIV prevention purposes, effective risk-reduction strategies are critically needed. Recommendations include formal training and regulation for both clinical and traditional providers, standardizing complication definitions, and ensuring access to appropriate sterile surgical equipment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Helen A Weiss", "Natasha Larke", "Daniel Halperin", "Inon Schenker"], "organizations": ["London School of Hygiene & Tropical Medicine", "Harvard School of Public Health", "The Jerusalem AIDS Project", "World Health Organisation", "UNAIDS", "Bill & Melinda Gates Foundation", "Medical Research Council"], "themes": ["Pediatric Male Circumcision", "Post-operative Complications", "HIV/STI Prevention", "Global Health and Surgical Safety", "Medical vs. Traditional Circumcision Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('726f9378d10e6dee3424af8e3de8b64b6be57d313617006fb7183847f2af3b7d', 'Welch Erasing Foreskin JBSM 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/726f9378d10e6dee3424af8e3de8b64b6be57d313617006fb7183847f2af3b7d.pdf', 'medical_journal', 'ingested', '{"date": "2024", "description": "This article critiques non-therapeutic neonatal male circumcision in the United States, arguing that the practice persists due to pervasive cultural myths that mischaracterize the foreskin as unhygienic, aesthetically displeasing, or useless ''excess skin.'' The author contends that this normalization erases awareness of the foreskin''s biological, erogenous, and immunological functions while systematically denying or minimizing infant pain, surgical risks, and long-term psychological and physical complications. Examining evidence commonly cited in favor of circumcision\u2014such as prevention of urinary tract infections, penile cancer, and sexually transmitted infections\u2014the author asserts that these claims are either empirically flawed or ethically insufficient to justify non-consensual genital surgery on children.\n\nFurthermore, the paper highlights how the comedic trivialization and cultural erasure of circumcision enable a lucrative commercial market that harvests and traffics discarded infant foreskin tissue for biomedical research and cosmetic applications. Drawing comparisons to the legal and moral prohibitions against female genital mutilation, the author argues that the medical establishment and society maintain an unjustified double standard that severely undermines male bodily autonomy and integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Shawn Welch", "Brian D. Earp", "Ronald Goldman", "David Reimer", "John Harvey Kellogg", "Tim Hammond", "Robert Darby"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "National Secular Society", "University of Michigan", "NOHARMM"], "themes": ["Male Circumcision", "Bodily Autonomy and Integrity", "Medical Ethics", "Infant Genital Mutilation", "Tissue Harvesting and Commercialization", "Cultural Normalization and Media Representation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ca2c97a8d1a92c14fb57aa18ce861f1dda9e29d4f96b8d03c5c063d09160aa74', 'Werker Prepuce Free Flap PlasReconstrSurg 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ca2c97a8d1a92c14fb57aa18ce861f1dda9e29d4f96b8d03c5c063d09160aa74.pdf', 'medical_journal', 'ingested', '{"date": "1998", "description": "This study explores the feasibility and clinical utility of using a male prepuce free flap as a super-thin tissue option for reconstructive surgery, specifically for defects in the oral cavity and pharynx. Following initial dissection studies on cadavers and viability tests during male-to-female sex reassignment procedures, the prepuce free flap was successfully applied in two clinical reconstructions of the floor of the mouth, tongue, and oropharynx. The flap offers notable advantages such as thinness, pliability, a large surface area (averaging 46.7 cm\u00b2), a long pedicle, and low donor-site morbidity, though the small caliber of the flap artery remains a primary challenge.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Paul M. N. Werker", "Alex S. C. Terng", "Moshe Kon", "Duckett"], "organizations": ["University Hospital of Utrecht", "Utrecht University", "European Federation of Societies for Microsurgery", "Dutch Society for Plastic Surgery"], "themes": ["Reconstructive Surgery", "Prepuce Free Flap", "Microsurgery", "Oral Cavity Reconstruction", "Surgical Anatomy and Feasibility"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6fffdb866e0d5a952e322b51a65fe38597c031449deae0370332216aa413cb5d', 'White Healing_Harms_of_Circumcision Springer 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6fffdb866e0d5a952e322b51a65fe38597c031449deae0370332216aa413cb5d.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This clinical case study documents a long-term nursing intervention with a couple facing marital dissolution due to severe sexual dysfunction and pain caused by an asymmetrical, non-consensual infant circumcision deformity. Guided by Virginia Henderson''s nursing theory of fostering patient independence, the intervention addressed both physical complications\u2014such as dyspareunia, penile curvature, and painful erections\u2014and psychological distress resulting from medical trauma.\n\nOver an extended counseling and treatment period, the husband utilized self-managed skin expansion techniques, including freehand stretching and taping, to selectively lengthen foreskin remnants and correct penile alignment. Accompanied by health screenings that uncovered unrelated underlying medical issues, sexual counseling, and relationship therapy, the treatment successfully alleviated physical pain, restored sexual intimacy, and preserved the marriage.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["B. Maurene White", "Virginia Henderson", "Rita F. Cameron", "G. C. Denniston"], "organizations": ["Springer Science+Business Media", "National Organization of Restoring Men (NORM)", "National Organization of Circumcision Information Resource Centers (NOCIRC)", "Doctors Opposing Circumcision (DOC)", "Montreal General Hospital School of Nursing", "McGill University"], "themes": ["Male Infant Circumcision", "Foreskin Restoration", "Sexual Dysfunction", "Nursing Interventions", "Medical Ethics and Informed Consent", "Tissue Expansion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fe087b00122973cc8d510e91743ae76b6ad8b4038b44acbc126dd02186b9ecc6', 'Williams Kapila_ Complications of Circ BritJSurg 1993.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fe087b00122973cc8d510e91743ae76b6ad8b4038b44acbc126dd02186b9ecc6.pdf', 'medical_journal', 'ingested', '{"date": "1993", "description": "This review examines the indications, surgical techniques, and wide spectrum of complications associated with male circumcision. Although frequently viewed as a minor procedure, circumcision carries a defined morbidity rate, with complications ranging from common issues like hemorrhage, local infection, and unsatisfactory cosmetic outcomes to severe events such as penile denudation, concealed penis, urethrocutaneous fistulae, systemic sepsis, and gangrene. The authors note that while surgical complications are frequently linked to operator inexperience, excessive or inadequate tissue removal, and inappropriate use of diathermy or constrictive dressings, significant psychological sequelae\u2014including castration anxiety and behavioral trauma in children\u2014are also well-documented.\n\nThe paper emphasizes that professional guidelines, including those from the British Medical Association, recommend performing circumcision strictly for clear medical indications rather than routinely. Given the variety of documented risks and potential long-term physiological and psychological impacts, the authors urge greater clinical awareness, proper surgical training to reduce operator-dependent error, and careful consideration before deciding to perform the operation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["N. Williams", "L. Kapila", "Anna Freud"], "organizations": ["British Medical Association", "American Association of Pediatricians", "University Hospital Nottingham"], "themes": ["Circumcision complications", "Surgical morbidity and mortality", "Pediatric surgery guidelines", "Psychological effects of surgery", "Medical indications vs. routine procedures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('66faa2ae08d5807079a8d4f983708e0704bb92a641955407f0bb86c36376ae04', 'Williams Langerhans.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/66faa2ae08d5807079a8d4f983708e0704bb92a641955407f0bb86c36376ae04.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This article examines the biological role and significance of epidermal Langerhans cells (ELCs) in the human prepuce (foreskin). The author outlines the morphology and critical immune-surveillance functions of ELCs, which act as sentinel antigen-presenting cells that initiate adaptive immune responses.\n\nThe author critiques previous studies by Weiss et al. and Hussain & Lehner, arguing that these researchers misconstrued data to advance a pro-circumcision perspective regarding immune vulnerability and HIV transmission. Instead, the author contends that the foreskin is an essential, immunocompetent organ, and that circumcision permanently eliminates tens of thousands of protective ELCs, compromising local immune surveillance.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["George L Williams", "Paul Langerhans", "GN Weiss", "LA Hussain", "T Lehner"], "organizations": ["The New Children\u2019s Hospital"], "themes": ["Epidermal Langerhans Cells", "Male Circumcision", "Immunology and Immune Surveillance", "Preputial Anatomy", "HIV Transmission"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7adbd8b5061e9cf663ba347b99e46215cdf9839d4fc9751eeda453f28d0234d9', 'Winberg Prepuce Mistake of Nature Lancet 1989.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7adbd8b5061e9cf663ba347b99e46215cdf9839d4fc9751eeda453f28d0234d9.pdf', 'medical_journal', 'ingested', '{"date": "1989-03-18", "description": "This article discusses the paradox of retrospective studies showing that neonatal circumcision reduces the risk of early infantile urinary tract infections (UTIs) by approximately 90%. The authors argue that it is evolutionarily and biologically improbable that the prepuce is a ''mistake of nature'' requiring surgical removal. Instead, they propose that circumcision acts as an artificial countermeasure against another unphysiological condition: modern hospital maternity units where infants are colonized by environmental and nosocomial Escherichia coli strains rather than protective maternal anaerobic flora.\n\nThe authors suggest that ascending bacterial infections occur because uropathogenic P-fimbriated E. coli adhere avidly to the mucosal prepuce in the absence of normal maternal flora and maternal passive antibodies. Rather than resorting to universal routine circumcision, the paper argues for exploring more physiological alternatives, such as promoting maternal-infant rooming-in or actively establishing maternal gut and mucosal flora to prevent colonization by pathogenic bacteria.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jan Winberg", "Ingela Bollgren", "Leif Gothefors", "Maria Herthelius", "Kjell Tullus", "Thomas E. Wiswell"], "organizations": ["The Lancet", "Karolinska Institutet", "Karolinska Hospital", "Sach''s Childrens Hospital", "Umea University", "Danderyds Hospital", "Swedish Medical Research Council", "American Academy of Pediatrics"], "themes": ["Neonatal Circumcision", "Urinary Tract Infections (UTI)", "Bacterial Colonization", "Escherichia coli Pathogenesis", "Neonatal Microbial Ecology", "Infant Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4256956c4477212f3d87857ebdb4a52d37c5dc30cefb458d2d244db67dbb7857', 'Winkelmann Erogenous Zones Mayo 1959.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4256956c4477212f3d87857ebdb4a52d37c5dc30cefb458d2d244db67dbb7857.pdf', 'medical_journal', 'ingested', '{"date": "1959-01-21", "description": "This medical paper categorizes erogenous zones into nonspecific and specific types, examining their distinct neuroanatomy and sensory receptors. Nonspecific zones, such as the neck and axilla, rely on regular haired skin networks to produce an exaggerated tickle sensation. Specific erogenous zones encompass mucocutaneous regions\u2014including the prepuce, clitoris, glans penis, lips, and perianal tissue\u2014which feature specialized mucocutaneous end-organs and dense nerve networks that favor acute tactile perception.\n\nAuthor R. K. Winkelmann observes that these organized mucocutaneous endings develop largely postnatally, increasing in structural complexity with age. He suggests that this anatomical maturation aligns with psychoanalytic theories of psychosexual development (oral, anal, and genital stages) and posits that individual anatomical variations in cutaneous innervation could provide an organic basis for sexual disorders and clinical syndromes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["R. K. Winkelmann", "William Krause", "J. F. Tello", "H. Jaeger"], "organizations": ["Mayo Clinic", "Mayo Association", "Mayo Foundation for Medical Education and Research", "Circumcision Information and Resource Pages (CIRP)"], "themes": ["Cutaneous Innervation", "Neuroanatomy", "Erogenous Zones", "Mucocutaneous End-Organs", "Psychosexual Development", "Genital Anatomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('10c6a7f5f19bead33b35a4882a3ba0480249c644eb4d0feaf42a163a53dd934f', 'Wisdom Circumcisionism_Feminism_Gender JHUmRts 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/10c6a7f5f19bead33b35a4882a3ba0480249c644eb4d0feaf42a163a53dd934f.pdf', 'other', 'ingested', '{"date": "2012", "description": "In this academic paper, author Travis Wisdom argues that routine neonatal male circumcision constitutes genital mutilation and must be recognized as a serious human rights violation and feminist issue. While the global feminist movement has actively condemned female genital mutilation (FGM) to protect bodily integrity, it has largely ignored or trivialized male circumcision. Wisdom conceptualizes ''circumcisionism'' as the hegemonic cultural ideology in Western society that normalizes foreskin amputation through medicalization, religious tradition, aesthetic pressure, and linguistic bias, sustained by misinformation regarding infant pain, hygiene, and disease prevention.\n\nWisdom calls on feminists to support ''intactivism''\u2014a movement advocating for universal genital autonomy across the gender spectrum. The paper highlights legal inconsistencies, noting that while federal law strictly bans all forms of non-consensual female genital cutting, it leaves male infants legally unprotected. Wisdom concludes that maintaining this legal and ethical double standard perpetuates sex discrimination, arguing that true feminist commitments to gender equity and bodily ownership necessitate opposing all medically unnecessary, non-consensual genital modifications.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Travis Wisdom", "Paul M. Fleiss", "Cherr\u00ede Moraga", "bell hooks"], "organizations": ["University of Nevada \u2013 Las Vegas", "UNICEF"], "themes": ["Circumcisionism", "Feminism and Gender Equity", "Genital Autonomy", "Human Rights", "Intactivism", "Medicalization of Genitalia", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('43423abb88c594a2fa20d9d7478d127605cc2e5b2da5fe08e636a2ee9566ffc6', 'Wisdom Constructing_Phallic_Beauty InterDiscPress 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/43423abb88c594a2fa20d9d7478d127605cc2e5b2da5fe08e636a2ee9566ffc6.pdf', 'other', 'ingested', '{"date": "2014", "description": "This document examines ''circumcisionism''\u2014the hegemonic cultural and medical ideology that frames male genital cutting as normative, hygienic, and aesthetically desirable, particularly in the United States. Against this backdrop, the author evaluates the physical and psychological consequences of non-consensual infant circumcision and explores foreskin restoration as an act of bodily reclamation and aesthetic resistance. Presenting empirical findings from a mixed-methods study of 87 restoring men, the chapter details participants'' motivations, restoration techniques, and self-reported outcomes, highlighting how non-surgical tissue expansion helps men restore penile sensation, recover anatomical integrity, and reconstruct alternative ideals of masculine beauty.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Travis Wisdom", "Sallie McNamara", "Robert Fisher", "Lisa Howard", "Ken Monteith"], "organizations": ["Inter-Disciplinary Press", "Inter-Disciplinary.Net", "Keele University"], "themes": ["Foreskin Restoration", "Circumcision and Medicalisation", "Circumcisionism", "Masculine Beauty and Body Image", "Bodily Autonomy and Consent", "Sexual Health and Function"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('554a1e7025b6d908e0618251d09b8848df249c493f8d32063a00e907ebfdb908', 'WSJ Circ Coverage (Univ FL) 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/554a1e7025b6d908e0618251d09b8848df249c493f8d32063a00e907ebfdb908.pdf', 'newspaper_clipping', 'ingested', '{"date": "2014-01-20", "description": "Following a 2012 policy revision by the American Academy of Pediatrics recognizing the health benefits of circumcision, several U.S. states are reconsidering their decisions to exclude routine newborn circumcision from Medicaid coverage. After earlier policy guidance in 1999 led 18 states to eliminate routine funding to cut costs, researchers found that the policy often resulted in higher overall expenses. When families cannot afford infant circumcision, boys often require the procedure later in childhood due to medical complications\u2014requiring general anesthesia and costing far more under Medicaid than newborn procedures.\n\nWhile pediatricians and studies from institutions like the University of Florida Health and Johns Hopkins suggest that restoring coverage is cost-effective and prevents subsequent medical issues, opposition remains from anti-circumcision groups and state agencies questioning the medical necessity of elective coverage. Consequently, legislative efforts to reinstate funding face mixed progress across states.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Newspaper Clipping", "key_people": ["Saleem Islam", "Arian Campo-Flores", "Douglas Diekema"], "organizations": ["The Wall Street Journal", "American Academy of Pediatrics", "Florida Agency for Health Care Administration", "University of Florida Health", "Centers for Disease Control and Prevention", "Johns Hopkins University", "Medicaid"], "themes": ["Medicaid Coverage and Healthcare Policy", "Newborn and Pediatric Circumcision", "Healthcare Economics and State Budgets", "Preventative Healthcare vs. Elective Procedures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b51b2e74f661c212cfb334d56399167807f4b3a19e16302ad3cb3f9e4d09cdc2', 'Yang Foreskin development WorldJPeds 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b51b2e74f661c212cfb334d56399167807f4b3a19e16302ad3cb3f9e4d09cdc2.pdf', 'medical_journal', 'ingested', '{"date": "2009-11-15", "description": "This study evaluates the natural development of the foreskin and the prevalence of external genitalia abnormalities in a cohort of 10,421 Chinese boys aged 0 to 18 years at the Children''s Hospital of Chongqing Medical University. The findings show that phimosis is overwhelmingly common at birth (99.7%) but resolves naturally over time, dropping to 6.81% by adolescence as retractability steadily increases to 42.26%. Additional recorded conditions included micropenis, cryptorchidism, and inguinal hernias, with an overall abnormality rate of 7.98%.\n\nThe authors conclude that incomplete preputial separation is a normal physiological state in young boys rather than a pathology requiring immediate treatment. Consequently, they argue that routine circumcision and forced prepuce dilation before puberty are often unnecessary and may cause scarring, recommending that surgical interventions be reserved for pathological phimosis or specific medical indications after adolescence.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Chao Yang", "Xing Liu", "Guang-Hui Wei"], "organizations": ["Children''s Hospital of Chongqing Medical University", "Chongqing Medical University"], "themes": ["Foreskin Development", "Phimosis", "Circumcision", "Pediatric Urology", "Congenital Genital Abnormalities"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d0c45a13936c539df3366e51b13ead18e7d4e81da5dbf6cd77a572e94258b4cb', 'Yang Trends in Circ JAMA Peds 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d0c45a13936c539df3366e51b13ead18e7d4e81da5dbf6cd77a572e94258b4cb.pdf', 'medical_journal', 'ingested', '{"date": "2025-09-15", "description": "This cross-sectional study examines trends in inpatient neonatal male circumcision (NMC) in the United States from 2012 to 2022 using data from the Kids'' Inpatient Database. Despite endorsements regarding the health benefits of circumcision from major health organizations such as the WHO, AAP, and CDC, overall inpatient NMC prevalence significantly decreased from 54.1% in 2012 to 49.3% in 2022. The most pronounced reductions were observed among White neonates, infants from higher-income zip codes, and those with private insurance coverage, while prevalence remained stable among Black and Hispanic neonates.\n\nGeographically, the Midwest maintained the highest rates of circumcision while the West had the lowest. The authors attribute the continuing decline to multiple potential factors, including growing skepticism toward medical recommendations, policy shifts allowing parental discretion, shifting demographics such as growth in the Hispanic population, and Medicaid funding restrictions in multiple states.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ping Yang", "Xianming Zhu", "Eshan U. Patel", "Thomas C. Quinn", "Mary K. Grabowski", "Aaron A. R. Tobian"], "organizations": ["JAMA Pediatrics", "American Medical Association", "World Health Organization", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "Johns Hopkins University", "National Institute of Diabetes and Digestive and Kidney Diseases"], "themes": ["Neonatal Male Circumcision", "Pediatric Health", "Epidemiology and Healthcare Trends", "Racial and Socioeconomic Disparities", "Healthcare Insurance and Medicaid Coverage"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b8b652feff1b882592e4c1383d19bcde9819805092be6a167f453dfbb352227c', 'Yang Trends in Circ JAMA Peds-Hammond reply 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b8b652feff1b882592e4c1383d19bcde9819805092be6a167f453dfbb352227c.pdf', 'letter', 'ingested', '{"date": "2025", "description": "This document is a critical letter responding to a study by Yang and colleagues regarding male newborn circumcision trends in the United States. The author disputes claims that the American Academy of Pediatrics (AAP) ever formally recommended routine infant circumcision, noting that their 2012 policy expired without renewal. The text argues that nontherapeutic neonatal circumcision violates bodily integrity, the Hippocratic Oath, and the AMA Code of Medical Ethics, asserting that physicians misuse diagnoses like phimosis to obtain insurance reimbursement. The author calls on physicians to respect pediatric patient autonomy and suggests that the legal system must intervene to protect children from nonconsensual, irreversible surgical interventions if medical ethics fail.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Letter", "key_people": ["Tim Hammond", "Andrew Freedman", "P. Yang"], "organizations": ["Genital Autonomy Legal Defense and Education Fund", "American Academy of Pediatrics", "American Medical Association", "Brussels Collaboration on Bodily Integrity"], "themes": ["Infant Circumcision", "Medical Ethics", "Bodily Integrity", "Proxy Consent", "Children''s Rights", "Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c7f6c63bab97def1f44f8d1bd57de2a7b1a7186bb31f45ffd362d9366ac1b977', 'Yang Trends in Circs Corrections JAMA Peds_2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c7f6c63bab97def1f44f8d1bd57de2a7b1a7186bb31f45ffd362d9366ac1b977.pdf', 'medical_journal', 'ingested', '{"date": "2026-02-23", "description": "This document is a formal correction notice published in JAMA Pediatrics regarding the Research Letter titled ''Trends in Circumcision Among Newborn Males in the US.'' The correction amends statements concerning organizational recommendations from the World Health Organization (WHO), American Academy of Pediatrics (AAP), and Centers for Disease Control and Prevention (CDC).\n\nThe revisions clarify that the 2012 AAP recommendation regarding newborn male circumcision expired in 2017 and has not been replaced, while also noting the AAP''s position that parents should make the final decision despite the benefits outweighing the risks. The notice also updates language in the Discussion section to reflect the expiration of the AAP recommendation alongside the observed decline in newborn male circumcision prevalence between 2012 and 2022.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Yang P", "Zhu X", "Patel EU", "Quinn TC", "Grabowski MK", "Tobian AAR"], "organizations": ["World Health Organization", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "American Medical Association"], "themes": ["Newborn Male Circumcision", "Pediatric Health Guidelines", "Public Health Recommendations", "Medical Errata and Clarifications"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6ad993d3c22080353a025d8a1103d510747d0cb3a661a23e415f2763446c3fab', 'Yang_effect_circ_young_adult KaoJMedSci 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6ad993d3c22080353a025d8a1103d510747d0cb3a661a23e415f2763446c3fab.pdf', 'medical_journal', 'ingested', '{"date": "2013-12-09", "description": "This prospective study evaluated the effect of adult male circumcision on sexual function among 442 young Taiwanese men, assessing them before and 90 days after surgery using the International Index of Erectile Function-5 (IIEF-5), the Brief Male Sexual Function Inventory (BMSFI), and intravaginal ejaculation latency times (IELT). The primary indications for circumcision included phimosis, personal hygiene, and cosmetic reasons.\n\nThe findings demonstrated a statistically significant improvement in BMSFI scores, characterized by an increase in sexual drive and greater mental erection confidence post-procedure. Although overall IIEF-5 scores and sexual satisfaction showed no significant differences, patients reported slightly greater difficulty maintaining erections to intercourse completion and a trend toward shorter IELT, indicating that while adult circumcision enhances confidence and libido, further long-term study is needed.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Ming-Hsin Yang", "Chih-Wei Tsao", "Sheng-Tang Wu", "Feng-Ping Chuang", "En Meng", "Shou-Hung Tang", "Guang-Huan Sun", "Dah-Shyong Yu", "Sun-Yran Chang", "Tai-Lung Cha"], "organizations": ["Tri-Service General Hospital", "National Defense Medical Center", "Kaohsiung Medical University", "Elsevier Taiwan LLC"], "themes": ["Circumcision", "Sexual Function", "Erectile Dysfunction", "Urology", "Intravaginal Ejaculation Latency Time"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1e7bb08aa96ac277849e4a0dfa3821ddbce3ff4de0879249ecf94fe04f7b21b6', 'Young That Thing Springer 2009.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1e7bb08aa96ac277849e4a0dfa3821ddbce3ff4de0879249ecf94fe04f7b21b6.pdf', 'other', 'ingested', '{"date": "2009", "description": "This document explores the portrayal of the foreskin and circumcision in popular American media, particularly within television sitcoms, soap operas, and talk shows. The author argues that popular television plays a subtle yet significant role in promoting male circumcision in the United States, despite presenting contradictory and ambiguous messages. The procedure is frequently trivialized, treated as comic, or deemed inevitable, while the foreskin itself is commonly denigrated across dozens of prominent TV programs.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Hugh Young", "G. Denniston"], "organizations": ["Springer Science + Business Media B.V."], "themes": ["Circumcision", "Media Influence", "Popular Culture", "Television Sitcoms", "Human Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fbee4e1cfabcde672b9a128ccb4c41926d47059aea78200cf747c8c886c2c1c5', 'Zabus Beyond_Circumspection Matatu 2008.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fbee4e1cfabcde672b9a128ccb4c41926d47059aea78200cf747c8c886c2c1c5.pdf', 'other', 'ingested', '{"date": "2008", "description": "This academic essay by Chantal Zabus examines the discursive asymmetry between literary representations of female excision and male circumcision. While autobiographical writing by women against excision proliferated significantly from the 1990s onward, first-person accounts of male circumcision remain comparatively scarce. Zabus analyzes a progression beyond traditional ''circumspection'' through four distinct historical and cultural moments in male autobiographical writing: seventeenth-century converso confessions under the Spanish Inquisition, Kenyan Kikuyu ethno-autobiographies from the 1960s by Mugo Gatheru and Karari Njama, Jacques Derrida''s deconstructive confessional text ''Circumfession'', and Riad Sattouf''s anti-circumcision graphic novel ''Ma circoncision''.\n\nThe article demonstrates how these male experiential accounts articulate physical trauma, peer and patriarchal coercion, parental alienation, and bodily mourning. In doing so, they dismantle normative religious and cultural justifications for male circumcision, bridging African, Jewish, and Muslim experiences while challenging the broader silence surrounding male genital cutting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Chantal Zabus", "Jacques Derrida", "Riad Sattouf", "Mugo Gatheru", "Karari Njama", "Leonard B. Glick", "H\u00e9l\u00e8ne Cixous", "Sami Aldeeb Abu-Sahlieh"], "organizations": ["Editions Rodopi", "United Nations", "National Organization for Restoring Men (NORM)", "National Organization to Halt the Abuse and Routine Mutilation of Males (NOHARMM)"], "themes": ["Male Circumcision", "Female Genital Excision", "Autobiography and Life Writing", "Bodily Integrity and Trauma", "Discursive Asymmetry", "Rites of Passage", "Religion and Identity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f3d059bd5df6616484ecd7db8f1cb0689e4fadf57d010339762a50fa276613ff', 'Zakirhusain VMMC India SchJ AppMedSci 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f3d059bd5df6616484ecd7db8f1cb0689e4fadf57d010339762a50fa276613ff.pdf', 'medical_journal', 'ingested', '{"date": "2017", "description": "This cross-sectional online study evaluates the knowledge, acceptability, and perceived barriers regarding Voluntary Medical Male Circumcision (VMMC) among adult Indian men. Surveying 111 participants, the study found that 65% were aware of VMMC, with the most recognized benefit being improved genital hygiene (70%), followed by protection against penile cancer and sexually transmitted infections.\n\nAmong uncircumcised respondents, 29% expressed willingness to undergo VMMC, citing genital hygiene as their primary motivation. Contrary to common assumptions, religious and cultural objections were reported as a barrier by only 9% of those who declined. The authors conclude that socio-cultural barriers are not an insurmountable obstacle to VMMC in India and recommend that public health authorities offer safe, free circumcision services alongside targeted educational campaigns on HIV prevention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dr. Zakirhusain Shaikh", "Dr. Mihir Rupani"], "organizations": ["Hamdard Institute of Medical Sciences and Research", "Jamia Hamdard", "Government Medical College, Bhavnagar", "World Health Organization", "Indian Council of Medical Research", "National AIDS Research Institute", "Scholars Academic and Scientific Publisher"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV/AIDS Prevention", "Sexually Transmitted Infections", "Penile Hygiene", "Public Health and Socio-cultural Acceptability"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('80dca1bd8a04e265667a8c3b1e2c299f4cc6ab27ce5861f6374d305dae65344a', 'Zaliznyak Anatomic Map JSexMed 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/80dca1bd8a04e265667a8c3b1e2c299f4cc6ab27ce5861f6374d305dae65344a.pdf', 'medical_journal', 'ingested', '{"date": "2023", "description": "This study investigates whether male circumcision affects penile erogenous sensation and orgasm function by comparing self-reported data from 227 circumcised and 175 uncircumcised adult men. Participants rated pleasure across 12 anatomical penile regions on a 1\u201310 scale and evaluated six orgasm-related experiential domains via an anonymous web-based survey. The findings revealed no significant differences in overall pleasure ratings across penile regions or in orgasm parameters (including duration, time to reach orgasm, refractory period, and overall satisfaction) between circumcised and uncircumcised cohorts, though circumcised men were significantly more likely to report preferences for the penile tip and the middle ventral shaft. The authors conclude that male circumcision does not adversely affect penile erogeneity or orgasm quality, offering relevant empirical evidence for clinical counseling.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michael Zaliznyak", "Dylan Isaacson", "Erin Duralde", "Thomas W. Gaither", "Aurash Naser-Tavakolian", "Catherine Bresee", "Jenna Stelmar", "Nance Yuan", "Kimberly Topp", "Maurice M. Garcia"], "organizations": ["Oxford University Press", "International Society of Sexual Medicine", "Cedars-Sinai Medical Center", "Saint Louis University School of Medicine", "Northwestern University Feinberg School of Medicine", "Brigham and Women\u2019s Hospital", "Harvard Medical School", "University of California Los Angeles", "University of California San Francisco"], "themes": ["Male Circumcision", "Penile Erogenous Sensation", "Orgasm Function and Quality", "Sexual Health", "Urology and Andrology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('6627fb9153b79b09308b110c2f1f458a020554c734a6bad576f91238f5d098ad', 'Zambrano-Navia State Pub Insur Peds 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/6627fb9153b79b09308b110c2f1f458a020554c734a6bad576f91238f5d098ad.pdf', 'medical_journal', 'ingested', '{"date": "2020-10-14", "description": "This retrospective cohort study evaluates the impact of state-level Medicaid coverage policies on neonatal male circumcision rates using State Inpatient Databases data from four states (Colorado, Florida, Michigan, and New York) across four time points between 2001 and 2016. The authors observed that states that defunded Medicaid coverage for neonatal circumcision experienced significant reductions in procedure rates, specifically decreasing from 47.4% to 37.5% in Florida following defunding in 2003 and from 61.9% to 52.0% in Colorado following defunding in 2011.\n\nMultivariable analyses demonstrated that privately insured neonates had significantly higher odds of circumcision than publicly insured infants. Furthermore, policy defunding disproportionately affected Black neonates, who had higher odds of circumcision compared with white neonates when Medicaid coverage was active, but significantly lower odds when coverage was eliminated. The study concludes that removing public insurance coverage restricts access contrary to evidence-based recommendations from the American Academy of Pediatrics, exacerbating health disparities and potentially increasing long-term health system costs through complications and delayed elective procedures.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Mateo Zambrano Navia", "Deborah L. Jacobson", "Lauren C. Balmert", "Ilina Rosoklija", "Jane L. Holl", "Matthew M. Davis", "Emilie K. Johnson"], "organizations": ["American Academy of Pediatrics", "Northwestern University Feinberg School of Medicine", "Ann & Robert H. Lurie Children\u2019s Hospital of Chicago", "The University of Utah School of Medicine", "The University of Chicago", "Agency for Healthcare Research and Quality", "Colorado Department of Health Care Policy and Financing"], "themes": ["Medicaid Policy and Coverage", "Neonatal Male Circumcision", "Healthcare Disparities", "Racial and Ethnic Disparities in Health Access", "Preventive Pediatric Care"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8eb29356a52cd20b76aed81a4bb7eb5bdb17d5158a1d3aab5d28eb3ef1790881', 'Zebastian Johanzen PMDGMD.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8eb29356a52cd20b76aed81a4bb7eb5bdb17d5158a1d3aab5d28eb3ef1790881.pdf', 'other', 'ingested', '{"date": null, "description": "This text critiques the practice of diagnosing men seeking prepuce (foreskin) reconstruction with Body Dysmorphic Disorder (BDD). The author argues that these men have a biologically accurate understanding of anatomy and functionality, whereas the clinicians who dismiss their concerns exhibit what the text terms ''Pseudomedical Delusional Genital Mutilation Disorder (PMDGMD)''. It emphasizes the physiological and sensory importance of the prepuce, asserting that pathologizing patients'' desire to restore it represents a severe clinical misdiagnosis.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": [], "themes": ["Body Dysmorphic Disorder", "Prepuce Reconstruction", "Medical Misdiagnosis", "Genital Anatomy and Physiology", "Circumcision Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('39d9b9ec2a941691aaf1dee3d332929bdbcee3ceff1259ddeb165452dbdca02c', 'Zekeri HIV Conspiracy among Blacks AcadLtrs2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/39d9b9ec2a941691aaf1dee3d332929bdbcee3ceff1259ddeb165452dbdca02c.pdf', 'medical_journal', 'ingested', '{"date": "2021", "description": "This study examines beliefs regarding the origin of HIV/AIDS as a genocidal, manmade conspiracy among 258 African American and 97 White HIV-positive patients receiving care at clinics in southeastern Alabama. The findings indicate that race is the primary predictor of conspiracy beliefs, with African American patients significantly more likely than White patients to endorse theories that AIDS is a manmade virus (79.3%), a genocidal tool against Black people (77.8%), and produced in a government laboratory (76.3%).\n\nThe author concludes that these persistent conspiracy beliefs reflect deep-seated and historically rooted distrust of the American healthcare system and government among African Americans. Because such distrust can hinder engagement with treatment and adherence, the paper emphasizes that public health programs and prevention efforts must actively acknowledge, understand, and sensitively address these beliefs and community mistrust.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Andrew A. Zekeri"], "organizations": ["Tuskegee University", "AIDS Outreach Organization"], "themes": ["HIV/AIDS", "Conspiracy Theories", "Medical Mistrust", "Racial Disparities in Health", "Public Health and Prevention", "Rural Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c486f39643b2bc4488cb5496dc67e708977e33f50c30b8f1cf8fe4c58da1d454', 'Zhang Trends Newborn Male Circ 1999-2010.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c486f39643b2bc4488cb5496dc67e708977e33f50c30b8f1cf8fe4c58da1d454.pdf', 'medical_journal', 'ingested', '{"date": "2011-09-02", "description": "This report from the Centers for Disease Control and Prevention examines trends in in-hospital newborn male circumcision (NMC) in the United States from 1999 to 2010 using three independent inpatient data sources: the National Hospital Discharge Survey (NHDS), the Nationwide Inpatient Sample (NIS), and the Charge Data Master (CDM). Despite evidence indicating that adult male circumcision reduces HIV transmission risk, all three datasets revealed statistically significant decreases in routine in-hospital NMC incidence over the evaluated decade.\n\nThe findings show NMC rates dropping across datasets, with NHDS recording a decrease from 62.5% in 1999 to 56.9% in 2008, NIS declining from 63.5% to 56.3% over the same timeframe, and CDM showing a drop from 58.4% in 2001 to 54.7% in 2010. The authors note that insurance coverage heavily influences these rates, citing research that hospitals in states where Medicaid covers routine male circumcision report substantially higher procedure rates compared to states without coverage.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Xinjian Zhang", "Sanjyot Shinde", "Peter H Kilmarx", "Robert T Chen", "Shanna Cox", "Lee Warner", "Maria Owings", "Charbel El Bcheraoui", "Sarah Clark"], "organizations": ["Centers for Disease Control and Prevention", "National Center for HIV/AIDS, Viral Hepatitis, STD, and TB Prevention", "National Center for Chronic Disease Prevention and Health Promotion", "National Center for Health Statistics", "Agency for Healthcare Research and Quality", "SDIHealth", "American Hospital Association", "University of Michigan", "Medicaid"], "themes": ["Newborn Male Circumcision Trends", "Inpatient Hospitalization Data", "HIV and STI Prevention", "Public Health Surveillance", "Medicaid and Healthcare Coverage Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f1047449cb4d908b954b9b2d33c6e8234a67b3e90501dda3b97bf84a95dad366', 'Zoske Gender Perspective  JMensStud 1998.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f1047449cb4d908b954b9b2d33c6e8234a67b3e90501dda3b97bf84a95dad366.pdf', 'other', 'ingested', '{"date": "1998", "description": "This article critically examines the practice of routine neonatal male circumcision in the United States from historical, medical, ethical, and psychosexual perspectives. The author argues that circumcision is an unnecessary, non-consensual elective amputation of healthy, functional genital tissue that causes severe neonatal pain, risks surgical complications, and leaves lifelong physical and psychological trauma. The text contrasts the widespread social acceptance of male circumcision with the legal and ethical outcry against female genital mutilation, framing this disparity as a societal double standard.\n\nPositioning the procedure within gender studies, the paper contends that routine circumcision serves as an early cultural wounding that conditions men to accept bodily violence and disconnection from somatic sensuality. Highlighting evolving stances from pediatric organizations, testimonies from conscientious objector medical personnel, and the emergence of anti-circumcision and foreskin restoration movements, the author calls for an end to routine medical circumcision and urges greater respect for male bodily integrity.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Joseph Zoske", "Douglas Gardiner", "Sigmund Freud", "Ronald Goldman", "George C. Denniston", "Marilyn Milos"], "organizations": ["American Academy of Pediatrics", "American College of Obstetricians and Gynecologists", "Canadian Paediatric Society", "American Medical Association", "National Organization of Circumcision Information Resource Centers", "National Organization to Halt the Abuse and Routine Mutilation of Males", "Doctors Opposing Circumcision", "Nurses for the Rights of the Child"], "themes": ["Male Circumcision", "Bodily Integrity and Human Rights", "Neonatal Pain and Medical Ethics", "Psychosexual Trauma and Gender Identity", "Cultural Denial and Double Standards", "Foreskin Anatomy and Restoration"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5d0d185fc1e63561e8687e6b5ef75a6161cf6a30478d7e345a02cd93de115621', 'Özer Mokken Comment Foreskin Restorers IJIR 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5d0d185fc1e63561e8687e6b5ef75a6161cf6a30478d7e345a02cd93de115621.pdf', 'medical_journal', 'ingested', '{"date": "2023-04-17", "description": "This commentary examines a study by Hammond et al. regarding the motivations, challenges, and psychological experiences of individuals undergoing foreskin reconstruction following infant circumcision. The authors note that an overwhelming majority (up to 87%) of this population avoids seeking professional medical guidance, identifying them as an underserved group that frequently begins non-surgical restoration methods during adolescence or early adulthood to alleviate experienced sexual impairment and psychological distress.\n\nThe authors emphasize the urgent necessity of establishing open, evidence-based dialogues between healthcare providers and patients seeking foreskin restoration. Furthermore, they argue for a medical-ethics reconsideration of early infant penile circumcision, advocating that it should be reframed not merely as a parental choice, but as a medically unnecessary genital procedure on healthy infants.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["S. E. Mokken", "M. \u00d6zer", "F. W. Timmermans", "Hammond"], "organizations": ["Springer Nature", "Amsterdam University Medical Center", "BovenIJ Hospital", "V-Klinieken"], "themes": ["Foreskin Reconstruction", "Male Circumcision", "Medical Ethics", "Bodily Integrity", "Sexual Health and Function", "Patient-Provider Communication"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('32c871635561493e6edec23fb81bbc7c8e18a1e16a6e05c6af8f1f8036e0de05', 'Özer Timmerman Insight ForeskinReconstruction IJIR 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/32c871635561493e6edec23fb81bbc7c8e18a1e16a6e05c6af8f1f8036e0de05.pdf', 'medical_journal', 'ingested', '{"date": "2020", "description": "This prospective cohort study evaluates 11 men who sought medical assistance for foreskin reconstruction at the Amsterdam University Medical Center between 2015 and 2019. The participants, who were circumcised either during infancy for religious/cultural reasons or during adulthood due to medical conditions like lichen sclerosus, cited motivations such as loss of body integrity, feelings of mutilation, diminished glans sensitivity, and distress over imposed religious identity. Men circumcised in adulthood sought help significantly sooner after the procedure than those circumcised as infants.\n\nThe study highlights that patients frequently experienced a lack of support from healthcare providers and largely relied on internet forums for guidance. Nearly all patients utilized non-surgical mechanical tissue expansion and unregistered stretching devices (such as the Dual Tension Retriever) over several years to achieve coverage. The authors emphasize that patients face a profound psychological burden and urge clinicians to approach foreskin reconstruction with an open-minded attitude while calling for systematic research into the safety and efficacy of non-surgical methods.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["M. \u00d6zer", "Floyd W. Timmermans"], "organizations": ["Amsterdam University Medical Center", "VU University Medical Center", "Springer Nature", "World Health Organization"], "themes": ["Foreskin reconstruction", "Male circumcision", "Body integrity", "Tissue expansion and stretching", "Patient-physician communication", "Sexual health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0032c242da489c84c7e772482b60e12082ebdf9cb663f3fe2e8eaeaf4b1a1874', 'Consent Gentle Touch.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0032c242da489c84c7e772482b60e12082ebdf9cb663f3fe2e8eaeaf4b1a1874.pdf', 'legal_document', 'ingested', '{"date": null, "description": "This document is an informed consent form for elective infant circumcision under local anesthesia performed by Dr. Stefanie Green. It establishes legal parental consent while noting that the Canadian Paediatric Society does not recommend routine circumcision. The form requires parents to acknowledge understanding of the procedure''s elective nature, the lack of cosmetic guarantees, and the associated surgical risks.\n\nThe document also provides an overview of statistical risks and scientific benefits associated with newborn circumcision. Outlined complications include varying degrees of bleeding, infection, suboptimal cosmetic outcomes, rare penile trauma, and mortality risks, as well as clear contraindications for premature infants or those with bleeding disorders. Conversely, it lists medical benefits such as substantially reduced risks of urinary tract infections, penile cancer, phimosis, and various sexually transmitted infections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Stefanie Green"], "organizations": ["Canadian Paediatric Society"], "themes": ["Informed Consent", "Infant Circumcision", "Surgical Risks and Complications", "Pediatric Health", "Preventive Healthcare"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('68fdaa22fae3ced64215cde7b9201a497e17d7cca234a548935985345863f65c', 'Consent Gerson Mohelet.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/68fdaa22fae3ced64215cde7b9201a497e17d7cca234a548935985345863f65c.pdf', 'legal_document', 'ingested', '{"date": null, "description": "This document is a standard medical and religious informed consent form authorizing Dr. Gerson to perform a newborn circumcision and Brit Milah ceremony. It outlines that the procedure involves removing the foreskin from the penis for religious purposes, affirming the parents'' commitment to Jewish traditions.\n\nThe form details potential procedural risks, including bleeding, infection, and rare instances of penile damage, while acknowledging that cosmetic outcomes are governed by individual anatomy and cannot be guaranteed. By signing, the parents confirm they have discussed the procedure with the mohelet and voluntarily consent to both the medical operation and religious rite.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Dr. Gerson"], "organizations": ["Berit Milah Board of Reform Judaism", "National Organization of American Mohalim"], "themes": ["Informed Consent", "Brit Milah", "Newborn Circumcision", "Reform Judaism", "Medical Risks"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('a95851c3f94f369658f01e7b73fa5f11717add8031c03c6a39ffba954d82fcf5', 'HealthInfo Translations MaleCircumcision_SP.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/a95851c3f94f369658f01e7b73fa5f11717add8031c03c6a39ffba954d82fcf5.pdf', 'policy_guideline', 'ingested', '{"date": "2011", "description": "This bilingual (English and Spanish) patient education guide provides clear instructions and medical guidance for parents regarding newborn male circumcision. It details the surgical procedure, anesthesia, and typical recovery protocols for both the clamp and plastic ring methods, including expected healing timelines and pain management.\n\nIn addition, the document outlines essential home care routines, emphasizing proper diaper hygiene, gentle cleaning, and the avoidance of alcohol-based wipes. It also specifies warning signs of potential complications\u2014such as excessive bleeding, signs of infection, or urinary retention\u2014that require prompt medical evaluation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Policy Guideline", "key_people": [], "organizations": ["Health Information Translations", "The Ohio State University Medical Center", "Mount Carmel Health System", "OhioHealth", "Nationwide Children\u2019s Hospital"], "themes": ["Male Circumcision", "Newborn Care", "Post-Procedure Care", "Pediatric Health", "Patient Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d87ac283c10b7b8ecc95533501d6d8517ed2692d70a36604c1a720dad953f525', 'Informed Consent Avista Adventist  Hospital.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d87ac283c10b7b8ecc95533501d6d8517ed2692d70a36604c1a720dad953f525.pdf', 'legal_document', 'ingested', '{"date": "2008-08", "description": "This document is an informed consent form from Avista Adventist Hospital (Centura Health) for elective infant circumcision. It states that the procedure is performed for personal, cultural, or religious reasons rather than medical necessity, and outlines potential benefits alongside procedural risks such as pain, bleeding, and penile injury. It also details analgesia and pain-modifying techniques in line with Academy of Pediatrics recommendations, while granting authorization for necessary unforeseen procedures, assistant medical staff, and specimen retention.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": [], "organizations": ["Avista Adventist Hospital", "Centura Health", "Academy of Pediatrics"], "themes": ["Informed Consent", "Infant Circumcision", "Pediatric Pain Management", "Surgical Risks and Benefits", "Patient Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e2495f8da112293b47a332f651db2468293cd08029f2a5d589f99d001f256409', 'Informed Consent Queensland Health  Australia.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e2495f8da112293b47a332f651db2468293cd08029f2a5d589f99d001f256409.pdf', 'legal_document', 'ingested', '{"date": "2004", "description": "This document is a paediatric circumcision consent form published by Queensland Health. It details the nature of the procedure, involving the surgical removal of the foreskin, and provides sections to verify patient identification, interpreter needs, and cultural support requirements.\n\nThe form outlines standard surgical risks and complications associated with paediatric circumcision, including cosmetic dissatisfaction, damage to the tip of the penis, bleeding, scarring causing urinary obstruction, infection requiring antibiotics, and the potential need for further surgery. It requires clinicians to explain specific risks, outcomes, and alternative treatment options to parents before obtaining consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": [], "organizations": ["Queensland Government", "Queensland Health"], "themes": ["Paediatric Circumcision", "Informed Consent", "Surgical Risks", "Patient Rights and Cultural Support"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8783f09bbd2629c1e0553fd9c7b9e4f1a5ec6da754ec5ce916b7c7f6fd443083', 'Informed Consent Southwest  Washington Med Center.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8783f09bbd2629c1e0553fd9c7b9e4f1a5ec6da754ec5ce916b7c7f6fd443083.pdf', 'legal_document', 'ingested', '{"date": null, "description": "This document contains informational guidance and formal consent forms for newborn care procedures, specifically neonatal circumcision and the newborn Hepatitis B vaccination. It provides parents with details regarding the definition, reasons, and potential complications of circumcision, alongside standard consent signature sections and a procedural record detailing equipment, anesthesia, and outcomes. Additionally, it includes a maternal consent authorization for administering the initial dose of the Hepatitis B vaccine series in the nursery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": [], "organizations": ["Southwest Washington Medical Center", "Family Birth Center", "Healthy Steps Women''s and Children''s Center", "Health Department"], "themes": ["Neonatal Circumcision", "Informed Consent", "Hepatitis B Vaccination", "Newborn Care", "Pediatric Procedures"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d5d623a1023100c3bc5484483a21dc1cfd44b1b1f852c16015c0ca11f717d44b', 'Informed Consent Sunshine Valley  Pediatrics.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d5d623a1023100c3bc5484483a21dc1cfd44b1b1f852c16015c0ca11f717d44b.pdf', 'legal_document', 'ingested', '{"date": null, "description": "This document is a medical informed consent and authorization form for pediatric circumcision issued by Sunshine Valley Pediatrics. It informs parents about the procedure''s duration, requests that they remain outside the room, and details potential risks such as bleeding, infection, severe scarring, tissue damage, need for revision, and reactions to Lidocaine. By signing, the parent or guardian acknowledges understanding these risks, authorizes emergency procedures if needed, and consents to the use of a sucrose solution for pain management.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": [], "organizations": ["Sunshine Valley Pediatrics"], "themes": ["Informed Consent", "Pediatric Surgery", "Circumcision Risks", "Medical Liability", "Pain Management"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0258a275ec808d12d896ae6da3d3563220cae846ef910413c3bc6a3243045229', 'Longley Informed Consent Thesis.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0258a275ec808d12d896ae6da3d3563220cae846ef910413c3bc6a3243045229.pdf', 'other', 'ingested', '{"date": "2009", "description": "This master''s thesis examines the informational content and framing of 55 circumcision informational handouts targeted at expectant parents, focusing on the degree and manner in which the alternative of not circumcising is presented. Drawing upon informed consent doctrine and Robert Entman''s framing theory, the author evaluates handouts primarily from North American medical and health organizations alongside comparison materials from Australia, New Zealand, and advocacy groups. The analysis reveals that North American materials consistently provide inadequate, biased, or omitted information regarding the anatomy, protective and sexual functions, development, hygiene, and conservative care of the intact penis, largely framing circumcision as the normative standard while problematizing the alternative.\n\nThe author argues that because neonatal circumcision is an elective, non-therapeutic procedure decided by proxy consent, valid informed consent ethically demands a comprehensive and balanced disclosure of alternatives. To remedy the current deficiencies and subtle informational manipulation present in parent education materials, the study proposes an informational framework centered around four key dimensions: demystifying, normalizing, giving value to the intact foreskin, and offering appropriate parental support.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Gillian E. Longley", "Barbara J. Walkosz", "Virginia S. Fink", "Mark Yarborough", "Robert Entman", "Amos Tversky", "Daniel Kahneman"], "organizations": ["University of Colorado Denver", "American Academy of Pediatrics", "American Medical Association", "Canadian Paediatric Society", "British Medical Association", "Royal Australian College of Physicians"], "themes": ["Informed Consent", "Neonatal Circumcision", "Framing Theory", "Parental Education", "Foreskin Anatomy and Function", "Pediatric Proxy Consent", "Bioethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e2ee556787ef8cc65216150ff1d90280d4100eda1d89fdb499b5782a8d7886ab', 'Adler-CDC-recom-Int J Ch Rts-Draft-Spring-2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e2ee556787ef8cc65216150ff1d90280d4100eda1d89fdb499b5782a8d7886ab.pdf', 'other', 'ingested', '{"date": "2016", "description": "This article presents a comprehensive critique of the Centers for Disease Control and Prevention''s (CDC) draft recommendations on male circumcision, arguing that they are medically unfounded, ethically impermissible, legally invalid, and procedurally flawed. Author Peter W. Adler contends that the CDC significantly overstates the preventive health benefits of circumcision\u2014such as reductions in HIV transmission\u2014while failing to acknowledge the true complication rates, loss of healthy functional tissue, adverse effects on sexual sensitivity, and potential psychological harm. Furthermore, the article argues that recommending Medicaid coverage violates federal and state laws requiring medical necessity, and advising parents to consider non-medical factors such as aesthetic or religious preferences infringes upon the child''s rights to bodily integrity, equal protection, and future religious autonomy.\n\nThe author also highlights severe procedural violations under federal administrative standards for Highly Influential Scientific Assessments, including an unlawfully shortened public comment window, failure to address critical peer review from domestic and international medical bodies, undisclosed biases, and refusal to hold public hearings. Adler concludes that the CDC must withdraw the proposed recommendations and adopt the prevailing international consensus, which deters non-therapeutic genital surgery on healthy minors and respects patient autonomy.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Peter W. Adler", "Robert S. Van Howe", "J. Steven Svoboda"], "organizations": ["Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Attorneys For the Rights of the Child", "Royal Dutch Medical Association", "Doctors Opposing Circumcision", "U.S. Department of Health and Human Services", "Medicaid"], "themes": ["Male Circumcision", "Children''s Rights and Bodily Integrity", "Medical Ethics and Informed Consent", "Medicaid Funding and Medical Necessity", "Federal Administrative Procedure"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f775577ba074cc87d90dffd05c48b1eb2957d6b5b9da70a09883204afb98b984', 'AJB Commentary Feb 2015 (v 2) - Alex Myers-2.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f775577ba074cc87d90dffd05c48b1eb2957d6b5b9da70a09883204afb98b984.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This academic commentary argues that neonatal male circumcision (NMC) violates modern ethical standards regarding bodily integrity and consent. Using a thought experiment involving a hypothetical procedure that permanently alters an infant''s tongue to prevent sugar-related diseases, author Alex Myers illustrates that society would readily reject non-consensual modifications on healthy children even when significant lifelong medical benefits are claimed. Myers contends that NMC is far more invasive, causes substantial pain and alteration of function, and provides only minimal absolute risk reductions that fail to meet the burden of proof required to justify non-therapeutic surgery on infants.\n\nMyers further criticizes the defense of circumcision based on cultural tradition and religion, arguing that tradition cannot justify harmful or rights-violating practices. He demonstrates that relying on religious grounds could logically force the tolerance of female genital cutting under similar theological arguments in Islamic jurisprudence. Finally, Myers posits that proponents insist on infant circumcision primarily to ensure the perpetuation of the practice, as few informed adults would voluntarily choose to undergo it later in life.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Alex Myers", "A. J. Jacobs", "K. S. Arora", "Joseph Mazor"], "organizations": ["Hebrew University of Jerusalem", "American Academy of Pediatrics", "World Health Organization"], "themes": ["Bioethics", "Neonatal Male Circumcision", "Bodily Integrity", "Informed Consent", "Religious Tradition vs. Human Rights", "Pediatric Medical Ethics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8a8086cdd9cb775a8619aecd6e4d1a59db13ef942ae50dd8ebd2efde0a02c8fc', 'Circ and human rights AJOB final.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8a8086cdd9cb775a8619aecd6e4d1a59db13ef942ae50dd8ebd2efde0a02c8fc.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This commentary by Brian D. Earp critically assesses arguments presented by Jacobs and Arora concerning the impact of infant male circumcision on sexuality and ethics. Earp contends that Jacobs and Arora inappropriately rely on adult circumcision studies to infer outcomes for neonates, while overlooking methodological weaknesses, the loss of densely innervated erogenous tissue, and the subjective nature of sexual experience. He notes that the existence of foreskin restoration communities demonstrates that many circumcised men experience genuine resentment and perceived harm from involuntary childhood circumcision.\n\nEarp also examines circumcision from a gendered and human rights perspective, refuting claims that circumcision critics selectively apply rights rhetoric. He highlights consistent ethical opposition to non-therapeutic, medically unnecessary genital modifications across all sexes\u2014including intersex surgeries and female genital cutting. Earp argues that because altering healthy genital tissue carries unique psychosexual significance and uncertain future evaluations by the individual, such irreversible procedures should be deferred until a person is mature enough to provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian D. Earp", "Allan Jacobs", "Kavita Arora", "Morten Frisch", "J. Steven Svoboda", "Robert Darby"], "organizations": ["University of Oxford", "American Journal of Bioethics", "World Health Organization", "Centers for Disease Control and Prevention"], "themes": ["Infant male circumcision", "Bioethics", "Sexual function and anatomy", "Informed consent", "Genital autonomy", "Bodily integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1803a549a5c8438c681525c98d6e57d7e22039f8714b910937cef6090cde8292', 'JME Darby.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1803a549a5c8438c681525c98d6e57d7e22039f8714b910937cef6090cde8292.pdf', 'medical_journal', 'ingested', '{"date": "2013-01-30", "description": "This academic paper examines whether the principle of ''the child''s right to an open future''\u2014originally formulated by legal philosopher Joel Feinberg and expanded by bioethicist Dena Davis\u2014applies to non-therapeutic male circumcision. The principle posits that children possess ''rights in trust'' that adults must protect and not permanently foreclose before maturity, leaving children maximal latitude for exercising personal life choices in adulthood. Drawing analogies to debates surrounding parents intentionally selecting for deafness in offspring, the author explores limits on parental authority, bodily integrity, and religious socialization.\n\nThe author argues that routine or culturally motivated circumcision irreversibly alters normal healthy anatomy, reduces sensory function, and permanently removes the child''s future choice to retain an intact body or select their own religious affiliation. Relying on substituted judgment and the harm principle, the paper concludes that non-therapeutic infant circumcision violates the child''s right to an open future, and such irreversible bodily modifications should be deferred until the individual reaches the age of majority and can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Robert J L Darby", "Joel Feinberg", "Dena Davis", "John Locke", "James Dwyer", "John Eekelaar"], "organizations": ["BMJ Publishing Group", "Royal Dutch Medical Association", "Australasian Association of Paediatric Surgeons", "Cologne District Court", "US Supreme Court"], "themes": ["Bioethics", "Children''s Rights", "Right to an Open Future", "Non-Therapeutic Circumcision", "Bodily Integrity", "Parental Authority", "Religious Freedom"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ba036f84808c0400ed5203e120e17b3fa83956d8bbd29057de62d1e914dd3495', 'Nurs Ethics-2013-Antinuk.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ba036f84808c0400ed5203e120e17b3fa83956d8bbd29057de62d1e914dd3495.pdf', 'medical_journal', 'ingested', '{"date": "2013", "description": "This academic paper examines forced nontherapeutic genital cutting (FNGC)\u2014specifically routine infant male circumcision and cosmetic intersex child surgeries\u2014through the lens of feminist theory and nursing ethics. The author argues that while female genital cutting has been rightfully criminalized and recognized as a human rights violation, male and intersex genital cutting continue to be legitimized in North America due to cultural ''circumcisionism'' and financial incentives for medical practitioners. Emphasizing that bodily integrity and autonomy must be protected without gender discrimination, the article contends that nurses have a distinct ethical duty grounded in social justice to challenge these practices and advocate for universal legal protections for all children.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kira Antinuk", "David Reimer", "Lewis A. Sayre", "Neil Pollock", "Paul Tinari", "Shelley Wright-Estevam"], "organizations": ["University of Victoria", "Canadian Paediatric Society", "American Medical Association", "Intersex Society of North America", "College of Physicians and Surgeons of British Columbia", "College of Physicians and Surgeons of Saskatchewan"], "themes": ["Forced Nontherapeutic Genital Cutting (FNGC)", "Male Infant Circumcision", "Intersex Rights", "Feminist Theory", "Nursing Ethics", "Social Justice", "Bodily Integrity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1574c073d64a2ea5299725355e1cccf2425ca9679f90419f430b9939a56408cc', 'Pennasilico Immunogenicity Foreskin Bioengineering 2025 .pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1574c073d64a2ea5299725355e1cccf2425ca9679f90419f430b9939a56408cc.pdf', 'medical_journal', 'ingested', '{"date": "2025-10-31", "description": "This preclinical study evaluates the in vivo biocompatibility, immunogenicity, and tissue integration of a decellularized extracellular matrix (dECM) scaffold derived from human donor foreskin. Twenty-six male Wistar rats received subcutaneous implants of the scaffold and were observed across two time horizons: a 5-day follow-up (Group B) and a 30-day follow-up (Group A). Clinical, histological, and immunohistochemical assessments monitored inflammatory cell infiltrates, macrophage polarization, neo-angiogenesis, and fibroblastic recellularization.\n\nThe findings demonstrated that the dECM scaffold elicited only mild acute inflammatory reactions without evidence of necrosis, cavity formation, or adverse foreign body encapsulation. By day 30, implants exhibited significant neovascularization and massive cellular repopulation by host fibroblasts compared to day 5. These results indicate that the physical and enzymatic decellularization process successfully minimizes antigenic components while maintaining extracellular architecture, supporting the scaffold''s potential utility in human foreskin reconstructive surgery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Luca Pennasilico", "Margherita Galosi", "Lucia Biagini", "Valentina Riccio", "Caterina Di Bella", "Federica Serino", "Sara Sassaroli", "Felice Ciabocco", "Elena Bondioli", "Giacomo Rossi", "Vincenzo Aiello", "Andrea Pratesi", "Angela Palumbo Piccionello", "Christian Demitri"], "organizations": ["MDPI", "University of Camerino", "Futuravet", "University of Rome Tor Vergata", "Emilia Romagna Regional Skin Bank and Burn Centre Bufalini Hospital", "AUSL Romagna", "Foregen Onlus Association", "Italian Ministry of Health"], "themes": ["Tissue Engineering", "Regenerative Medicine", "Decellularized Extracellular Matrix (dECM)", "Foreskin Reconstruction", "Biocompatibility", "Immunogenicity", "Neovascularization", "Macrophage Polarization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('f20a3423a21c1d0d9357a3d78cbc62755e43c1640392c61d158dbf735a520fd9', 'Ahmady DoubleStandards EuroJHumSocSci 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/f20a3423a21c1d0d9357a3d78cbc62755e43c1640392c61d158dbf735a520fd9.pdf', 'medical_journal', 'ingested', '{"date": "2025-10-13", "description": "This article conducts a comparative ethical and human rights analysis between female genital mutilation (FGM) and male genital mutilation (MGM), confronting the international double standard that condemns FGM as a human rights violation while widely tolerating or endorsing MGM. The author demonstrates that both practices share profound sociocultural parallels, functioning as non-consensual mechanisms of patriarchal authority, social conformity, and gender identity construction inflicted on defenseless children without medical necessity.\n\nThe paper argues that defending MGM through cultural relativism, religious tradition, or contested medical prophylactic claims violates core principles of bodily integrity, autonomy, and non-maleficence. It also highlights how medicalization and commercial incentives within healthcare systems perpetuate the practice. The author calls for the dissolution of segregated ethical discourses and urges the adoption of a consistent, gender-neutral human rights framework that protects all children from non-therapeutic genital alterations until they reach the age of majority and can provide informed consent.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Kameel Ahmady", "Sami Aldeeb Abu-Sahlieh", "Hanny Lightfoot-Klein", "Nawal El Saadawi", "Mahmoud Amiri-Moghadam", "Akbar Karami", "Brian D. Earp"], "organizations": ["University of Kent", "World Health Organization", "UNAIDS", "UNICEF", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "United Nations", "Brussels Collaboration on Bodily Integrity"], "themes": ["Male Genital Mutilation (MGM)", "Female Genital Mutilation (FGM)", "Bodily Integrity", "Human Rights", "Medical Ethics and Informed Consent", "Gender Double Standards", "Patriarchy and Social Control"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('26fa126310ed4d572e304656f740471f0aef950b574c12f5eabb3f573f39d7dd', 'Demo Bitte lesen (Deutsch).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/26fa126310ed4d572e304656f740471f0aef950b574c12f5eabb3f573f39d7dd.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document is a getting-started guide and informational leaflet for the 30-day free trial of FileMaker Pro 11 database software. It guides users through available resources, such as product documentation, video tutorials, overview pages, and pre-built starter templates for managing contacts, projects, and invoices.\n\nAdditionally, the text outlines the steps required to purchase the full version and uninstall the trial software on both Windows and Mac OS systems, while reassuring users that databases created during the trial period can be retained and used in the full release.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Database Management", "Software Trial", "FileMaker Pro 11", "Installation and Setup", "Data Organization"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7ce23fafe347c40d73b567ab042350dda255527787079142e5f3fbefac911e87', 'Demo Viktigt (Svenska).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7ce23fafe347c40d73b567ab042350dda255527787079142e5f3fbefac911e87.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document introduces FileMaker Pro 11, detailing its features as a database software for Mac, Windows, and web platforms available as a 30-day free trial. It provides guidance on getting started, accessing resources and documentation, uninstalling the trial version, and purchasing the full version.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Database Management", "Software Evaluation", "FileMaker Pro 11", "Product Documentation", "Software Installation"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('17a09b56090817fbb85760a3019b2dcba507fbd18e883e34f20a4a12057bc675', 'Trial Lees mij (Nederlands).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/17a09b56090817fbb85760a3019b2dcba507fbd18e883e34f20a4a12057bc675.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document serves as an informational welcome and setup guide for the 30-day free trial of FileMaker Pro 11 database software for Windows, Mac, and the web. It details resources available to users during the evaluation period, including user documentation, the Resource Center with video tutorials, overview pages, and 30 starter solution templates for managing contacts, projects, and invoices.\n\nIt also outlines step-by-step instructions on how to purchase the full software version, uninstall the trial on both Windows and Mac operating systems without losing created databases, and install the purchased version. The document concludes with customer contact information and legal/copyright disclaimers from FileMaker, Inc.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Database Software", "Software Evaluation", "Product Guide", "Installation and Setup", "Information Management"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('cc2c867317b6c5759b8fe392806801cb5e0432be3b3dd710882b5335123f6b31', 'Trial Leggimi (Italiano).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/cc2c867317b6c5759b8fe392806801cb5e0432be3b3dd710882b5335123f6b31.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document serves as a welcome guide for users testing the 30-day free trial of FileMaker Pro 11, a database management software application for Mac, Windows, and the Web. It outlines essential onboarding resources, including official product documentation, the Information Center with video demos, online feature overviews, and over 30 pre-built starter solutions for tasks like contact and inventory tracking.\n\nAdditionally, the document provides step-by-step instructions for purchasing the full software version and properly uninstalling the trial edition on both Windows and Mac OS while preserving user-created databases. It concludes with customer support contact channels and legal terms regarding trial usage and licensing.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Database Management", "Software Evaluation", "Installation and Deployment", "Software Licensing", "Customer Support"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('33670ff40ff51d6283103c6ae75962a1e077965aef152b024a2e800d63ee2e8d', 'Trial Lisez Moi (Français).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/33670ff40ff51d6283103c6ae75962a1e077965aef152b024a2e800d63ee2e8d.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document provides an introduction and user guide for the 30-day trial version of FileMaker Pro 11, a cross-platform database management software designed for Windows, Mac, and the Web. It outlines resources to help users explore the application, including product documentation, the Quick Start screen, demo tutorials, and pre-built starter solutions for tasks such as invoicing, inventory tracking, and contact management.\n\nAdditionally, the document provides instructions on how to purchase the full software edition and uninstall the trial version on both Windows and Mac OS without losing user-created databases. It concludes with licensing terms, contact details, and technical support disclaimers regarding the evaluation period.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Database Management Software", "Trial Software", "Product Guide", "Software Installation and Upgrades"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b7dab2968dc68366f38472a5a83f83c2fdd6496b92135ba9933d6446adc8fc5c', 'Trial Léame (Español).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b7dab2968dc68366f38472a5a83f83c2fdd6496b92135ba9933d6446adc8fc5c.pdf', 'other', 'ingested', '{"date": "2010", "description": "Este documento ofrece una gu\u00eda de bienvenida e introducci\u00f3n a la versi\u00f3n de prueba de 30 d\u00edas de FileMaker Pro 11, un software de gesti\u00f3n de bases de datos para Mac, Windows y la Web. Explica c\u00f3mo acceder a la documentaci\u00f3n del producto, a los recursos de aprendizaje y a las plantillas predise\u00f1adas, adem\u00e1s de detallar el proceso para desinstalar la versi\u00f3n de prueba tras adquirir la licencia completa.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Software de base de datos", "Versi\u00f3n de prueba de 30 d\u00edas", "Instalaci\u00f3n y desinstalaci\u00f3n de software", "Soporte y recursos t\u00e9cnicos"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4dcb9322eb236b487d538ea733778a9aacc477dc9c8d88bc6876aa442305849f', 'FileMaker Pro 11.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4dcb9322eb236b487d538ea733778a9aacc477dc9c8d88bc6876aa442305849f.pdf', 'unknown', 'ingested', '{"date": "Unknown", "description": "", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "error": "Failed to generate"}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('5c0ffc227af9ef07447e96615e02a1389f6110c23b1305102e6c7ba205e09719', 'Readme.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/5c0ffc227af9ef07447e96615e02a1389f6110c23b1305102e6c7ba205e09719.pdf', 'other', 'ingested', '{"date": "2010", "description": "This document provides multilingual reference instructions for users needing to install and configure the ODBC driver for FileMaker. It directs users of FileMaker Pro and FileMaker Server to consult the official FileMaker ODBC and JDBC Guide, accessible via the applications'' Help menus or by visiting the FileMaker documentation website.\n\nThe instructional notice is translated across multiple languages, including English, French, German, Japanese, Italian, Swedish, Spanish, and Dutch, ensuring broad international accessibility for database administrators and software users.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": [], "organizations": ["FileMaker, Inc."], "themes": ["Software Documentation", "ODBC Driver Configuration", "Database Management", "Technical Support"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('eb55f3a4a2a7bdc8bcdd4e02c864d9f71b073fabbf1d762d9b64001601828582', 'Brown Varieties Circ Kenya STD 2001.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/eb55f3a4a2a7bdc8bcdd4e02c864d9f71b073fabbf1d762d9b64001601828582.pdf', 'medical_journal', 'ingested', '{"date": "2001-10", "description": "This study examines male circumcision practices in the Chogoria region of Kenya, identifying three distinct surgical techniques\u2014one hospital-based (Type A) and two traditional Meru practices (Types B and C)\u2014that differ significantly in the amount and layers of foreskin removed or altered. The findings indicate that relying solely on self-reported circumcision status is insufficient for epidemiological studies, as different surgical methods leave varying amounts of foreskin and distinct physical outcomes.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Judith E. Brown", "Kenneth D. Micheni", "Elizabeth M. J. Grant", "James M. Mwenda", "Francis M. Muthiri", "Angus R. Grant", "James M Mungiriria", "Andrew Koske"], "organizations": ["Chogoria Hospital", "Aga Khan University", "Kenya Medical Research Institute", "Overseas Medical Fund of Charlottesville, Virginia"], "themes": ["Male Circumcision", "HIV Transmission and Prevention", "Surgical and Traditional Procedures", "Meru Cultural Practices", "Epidemiological Methodology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c45a7b10a911608128fbd5719d2ae16044edcf540c00ce5238d318a903d84d9e', 'Forced Crcumcision & Politics Foreskin Kenya AfrStud 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c45a7b10a911608128fbd5719d2ae16044edcf540c00ce5238d318a903d84d9e.pdf', 'other', 'ingested', '{"date": "2018", "description": "This article examines the social, cultural, and political dynamics surrounding forced male circumcision and the ''politics of foreskin'' in Kenya. The author analyzes how forcible circumcisions, often perceived internationally as severe human rights abuses and male gender violence, possess an enduring, recognized social legitimacy within local contexts. Focusing largely on ethnically mixed towns in western Kenya such as Moi''s Bridge and Bungoma, the paper demonstrates how forced circumcision operates as an extra-judicial mechanism for asserting generational discipline, negotiating intermarriage, and assimilating ''stranger'' husbands and wayward men into the boundaries of moral ethnicity.\n\nFurthermore, the article argues that male circumcision has evolved into a hyper-masculinized political idiom deployed by politicians and communities to demarcate full citizenship and suitability for national leadership. Lamont illustrates how this bodily politics intersects with broader state ambivalence, emerging voluntary medical male circumcision (VMMC) public health campaigns, and the constitutional framework of Kenya''s 2010 Constitution, which struggles to reconcile individual bodily integrity rights with entrenched cultural claims and ethnopolitical tribalism.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Mark Lamont", "James Asega", "Asha Nalongo", "Dan Odula", "Mathew Ndanyi", "Suzette Heald", "John Lonsdale", "Paul Ocobock", "Wachira Kiago"], "organizations": ["The Open University", "British Institute in Eastern Africa", "National Cohesion and Integration Commission", "Kikuyu Council of Elders", "Kenya Television Network", "World Health Organization"], "themes": ["Forced Male Circumcision", "Politics of Foreskin", "Moral Ethnicity", "Masculinity and Gender-Based Violence", "Human Rights vs Cultural Rights", "Intermarriage and Migration", "State Formation and Extra-Judicial Violence"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bf81bcf3c34d40bd76ffdae450e8c218b01669bea6b364f9334dab3000302fbb', 'Gilbertson VMMC Kenya Unintended PLoS One 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bf81bcf3c34d40bd76ffdae450e8c218b01669bea6b364f9334dab3000302fbb.pdf', 'medical_journal', 'ingested', '{"date": "2019-11-04", "description": "This qualitative research study investigates the unintended consequences of meeting donor-driven service-delivery targets within voluntary medical male circumcision (VMMC) programs for HIV prevention among adolescents in Kenya. Conducting interviews with 29 key stakeholders and field observations across clinics and community mobilization events, the researchers evaluated how programmatic pressure to fulfill annual quotas set by PEPFAR affects clinical standards and ethical conduct.\n\nThe findings reveal that tying funding and staff remuneration to numeric quotas produces distinct challenges, particularly during seasonal surges aligned with school holidays. Clinicians and mobilizers reported compromised quality of care\u2014such as skipping preoperative checks and rushing surgical procedures\u2014alongside extensive clinic wait times, recruitment of underage boys under age ten, and misleading or coercive mobilization strategies that rely on social pressure and material inducements. The authors conclude that public health programs must balance uptake goals with ethical, human rights-centered implementation.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Adam Gilbertson", "Barrack Ongili", "Frederick S. Odongo", "Denise D. Hallfors", "Stuart Rennie", "Daniel Kwaro", "Winnie K. Luseno"], "organizations": ["Pacific Institute for Research and Evaluation", "Kenya Medical Research Institute", "University of North Carolina at Chapel Hill", "President''s Emergency Plan for AIDS Relief", "United States Agency for International Development", "Joint United Nations Programme on HIV/AIDS", "National Institute of Mental Health"], "themes": ["Voluntary Medical Male Circumcision", "HIV Prevention", "Public Health Quotas and Targets", "Adolescent Healthcare Ethics", "Quality of Clinical Care", "Informed Consent and Coercion"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b1e2c0b661a9e7b2c02e21216900dee8f4e4c8e23f08011c36974975e64ff4cd', 'Nyaundi Circ Rights Kenyan Boy AfrHumRtJ 2005.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b1e2c0b661a9e7b2c02e21216900dee8f4e4c8e23f08011c36974975e64ff4cd.pdf', 'legal_document', 'ingested', '{"date": "2005", "description": "This article examines the cultural practice of male circumcision in Kenya, arguing that performing non-therapeutic circumcision on non-consenting boys under the age of 18 constitutes a violation of their fundamental human rights. The author asserts that the practice infringes upon the right to bodily integrity, privacy, health, protection from cruel and inhuman treatment, and non-discrimination as enshrined in international and regional instruments, including the UN Convention on the Rights of the Child, the African Charter on the Rights and Welfare of the Child, and Kenya''s Children''s Act 2001.\n\nThe paper draws parallels to female circumcision, highlighting that cultural male circumcision carries severe physical risks\u2014such as fatal hemorrhaging, infections, deformity, and psychological trauma\u2014especially when conducted in unhygienic traditional settings. Emphasizing that modern children''s rights frameworks prioritize the best interests of the child over harmful cultural rites, the article concludes that the Kenyan government is legally obligated to halt the facilitation of non-consensual male circumcision and actively protect the boy-child from non-medical bodily alteration.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Legal Document", "key_people": ["Patricia Mande Nyaundi", "Samson Ombongi", "Walter Mwanda"], "organizations": ["Child Legal Aid Centre", "High Court of Kenya", "United Nations", "Organization of African Unity", "Kenya Haemophilia Association"], "themes": ["Children''s Rights", "Male Circumcision", "Bodily Integrity", "Customary Rites vs. Human Rights", "Public Health and Medical Complications", "Kenyan Children''s Act"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('bdf4162f3af1a9287fbccea86e18418cef3d9004095babc7f570867a10bd6875', 'Roloff-Bailey Acceptability MC Kenya PlosOne 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/bdf4162f3af1a9287fbccea86e18418cef3d9004095babc7f570867a10bd6875.pdf', 'medical_journal', 'ingested', '{"date": "2011-05-16", "description": "This study investigates the real-world facilitators and barriers influencing the uptake of voluntary medical male circumcision (VMMC) among uncircumcised men in Nyanza Province, Kenya, one year following the launch of the national circumcision program. Through 12 focus group discussions involving 121 men aged 18 to 40, researchers evaluated non-hypothetical perceptions in an area historically defined by low circumcision rates and high HIV prevalence.\n\nThe findings indicate that key facilitators for circumcision uptake include improved hygiene, social pressure, perceived protection against HIV and sexually transmitted infections, and enhanced sexual performance and satisfaction. Conversely, the foremost barriers cited were loss of income due to time away from work, traditional cultural and religious norms, fear of surgical adverse events, and the mandatory post-operative abstinence period. To improve program uptake, the authors recommend targeted communication strategies to dispel misconceptions about recovery and complications, as well as actively engaging religious leaders, women''s groups, and peer educators.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Amy Herman-Roloff", "Nixon Otieno", "Kawango Agot", "Jeckoniah Ndinya-Achola", "Robert C. Bailey", "Raila Odinga", "Andrew D. Badley"], "organizations": ["University of Illinois at Chicago", "Nyanza Reproductive Health Society", "Impact Research and Development Organization", "University of Nairobi", "World Health Organization", "UNAIDS", "Government of Kenya", "Bill and Melinda Gates Foundation", "FHI", "EngenderHealth", "Kenyatta National Hospital"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV/AIDS Prevention", "Public Health Programs", "Cultural and Religious Barriers", "Sexual and Reproductive Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b0145fb8e4fd3f78d93c965512a8964800ba698d26d6f5b242c094b7ed8c3bba', 'Morris Biomedical Imperative BioEssays 2007.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b0145fb8e4fd3f78d93c965512a8964800ba698d26d6f5b242c094b7ed8c3bba.pdf', 'medical_journal', 'ingested', '{"date": "2007", "description": "This article argues that male circumcision serves as a crucial surgical prophylactic\u2014analogous to a vaccine\u2014against numerous infectious diseases, malignancies, and dermatological conditions across a lifetime. Drawing on biological mechanisms and extensive epidemiological data, the author asserts that circumcision significantly reduces the risk of heterosexually acquired HIV, human papillomavirus (HPV), syphilis, chancroid, urinary tract infections, and penile and prostate cancers in men, while also offering substantial indirect protection against cervical cancer and chlamydia in female partners.\n\nContending that the medical benefits vastly outweigh the minor, infrequent risks associated with the procedure, the paper advocates for routine infant circumcision under local anesthesia as an optimal, safe, and cost-effective public health measure. It strongly criticizes medical professional opposition and anti-circumcision narratives, characterizing them as rooted in prejudice and misinformation rather than evidence-based medicine.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Terry Russell", "Sam Kunin", "Scott McCoombe", "Roger Short"], "organizations": ["The University of Sydney", "World Health Organization", "UNAIDS", "Centers for Disease Control"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Sexually Transmitted Infections (STIs)", "Penile and Cervical Cancer", "Pediatric Health", "Preventive Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('4ed21f97c9137bfa8ad27bc1641ef5a496c5fc1fa7baf3fa47345bf92c173870', 'Morris contra Bossio JSM 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/4ed21f97c9137bfa8ad27bc1641ef5a496c5fc1fa7baf3fa47345bf92c173870.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "In this commentary, authors Brian J. Morris and John N. Krieger critique a review by Bossio et al. that questioned the American Academy of Pediatrics (AAP) policy favoring neonatal male circumcision. Morris and Krieger argue that the review suffered from serious methodological defects, including the omission of high-quality meta-analyses and randomized controlled trials that prove male circumcision reduces risks of urinary tract infections, HIV, HPV, and certain cancers without impairing sexual function or satisfaction. They assert that extensive evidence, along with overwhelming favorable risk\u2013benefit and cost\u2013benefit analyses, strongly supports policies that facilitate parental education and access to safe neonatal male circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "John N. Krieger", "J. A. Bossio", "Robert S. Van Howe"], "organizations": ["American Academy of Pediatrics", "Centers for Disease Control and Prevention", "University of Sydney", "University of Washington School of Medicine", "International Society for Sexual Medicine", "Johns Hopkins"], "themes": ["Neonatal Male Circumcision", "Public Health and Pediatric Policy", "Sexually Transmitted Infections", "Sexual Function and Health", "Risk\u2013Benefit and Cost\u2013Benefit Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('e38141415cbdeba1653686b9c81502d2df3ec9eabdb1ed42cc430b043a9579ee', 'Morris Critical Eval Hammond&Carmack ASM 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/e38141415cbdeba1653686b9c81502d2df3ec9eabdb1ed42cc430b043a9579ee.pdf', 'medical_journal', 'ingested', '{"date": "2019-09-17", "description": "This article presents a comprehensive critical evaluation of a widely cited online survey by Timothy Hammond and Adrienne Carmack, which claimed that neonatal male circumcision (NMC) results in long-term physical, sexual, and psychological harm. The authors argue that Hammond and Carmack''s study suffers from fatal methodological flaws, including severe recruitment and selection bias, loaded questioning, and reliance on unverified self-reports from an online convenience sample largely drawn from anti-circumcision networks and men seeking foreskin restoration.\n\nContrasting the survey''s claims with high-quality medical evidence\u2014including randomized controlled trials, systematic reviews, and policy positions from major organizations like the CDC and the American Academy of Pediatrics\u2014the authors demonstrate that male circumcision does not adversely affect penile sensitivity, sexual pleasure, or mental health. They highlight that circumcision provides significant lifetime public health protections against urinary tract infections, STIs (including HIV), and genital cancers, concluding that anti-circumcision rhetoric grounded in flawed surveys promotes misinformation and inflicts unnecessary psychological distress on vulnerable men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Stefan A. Bailis", "Stephen Moreton", "Brian J. Morris", "Timothy Hammond", "Adrienne Carmack", "Morten Frisch", "Jennifer A. Bossio"], "organizations": ["Cornerstone Therapy & Recovery Center", "CircFacts", "University of Sydney", "Centers for Disease Control and Prevention", "American Academy of Pediatrics", "World Health Organization", "UNAIDS", "Attorneys for the Rights of the Child", "National Organization to Halt the Abuse and Routine Mutilation of Males"], "themes": ["Neonatal Male Circumcision", "Sexual Function and Penile Sensitivity", "Critique of Anti-Circumcision Activism", "Evidence-Based Medicine", "Public Health and Disease Prevention", "Bioethics and Children''s Health Rights"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('b234976bc635ac40ce41067e9adc432d7b710b92990e5c2325eb68ee3659aaf8', 'Morris Estimate prevalence male circ PopHlthMetrics 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/b234976bc635ac40ce41067e9adc432d7b710b92990e5c2325eb68ee3659aaf8.pdf', 'medical_journal', 'ingested', '{"date": "2016", "description": "This review paper provides comprehensive country-specific and global estimates of male circumcision (MC) prevalence across 237 countries and territories. Using data retrieved from national health surveys (such as DHS, AIS, and BSS), peer-reviewed publications, and demographic projections based on religious (primarily Muslim and Jewish) and cultural practices, the authors calculate that between 36.7% and 38.7% of men worldwide are circumcised. Approximately 62% of circumcisions globally are performed for religious reasons, with the remainder conducted for cultural traditions, medical indications, personal preference, or public health interventions.\n\nThe authors emphasize the epidemiological importance of these findings given the established medical benefits of male circumcision, most notably its substantial reduction of heterosexual HIV transmission risk. The study underscores how up-to-date baseline prevalence data can guide targeted public health initiatives, resource allocation, and voluntary medical male circumcision (VMMC) scale-up programs in disease-burdened regions such as sub-Saharan Africa.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J Morris", "Richard G Wamai", "Esther B Henebeng", "Aaron AR Tobian", "Jeffrey D Klausner", "Joya Banerjee", "Catherine A Hankins"], "organizations": ["World Health Organization", "UNAIDS", "Centers for Disease Control and Prevention", "American Academy of Pediatrics", "Northeastern University", "University of Sydney", "Johns Hopkins University"], "themes": ["Male Circumcision", "HIV Prevention", "Global Health Epidemiology", "Public Health Policy", "Religious and Cultural Practices"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('184091cb6a7cf5f19ad607302ba0e5ef2bfae868987dc19f5475bd7ccf053169', 'Morris Expertise and Ideology WorldJAIDS 2017.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/184091cb6a7cf5f19ad607302ba0e5ef2bfae868987dc19f5475bd7ccf053169.pdf', 'medical_journal', 'ingested', '{"date": "2017-08-11", "description": "This academic paper critically evaluates meta-regression analyses and arguments published by Robert S. Van Howe opposing male circumcision (MC). The authors assert that Van Howe''s analyses rely on flawed methodology, misrepresentation of data, and ideological bias to contest the protective efficacy of male circumcision against HIV infection. By performing their own meta-regression across global and African datasets, the authors demonstrate that male circumcision significantly reduces the risk of heterosexual HIV transmission both inside and outside Africa, while providing additional long-term health benefits.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Gia Barboza", "Richard G. Wamai", "John N. Krieger", "Robert S. Van Howe"], "organizations": ["University of Sydney", "Northeastern University", "University of Washington", "VA Puget Sound Health Care System", "Centers for Disease Control and Prevention", "Intact America", "American Academy of Pediatrics"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Meta-Regression Analysis", "Public Health Policy", "Epidemiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0a345c1692969f5a453627f665a8faed65cbfdf87d02355f85b87c97afac5e83', 'Morris Primary Preventive HIV GlobPubHealth 2018.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0a345c1692969f5a453627f665a8faed65cbfdf87d02355f85b87c97afac5e83.pdf', 'medical_journal', 'ingested', '{"date": "2016-04-04", "description": "This academic paper critically evaluates a meta-regression analysis by Robert Van Howe that disputed the role of male circumcision as a primary preventive measure against HIV infection. The authors argue that Van Howe''s conclusions are invalid due to severe methodological flaws, including inaccurate male circumcision prevalence figures, the misuse of crude rather than adjusted odds ratios, an inappropriate application of meta-regression techniques, and the reliance on unpublished, non-replicable data.\n\nThe authors reaffirm the consensus established by randomized controlled trials and previous systematic reviews, demonstrating that male circumcision significantly reduces the risk of heterosexually acquired HIV. They emphasize that circumcision remains a highly effective, lasting, and cost-effective public health intervention against HIV transmission, warning against flawed statistical analyses that misinform prevention policies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Gia Barboza", "Richard G. Wamai", "John N. Krieger", "Robert S. Van Howe"], "organizations": ["University of Sydney", "Northeastern University", "University of Washington School of Medicine", "VA Puget Sound Health Care System", "Centers for Disease Control and Prevention", "USAID", "UNICEF"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Epidemiology and Meta-Regression", "Statistical Methodology and Bias", "Global Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1a3c8f4e0f544da7999fd3a5877ee8dd7d81d8348b1cd422be9f0475637cdcf1', 'Morris Veracity_rhetoric JME 2014.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1a3c8f4e0f544da7999fd3a5877ee8dd7d81d8348b1cd422be9f0475637cdcf1.pdf', 'medical_journal', 'ingested', '{"date": "2013-08-16", "description": "This paper presents a detailed critique of an article by J. Steven Svoboda and Robert S. Van Howe that contested the American Academy of Pediatrics (AAP) 2012 policy statement on infant male circumcision (IMC). The authors argue that Svoboda and Van Howe''s counterarguments are methodologically flawed, relying on selective citation, statistical manipulation, and misinterpretations of epidemiological data while disregarding high-quality evidence and randomized controlled trials.\n\nThe authors defend the AAP''s position that the prophylactic benefits of neonatal male circumcision significantly outweigh the minimal procedural risks. They emphasize that infant male circumcision provides lasting protection against urinary tract infections, penile cancer, and sexually transmitted infections, including oncogenic HPV and HIV. Consequently, the authors conclude that elective newborn circumcision is an ethically valid, medically beneficial, and cost-effective preventive health intervention that should be supported by public health policies and third-party insurance coverage.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J Morris", "Aaron A R Tobian", "Catherine A Hankins", "Jeffrey D Klausner", "Joya Banerjee", "Stefan A Bailis", "Stephen Moses", "Thomas E Wiswell", "J. Steven Svoboda", "Robert S. Van Howe"], "organizations": ["American Academy of Pediatrics", "Centers for Disease Control and Prevention", "American College of Obstetricians and Gynecologists", "Circumcision Foundation of Australia", "Royal Australasian College of Physicians", "Royal Dutch Medical Association", "University of Sydney", "Johns Hopkins University"], "themes": ["Infant Male Circumcision", "Pediatric Health Policy", "Medical Ethics", "Preventive Medicine and Public Health", "Sexually Transmitted Infections", "Risk-Benefit and Cost-Effectiveness Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('853a43559d1c836d2bbb0c597ee2e46952b6fd26c4be055b13531e7a839b3ab9', 'Morris Wodak Evidence Based Stmt OJPM 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/853a43559d1c836d2bbb0c597ee2e46952b6fd26c4be055b13531e7a839b3ab9.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This article provides an evidence-based review and policy statement advocating for routine infant male circumcision in developed countries, with a primary focus on Australia. Drawing upon randomized controlled trials and meta-analyses, the authors assert that circumcision confers substantial protection against urinary tract infections, phimosis, inflammatory conditions, and sexually transmitted infections\u2014including HIV, HPV, and HSV-2\u2014while also reducing cervical cancer risk in female partners and penile cancer risk in men.\n\nThe authors conclude that the medical benefits of infant male circumcision substantially outweigh its low procedural risks (<1%), demonstrating that uncircumcised males face a significant lifetime risk of foreskin-related medical conditions. Comparing the ethics of infant circumcision to routine childhood vaccination, the paper argues that the procedure is most safe, convenient, and cost-effective when performed in infancy under local anesthesia, urging governments and healthcare bodies to improve public education, insurance coverage, and accessibility.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Alex D. Wodak", "Adrian Mindel", "Leslie Schrieber", "Karen A. Duggan", "Anthony Dilley", "Robin J. Willcourt", "Michael Lowy", "David A. Cooper", "Eugenie R. Lumbers", "C. Terry Russell", "Stephen R. Leeder"], "organizations": ["The University of Sydney", "St Vincents Hospital", "Westmead Hospital", "Vectus Biosystems", "Sydney Children\u2019s Hospital", "The Queen Elizabeth Hospital", "University of New South Wales", "University of Notre Dame Sydney", "The Kirby Institute for Infection and Immunity in Society", "University of Newcastle", "Hunter Medical Research Institute", "John Hunter Hospital", "Circumcision Foundation of Australia", "Menzies Centre for Health Policy"], "themes": ["Infant Male Circumcision", "Preventive Medicine and Public Health", "Sexually Transmitted Infections Prevention", "Urinary Tract Infections", "Penile and Cervical Cancer Reduction", "Medical Bioethics and Parental Consent"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('45d126ccd0023a38db728ad93516a4df4f2fa01ab2cccf7796ce781b7512f051', 'Morris-Bates Recommend Ban BMC Pediatrics 2013.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/45d126ccd0023a38db728ad93516a4df4f2fa01ab2cccf7796ce781b7512f051.pdf', 'medical_journal', 'ingested', '{"date": "2013-09-08", "description": "This debate article strongly critiques a report by the Tasmanian Law Reform Institute (TLRI) that recommended banning non-therapeutic infant male circumcision unless parents have distinct religious or ethnic motivations. The authors argue that the TLRI disregarded substantial medical evidence and consensus, notably the 2012 American Academy of Pediatrics (AAP) policy statement, which concluded that the health benefits of newborn male circumcision significantly outweigh its risks in preventing conditions such as urinary tract infections, cervical and penile cancers, and sexually transmitted infections like HIV.\n\nFurthermore, the authors contend that criminalizing parental choice and medical practice over an evidence-based minor surgical procedure sets a dangerous international precedent, violates parental rights, and misinterprets the United Nations Convention on the Rights of the Child. They maintain that prohibiting infant circumcision would lead to unworkable legal scenarios, infringe upon bodily health benefits, and result in long-term negative economic and public health consequences.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Michael J Bates", "John B Ziegler", "Sean E Kennedy", "Adrian Mindel", "Alex D Wodak", "Laurie S Zoloth", "Aaron AR Tobian", "Brian J Morris", "Paul Mason", "Warwick Marshall", "William Patrick Deane"], "organizations": ["Tasmanian Law Reform Institute", "American Academy of Pediatrics", "Royal Australasian College of Physicians", "British Medical Association", "Royal Dutch Medical Association", "United Nations", "Centers for Disease Control and Prevention", "University of Sydney"], "themes": ["Infant Male Circumcision", "Pediatric Health Policy", "Parental Rights and Consent", "Medical Law and Criminal Liability", "Human Rights and Ethics", "Public Health and Cost-Effectiveness"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('96f4d618c06d81e7ee8c0774cdb6716577dbd203dfea031e1ce1cfe9e13a3145', 'Morris-Cox Histological Correlates SexMed 2015.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/96f4d618c06d81e7ee8c0774cdb6716577dbd203dfea031e1ce1cfe9e13a3145.pdf', 'medical_journal', 'ingested', '{"date": "2015", "description": "This systematic review analyzes histological and neuroanatomical literature regarding penile sensory structures to determine whether male circumcision impacts penile sensitivity and sexual pleasure. Evaluating structural findings alongside physiological measurements, the authors demonstrate that Meissner''s corpuscles in the prepuce diminish markedly with age after adolescence and that free nerve endings show no correlation with ejaculatory latency or sexual response. Tactile sensitivity also decreases with sexual arousal, indicating it does not drive sexual sensation, whereas genital corpuscles located primarily in the glans serve as the primary mediators of sexual response.\n\nThe authors conclude that the loss of the prepuce through circumcision has no detrimental effect on sexual function, sensitivity, or satisfaction. Instead, reported increases in sexual sensation post-circumcision are attributed to improved exposure and mechanical access to the genital corpuscles on the glans during intercourse rather than histomorphological alterations or glans keratinization.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Guy Cox", "John N. Krieger", "Brian J. Morris", "Pu (Paul) Xu"], "organizations": ["University of Sydney", "University of Washington", "VA Puget Sound Health Care System", "International Society for Sexual Medicine"], "themes": ["Male Circumcision", "Penile Histology and Anatomy", "Sexual Sensation and Pleasure", "Genital Corpuscles", "Meissner''s Corpuscles", "Neurophysiology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('74494b08500fd59ce77179d08110477d7443351b367fddaa2b8d30e48f64b065', 'Morris-Krieger Contrasting Evidence MC  SexMed 2020.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/74494b08500fd59ce77179d08110477d7443351b367fddaa2b8d30e48f64b065.pdf', 'medical_journal', 'ingested', '{"date": "2020-08-31", "description": "This systematic review analyzes 94 publications\u2014including randomized controlled trials, cohort studies, physiological assessments, and critiques\u2014to evaluate the impact of male circumcision (MC) on sexual function, penile sensation, and sexual pleasure. Evaluating the literature using the Scottish Intercollegiate Guidelines Network (SIGN) criteria, the authors conclude that high- and moderate-quality studies consistently show MC has minimal to no adverse effect on sexual function, sensitivity, satisfaction, or pleasure, regardless of whether circumcision occurs in infancy or adulthood. Some studies even report benefits, such as reduced dyspareunia and lower rates of erectile dysfunction.\n\nIn contrast, the authors argue that studies asserting adverse effects of male circumcision suffer from methodological flaws, lack of scientific rigor, biased sampling, and statistical misinterpretations. Furthermore, neuroanatomical and physiological evidence indicates that primary erogenous sensation is mediated by the glans penis and the underside of the shaft rather than the foreskin, challenging claims that prepuce excision diminishes sexual enjoyment.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "John N. Krieger", "Morten Frisch", "Brian D. Earp", "Jennifer A. Bossio", "Gregory J. Boyle"], "organizations": ["University of Sydney", "University of Washington School of Medicine", "International Society for Sexual Medicine", "Elsevier Inc.", "Scottish Intercollegiate Guidelines Network"], "themes": ["Male Circumcision", "Sexual Function and Dysfunction", "Penile Sensation and Sensitivity", "Sexual Satisfaction and Pleasure", "Systematic Review and Meta-Analysis", "Evidence-Based Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('9f245f82cafbd19a99d1bb3f62d4eb3dfa4edf55cf374bdc2f9b7a31a59e8086', 'Morris-Krieger NTMC PediatricsUK 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/9f245f82cafbd19a99d1bb3f62d4eb3dfa4edf55cf374bdc2f9b7a31a59e8086.pdf', 'medical_journal', 'ingested', '{"date": "2019", "description": "This review evaluates non-therapeutic male circumcision (NTMC), specifically addressing and critiquing the 2019 British Medical Association (BMA) guidance which adopts a restrictive stance on the procedure for minors. The authors present a comprehensive risk-benefit analysis tailored to the UK, arguing that the medical benefits of infant circumcision\u2014including substantial lifetime risk reductions for urinary tract infections, sexually transmitted infections, and genital cancers\u2014exceed procedural risks by approximately 200 to one. They highlight that early infancy is the optimal time for the procedure due to lower costs, minimal complications, and faster healing compared to circumcisions performed later in life.\n\nIn addition to epidemiological and clinical evidence, the article explores legal and ethical considerations, drawing parallels between infant circumcision and routine childhood vaccinations as preventive public health measures. The authors dispute claims regarding diminished sexual function or satisfaction and urge UK medical authorities to align their guidance with major international bodies, such as the American Academy of Pediatrics (AAP) and the US Centers for Disease Control and Prevention (CDC), by supporting access to elective infant circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J Morris", "John N Krieger", "James Munby"], "organizations": ["British Medical Association", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "World Health Organization", "Canadian Paediatric Society", "Danish Medical Association", "Royal Dutch Medical Association", "United Nations"], "themes": ["Non-therapeutic male circumcision", "Pediatric surgery and procedural risks", "Preventive healthcare and public health policy", "Sexually transmitted infections and cancer prophylaxis", "Bioethics and parental decision-making"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('026b4d59d95a6c77375380871eba25f7131662a1135cb32b4f2ee7e810251929', 'Morris-Moreton Crit Eval Argum Oppos JEvidBaseMed 2019.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/026b4d59d95a6c77375380871eba25f7131662a1135cb32b4f2ee7e810251929.pdf', 'medical_journal', 'ingested', '{"date": "2019-09", "description": "This systematic review critically evaluates common arguments and claims made against nontherapeutic male circumcision (MC), especially early infant male circumcision (EIMC). By synthesizing findings from randomized controlled trials, large cohort studies, and meta-analyses, the authors demonstrate that opposing arguments regarding high complication rates, psychological trauma, reduced sexual function or pleasure, and alleged foreskin functions are generally rooted in low-quality evidence or ideological opinion. In contrast, rigorous medical evidence reveals minimal adverse events, no significant impact on sexual satisfaction, and substantial lifetime risk reductions for urinary tract infections, human immunodeficiency virus (HIV), human papillomavirus (HPV), and genital cancers in both men and female sexual partners.\n\nFurthermore, the review assesses the ethical, legal, and economic dimensions of infant circumcision versus delaying the procedure until adulthood. The authors find that risk-benefit analyses favor early infant circumcision over adult circumcision due to fewer surgical complications, rapid healing, greater cumulative health protection, and cost savings for public health systems. They conclude that public health policies discouraging circumcision are contrary to established scientific consensus and that parent-permitted infant circumcision is fully ethical, legal, and beneficial to long-term well-being.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J Morris", "Stephen Moreton", "John N Krieger"], "organizations": ["University of Sydney", "CircFacts", "University of Washington School of Medicine", "American Academy of Pediatrics", "Centers for Disease Control and Prevention", "World Health Organization", "UNAIDS"], "themes": ["Male Circumcision", "Systematic Review and Evidence-Based Medicine", "Public Health and Preventative Healthcare", "Sexually Transmitted Infections and HIV Prevention", "Medical Ethics and Pediatric Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7bbc2ff976ec0dff7dac83724fbe9be10a668c3a41662d769b6c7c0271cb74e5', 'Morris-Schreiber 2010_RACP IMJ 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7bbc2ff976ec0dff7dac83724fbe9be10a668c3a41662d769b6c7c0271cb74e5.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This document features articles published in the Internal Medicine Journal in 2012, primarily focusing on a critical viewpoint piece by B. J. Morris and colleagues evaluating the Royal Australasian College of Physicians'' (RACP) 2010 policy statement on infant male circumcision. The authors argue that the RACP statement lacks scientific rigor, selectively cites poor-quality research, and downplays substantial evidence demonstrating circumcision''s efficacy in protecting against urinary tract infections, penile cancer, and sexually transmitted infections such as HIV and HPV, as well as cervical cancer in female partners. They advocate for an updated, evidence-based policy, the removal of public hospital bans, and Medicare coverage for the procedure.\n\nThe text also includes an excerpt of a brief communication surveying Australian resident doctors at a Victorian tertiary health service. The survey highlights that while junior doctors feel generally comfortable around dying patients, an overwhelming majority identify a critical need for postgraduate education and practical communication training in palliative medicine.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Alex D. Wodak", "Adrian Mindel", "David A. Cooper", "Jennifer Weil"], "organizations": ["Royal Australasian College of Physicians", "University of Sydney", "St Vincent''s Hospital", "Centers for Disease Control and Prevention", "Circumcision Foundation of Australia"], "themes": ["Infant Male Circumcision", "Public Health Policy", "Sexually Transmitted Infections", "Preventative Medicine", "Palliative Care Education"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7511cc6e47f46cce49cee7b7c7fd50263c9d98913eb59145876e4f86d42fa537', 'Morris-Wamai Biological_basis Circ HIV  JSTD-AIDS 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7511cc6e47f46cce49cee7b7c7fd50263c9d98913eb59145876e4f86d42fa537.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This review synthesizes clinical and biological research explaining why uncircumcised men face a significantly higher risk of acquiring HIV and how male circumcision confers a protective effect of 60% to 75%. The authors explain that the inner foreskin is a mucosal epithelium that lacks thick protective keratin and contains a high density of primary HIV target cells, including CD4+ T-cells, macrophages, and Langerhans cells whose dendrites extend near the surface. During sexual exposure, HIV forms viral synapses with epithelial cells, where Langerhans cells capture the virus and rapidly migrate to transfer it to T-cells, facilitating systemic dissemination.\n\nThe review further identifies compounding risk factors, such as physical trauma or micro-tearing of the prepuce during intercourse, a larger foreskin surface area, and the preputial space acting as a warm, moist reservoir for infectious secretions. Additionally, inflammation caused by smegma, balanitis, an anaerobic penile microbiome, and ulcerative co-infections (especially HSV-2) significantly elevates susceptibility. The authors conclude that removing the foreskin eliminates the primary biological vulnerability to HIV acquisition in men.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["B J Morris", "R G Wamai"], "organizations": ["University of Sydney", "Bosch Institute", "Northeastern University"], "themes": ["HIV Transmission Mechanisms", "Male Circumcision", "Epidemiology of STIs", "Immunology and Cellular Pathology", "Foreskin Keratinization and Anatomy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('019236f534be6992064b27bee368635a231443d4fdf42237e3552ee8338a9cf3', 'Morris-Wamai Criticisms African Trials JLM 2012.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/019236f534be6992064b27bee368635a231443d4fdf42237e3552ee8338a9cf3.pdf', 'medical_journal', 'ingested', '{"date": "2012", "description": "This academic article provides a comprehensive rebuttal to criticisms raised by Gregory Boyle and George Hill regarding randomized controlled trials (RCTs) evaluating voluntary medical male circumcision (VMMC) for HIV prevention in sub-Saharan Africa. The authors argue that Boyle and Hill rely on outdated research, flawed statistical interpretations, and selective citation of outlier studies to contest well-established public health findings. By contrasting their claims with evidence from multiple RCTs, long-term follow-up studies, and meta-analyses, the authors demonstrate that male circumcision provides significant, durable protection against heterosexual HIV transmission in men (ranging from 60% to over 70% long-term efficacy), with indirect preventative benefits for women.\n\nFurthermore, the paper refutes allegations concerning methodological flaws, lack of clinical equipoise, inadequate ethical review, and participant coercion in African trials. The authors assert that the trials strictly complied with international ethical standards and biological plausibility, underscoring that public health guidelines and large-scale VMMC rollouts led by organizations such as WHO and UNAIDS are firmly evidence-based, cost-effective, and crucial for averting millions of HIV infections.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Richard G Wamai", "Brian J Morris", "Jake H Waskett", "Edward C Green", "Joya Banerjee", "Robert C Bailey", "Jeffrey D Klausner", "David C Sokal", "Catherine A Hankins", "Gregory J Boyle", "George Hill", "Robert S Van Howe", "Bertran Auvert", "Ronald H Gray"], "organizations": ["World Health Organization", "UNAIDS", "National Institutes of Health", "Cochrane Collaboration", "Doctors Opposing Circumcision", "Northeastern University", "University of Sydney", "Johns Hopkins Bloomberg School of Public Health"], "themes": ["Voluntary Medical Male Circumcision (VMMC)", "HIV Prevention and Transmission", "Randomized Controlled Trials", "Epidemiology in Sub-Saharan Africa", "Research Ethics and Informed Consent", "Evidence-Based Public Health Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('c8ba131726e665832baf1ad024466e93a4a997e8c02f60174d35cc57208bb1bc', 'Morris-Wamai Expose_of_fallacious_claims JPHA 2011.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/c8ba131726e665832baf1ad024466e93a4a997e8c02f60174d35cc57208bb1bc.pdf', 'medical_journal', 'ingested', '{"date": "2011", "description": "This article serves as a comprehensive rebuttal to a previous publication by Van Howe and Storms, which claimed that male circumcision increases HIV transmission risks in Africa. The authors systematically dismantle these claims, asserting that they are grounded in flawed statistical methodologies, selective citation, and misinterpretation of existing literature. Emphasizing robust data from three major randomized controlled trials in Kenya, Uganda, and South Africa endorsed by WHO and UNAIDS, the authors demonstrate that male circumcision substantially lowers the risk of heterosexually acquired HIV among men.\n\nFurthermore, the article addresses biological mechanisms, refuting misconceptions regarding foreskin mucosal thickness and Langerhans cell function, while reinforcing evidence that circumcision reduces vulnerability to multiple sexually transmitted infections. The authors also dismiss arguments predicting behavioral risk compensation or clinical failure, arguing that male circumcision acts as an efficacious, cost-effective ''surgical vaccine'' that should be implemented alongside condoms and behavioral interventions within comprehensive public health strategies.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Brian J. Morris", "Jake H. Waskett", "Ronald H. Gray", "Daniel T. Halperin", "Richard Wamai", "Bertran Auvert", "Jeffrey D. Klausner", "Robert S. Van Howe", "Michelle R. Storms"], "organizations": ["World Health Organization", "UNAIDS", "Cochrane Collaboration", "University of Sydney", "Johns Hopkins Bloomberg School of Public Health", "Harvard School of Public Health", "Northeastern University", "INSERM", "University of California, San Francisco"], "themes": ["Male Circumcision", "HIV/AIDS Prevention", "Epidemiology and Biostatistics", "Evidence-Based Medicine", "Public Health Policy in Sub-Saharan Africa"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('0666242d5a28e421c7748b8ea2edc0515fef830c09690f4b9cb9e5adbd4b283b', 'Circ Rape Times Register (1804).jpg', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/0666242d5a28e421c7748b8ea2edc0515fef830c09690f4b9cb9e5adbd4b283b.pdf', 'medical_journal', 'ingested', '{"date": null, "description": "This correspondence section from The Times and Register contains medical discussions and announcements. In the primary letter, Dr. E. Chenery responds to an article in the Boston Medical and Surgical Journal regarding circumcision as an alleged preventative measure for rape targeted at Black men; Chenery argues against racially motivated medical interventions, notes the actual hygienic benefits of circumcision, and suggests legal castration across racial lines as a preferable substitute for lynch law. A second communication from the Medical Society of the State of Pennsylvania details the appointment and agenda of a new Committee on Scientific Business, requesting member papers and outlining plans for a symposium on medical and surgical tuberculosis at their upcoming Gettysburg meeting.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["E. Chenery", "Charles W. Dulles", "E. E. Montgomery", "Albert DeHaven"], "organizations": ["Medical Society of the State of Pennsylvania", "Boston Medical and Surgical Journal"], "themes": ["Circumcision", "Racial Bias and Medicine", "Lynching and Criminal Punishment", "Medical Association Affairs", "Tuberculosis", "Public Health"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('16bb69b7e42251a1208fa7b22d0cc5a39d2d8fe057e31d60be973cab2d484583', 'MaGuire - Sexual Crimes Negroes Kansas Med J (1893).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/16bb69b7e42251a1208fa7b22d0cc5a39d2d8fe057e31d60be973cab2d484583.pdf', 'medical_journal', 'ingested', '{"date": "1893", "description": "This document is an excerpt from an 1893 editorial in the Kansas Medical Journal titled ''Sexual Crimes Among the Southern Negroes Scientifically Considered.'' It references an open letter from Dr. Hunter MaGuire of Richmond, Virginia, to Dr. G. Frank Lydston of Chicago, requesting a medical and scientific explanation for what MaGuire alleges is an increasing rate of sexual assaults committed by Black men against white women in the post-Civil War South.\n\nIn the excerpt, MaGuire frames these accusations through the lens of nineteenth-century scientific racism and acknowledges the swift, extrajudicial killings (lynching) carried out by white communities under an ''unwritten law,'' portraying this violent retribution as an immutable community standard.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hunter MaGuire", "G. Frank Lydston"], "organizations": ["Kansas Medical Journal"], "themes": ["Scientific Racism", "Lynching and Racial Violence", "Post-Reconstruction South", "Medicalization of Criminality"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('8f82be414a6581297327dce53202fbdcf838f1c023a2cf685ff5d03402863020', 'negro rape.jpg', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/8f82be414a6581297327dce53202fbdcf838f1c023a2cf685ff5d03402863020.pdf', 'medical_journal', 'ingested', '{"date": "1894", "description": "This excerpt from an 1894 issue of The National Popular Review presents a historical example of 19th-century racial discourse and pseudoscientific claims. The text reflects contemporary prejudices and extreme proposals framed as medical or observational remedies directed at Black populations.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": [], "organizations": ["The National Popular Review"], "themes": ["Scientific Racism", "19th-Century Racial Discourse", "History of Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7edf57ee070fd11815d25b91361c9f419ebf4305114b6ad7d4b60309527ed007', 'Vandavel Circ Enforced by Law TexasMedJ (1889).pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7edf57ee070fd11815d25b91361c9f419ebf4305114b6ad7d4b60309527ed007.pdf', 'medical_journal', 'ingested', '{"date": "1889-07", "description": "This excerpt from Daniel''s Texas Medical Journal introduces a paper titled ''Circumcision Enforced by Law'' authored by Dr. J. M. Vandavel of Waco. Originally read before the Lone Star Medical Society in Houston on June 25, 1889, the article discusses governmental regulation and begins laying the groundwork for a medical argument advocating for legally mandated circumcision.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["J. M. Vandavel"], "organizations": ["Lone Star Medical Society"], "themes": ["Circumcision", "Public Health Legislation", "Government Regulation", "19th Century Medicine"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('1523201177f6668ad18ebd3209d8ae4d4a8b55166f30ee47a1521dd5d6c4f9ac', 'Bustos Regret PRG 2021.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/1523201177f6668ad18ebd3209d8ae4d4a8b55166f30ee47a1521dd5d6c4f9ac.pdf', 'medical_journal', 'ingested', '{"date": "2021-03-19", "description": "This systematic review and meta-analysis evaluated the prevalence of regret among transgender and gender non-binary individuals who underwent gender-affirmation surgery (GAS). Analyzing 27 studies pooling 7,928 patients across 14 countries, the researchers found an overall pooled prevalence of regret of only 1% (95% CI <1%\u20132%), with transmasculine surgeries exhibiting a regret rate under 1% and transfeminine surgeries at 1%.\n\nThe document highlights that the vast majority of patients who experience regret do so primarily because of psychosocial difficulties\u2014such as unsupportive family environments and challenges with social acceptance\u2014or secondary issues like poor surgical, functional, or aesthetic outcomes. The authors conclude that these findings substantiate the efficacy and accuracy of modern patient selection criteria and clinical guidelines, though they emphasize the need for standardized and validated questionnaires to assess regret more objectively.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Valeria P. Bustos", "Samyd S. Bustos", "Andres Mascaro", "Gabriel Del Corral", "Antonio J. Forte", "Pedro Ciudad", "Esther A. Kim", "Howard N. Langstein", "Oscar J. Manrique"], "organizations": ["American Society of Plastic Surgeons", "Harvard Medical School", "Beth Israel Deaconess Medical Center", "University of Pittsburgh", "Cleveland Clinic", "MedStar Georgetown University Hospital", "Mayo Clinic", "University of Rochester Medical Center", "University of California, San Francisco", "Wolters Kluwer Health, Inc.", "World Professional Association for Transgender Health"], "themes": ["Gender-Affirmation Surgery", "Postoperative Regret and Detransition", "Transgender Health Care", "Systematic Review and Meta-Analysis", "Patient Satisfaction and Outcomes"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('19d78c4878477c6480f3456bc779271ab14e470e603940cf109e916ea89bb752', 'Dai Prevalence GenderAffirm JAMA 2024.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/19d78c4878477c6480f3456bc779271ab14e470e603940cf109e916ea89bb752.pdf', 'medical_journal', 'ingested', '{"date": "2024-06-27", "description": "This cross-sectional study analyzes 2019 US insurance claims data to evaluate the prevalence of gender-affirming surgical procedures among transgender and gender diverse (TGD) minors and adults. The researchers found that gender-affirming surgeries were extremely rare among TGD minors: zero procedures were performed on children aged 12 years or younger, 0.1 per 100,000 in minors aged 13 to 14, and 2.1 per 100,000 in minors aged 15 to 17, with nearly all minor procedures being chest-related.\n\nAdditionally, the study examined breast reduction procedures across populations, noting that 97% of breast reductions in minors and 80% in adults were performed on cisgender males rather than TGD individuals. The authors conclude that prevailing public and legislative concerns regarding widespread gender-affirming surgeries among TGD youth are unwarranted, likely reflecting clinical adherence to stringent established standards of care.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Dannie Dai", "Brittany M. Charlton", "Elizabeth R. Boskey", "Landon D. Hughes", "Jaclyn M.W. Hughto", "E. John Orav", "Jose F. Figueroa"], "organizations": ["Harvard T.H. Chan School of Public Health", "Harvard Medical School", "Harvard Pilgrim Health Care Institute", "Boston Children''s Hospital", "Brown School of Public Health", "Inovalon Insights", "National Institutes of Health"], "themes": ["Gender-Affirming Healthcare", "Transgender and Gender Diverse Youth", "Pediatric Surgical Trends", "Healthcare Policy and Legislation", "Insurance Claims Analysis"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fb70191f00a7d1b0e70cc28288cd6cb924a4fbdb11fb42b288b01cea84dc688a', 'Hughes Gender-affirming care rare HarvGazt 2025.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fb70191f00a7d1b0e70cc28288cd6cb924a4fbdb11fb42b288b01cea84dc688a.pdf', 'medical_journal', 'ingested', '{"date": "2025-01-06", "description": "This study published in JAMA Pediatrics investigates the prevalence and trends of gender-affirming medications among transgender adolescents in the United States between 2018 and 2022. It provides empirical data on medication utilization patterns within pediatric and adolescent healthcare settings during this multi-year period.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Landon D. Hughes", "Brittany M. Charlton", "Isa Berzansky", "Jae D. Corman"], "organizations": ["JAMA Pediatrics"], "themes": ["Transgender Health", "Gender-Affirming Care", "Adolescent Medicine", "Pharmacoepidemiology", "Pediatrics"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('ac220d595f773efaf4533d3d7bac5aeba3bf223d99277caa0ddeeeb0c92baefa', 'Hughes Incidence chart 2025.png', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/ac220d595f773efaf4533d3d7bac5aeba3bf223d99277caa0ddeeeb0c92baefa.pdf', 'medical_journal', 'ingested', '{"date": "2025", "description": "This document presents epidemiological findings on the receipt of gender-affirming medications among enrolled adolescents between 2018 and 2022. The data shows that overall utilization remains very low, with fewer than 7 in 1,000 adolescents receiving puberty blockers or gender-affirming hormone therapy (GAHT), and no adolescents under 12 years of age receiving hormone prescriptions. While medication receipt peaks at age 17, rates across both puberty blockers and hormone therapy remain higher among individuals assigned female at birth (AFAB) compared to those assigned male at birth (AMAB).", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Hughes"], "organizations": [], "themes": ["Gender-Affirming Care", "Adolescent Healthcare", "Puberty Blockers", "Hormone Therapy", "Pediatric Endocrinology"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('7d129e52e59c24671157ffa2f521759684cc676e161d79b543db34cbd5ba912a', 'Serano Detransition Medium 2016.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/7d129e52e59c24671157ffa2f521759684cc676e161d79b543db34cbd5ba912a.pdf', 'other', 'ingested', '{"date": "2025-03-04", "description": "This document consists of the printout headers and metadata for Julia Serano''s online essay titled ''Detransition, Desistance, and Disinformation: A Guide for Understanding...''. The work examines and addresses common misconceptions, research debates, and media narratives surrounding transgender youth, specifically analyzing how concepts of detransition and desistance are framed and utilized in public discourse.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Julia Serano"], "organizations": ["Medium"], "themes": ["Detransition", "Desistance", "Disinformation", "Transgender Youth", "Gender Identity"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('fa4eab527dd7f36a44b2aeb76819031286221fa940648f4be89b4f3b08468e4f', 'Williams Instit-UCLA Trans-Pop-Update-Jun-2022.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/fa4eab527dd7f36a44b2aeb76819031286221fa940648f4be89b4f3b08468e4f.pdf', 'other', 'ingested', '{"date": "2022", "description": "This report by the Williams Institute provides updated demographic estimates of transgender individuals in the United States using pooled data from the CDC''s Behavioral Risk Factor Surveillance System (BRFSS, 2017\u20132020) and Youth Risk Behavior Survey (YRBS, 2017 and 2019). The study estimates that over 1.6 million people ages 13 and older in the U.S. identify as transgender, comprising approximately 0.6% of this population. Among adults, 0.5% (roughly 1.3 million) identify as transgender, while youth ages 13 to 17 identify at a significantly higher rate of 1.4% (about 300,000), representing 18% of the transgender population. Among adults, 38.5% identify as transgender women, 35.9% as transgender men, and 25.6% as gender nonconforming.\n\nThe findings indicate that transgender populations are younger on average than the general U.S. population and mirror earlier research showing higher rates of transgender identification among Latinx, American Indian/Alaska Native, and multiracial populations compared to White populations. Geographic distribution varies widely, with the youth transgender population ranging from 0.6% in Wyoming to 3.0% in New York. To improve accuracy and eliminate the need for complex statistical modeling to compensate for missing state data, the authors recommend that federal statistical agencies systematically include gender identity measures in all core federal surveys.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Other", "key_people": ["Jody L. Herman", "Andrew R. Flores", "Kathryn K. O\u2019Neill", "Bianca Wilson", "Kerith Conron", "Christy Mallory", "Brad Sears", "Gary J. Gates"], "organizations": ["The Williams Institute", "UCLA School of Law", "Centers for Disease Control and Prevention", "U.S. Census Bureau", "Bureau of Justice Statistics", "American University"], "themes": ["Transgender Demographics", "Population Estimates", "Youth Gender Identity", "Survey Methodology", "Multilevel Regression and Poststratification", "Racial and Ethnic Disparities", "Federal Data Collection Policy"]}');
INSERT OR REPLACE INTO archive_documents (id, title, source_collection, url, type, status, metadata_json) VALUES ('d2fd084cf2082ab5920da6a500eda289389c1a968f8f29632dabe29b7fd948f5', 'Wright_Number Trans Surgery JAMA 2023.pdf', 'wetransfer_article-downloads-folder_2026-09-15_2250', '/api/assets/documents/d2fd084cf2082ab5920da6a500eda289389c1a968f8f29632dabe29b7fd948f5.pdf', 'medical_journal', 'ingested', '{"date": "2023-08-23", "description": "This cohort study evaluates national temporal trends in inpatient and outpatient gender-affirming surgery (GAS) across the United States from 2016 to 2020 using data from the Nationwide Ambulatory Surgery Sample and the National Inpatient Sample. Among 48,019 patients identified as having undergone GAS, the absolute number of annual procedures nearly tripled from 4,552 in 2016 to a peak of 13,011 in 2019, followed by a minor pandemic-related contraction to 12,818 in 2020. The majority of patients were between the ages of 19 and 30 years (52.3%), while minors aged 12 to 18 accounted for 7.7% of the cohort.\n\nBreast and chest surgeries constituted the most prevalent procedural class overall (56.6%) and made up the vast majority of interventions performed in younger demographics. Conversely, genital reconstructive procedures (35.1% overall) rose significantly in proportion with increasing patient age. The authors conclude that the substantial expansion of GAS necessitates an increased workforce of trained clinicians to manage care, highlighting that burgeoning state-level legal and policy restrictions pose serious ongoing challenges to equitable healthcare delivery.", "source": "wetransfer_article-downloads-folder_2026-09-15_2250", "document_type": "Medical Journal", "key_people": ["Jason D. Wright", "Ling Chen", "Yukio Suzuki", "Koji Matsuo", "Dawn L. Hershman"], "organizations": ["JAMA Network Open", "Columbia University College of Physicians and Surgeons", "University of Southern California", "Healthcare Cost and Utilization Project", "Agency for Healthcare Research and Quality"], "themes": ["Gender-Affirming Surgery", "Transgender Health Care", "Surgical Epidemiology", "Health Insurance and Policy", "Adolescent Healthcare Access"]}');